#[derive(Clone, Copy, Debug)]
pub struct VectorSearchSource<'a> {
    pub property: PropertyId,
    pub exact: &'a VectorIndex,
    pub approximate: Option<&'a IvfPqIndex>,
    pub profile_hash: [u8; 32],
}

/// Actual exact-reranked vector evidence emitted by one physical SEARCH execution.
#[derive(Clone, Debug, PartialEq, Serialize, Deserialize)]
pub struct VectorSearchTrace {
    pub index_name: String,
    pub profile_hash: [u8; 32],
    pub access: ResidentVectorAccess,
    pub candidate_budget: u32,
    pub build_generation: [u8; 32],
    pub bookmark: Bookmark,
    pub hits: Vec<crate::graph::VectorHit>,
}

/// Execution inputs resolved by the protocol/transaction layer.
pub struct ExecutionContext<'a> {
    pub project_id: ProjectId,
    pub graph: &'a GraphStore,
    /// Small transaction-local name dictionary including prior statement declarations.
    pub binding_catalog: &'a crate::graph::NameCatalog,
    /// Prior uncommitted statements, applied as a sparse read-own-writes overlay.
    pub prior_graph_mutations: &'a [GraphMutation],
    pub temporal: Option<&'a TemporalStore>,
    /// Prior uncommitted temporal samples in the same explicit transaction.
    pub prior_temporal_mutations: &'a [PreparedTemporalMutation],
    pub vector_indexes: BTreeMap<String, VectorSearchSource<'a>>,
    /// ONLINE scalar indexes from the same immutable project snapshot.
    pub scalar_indexes: Option<&'a IndexCatalog>,
    pub text_embedding: Option<&'a dyn TextEmbedding>,
    pub parameters: BTreeMap<String, ResultValue>,
    pub bookmark: Bookmark,
    pub mutation_revision: u64,
    pub resolved_time_nanos: i64,
    pub next_node_id: u64,
    pub next_edge_id: u64,
    pub predicate_versions: BTreeMap<DependencyStamp, u64>,
    pub capabilities: BindCapabilities,
    pub max_result_rows: usize,
    pub max_batch_rows: usize,
    /// Rebuildable statistics generation cached by the owning project snapshot when available.
    pub optimizer_statistics: Option<&'a StatisticsSnapshot>,
    /// Complete resident execution image for this project, when its bookmark matches exactly.
    pub backend: Option<&'a dyn ExecutionBackend>,
    pub cancellation: CancellationToken,
    pub deadline: Option<Instant>,
    /// Engine-owned value resolved only from the query's parsed `AT TIME` preamble.
    pub resolved_query_at_time_nanos: Option<i64>,
}

/// A normal query execution context scoped to one immutable ephemeral procedure catalog.
/// Keeping this as a short-lived wrapper avoids process-global registration and prevents fixture
/// procedures from leaking into unrelated queries or projects.
pub struct ProcedureExecutionContext<'scope, 'graph> {
    context: &'scope mut ExecutionContext<'graph>,
    procedures: &'scope ProcedureCatalog,
}

impl<'graph> ExecutionContext<'graph> {
    pub fn with_procedures<'scope>(
        &'scope mut self,
        procedures: &'scope ProcedureCatalog,
    ) -> ProcedureExecutionContext<'scope, 'graph> {
        ProcedureExecutionContext {
            context: self,
            procedures,
        }
    }
}

#[derive(Clone, Copy, Debug, PartialEq, Eq, PartialOrd, Ord, Serialize, Deserialize)]
pub enum EntityDependency {
    Node(NodeId),
    Relationship(EdgeId),
}

#[derive(Clone, Debug, Default, Serialize, Deserialize)]
pub struct TransactionDependencies {
    pub entities: BTreeMap<EntityDependency, u64>,
    pub predicates: BTreeMap<DependencyStamp, u64>,
    pub write_targets: BTreeSet<EntityDependency>,
}

#[derive(Clone, Debug)]
pub struct PreparedTemporalMutation {
    pub entity_kind: EntityKind,
    /// Stable label ID for a node or relationship-type ID for a relationship.
    pub target: u64,
    pub sample: TemporalSample,
    /// The event timestamp is provisional until the sequencer resolves commit time.
    pub uses_commit_time: bool,
}

#[derive(Clone, Debug)]
pub struct ExecutionOutput {
    pub result: QueryResult,
    pub graph_mutations: Vec<GraphMutation>,
    pub temporal_mutations: Vec<PreparedTemporalMutation>,
    pub dependencies: TransactionDependencies,
    pub administrative: Option<Statement>,
    /// Bounded engine-owned physical evidence; never encoded into semantic model content.
    pub vector_searches: Vec<VectorSearchTrace>,
    /// Ephemeral internal diagnostic; a legal execution can restart at most once.
    pub runtime_replans: u8,
}

/// Stateless query pipeline. Transaction ownership and canonical publication happen above it.
#[derive(Clone, Copy, Debug, Default)]
pub struct QueryEngine;

impl QueryEngine {
    pub fn execute(
        &self,
        source: &str,
        context: &mut ExecutionContext<'_>,
    ) -> Result<ExecutionOutput> {
        check_execution(context)?;
        let (plan, force_host_adaptive) = prepared_plan(source, context, None)?;
        execute_plan(plan, context, None, None, force_host_adaptive)
    }

    /// Executes with procedures visible only for this scoped execution.
    pub fn execute_with_procedures(
        &self,
        source: &str,
        scoped: ProcedureExecutionContext<'_, '_>,
    ) -> Result<ExecutionOutput> {
        let ProcedureExecutionContext {
            context,
            procedures,
        } = scoped;
        check_execution(context)?;
        let (plan, force_host_adaptive) = prepared_plan(source, context, Some(procedures))?;
        execute_plan(plan, context, Some(procedures), None, force_host_adaptive)
    }

    /// Executes a query while synchronously yielding schema and bounded columnar batches.
    /// The returned result contains only terminal metadata and never duplicates yielded batches.
    pub fn execute_streaming(
        &self,
        source: &str,
        context: &mut ExecutionContext<'_>,
        emit: &mut dyn FnMut(ExecutionStreamItem) -> Result<()>,
    ) -> Result<ExecutionOutput> {
        check_execution(context)?;
        let (plan, force_host_adaptive) = prepared_plan(source, context, None)?;
        if !plan.read_only {
            return Err(Error::new(
                ErrorCode::QueryType,
                "stream-before-commit execution is restricted to read-only queries",
            ));
        }
        execute_plan(plan, context, None, Some(emit), force_host_adaptive)
    }

    #[cfg(test)]
    pub fn execute_unoptimized(
        &self,
        source: &str,
        context: &mut ExecutionContext<'_>,
    ) -> Result<ExecutionOutput> {
        check_execution(context)?;
        let query = parse(source)?;
        let bound = bind_with_parameters(
            query,
            context.binding_catalog,
            context.capabilities,
            &context.parameters,
        )?;
        execute_plan(plan(bound)?, context, None, None, false)
    }
}

fn prepared_plan(
    source: &str,
    context: &ExecutionContext<'_>,
    procedures: Option<&ProcedureCatalog>,
) -> Result<(PhysicalPlan, bool)> {
    let backend = context
        .backend
        .map_or(crate::execution::BackendKind::Cpu, ExecutionBackend::kind);
    let scratch_budget_bytes = context
        .backend
        .map_or(usize::MAX, ExecutionBackend::available_query_scratch_bytes);
    let index_generation = context
        .scalar_indexes
        .map_or([0_u8; 32], IndexCatalog::optimizer_generation);
    let statistics_revision = context.optimizer_statistics.map_or_else(
        || context.graph.revision(),
        |statistics| statistics.graph_revision,
    );
    let runtime_checkpoint_eligible =
        context.prior_graph_mutations.is_empty() && context.prior_temporal_mutations.is_empty();
    check_execution(context)?;
    let early_key = procedures
        .is_none()
        .then(|| {
            EarlyPlanCacheKey::new(
                context.project_id,
                source,
                context.binding_catalog,
                index_generation,
                &context.parameters,
                statistics_revision,
                backend,
                super::optimizer::backend_capability_bits(backend),
                context.capabilities,
                runtime_checkpoint_eligible,
                scratch_budget_bytes,
                context.max_result_rows,
            )
        })
        .transpose()?;
    if let Some(early_key) = early_key.as_ref() {
        if let Some(plan) = plan_cache::get_early(early_key, &context.parameters) {
            return Ok(plan);
        }
    }
    let query = parse(source)?;
    check_execution(context)?;
    let bound = match procedures {
        Some(procedures) => bind_with_procedures(
            query,
            context.binding_catalog,
            context.capabilities,
            procedures,
            &context.parameters,
        )?,
        None => bind_with_parameters(
            query,
            context.binding_catalog,
            context.capabilities,
            &context.parameters,
        )?,
    };
    let physical = plan(bound)?;
    let collected;
    let statistics = if let Some(statistics) = context.optimizer_statistics {
        statistics
    } else {
        collected = StatisticsSnapshot::collect(context.graph);
        &collected
    };
    // Broad query classes stay on the admitted resident backend. Only a Metal-optimized plan can
    // prove the selective/bounded host shapes below, after which it is re-planned once with CPU
    // costs and both the plan and route bit are cached.
    let optimizer_backend = backend;
    // An explicitly admitted CPU backend has a real resident scratch limit too. Preserve that
    // admission contract here; only the detached selective host replan below receives unbounded
    // backend scratch because it does not execute against the resident backend at all.
    let optimizer_scratch_budget_bytes = scratch_budget_bytes;
    let mut force_host_adaptive = false;
    let host_replan_candidate = (backend == crate::execution::BackendKind::Metal
        && !context.capabilities.require_native_execution
        && context.prior_graph_mutations.is_empty()
        && context.prior_temporal_mutations.is_empty()
        && optimizer_backend != crate::execution::BackendKind::Cpu)
        .then(|| physical.clone());
    let temporal_mode = plan_temporal_mode(&physical);
    let key = procedures
        .is_none()
        .then(|| {
            PlanCacheKey::new(
                context.project_id,
                source,
                context.binding_catalog,
                index_generation,
                &context.parameters,
                statistics.graph_revision,
                backend,
                super::optimizer::backend_capability_bits(backend),
                context.capabilities,
                physical.read_layers,
                temporal_mode,
                runtime_checkpoint_eligible,
                scratch_budget_bytes,
                context.max_result_rows,
            )
        })
        .transpose()?;
    if let Some(key) = &key
        && let Some(plan) = plan_cache::get(key, &context.parameters)
    {
        return Ok(plan);
    }
    let (mut plan, mut profile) = optimize(
        physical,
        OptimizerInput {
            statistics,
            catalog: context.binding_catalog,
            indexes: context.scalar_indexes,
            parameters: &context.parameters,
            backend: optimizer_backend,
            scratch_budget_bytes: optimizer_scratch_budget_bytes,
            max_result_rows: context.max_result_rows,
            runtime_feedback: None,
            allow_runtime_checkpoint: runtime_checkpoint_eligible,
        },
    );
    if let Some(cpu_physical) = host_replan_candidate
        && (plan_is_host_fast_read(&plan)
            || plan_is_host_indexed_seek_read(&plan)
            || plan_bare_scan_row_cap(&plan).is_some())
    {
        // The Metal optimizer has now proved this is a bounded/selective host winner. Re-plan from
        // the unoptimized IR with CPU costs instead of executing a Metal-costed access path on the
        // host. This happens only on a cold cache miss; the plan and route bit are cached together.
        (plan, profile) = optimize(
            cpu_physical,
            OptimizerInput {
                statistics,
                catalog: context.binding_catalog,
                indexes: context.scalar_indexes,
                parameters: &context.parameters,
                backend: crate::execution::BackendKind::Cpu,
                scratch_budget_bytes: usize::MAX,
                max_result_rows: context.max_result_rows,
                runtime_feedback: None,
                allow_runtime_checkpoint: runtime_checkpoint_eligible,
            },
        );
        force_host_adaptive = true;
    }
    if context.backend.is_some() && !profile.scratch_feasible {
        return Err(Error::retryable(
            ErrorCode::GpuAdmissionFailure,
            format!(
                "query plan requires an estimated {} scratch bytes but only {} are available",
                profile.estimated_peak_scratch_bytes, scratch_budget_bytes
            ),
            Some(10),
        ));
    }
    if let Some(key) = key {
        let early_key = early_key
            .ok_or_else(|| Error::internal("cacheable physical plan has no exact-source key"))?;
        plan_cache::insert(
            early_key,
            key,
            plan.clone(),
            force_host_adaptive,
            profile.specialized_parameters.clone(),
        );
    }
    Ok((plan, force_host_adaptive))
}

fn plan_temporal_mode(plan: &PhysicalPlan) -> u8 {
    let mut mode = u8::from(plan.at_time.is_some());
    if plan
        .operators
        .iter()
        .chain(
            plan.unions
                .iter()
                .flat_map(|(_, operators)| operators.iter()),
        )
        .any(|operator| {
            matches!(
                operator,
                PhysicalOperator::TemporalHistory(_)
                    | PhysicalOperator::TemporalWindow(_)
                    | PhysicalOperator::TemporalHistoryWindow { .. }
            )
        })
    {
        mode |= 1 << 1;
    }
    mode
}

#[derive(Clone, Debug, PartialEq, Serialize)]
enum BindingValue {
    Node(u32),
    Relationship(u32),
    Path {
        nodes: Vec<u32>,
        relationships: Vec<u32>,
    },
    /// Statement-owned containers retain entity bindings without exposing mutation authority in
    /// the public `ResultValue` representation. Values originating outside this execution are
    /// recursively wrapped with untrusted leaves instead.
    List(Vec<BindingValue>),
    Map(BTreeMap<String, BindingValue>),
    Value(ResultValue),
    Null,
}

/// Compact deterministic binding row. Typical graph pipelines stay inline and avoid one tree
/// allocation plus one node allocation per bound symbol.
#[derive(Clone, Debug, Default, Serialize)]
struct Row {
    values: SmallVec<[(String, BindingValue); 8]>,
    /// Dense relationship identities already selected by patterns in the current MATCH clause.
    /// This is execution metadata, not a Cypher binding: projections, equality, and result
    /// serialization must never expose it. A different `MatchGroupId` clears the set.
    #[serde(skip)]
    match_group: Option<MatchGroupId>,
    #[serde(skip)]
    match_relationships: BTreeSet<u32>,
}

impl PartialEq for Row {
    fn eq(&self, other: &Self) -> bool {
        self.values == other.values
    }
}

impl Row {
    fn new() -> Self {
        Self::default()
    }

    fn get(&self, name: &str) -> Option<&BindingValue> {
        self.values
            .binary_search_by(|(candidate, _)| candidate.as_str().cmp(name))
            .ok()
            .and_then(|position| self.values.get(position).map(|(_, value)| value))
    }

    fn contains_key(&self, name: &str) -> bool {
        self.get(name).is_some()
    }

    fn insert(&mut self, name: String, value: BindingValue) -> Option<BindingValue> {
        match self
            .values
            .binary_search_by(|(candidate, _)| candidate.as_str().cmp(name.as_str()))
        {
            Ok(position) => Some(std::mem::replace(&mut self.values[position].1, value)),
            Err(position) => {
                self.values.insert(position, (name, value));
                None
            }
        }
    }

    fn insert_if_absent(&mut self, name: String, value: BindingValue) {
        if let Err(position) = self
            .values
            .binary_search_by(|(candidate, _)| candidate.as_str().cmp(name.as_str()))
        {
            self.values.insert(position, (name, value));
        }
    }

    fn keys(&self) -> impl Iterator<Item = &String> {
        self.values.iter().map(|(name, _)| name)
    }

    fn values(&self) -> impl Iterator<Item = &BindingValue> {
        self.values.iter().map(|(_, value)| value)
    }

    fn enter_match_group(&mut self, match_group: MatchGroupId) {
        if self.match_group != Some(match_group) {
            self.match_group = Some(match_group);
            self.match_relationships.clear();
        }
    }

    fn reset_match_group(&mut self) {
        self.match_group = None;
        self.match_relationships.clear();
    }
}

impl<'a> IntoIterator for &'a Row {
    type Item = &'a (String, BindingValue);
    type IntoIter = std::slice::Iter<'a, (String, BindingValue)>;

    fn into_iter(self) -> Self::IntoIter {
        self.values.iter()
    }
}

impl<const N: usize> From<[(String, BindingValue); N]> for Row {
    fn from(values: [(String, BindingValue); N]) -> Self {
        let mut row = Self::new();
        for (name, value) in values {
            row.insert(name, value);
        }
        row
    }
}

const INTERNAL_WINDOW_EMPTY: &str = "\0window_empty";

fn check_execution(context: &ExecutionContext<'_>) -> Result<()> {
    if context.cancellation.is_cancelled() {
        return Err(Error::new(
            ErrorCode::Cancelled,
            "query execution cancelled",
        ));
    }
    if context
        .deadline
        .is_some_and(|deadline| Instant::now() >= deadline)
    {
        return Err(Error::new(
            ErrorCode::DeadlineExceeded,
            "query execution deadline exceeded",
        ));
    }
    Ok(())
}

fn current_backend<'a>(
    state: &'a ExecutionState<'_>,
    context: &'a ExecutionContext<'_>,
) -> Option<&'a dyn ExecutionBackend> {
    let backend = state.resident_backend.as_deref().or_else(|| {
        state
            .allow_context_backend
            .then_some(context.backend)
            .flatten()
    })?;
    (backend.resident_bookmark(context.project_id) == Some(context.bookmark)
        && backend.resident_graph_revision(context.project_id) == Some(state.graph.revision()))
    .then_some(backend)
}

fn execute_plan(
    plan: PhysicalPlan,
    context: &mut ExecutionContext<'_>,
    procedures: Option<&ProcedureCatalog>,
    stream: Option<&mut dyn FnMut(ExecutionStreamItem) -> Result<()>>,
    force_host_adaptive: bool,
) -> Result<ExecutionOutput> {
    if !force_host_adaptive {
        return execute_plan_with_selected_backend(plan, context, procedures, stream, false);
    }
    // The CPU route is an execution boundary, not a hint. Temporarily hiding the accelerator from
    // the whole executor prevents an opportunistic sort/group/path helper from re-entering Metal
    // mid-plan. Option<&dyn ExecutionBackend> is copied, no query data or graph bytes are cloned,
    // and restoration happens for both success and error results.
    let accelerator = context.backend;
    context.backend = None;
    let result = execute_plan_with_selected_backend(plan, context, procedures, stream, true);
    context.backend = accelerator;
    result
}

fn execute_plan_with_selected_backend(
    mut plan: PhysicalPlan,
    context: &mut ExecutionContext<'_>,
    procedures: Option<&ProcedureCatalog>,
    stream: Option<&mut dyn FnMut(ExecutionStreamItem) -> Result<()>>,
    force_host_adaptive: bool,
) -> Result<ExecutionOutput> {
    let prior_at_time = context.resolved_query_at_time_nanos;
    let graph = transaction_graph_view(context)?;
    let temporal = transaction_temporal_view(context)?;
    context.resolved_query_at_time_nanos = match &plan.at_time {
        Some(expression) => Some(timestamp_nanos(&evaluate_with_temporal(
            expression,
            &Row::new(),
            &graph,
            context,
            Some(&temporal),
            context.bookmark.index,
        )?)?),
        None => None,
    };
    let result = resolve_plan_row_counts(&mut plan, &graph, &temporal, context)
        .and_then(|()| {
            preflight_context_free_runtime_expressions(&mut plan, &graph, &temporal, context)
        })
        .and_then(|()| execute_plan_inner(plan, context, procedures, stream, force_host_adaptive));
    context.resolved_query_at_time_nanos = prior_at_time;
    result
}

fn resolve_plan_row_counts(
    plan: &mut PhysicalPlan,
    graph: &GraphReadView<'_>,
    temporal: &TemporalReadView<'_>,
    context: &ExecutionContext<'_>,
) -> Result<()> {
    for operators in std::iter::once(&mut plan.operators)
        .chain(plan.unions.iter_mut().map(|(_, operators)| operators))
    {
        for operator in operators {
            let expression = match operator {
                PhysicalOperator::Skip(expression) | PhysicalOperator::Limit(expression) => {
                    expression
                }
                _ => continue,
            };
            let value = evaluate_with_temporal(
                expression,
                &Row::new(),
                graph,
                context,
                Some(temporal),
                context.bookmark.index,
            )?;
            let count = evaluate_row_count_value(value)?;
            let count = i64::try_from(count).map_err(|_| {
                Error::new(
                    ErrorCode::QueryType,
                    "SKIP/LIMIT value exceeds the supported row-count range",
                )
            })?;
            *expression = Expression::Literal(ScalarValue::Integer(count));
        }
    }
    Ok(())
}

/// Resolves the small set of runtime values which are deterministic and need no row, entity, or
/// graph binding. This remains an executor preflight so semantic failures keep their runtime
/// phase, but it runs before resident admission so CPU and GPU report the same semantic error.
/// Successful values replace their original expression, ensuring the normal execution path never
/// evaluates the original expression a second time.
fn preflight_context_free_runtime_expressions(
    plan: &mut PhysicalPlan,
    graph: &GraphReadView<'_>,
    temporal: &TemporalReadView<'_>,
    context: &ExecutionContext<'_>,
) -> Result<()> {
    for operators in std::iter::once(&mut plan.operators)
        .chain(plan.unions.iter_mut().map(|(_, operators)| operators))
    {
        for operator in operators {
            match operator {
                PhysicalOperator::MergePattern { pattern, .. } => {
                    preflight_merge_pattern_properties(pattern, graph, temporal, context)?;
                }
                PhysicalOperator::Project { projection, .. } => {
                    for item in &mut projection.items {
                        preflight_percentile_arguments(
                            &mut item.expression,
                            graph,
                            temporal,
                            context,
                        )?;
                    }
                }
                PhysicalOperator::Sort(items) | PhysicalOperator::TopK { items, .. } => {
                    for item in items {
                        preflight_percentile_arguments(
                            &mut item.expression,
                            graph,
                            temporal,
                            context,
                        )?;
                    }
                }
                _ => {}
            }
        }
    }
    Ok(())
}

fn preflight_merge_pattern_properties(
    pattern: &mut Pattern,
    graph: &GraphReadView<'_>,
    temporal: &TemporalReadView<'_>,
    context: &ExecutionContext<'_>,
) -> Result<()> {
    preflight_merge_property_entries(&mut pattern.start.properties, graph, temporal, context)?;
    for step in &mut pattern.steps {
        preflight_merge_property_entries(
            &mut step.relationship.properties,
            graph,
            temporal,
            context,
        )?;
        preflight_merge_property_entries(&mut step.node.properties, graph, temporal, context)?;
    }
    Ok(())
}

fn preflight_merge_property_entries(
    entries: &mut [(String, Expression)],
    graph: &GraphReadView<'_>,
    temporal: &TemporalReadView<'_>,
    context: &ExecutionContext<'_>,
) -> Result<()> {
    for (name, expression) in entries {
        if !preflight_expression_is_context_free(expression, &context.parameters) {
            continue;
        }
        let value = evaluate_with_temporal(
            expression,
            &Row::new(),
            graph,
            context,
            Some(temporal),
            context.bookmark.index,
        )?;
        let value = scalar(value)?;
        if matches!(value, ScalarValue::Null) {
            return Err(merge_null_property_error(name));
        }
        *expression = Expression::Literal(value);
    }
    Ok(())
}

fn preflight_percentile_arguments(
    expression: &mut Expression,
    graph: &GraphReadView<'_>,
    temporal: &TemporalReadView<'_>,
    context: &ExecutionContext<'_>,
) -> Result<()> {
    if expression.existential_subquery_parts().is_some()
        || expression.pattern_predicate_pattern().is_some()
        || expression.pattern_comprehension_parts().is_some()
    {
        return Ok(());
    }

    if let Expression::Function {
        name, arguments, ..
    } = expression
        && matches!(
            name.join(".").to_ascii_lowercase().as_str(),
            "percentilecont" | "percentiledisc"
        )
        && let Some(percentile_expression) = arguments.get_mut(1)
        && preflight_expression_is_context_free(percentile_expression, &context.parameters)
    {
        let preserve_parameter = matches!(percentile_expression, Expression::Parameter(_));
        let value = evaluate_with_temporal(
            percentile_expression,
            &Row::new(),
            graph,
            context,
            Some(temporal),
            context.bookmark.index,
        )?;
        let percentile = numeric(&value)?;
        validate_percentile_argument(percentile)?;
        if !preserve_parameter {
            *percentile_expression = Expression::Literal(scalar(value)?);
        }
    }

    match expression {
        Expression::Property(source, _)
        | Expression::Unary {
            operand: source, ..
        }
        | Expression::IsNull {
            expression: source, ..
        } => preflight_percentile_arguments(source, graph, temporal, context)?,
        Expression::List(values)
        | Expression::Function {
            arguments: values, ..
        } => {
            for value in values {
                preflight_percentile_arguments(value, graph, temporal, context)?;
            }
        }
        Expression::Map(values) => {
            for (_, value) in values {
                preflight_percentile_arguments(value, graph, temporal, context)?;
            }
        }
        Expression::MapProjection { source, items } => {
            preflight_percentile_arguments(source, graph, temporal, context)?;
            for item in items {
                if let MapProjectionItem::Entry(_, value) = item {
                    preflight_percentile_arguments(value, graph, temporal, context)?;
                }
            }
        }
        Expression::Case {
            operand,
            alternatives,
            default,
        } => {
            if let Some(operand) = operand {
                preflight_percentile_arguments(operand, graph, temporal, context)?;
            }
            for alternative in alternatives {
                preflight_percentile_arguments(&mut alternative.when, graph, temporal, context)?;
                preflight_percentile_arguments(&mut alternative.then, graph, temporal, context)?;
            }
            if let Some(default) = default {
                preflight_percentile_arguments(default, graph, temporal, context)?;
            }
        }
        Expression::ListComprehension {
            list,
            predicate,
            projection,
            ..
        } => {
            preflight_percentile_arguments(list, graph, temporal, context)?;
            if let Some(predicate) = predicate {
                preflight_percentile_arguments(predicate, graph, temporal, context)?;
            }
            if let Some(projection) = projection {
                preflight_percentile_arguments(projection, graph, temporal, context)?;
            }
        }
        Expression::Reduce {
            initial,
            list,
            expression,
            ..
        } => {
            preflight_percentile_arguments(initial, graph, temporal, context)?;
            preflight_percentile_arguments(list, graph, temporal, context)?;
            preflight_percentile_arguments(expression, graph, temporal, context)?;
        }
        Expression::ListPredicate {
            list, predicate, ..
        }
        | Expression::Binary {
            left: list,
            right: predicate,
            ..
        }
        | Expression::Index {
            expression: list,
            index: predicate,
        } => {
            preflight_percentile_arguments(list, graph, temporal, context)?;
            preflight_percentile_arguments(predicate, graph, temporal, context)?;
        }
        Expression::Slice {
            expression,
            start,
            end,
        } => {
            preflight_percentile_arguments(expression, graph, temporal, context)?;
            if let Some(start) = start {
                preflight_percentile_arguments(start, graph, temporal, context)?;
            }
            if let Some(end) = end {
                preflight_percentile_arguments(end, graph, temporal, context)?;
            }
        }
        Expression::Literal(_)
        | Expression::Parameter(_)
        | Expression::Variable(_)
        | Expression::ExistentialSubquery(_)
        | Expression::Star => {}
    }
    Ok(())
}

fn preflight_expression_is_context_free(
    expression: &Expression,
    parameters: &BTreeMap<String, ResultValue>,
) -> bool {
    if expression.existential_subquery_parts().is_some()
        || expression.pattern_predicate_pattern().is_some()
        || expression.pattern_comprehension_parts().is_some()
        || expression.entity_label_predicate_parts().is_some()
    {
        return false;
    }
    match expression {
        Expression::Literal(_) => true,
        Expression::Parameter(name) => parameters
            .get(name)
            .is_some_and(preflight_value_is_context_free),
        Expression::Property(source, _)
        | Expression::Unary {
            operand: source, ..
        }
        | Expression::IsNull {
            expression: source, ..
        } => preflight_expression_is_context_free(source, parameters),
        Expression::List(values) => values
            .iter()
            .all(|value| preflight_expression_is_context_free(value, parameters)),
        Expression::Map(values) => values
            .iter()
            .all(|(_, value)| preflight_expression_is_context_free(value, parameters)),
        Expression::MapProjection { source, items } => {
            preflight_expression_is_context_free(source, parameters)
                && items.iter().all(|item| match item {
                    MapProjectionItem::AllProperties | MapProjectionItem::Property(_) => true,
                    MapProjectionItem::Variable(_) => false,
                    MapProjectionItem::Entry(_, value) => {
                        preflight_expression_is_context_free(value, parameters)
                    }
                })
        }
        Expression::Case {
            operand,
            alternatives,
            default,
        } => {
            operand
                .as_deref()
                .is_none_or(|value| preflight_expression_is_context_free(value, parameters))
                && alternatives.iter().all(|alternative| {
                    preflight_expression_is_context_free(&alternative.when, parameters)
                        && preflight_expression_is_context_free(&alternative.then, parameters)
                })
                && default
                    .as_deref()
                    .is_none_or(|value| preflight_expression_is_context_free(value, parameters))
        }
        Expression::Function {
            name, arguments, ..
        } => {
            !(name.len() == 1 && name[0].eq_ignore_ascii_case("rand"))
                && !is_aggregate_function(name)
                && arguments
                    .iter()
                    .all(|argument| preflight_expression_is_context_free(argument, parameters))
        }
        Expression::Binary { left, right, .. }
        | Expression::Index {
            expression: left,
            index: right,
        } => {
            preflight_expression_is_context_free(left, parameters)
                && preflight_expression_is_context_free(right, parameters)
        }
        Expression::Slice {
            expression,
            start,
            end,
        } => {
            preflight_expression_is_context_free(expression, parameters)
                && start
                    .as_deref()
                    .is_none_or(|value| preflight_expression_is_context_free(value, parameters))
                && end
                    .as_deref()
                    .is_none_or(|value| preflight_expression_is_context_free(value, parameters))
        }
        Expression::Variable(_)
        | Expression::ListComprehension { .. }
        | Expression::Reduce { .. }
        | Expression::ListPredicate { .. }
        | Expression::ExistentialSubquery(_)
        | Expression::Star => false,
    }
}

fn preflight_value_is_context_free(value: &ResultValue) -> bool {
    match value {
        ResultValue::Scalar(_) | ResultValue::Vector(_) => true,
        ResultValue::List(values) => values.iter().all(preflight_value_is_context_free),
        ResultValue::Map(values) => values.values().all(preflight_value_is_context_free),
        ResultValue::Node(_) | ResultValue::Relationship(_) | ResultValue::Path { .. } => false,
    }
}

fn execute_plan_inner(
    mut plan: PhysicalPlan,
    context: &mut ExecutionContext<'_>,
    procedures: Option<&ProcedureCatalog>,
    mut stream: Option<&mut dyn FnMut(ExecutionStreamItem) -> Result<()>>,
    force_host_adaptive: bool,
) -> Result<ExecutionOutput> {
    check_execution(context)?;
    // Bare cardinality: `MATCH (n[:Label]) RETURN count(n)` is answered in O(1) from the optimizer
    // statistics instead of materializing one row per node (which trips the row budget at millions).
    // Only for a pure read with no pending mutations, so the statistics snapshot is authoritative.
    if !context.capabilities.require_native_execution
        && context.prior_graph_mutations.is_empty()
        && context.prior_temporal_mutations.is_empty()
        && let Some((label_name, output_name)) = plan_is_label_count(&plan)
    {
        // Answer `count(n)` / `count(n:Label)` / `count(*)` directly from the graph's O(1) live
        // counters. This is independent of the optimizer statistics snapshot, so the fast path fires
        // the first time a count is asked — no heavyweight pre-warm scan required — and both a bare
        // CPU node and a resident GPU node return the same cardinality without materializing rows.
        let view = GraphReadView::new(context.graph);
        let count = match &label_name {
            Some(name) => view.label(name).map_or(0, |label| {
                context.graph.label_node_count(label, plan.read_layers)
            }),
            None => context.graph.node_count_in_layers(plan.read_layers),
        };
        return emit_resident_scalar_count(count, &output_name, &view, context, stream);
    }
    // Relationship counts: `MATCH ()-[r]->() RETURN count(r)` / `count(*)` (optionally `[r:TYPE]`)
    // reduce to the graph's O(1) live edge counters, the same way label counts do for nodes.
    if !context.capabilities.require_native_execution
        && context.prior_graph_mutations.is_empty()
        && context.prior_temporal_mutations.is_empty()
        && let Some((type_name, output_name)) = plan_is_relationship_count(&plan)
    {
        let view = GraphReadView::new(context.graph);
        let count = match &type_name {
            Some(name) => view.relationship_type(name).map_or(0, |relationship_type| {
                context
                    .graph
                    .relationship_count(relationship_type, plan.read_layers)
            }),
            None => context.graph.edge_count_in_layers(plan.read_layers),
        };
        return emit_resident_scalar_count(count, &output_name, &view, context, stream);
    }
    // `count(DISTINCT n.<int property>)` over a bare label scan: the answer is the number of distinct
    // non-null integer values of that column. Collect them in one column pass into a set instead of
    // the segmented cell-materialization path (which reduces one cell per node). count() ignores
    // NULL, so rows missing the property contribute nothing.
    if !context.capabilities.require_native_execution
        && context.prior_graph_mutations.is_empty()
        && context.prior_temporal_mutations.is_empty()
        && let Some((label_name, property_name, output_name)) =
            plan_is_property_distinct_count(&plan)
        && let Some(property) = context.binding_catalog.property(&property_name)
        && context.graph.node_property_is_integer(property)
    {
        let view = GraphReadView::new(context.graph);
        // A named label that does not exist matches no nodes, so the distinct count is zero.
        let label = label_name.as_deref().map(|name| view.label(name));
        if label != Some(None) {
            let label = label.flatten();
            let mut distinct = std::collections::HashSet::<i64>::new();
            for node in context.graph.nodes() {
                if !plan.read_layers.contains_layer(node.layer()) {
                    continue;
                }
                if let Some(label) = label
                    && !node.labels().contains(&label)
                {
                    continue;
                }
                if let Some(ScalarValue::Integer(value)) = node.property(property) {
                    distinct.insert(value);
                }
            }
            return emit_resident_scalar_count(
                distinct.len() as u64,
                &output_name,
                &view,
                context,
                stream,
            );
        }
    }
    // Variable-length reachability count: `MATCH (n[:L])-[:R*min..max]->(m[:E]) RETURN count(DISTINCT m)`
    // with an anonymous, outgoing, single-type relationship and min-hops <= 1. The distinct reachable
    // end-node set is one O(V+E) frontier BFS over the resident adjacency — versus the host trail
    // enumeration, which is exponential (and hits the row budget at scale).
    if !context.capabilities.require_native_execution
        && context.prior_graph_mutations.is_empty()
        && context.prior_temporal_mutations.is_empty()
        && let Some(spec) = plan_is_reachable_endpoint_count(&plan)
    {
        return execute_reachable_endpoint_count(&spec, context, stream);
    }
    // Indexed point lookups cost less on the host (an equality-index hit in microseconds) than a
    // GPU command-buffer dispatch (~5-6ms fixed). Skip the resident path for them so they fall
    // through to host execution below. The conformance gate (`require_native_execution`) still
    // exercises the native path.
    let force_host_fast_read = !context.capabilities.require_native_execution
        && context
            .backend
            .is_some_and(|backend| backend.kind() != crate::execution::BackendKind::Cpu)
        && (plan_is_host_fast_read(&plan) || plan_is_host_indexed_seek_read(&plan));
    // A bare limited scan (`MATCH (n[:Label]) RETURN … [SKIP s] LIMIT k`, no filter/sort/aggregate/
    // DISTINCT) is answered on the host in O(s + k) by stopping the label scan early. The resident
    // node pipeline instead scans the whole label and truncates the output, which is O(label). Route
    // these to the host bounded scan on every backend; the conformance gate still exercises native.
    let force_host_bounded_scan =
        !context.capabilities.require_native_execution && plan_bare_scan_row_cap(&plan).is_some();
    // Production Metal nodes use the versioned measured crossover table. This is a pre-execution
    // choice against one pinned canonical generation, not a failure fallback: no work has started,
    // no graph is copied, and an unknown/unmeasured plan remains Metal-first.
    if !force_host_fast_read
        && !force_host_bounded_scan
        && !force_host_adaptive
        && let Some(output) = execute_resident_plan(&plan, context, procedures, &mut stream)?
    {
        return Ok(output);
    }
    if !force_host_fast_read
        && !force_host_bounded_scan
        && !force_host_adaptive
        && let Some(backend) = context.backend
        && backend.kind() != crate::execution::BackendKind::Cpu
    {
        if context.capabilities.require_native_execution && !plan_has_builtin_graph_procedure(&plan)
        {
            return Err(Error::new(
                ErrorCode::GpuAdmissionFailure,
                "active GPU execution class has no complete resident implementation for this query plan",
            ));
        }
        // Reaching here means a GPU backend is active and this plan has no resident implementation,
        // so it is evaluated on the host instead. On Apple unified memory the host IS the authority
        // and answers point/traversal reads in microseconds; many plan shapes (multi-clause writes
        // like the example-data seed, uncovered variable-length reads) are correctly and quickly run
        // here by design. This is therefore a native-*coverage* signal, not a runtime fault — and the
        // guardrail that actually enforces coverage is the conformance gate, which sets
        // `require_native_execution` and hard-errors above this point when a shape is uncovered. So at
        // production log levels this belongs at debug: emitting it at warn made every correct
        // host-executed query (the seed included) look like a malfunction. Raise the log level (or run
        // the conformance gate) to audit native coverage.
        tracing::debug!(
            backend = ?backend.kind(),
            read_only = plan.read_only,
            "query plan has no resident implementation; evaluated on the host (authority under unified memory)"
        );
    }
    // Writes whose graph access cannot stay resident are refused on a discrete GPU. Host-executing
    // such a plan there would build the canonical mutation batch from a different memory image
    // while the resident graph is the authority. Metal is different: its canonical transaction
    // graph is the same Apple unified-memory allocation addressed by the GPU, so an uncovered
    // mutation may safely use the host executor after resident compilation has declined it.
    //
    // Reads are not the same case and used to be refused alongside them. `ScanPattern` — every
    // variable-length pattern — has no host implementation admitted here, so any shape the
    // resident compilers did not cover failed outright instead of running. The resident
    // variable-path compiler is a chain of exact shape matchers grown from the pinned TCK corpus,
    // so "not covered" means "no scenario in that corpus needed it", not "cannot be answered":
    // `MATCH p=(a)-[:R*1..3]->(b) RETURN count(*)` is ordinary Cypher, is answered correctly by
    // the identical host path on a CPU node, and failed only because this node has a GPU. A
    // database that refuses a valid read because one execution strategy lacks a specialization is
    // not being strict, it is wrong. Reads now fall through to the same host execution a CPU node
    // performs, and the warn above records that native coverage was missing.
    //
    // The conformance gate is unaffected: it sets `require_native_execution`, which returns above
    // this point, so an uncovered scenario still fails there rather than passing on the host.
    if !plan.read_only
        && context
            .backend
            .is_some_and(|backend| backend.kind() != crate::execution::BackendKind::Cpu)
        && plan_requires_native_resident_execution(&plan)
        && !plan_supports_resident_mutation_execution(&plan)
        // Metal's resident image and the transaction graph share Apple unified memory. Falling
        // through here therefore executes against the same complete canonical generation; it is
        // not a host mirror, copy, or paged fallback. CUDA has discrete device authority and must
        // keep refusing an uncovered mutation plan.
        && !context
            .backend
            .is_some_and(|backend| backend.kind() == crate::execution::BackendKind::Metal)
    {
        return Err(Error::new(
            ErrorCode::GpuAdmissionFailure,
            "active GPU execution class has no complete resident implementation for this query plan",
        ));
    }
    let mut runtime_replans = 0_u8;
    loop {
        let mut dependencies = TransactionDependencies::default();
        for dependency in &plan.dependencies {
            let version = context
                .predicate_versions
                .get(dependency)
                .copied()
                .unwrap_or(context.bookmark.index);
            dependencies.predicates.insert(dependency.clone(), version);
        }
        let mut state = ExecutionState {
            graph: transaction_graph_view(context)?,
            temporal: transaction_temporal_view(context)?,
            mutations: Vec::new(),
            temporal_mutations: Vec::new(),
            dependencies,
            next_node_id: context.next_node_id,
            next_edge_id: context.next_edge_id,
            revision: context.mutation_revision,
            created_at: resolved_created_at(context.resolved_time_nanos),
            read_layers: plan.read_layers,
            write_layer: plan.write_layer,
            stats: StatementStats::default(),
            final_columns: Vec::new(),
            scope_columns: BTreeSet::new(),
            administrative: None,
            vector_searches: Vec::new(),
            resident_backend: if force_host_adaptive {
                None
            } else {
                context
                    .backend
                    .filter(|backend| backend.kind() != crate::execution::BackendKind::Cpu)
                    .map(|backend| backend.pin_project(context.project_id))
                    .transpose()?
            },
            allow_context_backend: !force_host_adaptive,
            resident_overlay_mutations: 0,
            existential_subquery_depth: 0,
            initial_scan_cap: plan_bare_scan_row_cap(&plan),
        };
        let mut rows = vec![Row::new()];
        let mut feedback = None;
        let mut operator_index = 0_usize;
        while operator_index < plan.operators.len() {
            let operator = &plan.operators[operator_index];
            check_execution(context)?;
            let (next_rows, consumed) = apply_operator_sequence_step(
                &plan.operators,
                operator_index,
                rows,
                &mut state,
                context,
                procedures,
            )?;
            rows = next_rows;
            operator_index = operator_index.saturating_add(consumed);
            if runtime_replans == 0
                && plan.read_only
                && plan.unions.is_empty()
                && context.prior_graph_mutations.is_empty()
                && context.prior_temporal_mutations.is_empty()
                && state.mutations.is_empty()
                && state.temporal_mutations.is_empty()
                && let PhysicalOperator::CardinalityCheckpoint {
                    pattern_key,
                    estimated_rows,
                } = operator
                && super::optimizer::cardinality_misestimation(*estimated_rows, rows.len() as u64)
            {
                feedback = Some((*pattern_key, rows.len() as u64));
                break;
            }
            if rows.len() > context.max_result_rows {
                return Err(Error::new(
                    ErrorCode::ResultBudgetExceeded,
                    "query row budget exceeded",
                ));
            }
        }
        if let Some((pattern_key, actual_rows)) = feedback {
            let collected;
            let statistics = if let Some(statistics) = context.optimizer_statistics {
                statistics
            } else {
                collected = StatisticsSnapshot::collect_project(
                    context.graph,
                    context.temporal,
                    context.scalar_indexes,
                );
                &collected
            };
            let runtime_feedback = BTreeMap::from([(pattern_key, actual_rows)]);
            let backend = if force_host_adaptive {
                crate::execution::BackendKind::Cpu
            } else {
                context
                    .backend
                    .map_or(crate::execution::BackendKind::Cpu, ExecutionBackend::kind)
            };
            let scratch_budget_bytes = if force_host_adaptive {
                usize::MAX
            } else {
                context
                    .backend
                    .map_or(usize::MAX, ExecutionBackend::available_query_scratch_bytes)
            };
            let (replanned, profile) = optimize(
                plan,
                OptimizerInput {
                    statistics,
                    catalog: context.binding_catalog,
                    indexes: context.scalar_indexes,
                    parameters: &context.parameters,
                    backend,
                    scratch_budget_bytes,
                    max_result_rows: context.max_result_rows,
                    runtime_feedback: Some(&runtime_feedback),
                    allow_runtime_checkpoint: false,
                },
            );
            if backend != crate::execution::BackendKind::Cpu && !profile.scratch_feasible {
                return Err(Error::retryable(
                    ErrorCode::GpuAdmissionFailure,
                    "runtime cardinality requires more device scratch than is available",
                    Some(10),
                ));
            }
            plan = replanned;
            runtime_replans = 1;
            continue;
        }
        let mut union_rows = rows;
        for (all, branch) in &plan.unions {
            check_execution(context)?;
            state.scope_columns.clear();
            let mut rows = vec![Row::new()];
            let mut operator_index = 0_usize;
            while operator_index < branch.len() {
                check_execution(context)?;
                let (next_rows, consumed) = apply_operator_sequence_step(
                    branch,
                    operator_index,
                    rows,
                    &mut state,
                    context,
                    procedures,
                )?;
                rows = next_rows;
                operator_index = operator_index.saturating_add(consumed);
            }
            union_rows.extend(rows);
            if !all {
                deduplicate_rows(&mut union_rows, &state.graph)?;
            }
        }
        let result = rows_to_result(
            &union_rows,
            &state.final_columns,
            &state.graph,
            context.bookmark,
            state.stats,
            context.max_batch_rows,
            stream,
        )?;
        return Ok(ExecutionOutput {
            result,
            graph_mutations: state.mutations,
            temporal_mutations: state.temporal_mutations,
            dependencies: state.dependencies,
            administrative: state.administrative,
            vector_searches: state.vector_searches,
            runtime_replans,
        });
    }
}

/// Version of the production CPU/Metal crossover table. The thresholds below come from the
/// 2026-08-25 Apple M5 Pro matrix in `performance-results/adaptive-routing/`.
/// Increment this when a fresh full matrix changes a threshold; keeping the policy explicit makes
/// a routing change reviewable and keeps query dispatch to one small in-process branch.
const ADAPTIVE_METAL_POLICY_VERSION: u32 = 8;

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
enum AdaptiveExecutor {
    Cpu,
    Metal,
}

fn adaptive_executor_for_graph_procedure(name: &str, nodes: usize) -> AdaptiveExecutor {
    debug_assert_eq!(ADAPTIVE_METAL_POLICY_VERSION, 8);
    let metal = match name {
        // Full production Cypher timings include filtered-adjacency setup, procedure-row
        // publication and downstream aggregation. Use the first measured winning size rather than
        // interpolating an unmeasured midpoint between matrix rows.
        "graph.degree" => nodes >= 10_000,
        "graph.trianglecount" => nodes >= 100_000,
        "graph.clusteringcoefficient" => (100_000..2_000_000).contains(&nodes),
        "graph.kcore" => nodes >= 100_000,
        // The in-place CPU delta path wins every current dense matrix size through 2M/8M and the
        // sparse 2.02M-node ICIJ graph. Preserve the final measured CPU winner above the endpoint.
        "graph.louvain" => false,
        // The remaining procedures are faster on CPU at the measured 2M-node / 8M-edge endpoint.
        // Above the measured range, preserve each procedure's last measured winner instead of
        // introducing an evidence-free backend discontinuity at 2,000,001 nodes. A larger
        // benchmark may revise this versioned policy when it establishes a real crossover.
        _ => false,
    };
    if metal {
        AdaptiveExecutor::Metal
    } else {
        AdaptiveExecutor::Cpu
    }
}

fn plan_has_builtin_graph_procedure(plan: &PhysicalPlan) -> bool {
    plan.operators.iter().any(|operator| {
        matches!(
            operator,
            PhysicalOperator::BuiltinProcedure(call)
                if call.name.len() == 2 && call.name[0].eq_ignore_ascii_case("graph")
        )
    })
}

#[cfg(test)]
mod adaptive_execution_policy_tests {
    use super::*;

    #[test]
    fn adaptive_execution_policy_keeps_only_measured_graph_procedure_wins_on_metal() {
        assert_eq!(ADAPTIVE_METAL_POLICY_VERSION, 8);
        for name in [
            "graph.bfs",
            "graph.dfs",
            "graph.shortestpath",
            "graph.dijkstra",
            "graph.wcc",
            "graph.scc",
            "graph.pagerank",
        ] {
            assert_eq!(
                adaptive_executor_for_graph_procedure(name, 2_000_000),
                AdaptiveExecutor::Cpu,
                "{name} must stay on its measured CPU winner"
            );
        }
        assert_eq!(
            adaptive_executor_for_graph_procedure("graph.degree", 100),
            AdaptiveExecutor::Cpu
        );
        assert_eq!(
            adaptive_executor_for_graph_procedure("graph.degree", 10_000),
            AdaptiveExecutor::Metal
        );
        assert_eq!(
            adaptive_executor_for_graph_procedure("graph.trianglecount", 10_000),
            AdaptiveExecutor::Cpu
        );
        assert_eq!(
            adaptive_executor_for_graph_procedure("graph.trianglecount", 100_000),
            AdaptiveExecutor::Metal
        );
        assert_eq!(
            adaptive_executor_for_graph_procedure("graph.trianglecount", 1_000_000),
            AdaptiveExecutor::Metal
        );
        assert_eq!(
            adaptive_executor_for_graph_procedure("graph.trianglecount", 2_000_000),
            AdaptiveExecutor::Metal
        );
        assert_eq!(
            adaptive_executor_for_graph_procedure("graph.trianglecount", usize::MAX),
            AdaptiveExecutor::Metal
        );
        assert_eq!(
            adaptive_executor_for_graph_procedure("graph.clusteringcoefficient", 100_000),
            AdaptiveExecutor::Metal
        );
        assert_eq!(
            adaptive_executor_for_graph_procedure("graph.clusteringcoefficient", 1_000_000),
            AdaptiveExecutor::Metal
        );
        assert_eq!(
            adaptive_executor_for_graph_procedure("graph.clusteringcoefficient", usize::MAX),
            AdaptiveExecutor::Cpu
        );
        assert_eq!(
            adaptive_executor_for_graph_procedure("graph.kcore", 10_000),
            AdaptiveExecutor::Cpu
        );
        assert_eq!(
            adaptive_executor_for_graph_procedure("graph.kcore", 100_000),
            AdaptiveExecutor::Metal
        );
        assert_eq!(
            adaptive_executor_for_graph_procedure("graph.kcore", usize::MAX),
            AdaptiveExecutor::Metal
        );
        assert_eq!(
            adaptive_executor_for_graph_procedure("graph.louvain", 100_000),
            AdaptiveExecutor::Cpu
        );
        assert_eq!(
            adaptive_executor_for_graph_procedure("graph.louvain", 1_000_000),
            AdaptiveExecutor::Cpu
        );
        assert_eq!(
            adaptive_executor_for_graph_procedure("graph.louvain", 2_017_662),
            AdaptiveExecutor::Cpu,
            "ICIJ topology must use its measured CPU winner"
        );
        assert_eq!(
            adaptive_executor_for_graph_procedure("graph.louvain", 2_000_000),
            AdaptiveExecutor::Cpu
        );
        assert_eq!(
            adaptive_executor_for_graph_procedure("graph.louvain", 2_000_001),
            AdaptiveExecutor::Cpu
        );
        assert_eq!(
            adaptive_executor_for_graph_procedure("graph.bfs", usize::MAX),
            AdaptiveExecutor::Cpu
        );
    }
}

/// A read whose primary access is an indexed point lookup (`MATCH (n:L {indexed: value})` or a
/// stable-id lookup) that touches at most a handful of rows. On a GPU node these are dominated by
/// the fixed Metal command-buffer dispatch (~5-6ms) even though the actual work is O(1); the host
/// executor resolves the same lookup through the equality index in microseconds, reading the
/// resident graph directly (on Apple's unified memory that is the *same* physical memory the GPU
/// uses, so there is no copy). Routing these to the host beats the dispatch floor; large scans,
/// traversals, and aggregations stay on the GPU where its parallelism pays for the dispatch.
fn plan_is_host_fast_read(plan: &PhysicalPlan) -> bool {
    if !plan.read_only || plan.at_time.is_some() || !plan.unions.is_empty() {
        return false;
    }
    let mut point_scans = 0usize;
    for operator in &plan.operators {
        match operator {
            PhysicalOperator::CardinalityCheckpoint { .. }
            | PhysicalOperator::Filter(_)
            | PhysicalOperator::Project { .. }
            | PhysicalOperator::Limit(_) => {}
            PhysicalOperator::ScanPattern {
                access,
                pattern,
                optional,
                ..
            } => {
                // A bare indexed start node — no relationship expansion, which could fan out to an
                // unbounded working set that the GPU should handle.
                let point = !*optional
                    && pattern.steps.is_empty()
                    && pattern.variable.is_none()
                    && matches!(
                        access,
                        ScanAccessPath::EqualityIndex { .. } | ScanAccessPath::StableId { .. }
                    );
                if !point {
                    return false;
                }
                point_scans += 1;
            }
            _ => return false,
        }
    }
    point_scans == 1
}

/// A read that seeks a *selective* indexed/stable start node and then expands a bounded, fixed-length
/// relationship pattern. The host seeks the start through the equality index (microseconds) and walks
/// the CSR from those few nodes, versus a GPU command-buffer dispatch that scans every node of the
/// start label and expands the whole frontier (~tens of ms at 100k+). Variable-length patterns can
/// fan out an unbounded frontier and are left to the resident compiler. Gated on a small estimated
/// start-row count so a non-selective index (which would expand from many starts) still uses the GPU.
fn plan_is_host_indexed_seek_read(plan: &PhysicalPlan) -> bool {
    if !plan.read_only || plan.at_time.is_some() || !plan.unions.is_empty() {
        return false;
    }
    // Max estimated start rows that stay on the host. A selective key seek returns a handful of
    // starts; above this the GPU's parallel expand is the better tool.
    const MAX_SEED_ROWS: u64 = 1024;
    let mut seeds = 0usize;
    for operator in &plan.operators {
        match operator {
            PhysicalOperator::CardinalityCheckpoint { .. }
            | PhysicalOperator::Filter(_)
            | PhysicalOperator::Project { .. }
            | PhysicalOperator::Limit(_) => {}
            PhysicalOperator::ScanPattern {
                access,
                pattern,
                optional,
                ..
            } => {
                if *optional || pattern.variable.is_some() {
                    return false;
                }
                let selective = match access {
                    ScanAccessPath::EqualityIndex { estimated_rows, .. } => {
                        *estimated_rows <= MAX_SEED_ROWS
                    }
                    ScanAccessPath::StableId { .. } => true,
                    _ => return false,
                };
                if !selective {
                    return false;
                }
                // Fixed-length hops only — no variable-length / bounded-repetition expansion.
                if pattern.steps.iter().any(|step| {
                    step.relationship.variable_length
                        || step.relationship.min_hops.is_some()
                        || step.relationship.max_hops.is_some()
                }) {
                    return false;
                }
                seeds += 1;
            }
            _ => return false,
        }
    }
    seeds == 1
}

/// A bare label/all-node cardinality query — `MATCH (n[:Label]) RETURN count(n) [AS c]` with no
/// steps, no property predicate, no filter, no `DISTINCT`, and no other operators. Every scanned
/// row binds `n`, so `count(n)` equals the number of matching nodes, which the maintained optimizer
/// statistics already hold per label. Returns `(optional start-label name, output column name)`.
///
/// Without this, the host executor materializes one row per node before aggregating — 1M rows at a
/// million nodes, which trips the result-row budget. This lets the count return in O(1) from the
/// statistics snapshot instead, in every execution mode (host, deferred, or GPU-absent).
/// Emits a single-row, single-column integer result carrying `count` under `output_name`. Shared by
/// the O(1) label-count and relationship-count fast paths.
fn emit_resident_scalar_count(
    count: u64,
    output_name: &str,
    view: &GraphReadView<'_>,
    context: &ExecutionContext<'_>,
    stream: Option<&mut dyn FnMut(ExecutionStreamItem) -> Result<()>>,
) -> Result<ExecutionOutput> {
    let value = i64::try_from(count)
        .map_err(|_| Error::new(ErrorCode::ResultBudgetExceeded, "count exceeds INTEGER"))?;
    let mut row = Row::new();
    row.insert(
        output_name.to_string(),
        BindingValue::Value(ResultValue::Scalar(ScalarValue::Integer(value))),
    );
    let output_names = [output_name.to_string()];
    let result = rows_to_result(
        std::slice::from_ref(&row),
        &output_names,
        view,
        context.bookmark,
        StatementStats::default(),
        context.max_batch_rows,
        stream,
    )?;
    Ok(ExecutionOutput {
        result,
        graph_mutations: Vec::new(),
        temporal_mutations: Vec::new(),
        dependencies: TransactionDependencies::default(),
        administrative: None,
        vector_searches: Vec::new(),
        runtime_replans: 0,
    })
}

/// Recognizes `MATCH ()-[r]->() RETURN count(r)` / `count(*)`, optionally typed `[r:TYPE]`, with
/// anonymous unlabelled endpoints and a single **directed** fixed-length relationship step. Returns
/// `(optional relationship-type name, output column name)`. Direction matters: an undirected
/// `()-[r]-()` matches each relationship once per orientation, so it is deliberately rejected here —
/// only directed patterns count each edge exactly once, making the answer the O(1) live edge count.
fn plan_is_relationship_count(plan: &PhysicalPlan) -> Option<(Option<String>, String)> {
    if !plan.read_only || plan.at_time.is_some() || !plan.unions.is_empty() {
        return None;
    }
    let PhysicalOperator::ScanPattern {
        optional: false,
        pattern,
        ..
    } = plan.operators.first()?
    else {
        return None;
    };
    if pattern.variable.is_some()
        || pattern.selector != PathSelector::All
        || pattern.mode != PathMode::DifferentRelationships
    {
        return None;
    }
    // Both endpoints must be anonymous and unfiltered, or the count is not the whole edge population.
    let endpoints_plain = |node: &crate::cypher::ast::NodePattern| {
        node.labels.is_empty() && node.properties.is_empty() && !node.property_predicate_present
    };
    if !endpoints_plain(&pattern.start) {
        return None;
    }
    let [step] = pattern.steps.as_slice() else {
        return None;
    };
    if !endpoints_plain(&step.node) {
        return None;
    }
    // A self-relationship pattern `(n)-[r]->(n)` (same endpoint variable) constrains source == target,
    // so it counts only self-loops — not the whole edge population. Reject it. Distinct or anonymous
    // endpoints impose no such constraint and every edge is matched exactly once.
    if pattern.start.variable.is_some() && pattern.start.variable == step.node.variable {
        return None;
    }
    let relationship = &step.relationship;
    if relationship.variable_length
        || relationship.min_hops.is_some()
        || relationship.max_hops.is_some()
        || !relationship.properties.is_empty()
        || matches!(
            relationship.direction,
            crate::cypher::ast::Direction::Undirected
        )
    {
        return None;
    }
    // At most one relationship type; more than one would be a disjunction sum, not a single counter.
    let relationship_type = match relationship.types.as_slice() {
        [] => None,
        [single] => Some(single.clone()),
        _ => return None,
    };
    let relationship_variable = relationship.variable.as_deref();
    let mut cursor = 1_usize;
    if matches!(
        plan.operators.get(cursor),
        Some(PhysicalOperator::CardinalityCheckpoint { .. })
    ) {
        cursor += 1;
    }
    let Some(PhysicalOperator::Project {
        keep_scope: false,
        projection,
    }) = plan.operators.get(cursor)
    else {
        return None;
    };
    cursor += 1;
    if cursor != plan.operators.len() || projection.distinct {
        return None;
    }
    let [item] = projection.items.as_slice() else {
        return None;
    };
    let Expression::Function {
        name,
        distinct: false,
        arguments,
    } = &item.expression
    else {
        return None;
    };
    if !matches!(name.as_slice(), [only] if only.eq_ignore_ascii_case("count")) {
        return None;
    }
    match arguments.as_slice() {
        // `count(r)` — the relationship variable is bound on every matched row.
        [Expression::Variable(variable)]
            if relationship_variable.is_some_and(|name| name == variable) => {}
        // `count(*)` — one row per matched relationship.
        [Expression::Star] => {}
        _ => return None,
    }
    Some((relationship_type, item.column_name(0)))
}

/// Recognizes `MATCH (n[:Label]) RETURN count(DISTINCT n.<prop>)` — a single unfiltered node scan
/// projecting exactly one distinct-count over a property of the scanned node. Returns
/// `(optional label name, property name, output column name)`. Any filter, relationship step, extra
/// projection item, or `DISTINCT` on the projection itself declines.
fn plan_is_property_distinct_count(
    plan: &PhysicalPlan,
) -> Option<(Option<String>, String, String)> {
    if !plan.read_only || plan.at_time.is_some() || !plan.unions.is_empty() {
        return None;
    }
    let PhysicalOperator::ScanPattern {
        optional: false,
        pattern,
        access,
        ..
    } = plan.operators.first()?
    else {
        return None;
    };
    let outer = pattern.start.variable.as_ref()?;
    if pattern.variable.is_some()
        || pattern.selector != PathSelector::All
        || pattern.mode != PathMode::DifferentRelationships
        || pattern.start.property_predicate_present
        || !pattern.start.properties.is_empty()
        || !pattern.steps.is_empty()
    {
        return None;
    }
    let label = match access {
        ScanAccessPath::Label { label } => Some(label.clone()),
        ScanAccessPath::AllNodes => None,
        _ => return None,
    };
    match (&label, pattern.start.labels.as_slice()) {
        (Some(scanned), [declared]) if scanned == declared => {}
        (None, []) => {}
        _ => return None,
    }
    let mut cursor = 1_usize;
    if matches!(
        plan.operators.get(cursor),
        Some(PhysicalOperator::CardinalityCheckpoint { .. })
    ) {
        cursor += 1;
    }
    let Some(PhysicalOperator::Project {
        keep_scope: false,
        projection,
    }) = plan.operators.get(cursor)
    else {
        return None;
    };
    cursor += 1;
    if cursor != plan.operators.len() || projection.distinct {
        return None;
    }
    let [item] = projection.items.as_slice() else {
        return None;
    };
    let Expression::Function {
        name,
        distinct: true,
        arguments,
    } = &item.expression
    else {
        return None;
    };
    if !matches!(name.as_slice(), [only] if only.eq_ignore_ascii_case("count")) {
        return None;
    }
    // The single argument must be exactly `<outer>.<property>`.
    let [Expression::Property(source, property)] = arguments.as_slice() else {
        return None;
    };
    let Expression::Variable(variable) = source.as_ref() else {
        return None;
    };
    if variable != outer {
        return None;
    }
    Some((label, property.clone(), item.column_name(0)))
}

/// Shape of `MATCH (n[:L])-[:R*min..max]->(m[:E]) RETURN count(DISTINCT m)`: a single unfiltered
/// scan whose one step is an anonymous, outgoing, single-type (or untyped) variable-length
/// relationship with minimum hops <= 1, and whose sole projection is `count(DISTINCT <end>)`.
struct ReachableEndpointCount {
    start_label: Option<String>,
    endpoint_label: Option<String>,
    relationship_type: Option<String>,
    min_hops: u32,
    max_hops: Option<u32>,
    layers: crate::graph::LayerMask,
    output_name: String,
}

fn plan_is_reachable_endpoint_count(plan: &PhysicalPlan) -> Option<ReachableEndpointCount> {
    if !plan.read_only || plan.at_time.is_some() || !plan.unions.is_empty() {
        return None;
    }
    let PhysicalOperator::ScanPattern {
        optional: false,
        pattern,
        ..
    } = plan.operators.first()?
    else {
        return None;
    };
    if pattern.variable.is_some()
        || pattern.selector != PathSelector::All
        || pattern.mode != PathMode::DifferentRelationships
        || pattern.start.property_predicate_present
        || !pattern.start.properties.is_empty()
    {
        return None;
    }
    let start_label = match pattern.start.labels.as_slice() {
        [] => None,
        [label] => Some(label.clone()),
        _ => return None,
    };
    let [step] = pattern.steps.as_slice() else {
        return None;
    };
    if step.node.property_predicate_present || !step.node.properties.is_empty() {
        return None;
    }
    let endpoint_variable = step.node.variable.as_deref()?;
    let endpoint_label = match step.node.labels.as_slice() {
        [] => None,
        [label] => Some(label.clone()),
        _ => return None,
    };
    let relationship = &step.relationship;
    if !relationship.variable_length
        || relationship.variable.is_some()
        || !relationship.properties.is_empty()
        || !matches!(
            relationship.direction,
            crate::cypher::ast::Direction::Outgoing
        )
    {
        return None;
    }
    let relationship_type = match relationship.types.as_slice() {
        [] => None,
        [single] => Some(single.clone()),
        _ => return None,
    };
    // Shortest-path reachability is only equivalent to trail-existence when the minimum is <= 1.
    let min_hops = relationship.min_hops.unwrap_or(1);
    if min_hops > 1 {
        return None;
    }
    let mut cursor = 1_usize;
    if matches!(
        plan.operators.get(cursor),
        Some(PhysicalOperator::CardinalityCheckpoint { .. })
    ) {
        cursor += 1;
    }
    let Some(PhysicalOperator::Project {
        keep_scope: false,
        projection,
    }) = plan.operators.get(cursor)
    else {
        return None;
    };
    cursor += 1;
    if cursor != plan.operators.len() || projection.distinct {
        return None;
    }
    let [item] = projection.items.as_slice() else {
        return None;
    };
    let Expression::Function {
        name,
        distinct: true,
        arguments,
    } = &item.expression
    else {
        return None;
    };
    if !matches!(name.as_slice(), [only] if only.eq_ignore_ascii_case("count")) {
        return None;
    }
    if !matches!(arguments.as_slice(), [Expression::Variable(variable)] if variable == endpoint_variable)
    {
        return None;
    }
    Some(ReachableEndpointCount {
        start_label,
        endpoint_label,
        relationship_type,
        min_hops,
        max_hops: relationship.max_hops,
        layers: plan.read_layers,
        output_name: item.column_name(0),
    })
}

/// Answers `count(DISTINCT <end>)` for a variable-length reachability pattern with one global
/// multi-source frontier BFS over the resident adjacency: O(V+E), and correct for the seed-overlap
/// case (a node that is both a start and, via a cycle, a reachable endpoint is counted).
fn execute_reachable_endpoint_count(
    spec: &ReachableEndpointCount,
    context: &ExecutionContext<'_>,
    stream: Option<&mut dyn FnMut(ExecutionStreamItem) -> Result<()>>,
) -> Result<ExecutionOutput> {
    let graph = context.graph;
    let view = GraphReadView::new(graph);
    let layers = spec.layers;
    // A named label or relationship type that does not exist matches nothing, so the count is zero.
    let relationship_type = match &spec.relationship_type {
        Some(name) => match view.relationship_type(name) {
            Some(id) => Some(id),
            None => {
                return emit_resident_scalar_count(0, &spec.output_name, &view, context, stream);
            }
        },
        None => None,
    };
    let start_label = match &spec.start_label {
        Some(name) => Some(match view.label(name) {
            Some(id) => id,
            None => {
                return emit_resident_scalar_count(0, &spec.output_name, &view, context, stream);
            }
        }),
        None => None,
    };
    let endpoint_label = match &spec.endpoint_label {
        Some(name) => Some(match view.label(name) {
            Some(id) => id,
            None => {
                return emit_resident_scalar_count(0, &spec.output_name, &view, context, stream);
            }
        }),
        None => None,
    };

    let mut seeds: Vec<NodeId> = Vec::new();
    for node in graph.nodes() {
        if !layers.contains_layer(node.layer()) {
            continue;
        }
        if let Some(label) = start_label
            && !node.labels().contains(&label)
        {
            continue;
        }
        seeds.push(node.id());
    }

    // `visited` bounds expansion (each node expanded at most once → O(V+E)); `reachable` is the
    // answer (nodes reached at a hop in [min_hops, max_hops]). They are separate so a start reached
    // back at >= 1 hop is still counted.
    let mut visited: std::collections::HashSet<u64> =
        std::collections::HashSet::with_capacity(seeds.len());
    let mut reachable: std::collections::HashSet<u64> = std::collections::HashSet::new();
    if spec.min_hops == 0 {
        reachable.extend(seeds.iter().map(|seed| seed.0));
    }
    visited.extend(seeds.iter().map(|seed| seed.0));
    let mut frontier = seeds;
    let max_hops = spec.max_hops.map_or(u64::MAX, u64::from);
    let mut hop = 1_u64;
    while !frontier.is_empty() && hop <= max_hops {
        check_execution(context)?;
        let mut next = Vec::new();
        for node in &frontier {
            for (_edge, neighbor) in graph.expand_out(*node, relationship_type, layers)? {
                let id = neighbor.id().0;
                if hop >= u64::from(spec.min_hops) {
                    reachable.insert(id);
                }
                if visited.insert(id) {
                    next.push(neighbor.id());
                }
            }
        }
        frontier = next;
        hop += 1;
    }

    let count = match endpoint_label {
        Some(label) => reachable
            .iter()
            .filter(|id| {
                graph
                    .node(NodeId(**id))
                    .is_some_and(|node| node.labels().contains(&label))
            })
            .count(),
        None => reachable.len(),
    };
    emit_resident_scalar_count(count as u64, &spec.output_name, &view, context, stream)
}

fn plan_is_label_count(plan: &PhysicalPlan) -> Option<(Option<String>, String)> {
    if !plan.read_only || plan.at_time.is_some() || !plan.unions.is_empty() {
        return None;
    }
    let PhysicalOperator::ScanPattern {
        optional: false,
        pattern,
        access,
        ..
    } = plan.operators.first()?
    else {
        return None;
    };
    let outer = pattern.start.variable.as_ref()?;
    if pattern.variable.is_some()
        || pattern.selector != PathSelector::All
        || pattern.mode != PathMode::DifferentRelationships
        || pattern.start.property_predicate_present
        || !pattern.start.properties.is_empty()
        || !pattern.steps.is_empty()
    {
        return None;
    }
    let label = match access {
        ScanAccessPath::Label { label } => Some(label.clone()),
        ScanAccessPath::AllNodes => None,
        _ => return None,
    };
    // The declared labels must agree with the access path: exactly the one scanned label, or none.
    match (&label, pattern.start.labels.as_slice()) {
        (Some(scanned), [declared]) if scanned == declared => {}
        (None, []) => {}
        _ => return None,
    }
    let mut cursor = 1_usize;
    if matches!(
        plan.operators.get(cursor),
        Some(PhysicalOperator::CardinalityCheckpoint { .. })
    ) {
        cursor += 1;
    }
    let Some(PhysicalOperator::Project {
        keep_scope: false,
        projection,
    }) = plan.operators.get(cursor)
    else {
        return None;
    };
    cursor += 1;
    if cursor != plan.operators.len() || projection.distinct {
        return None;
    }
    let [item] = projection.items.as_slice() else {
        return None;
    };
    // The single projected expression must be exactly `count(<outer>)` or `count(*)` (non-distinct).
    // For this single-scan, no-relationship-step shape the scanned node is bound on every matched
    // row, so `count(*)` equals `count(<outer>)` equals the matched-node cardinality.
    let Expression::Function {
        name,
        distinct: false,
        arguments,
    } = &item.expression
    else {
        return None;
    };
    if !matches!(name.as_slice(), [only] if only.eq_ignore_ascii_case("count")) {
        return None;
    }
    match arguments.as_slice() {
        [Expression::Variable(variable)] if variable == outer => {}
        [Expression::Star] => {}
        _ => return None,
    }
    Some((label, item.column_name(0)))
}

/// Row cap for a bare limited node scan: `MATCH (n[:Label]) [WITH/RETURN …] [SKIP s] LIMIT k` with no
/// filter, no relationship steps, no `DISTINCT`, no aggregation, and no ordering. Every scanned node
/// maps one-to-one to one output row through the projection, so the host scan needs to yield at most
/// `s + k` nodes. Bounding it there turns an O(label) materialization — which trips the result-row
/// budget once a label has more than `QUERY_EXECUTION_ROW_ADDRESS_SPACE` rows — into O(s + k), the
/// difference between answering a top-N read and failing it at millions of nodes.
///
/// Returns `None` for any shape where fewer-than-all scanned rows could change the answer: a `Filter`
/// (which may reject rows, so the scan must continue past `k`), `DISTINCT`, aggregation, `ORDER BY`
/// (`Sort`/`TopK`), a second pattern/scan, `UNWIND`, or a non-literal `SKIP`/`LIMIT`. `SKIP`/`LIMIT`
/// are already folded to integer literals by `resolve_plan_row_counts` before this runs.
fn plan_bare_scan_row_cap(plan: &PhysicalPlan) -> Option<usize> {
    if !plan.read_only || plan.at_time.is_some() || !plan.unions.is_empty() {
        return None;
    }
    let PhysicalOperator::ScanPattern {
        optional: false,
        pattern,
        access,
        ..
    } = plan.operators.first()?
    else {
        return None;
    };
    if pattern.variable.is_some()
        || pattern.selector != PathSelector::All
        || pattern.mode != PathMode::DifferentRelationships
        || pattern.start.property_predicate_present
        || !pattern.start.properties.is_empty()
        || !pattern.steps.is_empty()
    {
        return None;
    }
    if !matches!(
        access,
        ScanAccessPath::Label { .. } | ScanAccessPath::AllNodes
    ) {
        return None;
    }
    let mut skip = 0_usize;
    let mut limit: Option<usize> = None;
    for operator in plan.operators.iter().skip(1) {
        match operator {
            PhysicalOperator::CardinalityCheckpoint { .. } => {}
            PhysicalOperator::Project { projection, .. } => {
                if projection.distinct
                    || projection
                        .items
                        .iter()
                        .any(|item| super::expression::contains_aggregate(&item.expression))
                {
                    return None;
                }
            }
            PhysicalOperator::Skip(Expression::Literal(ScalarValue::Integer(value)))
                if *value >= 0 =>
            {
                skip = skip.saturating_add(*value as usize);
            }
            PhysicalOperator::Limit(Expression::Literal(ScalarValue::Integer(value)))
                if *value >= 0 =>
            {
                let value = *value as usize;
                limit = Some(limit.map_or(value, |existing| existing.min(value)));
            }
            _ => return None,
        }
    }
    // `s + k` is always a safe upper bound on the scanned rows the answer can depend on, regardless of
    // SKIP/LIMIT order, so a plan that never limits (limit is None) is not capped.
    limit.map(|limit| skip.saturating_add(limit))
}

fn plan_requires_native_resident_execution(plan: &PhysicalPlan) -> bool {
    plan.operators
        .iter()
        .chain(plan.unions.iter().flat_map(|(_, operators)| operators))
        .any(|operator| {
            matches!(
                operator,
                PhysicalOperator::ScanPattern { .. }
                    | PhysicalOperator::CyclicMultiwayJoin { .. }
                    | PhysicalOperator::TemporalHistory(_)
                    | PhysicalOperator::TemporalWindow(_)
                    | PhysicalOperator::TemporalHistoryWindow { .. }
            )
        })
}

/// Write plans may contain a bounded MATCH, but only when every graph access can remain on the
/// resident scan/expand path. The mutation operators themselves still produce the canonical
/// mutation batch; this whitelist prevents unsupported write plans from silently using host graph
/// scans on an active GPU node.
fn plan_supports_resident_mutation_execution(plan: &PhysicalPlan) -> bool {
    if !plan.unions.is_empty() {
        return false;
    }
    plan.operators.iter().all(|operator| match operator {
        PhysicalOperator::ScanPattern { pattern, .. } => {
            pattern.variable.is_none()
                && pattern.selector == PathSelector::All
                && pattern.mode == PathMode::DifferentRelationships
                && pattern.steps.len() <= 1
                && pattern.steps.iter().all(|step| {
                    !step.relationship.variable_length
                        && step.relationship.min_hops.is_none()
                        && step.relationship.max_hops.is_none()
                        && step.relationship.properties.is_empty()
                        && step.relationship.direction != Direction::Undirected
                        && step.node.variable.is_some()
                })
        }
        PhysicalOperator::CardinalityCheckpoint { .. }
        | PhysicalOperator::Filter(_)
        | PhysicalOperator::Unwind { .. }
        | PhysicalOperator::Project { .. }
        | PhysicalOperator::CreatePattern(_)
        // `Set` and `Remove` rewrite properties on rows the pattern has already bound. They perform
        // no graph access of their own, so they cannot smuggle in the host scan this whitelist
        // exists to prevent — and leaving them out refused a whole shape of ordinary write. A MATCH
        // filtered by a *parameter* cannot use an equality index at plan time, so it plans as a
        // `ScanPattern` where the identical filter written as a literal plans as a seek; the
        // parameterised form was therefore rejected outright on a GPU node while the literal ran.
        // Every internal writer passes values as parameters (interpolating them would be an
        // injection surface), so this took out property updates across the Workspace layer.
        | PhysicalOperator::Set(_)
        | PhysicalOperator::Remove(_)
        // A plain `DELETE` removes rows the pattern already bound and reads nothing further, so it
        // belongs here for the same reason. `DETACH DELETE` does not: finding a node's incident
        // relationships is graph access, and admitting it here would let it run off a host scan.
        | PhysicalOperator::Delete { detach: false, .. }
        | PhysicalOperator::Limit(_)
        | PhysicalOperator::Finish => true,
        _ => false,
    })
}

/// A plain fixed single-hop read that the streaming resident scan/expand executors
/// (`compile_resident` / `compile_resident_row`) handle in O(limit) by walking the CSR adjacency
/// directly. Such a plan must be kept away from the variable-path and nullable-relation compilers:
/// both reserve a device trail/candidate buffer whose size is O(edges × frontier), which cannot
/// scale to real graphs.
///
/// Restricted to a single hop deliberately: the streaming executors materialize intermediate rows
/// for multi-hop patterns rather than streaming with early LIMIT termination, so multi-hop belongs
/// with variable-length paths in the frontier-streaming work, not here.
///
/// The shape mirrors `plan_supports_resident_mutation_execution`'s streamable whitelist: exactly one
/// mandatory, directed, fixed single-hop `ScanPattern` with a bound end variable, an ordinary
/// (non-DISTINCT, non-aggregating) projection, and only streaming-compatible operators around it
/// (WHERE filters, LIMIT). Anything requiring the trail machinery — OPTIONAL null-extension, path
/// variables, variable-length, ORDER BY (`Sort`/`TopK`), `Skip`, `Unwind`, DISTINCT, aggregation,
/// or a `WITH` re-match (a second `ScanPattern`) — makes this return `false`, so those plans still
/// reach the variable-path compiler unchanged.
fn plan_is_plain_streamable_read(plan: &PhysicalPlan) -> bool {
    if !plan.read_only || plan.at_time.is_some() || !plan.unions.is_empty() {
        return false;
    }
    let mut scan_patterns = 0usize;
    let mut projections = 0usize;
    for operator in &plan.operators {
        match operator {
            PhysicalOperator::CardinalityCheckpoint { .. }
            | PhysicalOperator::Filter(_)
            | PhysicalOperator::Limit(_) => {}
            PhysicalOperator::ScanPattern {
                optional, pattern, ..
            } => {
                let streamable_pattern = !*optional
                    && pattern.variable.is_none()
                    && pattern.selector == PathSelector::All
                    && pattern.mode == PathMode::DifferentRelationships
                    && pattern.steps.len() == 1
                    && pattern.steps.iter().all(|step| {
                        !step.relationship.variable_length
                            && step.relationship.min_hops.is_none()
                            && step.relationship.max_hops.is_none()
                            && step.relationship.properties.is_empty()
                            && step.relationship.direction != Direction::Undirected
                            && step.node.variable.is_some()
                    });
                if !streamable_pattern {
                    return false;
                }
                scan_patterns += 1;
            }
            PhysicalOperator::Project { projection, .. } => {
                if projection.distinct
                    || projection.items.iter().any(|item| {
                        contains_aggregate(&item.expression)
                            // A `List`/`Map` literal constructs an entity container per row. The
                            // streaming scan/expand executors emit plain per-row values (node,
                            // relationship, property, scalar) and cannot build a container, so a
                            // container projection must reach the variable-path compiler instead —
                            // its OneHopEntityList / OneHopEntityMap outputs seal `RETURN [n,r,m]`
                            // and `RETURN {a: n, b: r, c: m}`. Left here it was mis-routed to the
                            // streaming path, which declined it, and the read fell back to host.
                            || matches!(
                                &item.expression,
                                Expression::List(_) | Expression::Map(_)
                            )
                    })
                {
                    return false;
                }
                projections += 1;
            }
            _ => return false,
        }
    }
    scan_patterns == 1 && projections >= 1
}

/// Counts the projection stages that aggregate.
///
/// The resident segmented compiler emits one program per plan, and the accelerator's segmented
/// graph program can lower only one aggregating stage inside it. A second one — an aggregate over
/// the result of an aggregate, which is how most distribution questions are written — was rejected
/// once the program reached the backend, and that rejection is a hard error rather than a decline,
/// so the query failed instead of falling through to a path that can answer it. Counting the stages
/// here lets the plan decline before a request is built. The CPU resident path lowers a second
/// stage and keeps it.
fn aggregating_projection_count(plan: &PhysicalPlan) -> usize {
    plan.operators
        .iter()
        .chain(plan.unions.iter().flat_map(|(_, operators)| operators))
        .filter(|operator| match operator {
            PhysicalOperator::Project { projection, .. } => projection
                .items
                .iter()
                .any(|item| contains_aggregate(&item.expression)),
            _ => false,
        })
        .count()
}

/// True when the plan reads a property that is declared temporal.
///
/// A declared temporal property has two stored representations: the canonical column, which stops
/// being written once the declaration exists, and the sample series, which is what every write
/// after the declaration goes to. Only the second is the current value. The resident compilers
/// project the canonical column directly, so a plan that reads such a property natively answers
/// with a value frozen at its declaration while the same read on the host path answers from the
/// series — the same expression giving two answers depending on which access path the planner
/// chose. Declining here keeps that read on the one path that resolves it.
fn plan_reads_declared_temporal_property(
    plan: &PhysicalPlan,
    context: &ExecutionContext<'_>,
) -> bool {
    let Some(temporal) = context.temporal else {
        return false;
    };
    if temporal.is_empty() {
        return false;
    }
    let declared = |name: &str| {
        context
            .binding_catalog
            .property(name)
            .is_some_and(|property| temporal.declares_property(property))
    };
    let reads = |expression: &Expression| reads_property_where(expression, &declared);
    plan.operators
        .iter()
        .chain(plan.unions.iter().flat_map(|(_, operators)| operators))
        .any(|operator| match operator {
            PhysicalOperator::Filter(expression)
            | PhysicalOperator::Unwind { expression, .. }
            | PhysicalOperator::Skip(expression)
            | PhysicalOperator::Limit(expression) => reads(expression),
            PhysicalOperator::Delete { expressions, .. } => expressions.iter().any(reads),
            PhysicalOperator::Project { projection, .. } => {
                projection.items.iter().any(|item| reads(&item.expression))
            }
            PhysicalOperator::Sort(items) | PhysicalOperator::TopK { items, .. } => {
                items.iter().any(|item| reads(&item.expression))
            }
            _ => false,
        })
}

fn plan_contains_pattern_comprehension(plan: &PhysicalPlan) -> bool {
    plan.operators
        .iter()
        .chain(plan.unions.iter().flat_map(|(_, operators)| operators))
        .any(|operator| match operator {
            PhysicalOperator::Filter(expression)
            | PhysicalOperator::Unwind { expression, .. }
            | PhysicalOperator::Skip(expression)
            | PhysicalOperator::Limit(expression) => contains_pattern_comprehension(expression),
            PhysicalOperator::Delete { expressions, .. } => {
                expressions.iter().any(contains_pattern_comprehension)
            }
            PhysicalOperator::Project { projection, .. } => projection
                .items
                .iter()
                .any(|item| contains_pattern_comprehension(&item.expression)),
            PhysicalOperator::Sort(items) | PhysicalOperator::TopK { items, .. } => items
                .iter()
                .any(|item| contains_pattern_comprehension(&item.expression)),
            _ => false,
        })
}

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
enum ResidentPatternCountExpressionMode {
    Count,
    Exists,
    NonNullListCount,
}

#[derive(Clone, Debug, PartialEq, Eq)]
struct ResidentPatternCountExpressionShape {
    mode: ResidentPatternCountExpressionMode,
    direction: ResidentDirection,
    relationship_type_names: Vec<String>,
}

#[derive(Clone, Debug, PartialEq, Eq)]
enum ResidentPatternCountProjection {
    Count {
        output_name: String,
    },
    NonNullListCount {
        output_name: String,
    },
    ExistsWithNode {
        node_output_name: String,
        boolean_output_name: String,
    },
}

#[derive(Clone, Debug, PartialEq, Eq)]
struct CompiledResidentPatternCountPlan {
    request: ResidentPatternCountRequest,
    outer_variable: String,
    projection: ResidentPatternCountProjection,
}

/// Decode only the List6 one-hop size scalar and the Pattern2 [6] non-null-list aggregate. In
/// particular, this does not admit a general pattern-comprehension list, an inner predicate,
/// endpoint constraints, or variable-length traversal. The aggregate form additionally requires
/// one named path projected unchanged through one typed outgoing hop.
fn resident_pattern_count_expression_shape(
    expression: &Expression,
    outer_variable: &str,
) -> Option<ResidentPatternCountExpressionShape> {
    if let Expression::Function {
        name,
        distinct: false,
        arguments,
    } = expression
        && matches!(name.as_slice(), [name] if name.eq_ignore_ascii_case("count"))
        && let [comprehension] = arguments.as_slice()
        && let Some((pattern, predicate, projection)) = comprehension.pattern_comprehension_parts()
        && let Some(path_variable) = pattern.variable.as_deref()
        && let [step] = pattern.steps.as_slice()
        && predicate.is_none()
        && matches!(projection, Expression::Variable(variable) if variable == path_variable)
        && pattern.selector == PathSelector::All
        && pattern.mode == PathMode::DifferentRelationships
        && pattern.start.variable.as_deref() == Some(outer_variable)
        && pattern.start.labels.is_empty()
        && !pattern.start.property_predicate_present
        && pattern.start.properties.is_empty()
        && step.relationship.variable.is_none()
        && !step.relationship.variable_length
        && step.relationship.min_hops.is_none()
        && step.relationship.max_hops.is_none()
        && step.relationship.types.len() == 1
        && step.relationship.properties.is_empty()
        && step.relationship.direction == Direction::Outgoing
        && step.node.variable.is_none()
        && step.node.labels.is_empty()
        && !step.node.property_predicate_present
        && step.node.properties.is_empty()
    {
        return Some(ResidentPatternCountExpressionShape {
            mode: ResidentPatternCountExpressionMode::NonNullListCount,
            direction: ResidentDirection::Outgoing,
            relationship_type_names: step.relationship.types.clone(),
        });
    }

    let (size_expression, mode) = match expression {
        Expression::Binary {
            left,
            operation: BinaryOperator::Greater,
            right,
        } if matches!(right.as_ref(), Expression::Literal(ScalarValue::Integer(0))) => {
            (left.as_ref(), ResidentPatternCountExpressionMode::Exists)
        }
        _ => (expression, ResidentPatternCountExpressionMode::Count),
    };
    let Expression::Function {
        name,
        distinct: false,
        arguments,
    } = size_expression
    else {
        return None;
    };
    let [function_name] = name.as_slice() else {
        return None;
    };
    let [comprehension] = arguments.as_slice() else {
        return None;
    };
    if !function_name.eq_ignore_ascii_case("size") {
        return None;
    }
    let (pattern, predicate, projection) = comprehension.pattern_comprehension_parts()?;
    let [step] = pattern.steps.as_slice() else {
        return None;
    };
    if predicate.is_some()
        || !matches!(projection, Expression::Literal(ScalarValue::Integer(1)))
        || pattern.variable.is_some()
        || pattern.selector != PathSelector::All
        || pattern.mode != PathMode::DifferentRelationships
        || pattern.start.variable.as_deref() != Some(outer_variable)
        || !pattern.start.labels.is_empty()
        || pattern.start.property_predicate_present
        || !pattern.start.properties.is_empty()
        || step.relationship.variable.is_some()
        || step.relationship.variable_length
        || step.relationship.min_hops.is_some()
        || step.relationship.max_hops.is_some()
        || !step.relationship.properties.is_empty()
        || step.node.variable.is_some()
        || !step.node.labels.is_empty()
        || step.node.property_predicate_present
        || !step.node.properties.is_empty()
    {
        return None;
    }
    let direction = match step.relationship.direction {
        Direction::Outgoing => ResidentDirection::Outgoing,
        Direction::Incoming => ResidentDirection::Incoming,
        Direction::Undirected => ResidentDirection::Undirected,
    };
    // List6 [7] is the node-plus-existence undirected shape. List6 [8]-[10] are outgoing integer
    // counts. Keeping those two forms distinct prevents this narrow route from becoming a
    // general comparison compiler around pattern comprehensions.
    if (mode == ResidentPatternCountExpressionMode::Exists
        && (direction != ResidentDirection::Undirected || !step.relationship.types.is_empty()))
        || (mode == ResidentPatternCountExpressionMode::Count
            && direction != ResidentDirection::Outgoing)
    {
        return None;
    }
    Some(ResidentPatternCountExpressionShape {
        mode,
        direction,
        relationship_type_names: step.relationship.types.clone(),
    })
}

/// Admit only the complete List6 [7]-[10] or Pattern2 [6] physical pipeline. The labelled scan,
/// one-hop traversal, zero-preserving per-parent aggregation, and final aligned row publication
/// all stay behind one generation-fenced backend call. Pattern2 counts the retained parent rows,
/// because each pattern-comprehension value is a non-null list even when its path count is zero.
fn compile_resident_pattern_count_plan(
    plan: &PhysicalPlan,
    context: &ExecutionContext<'_>,
) -> Result<Option<CompiledResidentPatternCountPlan>> {
    if !plan.read_only
        || plan.at_time.is_some()
        || !plan.unions.is_empty()
        || !context.prior_graph_mutations.is_empty()
        || !context.prior_temporal_mutations.is_empty()
    {
        return Ok(None);
    }
    let Some(PhysicalOperator::ScanPattern {
        optional: false,
        pattern,
        access,
        ..
    }) = plan.operators.first()
    else {
        return Ok(None);
    };
    let Some(outer_variable) = pattern.start.variable.as_ref() else {
        return Ok(None);
    };
    let [start_label_name] = pattern.start.labels.as_slice() else {
        return Ok(None);
    };
    if pattern.variable.is_some()
        || pattern.selector != PathSelector::All
        || pattern.mode != PathMode::DifferentRelationships
        || pattern.start.property_predicate_present
        || !pattern.start.properties.is_empty()
        || !pattern.steps.is_empty()
        || !matches!(access, ScanAccessPath::Label { label } if label == start_label_name)
    {
        return Ok(None);
    }

    let mut cursor = 1_usize;
    if matches!(
        plan.operators.get(cursor),
        Some(PhysicalOperator::CardinalityCheckpoint { .. })
    ) {
        cursor += 1;
    }
    let Some(PhysicalOperator::Project {
        keep_scope: false,
        projection,
    }) = plan.operators.get(cursor)
    else {
        return Ok(None);
    };
    cursor += 1;
    if cursor != plan.operators.len() || projection.distinct {
        return Ok(None);
    }

    let (shape, projection) = match projection.items.as_slice() {
        [item] => {
            let Some(shape) =
                resident_pattern_count_expression_shape(&item.expression, outer_variable)
            else {
                return Ok(None);
            };
            let output_name = item.column_name(0);
            let projection = match shape.mode {
                ResidentPatternCountExpressionMode::Count => {
                    ResidentPatternCountProjection::Count { output_name }
                }
                ResidentPatternCountExpressionMode::NonNullListCount => {
                    ResidentPatternCountProjection::NonNullListCount { output_name }
                }
                ResidentPatternCountExpressionMode::Exists => return Ok(None),
            };
            (shape, projection)
        }
        [node_item, boolean_item]
            if matches!(
                &node_item.expression,
                Expression::Variable(variable) if variable == outer_variable
            ) =>
        {
            let Some(shape) =
                resident_pattern_count_expression_shape(&boolean_item.expression, outer_variable)
            else {
                return Ok(None);
            };
            if shape.mode != ResidentPatternCountExpressionMode::Exists {
                return Ok(None);
            }
            (
                shape,
                ResidentPatternCountProjection::ExistsWithNode {
                    node_output_name: node_item.column_name(0),
                    boolean_output_name: boolean_item.column_name(1),
                },
            )
        }
        _ => return Ok(None),
    };

    let node_slots = context.graph.node_slot_count();
    let edge_slots = context.graph.edge_slot_count();
    if node_slots > u32::MAX as usize || edge_slots > u32::MAX as usize {
        return Err(Error::new(
            ErrorCode::GpuAdmissionFailure,
            "resident pattern count exceeds physical resident-row addressing",
        ));
    }
    let start_labels = context
        .binding_catalog
        .label(start_label_name)
        .map_or(ResidentPatternCountStartLabels::Never, |label| {
            ResidentPatternCountStartLabels::Known(vec![label])
        });
    let relationship_types = if shape.relationship_type_names.is_empty() {
        ResidentPatternRelationshipTypes::Any
    } else {
        let mut known = shape
            .relationship_type_names
            .iter()
            .filter_map(|name| context.binding_catalog.relationship_type(name))
            .collect::<Vec<_>>();
        known.sort_unstable();
        known.dedup();
        if known.is_empty() {
            ResidentPatternRelationshipTypes::Never
        } else {
            ResidentPatternRelationshipTypes::Known(known)
        }
    };
    let execution = fresh_resident_execution_id();
    let request = ResidentPatternCountRequest {
        project: context.project_id,
        expected_bookmark: context.bookmark,
        expected_graph_revision: context.graph.revision(),
        expected_layout_version: context.graph.layout_version(),
        layers: plan.read_layers,
        node_slots,
        edge_slots,
        start_labels,
        direction: shape.direction,
        relationship_types,
        execution,
        scan_obligation: ResidentExecutionObligation {
            id: 1,
            kind: ResidentObligationKind::PatternScan,
            scope: ResidentObligationScope::PatternScan,
        },
        traversal_obligation: ResidentExecutionObligation {
            id: 2,
            kind: ResidentObligationKind::PatternTraversal,
            scope: ResidentObligationScope::PatternLeaf(0),
        },
        final_obligation: ResidentExecutionObligation {
            id: 3,
            kind: ResidentObligationKind::PatternFilter,
            scope: ResidentObligationScope::PatternFinal,
        },
        max_output_rows: if matches!(
            &projection,
            ResidentPatternCountProjection::NonNullListCount { .. }
        ) {
            node_slots
        } else {
            context.max_result_rows.min(node_slots)
        },
    };
    request.validate()?;
    Ok(Some(CompiledResidentPatternCountPlan {
        request,
        outer_variable: outer_variable.clone(),
        projection,
    }))
}

#[derive(Clone, Debug, PartialEq, Eq)]
struct CompiledResidentPatternPredicatePlan {
    request: ResidentPatternPredicateRequest,
    output_name: String,
}

#[derive(Clone, Debug, PartialEq, Eq)]
struct CompiledResidentPatternPairPredicatePlan {
    request: ResidentPatternPairPredicateRequest,
    n_variable: String,
    m_variable: String,
    n_output_name: String,
    m_output_name: String,
}

/// Admits only the complete `MATCH (n) WHERE <Pattern1> RETURN n` pipeline. Once this returns a
/// plan, execution owns the whole query and every later failure must propagate rather than fall
/// through to a narrower resident route or the host row executor.
fn compile_resident_pattern_predicate_plan(
    plan: &PhysicalPlan,
    context: &ExecutionContext<'_>,
) -> Result<Option<CompiledResidentPatternPredicatePlan>> {
    if !plan.read_only
        || plan.at_time.is_some()
        || !plan.unions.is_empty()
        || !context.prior_graph_mutations.is_empty()
        || !context.prior_temporal_mutations.is_empty()
    {
        return Ok(None);
    }

    let Some(PhysicalOperator::ScanPattern {
        optional: false,
        pattern,
        access: ScanAccessPath::AllNodes,
        ..
    }) = plan.operators.first()
    else {
        return Ok(None);
    };
    let Some(outer_variable) = pattern.start.variable.as_ref() else {
        return Ok(None);
    };
    if pattern.variable.is_some()
        || pattern.selector != PathSelector::All
        || pattern.mode != PathMode::DifferentRelationships
        || !pattern.start.labels.is_empty()
        || !pattern.start.properties.is_empty()
        || !pattern.steps.is_empty()
    {
        return Ok(None);
    }

    let mut cursor = 1_usize;
    if matches!(
        plan.operators.get(cursor),
        Some(PhysicalOperator::CardinalityCheckpoint { .. })
    ) {
        cursor += 1;
    }

    let filter_start = cursor;
    let mut combined_filter = None;
    while let Some(PhysicalOperator::Filter(expression)) = plan.operators.get(cursor) {
        combined_filter = Some(match combined_filter {
            None => expression.clone(),
            Some(left) => Expression::Binary {
                left: Box::new(left),
                operation: BinaryOperator::And,
                right: Box::new(expression.clone()),
            },
        });
        cursor += 1;
    }
    if cursor == filter_start {
        return Ok(None);
    }

    let Some(PhysicalOperator::Project {
        keep_scope: false,
        projection,
    }) = plan.operators.get(cursor)
    else {
        return Ok(None);
    };
    cursor += 1;
    let [item] = projection.items.as_slice() else {
        return Ok(None);
    };
    if projection.distinct
        || !matches!(&item.expression, Expression::Variable(variable) if variable == outer_variable)
        || item
            .alias
            .as_ref()
            .is_some_and(|alias| alias != outer_variable)
        || cursor != plan.operators.len()
    {
        return Ok(None);
    }

    let node_slots = context.graph.node_slot_count();
    if node_slots > u32::MAX as usize {
        return Err(Error::new(
            ErrorCode::GpuAdmissionFailure,
            "resident Pattern1 visible-node scan exceeds its physical row-address width",
        ));
    }

    let execution = fresh_resident_execution_id();
    let scan_obligation = ResidentExecutionObligation {
        id: 1,
        kind: ResidentObligationKind::PatternScan,
        scope: ResidentObligationScope::PatternScan,
    };
    let Some(compiled) = compile_resident_pattern_predicate_expression(
        combined_filter
            .as_ref()
            .ok_or_else(|| Error::internal("resident Pattern1 filter disappeared"))?,
        outer_variable,
        context.binding_catalog,
        execution,
        2,
    )?
    else {
        return Ok(None);
    };
    if compiled.outer_variable != *outer_variable {
        return Err(Error::internal(
            "resident Pattern1 compiler changed the outer node binding",
        ));
    }

    let request = ResidentPatternPredicateRequest {
        project: context.project_id,
        expected_bookmark: context.bookmark,
        expected_graph_revision: context.graph.revision(),
        expected_layout_version: context.graph.layout_version(),
        layers: plan.read_layers,
        input: ResidentPatternPredicateInput::VisibleNodeScan {
            node_slots,
            obligation: scan_obligation,
        },
        program: compiled.program,
        max_output_rows: context.max_result_rows.min(node_slots),
    };
    request.validate()?;
    Ok(Some(CompiledResidentPatternPredicatePlan {
        request,
        output_name: item.column_name(0),
    }))
}

/// Admits only the complete
/// `MATCH (n), (m) WHERE (n)-[...]->(m) RETURN n, m` pipeline. Both all-node scans and their
/// row-major Cartesian domain remain backend-owned. Physical scan reordering is harmless because
/// both scans have the same visible-node domain; the compiler restores the predicate's semantic
/// start/end orientation before assigning output columns.
fn compile_resident_pattern_pair_predicate_plan(
    plan: &PhysicalPlan,
    context: &ExecutionContext<'_>,
) -> Result<Option<CompiledResidentPatternPairPredicatePlan>> {
    if !plan.read_only
        || plan.at_time.is_some()
        || !plan.unions.is_empty()
        || !context.prior_graph_mutations.is_empty()
        || !context.prior_temporal_mutations.is_empty()
    {
        return Ok(None);
    }

    let Some(first_scan) = plan.operators.first() else {
        return Ok(None);
    };
    if !matches!(first_scan, PhysicalOperator::ScanPattern { .. }) {
        return Ok(None);
    }
    let mut cursor = 1_usize;
    if matches!(
        plan.operators.get(cursor),
        Some(PhysicalOperator::CardinalityCheckpoint { .. })
    ) {
        cursor += 1;
    }
    let Some(second_scan) = plan.operators.get(cursor) else {
        return Ok(None);
    };
    if !matches!(second_scan, PhysicalOperator::ScanPattern { .. }) {
        return Ok(None);
    }
    cursor += 1;
    if matches!(
        plan.operators.get(cursor),
        Some(PhysicalOperator::CardinalityCheckpoint { .. })
    ) {
        cursor += 1;
    }
    let Some(filter) = plan.operators.get(cursor) else {
        return Ok(None);
    };
    if !matches!(filter, PhysicalOperator::Filter(_)) {
        return Ok(None);
    }
    cursor += 1;
    let Some(projection_operator) = plan.operators.get(cursor) else {
        return Ok(None);
    };
    cursor += 1;
    if cursor != plan.operators.len() {
        return Ok(None);
    }

    let execution = fresh_resident_execution_id();
    let compiled = match compile_resident_pattern_pair_predicate_components(
        first_scan,
        second_scan,
        filter,
        projection_operator,
        context.binding_catalog,
        execution,
        1,
    )? {
        Some(compiled) => compiled,
        None => {
            let Some(compiled) = compile_resident_pattern_pair_predicate_components(
                second_scan,
                first_scan,
                filter,
                projection_operator,
                context.binding_catalog,
                execution,
                1,
            )?
            else {
                return Ok(None);
            };
            compiled
        }
    };
    let PhysicalOperator::Project { projection, .. } = projection_operator else {
        return Err(Error::internal(
            "resident paired Pattern1 compiler accepted a non-projecting plan",
        ));
    };
    let [n_item, m_item] = projection.items.as_slice() else {
        return Err(Error::internal(
            "resident paired Pattern1 compiler accepted an invalid projection width",
        ));
    };

    let node_slots = context.graph.node_slot_count();
    if node_slots > RESIDENT_PATTERN_PAIR_MAX_NODE_SLOTS {
        return Err(Error::new(
            ErrorCode::GpuAdmissionFailure,
            "resident paired Pattern1 visible-node domain exceeds its bounded native frontier",
        ));
    }
    let pair_domain = node_slots.checked_mul(node_slots).ok_or_else(|| {
        Error::new(
            ErrorCode::GpuAdmissionFailure,
            "resident paired Pattern1 Cartesian domain overflow",
        )
    })?;
    let CompiledResidentPatternPairPredicateProgram {
        n_variable,
        m_variable,
        n_scan_obligation,
        m_scan_obligation,
        cartesian_obligation,
        program,
    } = compiled;
    let request = ResidentPatternPairPredicateRequest {
        project: context.project_id,
        expected_bookmark: context.bookmark,
        expected_graph_revision: context.graph.revision(),
        expected_layout_version: context.graph.layout_version(),
        layers: plan.read_layers,
        input: ResidentPatternPairVisibleNodeScans {
            node_slots,
            n_obligation: n_scan_obligation,
            m_obligation: m_scan_obligation,
            cartesian_obligation,
        },
        program,
        max_output_pairs: context.max_result_rows.min(pair_domain),
    };
    request.validate()?;
    Ok(Some(CompiledResidentPatternPairPredicatePlan {
        request,
        n_variable,
        m_variable,
        n_output_name: n_item.column_name(0),
        m_output_name: m_item.column_name(1),
    }))
}

fn fresh_resident_execution_id() -> ResidentExecutionId {
    let mut random = rand::rng();
    loop {
        let execution = ResidentExecutionId {
            high: random.random(),
            low: random.random(),
        };
        if execution.high != 0 || execution.low != 0 {
            return execution;
        }
    }
}

/// Removes one execution-scoped procedure only when its immutable relation is the relational
/// identity: one row and zero columns. An in-query CALL of that shape preserves every incoming row
/// without adding bindings, filtering, reordering, or multiplying it, so the surrounding native
/// graph plan remains complete after the operator is erased.
fn erase_in_query_unit_procedure(
    plan: &PhysicalPlan,
    procedures: &ProcedureCatalog,
    parameters: &BTreeMap<String, ResultValue>,
) -> Result<Option<PhysicalPlan>> {
    if !plan.unions.is_empty() {
        return Ok(None);
    }

    let mut call_index = None;
    for (index, operator) in plan.operators.iter().enumerate() {
        if !matches!(operator, PhysicalOperator::BuiltinProcedure(_)) {
            continue;
        }
        if call_index.replace(index).is_some() {
            return Ok(None);
        }
    }
    let Some(call_index) = call_index else {
        return Ok(None);
    };
    let PhysicalOperator::BuiltinProcedure(call) = &plan.operators[call_index] else {
        return Err(Error::internal(
            "unit procedure erasure selected a non-procedure operator",
        ));
    };

    // Keep the accepted surface deliberately exact. Validation below proves the registered
    // relation, while these shape checks ensure erasure never hides argument or YIELD semantics.
    if call.standalone
        || call.argument_mode != CallArgumentMode::Explicit
        || !call.arguments.is_empty()
        || call.yield_mode != CallYieldMode::Omitted
        || !call.yields.is_empty()
    {
        return Ok(None);
    }
    let ResolvedProcedure::ExecutionScoped(procedure) =
        validate_call(call, Some(procedures), Some(parameters))?
    else {
        return Ok(None);
    };
    if !procedure.inputs().is_empty()
        || !procedure.outputs().is_empty()
        || procedure.row_count() != 1
    {
        return Ok(None);
    }

    let mut erased = plan.clone();
    erased.operators.remove(call_index);
    Ok(Some(erased))
}

#[cfg(test)]
mod unit_procedure_erasure_tests {
    use super::*;
    use crate::graph::LayerMask;

    fn call(name: &str) -> CallClause {
        CallClause {
            name: name.split('.').map(str::to_owned).collect(),
            argument_mode: CallArgumentMode::Explicit,
            arguments: Vec::new(),
            yield_mode: CallYieldMode::Omitted,
            yields: Vec::new(),
            standalone: false,
        }
    }

    fn plan(call: CallClause) -> PhysicalPlan {
        PhysicalPlan {
            project: None,
            read_layers: LayerMask::all(),
            write_layer: Layer::Observed,
            at_time: None,
            operators: vec![
                PhysicalOperator::Finish,
                PhysicalOperator::BuiltinProcedure(call),
            ],
            unions: Vec::new(),
            read_only: true,
            dependencies: Vec::new(),
        }
    }

    fn catalog(definition: ProcedureDefinition) -> Result<ProcedureCatalog> {
        let mut catalog = ProcedureCatalog::default();
        catalog.register(definition)?;
        Ok(catalog)
    }

    #[test]
    fn erases_only_the_validated_one_row_zero_column_relation() -> Result<()> {
        let procedures = catalog(ProcedureDefinition::new_with_row_count(
            "test.unit",
            Vec::new(),
            Vec::new(),
            1,
            Vec::new(),
        )?)?;
        let erased =
            erase_in_query_unit_procedure(&plan(call("test.unit")), &procedures, &BTreeMap::new())?
                .ok_or_else(|| Error::internal("validated unit relation was not erased"))?;
        assert_eq!(erased.operators.len(), 1);
        assert!(matches!(erased.operators[0], PhysicalOperator::Finish));
        assert!(erased.unions.is_empty());
        Ok(())
    }

    #[test]
    fn refuses_non_unit_cardinality_builtin_multiple_and_union_shapes() -> Result<()> {
        for row_count in [0, 2] {
            let procedures = catalog(ProcedureDefinition::new_with_row_count(
                "test.not_unit",
                Vec::new(),
                Vec::new(),
                row_count,
                Vec::new(),
            )?)?;
            assert!(
                erase_in_query_unit_procedure(
                    &plan(call("test.not_unit")),
                    &procedures,
                    &BTreeMap::new(),
                )?
                .is_none(),
                "zero-column cardinality {row_count} is not the unit relation"
            );
        }

        assert!(
            erase_in_query_unit_procedure(
                &plan(call("graph.trianglecount")),
                &ProcedureCatalog::default(),
                &BTreeMap::new(),
            )?
            .is_none(),
            "a built-in procedure is never an immutable execution-scoped unit table"
        );

        let procedures = catalog(ProcedureDefinition::new(
            "test.unit",
            Vec::new(),
            Vec::new(),
            Vec::new(),
        )?)?;
        let mut multiple = plan(call("test.unit"));
        multiple
            .operators
            .push(PhysicalOperator::BuiltinProcedure(call("test.unit")));
        assert!(erase_in_query_unit_procedure(&multiple, &procedures, &BTreeMap::new())?.is_none());

        let mut union = plan(call("test.unit"));
        union.unions.push((false, vec![PhysicalOperator::Finish]));
        assert!(erase_in_query_unit_procedure(&union, &procedures, &BTreeMap::new())?.is_none());
        Ok(())
    }

    #[test]
    fn refuses_argument_yield_and_standalone_semantics_before_erasure() -> Result<()> {
        let procedures = catalog(ProcedureDefinition::new(
            "test.unit",
            Vec::new(),
            Vec::new(),
            Vec::new(),
        )?)?;
        let mut shapes = Vec::new();

        let mut implicit = call("test.unit");
        implicit.argument_mode = CallArgumentMode::Implicit;
        shapes.push(implicit);

        let mut argument = call("test.unit");
        argument
            .arguments
            .push(Expression::Literal(ScalarValue::Integer(1)));
        shapes.push(argument);

        let mut yielded = call("test.unit");
        yielded.yield_mode = CallYieldMode::All;
        shapes.push(yielded);

        let mut standalone = call("test.unit");
        standalone.standalone = true;
        shapes.push(standalone);

        for shape in shapes {
            assert!(
                erase_in_query_unit_procedure(&plan(shape), &procedures, &BTreeMap::new(),)?
                    .is_none()
            );
        }
        Ok(())
    }
}

fn render_resident_node_labels(value: ResultValue, nullable: bool) -> Result<ResultValue> {
    match value {
        ResultValue::Node(node) => Ok(ResultValue::List(
            node.labels.into_iter().map(string_value).collect(),
        )),
        ResultValue::Scalar(ScalarValue::Null) if nullable => {
            Ok(ResultValue::Scalar(ScalarValue::Null))
        }
        _ => Err(Error::new(
            ErrorCode::CorruptStorage,
            "validated resident labels projection did not publish its proven node shape",
        )),
    }
}

fn render_resident_non_null_node_path(value: ResultValue) -> Result<ResultValue> {
    match value {
        ResultValue::Node(node) => Ok(ResultValue::Path {
            nodes: vec![node],
            relationships: Vec::new(),
        }),
        _ => Err(Error::new(
            ErrorCode::CorruptStorage,
            "validated resident node-only path projection did not publish its proven node shape",
        )),
    }
}

fn render_resident_node_has_property(value: ResultValue, key: &str) -> Result<ResultValue> {
    match value {
        ResultValue::Node(node) => Ok(ResultValue::Scalar(ScalarValue::Boolean(
            node.properties.contains_key(key),
        ))),
        _ => Err(Error::new(
            ErrorCode::CorruptStorage,
            "validated resident keys membership projection did not publish its proven node shape",
        )),
    }
}

fn render_resident_entity_properties(
    value: ResultValue,
    expect_relationship: bool,
    nullable: bool,
) -> Result<ResultValue> {
    match value {
        ResultValue::Node(node) if !expect_relationship => property_map(&node.properties),
        ResultValue::Relationship(edge) if expect_relationship => property_map(&edge.properties),
        ResultValue::Scalar(ScalarValue::Null) if nullable => {
            Ok(ResultValue::Scalar(ScalarValue::Null))
        }
        _ => Err(Error::new(
            ErrorCode::CorruptStorage,
            "validated resident properties projection did not publish its proven entity shape",
        )),
    }
}

fn resident_render_column_type(render: &CompiledResidentOutputRender) -> ColumnType {
    match render {
        CompiledResidentOutputRender::NonNullNodePath => ColumnType::Path,
        CompiledResidentOutputRender::NonNullNodeLabels
        | CompiledResidentOutputRender::NullableNodeLabels => ColumnType::List,
        CompiledResidentOutputRender::NonNullNodeHasProperty { .. } => ColumnType::Boolean,
        CompiledResidentOutputRender::NonNullNodeProperties
        | CompiledResidentOutputRender::NullableNodeProperties
        | CompiledResidentOutputRender::NonNullRelationshipProperties
        | CompiledResidentOutputRender::NullableRelationshipProperties => ColumnType::Map,
    }
}

fn render_resident_value(
    value: ResultValue,
    render: &CompiledResidentOutputRender,
) -> Result<ResultValue> {
    match render {
        CompiledResidentOutputRender::NonNullNodePath => render_resident_non_null_node_path(value),
        CompiledResidentOutputRender::NonNullNodeLabels => {
            render_resident_node_labels(value, false)
        }
        CompiledResidentOutputRender::NullableNodeLabels => {
            render_resident_node_labels(value, true)
        }
        CompiledResidentOutputRender::NonNullNodeHasProperty { key } => {
            render_resident_node_has_property(value, key)
        }
        CompiledResidentOutputRender::NonNullNodeProperties => {
            render_resident_entity_properties(value, false, false)
        }
        CompiledResidentOutputRender::NullableNodeProperties => {
            render_resident_entity_properties(value, false, true)
        }
        CompiledResidentOutputRender::NonNullRelationshipProperties => {
            render_resident_entity_properties(value, true, false)
        }
        CompiledResidentOutputRender::NullableRelationshipProperties => {
            render_resident_entity_properties(value, true, true)
        }
    }
}

fn render_resident_output_schema(
    schema: &mut [(String, ColumnType)],
    output: &CompiledResidentRenderedOutput,
) -> Result<()> {
    let Some((name, value_type)) = schema.get_mut(output.index) else {
        return Err(Error::new(
            ErrorCode::CorruptStorage,
            "validated resident rendered projection omitted its output schema",
        ));
    };
    if name != &output.name {
        return Err(Error::new(
            ErrorCode::CorruptStorage,
            "validated resident rendered projection changed its output name",
        ));
    }
    *value_type = resident_render_column_type(&output.render);
    Ok(())
}

fn render_resident_output_batch(
    batch: &mut ResultBatch,
    output: &CompiledResidentRenderedOutput,
) -> Result<()> {
    if !batch.validate() {
        return Err(Error::new(
            ErrorCode::CorruptStorage,
            "validated resident rendered projection received a malformed result batch",
        ));
    }
    let Some(column) = batch.columns.get_mut(output.index) else {
        return Err(Error::new(
            ErrorCode::CorruptStorage,
            "validated resident rendered projection omitted its output column",
        ));
    };
    if column.name != output.name {
        return Err(Error::new(
            ErrorCode::CorruptStorage,
            "validated resident rendered projection changed its output column name",
        ));
    }
    column.values = std::mem::take(&mut column.values)
        .into_iter()
        .map(|value| render_resident_value(value, &output.render))
        .collect::<Result<Vec<_>>>()?;
    column.value_type = resident_render_column_type(&output.render);
    Ok(())
}

fn render_resident_stream_item(
    item: &mut ExecutionStreamItem,
    outputs: &[CompiledResidentRenderedOutput],
) -> Result<()> {
    match item {
        ExecutionStreamItem::Schema(schema) => {
            for output in outputs {
                render_resident_output_schema(schema, output)?;
            }
        }
        ExecutionStreamItem::Batch(batch) => {
            for output in outputs {
                render_resident_output_batch(batch, output)?;
            }
        }
    }
    Ok(())
}

fn render_resident_execution_output(
    output: &mut ExecutionOutput,
    renders: &[CompiledResidentRenderedOutput],
) -> Result<()> {
    for render in renders {
        render_resident_output_schema(&mut output.result.schema, render)?;
        for batch in &mut output.result.batches {
            render_resident_output_batch(batch, render)?;
        }
    }
    Ok(())
}

fn execute_resident_plan(
    plan: &PhysicalPlan,
    context: &ExecutionContext<'_>,
    procedures: Option<&ProcedureCatalog>,
    stream: &mut Option<&mut dyn FnMut(ExecutionStreamItem) -> Result<()>>,
) -> Result<Option<ExecutionOutput>> {
    let Some(rendered) = compile_resident_node_labels_render(plan, context.binding_catalog) else {
        return execute_resident_plan_unrendered(plan, context, procedures, stream);
    };

    if let Some(emit) = stream.as_deref_mut() {
        let mut render_and_emit = |mut item: ExecutionStreamItem| {
            render_resident_stream_item(&mut item, &rendered.outputs)?;
            emit(item)
        };
        let mut rendered_stream: Option<&mut dyn FnMut(ExecutionStreamItem) -> Result<()>> =
            Some(&mut render_and_emit);
        let Some(mut output) = execute_resident_plan_unrendered(
            &rendered.plan,
            context,
            procedures,
            &mut rendered_stream,
        )?
        else {
            return Ok(None);
        };
        render_resident_execution_output(&mut output, &rendered.outputs)?;
        return Ok(Some(output));
    }

    let mut no_stream = None;
    let Some(mut output) =
        execute_resident_plan_unrendered(&rendered.plan, context, procedures, &mut no_stream)?
    else {
        return Ok(None);
    };
    render_resident_execution_output(&mut output, &rendered.outputs)?;
    Ok(Some(output))
}

/// Attempts the resident *grouping* aggregation path (the one `stdev`/`variance` already take) for a
/// plan the segmented-aggregation compiler would otherwise claim. Both are correct, but they scale
/// very differently: this path reduces a resident property column in place through
/// `execute_node_group_pipeline`, whereas the segmented compiler materializes a per-row cell matrix
/// and reduces that — ~30x slower at millions of rows. Routing `sum`/`avg`/`min`/`max`/`count` and
/// single-key group-bys here, ahead of the segmented dispatch, closes that gap while leaving every
/// shape this compiler declines (containers, distinct segmented kernels, non-integer keys) to the
/// segmented path untouched.
///
/// Returns `Ok(None)` — deferring to the segmented dispatch and the rest of the chain — whenever the
/// grouping compiler declines the plan, the plan is not an aggregation, or a projected column is not
/// a resident integer column. The gate mirrors the segmented dispatch's own residency preconditions.
fn try_execute_resident_grouping_aggregation(
    plan: &PhysicalPlan,
    backend: &dyn ExecutionBackend,
    context: &ExecutionContext<'_>,
    stream: &mut Option<&mut dyn FnMut(ExecutionStreamItem) -> Result<()>>,
) -> Result<Option<ExecutionOutput>> {
    if !context.prior_graph_mutations.is_empty()
        || !context.prior_temporal_mutations.is_empty()
        || backend.resident_bookmark(context.project_id) != Some(context.bookmark)
        || backend.resident_graph_revision(context.project_id) != Some(context.graph.revision())
    {
        return Ok(None);
    }
    let Some(mut compiled) = compile_resident(
        plan,
        context.project_id,
        context.binding_catalog,
        context.graph,
        context.temporal,
        &context.parameters,
        context.bookmark.index,
        context.max_result_rows,
    )?
    else {
        return Ok(None);
    };
    // Only intercept aggregations. Plain reads, expansions and temporal plans stay on the main
    // dispatch chain, which reaches the identical `compile_resident` call at its tail.
    if compiled.grouping.is_none() || compiled.temporal.is_some() {
        return Ok(None);
    }
    preserve_resident_repeated_endpoint_equality(plan, &mut compiled.request);
    // The resident group pipeline consumes integer columns; any non-integer projected property means
    // this fast path cannot answer the plan, so defer to the segmented path (identical check to the
    // tail `compile_resident` dispatch below).
    if compiled
        .request
        .predicates
        .iter()
        .any(|predicate| !context.graph.node_property_is_integer(predicate.property))
        || compiled
            .request
            .expansion
            .as_ref()
            .is_some_and(|expansion| {
                expansion
                    .end_predicates
                    .iter()
                    .any(|predicate| !context.graph.node_property_is_integer(predicate.property))
            })
        || compiled.request.orders.iter().any(|order| {
            !context.graph.node_property_is_integer(order.property)
                && !context.graph.node_property_is_boolean(order.property)
                && !context.graph.node_property_is_float(order.property)
                && !context.graph.node_property_is_string(order.property)
        })
        || compiled
            .grouping
            .iter()
            .chain(&compiled.additional_groupings)
            .any(|grouping| {
                grouping
                    .key
                    .into_iter()
                    .chain(grouping.value)
                    .any(|projection| !context.graph.node_property_is_integer(projection.property))
            })
        || compiled
            .request
            .property_null_projections
            .iter()
            .any(|projection| {
                projection
                    .property
                    .is_some_and(|property| !context.graph.node_property_is_integer(property))
            })
    {
        return Ok(None);
    }
    for output in &mut compiled.outputs {
        if let ResidentOutputSource::Integer(binding, property) = output.source
            && !context.graph.node_property_is_integer(property)
        {
            output.source = ResidentOutputSource::Property(binding, property);
        }
    }
    compiled
        .request
        .integer_projections
        .retain(|projection| context.graph.node_property_is_integer(projection.property));
    check_execution(context)?;
    let pinned = backend.pin_project(context.project_id)?;
    if pinned.resident_bookmark(context.project_id) != Some(context.bookmark)
        || pinned.resident_graph_revision(context.project_id) != Some(context.graph.revision())
    {
        return Err(Error::new(
            ErrorCode::GpuAdmissionFailure,
            "resident node pipeline backend does not own the requested canonical snapshot",
        ));
    }
    check_execution(context)?;
    execute_resident_group_plan(plan, &compiled, pinned.as_ref(), context, stream).map(Some)
}

fn execute_resident_plan_unrendered(
    plan: &PhysicalPlan,
    context: &ExecutionContext<'_>,
    procedures: Option<&ProcedureCatalog>,
    stream: &mut Option<&mut dyn FnMut(ExecutionStreamItem) -> Result<()>>,
) -> Result<Option<ExecutionOutput>> {
    let Some(backend) = context.backend else {
        return Ok(None);
    };
    // A plan that reads a declared temporal property, without itself being a temporal plan, must
    // stay on the host path: see `plan_reads_declared_temporal_property`. Plans that carry their
    // own time — a query-level `AT TIME`, or a `HISTORY`/`WINDOW` operator — already resolve the
    // series through compilers that know about it, and are left accelerated.
    if plan_temporal_mode(plan) == 0 && plan_reads_declared_temporal_property(plan, context) {
        return Ok(None);
    }
    // One aggregating stage per accelerated program: see `aggregating_projection_count`. The CPU
    // resident path lowers a second stage and is left to do so; only the accelerator's segmented
    // graph program cannot, and there the decline has to happen here rather than as an admission
    // failure raised after the request is already built.
    if backend.kind() != crate::execution::BackendKind::Cpu
        && aggregating_projection_count(plan) > 1
    {
        return Ok(None);
    }
    if let Some(compiled) = compile_resident_pattern_count_plan(plan, context)? {
        return execute_resident_pattern_count_plan(plan, &compiled, backend, context, stream)
            .map(Some);
    }
    if context.prior_graph_mutations.is_empty()
        && context.prior_temporal_mutations.is_empty()
        && backend.supports_native_variable_path()
        && let Some(compiled) = compile_resident_pattern_comprehension(
            plan,
            context.project_id,
            context.bookmark,
            context.binding_catalog,
            context.graph,
        )?
    {
        return execute_resident_pattern_comprehension_plan(
            plan, &compiled, backend, context, stream,
        )
        .map(Some);
    }
    // Pattern comprehensions are currently a CPU-reference expression. Do not allow a narrower
    // resident compiler to consume any shape outside the sealed compiler above and accidentally
    // claim that host-side correlated traversal or list construction was native GPU execution.
    if backend.kind() != crate::execution::BackendKind::Cpu
        && plan_contains_pattern_comprehension(plan)
    {
        return Ok(None);
    }
    if let Some(procedures) = procedures
        && let Some(compiled) =
            compile_resident_procedure_table(plan, procedures, &context.parameters)?
    {
        return execute_resident_procedure_table_plan(plan, &compiled, backend, context, stream)
            .map(Some);
    }
    if let Some(procedures) = procedures
        && let Some(erased) = erase_in_query_unit_procedure(plan, procedures, &context.parameters)?
    {
        // Recursion is bounded: the only procedure operator was removed, and no host procedure
        // execution is involved. The unchanged plan metadata still binds the resident read to the
        // same canonical graph snapshot and dependencies.
        return execute_resident_plan(&erased, context, None, stream);
    }
    // Execution-scoped relation procedures need their own native constant-table operator. Until
    // that exists, strict GPU execution must reject the complete plan instead of running CALL on
    // the host after a partially resident prefix.
    if procedures.is_some()
        && plan
            .operators
            .iter()
            .chain(plan.unions.iter().flat_map(|(_, branch)| branch))
            .any(|operator| matches!(operator, PhysicalOperator::BuiltinProcedure(_)))
    {
        return Ok(None);
    }
    if !plan.read_only {
        if !context.prior_graph_mutations.is_empty()
            || !context.prior_temporal_mutations.is_empty()
            || backend.resident_bookmark(context.project_id) != Some(context.bookmark)
            || backend.resident_graph_revision(context.project_id) != Some(context.graph.revision())
            || !resident_catalog_matches_canonical(context)
        {
            return Ok(None);
        }
        let mut random = rand::rng();
        let execution = loop {
            let execution = ResidentExecutionId {
                high: random.random(),
                low: random.random(),
            };
            if execution.high != 0 || execution.low != 0 {
                break execution;
            }
        };
        if let Some(compiled) = compile_resident_row_mutation(
            plan,
            context.project_id,
            context.binding_catalog,
            context.graph,
            &context.parameters,
            context.bookmark,
            execution,
            context.next_node_id,
            context.next_edge_id,
            context.max_result_rows,
        )? {
            return execute_resident_row_mutation_plan(plan, &compiled, backend, context, stream)
                .map(Some);
        }
        if backend.supports_native_create_node()
            && let Some(compiled) = compile_resident_create_nodes(
                plan,
                context.project_id,
                context.graph,
                &context.parameters,
                context.bookmark,
                execution,
                context.next_node_id,
            )?
        {
            return execute_resident_create_node_plan(plan, &compiled, backend, context, stream)
                .map(Some);
        }
        if let Some(compiled) = compile_resident_delete(
            plan,
            context.project_id,
            context.bookmark,
            context.binding_catalog,
            context.graph,
            &context.parameters,
            execution,
            context.max_result_rows,
        )? {
            return execute_resident_delete_plan(plan, &compiled, backend, context, stream)
                .map(Some);
        }
        let Some(compiled) = compile_resident_mutation(
            plan,
            context.project_id,
            context.binding_catalog,
            context.graph,
            &context.parameters,
            context.bookmark,
            execution,
            context.max_result_rows,
        )?
        else {
            return Ok(None);
        };
        return execute_resident_mutation_plan(plan, &compiled, backend, context, stream).map(Some);
    }
    if let Some(compiled) = compile_resident_pattern_pair_predicate_plan(plan, context)? {
        return execute_resident_pattern_pair_predicate_plan(
            plan, &compiled, backend, context, stream,
        )
        .map(Some);
    }
    if let Some(compiled) = compile_resident_pattern_predicate_plan(plan, context)? {
        return execute_resident_pattern_predicate_plan(plan, &compiled, backend, context, stream)
            .map(Some);
    }
    if backend.supports_native_quantifier_program()
        && context.prior_graph_mutations.is_empty()
        && context.prior_temporal_mutations.is_empty()
        && backend.resident_bookmark(context.project_id) == Some(context.bookmark)
        && backend.resident_graph_revision(context.project_id) == Some(context.graph.revision())
        && resident_catalog_matches_canonical(context)
        && let Some(compiled) = compile_resident_quantifier(
            plan,
            context.project_id,
            context.bookmark,
            context.binding_catalog,
            context.graph,
            &context.parameters,
            context.max_result_rows,
        )?
    {
        return execute_resident_quantifier_plan(plan, &compiled, backend, context, stream)
            .map(Some);
    }
    // Prefer the resident grouping pipeline (in-place column reduction) over the segmented
    // aggregation compiler (per-row cell materialization) for the aggregation shapes it accepts.
    if let Some(output) = try_execute_resident_grouping_aggregation(plan, backend, context, stream)?
    {
        return Ok(Some(output));
    }
    if backend.supports_native_segmented_aggregation()
        && context.prior_graph_mutations.is_empty()
        && context.prior_temporal_mutations.is_empty()
        && backend.resident_bookmark(context.project_id) == Some(context.bookmark)
        && backend.resident_graph_revision(context.project_id) == Some(context.graph.revision())
        && resident_catalog_matches_canonical(context)
    {
        let execution = fresh_resident_execution_id();
        if let Some(compiled) = compile_resident_segmented_aggregation(
            plan,
            context.project_id,
            context.graph,
            &context.parameters,
            context.bookmark,
            execution,
            context.max_result_rows,
        )? {
            return execute_resident_segmented_aggregation_plan(
                plan, &compiled, backend, context, stream,
            )
            .map(Some);
        }
    }
    if let Some(compiled) =
        compile_resident_literal_sort(plan, &context.parameters, context.max_result_rows)?
    {
        return execute_resident_literal_sort_plan(plan, &compiled, backend, context, stream)
            .map(Some);
    }
    if backend.supports_native_range_program() {
        if let Some(compiled) =
            compile_resident_range(plan, &context.parameters, context.max_result_rows)?
        {
            return execute_resident_range_plan(plan, &compiled, backend, context, stream)
                .map(Some);
        }
    }
    if backend.supports_native_temporal_arithmetic_program()
        && context.prior_graph_mutations.is_empty()
        && context.prior_temporal_mutations.is_empty()
        && backend.resident_bookmark(context.project_id) == Some(context.bookmark)
        && backend.resident_graph_revision(context.project_id) == Some(context.graph.revision())
        && resident_catalog_matches_canonical(context)
    {
        let execution = fresh_resident_execution_id();
        if let Some(compiled) = compile_resident_temporal_arithmetic(
            plan,
            context.project_id,
            context.bookmark,
            context.binding_catalog,
            context.graph,
            &context.parameters,
            execution,
            context.max_result_rows,
        )? {
            return execute_resident_temporal_arithmetic_plan(
                plan, &compiled, backend, context, stream,
            )
            .map(Some);
        }
    }
    if backend.supports_native_temporal_value_program() {
        if let Some(compiled) = compile_resident_temporal_values(plan, &context.parameters)? {
            return execute_resident_temporal_value_plan(plan, &compiled, backend, context, stream)
                .map(Some);
        }
    }
    if backend.supports_native_scalar_program() {
        if let Some(compiled) = compile_resident_literal_values(plan, &context.parameters)? {
            return execute_resident_scalar_value_plan(plan, &compiled, backend, context, stream)
                .map(Some);
        }
    }
    if backend.supports_native_boolean_aggregate_program() {
        if let Some(compiled) =
            compile_resident_boolean_aggregate(plan, &context.parameters, context.max_result_rows)?
        {
            return execute_resident_boolean_aggregate_plan(
                plan, &compiled, backend, context, stream,
            )
            .map(Some);
        }
    }
    if backend.supports_native_boolean_program() {
        if let Some(compiled) =
            compile_resident_boolean(plan, &context.parameters, context.max_result_rows)?
        {
            return execute_resident_boolean_plan(plan, &compiled, backend, context, stream)
                .map(Some);
        }
        if let Some(compiled) = compile_resident_literal_boolean(plan, &context.parameters)? {
            return execute_resident_boolean_plan(plan, &compiled, backend, context, stream)
                .map(Some);
        }
    }
    if backend.supports_native_to_boolean() {
        if let Some(compiled) =
            compile_resident_scalar(plan, &context.parameters, context.max_result_rows)?
        {
            return execute_resident_to_boolean_plan(plan, &compiled, backend, context, stream)
                .map(Some);
        }
    }
    if !context.prior_graph_mutations.is_empty()
        || !context.prior_temporal_mutations.is_empty()
        || backend.resident_bookmark(context.project_id) != Some(context.bookmark)
        || backend.resident_graph_revision(context.project_id) != Some(context.graph.revision())
    {
        return Ok(None);
    }
    // A plain fixed one-hop read streams through the resident scan/expand executors in O(limit), so
    // prefer that path when its compiler accepts the plan — routing a streamable read to the
    // variable-path trail command (or the nullable-relation candidate buffer) would be
    // O(edges × frontier) and unable to scale. But the streaming compiler declines filters it cannot
    // lower (relationship-property predicates, string comparisons): those must still execute natively
    // on the richer compilers below rather than fall back to host. So the streaming attempt comes
    // first, and the variable-path / nullable-relation compilers are the fallback for everything it
    // declines — no longer gated off for every plain read.
    let plain_streamable_read = plan_is_plain_streamable_read(plan);
    if plain_streamable_read
        && let Some(compiled) = compile_resident_row(
            plan,
            context.project_id,
            context.bookmark,
            context.binding_catalog,
            context.graph,
            &context.parameters,
            context.max_result_rows,
        )?
    {
        return execute_resident_row_plan(plan, &compiled, backend, context, stream).map(Some);
    }
    if backend.supports_native_variable_path()
        && let Some(compiled) = compile_resident_variable_path(
            plan,
            context.project_id,
            context.bookmark,
            context.binding_catalog,
            context.graph,
            context.max_result_rows,
        )?
    {
        return execute_resident_variable_path_plan(plan, &compiled, backend, context, stream)
            .map(Some);
    }
    if let Some(compiled) = compile_resident_nullable_relation(
        plan,
        context.project_id,
        context.bookmark,
        context.binding_catalog,
        context.graph,
        &context.parameters,
        context.max_result_rows,
    )? {
        let predicates_supported = compiled.request.predicate_program.is_empty()
            || backend.supports_nullable_relation_predicates();
        let scope_limit_supported = !compiled.request.program.requires_stable_scope_limit()?
            || backend.supports_nullable_relation_scope_limit();
        let existing_relationship_supported =
            !compiled.request.program.requires_existing_relationship()?
                || backend.supports_nullable_relation_existing_relationship();
        let relationship_endpoint_seed_supported = !compiled
            .request
            .predicate_program
            .requires_relationship_endpoint_seed()
            || backend.supports_nullable_relation_relationship_endpoint_seed();
        let string_property_equality_supported = !compiled
            .request
            .predicate_program
            .requires_string_property_equality()
            || backend.supports_nullable_relation_string_property_equality();
        if predicates_supported
            && scope_limit_supported
            && existing_relationship_supported
            && relationship_endpoint_seed_supported
            && string_property_equality_supported
        {
            return execute_resident_nullable_relation_plan(
                plan, &compiled, backend, context, stream,
            )
            .map(Some);
        }
    }
    // Non-plain reads reach the streaming compiler here (plain reads already tried it first, above).
    if !plain_streamable_read
        && let Some(compiled) = compile_resident_row(
            plan,
            context.project_id,
            context.bookmark,
            context.binding_catalog,
            context.graph,
            &context.parameters,
            context.max_result_rows,
        )?
    {
        return execute_resident_row_plan(plan, &compiled, backend, context, stream).map(Some);
    }
    if let Some(compiled) = compile_resident_value_matrix(
        plan,
        context.project_id,
        context.binding_catalog,
        &context.parameters,
        context.max_result_rows,
    )? {
        return execute_resident_value_matrix_plan(plan, &compiled, backend, context, stream)
            .map(Some);
    }
    if let Some(compiled) = compile_resident_vector(
        plan,
        context.project_id,
        context.binding_catalog,
        &context.parameters,
    )? {
        return execute_resident_vector_plan(plan, &compiled, context, stream).map(Some);
    }
    let Some(mut compiled) = compile_resident(
        plan,
        context.project_id,
        context.binding_catalog,
        context.graph,
        context.temporal,
        &context.parameters,
        context.bookmark.index,
        context.max_result_rows,
    )?
    else {
        return Ok(None);
    };
    preserve_resident_repeated_endpoint_equality(plan, &mut compiled.request);
    if compiled
        .request
        .predicates
        .iter()
        .any(|predicate| !context.graph.node_property_is_integer(predicate.property))
        || compiled
            .request
            .expansion
            .as_ref()
            .is_some_and(|expansion| {
                expansion
                    .end_predicates
                    .iter()
                    .any(|predicate| !context.graph.node_property_is_integer(predicate.property))
            })
        || compiled.request.orders.iter().any(|order| {
            !context.graph.node_property_is_integer(order.property)
                && !context.graph.node_property_is_boolean(order.property)
                && !context.graph.node_property_is_float(order.property)
                && !context.graph.node_property_is_string(order.property)
        })
        || compiled
            .grouping
            .iter()
            .chain(&compiled.additional_groupings)
            .any(|grouping| {
                grouping
                    .key
                    .into_iter()
                    .chain(grouping.value)
                    .any(|projection| !context.graph.node_property_is_integer(projection.property))
            })
        || compiled
            .request
            .property_null_projections
            .iter()
            .any(|projection| {
                projection
                    .property
                    .is_some_and(|property| !context.graph.node_property_is_integer(property))
            })
    {
        return Ok(None);
    }
    for output in &mut compiled.outputs {
        if let ResidentOutputSource::Integer(binding, property) = output.source
            && !context.graph.node_property_is_integer(property)
        {
            output.source = ResidentOutputSource::Property(binding, property);
        }
    }
    compiled
        .request
        .integer_projections
        .retain(|projection| context.graph.node_property_is_integer(projection.property));
    check_execution(context)?;
    let pinned = backend.pin_project(context.project_id)?;
    if pinned.resident_bookmark(context.project_id) != Some(context.bookmark)
        || pinned.resident_graph_revision(context.project_id) != Some(context.graph.revision())
    {
        return Err(Error::new(
            ErrorCode::GpuAdmissionFailure,
            "resident node pipeline backend does not own the requested canonical snapshot",
        ));
    }
    check_execution(context)?;
    if compiled.grouping.is_some() {
        return execute_resident_group_plan(plan, &compiled, pinned.as_ref(), context, stream)
            .map(Some);
    }
    if compiled.temporal.is_some() {
        return execute_resident_temporal_plan(plan, &compiled, pinned.as_ref(), context, stream)
            .map(Some);
    }
    let resident = pinned.execute_node_pipeline(&compiled.request, &context.cancellation)?;
    if resident.start_rows.len() > context.max_result_rows {
        return Err(Error::new(
            ErrorCode::ResultBudgetExceeded,
            "query row budget exceeded",
        ));
    }
    let row_count = resident.start_rows.len();
    let expansion_count = compiled.request.expansion_steps().count();
    let relationship_count = compiled.request.relationship_column_count();
    let node_columns_valid = if expansion_count == 0 {
        resident.end_rows.is_empty() && resident.intermediate_node_rows.is_empty()
    } else {
        resident.end_rows.len() == row_count
            && resident.intermediate_node_rows.len() == expansion_count - 1
            && resident
                .intermediate_node_rows
                .iter()
                .all(|column| column.len() == row_count)
    };
    let relationship_columns_valid = if relationship_count == 0 {
        resident.edge_rows.is_empty() && resident.intermediate_edge_rows.is_empty()
    } else {
        resident.edge_rows.len() == row_count
            && resident.intermediate_edge_rows.len() == relationship_count - 1
            && resident
                .intermediate_edge_rows
                .iter()
                .all(|column| column.len() == row_count)
    };
    if resident.integer_columns.iter().any(|column| {
        column.values.len() != resident.start_rows.len()
            || column.validity.len() != resident.start_rows.len()
    }) || resident.boolean_columns.iter().any(|column| {
        column.values.len() != resident.start_rows.len()
            || column.values.iter().any(|value| *value > 1)
    }) || !node_columns_valid
        || !relationship_columns_valid
    {
        return Err(Error::new(
            ErrorCode::CorruptStorage,
            "resident node pipeline returned columns with different lengths",
        ));
    }
    let graph = GraphReadView::new(context.graph);
    let mut columns = Vec::with_capacity(compiled.outputs.len());
    for output in &compiled.outputs {
        let (value_type, values) = match output.source {
            ResidentOutputSource::Node(binding) => {
                let rows = resident_node_rows(&resident, binding)?;
                let values = rows
                    .iter()
                    .map(|dense| {
                        if *dense == crate::execution::RESIDENT_NULL_ROW {
                            Ok(ResultValue::Scalar(ScalarValue::Null))
                        } else {
                            materialize_node(&graph, *dense).map(ResultValue::Node)
                        }
                    })
                    .collect::<Result<Vec<_>>>()?;
                let value_type = if values
                    .iter()
                    .any(|value| matches!(value, ResultValue::Node(_)))
                {
                    ColumnType::Node
                } else {
                    ColumnType::Null
                };
                (value_type, values)
            }
            ResidentOutputSource::Relationship => {
                let values = resident
                    .edge_rows
                    .iter()
                    .map(|dense| {
                        if *dense == crate::execution::RESIDENT_NULL_ROW {
                            Ok(ResultValue::Scalar(ScalarValue::Null))
                        } else {
                            materialize_edge(&graph, *dense).map(ResultValue::Relationship)
                        }
                    })
                    .collect::<Result<Vec<_>>>()?;
                let value_type = if values
                    .iter()
                    .any(|value| matches!(value, ResultValue::Relationship(_)))
                {
                    ColumnType::Relationship
                } else {
                    ColumnType::Null
                };
                (value_type, values)
            }
            ResidentOutputSource::Integer(binding, property) => {
                let column = resident
                    .integer_columns
                    .iter()
                    .find(|column| column.binding == binding && column.property == property)
                    .ok_or_else(|| {
                        Error::new(
                            ErrorCode::CorruptStorage,
                            "resident node pipeline omitted a projected column",
                        )
                    })?;
                let values = column
                    .values
                    .iter()
                    .zip(&column.validity)
                    .map(|(value, valid)| {
                        ResultValue::Scalar(if *valid == 0 {
                            ScalarValue::Null
                        } else {
                            ScalarValue::Integer(*value)
                        })
                    })
                    .collect::<Vec<_>>();
                let value_type = if column.validity.iter().any(|valid| *valid != 0) {
                    ColumnType::Integer
                } else {
                    ColumnType::Null
                };
                (value_type, values)
            }
            ResidentOutputSource::Property(binding, property) => {
                let rows = resident_node_rows(&resident, binding)?;
                let values = rows
                    .iter()
                    .map(|dense| {
                        if *dense == crate::execution::RESIDENT_NULL_ROW {
                            return Ok(ResultValue::Scalar(ScalarValue::Null));
                        }
                        graph
                            .node_dense(*dense)
                            .and_then(|node| node.property(property))
                            .map_or(
                                Ok(ResultValue::Scalar(ScalarValue::Null)),
                                ResultValue::from_property,
                            )
                    })
                    .collect::<Result<Vec<_>>>()?;
                let mut value_type = ColumnType::Null;
                for value in &values {
                    let next = value.column_type();
                    if next == ColumnType::Null {
                        continue;
                    }
                    if value_type == ColumnType::Null {
                        value_type = next;
                    } else if value_type != next {
                        value_type = ColumnType::Any;
                        break;
                    }
                }
                (value_type, values)
            }
            ResidentOutputSource::PropertyIsNull(projection) => {
                let column = resident
                    .boolean_columns
                    .iter()
                    .find(|column| column.projection == projection)
                    .ok_or_else(|| {
                        Error::new(
                            ErrorCode::CorruptStorage,
                            "resident node pipeline omitted a Boolean property-null projection",
                        )
                    })?;
                let values = column
                    .values
                    .iter()
                    .map(|value| ResultValue::Scalar(ScalarValue::Boolean(*value != 0)))
                    .collect::<Vec<_>>();
                (ColumnType::Boolean, values)
            }
            ResidentOutputSource::GroupKey | ResidentOutputSource::GroupAggregate(_) => {
                return Err(Error::internal(
                    "resident grouping output reached the row pipeline",
                ));
            }
            ResidentOutputSource::TemporalSample
            | ResidentOutputSource::TemporalTime
            | ResidentOutputSource::TemporalValue
            | ResidentOutputSource::TemporalBucket
            | ResidentOutputSource::TemporalBucketStart
            | ResidentOutputSource::TemporalBucketEnd => {
                return Err(Error::internal(
                    "resident temporal output reached the row pipeline",
                ));
            }
        };
        columns.push(ResultColumn {
            name: output.name.clone(),
            value_type,
            values,
        });
    }
    let schema = columns
        .iter()
        .map(|column| (column.name.clone(), column.value_type.clone()))
        .collect::<Vec<_>>();
    if let Some(emit) = stream.as_deref_mut() {
        emit(ExecutionStreamItem::Schema(schema.clone()))?;
    }
    let mut batches = Vec::new();
    let batch_rows = context.max_batch_rows.max(1);
    for start in (0..resident.start_rows.len()).step_by(batch_rows) {
        check_execution(context)?;
        let end = start
            .saturating_add(batch_rows)
            .min(resident.start_rows.len());
        let batch = ResultBatch {
            row_count: end - start,
            columns: columns
                .iter()
                .map(|column| ResultColumn {
                    name: column.name.clone(),
                    value_type: column.value_type.clone(),
                    values: column.values[start..end].to_vec(),
                })
                .collect(),
        };
        if let Some(emit) = stream.as_deref_mut() {
            emit(ExecutionStreamItem::Batch(batch))?;
        } else {
            batches.push(batch);
        }
    }
    let mut dependencies = TransactionDependencies::default();
    for dependency in &plan.dependencies {
        let version = context
            .predicate_versions
            .get(dependency)
            .copied()
            .unwrap_or(context.bookmark.index);
        dependencies.predicates.insert(dependency.clone(), version);
    }
    let mut dependent_node_rows = BTreeSet::new();
    for dense in resident
        .start_rows
        .iter()
        .chain(&resident.end_rows)
        .chain(resident.intermediate_node_rows.iter().flatten())
    {
        if *dense == crate::execution::RESIDENT_NULL_ROW || !dependent_node_rows.insert(*dense) {
            continue;
        }
        let node = context.graph.node_dense(*dense).ok_or_else(|| {
            Error::new(
                ErrorCode::CorruptStorage,
                "resident node pipeline selected a deleted node",
            )
        })?;
        dependencies
            .entities
            .insert(EntityDependency::Node(node.id()), node.revision());
    }
    let mut dependent_edge_rows = BTreeSet::new();
    for dense in resident
        .edge_rows
        .iter()
        .chain(resident.intermediate_edge_rows.iter().flatten())
    {
        if *dense == crate::execution::RESIDENT_NULL_ROW || !dependent_edge_rows.insert(*dense) {
            continue;
        }
        let edge = context.graph.edge_dense(*dense).ok_or_else(|| {
            Error::new(
                ErrorCode::CorruptStorage,
                "resident node pipeline selected a deleted relationship",
            )
        })?;
        dependencies
            .entities
            .insert(EntityDependency::Relationship(edge.id()), edge.revision());
    }
    Ok(Some(ExecutionOutput {
        result: QueryResult {
            schema,
            batches,
            bookmark: context.bookmark,
            statistics: StatementStats::default(),
            truncated: false,
        },
        graph_mutations: Vec::new(),
        temporal_mutations: Vec::new(),
        dependencies,
        administrative: None,
        vector_searches: Vec::new(),
        runtime_replans: 0,
    }))
}

/// The general resident compiler represents an OPTIONAL single-hop expansion following a
/// node-only scan as the request's first expansion. Preserve a repeated endpoint variable as an
/// equality constraint at that boundary: `(a)-[r]-(a)` may select parallel self-loops, but never
/// an ordinary edge which merely touches `a`.
fn preserve_resident_repeated_endpoint_equality(
    plan: &PhysicalPlan,
    request: &mut ResidentNodePipelineRequest,
) {
    let repeated_optional_endpoint = plan.operators.iter().any(|operator| {
        let PhysicalOperator::ScanPattern {
            optional: true,
            pattern,
            ..
        } = operator
        else {
            return false;
        };
        let [step] = pattern.steps.as_slice() else {
            return false;
        };
        pattern.start.variable.is_some()
            && pattern.start.variable.as_ref() == step.node.variable.as_ref()
    });
    if repeated_optional_endpoint
        && let Some(expansion) = &mut request.expansion
        && expansion.optional
    {
        expansion.end_equals_start = true;
    }
}

fn resident_catalog_matches_canonical(context: &ExecutionContext<'_>) -> bool {
    let binding = context.binding_catalog;
    let canonical = context.graph.catalog();
    binding.optimizer_generation() == canonical.optimizer_generation()
        && binding.next_label_id() == canonical.next_label_id()
        && binding.next_property_id() == canonical.next_property_id()
        && binding.next_relationship_type_id() == canonical.next_relationship_type_id()
}

fn execute_resident_pattern_count_plan(
    plan: &PhysicalPlan,
    compiled: &CompiledResidentPatternCountPlan,
    backend: &dyn ExecutionBackend,
    context: &ExecutionContext<'_>,
    stream: &mut Option<&mut dyn FnMut(ExecutionStreamItem) -> Result<()>>,
) -> Result<ExecutionOutput> {
    let request = &compiled.request;
    if !resident_catalog_matches_canonical(context)
        || request.project != context.project_id
        || request.expected_bookmark != context.bookmark
        || request.expected_graph_revision != context.graph.revision()
        || request.expected_layout_version != context.graph.layout_version()
        || request.layers != plan.read_layers
        || request.node_slots != context.graph.node_slot_count()
        || request.edge_slots != context.graph.edge_slot_count()
    {
        return Err(Error::new(
            ErrorCode::GpuAdmissionFailure,
            "resident pattern-count compiler generation no longer matches the canonical statement",
        ));
    }

    check_execution(context)?;
    let pinned = backend.pin_project(context.project_id)?;
    if pinned.resident_bookmark(context.project_id) != Some(context.bookmark)
        || pinned.resident_graph_revision(context.project_id) != Some(context.graph.revision())
    {
        return Err(Error::new(
            ErrorCode::GpuAdmissionFailure,
            "resident pattern-count backend does not own the requested canonical snapshot",
        ));
    }
    check_execution(context)?;
    let raw = pinned.execute_pattern_count(request, &context.cancellation)?;
    let validated = raw.validate(request, pinned.kind())?;
    check_execution(context)?;
    let (rows, counts) = validated.into_columns();

    let graph = GraphReadView::new(context.graph);
    let include_nodes = matches!(
        &compiled.projection,
        ResidentPatternCountProjection::ExistsWithNode { .. }
    );
    let mut node_values = include_nodes.then(|| Vec::with_capacity(rows.len()));
    let mut scalar_values = Vec::with_capacity(rows.len());
    let mut dependencies = TransactionDependencies::default();
    for dependency in &plan.dependencies {
        let version = context
            .predicate_versions
            .get(dependency)
            .copied()
            .unwrap_or(context.bookmark.index);
        dependencies.predicates.insert(dependency.clone(), version);
    }
    for (index, (dense, count)) in rows.iter().zip(&counts).enumerate() {
        if index.is_multiple_of(4096) {
            check_execution(context)?;
        }
        let node = context.graph.node_dense(*dense).ok_or_else(|| {
            Error::new(
                ErrorCode::CorruptStorage,
                format!(
                    "resident pattern count selected a missing or deleted `{}` node",
                    compiled.outer_variable
                ),
            )
        })?;
        if !plan.read_layers.contains_layer(node.layer())
            || match &request.start_labels {
                ResidentPatternCountStartLabels::Known(labels) => {
                    labels.iter().any(|label| !node.labels().contains(label))
                }
                ResidentPatternCountStartLabels::Never => true,
            }
        {
            return Err(Error::new(
                ErrorCode::CorruptStorage,
                "resident pattern count selected a node outside its labelled visible domain",
            ));
        }
        dependencies
            .entities
            .insert(EntityDependency::Node(node.id()), node.revision());
        if let Some(node_values) = &mut node_values {
            node_values.push(ResultValue::Node(materialize_node(&graph, *dense)?));
        }
        match &compiled.projection {
            ResidentPatternCountProjection::Count { .. } => {
                scalar_values.push(ResultValue::Scalar(ScalarValue::Integer(i64::from(*count))))
            }
            ResidentPatternCountProjection::ExistsWithNode { .. } => {
                scalar_values.push(ResultValue::Scalar(ScalarValue::Boolean(*count > 0)))
            }
            ResidentPatternCountProjection::NonNullListCount { .. } => {}
        }
    }
    if matches!(
        &compiled.projection,
        ResidentPatternCountProjection::NonNullListCount { .. }
    ) {
        scalar_values.push(ResultValue::Scalar(ScalarValue::Integer(
            i64::try_from(rows.len()).map_err(|_| {
                Error::new(
                    ErrorCode::ResultBudgetExceeded,
                    "resident pattern list cardinality exceeds INTEGER",
                )
            })?,
        )));
    }

    let (schema, columns, output_row_count) = match &compiled.projection {
        ResidentPatternCountProjection::Count { output_name } => (
            vec![(output_name.clone(), ColumnType::Integer)],
            vec![(output_name.clone(), ColumnType::Integer, scalar_values)],
            rows.len(),
        ),
        ResidentPatternCountProjection::NonNullListCount { output_name } => (
            vec![(output_name.clone(), ColumnType::Integer)],
            vec![(output_name.clone(), ColumnType::Integer, scalar_values)],
            1,
        ),
        ResidentPatternCountProjection::ExistsWithNode {
            node_output_name,
            boolean_output_name,
        } => (
            vec![
                (node_output_name.clone(), ColumnType::Node),
                (boolean_output_name.clone(), ColumnType::Boolean),
            ],
            vec![
                (
                    node_output_name.clone(),
                    ColumnType::Node,
                    node_values.ok_or_else(|| {
                        Error::internal("resident pattern-count node column disappeared")
                    })?,
                ),
                (
                    boolean_output_name.clone(),
                    ColumnType::Boolean,
                    scalar_values,
                ),
            ],
            rows.len(),
        ),
    };
    let batch_rows = context.max_batch_rows.max(1);
    let mut batches = Vec::new();
    // All backend provenance, canonical row identities, labels, and aligned values are validated
    // before the first client-visible stream item.
    if let Some(emit) = stream.as_deref_mut() {
        emit(ExecutionStreamItem::Schema(schema.clone()))?;
    }
    for start in (0..output_row_count).step_by(batch_rows) {
        check_execution(context)?;
        let end = start.saturating_add(batch_rows).min(output_row_count);
        let batch = ResultBatch {
            row_count: end - start,
            columns: columns
                .iter()
                .map(|(name, value_type, values)| ResultColumn {
                    name: name.clone(),
                    value_type: value_type.clone(),
                    values: values[start..end].to_vec(),
                })
                .collect(),
        };
        if let Some(emit) = stream.as_deref_mut() {
            emit(ExecutionStreamItem::Batch(batch))?;
        } else {
            batches.push(batch);
        }
    }

    Ok(ExecutionOutput {
        result: QueryResult {
            schema,
            batches,
            bookmark: context.bookmark,
            statistics: StatementStats::default(),
            truncated: false,
        },
        graph_mutations: Vec::new(),
        temporal_mutations: Vec::new(),
        dependencies,
        administrative: None,
        vector_searches: Vec::new(),
        runtime_replans: 0,
    })
}

fn execute_resident_pattern_pair_predicate_plan(
    plan: &PhysicalPlan,
    compiled: &CompiledResidentPatternPairPredicatePlan,
    backend: &dyn ExecutionBackend,
    context: &ExecutionContext<'_>,
    stream: &mut Option<&mut dyn FnMut(ExecutionStreamItem) -> Result<()>>,
) -> Result<ExecutionOutput> {
    if !resident_catalog_matches_canonical(context) {
        return Err(Error::new(
            ErrorCode::GpuAdmissionFailure,
            "resident paired Pattern1 catalog does not match the canonical graph catalog",
        ));
    }

    check_execution(context)?;
    let pinned = backend.pin_project(context.project_id)?;
    if pinned.resident_bookmark(context.project_id) != Some(context.bookmark)
        || pinned.resident_graph_revision(context.project_id) != Some(context.graph.revision())
    {
        return Err(Error::new(
            ErrorCode::GpuAdmissionFailure,
            "resident paired Pattern1 backend does not own the requested canonical snapshot",
        ));
    }

    check_execution(context)?;
    let raw = pinned.execute_pattern_predicate_pairs(&compiled.request, &context.cancellation)?;
    let validated = raw.validate(&compiled.request, pinned.kind())?;
    check_execution(context)?;
    let (n_rows, m_rows) = validated.into_columns();
    if n_rows.len() != m_rows.len() {
        return Err(Error::new(
            ErrorCode::CorruptStorage,
            "validated resident paired Pattern1 columns are misaligned",
        ));
    }

    let graph = GraphReadView::new(context.graph);
    let mut n_values = Vec::with_capacity(n_rows.len());
    let mut m_values = Vec::with_capacity(m_rows.len());
    let mut dependencies = TransactionDependencies::default();
    for dependency in &plan.dependencies {
        let version = context
            .predicate_versions
            .get(dependency)
            .copied()
            .unwrap_or(context.bookmark.index);
        dependencies.predicates.insert(dependency.clone(), version);
    }
    for (index, (n_dense, m_dense)) in n_rows.iter().zip(&m_rows).enumerate() {
        if index.is_multiple_of(4096) {
            check_execution(context)?;
        }
        let n_node = context.graph.node_dense(*n_dense).ok_or_else(|| {
            Error::new(
                ErrorCode::CorruptStorage,
                format!(
                    "resident paired Pattern1 selected a missing or deleted `{}` node",
                    compiled.n_variable
                ),
            )
        })?;
        let m_node = context.graph.node_dense(*m_dense).ok_or_else(|| {
            Error::new(
                ErrorCode::CorruptStorage,
                format!(
                    "resident paired Pattern1 selected a missing or deleted `{}` node",
                    compiled.m_variable
                ),
            )
        })?;
        if !plan.read_layers.contains_layer(n_node.layer())
            || !plan.read_layers.contains_layer(m_node.layer())
        {
            return Err(Error::new(
                ErrorCode::CorruptStorage,
                "resident paired Pattern1 selected a node outside the query's visible layers",
            ));
        }
        let n_materialized = materialize_node(&graph, *n_dense)?;
        let m_materialized = materialize_node(&graph, *m_dense)?;
        dependencies
            .entities
            .insert(EntityDependency::Node(n_node.id()), n_node.revision());
        dependencies
            .entities
            .insert(EntityDependency::Node(m_node.id()), m_node.revision());
        n_values.push(ResultValue::Node(n_materialized));
        m_values.push(ResultValue::Node(m_materialized));
    }

    let value_type = if n_values.is_empty() {
        ColumnType::Null
    } else {
        ColumnType::Node
    };
    let schema = vec![
        (compiled.n_output_name.clone(), value_type.clone()),
        (compiled.m_output_name.clone(), value_type.clone()),
    ];
    let mut batches = Vec::new();
    let batch_rows = context.max_batch_rows.max(1);

    // The device frame, every receipt, aligned pair columns, canonical nodes, and dependencies
    // are validated before the first client-visible item. A corrupt or stale result therefore
    // cannot leak a schema or a partial row batch.
    if let Some(emit) = stream.as_deref_mut() {
        emit(ExecutionStreamItem::Schema(schema.clone()))?;
    }
    for start in (0..n_values.len()).step_by(batch_rows) {
        check_execution(context)?;
        let end = start.saturating_add(batch_rows).min(n_values.len());
        let batch = ResultBatch {
            row_count: end - start,
            columns: vec![
                ResultColumn {
                    name: compiled.n_output_name.clone(),
                    value_type: value_type.clone(),
                    values: n_values[start..end].to_vec(),
                },
                ResultColumn {
                    name: compiled.m_output_name.clone(),
                    value_type: value_type.clone(),
                    values: m_values[start..end].to_vec(),
                },
            ],
        };
        if let Some(emit) = stream.as_deref_mut() {
            emit(ExecutionStreamItem::Batch(batch))?;
        } else {
            batches.push(batch);
        }
    }

    Ok(ExecutionOutput {
        result: QueryResult {
            schema,
            batches,
            bookmark: context.bookmark,
            statistics: StatementStats::default(),
            truncated: false,
        },
        graph_mutations: Vec::new(),
        temporal_mutations: Vec::new(),
        dependencies,
        administrative: None,
        vector_searches: Vec::new(),
        runtime_replans: 0,
    })
}

fn execute_resident_pattern_predicate_plan(
    plan: &PhysicalPlan,
    compiled: &CompiledResidentPatternPredicatePlan,
    backend: &dyn ExecutionBackend,
    context: &ExecutionContext<'_>,
    stream: &mut Option<&mut dyn FnMut(ExecutionStreamItem) -> Result<()>>,
) -> Result<ExecutionOutput> {
    if !resident_catalog_matches_canonical(context) {
        return Err(Error::new(
            ErrorCode::GpuAdmissionFailure,
            "resident Pattern1 catalog does not match the canonical graph catalog",
        ));
    }

    check_execution(context)?;
    let pinned = backend.pin_project(context.project_id)?;
    if pinned.resident_bookmark(context.project_id) != Some(context.bookmark)
        || pinned.resident_graph_revision(context.project_id) != Some(context.graph.revision())
    {
        return Err(Error::new(
            ErrorCode::GpuAdmissionFailure,
            "resident Pattern1 backend does not own the requested canonical snapshot",
        ));
    }

    check_execution(context)?;
    let raw = pinned.execute_pattern_predicate(&compiled.request, &context.cancellation)?;
    let validated = raw.validate(&compiled.request, pinned.kind())?;
    check_execution(context)?;

    let rows = validated.into_rows();
    if rows.windows(2).any(|pair| pair[0] >= pair[1]) {
        return Err(Error::new(
            ErrorCode::CorruptStorage,
            "validated resident Pattern1 rows are not unique and ascending",
        ));
    }

    let graph = GraphReadView::new(context.graph);
    let mut values = Vec::with_capacity(rows.len());
    let mut dependencies = TransactionDependencies::default();
    for dependency in &plan.dependencies {
        let version = context
            .predicate_versions
            .get(dependency)
            .copied()
            .unwrap_or(context.bookmark.index);
        dependencies.predicates.insert(dependency.clone(), version);
    }
    for dense in &rows {
        let node = context.graph.node_dense(*dense).ok_or_else(|| {
            Error::new(
                ErrorCode::CorruptStorage,
                "resident Pattern1 selected a missing or deleted canonical node",
            )
        })?;
        if !plan.read_layers.contains_layer(node.layer()) {
            return Err(Error::new(
                ErrorCode::CorruptStorage,
                "resident Pattern1 selected a node outside the query's visible layers",
            ));
        }
        let materialized = materialize_node(&graph, *dense)?;
        dependencies
            .entities
            .insert(EntityDependency::Node(node.id()), node.revision());
        values.push(ResultValue::Node(materialized));
    }

    let value_type = if values.is_empty() {
        ColumnType::Null
    } else {
        ColumnType::Node
    };
    let schema = vec![(compiled.output_name.clone(), value_type.clone())];
    let mut batches = Vec::new();
    let batch_rows = context.max_batch_rows.max(1);

    // Everything derived from the private raw result is validated and materialized before the
    // first client-visible item. Provenance or canonical-boundary failures therefore emit no
    // schema and no partial batch.
    if let Some(emit) = stream.as_deref_mut() {
        emit(ExecutionStreamItem::Schema(schema.clone()))?;
    }
    for start in (0..values.len()).step_by(batch_rows) {
        check_execution(context)?;
        let end = start.saturating_add(batch_rows).min(values.len());
        let batch = ResultBatch {
            row_count: end - start,
            columns: vec![ResultColumn {
                name: compiled.output_name.clone(),
                value_type: value_type.clone(),
                values: values[start..end].to_vec(),
            }],
        };
        if let Some(emit) = stream.as_deref_mut() {
            emit(ExecutionStreamItem::Batch(batch))?;
        } else {
            batches.push(batch);
        }
    }

    Ok(ExecutionOutput {
        result: QueryResult {
            schema,
            batches,
            bookmark: context.bookmark,
            statistics: StatementStats::default(),
            truncated: false,
        },
        graph_mutations: Vec::new(),
        temporal_mutations: Vec::new(),
        dependencies,
        administrative: None,
        vector_searches: Vec::new(),
        runtime_replans: 0,
    })
}

fn execute_resident_row_match_merge_relationship_plan(
    plan: &PhysicalPlan,
    request: &crate::execution::ResidentRowMutationRequest,
    validated: &ValidatedResidentRowMatchMergeRelationship,
    context: &ExecutionContext<'_>,
) -> Result<ExecutionOutput> {
    let program = request.match_merge_relationship.as_ref().ok_or_else(|| {
        Error::new(
            ErrorCode::CorruptStorage,
            "validated generalized row mutation lost its immutable program",
        )
    })?;
    let read_dependencies = validated
        .read_dependencies()
        .iter()
        .copied()
        .collect::<BTreeSet<_>>();
    let mut dependencies = TransactionDependencies::default();
    for dependency in &plan.dependencies {
        let version = context
            .predicate_versions
            .get(dependency)
            .copied()
            .unwrap_or(context.bookmark.index);
        dependencies.predicates.insert(dependency.clone(), version);
    }
    for dependency in &read_dependencies {
        match dependency {
            ResidentMutationReadDependency::Node(dense) => {
                let node = context.graph.node_dense(*dense).ok_or_else(|| {
                    Error::new(
                        ErrorCode::CorruptStorage,
                        "generalized row mutation read set names a missing node",
                    )
                })?;
                if node.revision() > context.graph.revision() {
                    return Err(Error::new(
                        ErrorCode::CorruptStorage,
                        "generalized row mutation read set names a node from a future revision",
                    ));
                }
                dependencies
                    .entities
                    .insert(EntityDependency::Node(node.id()), node.revision());
            }
            ResidentMutationReadDependency::Relationship(dense) => {
                let edge = context.graph.edge_dense(*dense).ok_or_else(|| {
                    Error::new(
                        ErrorCode::CorruptStorage,
                        "generalized row mutation read set names a missing relationship",
                    )
                })?;
                if edge.revision() > context.graph.revision() {
                    return Err(Error::new(
                        ErrorCode::CorruptStorage,
                        "generalized row mutation read set names a relationship from a future revision",
                    ));
                }
                dependencies
                    .entities
                    .insert(EntityDependency::Relationship(edge.id()), edge.revision());
            }
        }
    }

    // Resolve every backend-authored binding against the immutable canonical image before the
    // first catalog name or graph effect is published. This is identity validation only; MATCH
    // and MERGE membership remain backend work proven by the sealed result and receipts.
    let relationship_token = program
        .relationship_type_tokens
        .get(usize::from(program.relationship.relationship_type))
        .copied()
        .flatten();
    let mut created_node_ids = BTreeSet::new();
    let mut created_relationship_ids = BTreeSet::new();
    for row in validated.work_rows() {
        let matched_dense = row.matched_node.dense_row.ok_or_else(|| {
            Error::new(
                ErrorCode::CorruptStorage,
                "generalized row mutation MATCH returned a statement-local node",
            )
        })?;
        let matched = context.graph.node_dense(matched_dense).ok_or_else(|| {
            Error::new(
                ErrorCode::CorruptStorage,
                "generalized row mutation MATCH target disappeared",
            )
        })?;
        if row.matched_node.created_by.is_some()
            || matched.id().0 != row.matched_node.target_id
            || !read_dependencies.contains(&ResidentMutationReadDependency::Node(matched_dense))
        {
            return Err(Error::new(
                ErrorCode::CorruptStorage,
                "generalized row mutation MATCH target has a wrong identity or missing dependency",
            ));
        }

        match (row.merged_node.dense_row, row.merged_node.created_by) {
            (Some(dense), None) => {
                let node = context.graph.node_dense(dense).ok_or_else(|| {
                    Error::new(
                        ErrorCode::CorruptStorage,
                        "generalized row mutation existing MERGE node disappeared",
                    )
                })?;
                if node.id().0 != row.merged_node.target_id
                    || !read_dependencies.contains(&ResidentMutationReadDependency::Node(dense))
                {
                    return Err(Error::new(
                        ErrorCode::CorruptStorage,
                        "generalized row mutation existing MERGE node has a wrong identity or missing dependency",
                    ));
                }
            }
            (None, Some(_)) => {
                if context
                    .graph
                    .contains_node_id(NodeId(row.merged_node.target_id))
                {
                    return Err(Error::new(
                        ErrorCode::TransactionConflict,
                        "generalized row mutation created node identity already exists",
                    ));
                }
                created_node_ids.insert(row.merged_node.target_id);
            }
            _ => {
                return Err(Error::new(
                    ErrorCode::CorruptStorage,
                    "generalized row mutation MERGE node mixed immutable and statement-local identity",
                ));
            }
        }

        match (
            row.merged_relationship.dense_row,
            row.merged_relationship.created_by,
        ) {
            (Some(dense), None) => {
                let edge = context.graph.edge_dense(dense).ok_or_else(|| {
                    Error::new(
                        ErrorCode::CorruptStorage,
                        "generalized row mutation existing MERGE relationship disappeared",
                    )
                })?;
                if edge.id().0 != row.merged_relationship.target_id
                    || edge.source().0 != row.merged_node.target_id
                    || edge.target().0 != row.matched_node.target_id
                    || relationship_token != Some(edge.relationship_type())
                    || !read_dependencies
                        .contains(&ResidentMutationReadDependency::Relationship(dense))
                {
                    return Err(Error::new(
                        ErrorCode::CorruptStorage,
                        "generalized row mutation existing relationship has a wrong identity, direction, type, or dependency",
                    ));
                }
            }
            (None, Some(_)) => {
                if context
                    .graph
                    .contains_edge_id(EdgeId(row.merged_relationship.target_id))
                {
                    return Err(Error::new(
                        ErrorCode::TransactionConflict,
                        "generalized row mutation created relationship identity already exists",
                    ));
                }
                created_relationship_ids.insert(row.merged_relationship.target_id);
            }
            _ => {
                return Err(Error::new(
                    ErrorCode::CorruptStorage,
                    "generalized row mutation MERGE relationship mixed immutable and statement-local identity",
                ));
            }
        }
    }

    let mut intent_node_ids = BTreeSet::new();
    let mut intent_relationship_ids = BTreeSet::new();
    for intent in validated.intents() {
        match &intent.action {
            ResidentRowMutationWorkIntentAction::CreateNode { .. } => {
                if !created_node_ids.contains(&intent.target_id)
                    || !intent_node_ids.insert(intent.target_id)
                {
                    return Err(Error::new(
                        ErrorCode::CorruptStorage,
                        "generalized row mutation node intent does not name one create leader",
                    ));
                }
            }
            ResidentRowMutationWorkIntentAction::CreateRelationship {
                source_node_id,
                target_node_id,
                ..
            } => {
                if !created_relationship_ids.contains(&intent.target_id)
                    || !intent_relationship_ids.insert(intent.target_id)
                    || (!created_node_ids.contains(source_node_id)
                        && !context.graph.contains_node_id(NodeId(*source_node_id)))
                    || (!created_node_ids.contains(target_node_id)
                        && !context.graph.contains_node_id(NodeId(*target_node_id)))
                {
                    return Err(Error::new(
                        ErrorCode::CorruptStorage,
                        "generalized row mutation relationship intent has a foreign identity or endpoint",
                    ));
                }
            }
        }
    }
    if intent_node_ids != created_node_ids || intent_relationship_ids != created_relationship_ids {
        return Err(Error::new(
            ErrorCode::CorruptStorage,
            "generalized row mutation did not publish exactly its statement-local leaders",
        ));
    }

    let row_count = validated.work_rows().len();
    let mut decoded_columns = Vec::with_capacity(validated.columns().len());
    for column in validated.columns() {
        if column.values.len() != row_count
            || column.validity.len() != row_count
            || column.validity.iter().any(|valid| *valid != 1)
        {
            return Err(Error::new(
                ErrorCode::CorruptStorage,
                "generalized row mutation integer output changed after validation",
            ));
        }
        decoded_columns.push(
            column
                .values
                .iter()
                .copied()
                .map(|value| ResultValue::Scalar(ScalarValue::Integer(value)))
                .collect::<Vec<_>>(),
        );
    }

    let mut state = ExecutionState {
        graph: transaction_graph_view(context)?,
        temporal: transaction_temporal_view(context)?,
        mutations: Vec::new(),
        temporal_mutations: Vec::new(),
        dependencies,
        next_node_id: context.next_node_id,
        next_edge_id: context.next_edge_id,
        revision: context.mutation_revision,
        created_at: resolved_created_at(context.resolved_time_nanos),
        read_layers: plan.read_layers,
        write_layer: plan.write_layer,
        stats: StatementStats::default(),
        final_columns: Vec::new(),
        scope_columns: BTreeSet::new(),
        administrative: None,
        vector_searches: Vec::new(),
        resident_backend: None,
        allow_context_backend: true,
        resident_overlay_mutations: 0,
        existential_subquery_depth: 0,
        initial_scan_cap: None,
    };
    let mut published_node_ids = BTreeSet::new();
    let mut published_relationship_ids = BTreeSet::new();
    for intent in validated.intents() {
        match &intent.action {
            ResidentRowMutationWorkIntentAction::CreateNode { labels, properties } => {
                if !published_node_ids.insert(intent.target_id)
                    || state.graph.node(NodeId(intent.target_id)).is_some()
                {
                    return Err(Error::new(
                        ErrorCode::CorruptStorage,
                        "generalized row mutation CREATE node reused a canonical identity",
                    ));
                }
                let mut resolved_labels = Vec::with_capacity(labels.len());
                for label in labels {
                    let name = request
                        .program
                        .label_names
                        .get(usize::from(*label))
                        .ok_or_else(|| {
                            Error::new(
                                ErrorCode::CorruptStorage,
                                "generalized row mutation CREATE label name disappeared",
                            )
                        })?;
                    resolved_labels.push(intern_label(name, &mut state)?);
                }
                resolved_labels.sort_unstable();
                resolved_labels.dedup();
                let mut resolved_properties = Vec::with_capacity(properties.len());
                let mut unique_properties = BTreeSet::new();
                for property in properties {
                    if !unique_properties.insert(property.property_name) {
                        return Err(Error::new(
                            ErrorCode::CorruptStorage,
                            "generalized row mutation CREATE node duplicated a key property",
                        ));
                    }
                    let name = request
                        .program
                        .property_names
                        .get(usize::from(property.property_name))
                        .ok_or_else(|| {
                            Error::new(
                                ErrorCode::CorruptStorage,
                                "generalized row mutation CREATE node property name disappeared",
                            )
                        })?;
                    let property_id = intern_property(name, &mut state)?;
                    if !matches!(property.value, ScalarValue::Null) {
                        resolved_properties.push((property_id, property.value.clone()));
                    }
                }
                validate_node_properties(context.graph, &resolved_properties)?;
                apply_mutation(
                    &mut state,
                    GraphMutation::InsertNode(NodeInput {
                        id: NodeId(intent.target_id),
                        layer: request.write_layer,
                        revision: context.mutation_revision,
                        labels: resolved_labels,
                        properties: resolved_properties,
                    }),
                )?;
                state.next_node_id =
                    state
                        .next_node_id
                        .max(intent.target_id.checked_add(1).ok_or_else(|| {
                            Error::new(ErrorCode::ResultBudgetExceeded, "node ID space exhausted")
                        })?);
                state.stats.nodes_created = state.stats.nodes_created.saturating_add(1);
                state.stats.labels_added =
                    state.stats.labels_added.saturating_add(labels.len() as u64);
            }
            ResidentRowMutationWorkIntentAction::CreateRelationship {
                relationship_type,
                source_node_id,
                target_node_id,
                properties,
            } => {
                let edge_id = EdgeId(intent.target_id);
                if !published_relationship_ids.insert(intent.target_id)
                    || state.graph.edge(edge_id).is_some()
                    || state.graph.node(NodeId(*source_node_id)).is_none()
                    || state.graph.node(NodeId(*target_node_id)).is_none()
                {
                    return Err(Error::new(
                        ErrorCode::CorruptStorage,
                        "generalized row mutation CREATE relationship reused an identity or lost an endpoint",
                    ));
                }
                let relationship_name = program
                    .relationship_type_names
                    .get(usize::from(*relationship_type))
                    .ok_or_else(|| {
                        Error::new(
                            ErrorCode::CorruptStorage,
                            "generalized row mutation CREATE relationship type disappeared",
                        )
                    })?;
                let relationship_type = intern_relationship_type(relationship_name, &mut state)?;
                let mut resolved_properties = Vec::with_capacity(properties.len());
                let mut unique_properties = BTreeSet::new();
                for property in properties {
                    if !unique_properties.insert(property.property_name) {
                        return Err(Error::new(
                            ErrorCode::CorruptStorage,
                            "generalized row mutation CREATE relationship duplicated a key property",
                        ));
                    }
                    let name = request
                        .program
                        .property_names
                        .get(usize::from(property.property_name))
                        .ok_or_else(|| {
                            Error::new(
                                ErrorCode::CorruptStorage,
                                "generalized row mutation CREATE relationship property name disappeared",
                            )
                        })?;
                    let property_id = intern_property(name, &mut state)?;
                    if !matches!(property.value, ScalarValue::Null) {
                        resolved_properties.push((property_id, property.value.clone()));
                    }
                }
                validate_edge_properties(context.graph, &resolved_properties)?;
                apply_mutation(
                    &mut state,
                    GraphMutation::InsertEdge(EdgeInput {
                        id: edge_id,
                        source: NodeId(*source_node_id),
                        target: NodeId(*target_node_id),
                        relationship_type,
                        layer: request.write_layer,
                        revision: context.mutation_revision,
                        properties: resolved_properties,
                    }),
                )?;
                state.next_edge_id =
                    state
                        .next_edge_id
                        .max(intent.target_id.checked_add(1).ok_or_else(|| {
                            Error::new(
                                ErrorCode::ResultBudgetExceeded,
                                "relationship ID space exhausted",
                            )
                        })?);
                state.stats.relationships_created =
                    state.stats.relationships_created.saturating_add(1);
            }
        }
    }

    let output_type = if row_count == 0 {
        ColumnType::Null
    } else {
        ColumnType::Integer
    };
    let schema = program
        .integer_outputs
        .iter()
        .map(|output| (output.name.clone(), output_type.clone()))
        .collect::<Vec<_>>();
    let mut batches = Vec::new();
    let batch_rows = context.max_batch_rows.max(1);
    for start in (0..row_count).step_by(batch_rows) {
        let end = start.saturating_add(batch_rows).min(row_count);
        batches.push(ResultBatch {
            row_count: end - start,
            columns: program
                .integer_outputs
                .iter()
                .zip(&decoded_columns)
                .map(|(output, values)| ResultColumn {
                    name: output.name.clone(),
                    value_type: output_type.clone(),
                    values: values[start..end].to_vec(),
                })
                .collect(),
        });
    }

    Ok(ExecutionOutput {
        result: QueryResult {
            schema,
            batches,
            bookmark: context.bookmark,
            statistics: state.stats,
            truncated: false,
        },
        graph_mutations: state.mutations,
        temporal_mutations: state.temporal_mutations,
        dependencies: state.dependencies,
        administrative: None,
        vector_searches: Vec::new(),
        runtime_replans: 0,
    })
}

#[allow(clippy::too_many_lines)]
fn execute_resident_bound_relationship_merge_plan(
    plan: &PhysicalPlan,
    request: &crate::execution::ResidentRowMutationRequest,
    validated: &ValidatedResidentRowBoundRelationshipMerge,
    context: &ExecutionContext<'_>,
) -> Result<ExecutionOutput> {
    let body = request.bound_relationship_merge_body().ok_or_else(|| {
        Error::new(
            ErrorCode::CorruptStorage,
            "validated bound relationship MERGE lost its immutable program",
        )
    })?;
    let program = &body.program;
    let mut dependencies = TransactionDependencies::default();
    for dependency in &plan.dependencies {
        let version = context
            .predicate_versions
            .get(dependency)
            .copied()
            .unwrap_or(context.bookmark.index);
        dependencies.predicates.insert(dependency.clone(), version);
    }
    for dependency in validated.read_dependencies() {
        match *dependency {
            ResidentMutationReadDependency::Node(dense) => {
                let node = context.graph.node_dense(dense).ok_or_else(|| {
                    Error::new(
                        ErrorCode::CorruptStorage,
                        "bound relationship MERGE dependency names a missing node",
                    )
                })?;
                if node.revision() > context.graph.revision()
                    || !plan.read_layers.contains_layer(node.layer())
                {
                    return Err(Error::new(
                        ErrorCode::CorruptStorage,
                        "bound relationship MERGE node dependency is outside the pinned generation",
                    ));
                }
                dependencies
                    .entities
                    .insert(EntityDependency::Node(node.id()), node.revision());
            }
            ResidentMutationReadDependency::Relationship(dense) => {
                let edge = context.graph.edge_dense(dense).ok_or_else(|| {
                    Error::new(
                        ErrorCode::CorruptStorage,
                        "bound relationship MERGE dependency names a missing relationship",
                    )
                })?;
                if edge.revision() > context.graph.revision()
                    || !plan.read_layers.contains_layer(edge.layer())
                {
                    return Err(Error::new(
                        ErrorCode::CorruptStorage,
                        "bound relationship MERGE relationship dependency is outside the pinned generation",
                    ));
                }
                dependencies
                    .entities
                    .insert(EntityDependency::Relationship(edge.id()), edge.revision());
            }
        }
    }

    let mut deleted_nodes = BTreeSet::new();
    let mut deleted_relationships = BTreeSet::new();
    let mut prior_delete_order = None::<(bool, u64)>;
    for intent in validated.delete_intents() {
        let stage = body
            .schedule
            .stages
            .get(usize::from(intent.stage))
            .ok_or_else(|| {
                Error::new(
                    ErrorCode::CorruptStorage,
                    "bound relationship DELETE intent names a missing schedule stage",
                )
            })?;
        let ResidentRowBoundRelationshipStage::Delete { targets, .. } = stage else {
            return Err(Error::new(
                ErrorCode::CorruptStorage,
                "bound relationship DELETE intent names a non-DELETE schedule stage",
            ));
        };
        let target = targets.get(usize::from(intent.target)).ok_or_else(|| {
            Error::new(
                ErrorCode::CorruptStorage,
                "bound relationship DELETE intent names a missing target expression",
            )
        })?;
        if target.entity >= program.entity_slot_count {
            return Err(Error::new(
                ErrorCode::CorruptStorage,
                "bound relationship DELETE intent changed its immutable entity provenance",
            ));
        }
        let order = (
            intent.entity.kind == EntityKind::Node,
            intent.entity.target_id,
        );
        if prior_delete_order.is_some_and(|prior| prior >= order) {
            return Err(Error::new(
                ErrorCode::CorruptStorage,
                "bound relationship DELETE intents are not unique relationship-first stable IDs",
            ));
        }
        prior_delete_order = Some(order);
        match (
            intent.entity.kind,
            intent.entity.dense_row,
            intent.entity.created_by,
        ) {
            (EntityKind::Node, Some(dense), None) => {
                let node = context.graph.node_dense(dense).ok_or_else(|| {
                    Error::new(
                        ErrorCode::CorruptStorage,
                        "bound relationship DELETE node target disappeared",
                    )
                })?;
                if node.id().0 != intent.entity.target_id
                    || !validated
                        .read_dependencies()
                        .contains(&ResidentMutationReadDependency::Node(dense))
                    || !deleted_nodes.insert(intent.entity.target_id)
                {
                    return Err(Error::new(
                        ErrorCode::CorruptStorage,
                        "bound relationship DELETE node target changed identity or dependency",
                    ));
                }
            }
            (EntityKind::Relationship, Some(dense), None) => {
                let edge = context.graph.edge_dense(dense).ok_or_else(|| {
                    Error::new(
                        ErrorCode::CorruptStorage,
                        "bound relationship DELETE relationship target disappeared",
                    )
                })?;
                if edge.id().0 != intent.entity.target_id
                    || !validated
                        .read_dependencies()
                        .contains(&ResidentMutationReadDependency::Relationship(dense))
                    || !deleted_relationships.insert(intent.entity.target_id)
                {
                    return Err(Error::new(
                        ErrorCode::CorruptStorage,
                        "bound relationship DELETE relationship target changed identity or dependency",
                    ));
                }
            }
            (EntityKind::Node, None, Some(origin)) => {
                let local_target_matches = matches!(
                    program.commands.get(usize::from(origin.command)),
                    Some(ResidentRowCreateCommand::CreateNode(command))
                        if command.output_entity == target.entity
                            && origin.work_row == intent.work_row
                );
                if !local_target_matches
                    || context
                        .graph
                        .contains_node_id(NodeId(intent.entity.target_id))
                    || !deleted_nodes.insert(intent.entity.target_id)
                {
                    return Err(Error::new(
                        ErrorCode::CorruptStorage,
                        "bound relationship DELETE statement-local node changed creation provenance",
                    ));
                }
            }
            _ => {
                return Err(Error::new(
                    ErrorCode::CorruptStorage,
                    "bound relationship DELETE intent mixed immutable and statement-local provenance",
                ));
            }
        }
    }

    let mut command_after_delete = vec![false; program.commands.len()];
    let mut saw_delete = false;
    for stage in &body.schedule.stages {
        match stage {
            ResidentRowBoundRelationshipStage::Delete { .. } => saw_delete = true,
            ResidentRowBoundRelationshipStage::Command { command } => {
                if let Some(after_delete) = command_after_delete.get_mut(usize::from(*command)) {
                    *after_delete = saw_delete;
                }
            }
            ResidentRowBoundRelationshipStage::Unwind { .. }
            | ResidentRowBoundRelationshipStage::Project { .. } => {}
        }
    }

    let mut created_nodes = BTreeMap::new();
    let mut created_relationships = BTreeMap::new();
    for row in validated.work_rows() {
        for entity in &row.entities {
            match (entity.kind, entity.dense_row, entity.created_by) {
                (EntityKind::Node, Some(dense), None) => {
                    let node = context.graph.node_dense(dense).ok_or_else(|| {
                        Error::new(
                            ErrorCode::CorruptStorage,
                            "bound relationship MERGE node binding disappeared",
                        )
                    })?;
                    if node.id().0 != entity.target_id
                        || !validated
                            .read_dependencies()
                            .contains(&ResidentMutationReadDependency::Node(dense))
                    {
                        return Err(Error::new(
                            ErrorCode::CorruptStorage,
                            "bound relationship MERGE node binding has a wrong identity or dependency",
                        ));
                    }
                }
                (EntityKind::Node, None, Some(origin)) => {
                    if context.graph.contains_node_id(NodeId(entity.target_id))
                        || created_nodes
                            .insert(entity.target_id, origin)
                            .is_some_and(|prior| prior != origin)
                    {
                        return Err(Error::new(
                            ErrorCode::TransactionConflict,
                            "bound relationship MERGE created node identity already exists or changed provenance",
                        ));
                    }
                }
                (EntityKind::Relationship, Some(dense), None) => {
                    let edge = context.graph.edge_dense(dense).ok_or_else(|| {
                        Error::new(
                            ErrorCode::CorruptStorage,
                            "bound relationship MERGE relationship binding disappeared",
                        )
                    })?;
                    if edge.id().0 != entity.target_id
                        || !validated
                            .read_dependencies()
                            .contains(&ResidentMutationReadDependency::Relationship(dense))
                    {
                        return Err(Error::new(
                            ErrorCode::CorruptStorage,
                            "bound relationship MERGE relationship binding has a wrong identity or dependency",
                        ));
                    }
                }
                (EntityKind::Relationship, None, Some(origin)) => {
                    if context.graph.contains_edge_id(EdgeId(entity.target_id))
                        || created_relationships
                            .insert(entity.target_id, origin)
                            .is_some_and(|prior| prior != origin)
                    {
                        return Err(Error::new(
                            ErrorCode::TransactionConflict,
                            "bound relationship MERGE created identity already exists or changed provenance",
                        ));
                    }
                }
                _ => {
                    return Err(Error::new(
                        ErrorCode::CorruptStorage,
                        "bound relationship MERGE entity mixed immutable and statement-local provenance",
                    ));
                }
            }
        }
    }

    for (command_index, (command, semantics)) in
        program.commands.iter().zip(&body.commands).enumerate()
    {
        if !command_after_delete[command_index]
            || !matches!(semantics, ResidentRowBoundRelationshipCommand::MergeNode)
        {
            continue;
        }
        let ResidentRowCreateCommand::CreateNode(command) = command else {
            return Err(Error::new(
                ErrorCode::CorruptStorage,
                "bound relationship post-DELETE node MERGE lost structural alignment",
            ));
        };
        if validated.work_rows().iter().any(|row| {
            row.entities
                .get(usize::from(command.output_entity))
                .is_some_and(|entity| {
                    entity.kind != EntityKind::Node
                        || (entity.created_by.is_none()
                            && deleted_nodes.contains(&entity.target_id))
                })
        }) {
            return Err(Error::new(
                ErrorCode::CorruptStorage,
                "bound relationship post-DELETE node MERGE reused a tombstoned entity",
            ));
        }
    }

    // Verify every immutable or statement-local relationship result against its command-local
    // endpoint, direction, type, and exact key-property semantics. This is a publication
    // integrity check over the backend-authored work relation, not host-side candidate selection.
    for (command_index, (command, semantics)) in
        program.commands.iter().zip(&body.commands).enumerate()
    {
        let command_index = u16::try_from(command_index).map_err(|_| {
            Error::new(
                ErrorCode::CorruptStorage,
                "bound relationship MERGE command index exceeds u16",
            )
        })?;
        let ResidentRowCreateCommand::CreateRelationship(command) = command else {
            continue;
        };
        let direction = match semantics {
            ResidentRowBoundRelationshipCommand::MatchRelationship { direction, .. }
            | ResidentRowBoundRelationshipCommand::MergeRelationship { direction } => *direction,
            ResidentRowBoundRelationshipCommand::CreateRelationship => {
                ResidentRowBoundRelationshipDirection::Directed
            }
            ResidentRowBoundRelationshipCommand::MatchNode { .. }
            | ResidentRowBoundRelationshipCommand::MatchNodeIncludingWrites { .. }
            | ResidentRowBoundRelationshipCommand::CreateNode
            | ResidentRowBoundRelationshipCommand::MergeNode => continue,
        };
        for row in validated.work_rows() {
            let relationship = row
                .entities
                .get(usize::from(command.output_entity))
                .ok_or_else(|| {
                    Error::new(
                        ErrorCode::CorruptStorage,
                        "bound relationship MERGE output entity slot disappeared",
                    )
                })?;
            let source = row
                .entities
                .get(usize::from(command.source_entity))
                .filter(|entity| entity.kind == EntityKind::Node)
                .ok_or_else(|| {
                    Error::new(
                        ErrorCode::CorruptStorage,
                        "bound relationship MERGE source endpoint disappeared",
                    )
                })?;
            let target = row
                .entities
                .get(usize::from(command.target_entity))
                .filter(|entity| entity.kind == EntityKind::Node)
                .ok_or_else(|| {
                    Error::new(
                        ErrorCode::CorruptStorage,
                        "bound relationship MERGE target endpoint disappeared",
                    )
                })?;
            if command_after_delete[usize::from(command_index)]
                && (deleted_nodes.contains(&source.target_id)
                    || deleted_nodes.contains(&target.target_id)
                    || (relationship.created_by.is_none()
                        && deleted_relationships.contains(&relationship.target_id)))
            {
                return Err(Error::new(
                    ErrorCode::CorruptStorage,
                    "bound relationship post-DELETE MERGE reused a tombstoned endpoint or relationship",
                ));
            }
            match (relationship.dense_row, relationship.created_by) {
                (Some(dense), None) => {
                    if matches!(
                        semantics,
                        ResidentRowBoundRelationshipCommand::CreateRelationship
                    ) {
                        return Err(Error::new(
                            ErrorCode::CorruptStorage,
                            "ordered relationship CREATE reused an immutable relationship",
                        ));
                    }
                    let edge = context.graph.edge_dense(dense).ok_or_else(|| {
                        Error::new(
                            ErrorCode::CorruptStorage,
                            "bound relationship MERGE existing edge disappeared",
                        )
                    })?;
                    let endpoints_match = (edge.source().0 == source.target_id
                        && edge.target().0 == target.target_id)
                        || (direction == ResidentRowBoundRelationshipDirection::Undirected
                            && edge.source().0 == target.target_id
                            && edge.target().0 == source.target_id);
                    let type_matches = match semantics {
                        ResidentRowBoundRelationshipCommand::MatchRelationship {
                            relationship_types,
                            ..
                        } if relationship_types.is_empty() => true,
                        ResidentRowBoundRelationshipCommand::MatchRelationship {
                            relationship_types,
                            ..
                        } => relationship_types.iter().any(|relationship_type| {
                            program
                                .relationship_type_tokens
                                .get(usize::from(*relationship_type))
                                .copied()
                                .flatten()
                                == Some(edge.relationship_type())
                        }),
                        ResidentRowBoundRelationshipCommand::MergeRelationship { .. } => {
                            program
                                .relationship_type_tokens
                                .get(usize::from(command.relationship_type))
                                .copied()
                                .flatten()
                                == Some(edge.relationship_type())
                        }
                        ResidentRowBoundRelationshipCommand::MatchNode { .. }
                        | ResidentRowBoundRelationshipCommand::MatchNodeIncludingWrites {
                            ..
                        }
                        | ResidentRowBoundRelationshipCommand::CreateNode
                        | ResidentRowBoundRelationshipCommand::CreateRelationship
                        | ResidentRowBoundRelationshipCommand::MergeNode => false,
                    };
                    if !endpoints_match || !type_matches {
                        return Err(Error::new(
                            ErrorCode::CorruptStorage,
                            "bound relationship MERGE selected an immutable relationship with wrong direction, endpoints, or type",
                        ));
                    }
                    for property in &command.properties {
                        if body
                            .schedule
                            .property_bindings
                            .binary_search_by(|binding| {
                                (binding.command, binding.property_name)
                                    .cmp(&(command_index, property.property_name))
                            })
                            .is_ok()
                        {
                            // The sealed schedule validator has already replayed the work-row
                            // value slot and proved the selected candidate's exact dynamic key.
                            // The structural property is deliberately only a placeholder here.
                            continue;
                        }
                        let expected = resident_row_bound_property_value(
                            &request.input,
                            program,
                            row.source_row,
                            &property.value,
                        )?;
                        let actual = program
                            .property_tokens
                            .get(usize::from(property.property_name))
                            .copied()
                            .flatten()
                            .and_then(|property| edge.property(property))
                            .unwrap_or(ScalarValue::Null);
                        if matches!(expected, ScalarValue::Null) || actual != expected {
                            return Err(Error::new(
                                ErrorCode::CorruptStorage,
                                "bound relationship MERGE selected an immutable relationship with a non-exact key property",
                            ));
                        }
                    }
                }
                (None, Some(origin)) => {
                    let intent = validated
                        .intents()
                        .iter()
                        .find(|intent| {
                            intent.target_id == relationship.target_id
                                && intent.command == origin.command
                                && matches!(
                                    &intent.action,
                                    ResidentRowMutationWorkIntentAction::CreateRelationship { .. }
                                )
                        })
                        .ok_or_else(|| {
                            Error::new(
                                ErrorCode::CorruptStorage,
                                "bound relationship MERGE statement-local match lost its creation intent",
                            )
                        })?;
                    let ResidentRowMutationWorkIntentAction::CreateRelationship {
                        relationship_type,
                        source_node_id,
                        target_node_id,
                        properties,
                    } = &intent.action
                    else {
                        return Err(Error::new(
                            ErrorCode::CorruptStorage,
                            "bound relationship MERGE statement-local match names a non-relationship intent",
                        ));
                    };
                    let endpoints_match = (*source_node_id == source.target_id
                        && *target_node_id == target.target_id)
                        || (direction == ResidentRowBoundRelationshipDirection::Undirected
                            && *source_node_id == target.target_id
                            && *target_node_id == source.target_id);
                    let type_matches = match semantics {
                        ResidentRowBoundRelationshipCommand::MatchRelationship {
                            relationship_types,
                            ..
                        } => {
                            relationship_types.is_empty()
                                || relationship_types.contains(relationship_type)
                        }
                        ResidentRowBoundRelationshipCommand::MergeRelationship { .. } => {
                            *relationship_type == command.relationship_type
                        }
                        ResidentRowBoundRelationshipCommand::CreateRelationship => {
                            *relationship_type == command.relationship_type
                                && origin.command == command_index
                        }
                        ResidentRowBoundRelationshipCommand::MatchNode { .. }
                        | ResidentRowBoundRelationshipCommand::MatchNodeIncludingWrites {
                            ..
                        }
                        | ResidentRowBoundRelationshipCommand::CreateNode
                        | ResidentRowBoundRelationshipCommand::MergeNode => false,
                    };
                    if intent.command != origin.command
                        || intent.work_row != origin.work_row
                        || !endpoints_match
                        || !type_matches
                    {
                        return Err(Error::new(
                            ErrorCode::CorruptStorage,
                            "bound relationship MERGE selected a statement-local relationship with wrong provenance, direction, endpoints, or type",
                        ));
                    }
                    for property in &command.properties {
                        if body
                            .schedule
                            .property_bindings
                            .binary_search_by(|binding| {
                                (binding.command, binding.property_name)
                                    .cmp(&(command_index, property.property_name))
                            })
                            .is_ok()
                        {
                            // Dynamic properties were already replayed from the sealed schedule
                            // and compared with this intent by result validation.
                            continue;
                        }
                        let expected = resident_row_bound_property_value(
                            &request.input,
                            program,
                            row.source_row,
                            &property.value,
                        )?;
                        let actual = properties
                            .binary_search_by_key(&property.property_name, |property| {
                                property.property_name
                            })
                            .ok()
                            .map(|index| properties[index].value.clone())
                            .unwrap_or(ScalarValue::Null);
                        if matches!(expected, ScalarValue::Null) || actual != expected {
                            return Err(Error::new(
                                ErrorCode::CorruptStorage,
                                "bound relationship MERGE selected a statement-local relationship with a non-exact key property",
                            ));
                        }
                    }
                }
                _ => {
                    return Err(Error::new(
                        ErrorCode::CorruptStorage,
                        "bound relationship MERGE selected a relationship with mixed provenance",
                    ));
                }
            }
        }
    }

    let mut intent_node_ids = BTreeSet::new();
    let mut intent_relationship_ids = BTreeSet::new();
    for intent in validated.intents() {
        match &intent.action {
            ResidentRowMutationWorkIntentAction::CreateNode { .. } => {
                let Some(origin) = created_nodes.get(&intent.target_id).copied() else {
                    return Err(Error::new(
                        ErrorCode::CorruptStorage,
                        "bound relationship MERGE intent names a foreign node",
                    ));
                };
                if !intent_node_ids.insert(intent.target_id)
                    || intent.command != origin.command
                    || intent.work_row != origin.work_row
                {
                    return Err(Error::new(
                        ErrorCode::CorruptStorage,
                        "bound relationship MERGE node intent duplicated or changed creation leadership",
                    ));
                }
                let command = match program.commands.get(usize::from(intent.command)) {
                    Some(ResidentRowCreateCommand::CreateNode(command)) => command,
                    _ => {
                        return Err(Error::new(
                            ErrorCode::CorruptStorage,
                            "bound relationship MERGE node-intent command disappeared",
                        ));
                    }
                };
                if validated.work_rows().iter().all(|row| {
                    row.entities
                        .get(usize::from(command.output_entity))
                        .is_none_or(|entity| entity.target_id != intent.target_id)
                }) {
                    return Err(Error::new(
                        ErrorCode::CorruptStorage,
                        "bound relationship MERGE node creation has no result-row binding",
                    ));
                }
            }
            ResidentRowMutationWorkIntentAction::CreateRelationship {
                source_node_id,
                target_node_id,
                ..
            } => {
                let Some(origin) = created_relationships.get(&intent.target_id).copied() else {
                    return Err(Error::new(
                        ErrorCode::CorruptStorage,
                        "bound relationship MERGE intent names a foreign relationship",
                    ));
                };
                if !intent_relationship_ids.insert(intent.target_id)
                    || intent.command != origin.command
                    || intent.work_row != origin.work_row
                {
                    return Err(Error::new(
                        ErrorCode::CorruptStorage,
                        "bound relationship MERGE relationship intent duplicated or changed creation leadership",
                    ));
                }
                let command = match program.commands.get(usize::from(intent.command)) {
                    Some(ResidentRowCreateCommand::CreateRelationship(command)) => command,
                    _ => {
                        return Err(Error::new(
                            ErrorCode::CorruptStorage,
                            "bound relationship MERGE relationship-intent command disappeared",
                        ));
                    }
                };
                let matching_row = validated.work_rows().iter().find(|row| {
                    row.entities
                        .get(usize::from(command.output_entity))
                        .is_some_and(|entity| entity.target_id == intent.target_id)
                });
                let Some(row) = matching_row else {
                    return Err(Error::new(
                        ErrorCode::CorruptStorage,
                        "bound relationship MERGE relationship creation has no result-row binding",
                    ));
                };
                if row
                    .entities
                    .get(usize::from(command.source_entity))
                    .is_none_or(|entity| entity.target_id != *source_node_id)
                    || row
                        .entities
                        .get(usize::from(command.target_entity))
                        .is_none_or(|entity| entity.target_id != *target_node_id)
                    || (!created_nodes.contains_key(source_node_id)
                        && !context.graph.contains_node_id(NodeId(*source_node_id)))
                    || (!created_nodes.contains_key(target_node_id)
                        && !context.graph.contains_node_id(NodeId(*target_node_id)))
                {
                    return Err(Error::new(
                        ErrorCode::CorruptStorage,
                        "bound relationship MERGE intent endpoints disagree with their bound row",
                    ));
                }
            }
        }
    }
    if intent_node_ids.len() != created_nodes.len()
        || intent_relationship_ids.len() != created_relationships.len()
    {
        return Err(Error::new(
            ErrorCode::CorruptStorage,
            "bound relationship MERGE intents do not cover unique node and relationship creations exactly once",
        ));
    }

    let mut state = ExecutionState {
        graph: transaction_graph_view(context)?,
        temporal: transaction_temporal_view(context)?,
        mutations: Vec::new(),
        temporal_mutations: Vec::new(),
        dependencies,
        next_node_id: context.next_node_id,
        next_edge_id: context.next_edge_id,
        revision: context.mutation_revision,
        created_at: resolved_created_at(context.resolved_time_nanos),
        read_layers: plan.read_layers,
        write_layer: plan.write_layer,
        stats: StatementStats::default(),
        final_columns: Vec::new(),
        scope_columns: BTreeSet::new(),
        administrative: None,
        vector_searches: Vec::new(),
        resident_backend: None,
        allow_context_backend: true,
        resident_overlay_mutations: 0,
        existential_subquery_depth: 0,
        initial_scan_cap: None,
    };
    for intent in validated.delete_intents() {
        let ResidentRowBoundRelationshipStage::Delete { detach, .. } = body
            .schedule
            .stages
            .get(usize::from(intent.stage))
            .ok_or_else(|| Error::internal("validated DELETE stage disappeared"))?
        else {
            return Err(Error::internal(
                "validated DELETE intent changed schedule-stage kind",
            ));
        };
        if intent.entity.created_by.is_some() {
            // Statement-local targets are published from their sealed CREATE intent first, then
            // tombstoned below in lexical CREATE-before-DELETE order.
            continue;
        }
        match intent.entity.kind {
            EntityKind::Relationship => {
                let edge = EdgeId(intent.entity.target_id);
                if state.graph.edge(edge).is_none() {
                    return Err(Error::new(
                        ErrorCode::CorruptStorage,
                        "bound relationship DELETE relationship disappeared before publication",
                    ));
                }
                apply_mutation(
                    &mut state,
                    GraphMutation::DeleteEdge {
                        edge,
                        revision: context.mutation_revision,
                    },
                )?;
                state.stats.relationships_deleted =
                    state.stats.relationships_deleted.saturating_add(1);
            }
            EntityKind::Node => {
                let node = NodeId(intent.entity.target_id);
                if state.graph.node(node).is_none() {
                    return Err(Error::new(
                        ErrorCode::CorruptStorage,
                        "bound relationship DELETE node disappeared before publication",
                    ));
                }
                apply_mutation(
                    &mut state,
                    GraphMutation::DeleteNode {
                        node,
                        detach: *detach,
                        revision: context.mutation_revision,
                    },
                )
                .map_err(|error| {
                    if !*detach
                        && error.code == ErrorCode::QueryType
                        && error.message == "node still has relationships"
                    {
                        Error::new(
                            ErrorCode::CorruptStorage,
                            "backend authorized an ordinary DELETE for a connected node",
                        )
                    } else {
                        error
                    }
                })?;
                state.stats.nodes_deleted = state.stats.nodes_deleted.saturating_add(1);
            }
        }
    }
    let mut published_node_ids = BTreeSet::new();
    let mut published_relationship_ids = BTreeSet::new();
    for intent in validated.intents() {
        match &intent.action {
            ResidentRowMutationWorkIntentAction::CreateNode { labels, properties } => {
                if !published_node_ids.insert(intent.target_id)
                    || state.graph.node(NodeId(intent.target_id)).is_some()
                {
                    return Err(Error::new(
                        ErrorCode::CorruptStorage,
                        "bound relationship MERGE CREATE node reused a canonical identity",
                    ));
                }
                let mut resolved_labels = Vec::with_capacity(labels.len());
                for label in labels {
                    let name = program
                        .label_names
                        .get(usize::from(*label))
                        .ok_or_else(|| {
                            Error::new(
                                ErrorCode::CorruptStorage,
                                "bound relationship MERGE CREATE label name disappeared",
                            )
                        })?;
                    resolved_labels.push(intern_label(name, &mut state)?);
                }
                resolved_labels.sort_unstable();
                resolved_labels.dedup();
                let mut resolved_properties = Vec::with_capacity(properties.len());
                let mut unique_properties = BTreeSet::new();
                for property in properties {
                    if !unique_properties.insert(property.property_name) {
                        return Err(Error::new(
                            ErrorCode::CorruptStorage,
                            "bound relationship MERGE CREATE node duplicated a property",
                        ));
                    }
                    let name = program
                        .property_names
                        .get(usize::from(property.property_name))
                        .ok_or_else(|| {
                            Error::new(
                                ErrorCode::CorruptStorage,
                                "bound relationship MERGE CREATE node property name disappeared",
                            )
                        })?;
                    let property_id = intern_property(name, &mut state)?;
                    if !matches!(property.value, ScalarValue::Null) {
                        resolved_properties.push((property_id, property.value.clone()));
                    }
                }
                validate_node_properties(context.graph, &resolved_properties)?;
                apply_mutation(
                    &mut state,
                    GraphMutation::InsertNode(NodeInput {
                        id: NodeId(intent.target_id),
                        layer: request.write_layer,
                        revision: context.mutation_revision,
                        labels: resolved_labels,
                        properties: resolved_properties,
                    }),
                )?;
                state.next_node_id =
                    state
                        .next_node_id
                        .max(intent.target_id.checked_add(1).ok_or_else(|| {
                            Error::new(ErrorCode::ResultBudgetExceeded, "node ID space exhausted")
                        })?);
                state.stats.nodes_created = state.stats.nodes_created.saturating_add(1);
                state.stats.labels_added =
                    state.stats.labels_added.saturating_add(labels.len() as u64);
            }
            ResidentRowMutationWorkIntentAction::CreateRelationship {
                relationship_type,
                source_node_id,
                target_node_id,
                properties,
            } => {
                let edge_id = EdgeId(intent.target_id);
                if !published_relationship_ids.insert(intent.target_id)
                    || state.graph.edge(edge_id).is_some()
                    || state.graph.node(NodeId(*source_node_id)).is_none()
                    || state.graph.node(NodeId(*target_node_id)).is_none()
                {
                    return Err(Error::new(
                        ErrorCode::CorruptStorage,
                        "bound relationship MERGE CREATE relationship reused an identity or lost an endpoint",
                    ));
                }
                let relationship_name = program
                    .relationship_type_names
                    .get(usize::from(*relationship_type))
                    .ok_or_else(|| {
                        Error::new(
                            ErrorCode::CorruptStorage,
                            "bound relationship MERGE type name disappeared",
                        )
                    })?;
                let relationship_type = intern_relationship_type(relationship_name, &mut state)?;
                let mut resolved_properties = Vec::with_capacity(properties.len());
                let mut unique_properties = BTreeSet::new();
                for property in properties {
                    if !unique_properties.insert(property.property_name) {
                        return Err(Error::new(
                            ErrorCode::CorruptStorage,
                            "bound relationship MERGE CREATE relationship duplicated a property",
                        ));
                    }
                    let name = program
                        .property_names
                        .get(usize::from(property.property_name))
                        .ok_or_else(|| {
                            Error::new(
                                ErrorCode::CorruptStorage,
                                "bound relationship MERGE property name disappeared",
                            )
                        })?;
                    let property_id = intern_property(name, &mut state)?;
                    if !matches!(property.value, ScalarValue::Null) {
                        resolved_properties.push((property_id, property.value.clone()));
                    }
                }
                validate_edge_properties(context.graph, &resolved_properties)?;
                apply_mutation(
                    &mut state,
                    GraphMutation::InsertEdge(EdgeInput {
                        id: edge_id,
                        source: NodeId(*source_node_id),
                        target: NodeId(*target_node_id),
                        relationship_type,
                        layer: request.write_layer,
                        revision: context.mutation_revision,
                        properties: resolved_properties,
                    }),
                )?;
                state.next_edge_id =
                    state
                        .next_edge_id
                        .max(intent.target_id.checked_add(1).ok_or_else(|| {
                            Error::new(
                                ErrorCode::ResultBudgetExceeded,
                                "relationship ID space exhausted",
                            )
                        })?);
                state.stats.relationships_created =
                    state.stats.relationships_created.saturating_add(1);
            }
        }
    }

    for intent in validated
        .delete_intents()
        .iter()
        .filter(|intent| intent.entity.created_by.is_some())
    {
        let ResidentRowBoundRelationshipStage::Delete { detach, .. } = body
            .schedule
            .stages
            .get(usize::from(intent.stage))
            .ok_or_else(|| Error::internal("validated local DELETE stage disappeared"))?
        else {
            return Err(Error::internal(
                "validated local DELETE intent changed schedule-stage kind",
            ));
        };
        if intent.entity.kind != EntityKind::Node
            || *detach
            || !published_node_ids.contains(&intent.entity.target_id)
        {
            return Err(Error::new(
                ErrorCode::CorruptStorage,
                "bound relationship DELETE published an unsupported statement-local target",
            ));
        }
        let node = NodeId(intent.entity.target_id);
        if state.graph.node(node).is_none() {
            return Err(Error::new(
                ErrorCode::CorruptStorage,
                "bound relationship DELETE statement-local node was not created first",
            ));
        }
        apply_mutation(
            &mut state,
            GraphMutation::DeleteNode {
                node,
                detach: false,
                revision: context.mutation_revision,
            },
        )?;
        state.stats.nodes_deleted = state.stats.nodes_deleted.saturating_add(1);
    }

    // Resolve every dynamic source against the canonical graph before publishing any
    // conditional property mutation. This prevents one action in the same result from
    // becoming the source of a later action and preserves the graph-fenced read snapshot.
    let mut sealed_merge_property_modes =
        Vec::with_capacity(validated.merge_property_actions().len());
    for action in validated.merge_property_actions() {
        let mut descriptors = body.merge_property_sets.iter().filter(|descriptor| {
            descriptor.branch == action.branch
                && descriptor.trigger_command == action.trigger_command
                && descriptor.target_entity == action.target_entity
                && descriptor.property_name == action.property_name
        });
        let descriptor = descriptors.next().ok_or_else(|| {
            Error::new(
                ErrorCode::CorruptStorage,
                "bound MERGE property action changed its sealed descriptor identity",
            )
        })?;
        if descriptors.next().is_some() {
            return Err(Error::new(
                ErrorCode::CorruptStorage,
                "bound MERGE property action matched ambiguous sealed descriptors",
            ));
        }
        let row = validated
            .work_rows()
            .iter()
            .find(|row| row.work_row == action.work_row && row.source_row == action.source_row)
            .ok_or_else(|| {
                Error::new(
                    ErrorCode::CorruptStorage,
                    "bound MERGE property action lost its work row",
                )
            })?;
        let expected = match &descriptor.source {
            ResidentRowBoundMergePropertySource::Constant(value) => value.clone(),
            ResidentRowBoundMergePropertySource::EntityProperty {
                entity,
                property_name,
                maximum_payload_bytes,
            } => {
                let source = row.entities.get(usize::from(*entity)).ok_or_else(|| {
                    Error::new(
                        ErrorCode::CorruptStorage,
                        "bound MERGE property source entity disappeared",
                    )
                })?;
                if source.created_by.is_some() || source.dense_row.is_none() {
                    return Err(Error::new(
                        ErrorCode::CorruptStorage,
                        "bound MERGE property source escaped its immutable match binding",
                    ));
                }
                let source_property_name = program
                    .property_names
                    .get(usize::from(*property_name))
                    .ok_or_else(|| {
                        Error::new(
                            ErrorCode::CorruptStorage,
                            "bound MERGE source property name disappeared",
                        )
                    })?;
                let value = if let Some(property) = state.graph.property(source_property_name) {
                    match source.kind {
                        EntityKind::Node => state
                            .graph
                            .node(NodeId(source.target_id))
                            .ok_or_else(|| {
                                Error::new(
                                    ErrorCode::CorruptStorage,
                                    "bound MERGE source node disappeared before publication",
                                )
                            })?
                            .property(property)
                            .unwrap_or(ScalarValue::Null),
                        EntityKind::Relationship => state
                            .graph
                            .edge(EdgeId(source.target_id))
                            .ok_or_else(|| {
                                Error::new(
                                    ErrorCode::CorruptStorage,
                                    "bound MERGE source relationship disappeared before publication",
                                )
                            })?
                            .property(property)
                            .unwrap_or(ScalarValue::Null),
                    }
                } else {
                    ScalarValue::Null
                };
                if crate::execution::resident_row_bound_scalar_payload_bytes(&value)?
                    > *maximum_payload_bytes
                {
                    return Err(Error::new(
                        ErrorCode::CorruptStorage,
                        "bound MERGE property source exceeded its sealed payload bound",
                    ));
                }
                value
            }
        };
        if action.value != expected {
            return Err(Error::new(
                ErrorCode::CorruptStorage,
                "bound MERGE property action changed its sealed scalar source",
            ));
        }
        sealed_merge_property_modes.push(descriptor.mode);
    }

    let mut published_merge_property_actions = BTreeSet::new();
    for (action, mode) in validated
        .merge_property_actions()
        .iter()
        .zip(sealed_merge_property_modes)
    {
        let Some((trigger, semantics)) = program
            .commands
            .get(usize::from(action.trigger_command))
            .zip(body.commands.get(usize::from(action.trigger_command)))
        else {
            return Err(Error::new(
                ErrorCode::CorruptStorage,
                "bound MERGE property action lost its trigger command",
            ));
        };
        let trigger_entity = match (trigger, semantics) {
            (
                ResidentRowCreateCommand::CreateNode(trigger),
                ResidentRowBoundRelationshipCommand::MergeNode,
            ) => trigger.output_entity,
            (
                ResidentRowCreateCommand::CreateRelationship(trigger),
                ResidentRowBoundRelationshipCommand::MergeRelationship { .. },
            ) => trigger.output_entity,
            _ => {
                return Err(Error::new(
                    ErrorCode::CorruptStorage,
                    "bound MERGE property action escaped node/relationship MERGE",
                ));
            }
        };
        let row = validated
            .work_rows()
            .iter()
            .find(|row| row.work_row == action.work_row && row.source_row == action.source_row)
            .ok_or_else(|| {
                Error::new(
                    ErrorCode::CorruptStorage,
                    "bound MERGE property action lost its work row",
                )
            })?;
        let trigger_entity = row
            .entities
            .get(usize::from(trigger_entity))
            .ok_or_else(|| {
                Error::new(
                    ErrorCode::CorruptStorage,
                    "bound MERGE property trigger entity disappeared",
                )
            })?;
        let is_creation_leader = trigger_entity.created_by
            == Some(crate::execution::ResidentRowCreateEntityOrigin {
                command: action.trigger_command,
                work_row: action.work_row,
            });
        if !matches!(
            (action.branch, is_creation_leader),
            (ResidentRowBoundMergeBranch::Create, true)
                | (ResidentRowBoundMergeBranch::Match, false)
        ) {
            return Err(Error::new(
                ErrorCode::CorruptStorage,
                "bound MERGE property action fired for the wrong creation/match branch",
            ));
        }
        let target_entity = row
            .entities
            .get(usize::from(action.target_entity))
            .filter(|entity| entity.target_id == action.target_id)
            .ok_or_else(|| {
                Error::new(
                    ErrorCode::CorruptStorage,
                    "bound MERGE property target disagrees with its sealed row",
                )
            })?;
        if !published_merge_property_actions.insert((
            action.trigger_command,
            action.work_row,
            action.target_entity,
            action.property_name,
        )) {
            return Err(Error::new(
                ErrorCode::CorruptStorage,
                "bound MERGE property action was duplicated",
            ));
        }
        let property_name = program
            .property_names
            .get(usize::from(action.property_name))
            .ok_or_else(|| {
                Error::new(
                    ErrorCode::CorruptStorage,
                    "bound MERGE property name disappeared",
                )
            })?;
        let property = intern_property(property_name, &mut state)?;
        let target = match target_entity.kind {
            EntityKind::Node => {
                let node = NodeId(action.target_id);
                if state.graph.node(node).is_none() {
                    return Err(Error::new(
                        ErrorCode::CorruptStorage,
                        "bound MERGE property node target disappeared before publication",
                    ));
                }
                PropertyMutationTarget::Node(node)
            }
            EntityKind::Relationship => {
                let edge = EdgeId(action.target_id);
                if state.graph.edge(edge).is_none() {
                    return Err(Error::new(
                        ErrorCode::CorruptStorage,
                        "bound MERGE property relationship target disappeared before publication",
                    ));
                }
                PropertyMutationTarget::Relationship(edge)
            }
        };
        match mode {
            ResidentRowBoundMergePropertyMode::Set
            | ResidentRowBoundMergePropertyMode::ReplaceMap => {
                // A catalog-complete ReplaceMap stream carries Null for an absent source
                // key. The ordinary property mutation path interprets Null as removal.
                target.validate(context.graph, property, &action.value)?;
                apply_mutation(
                    &mut state,
                    target.mutation(property, action.value.clone(), context.mutation_revision),
                )?;
            }
        }
        state.stats.properties_set = state.stats.properties_set.saturating_add(1);
    }

    let mut published_merge_label_actions = BTreeSet::new();
    for action in validated.merge_label_actions() {
        let mut descriptors = body.merge_label_sets.iter().filter(|descriptor| {
            descriptor.branch == action.branch
                && descriptor.trigger_command == action.trigger_command
                && descriptor.target_entity == action.target_entity
                && descriptor.labels == action.labels
        });
        let descriptor = descriptors.next().ok_or_else(|| {
            Error::new(
                ErrorCode::CorruptStorage,
                "bound MERGE label action changed its sealed descriptor identity",
            )
        })?;
        if descriptors.next().is_some() {
            return Err(Error::new(
                ErrorCode::CorruptStorage,
                "bound MERGE label action matched ambiguous sealed descriptors",
            ));
        }
        let Some((trigger, semantics)) = program
            .commands
            .get(usize::from(action.trigger_command))
            .zip(body.commands.get(usize::from(action.trigger_command)))
        else {
            return Err(Error::new(
                ErrorCode::CorruptStorage,
                "bound MERGE label action lost its trigger command",
            ));
        };
        let trigger_entity = match (trigger, semantics) {
            (
                ResidentRowCreateCommand::CreateNode(trigger),
                ResidentRowBoundRelationshipCommand::MergeNode,
            ) => trigger.output_entity,
            _ => {
                return Err(Error::new(
                    ErrorCode::CorruptStorage,
                    "bound MERGE label action escaped node MERGE",
                ));
            }
        };
        let row = validated
            .work_rows()
            .iter()
            .find(|row| row.work_row == action.work_row && row.source_row == action.source_row)
            .ok_or_else(|| {
                Error::new(
                    ErrorCode::CorruptStorage,
                    "bound MERGE label action lost its work row",
                )
            })?;
        let trigger_entity = row
            .entities
            .get(usize::from(trigger_entity))
            .ok_or_else(|| {
                Error::new(
                    ErrorCode::CorruptStorage,
                    "bound MERGE label trigger entity disappeared",
                )
            })?;
        let is_creation_leader = trigger_entity.created_by
            == Some(crate::execution::ResidentRowCreateEntityOrigin {
                command: action.trigger_command,
                work_row: action.work_row,
            });
        if !matches!(
            (action.branch, is_creation_leader),
            (ResidentRowBoundMergeBranch::Create, true)
                | (ResidentRowBoundMergeBranch::Match, false)
        ) {
            return Err(Error::new(
                ErrorCode::CorruptStorage,
                "bound MERGE label action fired for the wrong creation/match branch",
            ));
        }
        let target = row
            .entities
            .get(usize::from(action.target_entity))
            .filter(|entity| {
                entity.kind == EntityKind::Node && entity.target_id == action.target_id
            })
            .ok_or_else(|| {
                Error::new(
                    ErrorCode::CorruptStorage,
                    "bound MERGE label target disagrees with its sealed row",
                )
            })?;
        if target.target_id != action.target_id
            || !published_merge_label_actions.insert((
                action.trigger_command,
                action.work_row,
                action.target_entity,
                action.labels.clone(),
            ))
        {
            return Err(Error::new(
                ErrorCode::CorruptStorage,
                "bound MERGE label action was duplicated",
            ));
        }
        let node_id = NodeId(action.target_id);
        let existing = state
            .graph
            .node(node_id)
            .ok_or_else(|| {
                Error::new(
                    ErrorCode::CorruptStorage,
                    "bound MERGE label node target disappeared before publication",
                )
            })?
            .labels()
            .iter()
            .copied()
            .collect::<BTreeSet<_>>();
        let mut labels = Vec::with_capacity(descriptor.labels.len());
        for label in &descriptor.labels {
            let name = program
                .label_names
                .get(usize::from(*label))
                .ok_or_else(|| {
                    Error::new(
                        ErrorCode::CorruptStorage,
                        "bound MERGE label name disappeared",
                    )
                })?;
            let label = intern_label(name, &mut state)?;
            if !existing.contains(&label) {
                labels.push(label);
            }
        }
        labels.sort_unstable();
        labels.dedup();
        if !labels.is_empty() {
            let added = u64::try_from(labels.len()).map_err(|_| {
                Error::new(
                    ErrorCode::ResultBudgetExceeded,
                    "bound MERGE added-label count exceeds u64",
                )
            })?;
            apply_mutation(
                &mut state,
                GraphMutation::AddNodeLabels {
                    node: node_id,
                    labels,
                    revision: context.mutation_revision,
                },
            )?;
            state.stats.labels_added = state.stats.labels_added.saturating_add(added);
        }
    }

    let mut decoded_columns = Vec::with_capacity(body.outputs.len());
    for (output, column) in body.outputs.iter().zip(validated.columns()) {
        let values = match (output, column) {
            (
                ResidentRowBoundRelationshipOutput::CountRows { .. }
                | ResidentRowBoundRelationshipOutput::CountEntity { .. }
                | ResidentRowBoundRelationshipOutput::CountOptionalUndirectedRelationships { .. },
                ResidentRowBoundRelationshipColumn::Count { value, .. },
            ) => vec![ResultValue::Scalar(ScalarValue::Integer(
                i64::try_from(*value).map_err(|_| {
                    Error::new(
                        ErrorCode::ResultBudgetExceeded,
                        "bound relationship MERGE count exceeds INTEGER",
                    )
                })?,
            ))],
            (
                ResidentRowBoundRelationshipOutput::Entity { .. },
                ResidentRowBoundRelationshipColumn::Entity { values, .. },
            ) => values
                .iter()
                .map(|entity| match entity.kind {
                    EntityKind::Node => {
                        let node = state.graph.node(NodeId(entity.target_id)).ok_or_else(|| {
                            Error::new(
                                ErrorCode::CorruptStorage,
                                "bound relationship MERGE result node disappeared",
                            )
                        })?;
                        materialize_node(&state.graph, node.dense()).map(ResultValue::Node)
                    }
                    EntityKind::Relationship => {
                        let edge = state.graph.edge(EdgeId(entity.target_id)).ok_or_else(|| {
                            Error::new(
                                ErrorCode::CorruptStorage,
                                "bound relationship MERGE result relationship disappeared",
                            )
                        })?;
                        materialize_edge(&state.graph, edge.dense()).map(ResultValue::Relationship)
                    }
                })
                .collect::<Result<Vec<_>>>()?,
            (
                ResidentRowBoundRelationshipOutput::Labels { .. },
                ResidentRowBoundRelationshipColumn::Entity { values, .. },
            ) => values
                .iter()
                .map(|entity| {
                    if entity.kind != EntityKind::Node {
                        return Err(Error::new(
                            ErrorCode::CorruptStorage,
                            "bound relationship labels output changed entity kind",
                        ));
                    }
                    let node = state.graph.node(NodeId(entity.target_id)).ok_or_else(|| {
                        Error::new(
                            ErrorCode::CorruptStorage,
                            "bound relationship labels output node disappeared",
                        )
                    })?;
                    render_resident_node_labels(
                        ResultValue::Node(materialize_node(&state.graph, node.dense())?),
                        false,
                    )
                })
                .collect::<Result<Vec<_>>>()?,
            (
                ResidentRowBoundRelationshipOutput::Path {
                    start_entity,
                    relationship_entity,
                    end_entity,
                    ..
                },
                ResidentRowBoundRelationshipColumn::Entity { values, .. },
            ) => validated
                .work_rows()
                .iter()
                .zip(values)
                .map(|(row, relationship)| {
                    let start = row
                        .entities
                        .get(usize::from(*start_entity))
                        .filter(|entity| entity.kind == EntityKind::Node)
                        .ok_or_else(|| {
                            Error::new(
                                ErrorCode::CorruptStorage,
                                "bound relationship MERGE path start node disappeared",
                            )
                        })?;
                    let sealed_relationship = row
                        .entities
                        .get(usize::from(*relationship_entity))
                        .filter(|entity| entity.kind == EntityKind::Relationship)
                        .ok_or_else(|| {
                            Error::new(
                                ErrorCode::CorruptStorage,
                                "bound relationship MERGE path relationship disappeared",
                            )
                        })?;
                    let end = row
                        .entities
                        .get(usize::from(*end_entity))
                        .filter(|entity| entity.kind == EntityKind::Node)
                        .ok_or_else(|| {
                            Error::new(
                                ErrorCode::CorruptStorage,
                                "bound relationship MERGE path end node disappeared",
                            )
                        })?;
                    if relationship != sealed_relationship {
                        return Err(Error::new(
                            ErrorCode::CorruptStorage,
                            "bound relationship MERGE path column changed its relationship binding",
                        ));
                    }
                    let start = state.graph.node(NodeId(start.target_id)).ok_or_else(|| {
                        Error::new(
                            ErrorCode::CorruptStorage,
                            "bound relationship MERGE path start node was not published",
                        )
                    })?;
                    let relationship = state
                        .graph
                        .edge(EdgeId(relationship.target_id))
                        .ok_or_else(|| {
                            Error::new(
                                ErrorCode::CorruptStorage,
                                "bound relationship MERGE path relationship was not published",
                            )
                        })?;
                    let end = state.graph.node(NodeId(end.target_id)).ok_or_else(|| {
                        Error::new(
                            ErrorCode::CorruptStorage,
                            "bound relationship MERGE path end node was not published",
                        )
                    })?;
                    Ok(ResultValue::Path {
                        nodes: vec![
                            materialize_node(&state.graph, start.dense())?,
                            materialize_node(&state.graph, end.dense())?,
                        ],
                        relationships: vec![materialize_edge(&state.graph, relationship.dense())?],
                    })
                })
                .collect::<Result<Vec<_>>>()?,
            (
                ResidentRowBoundRelationshipOutput::Property {
                    entity,
                    property_name,
                    ..
                },
                ResidentRowBoundRelationshipColumn::Scalar { values, .. },
            ) => {
                let property = program
                    .property_names
                    .get(usize::from(*property_name))
                    .and_then(|name| state.graph.property(name));
                for (row, actual) in validated.work_rows().iter().zip(values) {
                    let entity = row.entities.get(usize::from(*entity)).ok_or_else(|| {
                        Error::new(
                            ErrorCode::CorruptStorage,
                            "bound relationship MERGE property entity disappeared",
                        )
                    })?;
                    let expected = property.map_or(ScalarValue::Null, |property| {
                        match entity.kind {
                            EntityKind::Node => state
                                .graph
                                .node(NodeId(entity.target_id))
                                .and_then(|node| node.property(property)),
                            EntityKind::Relationship => state
                                .graph
                                .edge(EdgeId(entity.target_id))
                                .and_then(|edge| edge.property(property)),
                        }
                        .unwrap_or(ScalarValue::Null)
                    });
                    if *actual != expected {
                        return Err(Error::new(
                            ErrorCode::CorruptStorage,
                            "bound relationship MERGE scalar output disagrees with its entity property",
                        ));
                    }
                }
                values
                    .iter()
                    .cloned()
                    .map(ResultValue::from_property)
                    .collect::<Result<Vec<_>>>()?
            }
            _ => {
                return Err(Error::new(
                    ErrorCode::CorruptStorage,
                    "bound relationship MERGE validated output changed shape",
                ));
            }
        };
        decoded_columns.push(values);
    }
    let schema = body
        .outputs
        .iter()
        .zip(&decoded_columns)
        .map(|(output, values)| (output.name().to_owned(), result_values_type(values)))
        .collect::<Vec<_>>();
    let row_count = decoded_columns.first().map_or(0, Vec::len);
    if decoded_columns
        .iter()
        .any(|values| values.len() != row_count)
    {
        return Err(Error::new(
            ErrorCode::CorruptStorage,
            "bound relationship MERGE final columns have different cardinalities",
        ));
    }
    let mut batches = Vec::new();
    let batch_rows = context.max_batch_rows.max(1);
    for start in (0..row_count).step_by(batch_rows) {
        let end = start.saturating_add(batch_rows).min(row_count);
        batches.push(ResultBatch {
            row_count: end - start,
            columns: body
                .outputs
                .iter()
                .zip(&schema)
                .zip(&decoded_columns)
                .map(|((output, (_, value_type)), values)| ResultColumn {
                    name: output.name().to_owned(),
                    value_type: value_type.clone(),
                    values: values[start..end].to_vec(),
                })
                .collect(),
        });
    }

    Ok(ExecutionOutput {
        result: QueryResult {
            schema,
            batches,
            bookmark: context.bookmark,
            statistics: state.stats,
            truncated: false,
        },
        graph_mutations: state.mutations,
        temporal_mutations: state.temporal_mutations,
        dependencies: state.dependencies,
        administrative: None,
        vector_searches: Vec::new(),
        runtime_replans: 0,
    })
}

#[allow(clippy::too_many_lines)]
fn execute_resident_row_create_plan(
    plan: &PhysicalPlan,
    request: &crate::execution::ResidentRowMutationRequest,
    validated: &ValidatedResidentRowCreate,
    context: &ExecutionContext<'_>,
) -> Result<ExecutionOutput> {
    let body = request.create_body().ok_or_else(|| {
        Error::new(
            ErrorCode::CorruptStorage,
            "validated resident row CREATE lost its immutable program",
        )
    })?;
    let program = &body.program;

    let mut dependencies = TransactionDependencies::default();
    for dependency in &plan.dependencies {
        let version = context
            .predicate_versions
            .get(dependency)
            .copied()
            .unwrap_or(context.bookmark.index);
        dependencies.predicates.insert(dependency.clone(), version);
    }
    for dependency in validated.read_dependencies() {
        let ResidentMutationReadDependency::Node(dense) = *dependency else {
            return Err(Error::new(
                ErrorCode::CorruptStorage,
                "resident row CREATE returned a non-node immutable dependency",
            ));
        };
        let node = context.graph.node_dense(dense).ok_or_else(|| {
            Error::new(
                ErrorCode::CorruptStorage,
                "resident row CREATE dependency names a missing node",
            )
        })?;
        if node.revision() > context.graph.revision()
            || !plan.read_layers.contains_layer(node.layer())
        {
            return Err(Error::new(
                ErrorCode::CorruptStorage,
                "resident row CREATE dependency is outside its immutable visible generation",
            ));
        }
        dependencies
            .entities
            .insert(EntityDependency::Node(node.id()), node.revision());
    }

    // Re-resolve every backend-authored entity cell before interning any name or publishing any
    // graph effect. This is an identity/generation check only; label selection, Cartesian MATCH,
    // endpoint binding and statement-local provenance were already backend work and are proved by
    // the validated lineage and receipts.
    let mut created_node_ids = BTreeSet::new();
    let mut created_relationship_ids = BTreeSet::new();
    for row in validated.work_rows() {
        for entity in &row.entities {
            match (entity.kind, entity.dense_row, entity.created_by) {
                (EntityKind::Node, Some(dense), None) => {
                    let node = context.graph.node_dense(dense).ok_or_else(|| {
                        Error::new(
                            ErrorCode::CorruptStorage,
                            "resident row CREATE MATCH entity disappeared",
                        )
                    })?;
                    if node.id().0 != entity.target_id
                        || !validated
                            .read_dependencies()
                            .contains(&ResidentMutationReadDependency::Node(dense))
                    {
                        return Err(Error::new(
                            ErrorCode::CorruptStorage,
                            "resident row CREATE MATCH entity has a wrong identity or missing dependency",
                        ));
                    }
                }
                (EntityKind::Node, None, Some(_)) => {
                    if context.graph.contains_node_id(NodeId(entity.target_id))
                        || !created_node_ids.insert(entity.target_id)
                    {
                        return Err(Error::new(
                            ErrorCode::TransactionConflict,
                            "resident row CREATE node identity already exists or is duplicated",
                        ));
                    }
                }
                (EntityKind::Relationship, None, Some(_)) => {
                    if context.graph.contains_edge_id(EdgeId(entity.target_id))
                        || !created_relationship_ids.insert(entity.target_id)
                    {
                        return Err(Error::new(
                            ErrorCode::TransactionConflict,
                            "resident row CREATE relationship identity already exists or is duplicated",
                        ));
                    }
                }
                _ => {
                    return Err(Error::new(
                        ErrorCode::CorruptStorage,
                        "resident row CREATE entity mixed immutable and statement-local provenance",
                    ));
                }
            }
        }
    }

    let mut intent_node_ids = BTreeSet::new();
    let mut intent_relationship_ids = BTreeSet::new();
    for intent in validated.intents() {
        match &intent.action {
            ResidentRowMutationWorkIntentAction::CreateNode { .. } => {
                if !created_node_ids.contains(&intent.target_id)
                    || !intent_node_ids.insert(intent.target_id)
                {
                    return Err(Error::new(
                        ErrorCode::CorruptStorage,
                        "resident row CREATE node intent does not name exactly one created entity",
                    ));
                }
            }
            ResidentRowMutationWorkIntentAction::CreateRelationship {
                source_node_id,
                target_node_id,
                ..
            } => {
                if !created_relationship_ids.contains(&intent.target_id)
                    || !intent_relationship_ids.insert(intent.target_id)
                    || (!created_node_ids.contains(source_node_id)
                        && !context.graph.contains_node_id(NodeId(*source_node_id)))
                    || (!created_node_ids.contains(target_node_id)
                        && !context.graph.contains_node_id(NodeId(*target_node_id)))
                {
                    return Err(Error::new(
                        ErrorCode::CorruptStorage,
                        "resident row CREATE relationship intent has a foreign identity or endpoint",
                    ));
                }
            }
        }
    }
    if intent_node_ids != created_node_ids || intent_relationship_ids != created_relationship_ids {
        return Err(Error::new(
            ErrorCode::CorruptStorage,
            "resident row CREATE intents do not cover every statement-local entity exactly once",
        ));
    }

    let mut state = ExecutionState {
        graph: transaction_graph_view(context)?,
        temporal: transaction_temporal_view(context)?,
        mutations: Vec::new(),
        temporal_mutations: Vec::new(),
        dependencies,
        next_node_id: context.next_node_id,
        next_edge_id: context.next_edge_id,
        revision: context.mutation_revision,
        created_at: resolved_created_at(context.resolved_time_nanos),
        read_layers: plan.read_layers,
        write_layer: plan.write_layer,
        stats: StatementStats::default(),
        final_columns: Vec::new(),
        scope_columns: BTreeSet::new(),
        administrative: None,
        vector_searches: Vec::new(),
        resident_backend: None,
        allow_context_backend: true,
        resident_overlay_mutations: 0,
        existential_subquery_depth: 0,
        initial_scan_cap: None,
    };

    let mut published_node_ids = BTreeSet::new();
    let mut published_relationship_ids = BTreeSet::new();
    for intent in validated.intents() {
        match &intent.action {
            ResidentRowMutationWorkIntentAction::CreateNode { labels, properties } => {
                if !published_node_ids.insert(intent.target_id)
                    || state.graph.node(NodeId(intent.target_id)).is_some()
                {
                    return Err(Error::new(
                        ErrorCode::CorruptStorage,
                        "resident row CREATE node publication reused an identity",
                    ));
                }
                let mut resolved_labels = Vec::with_capacity(labels.len());
                for label in labels {
                    let name = program
                        .label_names
                        .get(usize::from(*label))
                        .ok_or_else(|| {
                            Error::new(
                                ErrorCode::CorruptStorage,
                                "resident row CREATE label name disappeared",
                            )
                        })?;
                    resolved_labels.push(intern_label(name, &mut state)?);
                }
                resolved_labels.sort_unstable();
                resolved_labels.dedup();
                let mut resolved_properties = Vec::with_capacity(properties.len());
                let mut unique_properties = BTreeSet::new();
                for property in properties {
                    if !unique_properties.insert(property.property_name) {
                        return Err(Error::new(
                            ErrorCode::CorruptStorage,
                            "resident row CREATE node duplicated a property",
                        ));
                    }
                    let name = program
                        .property_names
                        .get(usize::from(property.property_name))
                        .ok_or_else(|| {
                            Error::new(
                                ErrorCode::CorruptStorage,
                                "resident row CREATE node property name disappeared",
                            )
                        })?;
                    let property_id = intern_property(name, &mut state)?;
                    if !matches!(property.value, ScalarValue::Null) {
                        resolved_properties.push((property_id, property.value.clone()));
                    }
                }
                validate_node_properties(context.graph, &resolved_properties)?;
                apply_mutation(
                    &mut state,
                    GraphMutation::InsertNode(NodeInput {
                        id: NodeId(intent.target_id),
                        layer: request.write_layer,
                        revision: context.mutation_revision,
                        labels: resolved_labels,
                        properties: resolved_properties,
                    }),
                )?;
                state.next_node_id =
                    state
                        .next_node_id
                        .max(intent.target_id.checked_add(1).ok_or_else(|| {
                            Error::new(ErrorCode::ResultBudgetExceeded, "node ID space exhausted")
                        })?);
                state.stats.nodes_created = state.stats.nodes_created.saturating_add(1);
                state.stats.labels_added =
                    state.stats.labels_added.saturating_add(labels.len() as u64);
            }
            ResidentRowMutationWorkIntentAction::CreateRelationship {
                relationship_type,
                source_node_id,
                target_node_id,
                properties,
            } => {
                if !published_relationship_ids.insert(intent.target_id)
                    || state.graph.edge(EdgeId(intent.target_id)).is_some()
                    || state.graph.node(NodeId(*source_node_id)).is_none()
                    || state.graph.node(NodeId(*target_node_id)).is_none()
                {
                    return Err(Error::new(
                        ErrorCode::CorruptStorage,
                        "resident row CREATE relationship publication lost an endpoint or reused an identity",
                    ));
                }
                let relationship_name = program
                    .relationship_type_names
                    .get(usize::from(*relationship_type))
                    .ok_or_else(|| {
                        Error::new(
                            ErrorCode::CorruptStorage,
                            "resident row CREATE relationship type disappeared",
                        )
                    })?;
                let relationship_type = intern_relationship_type(relationship_name, &mut state)?;
                let mut resolved_properties = Vec::with_capacity(properties.len());
                let mut unique_properties = BTreeSet::new();
                for property in properties {
                    if !unique_properties.insert(property.property_name) {
                        return Err(Error::new(
                            ErrorCode::CorruptStorage,
                            "resident row CREATE relationship duplicated a property",
                        ));
                    }
                    let name = program
                        .property_names
                        .get(usize::from(property.property_name))
                        .ok_or_else(|| {
                            Error::new(
                                ErrorCode::CorruptStorage,
                                "resident row CREATE relationship property name disappeared",
                            )
                        })?;
                    let property_id = intern_property(name, &mut state)?;
                    if !matches!(property.value, ScalarValue::Null) {
                        resolved_properties.push((property_id, property.value.clone()));
                    }
                }
                validate_edge_properties(context.graph, &resolved_properties)?;
                apply_mutation(
                    &mut state,
                    GraphMutation::InsertEdge(EdgeInput {
                        id: EdgeId(intent.target_id),
                        source: NodeId(*source_node_id),
                        target: NodeId(*target_node_id),
                        relationship_type,
                        layer: request.write_layer,
                        revision: context.mutation_revision,
                        properties: resolved_properties,
                    }),
                )?;
                state.next_edge_id =
                    state
                        .next_edge_id
                        .max(intent.target_id.checked_add(1).ok_or_else(|| {
                            Error::new(
                                ErrorCode::ResultBudgetExceeded,
                                "relationship ID space exhausted",
                            )
                        })?);
                state.stats.relationships_created =
                    state.stats.relationships_created.saturating_add(1);
            }
        }
    }

    let (output_names, decoded_columns, row_count) = if let Some(continuation) =
        &program.continuation
    {
        let relation = validated.final_relation().ok_or_else(|| {
            Error::new(
                ErrorCode::CorruptStorage,
                "validated resident row CREATE continuation lost its final relation",
            )
        })?;
        let mut decoded = Vec::with_capacity(continuation.outputs.len());
        for (output, column) in continuation.outputs.iter().zip(&relation.columns) {
            let values = match (output.source, column) {
                    (
                        ResidentRowCreateProjectionSource::Entity(entity_slot),
                        ResidentRowCreateContinuationColumn::Entity { .. },
                    ) => relation
                        .work_rows
                        .iter()
                        .map(|work_row| {
                            let row = validated
                                .work_rows()
                                .get(usize::try_from(*work_row).map_err(|_| {
                                    Error::new(
                                        ErrorCode::CorruptStorage,
                                        "resident row CREATE result work row exceeds usize",
                                    )
                                })?)
                                .ok_or_else(|| {
                                    Error::new(
                                        ErrorCode::CorruptStorage,
                                        "resident row CREATE result work row disappeared",
                                    )
                                })?;
                            let entity = row
                                .entities
                                .get(usize::from(entity_slot))
                                .ok_or_else(|| {
                                    Error::new(
                                        ErrorCode::CorruptStorage,
                                        "resident row CREATE result entity slot disappeared",
                                    )
                                })?;
                            match entity.kind {
                                EntityKind::Node => {
                                    let node = state
                                        .graph
                                        .node(NodeId(entity.target_id))
                                        .ok_or_else(|| {
                                            Error::new(
                                                ErrorCode::CorruptStorage,
                                                "resident row CREATE result node was not published",
                                            )
                                        })?;
                                    materialize_node(&state.graph, node.dense())
                                        .map(ResultValue::Node)
                                }
                                EntityKind::Relationship => {
                                    let edge = state
                                        .graph
                                        .edge(EdgeId(entity.target_id))
                                        .ok_or_else(|| {
                                            Error::new(
                                                ErrorCode::CorruptStorage,
                                                "resident row CREATE result relationship was not published",
                                            )
                                        })?;
                                    materialize_edge(&state.graph, edge.dense())
                                        .map(ResultValue::Relationship)
                                }
                            }
                        })
                        .collect::<Result<Vec<_>>>()?,
                    (
                        ResidentRowCreateProjectionSource::IntegerProperty { .. }
                        | ResidentRowCreateProjectionSource::AggregateInteger,
                        ResidentRowCreateContinuationColumn::Integer {
                            values, validity, ..
                        },
                    ) => values
                        .iter()
                        .zip(validity)
                        .map(|(value, valid)| {
                            ResultValue::Scalar(if *valid == 0 {
                                ScalarValue::Null
                            } else {
                                ScalarValue::Integer(*value)
                            })
                        })
                        .collect(),
                    _ => {
                        return Err(Error::new(
                            ErrorCode::CorruptStorage,
                            "resident row CREATE continuation changed its validated output type",
                        ));
                    }
                };
            decoded.push(values);
        }
        (
            continuation
                .outputs
                .iter()
                .map(|output| output.name.clone())
                .collect::<Vec<_>>(),
            decoded,
            usize::try_from(relation.row_count).map_err(|_| {
                Error::new(
                    ErrorCode::CorruptStorage,
                    "resident row CREATE result cardinality exceeds usize",
                )
            })?,
        )
    } else {
        (
            program
                .outputs
                .iter()
                .map(|output| output.name.clone())
                .collect::<Vec<_>>(),
            validated
                .columns()
                .iter()
                .map(|column| {
                    column
                        .values
                        .iter()
                        .cloned()
                        .map(ResultValue::Scalar)
                        .collect::<Vec<_>>()
                })
                .collect::<Vec<_>>(),
            validated.work_rows().len(),
        )
    };
    if decoded_columns
        .iter()
        .any(|values| values.len() != row_count)
    {
        return Err(Error::new(
            ErrorCode::CorruptStorage,
            "resident row CREATE final columns have different cardinalities",
        ));
    }
    let schema = output_names
        .iter()
        .zip(&decoded_columns)
        .map(|(name, values)| (name.clone(), result_values_type(values)))
        .collect::<Vec<_>>();
    let mut batches = Vec::new();
    if !output_names.is_empty() {
        let batch_rows = context.max_batch_rows.max(1);
        for start in (0..row_count).step_by(batch_rows) {
            let end = start.saturating_add(batch_rows).min(row_count);
            batches.push(ResultBatch {
                row_count: end - start,
                columns: output_names
                    .iter()
                    .zip(&schema)
                    .zip(&decoded_columns)
                    .map(|((name, (_, value_type)), values)| ResultColumn {
                        name: name.clone(),
                        value_type: value_type.clone(),
                        values: values[start..end].to_vec(),
                    })
                    .collect(),
            });
        }
    }

    Ok(ExecutionOutput {
        result: QueryResult {
            schema,
            batches,
            bookmark: context.bookmark,
            statistics: state.stats,
            truncated: false,
        },
        graph_mutations: state.mutations,
        temporal_mutations: state.temporal_mutations,
        dependencies: state.dependencies,
        administrative: None,
        vector_searches: Vec::new(),
        runtime_replans: 0,
    })
}

fn execute_resident_row_mutation_plan(
    plan: &PhysicalPlan,
    compiled: &CompiledResidentRowMutationPlan,
    backend: &dyn ExecutionBackend,
    context: &ExecutionContext<'_>,
    stream: &mut Option<&mut dyn FnMut(ExecutionStreamItem) -> Result<()>>,
) -> Result<ExecutionOutput> {
    if stream.is_some() {
        return Err(Error::internal(
            "resident row mutation cannot enter the read-only streaming API",
        ));
    }
    let request = &compiled.request;
    request.validate()?;
    if request.generation.project != context.project_id
        || request.generation.bookmark != context.bookmark
        || request.generation.graph_revision != context.graph.revision()
        || request.generation.layout_version != context.graph.layout_version()
        || request.generation.catalog_generation != context.binding_catalog.optimizer_generation()
        || request.read_layers != plan.read_layers
        || request.write_layer != plan.write_layer
        || request
            .program
            .property_names
            .iter()
            .zip(&request.program.property_tokens)
            .any(|(name, token)| context.binding_catalog.property(name) != *token)
        || request
            .program
            .label_names
            .iter()
            .zip(&request.program.label_tokens)
            .any(|(name, token)| context.binding_catalog.label(name) != *token)
        || request
            .match_merge_relationship
            .as_ref()
            .is_some_and(|program| {
                program
                    .relationship_type_names
                    .iter()
                    .zip(&program.relationship_type_tokens)
                    .any(|(name, token)| context.binding_catalog.relationship_type(name) != *token)
            })
        || request.create_body().is_some_and(|body| {
            body.program
                .property_names
                .iter()
                .zip(&body.program.property_tokens)
                .any(|(name, token)| context.binding_catalog.property(name) != *token)
                || body
                    .program
                    .label_names
                    .iter()
                    .zip(&body.program.label_tokens)
                    .any(|(name, token)| context.binding_catalog.label(name) != *token)
                || body
                    .program
                    .relationship_type_names
                    .iter()
                    .zip(&body.program.relationship_type_tokens)
                    .any(|(name, token)| context.binding_catalog.relationship_type(name) != *token)
        })
        || request.bound_relationship_merge_body().is_some_and(|body| {
            body.program
                .property_names
                .iter()
                .zip(&body.program.property_tokens)
                .any(|(name, token)| context.binding_catalog.property(name) != *token)
                || body
                    .program
                    .label_names
                    .iter()
                    .zip(&body.program.label_tokens)
                    .any(|(name, token)| context.binding_catalog.label(name) != *token)
                || body
                    .program
                    .relationship_type_names
                    .iter()
                    .zip(&body.program.relationship_type_tokens)
                    .any(|(name, token)| context.binding_catalog.relationship_type(name) != *token)
        })
    {
        return Err(Error::new(
            ErrorCode::GpuAdmissionFailure,
            "resident row mutation compiler generation or catalog no longer matches the canonical statement",
        ));
    }

    check_execution(context)?;
    let pinned = backend.pin_project(context.project_id)?;
    if pinned.resident_bookmark(context.project_id) != Some(context.bookmark)
        || pinned.resident_graph_revision(context.project_id) != Some(context.graph.revision())
    {
        return Err(Error::new(
            ErrorCode::GpuAdmissionFailure,
            "pinned row-mutation backend does not own the requested immutable generation",
        ));
    }
    let raw = pinned.execute_row_mutation(request, &context.cancellation)?;
    let validated = raw.validate_for_publication(request, pinned.kind())?;
    check_execution(context)?;

    if let Some(generalized) = validated.match_merge_relationship() {
        return execute_resident_row_match_merge_relationship_plan(
            plan,
            request,
            generalized,
            context,
        );
    }
    if let Some(create) = validated.create() {
        return execute_resident_row_create_plan(plan, request, create, context);
    }
    if let Some(bound_relationship_merge) = validated.bound_relationship_merge() {
        return execute_resident_bound_relationship_merge_plan(
            plan,
            request,
            bound_relationship_merge,
            context,
        );
    }

    // Validate the complete immutable boundary and decode every output before interning one name
    // or constructing one canonical graph effect. Device failure can therefore never leak a
    // partial node, property, label, schema, or result batch.
    let read_dependencies = validated
        .read_dependencies()
        .iter()
        .copied()
        .collect::<BTreeSet<_>>();
    let mut dependencies = TransactionDependencies::default();
    for dependency in &plan.dependencies {
        let version = context
            .predicate_versions
            .get(dependency)
            .copied()
            .unwrap_or(context.bookmark.index);
        dependencies.predicates.insert(dependency.clone(), version);
    }
    for dense in &read_dependencies {
        let node = context.graph.node_dense(*dense).ok_or_else(|| {
            Error::new(
                ErrorCode::CorruptStorage,
                "resident row mutation read set names a missing node",
            )
        })?;
        if node.revision() > context.graph.revision() {
            return Err(Error::new(
                ErrorCode::CorruptStorage,
                "resident row mutation read set names a node from a future revision",
            ));
        }
        dependencies
            .entities
            .insert(EntityDependency::Node(node.id()), node.revision());
    }
    let mut created_ids = BTreeSet::new();
    for target in validated.targets() {
        match (target.dense_row, target.created_by) {
            (Some(dense), None) => {
                let node = context.graph.node_dense(dense).ok_or_else(|| {
                    Error::new(
                        ErrorCode::CorruptStorage,
                        "resident row mutation target names a missing dense node",
                    )
                })?;
                if node.id().0 != target.target_id || !read_dependencies.contains(&dense) {
                    return Err(Error::new(
                        ErrorCode::CorruptStorage,
                        "resident row mutation existing target has the wrong stable identity or missing read dependency",
                    ));
                }
            }
            (None, Some(_)) => {
                if context.graph.contains_node_id(NodeId(target.target_id)) {
                    return Err(Error::new(
                        ErrorCode::TransactionConflict,
                        "resident row mutation created identity already exists",
                    ));
                }
                created_ids.insert(target.target_id);
            }
            _ => {
                return Err(Error::new(
                    ErrorCode::CorruptStorage,
                    "resident row mutation target crossed immutable and statement-local identity",
                ));
            }
        }
    }

    let mut decoded_columns = Vec::with_capacity(validated.columns().len());
    for column in validated.columns() {
        let mut values = Vec::with_capacity(request.input.len());
        for row in 0..request.input.len() {
            let start = usize::try_from(column.offsets[row]).map_err(|_| {
                Error::new(
                    ErrorCode::CorruptStorage,
                    "resident row mutation output offset exceeds usize",
                )
            })?;
            let end = usize::try_from(column.offsets[row + 1]).map_err(|_| {
                Error::new(
                    ErrorCode::CorruptStorage,
                    "resident row mutation output end exceeds usize",
                )
            })?;
            let value = if column.validity[row] == 0 {
                ScalarValue::Null
            } else {
                let value = std::str::from_utf8(&column.bytes[start..end]).map_err(|_| {
                    Error::new(
                        ErrorCode::CorruptStorage,
                        "resident row mutation output slice is not UTF-8",
                    )
                })?;
                ScalarValue::String(Arc::from(value))
            };
            values.push(ResultValue::Scalar(value));
        }
        decoded_columns.push(values);
    }

    let mut state = ExecutionState {
        graph: transaction_graph_view(context)?,
        temporal: transaction_temporal_view(context)?,
        mutations: Vec::new(),
        temporal_mutations: Vec::new(),
        dependencies,
        next_node_id: context.next_node_id,
        next_edge_id: context.next_edge_id,
        revision: context.mutation_revision,
        created_at: resolved_created_at(context.resolved_time_nanos),
        read_layers: plan.read_layers,
        write_layer: plan.write_layer,
        stats: StatementStats::default(),
        final_columns: Vec::new(),
        scope_columns: BTreeSet::new(),
        administrative: None,
        vector_searches: Vec::new(),
        resident_backend: None,
        allow_context_backend: true,
        resident_overlay_mutations: 0,
        existential_subquery_depth: 0,
        initial_scan_cap: None,
    };
    for intent in validated.intents() {
        match &intent.action {
            ResidentRowMutationIntentAction::CreateNode { labels, properties } => {
                if !created_ids.contains(&intent.target_id)
                    || state.graph.node(NodeId(intent.target_id)).is_some()
                {
                    return Err(Error::new(
                        ErrorCode::CorruptStorage,
                        "resident row mutation CREATE intent reused a canonical identity",
                    ));
                }
                let mut resolved_labels = Vec::with_capacity(labels.len());
                for label in labels {
                    let name = request
                        .program
                        .label_names
                        .get(usize::from(*label))
                        .ok_or_else(|| {
                            Error::new(
                                ErrorCode::CorruptStorage,
                                "resident row mutation CREATE label name disappeared",
                            )
                        })?;
                    resolved_labels.push(intern_label(name, &mut state)?);
                }
                resolved_labels.sort_unstable();
                resolved_labels.dedup();
                let mut resolved_properties = Vec::with_capacity(properties.len());
                let mut unique_properties = BTreeSet::new();
                for property in properties {
                    if !unique_properties.insert(property.property_name) {
                        return Err(Error::new(
                            ErrorCode::CorruptStorage,
                            "resident row mutation CREATE intent duplicated a key property",
                        ));
                    }
                    let name = request
                        .program
                        .property_names
                        .get(usize::from(property.property_name))
                        .ok_or_else(|| {
                            Error::new(
                                ErrorCode::CorruptStorage,
                                "resident row mutation CREATE property name disappeared",
                            )
                        })?;
                    let property_id = intern_property(name, &mut state)?;
                    if !matches!(property.value, ScalarValue::Null) {
                        resolved_properties.push((property_id, property.value.clone()));
                    }
                }
                validate_node_properties(context.graph, &resolved_properties)?;
                let node_id = NodeId(intent.target_id);
                apply_mutation(
                    &mut state,
                    GraphMutation::InsertNode(NodeInput {
                        id: node_id,
                        layer: request.write_layer,
                        revision: context.mutation_revision,
                        labels: resolved_labels,
                        properties: resolved_properties,
                    }),
                )?;
                state.next_node_id =
                    state
                        .next_node_id
                        .max(intent.target_id.checked_add(1).ok_or_else(|| {
                            Error::new(ErrorCode::ResultBudgetExceeded, "node ID space exhausted")
                        })?);
                state.stats.nodes_created = state.stats.nodes_created.saturating_add(1);
                state.stats.labels_added =
                    state.stats.labels_added.saturating_add(labels.len() as u64);
            }
            ResidentRowMutationIntentAction::SetProperty {
                property_name,
                value,
            } => {
                let node_id = NodeId(intent.target_id);
                if state.graph.node(node_id).is_none() {
                    return Err(Error::new(
                        ErrorCode::CorruptStorage,
                        "resident row mutation SET target disappeared from the statement overlay",
                    ));
                }
                let name = request
                    .program
                    .property_names
                    .get(usize::from(*property_name))
                    .ok_or_else(|| {
                        Error::new(
                            ErrorCode::CorruptStorage,
                            "resident row mutation SET property name disappeared",
                        )
                    })?;
                let property = intern_property(name, &mut state)?;
                let target = PropertyMutationTarget::Node(node_id);
                target.validate(context.graph, property, value)?;
                apply_mutation(
                    &mut state,
                    target.mutation(property, value.clone(), context.mutation_revision),
                )?;
                state.stats.properties_set = state.stats.properties_set.saturating_add(1);
            }
        }
    }

    let schema = request
        .program
        .outputs
        .iter()
        .map(|output| (output.name.clone(), ColumnType::String))
        .collect::<Vec<_>>();
    let mut batches = Vec::new();
    let batch_rows = context.max_batch_rows.max(1);
    for start in (0..request.input.len()).step_by(batch_rows) {
        let end = start.saturating_add(batch_rows).min(request.input.len());
        batches.push(ResultBatch {
            row_count: end - start,
            columns: request
                .program
                .outputs
                .iter()
                .zip(&decoded_columns)
                .map(|(output, values)| ResultColumn {
                    name: output.name.clone(),
                    value_type: ColumnType::String,
                    values: values[start..end].to_vec(),
                })
                .collect(),
        });
    }

    Ok(ExecutionOutput {
        result: QueryResult {
            schema,
            batches,
            bookmark: context.bookmark,
            statistics: state.stats,
            truncated: false,
        },
        graph_mutations: state.mutations,
        temporal_mutations: state.temporal_mutations,
        dependencies: state.dependencies,
        administrative: None,
        vector_searches: Vec::new(),
        runtime_replans: 0,
    })
}

fn execute_resident_create_node_plan(
    plan: &PhysicalPlan,
    compiled: &CompiledResidentCreateNodePlan,
    backend: &dyn ExecutionBackend,
    context: &ExecutionContext<'_>,
    stream: &mut Option<&mut dyn FnMut(ExecutionStreamItem) -> Result<()>>,
) -> Result<ExecutionOutput> {
    if stream.is_some() {
        return Err(Error::internal(
            "resident CREATE execution cannot enter the read-only streaming API",
        ));
    }
    if compiled.requests.is_empty() {
        return Err(Error::internal(
            "resident CREATE plan lost its node operations",
        ));
    }

    check_execution(context)?;
    let pinned = backend.pin_project(context.project_id)?;
    if pinned.resident_bookmark(context.project_id) != Some(context.bookmark)
        || pinned.resident_graph_revision(context.project_id) != Some(context.graph.revision())
    {
        return Err(Error::new(
            ErrorCode::GpuAdmissionFailure,
            "resident CREATE backend does not own the requested canonical snapshot",
        ));
    }

    // Dispatch and validate the complete batch before interning one name or constructing one
    // canonical mutation. A late device error can therefore never publish an earlier CREATE.
    let mut validated = Vec::with_capacity(compiled.requests.len());
    for request in &compiled.requests {
        check_execution(context)?;
        let raw = pinned.execute_create_node(request, &context.cancellation)?;
        validated.push(raw.validate_for_publication(request, pinned.kind())?);
    }
    check_execution(context)?;
    let intents = validated
        .into_iter()
        .map(crate::execution::ValidatedResidentCreateNode::into_intent)
        .collect::<Vec<_>>();

    // Cross-intent checks are also part of the atomic validation boundary. Even individually
    // valid receipts may not alias one stable identity within the same statement.
    let mut created_ids = BTreeSet::new();
    for intent in &intents {
        if !created_ids.insert(intent.node_id) {
            return Err(Error::new(
                ErrorCode::CorruptStorage,
                "validated resident CREATE batch reused one node identity",
            ));
        }
        if context.graph.contains_node_id(intent.node_id) {
            return Err(Error::new(
                ErrorCode::TransactionConflict,
                "validated resident CREATE identity already exists",
            ));
        }
    }

    let mut dependencies = TransactionDependencies::default();
    for dependency in &plan.dependencies {
        let version = context
            .predicate_versions
            .get(dependency)
            .copied()
            .unwrap_or(context.bookmark.index);
        dependencies.predicates.insert(dependency.clone(), version);
    }
    let mut state = ExecutionState {
        graph: transaction_graph_view(context)?,
        temporal: transaction_temporal_view(context)?,
        mutations: Vec::new(),
        temporal_mutations: Vec::new(),
        dependencies,
        next_node_id: context.next_node_id,
        next_edge_id: context.next_edge_id,
        revision: context.mutation_revision,
        created_at: resolved_created_at(context.resolved_time_nanos),
        read_layers: plan.read_layers,
        write_layer: plan.write_layer,
        stats: StatementStats::default(),
        final_columns: Vec::new(),
        scope_columns: BTreeSet::new(),
        administrative: None,
        vector_searches: Vec::new(),
        resident_backend: None,
        allow_context_backend: true,
        resident_overlay_mutations: 0,
        existential_subquery_depth: 0,
        initial_scan_cap: None,
    };

    struct CreateOverlayNode {
        node: ResultNode,
        properties: BTreeMap<u16, ScalarValue>,
    }

    let mut overlay = Vec::with_capacity(intents.len());
    for (request, intent) in compiled.requests.iter().zip(&intents) {
        let mut labels = Vec::with_capacity(intent.labels.len());
        for label in &intent.labels {
            let name = request
                .label_names
                .get(usize::from(*label))
                .ok_or_else(|| {
                    Error::new(
                        ErrorCode::CorruptStorage,
                        "validated resident CREATE label name disappeared",
                    )
                })?;
            labels.push(intern_label(name, &mut state)?);
        }
        labels.sort_unstable();
        labels.dedup();

        let mut properties = Vec::with_capacity(intent.properties.len());
        let mut overlay_properties = BTreeMap::new();
        for property in &intent.properties {
            let name = request
                .property_names
                .get(usize::from(property.property_name))
                .ok_or_else(|| {
                    Error::new(
                        ErrorCode::CorruptStorage,
                        "validated resident CREATE property name disappeared",
                    )
                })?;
            let property_id = intern_property(name, &mut state)?;
            if overlay_properties
                .insert(property.property_name, property.value.clone())
                .is_some()
            {
                return Err(Error::new(
                    ErrorCode::CorruptStorage,
                    "validated resident CREATE intent duplicated a property",
                ));
            }
            // Cypher NULL removes/omits a canonical property, but the statement-local overlay
            // retains that exact device-produced NULL for `RETURN n.property`.
            if !matches!(property.value, ScalarValue::Null) {
                properties.push((property_id, property.value.clone()));
            }
        }
        validate_node_properties(context.graph, &properties)?;
        let revision = state.revision;
        apply_mutation(
            &mut state,
            GraphMutation::InsertNode(NodeInput {
                id: intent.node_id,
                layer: intent.layer,
                revision,
                labels,
                properties,
            }),
        )?;
        let dense = state
            .graph
            .node(intent.node_id)
            .ok_or_else(|| Error::internal("resident CREATE overlay lost its inserted node"))?
            .dense();
        overlay.push(CreateOverlayNode {
            node: materialize_node(&state.graph, dense)?,
            properties: overlay_properties,
        });
        state.next_node_id = state
            .next_node_id
            .max(intent.node_id.0.checked_add(1).ok_or_else(|| {
                Error::new(ErrorCode::ResultBudgetExceeded, "node ID space exhausted")
            })?);
        state.stats.nodes_created = state.stats.nodes_created.saturating_add(1);
        state.stats.labels_added = state
            .stats
            .labels_added
            .saturating_add(intent.labels.len() as u64);
    }
    if state.next_node_id != compiled.next_node_id {
        return Err(Error::new(
            ErrorCode::CorruptStorage,
            "resident CREATE stable-ID cursor differs from its compiled batch",
        ));
    }

    let mut schema = Vec::with_capacity(compiled.outputs.len());
    let mut columns = Vec::with_capacity(compiled.outputs.len());
    for output in &compiled.outputs {
        let value = match output.source {
            ResidentCreateOverlaySource::Node { request } => overlay
                .get(request)
                .map(|created| ResultValue::Node(created.node.clone()))
                .ok_or_else(|| {
                    Error::new(
                        ErrorCode::CorruptStorage,
                        "resident CREATE overlay output names an absent node intent",
                    )
                })?,
            ResidentCreateOverlaySource::Property {
                request,
                property_name,
            } => {
                let created = overlay.get(request).ok_or_else(|| {
                    Error::new(
                        ErrorCode::CorruptStorage,
                        "resident CREATE overlay property names an absent node intent",
                    )
                })?;
                let value = property_name
                    .and_then(|property_name| created.properties.get(&property_name).cloned())
                    .unwrap_or(ScalarValue::Null);
                ResultValue::from_property(value)?
            }
        };
        let value_type = value.column_type();
        schema.push((output.name.clone(), value_type.clone()));
        columns.push(ResultColumn {
            name: output.name.clone(),
            value_type,
            values: vec![value],
        });
    }
    let batches = if columns.is_empty() {
        Vec::new()
    } else {
        vec![ResultBatch {
            row_count: 1,
            columns,
        }]
    };

    Ok(ExecutionOutput {
        result: QueryResult {
            schema,
            batches,
            bookmark: context.bookmark,
            statistics: state.stats,
            truncated: false,
        },
        graph_mutations: state.mutations,
        temporal_mutations: state.temporal_mutations,
        dependencies: state.dependencies,
        administrative: None,
        vector_searches: Vec::new(),
        runtime_replans: 0,
    })
}

fn resident_delete_dependencies(
    plan: &PhysicalPlan,
    validated: &ValidatedResidentDeleteResult,
    context: &ExecutionContext<'_>,
) -> Result<TransactionDependencies> {
    let mut dependencies = TransactionDependencies::default();
    for dependency in &plan.dependencies {
        let version = context
            .predicate_versions
            .get(dependency)
            .copied()
            .unwrap_or(context.bookmark.index);
        dependencies.predicates.insert(dependency.clone(), version);
    }
    for dependency in validated.read_dependencies() {
        match dependency {
            ResidentMutationReadDependency::Node(dense) => {
                let node = context.graph.node_dense(*dense).ok_or_else(|| {
                    Error::new(
                        ErrorCode::CorruptStorage,
                        "resident DELETE read set contains a missing node",
                    )
                })?;
                dependencies
                    .entities
                    .insert(EntityDependency::Node(node.id()), node.revision());
            }
            ResidentMutationReadDependency::Relationship(dense) => {
                let edge = context.graph.edge_dense(*dense).ok_or_else(|| {
                    Error::new(
                        ErrorCode::CorruptStorage,
                        "resident DELETE read set contains a missing relationship",
                    )
                })?;
                dependencies
                    .entities
                    .insert(EntityDependency::Relationship(edge.id()), edge.revision());
            }
        }
    }
    Ok(dependencies)
}

fn resident_delete_relation_to_result(
    relation: &ResidentDeleteFinalRelation,
    request: &ResidentDeleteRequest,
    catalog: &crate::graph::NameCatalog,
    bookmark: Bookmark,
    statistics: StatementStats,
    max_batch_rows: usize,
) -> Result<QueryResult> {
    let continuation = request.continuation.as_ref().ok_or_else(|| {
        Error::new(
            ErrorCode::CorruptStorage,
            "resident DELETE final relation has no compiled continuation",
        )
    })?;
    if relation.row_count != relation.values.len() || relation.row_count != relation.validity.len()
    {
        return Err(Error::new(
            ErrorCode::CorruptStorage,
            "resident DELETE final relation is misaligned",
        ));
    }
    let value_type = match continuation.output.source {
        ResidentDeleteOutputSource::Integer(_) => {
            if relation.validity.iter().any(|valid| *valid != 0) {
                ColumnType::Integer
            } else {
                ColumnType::Null
            }
        }
        ResidentDeleteOutputSource::RelationshipType(_) => {
            if relation.validity.iter().any(|valid| *valid != 0) {
                ColumnType::String
            } else {
                ColumnType::Null
            }
        }
        ResidentDeleteOutputSource::NullEntity(_) => ColumnType::Null,
    };
    let schema = vec![(continuation.output.name.clone(), value_type.clone())];
    let mut batches = Vec::new();
    let batch_rows = max_batch_rows.max(1);
    for start in (0..relation.row_count).step_by(batch_rows) {
        let end = start.saturating_add(batch_rows).min(relation.row_count);
        let values = relation.values[start..end]
            .iter()
            .copied()
            .zip(&relation.validity[start..end])
            .map(|(value, valid)| -> Result<ResultValue> {
                Ok(match continuation.output.source {
                ResidentDeleteOutputSource::Integer(_) if *valid != 0 => {
                    ResultValue::Scalar(ScalarValue::Integer(value))
                }
                ResidentDeleteOutputSource::RelationshipType(_) if *valid != 0 => {
                    let relationship_type = RelationshipTypeId(value as u64);
                    let name = catalog.relationship_type_name(relationship_type).ok_or_else(|| {
                        Error::new(
                            ErrorCode::CorruptStorage,
                            "resident DELETE returned a relationship type outside the pinned catalog",
                        )
                    })?;
                    ResultValue::Scalar(ScalarValue::String(Arc::from(name)))
                }
                ResidentDeleteOutputSource::Integer(_)
                | ResidentDeleteOutputSource::RelationshipType(_)
                | ResidentDeleteOutputSource::NullEntity(_) => {
                    ResultValue::Scalar(ScalarValue::Null)
                }
                })
            })
            .collect::<Result<Vec<_>>>()?;
        batches.push(ResultBatch {
            row_count: end - start,
            columns: vec![ResultColumn {
                name: continuation.output.name.clone(),
                value_type: value_type.clone(),
                values,
            }],
        });
    }
    Ok(QueryResult {
        schema,
        batches,
        bookmark,
        statistics,
        truncated: false,
    })
}

fn execute_resident_delete_plan(
    plan: &PhysicalPlan,
    compiled: &CompiledResidentDeletePlan,
    backend: &dyn ExecutionBackend,
    context: &ExecutionContext<'_>,
    stream: &mut Option<&mut dyn FnMut(ExecutionStreamItem) -> Result<()>>,
) -> Result<ExecutionOutput> {
    if stream.is_some() {
        return Err(Error::internal(
            "resident DELETE execution cannot enter the read-only streaming API",
        ));
    }
    check_execution(context)?;
    let pinned = backend.pin_project(context.project_id)?;
    if pinned.resident_bookmark(context.project_id) != Some(context.bookmark)
        || pinned.resident_graph_revision(context.project_id) != Some(context.graph.revision())
    {
        return Err(Error::new(
            ErrorCode::GpuAdmissionFailure,
            "pinned resident DELETE backend does not own the requested immutable generation",
        ));
    }
    check_execution(context)?;
    let raw = pinned.execute_delete_pipeline(&compiled.request, &context.cancellation)?;
    let validated = raw.validate_for_publication(&compiled.request, pinned.kind())?;
    let dependencies = resident_delete_dependencies(plan, &validated, context)?;
    let mut state = ExecutionState {
        graph: transaction_graph_view(context)?,
        temporal: transaction_temporal_view(context)?,
        mutations: Vec::new(),
        temporal_mutations: Vec::new(),
        dependencies,
        next_node_id: context.next_node_id,
        next_edge_id: context.next_edge_id,
        revision: context.mutation_revision,
        created_at: resolved_created_at(context.resolved_time_nanos),
        read_layers: plan.read_layers,
        write_layer: plan.write_layer,
        stats: StatementStats::default(),
        final_columns: Vec::new(),
        scope_columns: BTreeSet::new(),
        administrative: None,
        vector_searches: Vec::new(),
        resident_backend: None,
        allow_context_backend: true,
        resident_overlay_mutations: 0,
        existential_subquery_depth: 0,
        initial_scan_cap: None,
    };
    for intent in validated.intents() {
        if intent.origin == ResidentDeleteIntentOrigin::DetachIncident {
            // This backend-authored row proves complete DETACH expansion. The canonical
            // DeleteNode(detach=true) frame remains the one mutation that removes it.
            continue;
        }
        let command = compiled
            .request
            .commands
            .get(intent.command as usize)
            .ok_or_else(|| Error::internal("validated resident DELETE command disappeared"))?;
        match intent.target_kind {
            EntityKind::Relationship => {
                let edge = EdgeId(intent.target_id);
                if state.graph.edge(edge).is_none() {
                    return Err(Error::new(
                        ErrorCode::CorruptStorage,
                        "validated resident DELETE relationship target disappeared",
                    ));
                }
                apply_mutation(
                    &mut state,
                    GraphMutation::DeleteEdge {
                        edge,
                        revision: context.mutation_revision,
                    },
                )?;
                state.stats.relationships_deleted =
                    state.stats.relationships_deleted.saturating_add(1);
            }
            EntityKind::Node => {
                let node = NodeId(intent.target_id);
                if state.graph.node(node).is_none() {
                    return Err(Error::new(
                        ErrorCode::CorruptStorage,
                        "validated resident DELETE node target disappeared",
                    ));
                }
                apply_mutation(
                    &mut state,
                    GraphMutation::DeleteNode {
                        node,
                        detach: command.detach,
                        revision: context.mutation_revision,
                    },
                )
                .map_err(|error| {
                    if !command.detach
                        && error.code == ErrorCode::QueryType
                        && error.message == "node still has relationships"
                    {
                        Error::new(
                            ErrorCode::CorruptStorage,
                            "backend authorized an ordinary DELETE for a connected node",
                        )
                    } else {
                        error
                    }
                })?;
                state.stats.nodes_deleted = state.stats.nodes_deleted.saturating_add(1);
            }
        }
    }
    let result = match validated.final_relation() {
        Some(relation) => resident_delete_relation_to_result(
            relation,
            &compiled.request,
            context.binding_catalog,
            context.bookmark,
            state.stats,
            context.max_batch_rows,
        )?,
        None => QueryResult {
            schema: Vec::new(),
            batches: Vec::new(),
            bookmark: context.bookmark,
            statistics: state.stats,
            truncated: false,
        },
    };
    Ok(ExecutionOutput {
        result,
        graph_mutations: state.mutations,
        temporal_mutations: state.temporal_mutations,
        dependencies: state.dependencies,
        administrative: None,
        vector_searches: Vec::new(),
        runtime_replans: 0,
    })
}

fn execute_resident_mutation_plan(
    plan: &PhysicalPlan,
    compiled: &CompiledResidentMutationPlan,
    backend: &dyn ExecutionBackend,
    context: &ExecutionContext<'_>,
    stream: &mut Option<&mut dyn FnMut(ExecutionStreamItem) -> Result<()>>,
) -> Result<ExecutionOutput> {
    if stream.is_some() {
        return Err(Error::internal(
            "resident mutation execution cannot enter the read-only streaming API",
        ));
    }
    check_execution(context)?;
    let pinned = backend.pin_project(context.project_id)?;
    if pinned.resident_bookmark(context.project_id) != Some(context.bookmark)
        || pinned.resident_graph_revision(context.project_id) != Some(context.graph.revision())
    {
        return Err(Error::new(
            ErrorCode::GpuAdmissionFailure,
            "pinned resident mutation backend does not own the requested immutable generation",
        ));
    }
    check_execution(context)?;
    let mut resident = pinned.execute_node_pipeline(&compiled.request, &context.cancellation)?;
    let raw = resident.mutation.take().ok_or_else(|| {
        Error::new(
            ErrorCode::CorruptStorage,
            "resident mutation pipeline omitted its raw mutation result",
        )
    })?;

    // Raw intents are deliberately inaccessible until this consumes and validates every receipt
    // against the exact request and selected backend completion class.
    let validated = raw.validate_for_publication(&compiled.request, pinned.kind())?;
    let dependencies = validate_resident_mutation_boundary(
        plan,
        &compiled.request,
        &resident,
        &validated,
        context,
    )?;

    let mut state = ExecutionState {
        graph: transaction_graph_view(context)?,
        temporal: transaction_temporal_view(context)?,
        mutations: Vec::new(),
        temporal_mutations: Vec::new(),
        dependencies,
        next_node_id: context.next_node_id,
        next_edge_id: context.next_edge_id,
        revision: context.mutation_revision,
        created_at: resolved_created_at(context.resolved_time_nanos),
        read_layers: plan.read_layers,
        write_layer: plan.write_layer,
        stats: StatementStats::default(),
        final_columns: Vec::new(),
        scope_columns: BTreeSet::new(),
        administrative: None,
        vector_searches: Vec::new(),
        resident_backend: None,
        allow_context_backend: true,
        resident_overlay_mutations: 0,
        existential_subquery_depth: 0,
        initial_scan_cap: None,
    };
    let program = compiled.request.mutation.as_ref().ok_or_else(|| {
        Error::new(
            ErrorCode::CorruptStorage,
            "validated resident mutation request lost its mutation program",
        )
    })?;
    for intent in validated.intents() {
        publish_resident_mutation_intent(intent, program, &mut state, context)?;
    }

    let result = if let Some(relation) = validated.final_relation() {
        resident_mutation_relation_to_result(relation, program, &state.graph, context, state.stats)?
    } else {
        QueryResult {
            schema: Vec::new(),
            batches: Vec::new(),
            bookmark: context.bookmark,
            statistics: state.stats,
            truncated: false,
        }
    };

    Ok(ExecutionOutput {
        result,
        graph_mutations: state.mutations,
        temporal_mutations: state.temporal_mutations,
        dependencies: state.dependencies,
        administrative: None,
        vector_searches: Vec::new(),
        runtime_replans: 0,
    })
}

fn resident_mutation_relation_to_result(
    relation: &crate::execution::ResidentMutationFinalRelation,
    program: &crate::execution::ResidentMutationProgram,
    graph: &GraphReadView<'_>,
    context: &ExecutionContext<'_>,
    statistics: StatementStats,
) -> Result<QueryResult> {
    let continuation = program.continuation.as_ref().ok_or_else(|| {
        Error::new(
            ErrorCode::CorruptStorage,
            "resident mutation final relation has no compiled continuation",
        )
    })?;
    let mut rows = (0..relation.row_count)
        .map(|_| Row::new())
        .collect::<Vec<_>>();
    for (column, output) in relation.columns.iter().zip(&continuation.outputs) {
        match column {
            crate::execution::ResidentMutationRelationColumn::Entity { source, dense_rows } => {
                let node = matches!(source, ResidentEntityBinding::Node(_));
                for (row, dense) in rows.iter_mut().zip(dense_rows) {
                    let value = if *dense == crate::execution::RESIDENT_NULL_ROW {
                        BindingValue::Null
                    } else if node {
                        BindingValue::Node(*dense)
                    } else {
                        BindingValue::Relationship(*dense)
                    };
                    row.insert(output.name.clone(), value);
                }
            }
            crate::execution::ResidentMutationRelationColumn::Integer {
                values, validity, ..
            } => {
                for ((row, value), valid) in rows.iter_mut().zip(values).zip(validity) {
                    let scalar = if matches!(
                        output.source,
                        crate::execution::ResidentMutationProjectionSource::PropertyIsNotNull(_)
                    ) {
                        ScalarValue::Boolean(*value != 0)
                    } else {
                        ScalarValue::Integer(*value)
                    };
                    row.insert(
                        output.name.clone(),
                        if *valid == 0 {
                            BindingValue::Null
                        } else {
                            BindingValue::Value(ResultValue::Scalar(scalar))
                        },
                    );
                }
            }
            crate::execution::ResidentMutationRelationColumn::Value { values, .. } => {
                for (row, value) in rows.iter_mut().zip(values) {
                    row.insert(
                        output.name.clone(),
                        BindingValue::Value(decode_resident_quantifier_value(value.clone())?),
                    );
                }
            }
        }
    }
    let columns = continuation
        .outputs
        .iter()
        .map(|output| output.name.clone())
        .collect::<Vec<_>>();
    rows_to_result(
        &rows,
        &columns,
        graph,
        context.bookmark,
        statistics,
        context.max_batch_rows,
        None,
    )
}

fn validate_resident_mutation_boundary(
    plan: &PhysicalPlan,
    request: &ResidentNodePipelineRequest,
    resident: &ResidentNodePipelineResult,
    validated: &ValidatedResidentMutationBatch,
    context: &ExecutionContext<'_>,
) -> Result<TransactionDependencies> {
    let program = request.mutation.as_ref().ok_or_else(|| {
        Error::new(
            ErrorCode::CorruptStorage,
            "resident mutation result has no mutation program",
        )
    })?;
    let selected_rows = validated
        .receipts()
        .iter()
        .find(|receipt| receipt.obligation == program.selection_obligation)
        .ok_or_else(|| {
            Error::new(
                ErrorCode::CorruptStorage,
                "validated resident mutation batch lost its selection receipt",
            )
        })?
        .output_cardinality;
    let selected_rows = usize::try_from(selected_rows).map_err(|_| {
        Error::new(
            ErrorCode::CorruptStorage,
            "resident mutation selected-row cardinality exceeds usize",
        )
    })?;
    let row_count = resident.start_rows.len();
    let expansion_count = request.expansion_steps().count();
    let relationship_count = request.relationship_column_count();
    let node_columns_valid = if expansion_count == 0 {
        resident.end_rows.is_empty() && resident.intermediate_node_rows.is_empty()
    } else {
        resident.end_rows.len() == row_count
            && resident.intermediate_node_rows.len() == expansion_count - 1
            && resident
                .intermediate_node_rows
                .iter()
                .all(|column| column.len() == row_count)
    };
    let relationship_columns_valid = if relationship_count == 0 {
        resident.edge_rows.is_empty() && resident.intermediate_edge_rows.is_empty()
    } else {
        resident.edge_rows.len() == row_count
            && resident.intermediate_edge_rows.len() == relationship_count - 1
            && resident
                .intermediate_edge_rows
                .iter()
                .all(|column| column.len() == row_count)
    };
    if selected_rows != row_count
        || row_count > request.max_output_rows
        || !node_columns_valid
        || !relationship_columns_valid
        || !resident.integer_columns.is_empty()
        || !resident.boolean_columns.is_empty()
        || !resident.value_left_indices.is_empty()
        || !resident.value_right_indices.is_empty()
    {
        return Err(Error::new(
            ErrorCode::CorruptStorage,
            "resident mutation pipeline returned an inconsistent selected-row boundary",
        ));
    }

    if program.continuation.is_some() {
        let relation = validated.final_relation().ok_or_else(|| {
            Error::new(
                ErrorCode::CorruptStorage,
                "resident mutation continuation omitted its final relation",
            )
        })?;
        for column in &relation.columns {
            let crate::execution::ResidentMutationRelationColumn::Entity { source, dense_rows } =
                column
            else {
                continue;
            };
            let domain = (0..row_count)
                .map(|source_row| {
                    resident_mutation_binding_dense(resident, request, *source, source_row)
                })
                .collect::<Result<BTreeSet<_>>>()?;
            for dense in dense_rows {
                if *dense == crate::execution::RESIDENT_NULL_ROW || !domain.contains(dense) {
                    return Err(Error::new(
                        ErrorCode::CorruptStorage,
                        "resident mutation final entity is outside its selected binding domain",
                    ));
                }
                let valid = match source {
                    ResidentEntityBinding::Node(_) => context.graph.node_dense(*dense).is_some(),
                    ResidentEntityBinding::Relationship(_) => {
                        context.graph.edge_dense(*dense).is_some()
                    }
                };
                if !valid {
                    return Err(Error::new(
                        ErrorCode::CorruptStorage,
                        "resident mutation final relation contains an invalid dense entity ID",
                    ));
                }
            }
        }
    }

    let mut dependencies = TransactionDependencies::default();
    for dependency in &plan.dependencies {
        let version = context
            .predicate_versions
            .get(dependency)
            .copied()
            .unwrap_or(context.bookmark.index);
        dependencies.predicates.insert(dependency.clone(), version);
    }
    if program.continuation.is_some() {
        let mut dependency_nodes = BTreeSet::new();
        let mut dependency_relationships = BTreeSet::new();
        for dependency in validated.read_dependencies() {
            match dependency {
                ResidentMutationReadDependency::Node(dense) => {
                    let node = context.graph.node_dense(*dense).ok_or_else(|| {
                        Error::new(
                            ErrorCode::CorruptStorage,
                            "resident mutation read set names a missing node",
                        )
                    })?;
                    if node.revision() > context.graph.revision() {
                        return Err(Error::new(
                            ErrorCode::CorruptStorage,
                            "resident mutation read set names a node from a future revision",
                        ));
                    }
                    dependency_nodes.insert(*dense);
                    dependencies
                        .entities
                        .insert(EntityDependency::Node(node.id()), node.revision());
                }
                ResidentMutationReadDependency::Relationship(dense) => {
                    let edge = context.graph.edge_dense(*dense).ok_or_else(|| {
                        Error::new(
                            ErrorCode::CorruptStorage,
                            "resident mutation read set names a missing relationship",
                        )
                    })?;
                    if edge.revision() > context.graph.revision() {
                        return Err(Error::new(
                            ErrorCode::CorruptStorage,
                            "resident mutation read set names a relationship from a future revision",
                        ));
                    }
                    dependency_relationships.insert(*dense);
                    dependencies
                        .entities
                        .insert(EntityDependency::Relationship(edge.id()), edge.revision());
                }
            }
        }
        for dense in resident
            .start_rows
            .iter()
            .chain(resident.intermediate_node_rows.iter().flatten())
            .chain(&resident.end_rows)
        {
            if *dense != crate::execution::RESIDENT_NULL_ROW && !dependency_nodes.contains(dense) {
                return Err(Error::new(
                    ErrorCode::CorruptStorage,
                    "resident mutation read set omitted a selected node",
                ));
            }
        }
        for dense in resident
            .intermediate_edge_rows
            .iter()
            .flatten()
            .chain(&resident.edge_rows)
        {
            if *dense != crate::execution::RESIDENT_NULL_ROW
                && !dependency_relationships.contains(dense)
            {
                return Err(Error::new(
                    ErrorCode::CorruptStorage,
                    "resident mutation read set omitted a selected relationship",
                ));
            }
        }
    } else {
        let node_columns = std::iter::once(resident.start_rows.as_slice())
            .chain(resident.intermediate_node_rows.iter().map(Vec::as_slice))
            .chain(std::iter::once(resident.end_rows.as_slice()));
        for column in node_columns {
            for dense in column {
                if *dense == crate::execution::RESIDENT_NULL_ROW {
                    continue;
                }
                let node = context.graph.node_dense(*dense).ok_or_else(|| {
                    Error::new(
                        ErrorCode::CorruptStorage,
                        "resident mutation selected a missing node",
                    )
                })?;
                if node.revision() > context.graph.revision() {
                    return Err(Error::new(
                        ErrorCode::CorruptStorage,
                        "resident mutation selected a node from a future revision",
                    ));
                }
                dependencies
                    .entities
                    .insert(EntityDependency::Node(node.id()), node.revision());
            }
        }
        let edge_columns = resident
            .intermediate_edge_rows
            .iter()
            .map(Vec::as_slice)
            .chain(std::iter::once(resident.edge_rows.as_slice()));
        for column in edge_columns {
            for dense in column {
                if *dense == crate::execution::RESIDENT_NULL_ROW {
                    continue;
                }
                let edge = context.graph.edge_dense(*dense).ok_or_else(|| {
                    Error::new(
                        ErrorCode::CorruptStorage,
                        "resident mutation selected a missing relationship",
                    )
                })?;
                if edge.revision() > context.graph.revision() {
                    return Err(Error::new(
                        ErrorCode::CorruptStorage,
                        "resident mutation selected a relationship from a future revision",
                    ));
                }
                dependencies
                    .entities
                    .insert(EntityDependency::Relationship(edge.id()), edge.revision());
            }
        }
    }

    // Independently reconstruct only target identity from the receipted selected-row columns.
    // The validated batch exposes effectful actions only; absence at a non-null row/command is a
    // backend-receipted no-op, never a host membership decision.
    let mut intents = validated.intents().iter().peekable();
    for source_row in 0..row_count {
        let source_row_u32 = u32::try_from(source_row).map_err(|_| {
            Error::new(
                ErrorCode::CorruptStorage,
                "resident mutation source-row index exceeds u32",
            )
        })?;
        for (command_index, command) in program.commands.iter().enumerate() {
            let binding = resident_mutation_operation_target(&command.operation);
            let dense = resident_mutation_binding_dense(resident, request, binding, source_row)?;
            let command_index_u16 = u16::try_from(command_index).map_err(|_| {
                Error::new(
                    ErrorCode::CorruptStorage,
                    "resident mutation command index exceeds u16",
                )
            })?;
            let key = (source_row_u32, command_index_u16);
            let next_key = intents
                .peek()
                .map(|intent| (intent.source_row, intent.command));
            if next_key.is_some_and(|next| next < key) {
                return Err(Error::new(
                    ErrorCode::CorruptStorage,
                    "resident mutation effect intent is not aligned in row-major order",
                ));
            }
            if dense == crate::execution::RESIDENT_NULL_ROW {
                if next_key == Some(key) {
                    return Err(Error::new(
                        ErrorCode::CorruptStorage,
                        "resident mutation emitted an effect for a null selected target",
                    ));
                }
                continue;
            }
            if next_key != Some(key) {
                continue;
            }
            let intent = intents
                .next()
                .ok_or_else(|| Error::internal("peeked resident mutation effect disappeared"))?;
            let target = match binding {
                ResidentEntityBinding::Node(_) => {
                    if intent.target_kind != EntityKind::Node {
                        return Err(Error::new(
                            ErrorCode::CorruptStorage,
                            "resident mutation node binding produced a relationship target",
                        ));
                    }
                    let node = context.graph.node_dense(dense).ok_or_else(|| {
                        Error::new(
                            ErrorCode::CorruptStorage,
                            "resident mutation target node does not exist",
                        )
                    })?;
                    if node.id().0 != intent.target_id {
                        return Err(Error::new(
                            ErrorCode::CorruptStorage,
                            "resident mutation target node differs from its selected-row binding",
                        ));
                    }
                    EntityDependency::Node(node.id())
                }
                ResidentEntityBinding::Relationship(_) => {
                    if intent.target_kind != EntityKind::Relationship {
                        return Err(Error::new(
                            ErrorCode::CorruptStorage,
                            "resident mutation relationship binding produced a node target",
                        ));
                    }
                    let edge = context.graph.edge_dense(dense).ok_or_else(|| {
                        Error::new(
                            ErrorCode::CorruptStorage,
                            "resident mutation target relationship does not exist",
                        )
                    })?;
                    if edge.id().0 != intent.target_id {
                        return Err(Error::new(
                            ErrorCode::CorruptStorage,
                            "resident mutation target relationship differs from its selected-row binding",
                        ));
                    }
                    EntityDependency::Relationship(edge.id())
                }
            };
            dependencies.write_targets.insert(target);
        }
    }
    if intents.next().is_some() {
        return Err(Error::new(
            ErrorCode::CorruptStorage,
            "resident mutation emitted an intent for a null or absent selected target",
        ));
    }
    Ok(dependencies)
}

fn resident_mutation_operation_target(
    operation: &ResidentMutationOperation,
) -> ResidentEntityBinding {
    match operation {
        ResidentMutationOperation::SetProperty { target, .. }
        | ResidentMutationOperation::MergeProperties { target, .. }
        | ResidentMutationOperation::ReplaceProperties { target, .. }
        | ResidentMutationOperation::RemoveProperty { target, .. } => *target,
        ResidentMutationOperation::AddLabels { target, .. }
        | ResidentMutationOperation::RemoveLabels { target, .. } => {
            ResidentEntityBinding::Node(*target)
        }
    }
}

fn resident_mutation_binding_dense(
    resident: &ResidentNodePipelineResult,
    request: &ResidentNodePipelineRequest,
    binding: ResidentEntityBinding,
    source_row: usize,
) -> Result<u32> {
    let rows = match binding {
        ResidentEntityBinding::Node(binding) => resident_node_rows(resident, binding)?,
        ResidentEntityBinding::Relationship(index) => {
            let index = index as usize;
            let count = request.relationship_column_count();
            if index >= count {
                return Err(Error::new(
                    ErrorCode::CorruptStorage,
                    "resident mutation relationship binding is outside the selected row",
                ));
            }
            if index + 1 == count {
                resident.edge_rows.as_slice()
            } else {
                resident
                    .intermediate_edge_rows
                    .get(index)
                    .map(Vec::as_slice)
                    .ok_or_else(|| {
                        Error::new(
                            ErrorCode::CorruptStorage,
                            "resident mutation omitted an intermediate relationship binding",
                        )
                    })?
            }
        }
    };
    rows.get(source_row).copied().ok_or_else(|| {
        Error::new(
            ErrorCode::CorruptStorage,
            "resident mutation binding is not aligned with its source row",
        )
    })
}

fn publish_resident_mutation_intent(
    intent: &ResidentMutationIntent,
    program: &crate::execution::ResidentMutationProgram,
    state: &mut ExecutionState<'_>,
    context: &ExecutionContext<'_>,
) -> Result<()> {
    if !intent.effectful {
        return Err(Error::new(
            ErrorCode::CorruptStorage,
            "validated resident mutation batch exposed a no-op attempt",
        ));
    }
    let target = match intent.target_kind {
        EntityKind::Node => {
            let node = NodeId(intent.target_id);
            if state.graph.node(node).is_none() {
                return Err(Error::new(
                    ErrorCode::CorruptStorage,
                    "validated resident mutation target node disappeared",
                ));
            }
            PropertyMutationTarget::Node(node)
        }
        EntityKind::Relationship => {
            let edge = EdgeId(intent.target_id);
            if state.graph.edge(edge).is_none() {
                return Err(Error::new(
                    ErrorCode::CorruptStorage,
                    "validated resident mutation target relationship disappeared",
                ));
            }
            PropertyMutationTarget::Relationship(edge)
        }
    };
    match &intent.action {
        ResidentMutationIntentAction::SetProperty {
            property_name,
            value,
        } => {
            let name = resident_mutation_property_name(program, *property_name)?;
            let property = intern_property(name, state)?;
            target.validate(context.graph, property, value)?;
            apply_mutation(
                state,
                target.mutation(property, value.clone(), state.revision),
            )?;
            state.stats.properties_set = state.stats.properties_set.saturating_add(1);
        }
        ResidentMutationIntentAction::MergeProperties { entries }
        | ResidentMutationIntentAction::ReplaceProperties { entries } => {
            let replace = matches!(
                intent.action,
                ResidentMutationIntentAction::ReplaceProperties { .. }
            );
            let mut updates = Vec::with_capacity(entries.len());
            let mut supplied = BTreeSet::new();
            for entry in entries {
                let name = resident_mutation_property_name(program, entry.property_name)?;
                let property = intern_property(name, state)?;
                target.validate(context.graph, property, &entry.value)?;
                supplied.insert(property);
                updates.push((property, entry.value.clone()));
            }
            if replace {
                for (property, _) in target.properties(state)? {
                    if !supplied.contains(&property) {
                        updates.push((property, ScalarValue::Null));
                    }
                }
            }
            for (property, value) in updates {
                apply_mutation(state, target.mutation(property, value, state.revision))?;
                state.stats.properties_set = state.stats.properties_set.saturating_add(1);
            }
        }
        ResidentMutationIntentAction::RemoveProperty { property_name } => {
            let name = resident_mutation_property_name(program, *property_name)?;
            let expected = program
                .property_tokens
                .get(*property_name as usize)
                .copied()
                .flatten()
                .ok_or_else(|| {
                    Error::new(
                        ErrorCode::CorruptStorage,
                        "backend claimed an effect for an unknown property token",
                    )
                })?;
            let property = state.graph.property(name).ok_or_else(|| {
                Error::new(
                    ErrorCode::CorruptStorage,
                    "effectful resident property removal lost its canonical token",
                )
            })?;
            if property != expected {
                return Err(Error::new(
                    ErrorCode::CorruptStorage,
                    "effectful resident property removal resolved a different canonical token",
                ));
            }
            apply_mutation(
                state,
                target.mutation(property, ScalarValue::Null, state.revision),
            )?;
            state.stats.properties_set = state.stats.properties_set.saturating_add(1);
        }
        ResidentMutationIntentAction::AddLabels { labels } => {
            let PropertyMutationTarget::Node(node) = target else {
                return Err(Error::new(
                    ErrorCode::CorruptStorage,
                    "resident label mutation targeted a relationship",
                ));
            };
            let mut resolved = Vec::with_capacity(labels.len());
            for label in labels {
                resolved.push(intern_label(
                    resident_mutation_label_name(program, *label)?,
                    state,
                )?);
            }
            resolved.sort_unstable();
            resolved.dedup();
            if resolved.is_empty() {
                return Err(Error::new(
                    ErrorCode::CorruptStorage,
                    "effectful resident label-add intent has no labels",
                ));
            }
            let added = resolved.len();
            apply_mutation(
                state,
                GraphMutation::AddNodeLabels {
                    node,
                    labels: resolved,
                    revision: state.revision,
                },
            )?;
            state.stats.labels_added = state
                .stats
                .labels_added
                .saturating_add(u64::try_from(added).unwrap_or(u64::MAX));
        }
        ResidentMutationIntentAction::RemoveLabels { labels } => {
            let PropertyMutationTarget::Node(node) = target else {
                return Err(Error::new(
                    ErrorCode::CorruptStorage,
                    "resident label mutation targeted a relationship",
                ));
            };
            let mut resolved = labels
                .iter()
                .map(|label| resident_mutation_label_name(program, *label))
                .collect::<Result<Vec<_>>>()?
                .into_iter()
                .map(|name| {
                    state.graph.label(name).ok_or_else(|| {
                        Error::new(
                            ErrorCode::CorruptStorage,
                            "backend claimed an effect for an unknown label token",
                        )
                    })
                })
                .collect::<Result<Vec<_>>>()?;
            resolved.sort_unstable();
            resolved.dedup();
            if resolved.is_empty() {
                return Err(Error::new(
                    ErrorCode::CorruptStorage,
                    "effectful resident label-remove intent has no labels",
                ));
            }
            let removed = resolved.len();
            apply_mutation(
                state,
                GraphMutation::RemoveNodeLabels {
                    node,
                    labels: resolved,
                    revision: state.revision,
                },
            )?;
            state.stats.labels_removed = state
                .stats
                .labels_removed
                .saturating_add(u64::try_from(removed).unwrap_or(u64::MAX));
        }
    }
    Ok(())
}

fn resident_mutation_property_name(
    program: &crate::execution::ResidentMutationProgram,
    index: u16,
) -> Result<&str> {
    program
        .property_names
        .get(index as usize)
        .map(String::as_str)
        .ok_or_else(|| {
            Error::new(
                ErrorCode::CorruptStorage,
                "resident mutation intent referenced an absent property name",
            )
        })
}

fn resident_mutation_label_name(
    program: &crate::execution::ResidentMutationProgram,
    index: u16,
) -> Result<&str> {
    program
        .label_names
        .get(index as usize)
        .map(String::as_str)
        .ok_or_else(|| {
            Error::new(
                ErrorCode::CorruptStorage,
                "resident mutation intent referenced an absent label name",
            )
        })
}

fn resident_node_rows(
    result: &crate::execution::ResidentNodePipelineResult,
    binding: crate::execution::ResidentNodeBinding,
) -> Result<&[u32]> {
    match binding {
        crate::execution::ResidentNodeBinding::Start => Ok(&result.start_rows),
        crate::execution::ResidentNodeBinding::Intermediate(index) => result
            .intermediate_node_rows
            .get(index as usize)
            .map(Vec::as_slice)
            .ok_or_else(|| {
                Error::new(
                    ErrorCode::CorruptStorage,
                    "resident node pipeline omitted an intermediate node binding",
                )
            }),
        crate::execution::ResidentNodeBinding::End => Ok(&result.end_rows),
    }
}

/// Execute one sealed pattern-comprehension command. Native publication owns the correlated scan,
/// traversal, OPTIONAL parent coverage, and path identity; host work begins only after immutable
/// generation and ordered receipts validate, and is limited to grouping and ordinary entity/value
/// serialization at the result edge.
fn execute_resident_pattern_comprehension_plan(
    plan: &PhysicalPlan,
    compiled: &CompiledResidentPatternComprehensionPlan,
    backend: &dyn ExecutionBackend,
    context: &ExecutionContext<'_>,
    stream: &mut Option<&mut dyn FnMut(ExecutionStreamItem) -> Result<()>>,
) -> Result<ExecutionOutput> {
    let request = &compiled.request;
    if !resident_catalog_matches_canonical(context)
        || request.project != context.project_id
        || request.expected_bookmark != context.bookmark
        || request.expected_graph_revision != context.graph.revision()
        || request.expected_layout_version != context.graph.layout_version()
        || request.expected_node_slots != context.graph.node_slot_count()
        || request.expected_edge_slots != context.graph.edge_slot_count()
        || request.layers != plan.read_layers
    {
        return Err(Error::new(
            ErrorCode::GpuAdmissionFailure,
            "resident pattern-comprehension generation no longer matches the canonical statement",
        ));
    }

    check_execution(context)?;
    let pinned = backend.pin_project(context.project_id)?;
    if !pinned.supports_native_variable_path()
        || pinned.resident_bookmark(context.project_id) != Some(context.bookmark)
        || pinned.resident_graph_revision(context.project_id) != Some(context.graph.revision())
    {
        return Err(Error::new(
            ErrorCode::GpuAdmissionFailure,
            "pinned backend does not own the requested native pattern-comprehension generation",
        ));
    }
    check_execution(context)?;
    let validated = pinned
        .execute_variable_path(request, &context.cancellation)?
        .validate_for_publication(request, pinned.kind())?;
    check_execution(context)?;

    let mut publications =
        BTreeMap::<u32, Vec<&crate::execution::ResidentVariablePathPublicationRow>>::new();
    for publication in validated.rows() {
        publications
            .entry(publication.parent_row)
            .or_default()
            .push(publication);
    }

    let mut dependencies = TransactionDependencies::default();
    for dependency in &plan.dependencies {
        let version = context
            .predicate_versions
            .get(dependency)
            .copied()
            .unwrap_or(context.bookmark.index);
        dependencies.predicates.insert(dependency.clone(), version);
    }
    for publication in validated.rows() {
        record_variable_path_publication_dependencies(publication, context, &mut dependencies)?;
    }

    let mut rows = Vec::new();
    let output_names = match &compiled.projection {
        CompiledResidentPatternComprehensionProjection::ParentLists { output_name, item } => {
            let parent_count = usize::try_from(validated.input_cardinality()).map_err(|_| {
                Error::new(
                    ErrorCode::ResultBudgetExceeded,
                    "pattern-comprehension parent cardinality exceeds addressable memory",
                )
            })?;
            if parent_count > context.max_result_rows {
                return Err(Error::new(
                    ErrorCode::ResultBudgetExceeded,
                    "pattern-comprehension parent cardinality exceeds the result row budget",
                ));
            }
            rows.reserve(parent_count);
            for parent in 0..parent_count {
                check_execution(context)?;
                let parent = u32::try_from(parent).map_err(|_| {
                    Error::new(
                        ErrorCode::CorruptStorage,
                        "validated pattern-comprehension parent exceeds the publication ABI",
                    )
                })?;
                let parent_publications = publications.get(&parent).ok_or_else(|| {
                    Error::new(
                        ErrorCode::CorruptStorage,
                        "validated OPTIONAL pattern comprehension omitted a retained parent",
                    )
                })?;
                let mut values = Vec::new();
                for publication in parent_publications {
                    if let Some(path) = publication.path.as_ref() {
                        values.push(render_pattern_comprehension_item(item, path, context)?);
                    }
                }
                let mut row = Row::new();
                row.insert(output_name.clone(), BindingValue::List(values));
                rows.push(row);
            }
            vec![output_name.clone()]
        }
        CompiledResidentPatternComprehensionProjection::IdenticalOutgoingPathGroups {
            list_output_name,
            count_output_name,
        } => {
            if publications.len() > context.max_result_rows {
                return Err(Error::new(
                    ErrorCode::ResultBudgetExceeded,
                    "pattern-comprehension group cardinality exceeds the result row budget",
                ));
            }
            rows.reserve(publications.len());
            for parent_publications in publications.values() {
                check_execution(context)?;
                let mut paths = Vec::with_capacity(parent_publications.len());
                for publication in parent_publications {
                    let path = publication.path.as_ref().ok_or_else(|| {
                        Error::new(
                            ErrorCode::CorruptStorage,
                            "mandatory grouped pattern comprehension published a null path",
                        )
                    })?;
                    paths.push(BindingValue::Path {
                        nodes: path.nodes.clone(),
                        relationships: path.relationships.clone(),
                    });
                }
                if paths.is_empty() {
                    return Err(Error::new(
                        ErrorCode::CorruptStorage,
                        "grouped pattern comprehension published an empty mandatory group",
                    ));
                }
                let count = i64::try_from(paths.len()).map_err(|_| {
                    Error::new(
                        ErrorCode::ResultBudgetExceeded,
                        "pattern-comprehension group count exceeds INTEGER",
                    )
                })?;
                let mut row = Row::new();
                row.insert(list_output_name.clone(), BindingValue::List(paths));
                row.insert(
                    count_output_name.clone(),
                    BindingValue::Value(ResultValue::Scalar(ScalarValue::Integer(count))),
                );
                rows.push(row);
            }
            vec![list_output_name.clone(), count_output_name.clone()]
        }
        CompiledResidentPatternComprehensionProjection::GroupedVariablePathLists {
            list_output_name,
            count_output_name,
        } => {
            let crate::execution::ResidentVariablePathFinalRelation::GroupedPathLists(groups) =
                validated.final_relation()
            else {
                return Err(Error::new(
                    ErrorCode::CorruptStorage,
                    "grouped pattern comprehension omitted its sealed backend relation",
                ));
            };
            if groups.len() > context.max_result_rows {
                return Err(Error::new(
                    ErrorCode::ResultBudgetExceeded,
                    "grouped pattern-comprehension cardinality exceeds the result row budget",
                ));
            }
            rows.reserve(groups.len());
            for group in groups {
                check_execution(context)?;
                let count = i64::try_from(group.parent_count).map_err(|_| {
                    Error::new(
                        ErrorCode::ResultBudgetExceeded,
                        "grouped pattern-comprehension count exceeds INTEGER",
                    )
                })?;
                let paths = group
                    .paths
                    .iter()
                    .map(|path| BindingValue::Path {
                        nodes: path.nodes.clone(),
                        relationships: path.relationships.clone(),
                    })
                    .collect();
                let mut row = Row::new();
                row.insert(list_output_name.clone(), BindingValue::List(paths));
                row.insert(
                    count_output_name.clone(),
                    BindingValue::Value(ResultValue::Scalar(ScalarValue::Integer(count))),
                );
                rows.push(row);
            }
            vec![list_output_name.clone(), count_output_name.clone()]
        }
        CompiledResidentPatternComprehensionProjection::PathNodeOutgoingLabelCounts {
            node_output_name,
            list_output_name,
        } => {
            let crate::execution::ResidentVariablePathFinalRelation::PathNodeLabelCounts(
                count_rows,
            ) = validated.final_relation()
            else {
                return Err(Error::new(
                    ErrorCode::CorruptStorage,
                    "nested pattern comprehension omitted its sealed node-count relation",
                ));
            };
            if count_rows.len() > context.max_result_rows {
                return Err(Error::new(
                    ErrorCode::ResultBudgetExceeded,
                    "nested pattern-comprehension result exceeds the row budget",
                ));
            }
            rows.reserve(count_rows.len());
            for count_row in count_rows {
                let publication = validated
                    .rows()
                    .get(count_row.publication as usize)
                    .ok_or_else(|| {
                        Error::new(
                            ErrorCode::CorruptStorage,
                            "nested pattern-comprehension count names a foreign publication",
                        )
                    })?;
                let mut row = Row::new();
                row.insert(
                    node_output_name.clone(),
                    BindingValue::Node(publication.start),
                );
                row.insert(
                    list_output_name.clone(),
                    BindingValue::List(
                        count_row
                            .counts
                            .iter()
                            .map(|count| {
                                i64::try_from(*count)
                                    .map(|count| {
                                        BindingValue::Value(ResultValue::Scalar(
                                            ScalarValue::Integer(count),
                                        ))
                                    })
                                    .map_err(|_| {
                                        Error::new(
                                            ErrorCode::CorruptStorage,
                                            "nested pattern-comprehension count exceeds INTEGER",
                                        )
                                    })
                            })
                            .collect::<Result<Vec<_>>>()?,
                    ),
                );
                rows.push(row);
            }
            vec![node_output_name.clone(), list_output_name.clone()]
        }
        CompiledResidentPatternComprehensionProjection::OrderedParentPathLists { output_name } => {
            let crate::execution::ResidentVariablePathFinalRelation::OrderedParentPathLists(
                parent_lists,
            ) = validated.final_relation()
            else {
                return Err(Error::new(
                    ErrorCode::CorruptStorage,
                    "ordered pattern comprehension omitted its sealed parent-list relation",
                ));
            };
            if parent_lists.len() > context.max_result_rows {
                return Err(Error::new(
                    ErrorCode::ResultBudgetExceeded,
                    "ordered pattern-comprehension result exceeds the row budget",
                ));
            }
            rows.reserve(parent_lists.len());
            for parent in parent_lists {
                let paths = parent
                    .publications
                    .iter()
                    .map(|publication| {
                        validated
                            .rows()
                            .get(*publication as usize)
                            .and_then(|publication| publication.path.as_ref())
                            .map(|path| BindingValue::Path {
                                nodes: path.nodes.clone(),
                                relationships: path.relationships.clone(),
                            })
                            .ok_or_else(|| {
                                Error::new(
                                    ErrorCode::CorruptStorage,
                                    "ordered pattern-comprehension list names a null or foreign path",
                                )
                            })
                    })
                    .collect::<Result<Vec<_>>>()?;
                let mut row = Row::new();
                row.insert(output_name.clone(), BindingValue::List(paths));
                rows.push(row);
            }
            vec![output_name.clone()]
        }
    };

    let graph = GraphReadView::new(context.graph);
    let result = rows_to_result(
        &rows,
        &output_names,
        &graph,
        context.bookmark,
        StatementStats::default(),
        context.max_batch_rows,
        stream.take(),
    )?;
    Ok(ExecutionOutput {
        result,
        graph_mutations: Vec::new(),
        temporal_mutations: Vec::new(),
        dependencies,
        administrative: None,
        vector_searches: Vec::new(),
        runtime_replans: 0,
    })
}

fn render_pattern_comprehension_item(
    item: &CompiledResidentPatternComprehensionItem,
    path: &crate::execution::ResidentVariablePath,
    context: &ExecutionContext<'_>,
) -> Result<BindingValue> {
    match item {
        CompiledResidentPatternComprehensionItem::Path => Ok(BindingValue::Path {
            nodes: path.nodes.clone(),
            relationships: path.relationships.clone(),
        }),
        CompiledResidentPatternComprehensionItem::EndNodeProperty { property } => {
            let dense = path.end().ok_or_else(|| {
                Error::new(
                    ErrorCode::CorruptStorage,
                    "validated one-hop pattern comprehension omitted its endpoint",
                )
            })?;
            let node = context.graph.node_dense(dense).ok_or_else(|| {
                Error::new(
                    ErrorCode::CorruptStorage,
                    "validated pattern comprehension selected a deleted endpoint",
                )
            })?;
            property.map_or(
                Ok(BindingValue::Value(ResultValue::Scalar(ScalarValue::Null))),
                |property| {
                    node.property(property).map_or(
                        Ok(BindingValue::Value(ResultValue::Scalar(ScalarValue::Null))),
                        |value| ResultValue::from_property(value).map(BindingValue::Value),
                    )
                },
            )
        }
        CompiledResidentPatternComprehensionItem::RelationshipProperty { property } => {
            let [dense] = path.relationships.as_slice() else {
                return Err(Error::new(
                    ErrorCode::CorruptStorage,
                    "validated fixed-hop pattern comprehension published a non-singleton relationship trail",
                ));
            };
            let relationship = context.graph.edge_dense(*dense).ok_or_else(|| {
                Error::new(
                    ErrorCode::CorruptStorage,
                    "validated pattern comprehension selected a deleted relationship",
                )
            })?;
            property.map_or(
                Ok(BindingValue::Value(ResultValue::Scalar(ScalarValue::Null))),
                |property| {
                    relationship.property(property).map_or(
                        Ok(BindingValue::Value(ResultValue::Scalar(ScalarValue::Null))),
                        |value| ResultValue::from_property(value).map(BindingValue::Value),
                    )
                },
            )
        }
    }
}

/// Execute one complete variable-length path command and publish only after the selected backend
/// proves the immutable scan, every traversal segment, and final result boundary. Canonical
/// property decoding happens at the ordinary result edge; path discovery and uniqueness never
/// return to the generic host executor.
fn execute_resident_variable_path_plan(
    plan: &PhysicalPlan,
    compiled: &CompiledResidentVariablePathPlan,
    backend: &dyn ExecutionBackend,
    context: &ExecutionContext<'_>,
    stream: &mut Option<&mut dyn FnMut(ExecutionStreamItem) -> Result<()>>,
) -> Result<ExecutionOutput> {
    check_execution(context)?;
    let pinned = backend.pin_project(context.project_id)?;
    if !pinned.supports_native_variable_path()
        || pinned.resident_bookmark(context.project_id) != Some(context.bookmark)
        || pinned.resident_graph_revision(context.project_id) != Some(context.graph.revision())
    {
        return Err(Error::new(
            ErrorCode::GpuAdmissionFailure,
            "pinned backend does not own the requested native variable-path generation",
        ));
    }
    check_execution(context)?;
    let validated = pinned
        .execute_variable_path(&compiled.request, &context.cancellation)?
        .validate_for_publication(&compiled.request, pinned.kind())?;
    check_execution(context)?;

    let graph = GraphReadView::new(context.graph);
    let (path_count_output, sealed_bound_count_output) = match compiled.outputs.as_slice() {
        [CompiledResidentVariablePathOutput::CountRelationships { name }] => {
            (Some(name.as_str()), None)
        }
        [CompiledResidentVariablePathOutput::CountBoundUndirectedRelationshipPaths {
            name,
            ..
        }] => (None, Some(name.as_str())),
        outputs
            if outputs.iter().any(|output| {
                matches!(
                    output,
                    CompiledResidentVariablePathOutput::CountRelationships { .. }
                        | CompiledResidentVariablePathOutput::CountBoundUndirectedRelationshipPaths {
                            ..
                        }
                )
            }) =>
        {
            return Err(Error::internal(
                "resident variable-path relationship count escaped its exact singleton output profile",
            ));
        }
        _ => (None, None),
    };
    let path_equality_output = match compiled.outputs.as_slice() {
        [CompiledResidentVariablePathOutput::PathEquality { name }] => Some(name.as_str()),
        outputs
            if outputs.iter().any(|output| {
                matches!(
                    output,
                    CompiledResidentVariablePathOutput::PathEquality { .. }
                )
            }) =>
        {
            return Err(Error::internal(
                "resident independent path equality escaped its exact singleton output profile",
            ));
        }
        _ => None,
    };
    let final_nodes_output = match compiled.outputs.as_slice() {
        [CompiledResidentVariablePathOutput::FinalNodes { name }] => Some(name.as_str()),
        outputs
            if outputs.iter().any(|output| {
                matches!(
                    output,
                    CompiledResidentVariablePathOutput::FinalNodes { .. }
                )
            }) =>
        {
            return Err(Error::internal(
                "sealed variable-path node relation escaped its singleton output profile",
            ));
        }
        _ => None,
    };
    let final_integer_output = match compiled.outputs.as_slice() {
        [CompiledResidentVariablePathOutput::FinalOptionalInteger { name }] => Some(name.as_str()),
        outputs
            if outputs.iter().any(|output| {
                matches!(
                    output,
                    CompiledResidentVariablePathOutput::FinalOptionalInteger { .. }
                )
            }) =>
        {
            return Err(Error::internal(
                "sealed variable-path integer relation escaped its singleton output profile",
            ));
        }
        _ => None,
    };
    let final_mixed_output = match compiled.outputs.as_slice() {
        [CompiledResidentVariablePathOutput::FinalMixedTypeValues { name }] => Some(name.as_str()),
        outputs
            if outputs.iter().any(|output| {
                matches!(
                    output,
                    CompiledResidentVariablePathOutput::FinalMixedTypeValues { .. }
                )
            }) =>
        {
            return Err(Error::internal(
                "sealed mixed-type path relation escaped its singleton output profile",
            ));
        }
        _ => None,
    };
    let grouped_path_length_outputs = match compiled.outputs.as_slice() {
        [
            CompiledResidentVariablePathOutput::FinalGroupedNodePaths { name: paths_name },
            CompiledResidentVariablePathOutput::FinalGroupedPathLength { name: length_name },
        ] => Some((paths_name.as_str(), length_name.as_str())),
        outputs
            if outputs.iter().any(|output| {
                matches!(
                    output,
                    CompiledResidentVariablePathOutput::FinalGroupedNodePaths { .. }
                        | CompiledResidentVariablePathOutput::FinalGroupedPathLength { .. }
                )
            }) =>
        {
            return Err(Error::internal(
                "sealed grouped path-length relation escaped its exact output profile",
            ));
        }
        _ => None,
    };
    let grouped_end_average_outputs = match compiled.outputs.as_slice() {
        [
            CompiledResidentVariablePathOutput::FinalGroupedEndNode { name: end_name },
            CompiledResidentVariablePathOutput::FinalGroupedAveragePathLength {
                name: average_name,
            },
        ] => Some((end_name.as_str(), average_name.as_str())),
        outputs
            if outputs.iter().any(|output| {
                matches!(
                    output,
                    CompiledResidentVariablePathOutput::FinalGroupedEndNode { .. }
                        | CompiledResidentVariablePathOutput::FinalGroupedAveragePathLength { .. }
                )
            }) =>
        {
            return Err(Error::internal(
                "sealed grouped terminal-node average escaped its exact output profile",
            ));
        }
        _ => None,
    };
    let grouped_minimum_endpoint_outputs = match compiled.outputs.as_slice() {
        [
            CompiledResidentVariablePathOutput::FinalMinimumGroupStartProperty {
                name: start_name,
                property: start_property,
            },
            CompiledResidentVariablePathOutput::FinalMinimumGroupEndProperties {
                name: ends_name,
                property: end_property,
            },
            CompiledResidentVariablePathOutput::FinalMinimumGroupLength { name: length_name },
        ] if start_property == end_property => Some((
            start_name.as_str(),
            ends_name.as_str(),
            length_name.as_str(),
            *start_property,
        )),
        outputs
            if outputs.iter().any(|output| {
                matches!(
                    output,
                    CompiledResidentVariablePathOutput::FinalMinimumGroupStartProperty { .. }
                        | CompiledResidentVariablePathOutput::FinalMinimumGroupEndProperties { .. }
                        | CompiledResidentVariablePathOutput::FinalMinimumGroupLength { .. }
                )
            }) =>
        {
            return Err(Error::internal(
                "sealed minimum path-length endpoint list escaped its exact output profile",
            ));
        }
        _ => None,
    };
    let publication_indices = match validated.final_relation() {
        crate::execution::ResidentVariablePathFinalRelation::SelectedPublications(selected)
        | crate::execution::ResidentVariablePathFinalRelation::OrderedPublications(selected) => {
            selected
                .iter()
                .map(|publication| *publication as usize)
                .collect::<Vec<_>>()
        }
        _ => (0..validated.rows().len()).collect(),
    };
    let mut rows = Vec::with_capacity(
        if path_count_output.is_some()
            || sealed_bound_count_output.is_some()
            || final_integer_output.is_some()
            || final_mixed_output.is_some()
        {
            1
        } else if let crate::execution::ResidentVariablePathFinalRelation::GroupedNodePathsByLength(
            groups,
        ) = validated.final_relation()
        {
            groups.len()
        } else if let crate::execution::ResidentVariablePathFinalRelation::GroupedEndNodeAveragePathLength(
            groups,
        ) = validated.final_relation()
        {
            groups.len()
        } else if let crate::execution::ResidentVariablePathFinalRelation::GroupedMinimumPathLengthEndpointLists(
            groups,
        ) = validated.final_relation()
        {
            groups.len()
        } else if let crate::execution::ResidentVariablePathFinalRelation::Nodes(values) =
            validated.final_relation()
        {
            values.len()
        } else if let crate::execution::ResidentVariablePathFinalRelation::Booleans(values) =
            validated.final_relation()
        {
            values.len()
        } else {
            publication_indices.len()
        },
    );
    let mut dependencies = TransactionDependencies::default();
    for dependency in &plan.dependencies {
        let version = context
            .predicate_versions
            .get(dependency)
            .copied()
            .unwrap_or(context.bookmark.index);
        dependencies.predicates.insert(dependency.clone(), version);
    }
    if let Some((end_name, average_name)) = grouped_end_average_outputs {
        let crate::execution::ResidentVariablePathFinalRelation::GroupedEndNodeAveragePathLength(
            groups,
        ) = validated.final_relation()
        else {
            return Err(Error::new(
                ErrorCode::CorruptStorage,
                "sealed grouped terminal-node average omitted its final relation",
            ));
        };
        if groups.len() > context.max_result_rows {
            return Err(Error::new(
                ErrorCode::ResultBudgetExceeded,
                "grouped terminal-node average exceeds the result row budget",
            ));
        }
        for group in groups {
            let average = f64::from_bits(group.average_length_bits);
            if !average.is_finite() {
                return Err(Error::new(
                    ErrorCode::CorruptStorage,
                    "grouped terminal-node average is non-finite",
                ));
            }
            let mut row = Row::new();
            row.insert(end_name.to_owned(), BindingValue::Node(group.end));
            row.insert(
                average_name.to_owned(),
                BindingValue::Value(ResultValue::Scalar(ScalarValue::Float(OrderedFloat(
                    average,
                )))),
            );
            rows.push(row);
        }
        for publication in validated.rows() {
            record_variable_path_publication_dependencies(publication, context, &mut dependencies)?;
        }
    } else if let Some((start_name, ends_name, length_name, property)) =
        grouped_minimum_endpoint_outputs
    {
        let crate::execution::ResidentVariablePathFinalRelation::GroupedMinimumPathLengthEndpointLists(
            groups,
        ) = validated.final_relation()
        else {
            return Err(Error::new(
                ErrorCode::CorruptStorage,
                "sealed minimum path-length endpoint list omitted its final relation",
            ));
        };
        if groups.len() > context.max_result_rows {
            return Err(Error::new(
                ErrorCode::ResultBudgetExceeded,
                "minimum path-length endpoint list exceeds the result row budget",
            ));
        }
        for group in groups {
            let start = context.graph.node_dense(group.start).ok_or_else(|| {
                Error::new(
                    ErrorCode::CorruptStorage,
                    "minimum path-length endpoint group selected a deleted start node",
                )
            })?;
            let start_value = start.property(property).ok_or_else(|| {
                Error::new(
                    ErrorCode::CorruptStorage,
                    "minimum path-length endpoint group lost its proven start property",
                )
            })?;
            if !matches!(start_value, ScalarValue::String(_)) {
                return Err(Error::new(
                    ErrorCode::CorruptStorage,
                    "minimum path-length endpoint start property changed scalar family",
                ));
            }
            let start_value = ResultValue::from_property(start_value)?;
            let ends = group
                .ends
                .iter()
                .map(|end| {
                    let node = context.graph.node_dense(*end).ok_or_else(|| {
                        Error::new(
                            ErrorCode::CorruptStorage,
                            "minimum path-length endpoint group selected a deleted terminal node",
                        )
                    })?;
                    let value = node.property(property).ok_or_else(|| {
                        Error::new(
                            ErrorCode::CorruptStorage,
                            "minimum path-length endpoint group lost its proven terminal property",
                        )
                    })?;
                    if !matches!(value, ScalarValue::String(_)) {
                        return Err(Error::new(
                            ErrorCode::CorruptStorage,
                            "minimum path-length endpoint property changed scalar family",
                        ));
                    }
                    ResultValue::from_property(value).map(BindingValue::Value)
                })
                .collect::<Result<Vec<_>>>()?;
            let mut row = Row::new();
            row.insert(start_name.to_owned(), BindingValue::Value(start_value));
            row.insert(ends_name.to_owned(), BindingValue::List(ends));
            row.insert(
                length_name.to_owned(),
                BindingValue::Value(ResultValue::Scalar(ScalarValue::Integer(i64::from(
                    group.length,
                )))),
            );
            rows.push(row);
        }
        for publication in validated.rows() {
            record_variable_path_publication_dependencies(publication, context, &mut dependencies)?;
        }
    } else if let Some((paths_name, length_name)) = grouped_path_length_outputs {
        let crate::execution::ResidentVariablePathFinalRelation::GroupedNodePathsByLength(groups) =
            validated.final_relation()
        else {
            return Err(Error::new(
                ErrorCode::CorruptStorage,
                "sealed grouped path-length projection omitted its final relation",
            ));
        };
        if groups.len() > context.max_result_rows {
            return Err(Error::new(
                ErrorCode::ResultBudgetExceeded,
                "grouped path-length relation exceeds the result row budget",
            ));
        }
        for group in groups {
            let length = i64::from(group.length);
            let paths = group
                .paths
                .iter()
                .map(|path| {
                    BindingValue::List(path.nodes.iter().copied().map(BindingValue::Node).collect())
                })
                .collect();
            let mut row = Row::new();
            row.insert(paths_name.to_owned(), BindingValue::List(paths));
            row.insert(
                length_name.to_owned(),
                BindingValue::Value(ResultValue::Scalar(ScalarValue::Integer(length))),
            );
            rows.push(row);
        }
        for publication in validated.rows() {
            record_variable_path_publication_dependencies(publication, context, &mut dependencies)?;
        }
    } else if let Some(output_name) = final_mixed_output {
        let crate::execution::ResidentVariablePathFinalRelation::MixedTypeValues(values) =
            validated.final_relation()
        else {
            return Err(Error::new(
                ErrorCode::CorruptStorage,
                "sealed mixed-type path projection omitted its final relation",
            ));
        };
        if values.len() > context.max_result_rows {
            return Err(Error::new(
                ErrorCode::ResultBudgetExceeded,
                "sealed mixed-type path relation exceeds the result row budget",
            ));
        }
        for value in values {
            use crate::execution::ResidentVariablePathMixedTypeValue as Mixed;
            let publication = match value {
                Mixed::Node(publication)
                | Mixed::Relationship(publication)
                | Mixed::Path(publication) => Some(*publication as usize),
                _ => None,
            };
            let path = publication
                .map(|publication| {
                    validated
                        .rows()
                        .get(publication)
                        .and_then(|row| row.path.as_ref())
                        .ok_or_else(|| {
                            Error::new(
                                ErrorCode::CorruptStorage,
                                "sealed mixed-type path value names a foreign publication",
                            )
                        })
                })
                .transpose()?;
            let binding = match value {
                Mixed::Map => BindingValue::Map(BTreeMap::from([(
                    "a".to_owned(),
                    BindingValue::Value(ResultValue::Scalar(ScalarValue::String(Arc::from("map")))),
                )])),
                Mixed::Node(_) => BindingValue::Node(
                    path.and_then(|path| path.nodes.first())
                        .copied()
                        .ok_or_else(|| {
                            Error::new(
                                ErrorCode::CorruptStorage,
                                "sealed mixed-type node value omitted its path start",
                            )
                        })?,
                ),
                Mixed::Relationship(_) => BindingValue::Relationship(
                    path.and_then(|path| path.relationships.first())
                        .copied()
                        .ok_or_else(|| {
                            Error::new(
                                ErrorCode::CorruptStorage,
                                "sealed mixed-type relationship value omitted its one-hop edge",
                            )
                        })?,
                ),
                Mixed::List => BindingValue::List(vec![BindingValue::Value(ResultValue::Scalar(
                    ScalarValue::String(Arc::from("list")),
                ))]),
                Mixed::Path(_) => {
                    let path = path.ok_or_else(|| {
                        Error::new(
                            ErrorCode::CorruptStorage,
                            "sealed mixed-type path value omitted its publication",
                        )
                    })?;
                    BindingValue::Path {
                        nodes: path.nodes.clone(),
                        relationships: path.relationships.clone(),
                    }
                }
                Mixed::String => {
                    BindingValue::Value(ResultValue::Scalar(ScalarValue::String(Arc::from("text"))))
                }
                Mixed::Boolean => {
                    BindingValue::Value(ResultValue::Scalar(ScalarValue::Boolean(false)))
                }
                Mixed::Number => {
                    BindingValue::Value(ResultValue::Scalar(ScalarValue::Float(OrderedFloat(1.5))))
                }
                Mixed::NaN => BindingValue::Value(ResultValue::Scalar(ScalarValue::Float(
                    OrderedFloat(f64::NAN),
                ))),
                Mixed::Null => BindingValue::Value(ResultValue::Scalar(ScalarValue::Null)),
            };
            let mut row = Row::new();
            row.insert(output_name.to_owned(), binding);
            rows.push(row);
        }
        for publication in validated.rows() {
            record_variable_path_publication_dependencies(publication, context, &mut dependencies)?;
        }
    } else if let Some(output_name) = final_nodes_output {
        let crate::execution::ResidentVariablePathFinalRelation::Nodes(values) =
            validated.final_relation()
        else {
            return Err(Error::new(
                ErrorCode::CorruptStorage,
                "sealed variable-path node projection omitted its final relation",
            ));
        };
        if values.len() > context.max_result_rows {
            return Err(Error::new(
                ErrorCode::ResultBudgetExceeded,
                "sealed variable-path node relation exceeds the result row budget",
            ));
        }
        for value in values {
            let mut row = Row::new();
            row.insert(output_name.to_owned(), BindingValue::Node(*value));
            rows.push(row);
        }
        for publication in validated.rows() {
            record_variable_path_publication_dependencies(publication, context, &mut dependencies)?;
        }
    } else if let Some(output_name) = final_integer_output {
        let crate::execution::ResidentVariablePathFinalRelation::OptionalInteger(value) =
            validated.final_relation()
        else {
            return Err(Error::new(
                ErrorCode::CorruptStorage,
                "sealed variable-path aggregate omitted its nullable integer relation",
            ));
        };
        let mut row = Row::new();
        row.insert(
            output_name.to_owned(),
            BindingValue::Value(ResultValue::Scalar(
                value.map_or(ScalarValue::Null, ScalarValue::Integer),
            )),
        );
        rows.push(row);
        for publication in validated.rows() {
            record_variable_path_publication_dependencies(publication, context, &mut dependencies)?;
        }
    } else if let Some(output_name) = path_equality_output {
        let crate::execution::ResidentVariablePathFinalRelation::Booleans(values) =
            validated.final_relation()
        else {
            return Err(Error::new(
                ErrorCode::CorruptStorage,
                "independent path equality omitted its sealed boolean relation",
            ));
        };
        if values.len() > context.max_result_rows {
            return Err(Error::new(
                ErrorCode::ResultBudgetExceeded,
                "independent path equality exceeds the result row budget",
            ));
        }
        for value in values {
            let mut row = Row::new();
            row.insert(
                output_name.to_owned(),
                BindingValue::Value(ResultValue::Scalar(ScalarValue::Boolean(*value))),
            );
            rows.push(row);
        }
        for publication in validated.rows() {
            record_variable_path_publication_dependencies(publication, context, &mut dependencies)?;
        }
    } else if let Some(output_name) = sealed_bound_count_output {
        let crate::execution::ResidentVariablePathFinalRelation::Count(count) =
            validated.final_relation()
        else {
            return Err(Error::new(
                ErrorCode::CorruptStorage,
                "bound-relationship path count omitted its sealed backend relation",
            ));
        };
        let count = i64::try_from(*count).map_err(|_| {
            Error::new(
                ErrorCode::CorruptStorage,
                "sealed bound-relationship path count exceeds INTEGER",
            )
        })?;
        let mut row = Row::new();
        row.insert(
            output_name.to_owned(),
            BindingValue::Value(ResultValue::Scalar(ScalarValue::Integer(count))),
        );
        rows.push(row);
        for publication in validated.rows() {
            record_variable_path_publication_dependencies(publication, context, &mut dependencies)?;
        }
    } else if let Some(output_name) = path_count_output {
        let mut count = 0_usize;
        for publication in validated.rows() {
            check_execution(context)?;
            let Some(path) = publication.path.as_ref() else {
                return Err(Error::new(
                    ErrorCode::CorruptStorage,
                    "mandatory resident path count published a null path",
                ));
            };
            if path.relationships.is_empty() {
                return Err(Error::new(
                    ErrorCode::CorruptStorage,
                    "unbounded Match9 relationship count published an empty relationship list",
                ));
            }
            count = count.checked_add(1).ok_or_else(|| {
                Error::new(
                    ErrorCode::ResultBudgetExceeded,
                    "resident path count exceeds host addressability",
                )
            })?;
            record_variable_path_publication_dependencies(publication, context, &mut dependencies)?;
        }
        let count = i64::try_from(count).map_err(|_| {
            Error::new(
                ErrorCode::ResultBudgetExceeded,
                "resident path count exceeds INTEGER",
            )
        })?;
        let mut row = Row::new();
        row.insert(
            output_name.to_owned(),
            BindingValue::Value(ResultValue::Scalar(ScalarValue::Integer(count))),
        );
        rows.push(row);
    } else {
        for publication_index in publication_indices {
            check_execution(context)?;
            let publication = validated.rows().get(publication_index).ok_or_else(|| {
                Error::new(
                    ErrorCode::CorruptStorage,
                    "selected variable-path relation names a foreign publication",
                )
            })?;
            let path = publication.path.as_ref();
            let mut row = Row::new();
            for output in &compiled.outputs {
                let value = match output {
                    CompiledResidentVariablePathOutput::Node { position, .. } => {
                        variable_path_publication_node(publication, *position)?
                            .map_or(BindingValue::Null, BindingValue::Node)
                    }
                    CompiledResidentVariablePathOutput::NodeProperty {
                        position, property, ..
                    } => {
                        if let Some(dense) = variable_path_publication_node(publication, *position)?
                        {
                            let node = context.graph.node_dense(dense).ok_or_else(|| {
                                Error::new(
                                    ErrorCode::CorruptStorage,
                                    "validated variable path selected a deleted projected node",
                                )
                            })?;
                            node.property(*property).map_or(
                                Ok(BindingValue::Value(ResultValue::Scalar(ScalarValue::Null))),
                                |value| ResultValue::from_property(value).map(BindingValue::Value),
                            )?
                        } else {
                            BindingValue::Value(ResultValue::Scalar(ScalarValue::Null))
                        }
                    }
                    CompiledResidentVariablePathOutput::Path { .. } => {
                        path.map_or(BindingValue::Null, |path| BindingValue::Path {
                            nodes: path.nodes.clone(),
                            relationships: path.relationships.clone(),
                        })
                    }
                    CompiledResidentVariablePathOutput::Nodes { .. } => {
                        path.map_or(BindingValue::Null, |path| {
                            BindingValue::List(
                                path.nodes.iter().copied().map(BindingValue::Node).collect(),
                            )
                        })
                    }
                    CompiledResidentVariablePathOutput::Relationships { .. } => {
                        path.map_or(BindingValue::Null, |path| {
                            BindingValue::List(
                                path.relationships
                                    .iter()
                                    .copied()
                                    .map(BindingValue::Relationship)
                                    .collect(),
                            )
                        })
                    }
                    CompiledResidentVariablePathOutput::OneHopEntityList { .. } => {
                        let (start, relationship, end) =
                            variable_path_publication_one_hop_entities(publication)?;
                        BindingValue::List(vec![
                            BindingValue::Node(start),
                            BindingValue::Relationship(relationship),
                            BindingValue::Node(end),
                        ])
                    }
                    CompiledResidentVariablePathOutput::OneHopEntityMap {
                        start_key,
                        relationship_key,
                        end_key,
                        ..
                    } => {
                        let (start, relationship, end) =
                            variable_path_publication_one_hop_entities(publication)?;
                        BindingValue::Map(BTreeMap::from([
                            (start_key.clone(), BindingValue::Node(start)),
                            (
                                relationship_key.clone(),
                                BindingValue::Relationship(relationship),
                            ),
                            (end_key.clone(), BindingValue::Node(end)),
                        ]))
                    }
                    CompiledResidentVariablePathOutput::OneHopRelationship { .. } => {
                        let (_, relationship, _) =
                            variable_path_publication_one_hop_entities(publication)?;
                        BindingValue::Relationship(relationship)
                    }
                    CompiledResidentVariablePathOutput::LastRelationship { .. } => path
                        .and_then(|path| path.relationships.last())
                        .copied()
                        .map_or(BindingValue::Null, BindingValue::Relationship),
                    CompiledResidentVariablePathOutput::CountRelationships { .. } => {
                        return Err(Error::internal(
                            "resident variable-path relationship count reached row-wise publication",
                        ));
                    }
                    CompiledResidentVariablePathOutput::CountBoundUndirectedRelationshipPaths {
                        ..
                    } => {
                        return Err(Error::internal(
                            "resident bound-relationship path count reached row-wise publication",
                        ));
                    }
                    CompiledResidentVariablePathOutput::Length { .. } => {
                        if let Some(path) = path {
                            let length = i64::try_from(path.relationships.len()).map_err(|_| {
                                Error::new(
                                    ErrorCode::CorruptStorage,
                                    "validated variable path length exceeds the Cypher integer domain",
                                )
                            })?;
                            BindingValue::Value(ResultValue::Scalar(ScalarValue::Integer(length)))
                        } else {
                            BindingValue::Null
                        }
                    }
                    CompiledResidentVariablePathOutput::PathEquality { .. } => {
                        return Err(Error::internal(
                            "sealed variable-path final relation reached row-wise publication",
                        ));
                    }
                    CompiledResidentVariablePathOutput::FinalNodes { .. }
                    | CompiledResidentVariablePathOutput::FinalOptionalInteger { .. }
                    | CompiledResidentVariablePathOutput::FinalMixedTypeValues { .. }
                    | CompiledResidentVariablePathOutput::FinalGroupedNodePaths { .. }
                    | CompiledResidentVariablePathOutput::FinalGroupedPathLength { .. }
                    | CompiledResidentVariablePathOutput::FinalGroupedEndNode { .. }
                    | CompiledResidentVariablePathOutput::FinalGroupedAveragePathLength {
                        ..
                    }
                    | CompiledResidentVariablePathOutput::FinalMinimumGroupStartProperty {
                        ..
                    }
                    | CompiledResidentVariablePathOutput::FinalMinimumGroupEndProperties {
                        ..
                    }
                    | CompiledResidentVariablePathOutput::FinalMinimumGroupLength { .. } => {
                        return Err(Error::internal(
                            "sealed variable-path post projection reached row-wise publication",
                        ));
                    }
                };
                row.insert(output.name().to_owned(), value);
            }
            rows.push(row);

            record_variable_path_publication_dependencies(publication, context, &mut dependencies)?;
        }
    }
    let output_names = compiled
        .outputs
        .iter()
        .map(|output| output.name().to_owned())
        .collect::<Vec<_>>();
    let result = rows_to_result(
        &rows,
        &output_names,
        &graph,
        context.bookmark,
        StatementStats::default(),
        context.max_batch_rows,
        stream.take(),
    )?;
    Ok(ExecutionOutput {
        result,
        graph_mutations: Vec::new(),
        temporal_mutations: Vec::new(),
        dependencies,
        administrative: None,
        vector_searches: Vec::new(),
        runtime_replans: 0,
    })
}

fn variable_path_publication_one_hop_entities(
    publication: &crate::execution::ResidentVariablePathPublicationRow,
) -> Result<(u32, u32, u32)> {
    let Some(path) = publication.path.as_ref() else {
        return Err(Error::new(
            ErrorCode::CorruptStorage,
            "validated mandatory one-hop publication was null-extended",
        ));
    };
    let ([start, end], [relationship]) = (path.nodes.as_slice(), path.relationships.as_slice())
    else {
        return Err(Error::new(
            ErrorCode::CorruptStorage,
            "validated fixed one-hop publication has a malformed entity trail",
        ));
    };
    if publication.start != *start {
        return Err(Error::new(
            ErrorCode::CorruptStorage,
            "validated fixed one-hop publication start disagrees with its trail",
        ));
    }
    Ok((*start, *relationship, *end))
}

fn variable_path_publication_node(
    publication: &crate::execution::ResidentVariablePathPublicationRow,
    position: CompiledResidentVariablePathNodePosition,
) -> Result<Option<u32>> {
    match position {
        CompiledResidentVariablePathNodePosition::Start => Ok(Some(publication.start)),
        CompiledResidentVariablePathNodePosition::BoundTerminal => {
            publication.bound_terminal.map(Some).ok_or_else(|| {
                Error::new(
                    ErrorCode::CorruptStorage,
                    "validated variable path omitted its retained bound terminal",
                )
            })
        }
        CompiledResidentVariablePathNodePosition::SegmentEnd(segment) => {
            let Some(path) = publication.path.as_ref() else {
                return Ok(None);
            };
            let boundary = path
                .segment_relationship_ends
                .get(segment as usize)
                .copied()
                .ok_or_else(|| {
                    Error::new(
                        ErrorCode::CorruptStorage,
                        "validated variable path omitted an intermediate segment boundary",
                    )
                })? as usize;
            path.nodes.get(boundary).copied().map(Some).ok_or_else(|| {
                Error::new(
                    ErrorCode::CorruptStorage,
                    "validated variable-path segment boundary exceeds its node trail",
                )
            })
        }
        CompiledResidentVariablePathNodePosition::End => {
            Ok(publication.path.as_ref().and_then(|path| path.end()))
        }
    }
}

fn record_variable_path_publication_dependencies(
    publication: &crate::execution::ResidentVariablePathPublicationRow,
    context: &ExecutionContext<'_>,
    dependencies: &mut TransactionDependencies,
) -> Result<()> {
    let path = publication.path.as_ref();
    let retained_nodes = std::iter::once(publication.start)
        .chain(publication.bound_terminal)
        .chain(path.into_iter().flat_map(|path| path.nodes.iter().copied()));
    for dense in retained_nodes {
        let selected = context.graph.node_dense(dense).ok_or_else(|| {
            Error::new(
                ErrorCode::CorruptStorage,
                "validated variable path selected a deleted node",
            )
        })?;
        dependencies
            .entities
            .insert(EntityDependency::Node(selected.id()), selected.revision());
    }
    for dense in path
        .into_iter()
        .flat_map(|path| path.relationships.iter().copied())
    {
        let selected = context.graph.edge_dense(dense).ok_or_else(|| {
            Error::new(
                ErrorCode::CorruptStorage,
                "validated variable path selected a deleted relationship",
            )
        })?;
        dependencies.entities.insert(
            EntityDependency::Relationship(selected.id()),
            selected.revision(),
        );
    }
    Ok(())
}

fn execute_resident_nullable_relation_plan(
    plan: &PhysicalPlan,
    compiled: &CompiledResidentNullableRelationPlan,
    backend: &dyn ExecutionBackend,
    context: &ExecutionContext<'_>,
    stream: &mut Option<&mut dyn FnMut(ExecutionStreamItem) -> Result<()>>,
) -> Result<ExecutionOutput> {
    let generation = compiled.request.generation;
    if !resident_catalog_matches_canonical(context)
        || generation.catalog_generation != context.binding_catalog.optimizer_generation()
        || generation.project != context.project_id
        || generation.bookmark != context.bookmark
        || generation.graph_revision != context.graph.revision()
        || generation.layout_version != context.graph.layout_version()
    {
        return Err(Error::new(
            ErrorCode::GpuAdmissionFailure,
            "resident nullable relation does not match the canonical graph/catalog generation",
        ));
    }

    check_execution(context)?;
    let pinned = backend.pin_project(context.project_id)?;
    if pinned.resident_bookmark(context.project_id) != Some(context.bookmark)
        || pinned.resident_graph_revision(context.project_id) != Some(context.graph.revision())
    {
        return Err(Error::new(
            ErrorCode::GpuAdmissionFailure,
            "resident nullable backend does not own the requested canonical snapshot",
        ));
    }

    check_execution(context)?;
    if !compiled.request.predicate_program.is_empty()
        && !pinned.supports_nullable_relation_predicates()
    {
        return Err(Error::new(
            ErrorCode::GpuAdmissionFailure,
            "selected backend has no native nullable predicate/filter stages",
        ));
    }
    if compiled.request.program.requires_stable_scope_limit()?
        && !pinned.supports_nullable_relation_scope_limit()
    {
        return Err(Error::new(
            ErrorCode::GpuAdmissionFailure,
            "selected backend has no native nullable stable scope-limit stage",
        ));
    }
    if compiled.request.program.requires_existing_relationship()?
        && !pinned.supports_nullable_relation_existing_relationship()
    {
        return Err(Error::new(
            ErrorCode::GpuAdmissionFailure,
            "selected backend has no native nullable existing-relationship expansion",
        ));
    }
    if compiled
        .request
        .predicate_program
        .requires_relationship_endpoint_seed()
        && !pinned.supports_nullable_relation_relationship_endpoint_seed()
    {
        return Err(Error::new(
            ErrorCode::GpuAdmissionFailure,
            "selected backend has no native nullable relationship-endpoint seed",
        ));
    }
    if compiled
        .request
        .predicate_program
        .requires_string_property_equality()
        && !pinned.supports_nullable_relation_string_property_equality()
    {
        return Err(Error::new(
            ErrorCode::GpuAdmissionFailure,
            "selected backend has no native nullable string-property equality",
        ));
    }
    let raw = pinned.execute_nullable_relation(&compiled.request, &context.cancellation)?;
    let completion = match pinned.kind() {
        crate::execution::BackendKind::Cpu => ResidentDeviceCompletion::CpuReference,
        crate::execution::BackendKind::Metal => ResidentDeviceCompletion::Metal,
        crate::execution::BackendKind::Cuda => {
            return Err(Error::new(
                ErrorCode::GpuAdmissionFailure,
                "selected backend has no validated nullable-relation completion kind",
            ));
        }
    };
    let validated = raw.validate(&compiled.request, completion)?;
    check_execution(context)?;
    let parts = validated.into_parts();
    if parts.row_count > context.max_result_rows || parts.columns.len() != compiled.outputs.len() {
        return Err(Error::new(
            ErrorCode::CorruptStorage,
            "validated resident nullable result violates its output row or column boundary",
        ));
    }
    for (column, output) in parts.columns.iter().zip(&compiled.outputs) {
        if column.source() != output.source.clone() || column.source_rows().len() != parts.row_count
        {
            return Err(Error::new(
                ErrorCode::CorruptStorage,
                "validated resident nullable output disagrees with the compiled projection",
            ));
        }
    }

    let mut dependencies = TransactionDependencies::default();
    for dependency in &plan.dependencies {
        let version = context
            .predicate_versions
            .get(dependency)
            .copied()
            .unwrap_or(context.bookmark.index);
        dependencies.predicates.insert(dependency.clone(), version);
    }

    // Decode every private device column before exposing schema or batches. Scalar properties are
    // read only from the validated device-authored payload; the canonical graph is consulted for
    // their source entity's visibility and dependency revision, never for the property value.
    let graph = GraphReadView::new(context.graph);
    let mut decoded_columns = Vec::with_capacity(parts.columns.len());
    for (column, output) in parts.columns.iter().zip(&compiled.outputs) {
        let mut values = Vec::with_capacity(parts.row_count);
        for position in 0..parts.row_count {
            if position.is_multiple_of(4096) {
                check_execution(context)?;
            }
            let dense = column.source_rows()[position];
            record_resident_nullable_source_dependency(
                dense,
                output.source.kind(),
                plan,
                context,
                &mut dependencies,
            )?;
            values.push(resident_nullable_output_value(
                column, position, dense, &graph,
            )?);
        }
        let value_type = result_values_type(&values);
        decoded_columns.push((output.name.clone(), value_type, values));
    }

    let schema = decoded_columns
        .iter()
        .map(|(name, value_type, _)| (name.clone(), value_type.clone()))
        .collect::<Vec<_>>();
    if let Some(emit) = stream.as_deref_mut() {
        emit(ExecutionStreamItem::Schema(schema.clone()))?;
    }
    let mut batches = Vec::new();
    let batch_size = context.max_batch_rows.max(1);
    for start in (0..parts.row_count).step_by(batch_size) {
        let end = start.saturating_add(batch_size).min(parts.row_count);
        let batch = ResultBatch {
            row_count: end - start,
            columns: decoded_columns
                .iter()
                .map(|(name, value_type, values)| ResultColumn {
                    name: name.clone(),
                    value_type: value_type.clone(),
                    values: values[start..end].to_vec(),
                })
                .collect(),
        };
        if let Some(emit) = stream.as_deref_mut() {
            emit(ExecutionStreamItem::Batch(batch))?;
        } else {
            batches.push(batch);
        }
    }
    let result = QueryResult {
        schema,
        batches,
        bookmark: context.bookmark,
        statistics: StatementStats::default(),
        truncated: false,
    };
    Ok(ExecutionOutput {
        result,
        graph_mutations: Vec::new(),
        temporal_mutations: Vec::new(),
        dependencies,
        administrative: None,
        vector_searches: Vec::new(),
        runtime_replans: 0,
    })
}

fn resident_nullable_output_value(
    column: &ResidentNullableRelationOutputColumn,
    position: usize,
    dense: u32,
    graph: &GraphReadView<'_>,
) -> Result<ResultValue> {
    match column {
        ResidentNullableRelationOutputColumn::Entity { kind, .. } => {
            if dense == crate::execution::RESIDENT_NULLABLE_RELATION_NULL_ROW {
                return Ok(ResultValue::Scalar(ScalarValue::Null));
            }
            match kind {
                ResidentNullableRelationBindingKind::Node => {
                    materialize_node(graph, dense).map(ResultValue::Node)
                }
                ResidentNullableRelationBindingKind::Relationship => {
                    materialize_edge(graph, dense).map(ResultValue::Relationship)
                }
            }
        }
        ResidentNullableRelationOutputColumn::IntegerProperty {
            values, validity, ..
        }
        | ResidentNullableRelationOutputColumn::StringPropertyToInteger {
            values, validity, ..
        } => {
            let value = *values.get(position).ok_or_else(|| {
                corrupt_resident_nullable_output("integer payload omitted a projected row")
            })?;
            match resident_nullable_validity(validity, position)? {
                false if value == 0 => Ok(ResultValue::Scalar(ScalarValue::Null)),
                false => Err(corrupt_resident_nullable_output(
                    "null integer payload is not canonical zero",
                )),
                true => Ok(ResultValue::Scalar(ScalarValue::Integer(value))),
            }
        }
        ResidentNullableRelationOutputColumn::FloatProperty { bits, validity, .. }
        | ResidentNullableRelationOutputColumn::IntegerPropertyToFloat { bits, validity, .. } => {
            let bits = *bits.get(position).ok_or_else(|| {
                corrupt_resident_nullable_output("float payload omitted a projected row")
            })?;
            match resident_nullable_validity(validity, position)? {
                false if bits == 0 => Ok(ResultValue::Scalar(ScalarValue::Null)),
                false => Err(corrupt_resident_nullable_output(
                    "null float payload is not canonical zero",
                )),
                true if f64::from_bits(bits).is_finite() => Ok(ResultValue::Scalar(
                    ScalarValue::Float(OrderedFloat(f64::from_bits(bits))),
                )),
                true => Err(corrupt_resident_nullable_output(
                    "float payload is not finite",
                )),
            }
        }
        ResidentNullableRelationOutputColumn::StringProperty {
            maximum_bytes,
            offsets,
            bytes,
            validity,
            ..
        } => {
            let start = usize::try_from(*offsets.get(position).ok_or_else(|| {
                corrupt_resident_nullable_output("string offsets omitted a projected row")
            })?)
            .map_err(|_| corrupt_resident_nullable_output("string offset exceeds usize"))?;
            let terminal = position.checked_add(1).ok_or_else(|| {
                corrupt_resident_nullable_output("string row position overflowed")
            })?;
            let end = usize::try_from(*offsets.get(terminal).ok_or_else(|| {
                corrupt_resident_nullable_output("string offsets omitted a terminal boundary")
            })?)
            .map_err(|_| corrupt_resident_nullable_output("string offset exceeds usize"))?;
            let width = end.checked_sub(start).ok_or_else(|| {
                corrupt_resident_nullable_output("string offsets are not monotonic")
            })?;
            let maximum_bytes = usize::try_from(*maximum_bytes).map_err(|_| {
                corrupt_resident_nullable_output("declared string width exceeds usize")
            })?;
            if width > maximum_bytes {
                return Err(corrupt_resident_nullable_output(
                    "string payload exceeds its declared width",
                ));
            }
            let valid = resident_nullable_validity(validity, position)?;
            if !valid {
                if start != end {
                    return Err(corrupt_resident_nullable_output(
                        "null string payload owns a non-empty byte range",
                    ));
                }
                return Ok(ResultValue::Scalar(ScalarValue::Null));
            }
            let value = bytes.get(start..end).ok_or_else(|| {
                corrupt_resident_nullable_output("string offsets exceed the payload arena")
            })?;
            let value = std::str::from_utf8(value).map_err(|_| {
                corrupt_resident_nullable_output("string payload is not valid UTF-8")
            })?;
            Ok(ResultValue::Scalar(ScalarValue::String(Arc::from(value))))
        }
        ResidentNullableRelationOutputColumn::IntegerPropertyToString {
            offsets,
            bytes,
            validity,
            ..
        } => {
            let start = usize::try_from(*offsets.get(position).ok_or_else(|| {
                corrupt_resident_nullable_output(
                    "integer-to-string offsets omitted a projected row",
                )
            })?)
            .map_err(|_| {
                corrupt_resident_nullable_output("integer-to-string offset exceeds usize")
            })?;
            let terminal = position.checked_add(1).ok_or_else(|| {
                corrupt_resident_nullable_output("integer-to-string row position overflowed")
            })?;
            let end = usize::try_from(*offsets.get(terminal).ok_or_else(|| {
                corrupt_resident_nullable_output(
                    "integer-to-string offsets omitted a terminal boundary",
                )
            })?)
            .map_err(|_| {
                corrupt_resident_nullable_output("integer-to-string offset exceeds usize")
            })?;
            let width = end.checked_sub(start).ok_or_else(|| {
                corrupt_resident_nullable_output("integer-to-string offsets are not monotonic")
            })?;
            if width
                > usize::try_from(
                    crate::execution::RESIDENT_NULLABLE_RELATION_INTEGER_STRING_MAXIMUM_BYTES,
                )
                .map_err(|_| {
                    corrupt_resident_nullable_output("integer-to-string width bound exceeds usize")
                })?
            {
                return Err(corrupt_resident_nullable_output(
                    "integer-to-string payload exceeds its width bound",
                ));
            }
            let valid = resident_nullable_validity(validity, position)?;
            if !valid {
                if start != end {
                    return Err(corrupt_resident_nullable_output(
                        "null integer-to-string payload owns a non-empty byte range",
                    ));
                }
                return Ok(ResultValue::Scalar(ScalarValue::Null));
            }
            let value = bytes.get(start..end).ok_or_else(|| {
                corrupt_resident_nullable_output(
                    "integer-to-string offsets exceed the payload arena",
                )
            })?;
            let value = std::str::from_utf8(value).map_err(|_| {
                corrupt_resident_nullable_output("integer-to-string payload is not valid UTF-8")
            })?;
            Ok(ResultValue::Scalar(ScalarValue::String(Arc::from(value))))
        }
        ResidentNullableRelationOutputColumn::RelationshipType {
            relationship_types, ..
        } => {
            let relationship_type = *relationship_types.get(position).ok_or_else(|| {
                corrupt_resident_nullable_output(
                    "relationship-type payload omitted a projected row",
                )
            })?;
            if dense == crate::execution::RESIDENT_NULLABLE_RELATION_NULL_ROW {
                if relationship_type.0 != 0 {
                    return Err(corrupt_resident_nullable_output(
                        "null relationship-type payload is not canonical zero",
                    ));
                }
                return Ok(ResultValue::Scalar(ScalarValue::Null));
            }
            let edge = graph.edge_dense(dense).ok_or_else(|| {
                corrupt_resident_nullable_output(
                    "relationship-type source row is absent from the canonical graph",
                )
            })?;
            if edge.relationship_type() != relationship_type {
                return Err(corrupt_resident_nullable_output(
                    "relationship-type payload disagrees with its canonical source edge",
                ));
            }
            let name = graph
                .relationship_type_name(relationship_type)
                .ok_or_else(|| {
                    corrupt_resident_nullable_output(
                        "relationship-type payload names an absent catalog token",
                    )
                })?;
            Ok(ResultValue::Scalar(ScalarValue::String(Arc::from(name))))
        }
        ResidentNullableRelationOutputColumn::EntityLabelPredicate {
            values, validity, ..
        } => {
            let value = *values.get(position).ok_or_else(|| {
                corrupt_resident_nullable_output(
                    "entity-label Boolean payload omitted a projected row",
                )
            })?;
            if value > 1 {
                return Err(corrupt_resident_nullable_output(
                    "entity-label Boolean payload is not canonical",
                ));
            }
            match resident_nullable_validity(validity, position)? {
                false if value == 0 => Ok(ResultValue::Scalar(ScalarValue::Null)),
                false => Err(corrupt_resident_nullable_output(
                    "null entity-label payload is not canonical zero",
                )),
                true => Ok(ResultValue::Scalar(ScalarValue::Boolean(value != 0))),
            }
        }
        ResidentNullableRelationOutputColumn::NullProperty { .. } => {
            Ok(ResultValue::Scalar(ScalarValue::Null))
        }
    }
}

fn resident_nullable_validity(validity: &[u8], position: usize) -> Result<bool> {
    match validity.get(position) {
        Some(0) => Ok(false),
        Some(1) => Ok(true),
        Some(_) => Err(corrupt_resident_nullable_output(
            "scalar validity must be zero or one",
        )),
        None => Err(corrupt_resident_nullable_output(
            "scalar validity omitted a projected row",
        )),
    }
}

fn corrupt_resident_nullable_output(message: &'static str) -> Error {
    Error::new(ErrorCode::CorruptStorage, message)
}

fn record_resident_nullable_source_dependency(
    dense: u32,
    kind: ResidentNullableRelationBindingKind,
    plan: &PhysicalPlan,
    context: &ExecutionContext<'_>,
    dependencies: &mut TransactionDependencies,
) -> Result<()> {
    if dense == crate::execution::RESIDENT_NULLABLE_RELATION_NULL_ROW {
        return Ok(());
    }
    match kind {
        ResidentNullableRelationBindingKind::Node => {
            let node = context.graph.node_dense(dense).ok_or_else(|| {
                Error::new(
                    ErrorCode::CorruptStorage,
                    "resident nullable result selected a missing canonical node",
                )
            })?;
            if !plan.read_layers.contains_layer(node.layer()) {
                return Err(Error::new(
                    ErrorCode::CorruptStorage,
                    "resident nullable result selected a node outside visible layers",
                ));
            }
            dependencies
                .entities
                .insert(EntityDependency::Node(node.id()), node.revision());
        }
        ResidentNullableRelationBindingKind::Relationship => {
            let edge = context.graph.edge_dense(dense).ok_or_else(|| {
                Error::new(
                    ErrorCode::CorruptStorage,
                    "resident nullable result selected a missing canonical relationship",
                )
            })?;
            if !plan.read_layers.contains_layer(edge.layer()) {
                return Err(Error::new(
                    ErrorCode::CorruptStorage,
                    "resident nullable result selected a relationship outside visible layers",
                ));
            }
            dependencies
                .entities
                .insert(EntityDependency::Relationship(edge.id()), edge.revision());
        }
    }
    Ok(())
}

fn execute_resident_row_plan(
    plan: &PhysicalPlan,
    compiled: &CompiledResidentRowPlan,
    backend: &dyn ExecutionBackend,
    context: &ExecutionContext<'_>,
    stream: &mut Option<&mut dyn FnMut(ExecutionStreamItem) -> Result<()>>,
) -> Result<ExecutionOutput> {
    if !resident_catalog_matches_canonical(context) {
        return Err(Error::new(
            ErrorCode::GpuAdmissionFailure,
            "resident typed-row catalog does not match the canonical graph catalog",
        ));
    }

    check_execution(context)?;
    let pinned = backend.pin_project(context.project_id)?;
    if pinned.resident_bookmark(context.project_id) != Some(context.bookmark)
        || pinned.resident_graph_revision(context.project_id) != Some(context.graph.revision())
    {
        return Err(Error::new(
            ErrorCode::GpuAdmissionFailure,
            "resident typed-row backend does not own the requested canonical snapshot",
        ));
    }

    check_execution(context)?;
    let raw = pinned.execute_row_program(&compiled.request, &context.cancellation)?;
    let validated = raw.validate(&compiled.request, pinned.kind())?;
    check_execution(context)?;
    let parts = validated.into_parts();
    let row_count = parts.source_positions.len();
    if row_count > context.max_result_rows {
        return Err(Error::new(
            ErrorCode::ResultBudgetExceeded,
            "resident typed-row result exceeded the query row budget",
        ));
    }

    for output in &compiled.outputs {
        match output.source {
            CompiledResidentRowOutputSource::Node(binding) => {
                if resident_node_rows(&parts.rows, binding)?.len() != row_count {
                    return Err(Error::new(
                        ErrorCode::CorruptStorage,
                        "validated resident typed-row node column is misaligned",
                    ));
                }
            }
            CompiledResidentRowOutputSource::ProjectedRegister { column, value_type } => {
                let projected = parts.projected_columns.get(column).ok_or_else(|| {
                    Error::new(
                        ErrorCode::CorruptStorage,
                        "validated resident typed-row scalar column is absent",
                    )
                })?;
                if projected.column.value_type() != value_type
                    || projected.column.len() != row_count
                {
                    return Err(Error::new(
                        ErrorCode::CorruptStorage,
                        "validated resident typed-row scalar column is misaligned",
                    ));
                }
            }
        }
    }

    let mut dependencies = TransactionDependencies::default();
    for dependency in &plan.dependencies {
        let version = context
            .predicate_versions
            .get(dependency)
            .copied()
            .unwrap_or(context.bookmark.index);
        dependencies.predicates.insert(dependency.clone(), version);
    }

    // Validate the complete private device result against the canonical graph before exposing
    // schema or batches. This prevents a stale/corrupt device row from producing a partial
    // client-visible result.
    let mut rows = Vec::with_capacity(row_count);
    for position in 0..row_count {
        if position.is_multiple_of(4096) {
            check_execution(context)?;
        }
        let mut row = Row::new();
        for output in &compiled.outputs {
            let value = match output.source {
                CompiledResidentRowOutputSource::Node(binding) => {
                    let dense = resident_node_rows(&parts.rows, binding)?[position];
                    if dense == crate::execution::RESIDENT_NULL_ROW {
                        BindingValue::Null
                    } else {
                        let node = context.graph.node_dense(dense).ok_or_else(|| {
                            Error::new(
                                ErrorCode::CorruptStorage,
                                "resident typed-row result selected a missing or deleted canonical node",
                            )
                        })?;
                        if !plan.read_layers.contains_layer(node.layer()) {
                            return Err(Error::new(
                                ErrorCode::CorruptStorage,
                                "resident typed-row result selected a node outside the query's visible layers",
                            ));
                        }
                        dependencies
                            .entities
                            .insert(EntityDependency::Node(node.id()), node.revision());
                        BindingValue::Node(dense)
                    }
                }
                CompiledResidentRowOutputSource::ProjectedRegister {
                    column,
                    value_type: _,
                } => {
                    let projected = &parts.projected_columns[column].column;
                    let valid = projected.validity()[position] != 0;
                    if !valid {
                        BindingValue::Null
                    } else if let ResidentRowColumn::List {
                        offsets,
                        values,
                        element_validity,
                        ..
                    } = projected
                    {
                        let start = offsets[position] as usize;
                        let end = offsets[position + 1] as usize;
                        BindingValue::List(
                            values[start..end]
                                .iter()
                                .zip(&element_validity[start..end])
                                .map(|(value, valid)| {
                                    if *valid == 0 {
                                        BindingValue::Null
                                    } else {
                                        BindingValue::Value(ResultValue::Scalar(
                                            ScalarValue::Integer(*value),
                                        ))
                                    }
                                })
                                .collect(),
                        )
                    } else {
                        let scalar = match projected {
                            ResidentRowColumn::Boolean { values, .. } => {
                                ScalarValue::Boolean(values[position] != 0)
                            }
                            ResidentRowColumn::Integer { values, .. } => {
                                ScalarValue::Integer(values[position])
                            }
                            ResidentRowColumn::Float { bits, .. } => {
                                ScalarValue::Float(OrderedFloat(f64::from_bits(bits[position])))
                            }
                            ResidentRowColumn::String { offsets, bytes, .. } => {
                                let start = offsets[position] as usize;
                                let end = offsets[position + 1] as usize;
                                let value =
                                    std::str::from_utf8(&bytes[start..end]).map_err(|_| {
                                        Error::new(
                                            ErrorCode::CorruptStorage,
                                            "validated resident typed-row string is not UTF-8",
                                        )
                                    })?;
                                ScalarValue::String(Arc::from(value))
                            }
                            ResidentRowColumn::Date { days, .. } => {
                                ScalarValue::Date(days[position])
                            }
                            ResidentRowColumn::LocalTime { nanos, .. } => {
                                ScalarValue::LocalTime(nanos[position])
                            }
                            ResidentRowColumn::ZonedTime {
                                nanos,
                                offset_seconds,
                                ..
                            } => ScalarValue::ZonedTime {
                                nanos: nanos[position],
                                offset_seconds: offset_seconds[position],
                            },
                            ResidentRowColumn::LocalDateTime { seconds, nanos, .. } => {
                                ScalarValue::LocalDateTime {
                                    seconds: seconds[position],
                                    nanos: nanos[position],
                                }
                            }
                            ResidentRowColumn::ZonedDateTime {
                                seconds,
                                nanos,
                                timezone_offsets,
                                timezone_bytes,
                                ..
                            } => {
                                let start = timezone_offsets[position] as usize;
                                let end = timezone_offsets[position + 1] as usize;
                                let timezone = std::str::from_utf8(&timezone_bytes[start..end])
                                    .map_err(|_| {
                                        Error::new(
                                            ErrorCode::CorruptStorage,
                                            "validated resident typed-row timezone is not UTF-8",
                                        )
                                    })?;
                                ScalarValue::ZonedDateTime {
                                    seconds: seconds[position],
                                    nanos: nanos[position],
                                    timezone: Arc::from(timezone),
                                }
                            }
                            ResidentRowColumn::List { .. } => {
                                unreachable!("resident list projection bypassed list publication")
                            }
                        };
                        BindingValue::Value(ResultValue::Scalar(scalar))
                    }
                }
            };
            row.insert(output.name.clone(), value);
        }
        rows.push(row);
    }

    let output_names = compiled
        .outputs
        .iter()
        .map(|output| output.name.clone())
        .collect::<Vec<_>>();
    let graph = GraphReadView::new(context.graph);
    let result = rows_to_result(
        &rows,
        &output_names,
        &graph,
        context.bookmark,
        StatementStats::default(),
        context.max_batch_rows,
        stream.take(),
    )?;
    Ok(ExecutionOutput {
        result,
        graph_mutations: Vec::new(),
        temporal_mutations: Vec::new(),
        dependencies,
        administrative: None,
        vector_searches: Vec::new(),
        runtime_replans: 0,
    })
}

fn execute_resident_value_matrix_plan(
    plan: &PhysicalPlan,
    compiled: &CompiledResidentValueMatrixPlan,
    backend: &dyn ExecutionBackend,
    context: &ExecutionContext<'_>,
    stream: &mut Option<&mut dyn FnMut(ExecutionStreamItem) -> Result<()>>,
) -> Result<ExecutionOutput> {
    check_execution(context)?;
    let resident = backend.execute_node_pipeline(&compiled.request, &context.cancellation)?;
    let row_count = resident.start_rows.len();
    if row_count > context.max_result_rows
        || compiled.request.expansion_steps().count() != 1
        || resident.end_rows.len() != row_count
        || resident.edge_rows.len() != row_count
        || !resident.intermediate_node_rows.is_empty()
        || !resident.intermediate_edge_rows.is_empty()
        || resident.value_left_indices.len() != row_count
        || resident.value_right_indices.len() != row_count
        || !resident.integer_columns.is_empty()
        || !resident.boolean_columns.is_empty()
        || resident
            .value_left_indices
            .iter()
            .chain(&resident.value_right_indices)
            .any(|index| *index as usize >= compiled.values.len())
    {
        return Err(Error::new(
            ErrorCode::CorruptStorage,
            "resident value matrix returned inconsistent row columns",
        ));
    }
    let graph = GraphReadView::new(context.graph);
    let materialize =
        |source: &ResidentValueMatrixOutput, position: usize| -> Result<ResultValue> {
            match source {
                ResidentValueMatrixOutput::Node(binding) => {
                    let dense = *resident_node_rows(&resident, *binding)?
                        .get(position)
                        .ok_or_else(|| Error::internal("resident matrix node row disappeared"))?;
                    materialize_node(&graph, dense).map(ResultValue::Node)
                }
                ResidentValueMatrixOutput::Relationship => {
                    let dense = *resident.edge_rows.get(position).ok_or_else(|| {
                        Error::internal("resident matrix relationship row disappeared")
                    })?;
                    materialize_edge(&graph, dense).map(ResultValue::Relationship)
                }
                ResidentValueMatrixOutput::Path => Ok(ResultValue::Path {
                    nodes: vec![
                        materialize_node(
                            &graph,
                            *resident.start_rows.get(position).ok_or_else(|| {
                                Error::internal("resident matrix path start row disappeared")
                            })?,
                        )?,
                        materialize_node(
                            &graph,
                            *resident.end_rows.get(position).ok_or_else(|| {
                                Error::internal("resident matrix path end row disappeared")
                            })?,
                        )?,
                    ],
                    relationships: vec![materialize_edge(
                        &graph,
                        *resident.edge_rows.get(position).ok_or_else(|| {
                            Error::internal("resident matrix path relationship row disappeared")
                        })?,
                    )?],
                }),
                ResidentValueMatrixOutput::Literal(value) => Ok(value.clone()),
            }
        };
    let left_values = resident
        .value_left_indices
        .iter()
        .enumerate()
        .map(|(position, index)| {
            materialize(
                compiled
                    .values
                    .get(*index as usize)
                    .ok_or_else(|| Error::internal("resident matrix left value disappeared"))?,
                position,
            )
        })
        .collect::<Result<Vec<_>>>()?;
    let right_values = resident
        .value_right_indices
        .iter()
        .enumerate()
        .map(|(position, index)| {
            materialize(
                compiled
                    .values
                    .get(*index as usize)
                    .ok_or_else(|| Error::internal("resident matrix right value disappeared"))?,
                position,
            )
        })
        .collect::<Result<Vec<_>>>()?;
    let columns = vec![
        ResultColumn {
            name: compiled.left_name.clone(),
            value_type: result_values_type(&left_values),
            values: left_values,
        },
        ResultColumn {
            name: compiled.right_name.clone(),
            value_type: result_values_type(&right_values),
            values: right_values,
        },
    ];
    let schema = columns
        .iter()
        .map(|column| (column.name.clone(), column.value_type.clone()))
        .collect::<Vec<_>>();
    if let Some(emit) = stream.as_deref_mut() {
        emit(ExecutionStreamItem::Schema(schema.clone()))?;
    }
    let mut batches = Vec::new();
    let batch_rows = context.max_batch_rows.max(1);
    for start in (0..row_count).step_by(batch_rows) {
        check_execution(context)?;
        let end = start.saturating_add(batch_rows).min(row_count);
        let batch = ResultBatch {
            row_count: end - start,
            columns: columns
                .iter()
                .map(|column| ResultColumn {
                    name: column.name.clone(),
                    value_type: column.value_type.clone(),
                    values: column.values[start..end].to_vec(),
                })
                .collect(),
        };
        if let Some(emit) = stream.as_deref_mut() {
            emit(ExecutionStreamItem::Batch(batch))?;
        } else {
            batches.push(batch);
        }
    }
    let mut dependencies = TransactionDependencies::default();
    for dependency in &plan.dependencies {
        dependencies.predicates.insert(
            dependency.clone(),
            context
                .predicate_versions
                .get(dependency)
                .copied()
                .unwrap_or(context.bookmark.index),
        );
    }
    let mut nodes = BTreeSet::new();
    for dense in resident.start_rows.iter().chain(&resident.end_rows) {
        if !nodes.insert(*dense) {
            continue;
        }
        let node = context.graph.node_dense(*dense).ok_or_else(|| {
            Error::new(
                ErrorCode::CorruptStorage,
                "resident value matrix selected a deleted node",
            )
        })?;
        dependencies
            .entities
            .insert(EntityDependency::Node(node.id()), node.revision());
    }
    let mut edges = BTreeSet::new();
    for dense in &resident.edge_rows {
        if !edges.insert(*dense) {
            continue;
        }
        let edge = context.graph.edge_dense(*dense).ok_or_else(|| {
            Error::new(
                ErrorCode::CorruptStorage,
                "resident value matrix selected a deleted relationship",
            )
        })?;
        dependencies
            .entities
            .insert(EntityDependency::Relationship(edge.id()), edge.revision());
    }
    Ok(ExecutionOutput {
        result: QueryResult {
            schema,
            batches,
            bookmark: context.bookmark,
            statistics: StatementStats::default(),
            truncated: false,
        },
        graph_mutations: Vec::new(),
        temporal_mutations: Vec::new(),
        dependencies,
        administrative: None,
        vector_searches: Vec::new(),
        runtime_replans: 0,
    })
}

fn execute_resident_literal_sort_plan(
    plan: &PhysicalPlan,
    compiled: &CompiledResidentLiteralSortPlan,
    backend: &dyn ExecutionBackend,
    context: &ExecutionContext<'_>,
    stream: &mut Option<&mut dyn FnMut(ExecutionStreamItem) -> Result<()>>,
) -> Result<ExecutionOutput> {
    check_execution(context)?;
    let expected_rows = compiled.device_limit.unwrap_or(compiled.rows.len());
    let sorted = backend.sort_rows(
        &ResidentSortRequest {
            project: context.project_id,
            row_count: compiled.rows.len(),
            keys: compiled.keys.clone(),
            limit: compiled.device_limit,
        },
        &context.cancellation,
    )?;
    if sorted.positions.len() != expected_rows {
        return Err(Error::new(
            ErrorCode::CorruptStorage,
            "native literal sort returned the wrong row count",
        ));
    }
    let mut seen = vec![false; compiled.rows.len()];
    let mut ordered = Vec::with_capacity(sorted.positions.len());
    for position in sorted.positions {
        let position = position as usize;
        let Some(source) = compiled.rows.get(position) else {
            return Err(Error::new(
                ErrorCode::CorruptStorage,
                "native literal sort returned an out-of-range row position",
            ));
        };
        if std::mem::replace(
            seen.get_mut(position).ok_or_else(|| {
                Error::new(
                    ErrorCode::CorruptStorage,
                    "native literal sort returned an unaddressable row position",
                )
            })?,
            true,
        ) {
            return Err(Error::new(
                ErrorCode::CorruptStorage,
                "native literal sort returned a duplicate row position",
            ));
        }
        ordered.push(source);
    }
    let mut rows = Vec::new();
    let take = compiled.output_limit.unwrap_or(usize::MAX);
    for source in ordered.into_iter().skip(compiled.offset).take(take) {
        if rows.len() >= context.max_result_rows {
            return Err(Error::new(
                ErrorCode::ResultBudgetExceeded,
                "native literal sort exceeded the result row budget",
            ));
        }
        let mut row = Row::new();
        for name in &compiled.output_names {
            let value = source.get(name).cloned().ok_or_else(|| {
                Error::new(
                    ErrorCode::CorruptStorage,
                    "native literal sort final projection omitted a column",
                )
            })?;
            row.insert(name.clone(), BindingValue::Value(value));
        }
        rows.push(row);
    }
    let graph = GraphReadView::new(context.graph);
    let result = rows_to_result(
        &rows,
        &compiled.output_names,
        &graph,
        context.bookmark,
        StatementStats::default(),
        context.max_batch_rows,
        stream.take(),
    )?;
    let mut dependencies = TransactionDependencies::default();
    for dependency in &plan.dependencies {
        let version = context
            .predicate_versions
            .get(dependency)
            .copied()
            .unwrap_or(context.bookmark.index);
        dependencies.predicates.insert(dependency.clone(), version);
    }
    Ok(ExecutionOutput {
        result,
        graph_mutations: Vec::new(),
        temporal_mutations: Vec::new(),
        dependencies,
        administrative: None,
        vector_searches: Vec::new(),
        runtime_replans: 0,
    })
}

fn execute_resident_range_plan(
    plan: &PhysicalPlan,
    compiled: &CompiledResidentRangePlan,
    backend: &dyn ExecutionBackend,
    context: &ExecutionContext<'_>,
    stream: &mut Option<&mut dyn FnMut(ExecutionStreamItem) -> Result<()>>,
) -> Result<ExecutionOutput> {
    check_execution(context)?;
    let output = backend.execute_range_program(&compiled.request, &context.cancellation)?;
    if output.values.len() > context.max_result_rows {
        return Err(Error::new(
            ErrorCode::ResultBudgetExceeded,
            "resident range program exceeded the result row budget",
        ));
    }
    let values = output
        .values
        .into_iter()
        .map(|value| ResultValue::Scalar(ScalarValue::Integer(value)))
        .collect();
    let mut row = Row::new();
    row.insert(
        compiled.output_name.clone(),
        BindingValue::Value(ResultValue::List(values)),
    );
    let graph = GraphReadView::new(context.graph);
    let columns = vec![compiled.output_name.clone()];
    let result = rows_to_result(
        &[row],
        &columns,
        &graph,
        context.bookmark,
        StatementStats::default(),
        context.max_batch_rows,
        stream.take(),
    )?;
    let mut dependencies = TransactionDependencies::default();
    for dependency in &plan.dependencies {
        let version = context
            .predicate_versions
            .get(dependency)
            .copied()
            .unwrap_or(context.bookmark.index);
        dependencies.predicates.insert(dependency.clone(), version);
    }
    Ok(ExecutionOutput {
        result,
        graph_mutations: Vec::new(),
        temporal_mutations: Vec::new(),
        dependencies,
        administrative: None,
        vector_searches: Vec::new(),
        runtime_replans: 0,
    })
}

/// Publish one relation-aware temporal arithmetic command only after the pinned backend has
/// completed every scan, property load, arithmetic instruction, and final boundary obligation.
/// The host converts already-validated typed cells to the public result representation; it never
/// evaluates or repairs an expression from the source query.
fn execute_resident_temporal_arithmetic_plan(
    plan: &PhysicalPlan,
    compiled: &CompiledResidentTemporalArithmeticPlan,
    backend: &dyn ExecutionBackend,
    context: &ExecutionContext<'_>,
    stream: &mut Option<&mut dyn FnMut(ExecutionStreamItem) -> Result<()>>,
) -> Result<ExecutionOutput> {
    if !resident_catalog_matches_canonical(context) {
        return Err(Error::new(
            ErrorCode::GpuAdmissionFailure,
            "resident temporal arithmetic catalog does not match the canonical graph catalog",
        ));
    }
    check_execution(context)?;
    let pinned = backend.pin_project(context.project_id)?;
    if !pinned.supports_native_temporal_arithmetic_program()
        || pinned.resident_bookmark(context.project_id) != Some(context.bookmark)
        || pinned.resident_graph_revision(context.project_id) != Some(context.graph.revision())
    {
        return Err(Error::new(
            ErrorCode::GpuAdmissionFailure,
            "pinned backend does not own the requested temporal arithmetic generation",
        ));
    }
    check_execution(context)?;
    let raw =
        pinned.execute_temporal_arithmetic_program(&compiled.request, &context.cancellation)?;
    let validated = raw.validate_for_publication(&compiled.request, pinned.kind())?;
    check_execution(context)?;

    match validated.status() {
        ResidentTemporalArithmeticStatus::Success => {}
        ResidentTemporalArithmeticStatus::QueryType { obligation } => {
            return Err(Error::new(
                ErrorCode::QueryType,
                format!(
                    "native temporal arithmetic type failure at obligation {}",
                    obligation.id
                ),
            ));
        }
        ResidentTemporalArithmeticStatus::TemporalRange { obligation } => {
            return Err(Error::new(
                ErrorCode::TemporalRange,
                format!(
                    "native temporal arithmetic range failure at obligation {}",
                    obligation.id
                ),
            ));
        }
    }
    if validated.relation_rows() > context.max_result_rows {
        return Err(Error::new(
            ErrorCode::CorruptStorage,
            "validated temporal arithmetic result exceeded the query row budget",
        ));
    }
    let mut rows = Vec::with_capacity(validated.relation_rows());
    for row_index in 0..validated.relation_rows() {
        let mut row = Row::new();
        for (name, column) in compiled.output_names.iter().zip(validated.columns()) {
            let value = column.values.get(row_index).ok_or_else(|| {
                Error::new(
                    ErrorCode::CorruptStorage,
                    "validated temporal arithmetic column omitted a result cell",
                )
            })?;
            row.insert(
                name.clone(),
                untrusted_result_binding(resident_temporal_arithmetic_result_value(value)?),
            );
        }
        rows.push(row);
    }

    let graph = GraphReadView::new(context.graph);
    let result = rows_to_result(
        &rows,
        &compiled.output_names,
        &graph,
        context.bookmark,
        StatementStats::default(),
        context.max_batch_rows,
        stream.take(),
    )?;
    let mut dependencies = TransactionDependencies::default();
    for dependency in &plan.dependencies {
        dependencies.predicates.insert(
            dependency.clone(),
            context
                .predicate_versions
                .get(dependency)
                .copied()
                .unwrap_or(context.bookmark.index),
        );
    }
    Ok(ExecutionOutput {
        result,
        graph_mutations: Vec::new(),
        temporal_mutations: Vec::new(),
        dependencies,
        administrative: None,
        vector_searches: Vec::new(),
        runtime_replans: 0,
    })
}

fn resident_temporal_arithmetic_result_value(value: &ResidentTemporalValue) -> Result<ResultValue> {
    let scalar = match value {
        ResidentTemporalValue::Null => ScalarValue::Null,
        ResidentTemporalValue::Date(days) => ScalarValue::Date(*days),
        ResidentTemporalValue::LocalTime(nanos) => ScalarValue::LocalTime(*nanos),
        ResidentTemporalValue::ZonedTime {
            nanos,
            offset_seconds,
        } => ScalarValue::ZonedTime {
            nanos: *nanos,
            offset_seconds: *offset_seconds,
        },
        ResidentTemporalValue::LocalDateTime { seconds, nanos } => ScalarValue::LocalDateTime {
            seconds: *seconds,
            nanos: *nanos,
        },
        ResidentTemporalValue::ZonedDateTimeFixedOffset {
            seconds,
            nanos,
            offset_seconds,
        } => ScalarValue::ZonedDateTime {
            seconds: *seconds,
            nanos: *nanos,
            timezone: resident_fixed_offset_timezone(*offset_seconds)?,
        },
        ResidentTemporalValue::ZonedDateTimeNamed {
            seconds,
            nanos,
            timezone,
        } => ScalarValue::ZonedDateTime {
            seconds: *seconds,
            nanos: *nanos,
            timezone: Arc::from(timezone.as_str()),
        },
        ResidentTemporalValue::Duration {
            months,
            days,
            seconds,
            nanos,
        } => ScalarValue::Duration {
            months: *months,
            days: *days,
            seconds: *seconds,
            nanos: *nanos,
        },
        ResidentTemporalValue::Integer(value) => ScalarValue::Integer(*value),
        ResidentTemporalValue::Boolean(_)
        | ResidentTemporalValue::String(_)
        | ResidentTemporalValue::InvalidArgument => {
            return Err(Error::new(
                ErrorCode::CorruptStorage,
                "validated temporal arithmetic result contains a non-arithmetic value",
            ));
        }
    };
    Ok(ResultValue::Scalar(scalar))
}

fn execute_resident_temporal_value_plan(
    plan: &PhysicalPlan,
    compiled: &CompiledResidentTemporalValuePlan,
    backend: &dyn ExecutionBackend,
    context: &ExecutionContext<'_>,
    stream: &mut Option<&mut dyn FnMut(ExecutionStreamItem) -> Result<()>>,
) -> Result<ExecutionOutput> {
    check_execution(context)?;
    if context.max_result_rows == 0 {
        return Err(Error::new(
            ErrorCode::ResultBudgetExceeded,
            "resident temporal value program exceeds the query row budget",
        ));
    }
    let output =
        backend.execute_temporal_value_program(&compiled.request, &context.cancellation)?;
    let output_registers = compiled.request.effective_output_registers();
    let output_kinds = compiled.request.output_kinds()?;
    if output.values.len() != compiled.output_names.len()
        || output_registers.len() != compiled.output_names.len()
        || output_kinds.len() != compiled.output_names.len()
    {
        return Err(Error::new(
            ErrorCode::CorruptStorage,
            "resident temporal value program returned the wrong result column count",
        ));
    }
    let mut row = Row::new();
    for (index, (name, value)) in compiled.output_names.iter().zip(output.values).enumerate() {
        let output_register = output_registers[index];
        if !output_kinds[index].matches_value(&value) {
            return Err(Error::new(
                ErrorCode::CorruptStorage,
                "resident temporal value program returned a forged output register kind or capacity",
            ));
        }
        let value = match value {
            ResidentTemporalValue::Null => ResultValue::Scalar(ScalarValue::Null),
            ResidentTemporalValue::String(value) => {
                ResultValue::Scalar(ScalarValue::String(Arc::from(value)))
            }
            ResidentTemporalValue::Date(days) => {
                ResultValue::Scalar(ScalarValue::Date(i64::from(days)))
            }
            ResidentTemporalValue::LocalTime(nanos) => {
                ResultValue::Scalar(ScalarValue::LocalTime(nanos))
            }
            ResidentTemporalValue::ZonedTime {
                nanos,
                offset_seconds,
            } => ResultValue::Scalar(ScalarValue::ZonedTime {
                nanos,
                offset_seconds,
            }),
            ResidentTemporalValue::LocalDateTime { seconds, nanos } => {
                ResultValue::Scalar(ScalarValue::LocalDateTime { seconds, nanos })
            }
            ResidentTemporalValue::ZonedDateTimeFixedOffset {
                seconds,
                nanos,
                offset_seconds,
            } => ResultValue::Scalar(ScalarValue::ZonedDateTime {
                seconds,
                nanos,
                timezone: resident_fixed_offset_timezone(offset_seconds)?,
            }),
            ResidentTemporalValue::ZonedDateTimeNamed {
                seconds,
                nanos,
                timezone,
            } => ResultValue::Scalar(ScalarValue::ZonedDateTime {
                seconds,
                nanos,
                timezone: Arc::from(timezone),
            }),
            ResidentTemporalValue::Duration {
                months,
                days,
                seconds,
                nanos,
            } => ResultValue::Scalar(ScalarValue::Duration {
                months,
                days,
                seconds,
                nanos,
            }),
            ResidentTemporalValue::Integer(value) => {
                ResultValue::Scalar(ScalarValue::Integer(value))
            }
            ResidentTemporalValue::Boolean(value) => {
                ResultValue::Scalar(ScalarValue::Boolean(value))
            }
            ResidentTemporalValue::InvalidArgument => {
                let message = match compiled.request.invocations[usize::from(output_register)]
                    .function
                {
                    ResidentTemporalValueFunction::Date => {
                        "InvalidArgumentValue: date requires an ISO calendar date string"
                    }
                    ResidentTemporalValueFunction::LocalTime => {
                        "InvalidArgumentValue: localtime requires an ISO local time string"
                    }
                    ResidentTemporalValueFunction::Time => {
                        "InvalidArgumentValue: time requires an ISO time with offset"
                    }
                    ResidentTemporalValueFunction::LocalDateTime => {
                        "InvalidArgumentValue: localdatetime requires an ISO local date-time"
                    }
                    ResidentTemporalValueFunction::DateTime => {
                        "InvalidArgumentValue: datetime requires an ISO-8601 value with an offset"
                    }
                    ResidentTemporalValueFunction::Duration => {
                        "InvalidArgumentValue: duration requires ISO-8601 P notation"
                    }
                };
                return Err(Error::new(ErrorCode::QueryType, message));
            }
        };
        row.insert(name.clone(), BindingValue::Value(value));
    }
    let graph = GraphReadView::new(context.graph);
    let result = rows_to_result(
        &[row],
        &compiled.output_names,
        &graph,
        context.bookmark,
        StatementStats::default(),
        context.max_batch_rows,
        stream.take(),
    )?;
    let mut dependencies = TransactionDependencies::default();
    for dependency in &plan.dependencies {
        let version = context
            .predicate_versions
            .get(dependency)
            .copied()
            .unwrap_or(context.bookmark.index);
        dependencies.predicates.insert(dependency.clone(), version);
    }
    Ok(ExecutionOutput {
        result,
        graph_mutations: Vec::new(),
        temporal_mutations: Vec::new(),
        dependencies,
        administrative: None,
        vector_searches: Vec::new(),
        runtime_replans: 0,
    })
}

/// A fixed-offset zone label is the public representation of a device-produced numeric offset.
/// The backend has already parsed the raw string and computed the instant; this boundary only
/// gives the canonical scalar its required stable zone label.
fn resident_fixed_offset_timezone(offset_seconds: i32) -> Result<Arc<str>> {
    if offset_seconds == 0 {
        return Ok(Arc::from("UTC"));
    }
    let absolute = offset_seconds.unsigned_abs();
    if absolute >= 86_400 {
        return Err(Error::new(
            ErrorCode::CorruptStorage,
            "resident temporal value program returned an invalid UTC offset",
        ));
    }
    let hour = absolute / 3_600;
    let minute = (absolute % 3_600) / 60;
    let second = absolute % 60;
    let sign = if offset_seconds < 0 { '-' } else { '+' };
    let timezone = if second == 0 {
        format!("{sign}{hour:02}:{minute:02}")
    } else {
        format!("{sign}{hour:02}:{minute:02}:{second:02}")
    };
    Ok(Arc::from(timezone))
}

fn execute_resident_scalar_value_plan(
    plan: &PhysicalPlan,
    compiled: &CompiledResidentScalarValuePlan,
    backend: &dyn ExecutionBackend,
    context: &ExecutionContext<'_>,
    stream: &mut Option<&mut dyn FnMut(ExecutionStreamItem) -> Result<()>>,
) -> Result<ExecutionOutput> {
    check_execution(context)?;
    if context.max_result_rows == 0 {
        return Err(Error::new(
            ErrorCode::ResultBudgetExceeded,
            "resident scalar program exceeds the query row budget",
        ));
    }
    let output = backend.execute_scalar_program(&compiled.request, &context.cancellation)?;
    let values = decode_resident_scalar_program(compiled, &output)?;
    let mut row = Row::new();
    for (name, value) in compiled.output_names.iter().zip(values) {
        row.insert(name.clone(), BindingValue::Value(value));
    }
    let graph = GraphReadView::new(context.graph);
    let result = rows_to_result(
        &[row],
        &compiled.output_names,
        &graph,
        context.bookmark,
        StatementStats::default(),
        context.max_batch_rows,
        stream.take(),
    )?;
    let mut dependencies = TransactionDependencies::default();
    for dependency in &plan.dependencies {
        let version = context
            .predicate_versions
            .get(dependency)
            .copied()
            .unwrap_or(context.bookmark.index);
        dependencies.predicates.insert(dependency.clone(), version);
    }
    Ok(ExecutionOutput {
        result,
        graph_mutations: Vec::new(),
        temporal_mutations: Vec::new(),
        dependencies,
        administrative: None,
        vector_searches: Vec::new(),
        runtime_replans: 0,
    })
}

/// Executes one immutable procedure relation through the selected backend's typed row-selection
/// ABI. The host decodes output columns only after the backend row IDs, immutable fingerprints,
/// execution identity, cardinalities, provenance, and completion receipt have all validated.
fn execute_resident_procedure_table_plan(
    plan: &PhysicalPlan,
    compiled: &CompiledResidentProcedureTablePlan,
    backend: &dyn ExecutionBackend,
    context: &ExecutionContext<'_>,
    stream: &mut Option<&mut dyn FnMut(ExecutionStreamItem) -> Result<()>>,
) -> Result<ExecutionOutput> {
    check_execution(context)?;
    let pinned = backend.pin_project(context.project_id)?;
    if !pinned.supports_native_procedure_table() {
        return Err(Error::new(
            ErrorCode::GpuAdmissionFailure,
            "pinned backend lacks native typed procedure-table selection",
        ));
    }
    const PROCEDURE_OBLIGATION_ID: u64 = 0x5052_4f43_0000_0001;
    let request = ResidentProcedureTableRequest::new(
        compiled.table.clone(),
        compiled.arguments.clone(),
        fresh_resident_execution_id(),
        ResidentExecutionObligation {
            id: PROCEDURE_OBLIGATION_ID,
            kind: ResidentObligationKind::Procedure,
            scope: ResidentObligationScope::ProcedureTable,
        },
        context
            .max_result_rows
            .min(compiled.table.row_count() as usize),
    )?;
    check_execution(context)?;
    let selected = pinned
        .execute_procedure_table(&request, &context.cancellation)?
        .validate_for_publication(&request, pinned.kind())?;
    let selected_cardinality = selected.output_cardinality();
    let selected = selected.into_selected_source_rows();
    check_execution(context)?;
    let relation = compiled.table.materialize_output_rows(&selected)?;
    let mut rows = Vec::with_capacity(relation.len());
    for values in relation {
        check_execution(context)?;
        let mut row = Row::new();
        if let Some(name) = &compiled.selected_cardinality_output {
            row.insert(
                name.clone(),
                BindingValue::Value(ResultValue::Scalar(ScalarValue::Integer(
                    i64::try_from(selected_cardinality).map_err(|_| {
                        Error::new(
                            ErrorCode::ResultBudgetExceeded,
                            "resident procedure-table cardinality exceeds signed integer output",
                        )
                    })?,
                ))),
            );
        }
        for output in &compiled.outputs {
            let value = values.get(output.output_ordinal).cloned().ok_or_else(|| {
                Error::new(
                    ErrorCode::CorruptStorage,
                    "resident procedure table omitted one projected output column",
                )
            })?;
            row.insert(output.name.clone(), BindingValue::Value(value));
        }
        rows.push(row);
    }
    let output_names = compiled
        .selected_cardinality_output
        .iter()
        .cloned()
        .chain(compiled.outputs.iter().map(|output| output.name.clone()))
        .collect::<Vec<_>>();
    let graph = GraphReadView::new(context.graph);
    let result = rows_to_result(
        &rows,
        &output_names,
        &graph,
        context.bookmark,
        StatementStats::default(),
        context.max_batch_rows,
        stream.take(),
    )?;
    let mut dependencies = TransactionDependencies::default();
    for dependency in &plan.dependencies {
        let version = context
            .predicate_versions
            .get(dependency)
            .copied()
            .unwrap_or(context.bookmark.index);
        dependencies.predicates.insert(dependency.clone(), version);
    }
    Ok(ExecutionOutput {
        result,
        graph_mutations: Vec::new(),
        temporal_mutations: Vec::new(),
        dependencies,
        administrative: None,
        vector_searches: Vec::new(),
        runtime_replans: 0,
    })
}

fn execute_resident_to_boolean_plan(
    plan: &PhysicalPlan,
    compiled: &CompiledResidentToBooleanPlan,
    backend: &dyn ExecutionBackend,
    context: &ExecutionContext<'_>,
    stream: &mut Option<&mut dyn FnMut(ExecutionStreamItem) -> Result<()>>,
) -> Result<ExecutionOutput> {
    check_execution(context)?;
    let output = backend.execute_to_boolean(
        &ResidentToBooleanRequest {
            inputs: compiled.inputs.clone(),
        },
        &context.cancellation,
    )?;
    if output.values.len() != compiled.inputs.len() {
        return Err(Error::new(
            ErrorCode::CorruptStorage,
            "resident toBoolean pipeline returned the wrong row count",
        ));
    }
    let mut rows = Vec::with_capacity(output.values.len());
    for value in output.values {
        let value = match value {
            ResidentBooleanValue::Null => ResultValue::Scalar(ScalarValue::Null),
            ResidentBooleanValue::Boolean(value) => {
                ResultValue::Scalar(ScalarValue::Boolean(value))
            }
            ResidentBooleanValue::InvalidArgument => {
                return Err(Error::new(
                    ErrorCode::QueryType,
                    "InvalidArgumentValue: toBoolean requires a BOOLEAN or STRING",
                ));
            }
        };
        let mut row = Row::new();
        row.insert(compiled.output_name.clone(), BindingValue::Value(value));
        rows.push(row);
    }
    let graph = GraphReadView::new(context.graph);
    let columns = vec![compiled.output_name.clone()];
    let result = rows_to_result(
        &rows,
        &columns,
        &graph,
        context.bookmark,
        StatementStats::default(),
        context.max_batch_rows,
        stream.take(),
    )?;
    let mut dependencies = TransactionDependencies::default();
    for dependency in &plan.dependencies {
        let version = context
            .predicate_versions
            .get(dependency)
            .copied()
            .unwrap_or(context.bookmark.index);
        dependencies.predicates.insert(dependency.clone(), version);
    }
    Ok(ExecutionOutput {
        result,
        graph_mutations: Vec::new(),
        temporal_mutations: Vec::new(),
        dependencies,
        administrative: None,
        vector_searches: Vec::new(),
        runtime_replans: 0,
    })
}

fn execute_resident_boolean_plan(
    plan: &PhysicalPlan,
    compiled: &CompiledResidentBooleanPlan,
    backend: &dyn ExecutionBackend,
    context: &ExecutionContext<'_>,
    stream: &mut Option<&mut dyn FnMut(ExecutionStreamItem) -> Result<()>>,
) -> Result<ExecutionOutput> {
    check_execution(context)?;
    let output = backend.execute_boolean_program(&compiled.request, &context.cancellation)?;
    if output.rows.len() > context.max_result_rows {
        return Err(Error::new(
            ErrorCode::ResultBudgetExceeded,
            "resident Boolean program exceeded the result row budget",
        ));
    }
    if output
        .rows
        .iter()
        .any(|row| row.len() != compiled.output_names.len())
    {
        return Err(Error::new(
            ErrorCode::CorruptStorage,
            "resident Boolean program returned an invalid final row shape",
        ));
    }
    let mut rows = Vec::with_capacity(output.rows.len());
    for values in output.rows {
        let mut row = Row::new();
        for (name, value) in compiled.output_names.iter().zip(values) {
            let value = match value {
                ResidentBooleanValue::Null => ResultValue::Scalar(ScalarValue::Null),
                ResidentBooleanValue::Boolean(value) => {
                    ResultValue::Scalar(ScalarValue::Boolean(value))
                }
                ResidentBooleanValue::InvalidArgument => {
                    return Err(Error::new(
                        ErrorCode::QueryType,
                        "InvalidArgumentValue: native scalar expression received incompatible values",
                    ));
                }
            };
            row.insert(name.clone(), BindingValue::Value(value));
        }
        rows.push(row);
    }
    let graph = GraphReadView::new(context.graph);
    let result = rows_to_result(
        &rows,
        &compiled.output_names,
        &graph,
        context.bookmark,
        StatementStats::default(),
        context.max_batch_rows,
        stream.take(),
    )?;
    let mut dependencies = TransactionDependencies::default();
    for dependency in &plan.dependencies {
        let version = context
            .predicate_versions
            .get(dependency)
            .copied()
            .unwrap_or(context.bookmark.index);
        dependencies.predicates.insert(dependency.clone(), version);
    }
    Ok(ExecutionOutput {
        result,
        graph_mutations: Vec::new(),
        temporal_mutations: Vec::new(),
        dependencies,
        administrative: None,
        vector_searches: Vec::new(),
        runtime_replans: 0,
    })
}

fn execute_resident_quantifier_plan(
    plan: &PhysicalPlan,
    compiled: &CompiledResidentQuantifierPlan,
    backend: &dyn ExecutionBackend,
    context: &ExecutionContext<'_>,
    stream: &mut Option<&mut dyn FnMut(ExecutionStreamItem) -> Result<()>>,
) -> Result<ExecutionOutput> {
    check_execution(context)?;
    let pinned = backend.pin_project(context.project_id)?;
    let has_entity_source = matches!(
        &compiled.request.source,
        ResidentQuantifierSource::VariablePathEntityList { .. }
    );
    if pinned.resident_bookmark(context.project_id) != Some(context.bookmark)
        || pinned.resident_graph_revision(context.project_id) != Some(context.graph.revision())
        || !pinned.supports_native_quantifier_program()
        || (has_entity_source && !pinned.supports_native_quantifier_entity_source())
    {
        return Err(Error::new(
            ErrorCode::GpuAdmissionFailure,
            "pinned backend does not own the requested native quantifier command, entity source, and snapshot",
        ));
    }
    let raw = pinned.execute_quantifier_program(&compiled.request, &context.cancellation)?;
    let validated = raw.validate(&compiled.request, pinned.kind())?;
    check_execution(context)?;
    let (parts, entity_parts) = validated.into_entity_parts();
    if parts.rows.len() > context.max_result_rows {
        return Err(Error::new(
            ErrorCode::CorruptStorage,
            "validated resident quantifier result exceeded the query row budget",
        ));
    }
    let output_names = compiled
        .request
        .program
        .outputs
        .iter()
        .map(|output| output.name.clone())
        .collect::<Vec<_>>();
    let (entity_outputs, read_dependencies) = entity_parts.map_or_else(
        || (BTreeMap::new(), Vec::new()),
        |parts| {
            (
                parts
                    .outputs
                    .into_iter()
                    .map(|output| ((output.row, output.column), output.value))
                    .collect::<BTreeMap<_, _>>(),
                parts.read_dependencies,
            )
        },
    );
    let mut entity_outputs = entity_outputs;
    let mut rows = Vec::with_capacity(parts.rows.len());
    for (row_index, values) in parts.rows.into_iter().enumerate() {
        if values.len() != output_names.len() {
            return Err(Error::new(
                ErrorCode::CorruptStorage,
                "validated resident quantifier output width changed during publication",
            ));
        }
        let mut row = Row::new();
        for (column_index, (name, value)) in output_names.iter().zip(values).enumerate() {
            let coordinate = (
                u32::try_from(row_index).map_err(|_| {
                    Error::new(
                        ErrorCode::CorruptStorage,
                        "validated resident quantifier row is not addressable",
                    )
                })?,
                u16::try_from(column_index).map_err(|_| {
                    Error::new(
                        ErrorCode::CorruptStorage,
                        "validated resident quantifier column is not addressable",
                    )
                })?,
            );
            let binding = entity_outputs.remove(&coordinate).map_or_else(
                || decode_resident_quantifier_value(value).map(untrusted_result_binding),
                |entities| decode_resident_quantifier_entity_list(entities, context.graph),
            )?;
            row.insert(name.clone(), binding);
        }
        rows.push(row);
    }
    if !entity_outputs.is_empty() {
        return Err(Error::new(
            ErrorCode::CorruptStorage,
            "validated resident quantifier entity output was not published",
        ));
    }
    let graph = GraphReadView::new(context.graph);
    let result = rows_to_result(
        &rows,
        &output_names,
        &graph,
        context.bookmark,
        StatementStats::default(),
        context.max_batch_rows,
        stream.take(),
    )?;
    let mut dependencies = TransactionDependencies::default();
    for dependency in &plan.dependencies {
        dependencies.predicates.insert(
            dependency.clone(),
            context
                .predicate_versions
                .get(dependency)
                .copied()
                .unwrap_or(context.bookmark.index),
        );
    }
    for dependency in read_dependencies {
        match dependency.entity {
            ResidentQuantifierEntityHandle::Node(handle) => {
                let node = context.graph.node_dense(handle.0).ok_or_else(|| {
                    Error::new(
                        ErrorCode::CorruptStorage,
                        "validated resident quantifier read a deleted node",
                    )
                })?;
                dependencies
                    .entities
                    .insert(EntityDependency::Node(node.id()), node.revision());
            }
            ResidentQuantifierEntityHandle::Relationship(handle) => {
                let relationship = context.graph.edge_dense(handle.0).ok_or_else(|| {
                    Error::new(
                        ErrorCode::CorruptStorage,
                        "validated resident quantifier read a deleted relationship",
                    )
                })?;
                dependencies.entities.insert(
                    EntityDependency::Relationship(relationship.id()),
                    relationship.revision(),
                );
            }
        }
    }
    Ok(ExecutionOutput {
        result,
        graph_mutations: Vec::new(),
        temporal_mutations: Vec::new(),
        dependencies,
        administrative: None,
        vector_searches: Vec::new(),
        runtime_replans: 0,
    })
}

fn decode_resident_quantifier_entity_list(
    value: ResidentQuantifierEntityList,
    graph: &GraphStore,
) -> Result<BindingValue> {
    value
        .values
        .into_iter()
        .map(|entity| match entity {
            ResidentQuantifierEntityHandle::Node(handle) => {
                graph.node_dense(handle.0).ok_or_else(|| {
                    Error::new(
                        ErrorCode::CorruptStorage,
                        "validated resident quantifier returned a deleted node",
                    )
                })?;
                Ok(BindingValue::Node(handle.0))
            }
            ResidentQuantifierEntityHandle::Relationship(handle) => {
                graph.edge_dense(handle.0).ok_or_else(|| {
                    Error::new(
                        ErrorCode::CorruptStorage,
                        "validated resident quantifier returned a deleted relationship",
                    )
                })?;
                Ok(BindingValue::Relationship(handle.0))
            }
        })
        .collect::<Result<Vec<_>>>()
        .map(BindingValue::List)
}

fn decode_resident_quantifier_value(value: ResidentQuantifierValue) -> Result<ResultValue> {
    Ok(match value {
        ResidentQuantifierValue::Null => ResultValue::Scalar(ScalarValue::Null),
        ResidentQuantifierValue::Boolean(value) => ResultValue::Scalar(ScalarValue::Boolean(value)),
        ResidentQuantifierValue::Integer(value) => ResultValue::Scalar(ScalarValue::Integer(value)),
        ResidentQuantifierValue::Float(value) => {
            ResultValue::Scalar(ScalarValue::Float(OrderedFloat(f64::from_bits(value))))
        }
        ResidentQuantifierValue::String(value) => {
            ResultValue::Scalar(ScalarValue::String(Arc::from(value)))
        }
        ResidentQuantifierValue::List(values) => ResultValue::List(
            values
                .into_iter()
                .map(decode_resident_quantifier_value)
                .collect::<Result<Vec<_>>>()?,
        ),
        ResidentQuantifierValue::Map(entries) => ResultValue::Map(
            entries
                .into_iter()
                .map(|(key, value)| Ok((key, decode_resident_quantifier_value(value)?)))
                .collect::<Result<BTreeMap<_, _>>>()?,
        ),
    })
}

fn execute_resident_segmented_aggregation_plan(
    plan: &PhysicalPlan,
    compiled: &CompiledResidentSegmentedAggregationPlan,
    backend: &dyn ExecutionBackend,
    context: &ExecutionContext<'_>,
    stream: &mut Option<&mut dyn FnMut(ExecutionStreamItem) -> Result<()>>,
) -> Result<ExecutionOutput> {
    check_execution(context)?;
    let pinned = backend.pin_project(context.project_id)?;
    if pinned.resident_bookmark(context.project_id) != Some(context.bookmark)
        || pinned.resident_graph_revision(context.project_id) != Some(context.graph.revision())
    {
        return Err(Error::new(
            ErrorCode::GpuAdmissionFailure,
            "resident segmented aggregation backend does not own the requested canonical snapshot",
        ));
    }
    if compiled.request.program.as_ref().is_some_and(|program| {
        program.catalog_generation != context.binding_catalog.optimizer_generation()
    }) {
        return Err(Error::new(
            ErrorCode::GpuAdmissionFailure,
            "sealed segmented aggregation targets a stale catalog generation",
        ));
    }
    if !pinned.supports_native_segmented_aggregation() {
        return Err(Error::new(
            ErrorCode::GpuAdmissionFailure,
            "pinned backend lost native segmented-aggregation capability",
        ));
    }

    check_execution(context)?;
    let raw = pinned.execute_segmented_aggregation(&compiled.request, &context.cancellation)?;
    let validated = raw.validate_for_publication(&compiled.request, pinned.kind())?;
    check_execution(context)?;
    let (relation, graph_read_dependencies) = validated.into_relation_and_graph_read_dependencies();
    if relation.row_count as usize > context.max_result_rows {
        return Err(Error::new(
            ErrorCode::CorruptStorage,
            "validated segmented aggregation exceeded the query result-row budget",
        ));
    }

    let width = relation.column_count as usize;
    let output_names = compiled
        .outputs
        .iter()
        .map(|output| output.name.clone())
        .collect::<Vec<_>>();
    let graph = GraphReadView::new(context.graph);
    let mut rows = Vec::with_capacity(relation.row_count as usize);
    for row_index in 0..relation.row_count as usize {
        let row_start = row_index.checked_mul(width).ok_or_else(|| {
            Error::new(
                ErrorCode::CorruptStorage,
                "segmented aggregation result row offset overflow",
            )
        })?;
        let mut row = Row::new();
        let decode_column = |column: u16| -> Result<ResultValue> {
            let cell_index = row_start
                .checked_add(column as usize)
                .filter(|index| *index < relation.top_level_cell_count())
                .ok_or_else(|| {
                    Error::new(
                        ErrorCode::CorruptStorage,
                        "segmented aggregation output mapping is outside the validated relation",
                    )
                })?;
            decode_segmented_aggregation_cell(&relation, cell_index, &graph)
        };
        for output in &compiled.outputs {
            // A container output is assembled on the host from its component device columns; the
            // device only ever produced the scalar/aggregate components (see the segmented-graph
            // compiler), which is what keeps the Metal program's packet well-formed.
            let value = match &output.container {
                Some(container) => {
                    let mut elements = Vec::with_capacity(container.entries.len());
                    for entry in &container.entries {
                        elements.push((entry.key.clone(), decode_column(entry.relation_column)?));
                    }
                    match container.kind {
                        SegmentedContainerKind::List => ResultValue::List(
                            elements.into_iter().map(|(_, value)| value).collect(),
                        ),
                        SegmentedContainerKind::Map => {
                            let mut map = BTreeMap::new();
                            for (key, value) in elements {
                                let key = key.ok_or_else(|| {
                                    Error::internal(
                                        "segmented map container entry is missing its key",
                                    )
                                })?;
                                map.insert(key, value);
                            }
                            ResultValue::Map(map)
                        }
                    }
                }
                None => decode_column(output.relation_column)?,
            };
            row.insert(output.name.clone(), untrusted_result_binding(value));
        }
        rows.push(row);
    }

    let result = rows_to_result(
        &rows,
        &output_names,
        &graph,
        context.bookmark,
        StatementStats::default(),
        context.max_batch_rows,
        stream.take(),
    )?;
    let mut dependencies = TransactionDependencies::default();
    for dependency in &plan.dependencies {
        dependencies.predicates.insert(
            dependency.clone(),
            context
                .predicate_versions
                .get(dependency)
                .copied()
                .unwrap_or(context.bookmark.index),
        );
    }
    for dependency in graph_read_dependencies.into_iter().flatten() {
        record_resident_segmented_graph_dependency(dependency, plan, context, &mut dependencies)?;
    }
    Ok(ExecutionOutput {
        result,
        graph_mutations: Vec::new(),
        temporal_mutations: Vec::new(),
        dependencies,
        administrative: None,
        vector_searches: Vec::new(),
        runtime_replans: 0,
    })
}

fn record_resident_segmented_graph_dependency(
    dependency: ResidentSegmentedGraphReadDependency,
    plan: &PhysicalPlan,
    context: &ExecutionContext<'_>,
    dependencies: &mut TransactionDependencies,
) -> Result<()> {
    match dependency {
        ResidentSegmentedGraphReadDependency::Node(id) => {
            let node = context.graph.node(NodeId(id)).ok_or_else(|| {
                Error::new(
                    ErrorCode::CorruptStorage,
                    "segmented graph source selected a missing canonical node",
                )
            })?;
            if !plan.read_layers.contains_layer(node.layer()) {
                return Err(Error::new(
                    ErrorCode::CorruptStorage,
                    "segmented graph source selected a node outside visible layers",
                ));
            }
            dependencies
                .entities
                .insert(EntityDependency::Node(node.id()), node.revision());
        }
        ResidentSegmentedGraphReadDependency::Relationship(id) => {
            let edge = context.graph.edge(EdgeId(id)).ok_or_else(|| {
                Error::new(
                    ErrorCode::CorruptStorage,
                    "segmented graph source selected a missing canonical relationship",
                )
            })?;
            if !plan.read_layers.contains_layer(edge.layer()) {
                return Err(Error::new(
                    ErrorCode::CorruptStorage,
                    "segmented graph source selected a relationship outside visible layers",
                ));
            }
            dependencies
                .entities
                .insert(EntityDependency::Relationship(edge.id()), edge.revision());
        }
    }
    Ok(())
}

fn decode_segmented_aggregation_cell(
    relation: &ResidentSegmentedRelation,
    index: usize,
    graph: &GraphReadView<'_>,
) -> Result<ResultValue> {
    let cell = relation.cells.get(index).copied().ok_or_else(|| {
        Error::new(
            ErrorCode::CorruptStorage,
            "segmented aggregation result cell is missing",
        )
    })?;
    let value = match cell.tag {
        ResidentSegmentedValueTag::Null => ResultValue::Scalar(ScalarValue::Null),
        ResidentSegmentedValueTag::Boolean => {
            ResultValue::Scalar(ScalarValue::Boolean(cell.payload != 0))
        }
        ResidentSegmentedValueTag::Integer => {
            ResultValue::Scalar(ScalarValue::Integer(cell.payload as i64))
        }
        ResidentSegmentedValueTag::Float => ResultValue::Scalar(ScalarValue::Float(OrderedFloat(
            f64::from_bits(cell.payload),
        ))),
        ResidentSegmentedValueTag::String => {
            let bytes = segmented_aggregation_bytes(relation, cell.payload, cell.auxiliary)?;
            let value = std::str::from_utf8(bytes).map_err(|_| {
                Error::new(
                    ErrorCode::CorruptStorage,
                    "validated segmented aggregation returned invalid UTF-8",
                )
            })?;
            ResultValue::Scalar(ScalarValue::String(Arc::from(value)))
        }
        ResidentSegmentedValueTag::Bytes => {
            let bytes = segmented_aggregation_bytes(relation, cell.payload, cell.auxiliary)?;
            ResultValue::Scalar(ScalarValue::Bytes(Arc::from(bytes)))
        }
        ResidentSegmentedValueTag::Map => {
            let bytes = segmented_aggregation_bytes(relation, cell.payload, cell.auxiliary)?;
            crate::document::validate_canonical(bytes, crate::document::DocumentRoot::Map)?;
            ResultValue::from_property(ScalarValue::Map(DocumentMap::from_canonical(Arc::from(
                bytes,
            ))))?
        }
        ResidentSegmentedValueTag::List => {
            let start = usize::try_from(cell.payload).map_err(|_| {
                Error::new(
                    ErrorCode::CorruptStorage,
                    "segmented aggregation list offset exceeds usize",
                )
            })?;
            let length = usize::try_from(cell.auxiliary).map_err(|_| {
                Error::new(
                    ErrorCode::CorruptStorage,
                    "segmented aggregation list length exceeds usize",
                )
            })?;
            let end = start.checked_add(length).ok_or_else(|| {
                Error::new(
                    ErrorCode::CorruptStorage,
                    "segmented aggregation list range overflow",
                )
            })?;
            if start < relation.top_level_cell_count() || end > relation.cells.len() {
                return Err(Error::new(
                    ErrorCode::CorruptStorage,
                    "segmented aggregation list range is outside the validated suffix",
                ));
            }
            ResultValue::List(
                (start..end)
                    .map(|child| decode_segmented_aggregation_cell(relation, child, graph))
                    .collect::<Result<Vec<_>>>()?,
            )
        }
        ResidentSegmentedValueTag::Node => {
            let id = NodeId(cell.payload);
            let dense = graph.node(id).map(|node| node.dense()).ok_or_else(|| {
                Error::new(
                    ErrorCode::CorruptStorage,
                    "sealed segmented aggregation returned an absent node identity",
                )
            })?;
            ResultValue::Node(materialize_node(graph, dense)?)
        }
        ResidentSegmentedValueTag::Relationship => {
            let id = EdgeId(cell.payload);
            let dense = graph.edge(id).map(|edge| edge.dense()).ok_or_else(|| {
                Error::new(
                    ErrorCode::CorruptStorage,
                    "sealed segmented aggregation returned an absent relationship identity",
                )
            })?;
            ResultValue::Relationship(materialize_edge(graph, dense)?)
        }
    };
    Ok(value)
}

fn segmented_aggregation_bytes(
    relation: &ResidentSegmentedRelation,
    offset: u64,
    length: u64,
) -> Result<&[u8]> {
    let start = usize::try_from(offset).map_err(|_| {
        Error::new(
            ErrorCode::CorruptStorage,
            "segmented aggregation byte offset exceeds usize",
        )
    })?;
    let length = usize::try_from(length).map_err(|_| {
        Error::new(
            ErrorCode::CorruptStorage,
            "segmented aggregation byte length exceeds usize",
        )
    })?;
    let end = start.checked_add(length).ok_or_else(|| {
        Error::new(
            ErrorCode::CorruptStorage,
            "segmented aggregation byte range overflow",
        )
    })?;
    relation.arena.get(start..end).ok_or_else(|| {
        Error::new(
            ErrorCode::CorruptStorage,
            "segmented aggregation byte range is outside the validated arena",
        )
    })
}

fn execute_resident_boolean_aggregate_plan(
    plan: &PhysicalPlan,
    compiled: &CompiledResidentBooleanAggregatePlan,
    backend: &dyn ExecutionBackend,
    context: &ExecutionContext<'_>,
    stream: &mut Option<&mut dyn FnMut(ExecutionStreamItem) -> Result<()>>,
) -> Result<ExecutionOutput> {
    check_execution(context)?;
    let output =
        backend.execute_boolean_aggregate_program(&compiled.request, &context.cancellation)?;
    if output.rows.len() > context.max_result_rows {
        return Err(Error::new(
            ErrorCode::ResultBudgetExceeded,
            "resident Boolean aggregate program exceeded the result row budget",
        ));
    }
    if output
        .rows
        .iter()
        .any(|row| row.len() != compiled.output_names.len())
    {
        return Err(Error::new(
            ErrorCode::CorruptStorage,
            "resident Boolean aggregate program returned an invalid final row shape",
        ));
    }
    let mut rows = Vec::with_capacity(output.rows.len());
    for values in output.rows {
        let mut row = Row::new();
        for (name, value) in compiled.output_names.iter().zip(values) {
            let value = match value {
                ResidentBooleanValue::Null => ResultValue::Scalar(ScalarValue::Null),
                ResidentBooleanValue::Boolean(value) => {
                    ResultValue::Scalar(ScalarValue::Boolean(value))
                }
                ResidentBooleanValue::InvalidArgument => {
                    return Err(Error::new(
                        ErrorCode::QueryType,
                        "InvalidArgumentValue: native Boolean aggregate received incompatible values",
                    ));
                }
            };
            row.insert(name.clone(), BindingValue::Value(value));
        }
        rows.push(row);
    }
    let graph = GraphReadView::new(context.graph);
    let result = rows_to_result(
        &rows,
        &compiled.output_names,
        &graph,
        context.bookmark,
        StatementStats::default(),
        context.max_batch_rows,
        stream.take(),
    )?;
    let mut dependencies = TransactionDependencies::default();
    for dependency in &plan.dependencies {
        let version = context
            .predicate_versions
            .get(dependency)
            .copied()
            .unwrap_or(context.bookmark.index);
        dependencies.predicates.insert(dependency.clone(), version);
    }
    Ok(ExecutionOutput {
        result,
        graph_mutations: Vec::new(),
        temporal_mutations: Vec::new(),
        dependencies,
        administrative: None,
        vector_searches: Vec::new(),
        runtime_replans: 0,
    })
}

fn execute_resident_vector_plan(
    plan: &PhysicalPlan,
    compiled: &CompiledResidentVectorPlan,
    context: &ExecutionContext<'_>,
    stream: &mut Option<&mut dyn FnMut(ExecutionStreamItem) -> Result<()>>,
) -> Result<ExecutionOutput> {
    check_execution(context)?;
    for predicate in &compiled.selection.predicates {
        if !context.graph.node_property_is_integer(predicate.property) {
            return Err(Error::new(
                ErrorCode::GpuAdmissionFailure,
                "resident vector candidate filter is not an integer device column",
            ));
        }
    }
    let mut dependencies = TransactionDependencies::default();
    for dependency in &plan.dependencies {
        let version = context
            .predicate_versions
            .get(dependency)
            .copied()
            .unwrap_or(context.bookmark.index);
        dependencies.predicates.insert(dependency.clone(), version);
    }
    let mut state = ExecutionState {
        graph: transaction_graph_view(context)?,
        temporal: transaction_temporal_view(context)?,
        mutations: Vec::new(),
        temporal_mutations: Vec::new(),
        dependencies,
        next_node_id: context.next_node_id,
        next_edge_id: context.next_edge_id,
        revision: context.mutation_revision,
        created_at: resolved_created_at(context.resolved_time_nanos),
        read_layers: plan.read_layers,
        write_layer: plan.write_layer,
        stats: StatementStats::default(),
        final_columns: Vec::new(),
        scope_columns: BTreeSet::new(),
        administrative: None,
        vector_searches: Vec::new(),
        resident_backend: None,
        allow_context_backend: true,
        resident_overlay_mutations: 0,
        existential_subquery_depth: 0,
        initial_scan_cap: None,
    };
    let mut rows = vector_search_with_selection(
        vec![Row::new()],
        &compiled.search,
        compiled.access,
        Some(&compiled.selection),
        &mut state,
        context,
    )?;
    state.scope_columns.insert(compiled.search.variable.clone());
    state
        .scope_columns
        .insert(compiled.search.score_variable.clone());
    if rows.len() > context.max_result_rows {
        return Err(Error::new(
            ErrorCode::ResultBudgetExceeded,
            "vector query row budget exceeded",
        ));
    }
    for operator in &compiled.trailing {
        check_execution(context)?;
        rows = apply_operator(operator, rows, &mut state, context, None)?;
        if rows.len() > context.max_result_rows {
            return Err(Error::new(
                ErrorCode::ResultBudgetExceeded,
                "vector query row budget exceeded",
            ));
        }
    }
    let graph = GraphReadView::new(context.graph);
    let output_stream = stream.take();
    let result = rows_to_result(
        &rows,
        &state.final_columns,
        &graph,
        context.bookmark,
        state.stats,
        context.max_batch_rows,
        output_stream,
    )?;
    Ok(ExecutionOutput {
        result,
        graph_mutations: state.mutations,
        temporal_mutations: state.temporal_mutations,
        dependencies: state.dependencies,
        administrative: state.administrative,
        vector_searches: state.vector_searches,
        runtime_replans: 0,
    })
}

fn execute_resident_group_plan(
    plan: &PhysicalPlan,
    compiled: &CompiledResidentPlan,
    backend: &dyn ExecutionBackend,
    context: &ExecutionContext<'_>,
    stream: &mut Option<&mut dyn FnMut(ExecutionStreamItem) -> Result<()>>,
) -> Result<ExecutionOutput> {
    let grouping = compiled
        .grouping
        .as_ref()
        .ok_or_else(|| Error::internal("resident grouping request is absent"))?;
    let reductions = backend.execute_node_group_pipelines(
        grouping,
        &compiled.additional_groupings,
        &context.cancellation,
    )?;
    if reductions.len() != 1 + compiled.additional_groupings.len() {
        return Err(Error::new(
            ErrorCode::CorruptStorage,
            "resident backend omitted an aligned grouping reduction",
        ));
    }
    for next in reductions.iter().skip(1) {
        if next.len() != reductions[0].len()
            || next
                .iter()
                .zip(&reductions[0])
                .any(|(next, first)| next.key != first.key || next.rows != first.rows)
        {
            return Err(Error::new(
                ErrorCode::CorruptStorage,
                "aligned resident reductions returned different grouping rows",
            ));
        }
    }
    let groups = &reductions[0];
    if groups.len() > context.max_result_rows {
        return Err(Error::new(
            ErrorCode::ResultBudgetExceeded,
            "resident grouping exceeded the query row budget",
        ));
    }
    let mut columns = Vec::with_capacity(compiled.outputs.len());
    for output in &compiled.outputs {
        let values = match output.source {
            ResidentOutputSource::GroupKey => groups
                .iter()
                .map(|group| {
                    ResultValue::Scalar(group.key.map_or(ScalarValue::Null, ScalarValue::Integer))
                })
                .collect::<Vec<_>>(),
            ResidentOutputSource::GroupAggregate(index) => reductions
                .get(index as usize)
                .ok_or_else(|| {
                    Error::new(
                        ErrorCode::CorruptStorage,
                        "resident grouping omitted a compiled reduction",
                    )
                })?
                .iter()
                .map(|group| ResultValue::Scalar(group.value.clone().unwrap_or(ScalarValue::Null)))
                .collect::<Vec<_>>(),
            ResidentOutputSource::Node(_)
            | ResidentOutputSource::Relationship
            | ResidentOutputSource::Integer(_, _)
            | ResidentOutputSource::Property(_, _)
            | ResidentOutputSource::PropertyIsNull(_)
            | ResidentOutputSource::TemporalSample
            | ResidentOutputSource::TemporalTime
            | ResidentOutputSource::TemporalValue
            | ResidentOutputSource::TemporalBucket
            | ResidentOutputSource::TemporalBucketStart
            | ResidentOutputSource::TemporalBucketEnd => {
                return Err(Error::internal(
                    "row output reached the resident grouping pipeline",
                ));
            }
        };
        columns.push(ResultColumn {
            name: output.name.clone(),
            value_type: result_values_type(&values),
            values,
        });
    }
    let schema = columns
        .iter()
        .map(|column| (column.name.clone(), column.value_type.clone()))
        .collect::<Vec<_>>();
    if let Some(emit) = stream.as_deref_mut() {
        emit(ExecutionStreamItem::Schema(schema.clone()))?;
    }
    let mut batches = Vec::new();
    let batch_rows = context.max_batch_rows.max(1);
    for start in (0..groups.len()).step_by(batch_rows) {
        check_execution(context)?;
        let end = start.saturating_add(batch_rows).min(groups.len());
        let batch = ResultBatch {
            row_count: end - start,
            columns: columns
                .iter()
                .map(|column| ResultColumn {
                    name: column.name.clone(),
                    value_type: column.value_type.clone(),
                    values: column.values[start..end].to_vec(),
                })
                .collect(),
        };
        if let Some(emit) = stream.as_deref_mut() {
            emit(ExecutionStreamItem::Batch(batch))?;
        } else {
            batches.push(batch);
        }
    }
    let mut dependencies = TransactionDependencies::default();
    for dependency in &plan.dependencies {
        let version = context
            .predicate_versions
            .get(dependency)
            .copied()
            .unwrap_or(context.bookmark.index);
        dependencies.predicates.insert(dependency.clone(), version);
    }
    // Every graph scan is bound with at least one predicate stamp (full scan, label, type, or
    // property), and standalone publication advances the project authority revision plus every
    // materialized stamp on each graph write. Those stamps already fence the complete aggregate
    // snapshot. Enumerating every visible node and edge here added no stronger conflict check; it
    // rebuilt an O(N+E) BTreeMap after the backend had reduced the query to one row, dominating
    // both latency and transient memory on large graphs.
    debug_assert!(
        !plan.dependencies.is_empty(),
        "resident graph grouping must retain a predicate dependency fence"
    );
    Ok(ExecutionOutput {
        result: QueryResult {
            schema,
            batches,
            bookmark: context.bookmark,
            statistics: StatementStats::default(),
            truncated: false,
        },
        graph_mutations: Vec::new(),
        temporal_mutations: Vec::new(),
        dependencies,
        administrative: None,
        vector_searches: Vec::new(),
        runtime_replans: 0,
    })
}

fn execute_resident_temporal_plan(
    plan: &PhysicalPlan,
    compiled: &CompiledResidentPlan,
    backend: &dyn ExecutionBackend,
    context: &ExecutionContext<'_>,
    stream: &mut Option<&mut dyn FnMut(ExecutionStreamItem) -> Result<()>>,
) -> Result<ExecutionOutput> {
    let request = compiled
        .temporal
        .as_ref()
        .ok_or_else(|| Error::internal("resident temporal request is absent"))?;
    let temporal = backend.execute_temporal_pipeline(request, &context.cancellation)?;
    let row_count = temporal.start_rows.len();
    let expansion_lengths_valid = if request.input.expansion.is_some() {
        temporal.edge_rows.len() == row_count && temporal.end_rows.len() == row_count
    } else {
        temporal.edge_rows.is_empty() && temporal.end_rows.is_empty()
    };
    let bucket_lengths_valid = if request.window.is_some() {
        temporal.bucket_starts_nanos.len() == row_count
            && temporal.bucket_ends_nanos.len() == row_count
    } else {
        temporal.bucket_starts_nanos.is_empty() && temporal.bucket_ends_nanos.is_empty()
    };
    if row_count > context.max_result_rows
        || temporal.event_times_nanos.len() != row_count
        || temporal.values.len() != row_count
        || temporal.validity.len() != row_count
        || !expansion_lengths_valid
        || !bucket_lengths_valid
    {
        return Err(Error::new(
            ErrorCode::CorruptStorage,
            "resident temporal pipeline returned columns with different lengths",
        ));
    }
    let graph = GraphReadView::new(context.graph);
    let mut columns = Vec::with_capacity(compiled.outputs.len());
    for output in &compiled.outputs {
        let values = match output.source {
            ResidentOutputSource::Node(binding) => {
                let rows = match binding {
                    ResidentNodeBinding::Start => &temporal.start_rows,
                    ResidentNodeBinding::Intermediate(_) => {
                        return Err(Error::internal(
                            "resident temporal pipeline cannot materialize an intermediate path node",
                        ));
                    }
                    ResidentNodeBinding::End => &temporal.end_rows,
                };
                rows.iter()
                    .map(|dense| materialize_node(&graph, *dense).map(ResultValue::Node))
                    .collect::<Result<Vec<_>>>()?
            }
            ResidentOutputSource::Relationship => temporal
                .edge_rows
                .iter()
                .map(|dense| materialize_edge(&graph, *dense).map(ResultValue::Relationship))
                .collect::<Result<Vec<_>>>()?,
            ResidentOutputSource::Integer(binding, property)
            | ResidentOutputSource::Property(binding, property) => {
                let rows = match binding {
                    ResidentNodeBinding::Start => &temporal.start_rows,
                    ResidentNodeBinding::Intermediate(_) => {
                        return Err(Error::internal(
                            "resident temporal pipeline cannot materialize an intermediate path node",
                        ));
                    }
                    ResidentNodeBinding::End => &temporal.end_rows,
                };
                rows.iter()
                    .map(|dense| {
                        graph
                            .node_dense(*dense)
                            .and_then(|node| node.property(property))
                            .map_or(
                                Ok(ResultValue::Scalar(ScalarValue::Null)),
                                ResultValue::from_property,
                            )
                    })
                    .collect::<Result<Vec<_>>>()?
            }
            ResidentOutputSource::PropertyIsNull(_) => {
                return Err(Error::internal(
                    "row Boolean output reached the resident temporal pipeline",
                ));
            }
            ResidentOutputSource::TemporalSample => temporal
                .event_times_nanos
                .iter()
                .copied()
                .zip(temporal.values.iter().copied())
                .zip(temporal.validity.iter().copied())
                .map(|((time, value), valid)| {
                    ResultValue::Map(BTreeMap::from([
                        (
                            "time".to_owned(),
                            ResultValue::Scalar(ScalarValue::Integer(time)),
                        ),
                        (
                            "value".to_owned(),
                            ResultValue::Scalar(if valid == 0 {
                                ScalarValue::Null
                            } else {
                                ScalarValue::Integer(value)
                            }),
                        ),
                    ]))
                })
                .collect(),
            ResidentOutputSource::TemporalTime => temporal
                .event_times_nanos
                .iter()
                .map(|time| ResultValue::Scalar(ScalarValue::Integer(*time)))
                .collect(),
            ResidentOutputSource::TemporalValue => temporal
                .values
                .iter()
                .zip(&temporal.validity)
                .map(|(value, valid)| {
                    ResultValue::Scalar(if *valid == 0 {
                        ScalarValue::Null
                    } else {
                        ScalarValue::Integer(*value)
                    })
                })
                .collect(),
            ResidentOutputSource::TemporalBucket => temporal
                .bucket_starts_nanos
                .iter()
                .zip(&temporal.bucket_ends_nanos)
                .map(|(start, end)| {
                    ResultValue::Map(BTreeMap::from([
                        (
                            "start".to_owned(),
                            ResultValue::Scalar(ScalarValue::Integer(*start)),
                        ),
                        (
                            "end".to_owned(),
                            ResultValue::Scalar(ScalarValue::Integer(*end)),
                        ),
                    ]))
                })
                .collect(),
            ResidentOutputSource::TemporalBucketStart => temporal
                .bucket_starts_nanos
                .iter()
                .map(|start| ResultValue::Scalar(ScalarValue::Integer(*start)))
                .collect(),
            ResidentOutputSource::TemporalBucketEnd => temporal
                .bucket_ends_nanos
                .iter()
                .map(|end| ResultValue::Scalar(ScalarValue::Integer(*end)))
                .collect(),
            ResidentOutputSource::GroupKey | ResidentOutputSource::GroupAggregate(_) => {
                return Err(Error::internal(
                    "resident grouping output reached the temporal pipeline",
                ));
            }
        };
        columns.push(ResultColumn {
            name: output.name.clone(),
            value_type: result_values_type(&values),
            values,
        });
    }
    let schema = columns
        .iter()
        .map(|column| (column.name.clone(), column.value_type.clone()))
        .collect::<Vec<_>>();
    if let Some(emit) = stream.as_deref_mut() {
        emit(ExecutionStreamItem::Schema(schema.clone()))?;
    }
    let mut batches = Vec::new();
    let batch_rows = context.max_batch_rows.max(1);
    for start in (0..row_count).step_by(batch_rows) {
        check_execution(context)?;
        let end = start.saturating_add(batch_rows).min(row_count);
        let batch = ResultBatch {
            row_count: end - start,
            columns: columns
                .iter()
                .map(|column| ResultColumn {
                    name: column.name.clone(),
                    value_type: column.value_type.clone(),
                    values: column.values[start..end].to_vec(),
                })
                .collect(),
        };
        if let Some(emit) = stream.as_deref_mut() {
            emit(ExecutionStreamItem::Batch(batch))?;
        } else {
            batches.push(batch);
        }
    }
    let mut dependencies = TransactionDependencies::default();
    for dependency in &plan.dependencies {
        let version = context
            .predicate_versions
            .get(dependency)
            .copied()
            .unwrap_or(context.bookmark.index);
        dependencies.predicates.insert(dependency.clone(), version);
    }
    for dense in temporal.start_rows.iter().chain(&temporal.end_rows) {
        let node = context.graph.node_dense(*dense).ok_or_else(|| {
            Error::new(
                ErrorCode::CorruptStorage,
                "resident temporal pipeline selected a deleted node",
            )
        })?;
        dependencies
            .entities
            .insert(EntityDependency::Node(node.id()), node.revision());
    }
    Ok(ExecutionOutput {
        result: QueryResult {
            schema,
            batches,
            bookmark: context.bookmark,
            statistics: StatementStats::default(),
            truncated: false,
        },
        graph_mutations: Vec::new(),
        temporal_mutations: Vec::new(),
        dependencies,
        administrative: None,
        vector_searches: Vec::new(),
        runtime_replans: 0,
    })
}

fn result_values_type(values: &[ResultValue]) -> ColumnType {
    let mut value_type = ColumnType::Null;
    for value in values {
        let next = value.column_type();
        if next == ColumnType::Null {
            continue;
        }
        if value_type == ColumnType::Null {
            value_type = next;
        } else if value_type != next {
            return ColumnType::Any;
        }
    }
    value_type
}

fn transaction_graph_view<'a>(context: &ExecutionContext<'a>) -> Result<GraphReadView<'a>> {
    let mut graph = GraphReadView::new(context.graph);
    for mutation in context.prior_graph_mutations {
        graph.apply(mutation)?;
    }
    Ok(graph)
}

fn transaction_temporal_view<'a>(context: &ExecutionContext<'a>) -> Result<TemporalReadView<'a>> {
    let mut temporal = TemporalReadView::new(context.temporal);
    for mutation in context.prior_temporal_mutations {
        temporal.append(
            mutation.entity_kind,
            mutation.target,
            mutation.sample.clone(),
            context.resolved_time_nanos,
        )?;
    }
    Ok(temporal)
}

struct ExecutionState<'a> {
    graph: GraphReadView<'a>,
    temporal: TemporalReadView<'a>,
    mutations: Vec<GraphMutation>,
    temporal_mutations: Vec<PreparedTemporalMutation>,
    dependencies: TransactionDependencies,
    next_node_id: u64,
    next_edge_id: u64,
    revision: u64,
    created_at: Option<ScalarValue>,
    read_layers: crate::graph::LayerMask,
    write_layer: Layer,
    stats: StatementStats,
    final_columns: Vec<String>,
    /// Logical visible bindings survive even when an operator produces no physical rows. This is
    /// the authoritative source for `RETURN *` schema expansion on an empty pipeline.
    scope_columns: BTreeSet<String>,
    administrative: Option<Statement>,
    vector_searches: Vec<VectorSearchTrace>,
    resident_backend: Option<Box<dyn ExecutionBackend>>,
    /// False only for a plan selected wholly for CPU by the measured adaptive policy. This keeps
    /// host operators from re-entering Metal through opportunistic sort/group helpers mid-plan.
    allow_context_backend: bool,
    resident_overlay_mutations: usize,
    existential_subquery_depth: usize,
    /// Upper bound on nodes the initial bare label/all-node scan needs to yield, when the plan is a
    /// bare limited scan (`plan_bare_scan_row_cap`). `None` means scan the whole label. Consumed only
    /// by the host unindexed scan in `start_candidates`; such plans have exactly one scan.
    initial_scan_cap: Option<usize>,
}

/// Executes one physical operator boundary. An adjacent OPTIONAL MATCH and WHERE must remain one
/// correlated unit: WHERE participates in deciding whether the optional pattern matched. Applying
/// it later as an ordinary filter would discard the null-extended input row.
fn apply_operator_sequence_step(
    operators: &[PhysicalOperator],
    operator_index: usize,
    rows: Vec<Row>,
    state: &mut ExecutionState<'_>,
    context: &ExecutionContext<'_>,
    procedures: Option<&ProcedureCatalog>,
) -> Result<(Vec<Row>, usize)> {
    let Some(operator) = operators.get(operator_index) else {
        return Ok((rows, 0));
    };
    if let PhysicalOperator::ScanPattern {
        match_group,
        optional: true,
        ..
    } = operator
    {
        let mut cursor = operator_index;
        let mut patterns = Vec::new();
        while let Some(PhysicalOperator::ScanPattern {
            match_group: candidate_group,
            optional: true,
            pattern,
            access,
        }) = operators.get(cursor)
        {
            if candidate_group != match_group {
                break;
            }
            patterns.push((pattern, access));
            cursor = cursor.saturating_add(1);
        }
        let predicates = operators[cursor..]
            .iter()
            .take_while(|operator| matches!(operator, PhysicalOperator::Filter(_)))
            .filter_map(|operator| match operator {
                PhysicalOperator::Filter(expression) => Some(expression),
                _ => None,
            })
            .collect::<Vec<_>>();
        let consumed = patterns.len().saturating_add(predicates.len());
        let mut rows = rows;
        for row in &mut rows {
            row.enter_match_group(*match_group);
        }
        let rows = optional_match_where(rows, &patterns, &predicates, state, context)?;
        for (pattern, _) in patterns {
            extend_pattern_scope(&mut state.scope_columns, pattern);
        }
        return Ok((rows, consumed));
    }
    if let PhysicalOperator::Unwind {
        expression,
        variable,
    } = operator
    {
        let demand =
            downstream_unwind_row_demand(operators, operator_index, rows.first(), state, context)?;
        let rows = unwind_rows(rows, expression, variable, demand, state, context)?;
        state.scope_columns.insert(variable.clone());
        return Ok((rows, 1));
    }
    apply_operator(operator, rows, state, context, procedures).map(|rows| (rows, 1))
}

/// Finds a downstream LIMIT which can safely bound UNWIND demand. A non-aggregating,
/// non-DISTINCT projection preserves one input row as one output row, so a pull-based LIMIT would
/// never request more than this many UNWIND rows. Filters, sorts, writes, aggregation, DISTINCT,
/// SKIP, and graph operators stop the pushdown because they may change cardinality or observable
/// work.
fn downstream_unwind_row_demand(
    operators: &[PhysicalOperator],
    operator_index: usize,
    first_row: Option<&Row>,
    state: &mut ExecutionState<'_>,
    context: &ExecutionContext<'_>,
) -> Result<Option<usize>> {
    let mut cursor = operator_index.saturating_add(1);
    loop {
        match operators.get(cursor) {
            Some(PhysicalOperator::CardinalityCheckpoint { .. }) => {
                cursor = cursor.saturating_add(1);
            }
            Some(PhysicalOperator::Project { projection, .. })
                if !projection.distinct
                    && projection
                        .items
                        .iter()
                        .all(|item| !is_aggregate(&item.expression)) =>
            {
                cursor = cursor.saturating_add(1);
            }
            Some(PhysicalOperator::Limit(expression)) => {
                return evaluate_non_negative_usize(expression, first_row, state, context)
                    .map(Some);
            }
            _ => return Ok(None),
        }
    }
}

fn unwind_rows(
    rows: Vec<Row>,
    expression: &Expression,
    variable: &str,
    demand: Option<usize>,
    state: &mut ExecutionState<'_>,
    context: &ExecutionContext<'_>,
) -> Result<Vec<Row>> {
    let mut output = Vec::new();
    for (index, row) in rows.into_iter().enumerate() {
        if demand.is_some_and(|demand| output.len() >= demand) {
            break;
        }
        if index & 4095 == 0 {
            check_execution(context)?;
        }
        let remaining_demand = demand.map(|demand| demand.saturating_sub(output.len()));
        let remaining_budget = context.max_result_rows.saturating_sub(output.len());
        let values = unwind_expression_values(
            expression,
            &row,
            remaining_demand,
            remaining_budget,
            state,
            context,
        )?;
        for value in values {
            if demand.is_some_and(|demand| output.len() >= demand) {
                break;
            }
            if output.len() >= context.max_result_rows {
                return Err(Error::new(
                    ErrorCode::ResultBudgetExceeded,
                    "query row budget exceeded",
                ));
            }
            let mut next = row.clone();
            next.insert(variable.to_owned(), value);
            output.push(next);
        }
    }
    Ok(output)
}

fn unwind_expression_values(
    expression: &Expression,
    row: &Row,
    demand: Option<usize>,
    maximum_rows: usize,
    state: &mut ExecutionState<'_>,
    context: &ExecutionContext<'_>,
) -> Result<Vec<BindingValue>> {
    if let Some(demand) = demand
        && let Expression::Function {
            name, arguments, ..
        } = expression
        && name.len() == 1
        && name[0].eq_ignore_ascii_case("range")
    {
        let values = arguments
            .iter()
            .map(|argument| evaluate_state(argument, row, state, context))
            .collect::<Result<Vec<_>>>()?;
        let ResultValue::List(values) =
            cypher_range_with_demand(&values, maximum_rows, Some(demand))?
        else {
            return Err(Error::internal("range did not produce a list"));
        };
        return Ok(values.into_iter().map(untrusted_result_binding).collect());
    }

    let value = evaluate_binding_state(expression, row, state, context)?;
    match value {
        BindingValue::List(values) => match demand {
            Some(demand) => Ok(values.into_iter().take(demand).collect()),
            None => Ok(values),
        },
        BindingValue::Value(ResultValue::List(values)) => Ok(values
            .into_iter()
            .take(demand.unwrap_or(usize::MAX))
            .map(untrusted_result_binding)
            .collect()),
        value if binding_is_null(&value) => Ok(Vec::new()),
        _ => Err(Error::new(
            ErrorCode::QueryType,
            "UNWIND expression must be a list",
        )),
    }
}

fn apply_operator(
    operator: &PhysicalOperator,
    rows: Vec<Row>,
    state: &mut ExecutionState<'_>,
    context: &ExecutionContext<'_>,
    procedures: Option<&ProcedureCatalog>,
) -> Result<Vec<Row>> {
    match operator {
        PhysicalOperator::ScanPattern {
            match_group,
            optional,
            pattern,
            access,
        } => {
            let mut rows = rows;
            for row in &mut rows {
                row.enter_match_group(*match_group);
            }
            let output = match_pattern(rows, pattern, access, *optional, true, state, context)?;
            extend_pattern_scope(&mut state.scope_columns, pattern);
            Ok(output)
        }
        PhysicalOperator::CardinalityCheckpoint { .. } => Ok(rows),
        PhysicalOperator::CyclicMultiwayJoin {
            match_group,
            patterns,
        } => {
            let mut rows = rows;
            for row in &mut rows {
                row.enter_match_group(*match_group);
            }
            let output = cyclic_multiway_join(rows, patterns, state, context)?;
            for (pattern, _) in patterns {
                extend_pattern_scope(&mut state.scope_columns, pattern);
            }
            Ok(output)
        }
        PhysicalOperator::Filter(expression) => filter_rows(rows, expression, state, context),
        PhysicalOperator::Unwind {
            expression,
            variable,
        } => {
            let output = unwind_rows(rows, expression, variable, None, state, context)?;
            state.scope_columns.insert(variable.clone());
            Ok(output)
        }
        PhysicalOperator::CreatePattern(pattern) => {
            let output = create_pattern(rows, pattern, state, context)?;
            extend_pattern_scope(&mut state.scope_columns, pattern);
            Ok(output)
        }
        PhysicalOperator::MergePattern {
            pattern,
            on_create,
            on_match,
        } => {
            let mut output = Vec::new();
            for row in rows {
                let pattern = evaluate_merge_pattern_properties(pattern, &row, state, context)?;
                let matched = match_pattern(
                    vec![row.clone()],
                    &pattern,
                    &super::ScanAccessPath::Unspecified,
                    false,
                    false,
                    state,
                    context,
                )?;
                if matched.is_empty() {
                    let created = create_pattern(vec![row], &pattern, state, context)?;
                    output.extend(set_items(created, on_create, state, context)?);
                } else {
                    output.extend(set_items(matched, on_match, state, context)?);
                }
            }
            extend_pattern_scope(&mut state.scope_columns, pattern);
            Ok(output)
        }
        PhysicalOperator::Set(items) => set_items(rows, items, state, context),
        PhysicalOperator::Remove(items) => remove_items(rows, items, state, context),
        PhysicalOperator::Delete {
            detach,
            expressions,
        } => delete_items(rows, expressions, *detach, state, context),
        PhysicalOperator::Project {
            keep_scope,
            projection,
        } => {
            let input_scope = state.scope_columns.clone();
            let (projected, columns) =
                project_rows(rows, projection, &input_scope, state, context, *keep_scope)?;
            if !keep_scope {
                state.scope_columns = columns.iter().cloned().collect();
                state.final_columns = columns;
            } else {
                state.scope_columns.extend(columns);
            }
            Ok(projected)
        }
        PhysicalOperator::Sort(items) => sort_rows(rows, items, state, context),
        PhysicalOperator::TopK { items, limit } => top_k_rows(rows, items, *limit, state, context),
        PhysicalOperator::Skip(expression) => {
            let count = evaluate_non_negative_usize(expression, rows.first(), state, context)?;
            Ok(rows.into_iter().skip(count).collect())
        }
        PhysicalOperator::Limit(expression) => {
            let count = evaluate_non_negative_usize(expression, rows.first(), state, context)?;
            Ok(rows.into_iter().take(count).collect())
        }
        PhysicalOperator::TemporalHistory(history) => {
            let output = temporal_history(rows, history, state, context)?;
            state.scope_columns.insert(history.variable.clone());
            Ok(output)
        }
        PhysicalOperator::TemporalWindow(window) => {
            let output = temporal_window(rows, window, state, context)?;
            state.scope_columns.insert(window.variable.clone());
            Ok(output)
        }
        PhysicalOperator::TemporalHistoryWindow { history, window } => {
            let output = temporal_history_window(rows, history, window, state, context)?;
            state.scope_columns.insert(history.variable.clone());
            state.scope_columns.insert(window.variable.clone());
            Ok(output)
        }
        PhysicalOperator::VectorSearch { search, access } => {
            let output = vector_search(rows, search, *access, state, context)?;
            state.scope_columns.insert(search.variable.clone());
            state.scope_columns.insert(search.score_variable.clone());
            Ok(output)
        }
        PhysicalOperator::BuiltinProcedure(call) => {
            let output = call_procedure(rows, call, state, context, procedures)?;
            state
                .scope_columns
                .extend(state.final_columns.iter().cloned());
            Ok(output)
        }
        PhysicalOperator::Finish => {
            state.final_columns.clear();
            state.scope_columns.clear();
            Ok(Vec::new())
        }
        PhysicalOperator::Administrative(statement) => {
            state.administrative = Some(statement.clone());
            Ok(rows)
        }
    }
}

fn filter_rows(
    rows: Vec<Row>,
    expression: &Expression,
    state: &mut ExecutionState<'_>,
    context: &ExecutionContext<'_>,
) -> Result<Vec<Row>> {
    if let Some(filtered) = device_filter_rows(&rows, expression, state, context)? {
        return Ok(filtered);
    }
    let has_correlated_graph_expression = needs_correlated_graph_evaluation(expression);
    let mut output = Vec::new();
    for (index, row) in rows.into_iter().enumerate() {
        if index & 4095 == 0 {
            check_execution(context)?;
        }
        let value = if has_correlated_graph_expression {
            let binding = evaluate_correlated_binding_state(expression, &row, state, context)?;
            binding_to_result(&binding, &state.graph)?
        } else {
            evaluate_state(expression, &row, state, context)?
        };
        match truth(&value)? {
            Truth::True => output.push(row),
            Truth::False | Truth::Unknown => {}
        }
    }
    Ok(output)
}

/// Pattern predicates are legal only inside a filtering expression. Detect them once per
/// operator so ordinary scalar filters do not pay for cloning and rewriting their expression for
/// every input row.
fn contains_pattern_predicate(expression: &Expression) -> bool {
    if expression.pattern_predicate_pattern().is_some() {
        return true;
    }
    match expression {
        Expression::Property(source, _) => contains_pattern_predicate(source),
        Expression::List(values) | Expression::Function { arguments: values, .. } => {
            values.iter().any(contains_pattern_predicate)
        }
        Expression::Map(values) => values
            .iter()
            .any(|(_, value)| contains_pattern_predicate(value)),
        Expression::MapProjection { source, items } => {
            contains_pattern_predicate(source)
                || items.iter().any(|item| {
                    matches!(item, MapProjectionItem::Entry(_, value) if contains_pattern_predicate(value))
                })
        }
        Expression::Case {
            operand,
            alternatives,
            default,
        } => {
            operand
                .as_deref()
                .is_some_and(contains_pattern_predicate)
                || alternatives.iter().any(|alternative| {
                    contains_pattern_predicate(&alternative.when)
                        || contains_pattern_predicate(&alternative.then)
                })
                || default
                    .as_deref()
                    .is_some_and(contains_pattern_predicate)
        }
        Expression::ListComprehension {
            list,
            predicate,
            projection,
            ..
        } => {
            contains_pattern_predicate(list)
                || predicate
                    .as_deref()
                    .is_some_and(contains_pattern_predicate)
                || projection
                    .as_deref()
                    .is_some_and(contains_pattern_predicate)
        }
        Expression::Reduce {
            initial,
            list,
            expression,
            ..
        } => {
            contains_pattern_predicate(initial)
                || contains_pattern_predicate(list)
                || contains_pattern_predicate(expression)
        }
        Expression::ListPredicate {
            list, predicate, ..
        } => contains_pattern_predicate(list) || contains_pattern_predicate(predicate),
        Expression::Unary { operand, .. } => contains_pattern_predicate(operand),
        Expression::Binary { left, right, .. } => {
            contains_pattern_predicate(left) || contains_pattern_predicate(right)
        }
        Expression::IsNull { expression, .. } => contains_pattern_predicate(expression),
        Expression::Index { expression, index } => {
            contains_pattern_predicate(expression) || contains_pattern_predicate(index)
        }
        Expression::Slice {
            expression,
            start,
            end,
        } => {
            contains_pattern_predicate(expression)
                || start
                    .as_deref()
                    .is_some_and(contains_pattern_predicate)
                || end.as_deref().is_some_and(contains_pattern_predicate)
        }
        Expression::Literal(_)
        | Expression::Parameter(_)
        | Expression::Variable(_)
        | Expression::ExistentialSubquery(_)
        | Expression::Star => false,
    }
}

fn contains_existential_subquery(expression: &Expression) -> bool {
    expression_tree_contains(expression, &|candidate| {
        candidate.existential_subquery_parts().is_some()
    })
}

fn expression_tree_contains(
    expression: &Expression,
    predicate: &impl Fn(&Expression) -> bool,
) -> bool {
    if predicate(expression) {
        return true;
    }
    let recurse = |child: &Expression| expression_tree_contains(child, predicate);
    match expression {
        Expression::Property(source, _)
        | Expression::Unary {
            operand: source, ..
        } => recurse(source),
        Expression::List(values)
        | Expression::Function {
            arguments: values, ..
        } => values.iter().any(recurse),
        Expression::Map(values) => values.iter().any(|(_, value)| recurse(value)),
        Expression::MapProjection { source, items } => {
            recurse(source)
                || items.iter().any(
                    |item| matches!(item, MapProjectionItem::Entry(_, value) if recurse(value)),
                )
        }
        Expression::Case {
            operand,
            alternatives,
            default,
        } => {
            operand.as_deref().is_some_and(&recurse)
                || alternatives
                    .iter()
                    .any(|alternative| recurse(&alternative.when) || recurse(&alternative.then))
                || default.as_deref().is_some_and(recurse)
        }
        Expression::ListComprehension {
            list,
            predicate: local_predicate,
            projection,
            ..
        } => {
            recurse(list)
                || local_predicate.as_deref().is_some_and(&recurse)
                || projection.as_deref().is_some_and(recurse)
        }
        Expression::Reduce {
            initial,
            list,
            expression,
            ..
        } => recurse(initial) || recurse(list) || recurse(expression),
        Expression::ListPredicate {
            list, predicate, ..
        }
        | Expression::Binary {
            left: list,
            right: predicate,
            ..
        }
        | Expression::Index {
            expression: list,
            index: predicate,
        } => recurse(list) || recurse(predicate),
        Expression::IsNull { expression, .. } => recurse(expression),
        Expression::Slice {
            expression,
            start,
            end,
        } => {
            recurse(expression)
                || start.as_deref().is_some_and(&recurse)
                || end.as_deref().is_some_and(recurse)
        }
        Expression::Literal(_)
        | Expression::Parameter(_)
        | Expression::Variable(_)
        | Expression::ExistentialSubquery(_)
        | Expression::Star => false,
    }
}

fn contains_pattern_comprehension(expression: &Expression) -> bool {
    if expression.pattern_comprehension_parts().is_some() {
        return true;
    }
    match expression {
        Expression::Property(source, _) => contains_pattern_comprehension(source),
        Expression::List(values) | Expression::Function { arguments: values, .. } => {
            values.iter().any(contains_pattern_comprehension)
        }
        Expression::Map(values) => values
            .iter()
            .any(|(_, value)| contains_pattern_comprehension(value)),
        Expression::MapProjection { source, items } => {
            contains_pattern_comprehension(source)
                || items.iter().any(|item| {
                    matches!(item, MapProjectionItem::Entry(_, value) if contains_pattern_comprehension(value))
                })
        }
        Expression::Case {
            operand,
            alternatives,
            default,
        } => {
            operand
                .as_deref()
                .is_some_and(contains_pattern_comprehension)
                || alternatives.iter().any(|alternative| {
                    contains_pattern_comprehension(&alternative.when)
                        || contains_pattern_comprehension(&alternative.then)
                })
                || default
                    .as_deref()
                    .is_some_and(contains_pattern_comprehension)
        }
        Expression::ListComprehension {
            list,
            predicate,
            projection,
            ..
        } => {
            contains_pattern_comprehension(list)
                || predicate
                    .as_deref()
                    .is_some_and(contains_pattern_comprehension)
                || projection
                    .as_deref()
                    .is_some_and(contains_pattern_comprehension)
        }
        Expression::Reduce {
            initial,
            list,
            expression,
            ..
        } => {
            contains_pattern_comprehension(initial)
                || contains_pattern_comprehension(list)
                || contains_pattern_comprehension(expression)
        }
        Expression::ListPredicate {
            list, predicate, ..
        } => {
            contains_pattern_comprehension(list) || contains_pattern_comprehension(predicate)
        }
        Expression::Unary { operand, .. } => contains_pattern_comprehension(operand),
        Expression::Binary { left, right, .. } => {
            contains_pattern_comprehension(left) || contains_pattern_comprehension(right)
        }
        Expression::IsNull { expression, .. } => contains_pattern_comprehension(expression),
        Expression::Index { expression, index } => {
            contains_pattern_comprehension(expression) || contains_pattern_comprehension(index)
        }
        Expression::Slice {
            expression,
            start,
            end,
        } => {
            contains_pattern_comprehension(expression)
                || start
                    .as_deref()
                    .is_some_and(contains_pattern_comprehension)
                || end
                    .as_deref()
                    .is_some_and(contains_pattern_comprehension)
        }
        Expression::Literal(_)
        | Expression::Parameter(_)
        | Expression::Variable(_)
        | Expression::ExistentialSubquery(_)
        | Expression::Star => false,
    }
}

fn needs_correlated_graph_evaluation(expression: &Expression) -> bool {
    contains_pattern_comprehension(expression)
        || contains_pattern_predicate(expression)
        || contains_existential_subquery(expression)
}

/// Evaluates graph-bearing expressions without teaching the ordinary scalar evaluator about graph
/// traversal. Pattern comprehensions use the canonical matcher and are then composed with the
/// existing scalar/list evaluator through statement-owned bindings. Lexical constructs are handled
/// here so their iteration variables exist before a nested graph expression is evaluated.
fn evaluate_correlated_binding_state(
    expression: &Expression,
    row: &Row,
    state: &mut ExecutionState<'_>,
    context: &ExecutionContext<'_>,
) -> Result<BindingValue> {
    if let Some(subquery) = expression.existential_subquery_parts() {
        return evaluate_existential_subquery(row, subquery, state, context);
    }
    if let Some((pattern, predicate, projection)) = expression.pattern_comprehension_parts() {
        return evaluate_pattern_comprehension(
            row, &pattern, predicate, projection, state, context,
        );
    }
    if !needs_correlated_graph_evaluation(expression) {
        return evaluate_binding_state(expression, row, state, context);
    }
    if !contains_pattern_comprehension(expression) && !contains_existential_subquery(expression) {
        if contains_pattern_predicate(expression) {
            let resolved = resolve_pattern_predicates(expression, row, state, context)?;
            return evaluate_binding_state(&resolved, row, state, context);
        }
    }
    match expression {
        Expression::Case {
            operand,
            alternatives,
            default,
        } => evaluate_correlated_case(
            operand.as_deref(),
            alternatives,
            default.as_deref(),
            row,
            state,
            context,
        ),
        Expression::ListComprehension {
            variable,
            list,
            predicate,
            projection,
        } => evaluate_correlated_list_comprehension(
            variable,
            list,
            predicate.as_deref(),
            projection.as_deref(),
            row,
            state,
            context,
        ),
        Expression::Reduce {
            accumulator,
            initial,
            variable,
            list,
            expression,
        } => evaluate_correlated_reduce(
            accumulator,
            initial,
            variable,
            list,
            expression,
            row,
            state,
            context,
        ),
        Expression::ListPredicate {
            kind,
            variable,
            list,
            predicate,
        } => evaluate_correlated_list_predicate(
            *kind, variable, list, predicate, row, state, context,
        ),
        _ => {
            let mut bindings = row.clone();
            let mut next_binding = 0_usize;
            let materialized = materialize_correlated_children(
                expression,
                row,
                &mut bindings,
                &mut next_binding,
                state,
                context,
            )?;
            evaluate_binding_state(&materialized, &bindings, state, context)
        }
    }
}

fn materialize_correlated_child(
    expression: &Expression,
    row: &Row,
    bindings: &mut Row,
    next_binding: &mut usize,
    state: &mut ExecutionState<'_>,
    context: &ExecutionContext<'_>,
) -> Result<Expression> {
    if !needs_correlated_graph_evaluation(expression) {
        return Ok(expression.clone());
    }
    let value = evaluate_correlated_binding_state(expression, row, state, context)?;
    let variable = format!("\0pattern_expression_{}", *next_binding);
    *next_binding = next_binding.saturating_add(1);
    bindings.insert(variable.clone(), value);
    Ok(Expression::Variable(variable))
}

fn materialize_correlated_children(
    expression: &Expression,
    row: &Row,
    bindings: &mut Row,
    next_binding: &mut usize,
    state: &mut ExecutionState<'_>,
    context: &ExecutionContext<'_>,
) -> Result<Expression> {
    let mut child = |expression: &Expression| {
        materialize_correlated_child(expression, row, bindings, next_binding, state, context)
    };
    Ok(match expression {
        Expression::Literal(_)
        | Expression::Parameter(_)
        | Expression::Variable(_)
        | Expression::Star => expression.clone(),
        Expression::ExistentialSubquery(_) => child(expression)?,
        Expression::Property(source, property) => {
            Expression::Property(Box::new(child(source)?), property.clone())
        }
        Expression::List(values) => {
            Expression::List(values.iter().map(&mut child).collect::<Result<_>>()?)
        }
        Expression::Map(values) => Expression::Map(
            values
                .iter()
                .map(|(name, value)| Ok((name.clone(), child(value)?)))
                .collect::<Result<_>>()?,
        ),
        Expression::MapProjection { source, items } => Expression::MapProjection {
            source: Box::new(child(source)?),
            items: items
                .iter()
                .map(|item| {
                    Ok(match item {
                        MapProjectionItem::Entry(name, value) => {
                            MapProjectionItem::Entry(name.clone(), child(value)?)
                        }
                        _ => item.clone(),
                    })
                })
                .collect::<Result<_>>()?,
        },
        Expression::Function {
            name,
            distinct,
            arguments,
        } => Expression::Function {
            name: name.clone(),
            distinct: *distinct,
            arguments: arguments.iter().map(&mut child).collect::<Result<_>>()?,
        },
        Expression::Unary { operation, operand } => Expression::Unary {
            operation: *operation,
            operand: Box::new(child(operand)?),
        },
        Expression::Binary {
            left,
            operation,
            right,
        } => Expression::Binary {
            left: Box::new(child(left)?),
            operation: *operation,
            right: Box::new(child(right)?),
        },
        Expression::IsNull {
            expression,
            negated,
        } => Expression::IsNull {
            expression: Box::new(child(expression)?),
            negated: *negated,
        },
        Expression::Index { expression, index } => Expression::Index {
            expression: Box::new(child(expression)?),
            index: Box::new(child(index)?),
        },
        Expression::Slice {
            expression,
            start,
            end,
        } => Expression::Slice {
            expression: Box::new(child(expression)?),
            start: start
                .as_deref()
                .map(|start| child(start).map(Box::new))
                .transpose()?,
            end: end
                .as_deref()
                .map(|end| child(end).map(Box::new))
                .transpose()?,
        },
        Expression::Case { .. }
        | Expression::ListComprehension { .. }
        | Expression::Reduce { .. }
        | Expression::ListPredicate { .. } => {
            return Err(Error::internal(
                "lexical correlated expression bypassed its stateful evaluator",
            ));
        }
    })
}

fn evaluate_correlated_case(
    operand: Option<&Expression>,
    alternatives: &[CaseAlternative],
    default: Option<&Expression>,
    row: &Row,
    state: &mut ExecutionState<'_>,
    context: &ExecutionContext<'_>,
) -> Result<BindingValue> {
    let operand = operand
        .map(|operand| {
            evaluate_correlated_binding_state(operand, row, state, context)
                .and_then(|value| binding_to_result(&value, &state.graph))
        })
        .transpose()?;
    for alternative in alternatives {
        let when = evaluate_correlated_binding_state(&alternative.when, row, state, context)?;
        let when = binding_to_result(&when, &state.graph)?;
        let selected = match &operand {
            Some(operand) => equal(operand, &when)? == Truth::True,
            None => truth(&when)? == Truth::True,
        };
        if selected {
            return evaluate_correlated_binding_state(&alternative.then, row, state, context);
        }
    }
    default.map_or(Ok(BindingValue::Null), |default| {
        evaluate_correlated_binding_state(default, row, state, context)
    })
}

fn evaluate_correlated_list_comprehension(
    variable: &str,
    list: &Expression,
    predicate: Option<&Expression>,
    projection: Option<&Expression>,
    row: &Row,
    state: &mut ExecutionState<'_>,
    context: &ExecutionContext<'_>,
) -> Result<BindingValue> {
    let list = evaluate_correlated_binding_state(list, row, state, context)?;
    let values = match normalize_untrusted_container(list) {
        BindingValue::List(values) => values,
        value if binding_is_null(&value) => return Ok(BindingValue::Null),
        _ => {
            return Err(Error::new(
                ErrorCode::QueryType,
                "list comprehension input must be a list",
            ));
        }
    };
    let mut output = Vec::with_capacity(values.len());
    for value in values {
        check_execution(context)?;
        let mut nested = row.clone();
        nested.insert(variable.to_owned(), value.clone());
        if let Some(predicate) = predicate {
            let predicate = evaluate_correlated_binding_state(predicate, &nested, state, context)?;
            if truth(&binding_to_result(&predicate, &state.graph)?)? != Truth::True {
                continue;
            }
        }
        output.push(match projection {
            Some(projection) => {
                evaluate_correlated_binding_state(projection, &nested, state, context)?
            }
            None => value,
        });
    }
    Ok(BindingValue::List(output))
}

#[allow(clippy::too_many_arguments)]
fn evaluate_correlated_reduce(
    accumulator: &str,
    initial: &Expression,
    variable: &str,
    list: &Expression,
    expression: &Expression,
    row: &Row,
    state: &mut ExecutionState<'_>,
    context: &ExecutionContext<'_>,
) -> Result<BindingValue> {
    let mut result = evaluate_correlated_binding_state(initial, row, state, context)?;
    let list = evaluate_correlated_binding_state(list, row, state, context)?;
    let values = match normalize_untrusted_container(list) {
        BindingValue::List(values) => values,
        value if binding_is_null(&value) => return Ok(BindingValue::Null),
        _ => {
            return Err(Error::new(
                ErrorCode::QueryType,
                "reduce input must be a list",
            ));
        }
    };
    for value in values {
        check_execution(context)?;
        let mut nested = row.clone();
        nested.insert(accumulator.to_owned(), result);
        nested.insert(variable.to_owned(), value);
        result = evaluate_correlated_binding_state(expression, &nested, state, context)?;
    }
    Ok(result)
}

fn evaluate_correlated_list_predicate(
    kind: ListPredicateKind,
    variable: &str,
    list: &Expression,
    predicate: &Expression,
    row: &Row,
    state: &mut ExecutionState<'_>,
    context: &ExecutionContext<'_>,
) -> Result<BindingValue> {
    let list = evaluate_correlated_binding_state(list, row, state, context)?;
    let values = match normalize_untrusted_container(list) {
        BindingValue::List(values) => values,
        value if binding_is_null(&value) => return Ok(BindingValue::Null),
        _ => {
            return Err(Error::new(
                ErrorCode::QueryType,
                "list predicate input must be a list",
            ));
        }
    };
    let mut true_count = 0_usize;
    let mut false_count = 0_usize;
    let mut unknown_count = 0_usize;
    for value in values {
        check_execution(context)?;
        let mut nested = row.clone();
        nested.insert(variable.to_owned(), value);
        let value = evaluate_correlated_binding_state(predicate, &nested, state, context)?;
        match truth(&binding_to_result(&value, &state.graph)?)? {
            Truth::True => true_count = true_count.saturating_add(1),
            Truth::False => false_count = false_count.saturating_add(1),
            Truth::Unknown => unknown_count = unknown_count.saturating_add(1),
        }
        match kind {
            ListPredicateKind::All if false_count > 0 => {
                return Ok(untrusted_result_binding(boolean(false)));
            }
            ListPredicateKind::Any if true_count > 0 => {
                return Ok(untrusted_result_binding(boolean(true)));
            }
            ListPredicateKind::None if true_count > 0 => {
                return Ok(untrusted_result_binding(boolean(false)));
            }
            ListPredicateKind::Single if true_count > 1 => {
                return Ok(untrusted_result_binding(boolean(false)));
            }
            _ => {}
        }
    }
    let result = match kind {
        ListPredicateKind::All => {
            if unknown_count > 0 {
                Truth::Unknown
            } else {
                Truth::True
            }
        }
        ListPredicateKind::Any => {
            if unknown_count > 0 {
                Truth::Unknown
            } else {
                Truth::False
            }
        }
        ListPredicateKind::None => {
            if unknown_count > 0 {
                Truth::Unknown
            } else {
                Truth::True
            }
        }
        ListPredicateKind::Single => match (true_count, unknown_count) {
            (1, 0) => Truth::True,
            (0 | 1, 1..) => Truth::Unknown,
            _ => Truth::False,
        },
    };
    Ok(untrusted_result_binding(result.into_value()))
}

fn evaluate_existential_subquery(
    row: &Row,
    subquery: &ExistentialSubquery,
    state: &mut ExecutionState<'_>,
    context: &ExecutionContext<'_>,
) -> Result<BindingValue> {
    stacker::maybe_grow(256 * 1024, 2 * 1024 * 1024, || {
        evaluate_existential_subquery_inner(row, subquery, state, context)
    })
}

fn evaluate_existential_subquery_inner(
    row: &Row,
    subquery: &ExistentialSubquery,
    state: &mut ExecutionState<'_>,
    context: &ExecutionContext<'_>,
) -> Result<BindingValue> {
    if context
        .backend
        .is_some_and(|backend| backend.kind() != crate::execution::BackendKind::Cpu)
    {
        return Err(Error::new(
            ErrorCode::GpuAdmissionFailure,
            "existential subquery has no native GPU implementation",
        ));
    }
    check_execution(context)?;
    let prior_depth = state.existential_subquery_depth;
    state.existential_subquery_depth = prior_depth.saturating_add(1);
    let saved_columns = std::mem::take(&mut state.final_columns);
    let saved_scope = state.scope_columns.clone();
    let result = (|| {
        let planned = plan_existential_subquery(subquery, state.existential_subquery_depth)?;
        state.scope_columns = saved_scope.clone();
        let mut rows =
            execute_existential_operator_branch(&planned.operators, row.clone(), state, context)?;
        for (all, branch) in &planned.unions {
            state.scope_columns = saved_scope.clone();
            let branch_rows =
                execute_existential_operator_branch(branch, row.clone(), state, context)?;
            rows.extend(branch_rows);
            if !all {
                deduplicate_rows(&mut rows, &state.graph)?;
            }
        }
        Ok(BindingValue::Value(ResultValue::Scalar(
            ScalarValue::Boolean(!rows.is_empty()),
        )))
    })();
    state.final_columns = saved_columns;
    state.scope_columns = saved_scope;
    state.existential_subquery_depth = prior_depth;
    result
}

fn execute_existential_operator_branch(
    operators: &[PhysicalOperator],
    mut correlated_row: Row,
    state: &mut ExecutionState<'_>,
    context: &ExecutionContext<'_>,
) -> Result<Vec<Row>> {
    // A subquery owns its own MATCH clauses. Its first group may reuse compact group ID zero, so
    // never inherit the outer clause's relationship trail merely because the numeric IDs match.
    correlated_row.reset_match_group();
    let mut rows = vec![correlated_row];
    let mut operator_index = 0_usize;
    while operator_index < operators.len() {
        check_execution(context)?;
        let (next_rows, consumed) =
            apply_operator_sequence_step(operators, operator_index, rows, state, context, None)?;
        rows = next_rows;
        operator_index = operator_index.saturating_add(consumed);
        if consumed == 0 {
            return Err(Error::internal(
                "existential-subquery operator execution made no progress",
            ));
        }
        if rows.len() > context.max_result_rows {
            return Err(Error::new(
                ErrorCode::ResultBudgetExceeded,
                "existential subquery row budget exceeded",
            ));
        }
    }
    check_execution(context)?;
    Ok(rows)
}

fn evaluate_pattern_comprehension(
    row: &Row,
    pattern: &Pattern,
    predicate: Option<&Expression>,
    projection: &Expression,
    state: &mut ExecutionState<'_>,
    context: &ExecutionContext<'_>,
) -> Result<BindingValue> {
    if context
        .backend
        .is_some_and(|backend| backend.kind() != crate::execution::BackendKind::Cpu)
    {
        return Err(Error::new(
            ErrorCode::GpuAdmissionFailure,
            "pattern comprehension has no native GPU implementation",
        ));
    }
    let matches = match_pattern(
        vec![row.clone()],
        pattern,
        &super::ScanAccessPath::Unspecified,
        false,
        false,
        state,
        context,
    )?;
    let mut output = Vec::with_capacity(matches.len());
    for matched in matches {
        check_execution(context)?;
        if let Some(predicate) = predicate {
            let value = evaluate_correlated_binding_state(predicate, &matched, state, context)?;
            if truth(&binding_to_result(&value, &state.graph)?)? != Truth::True {
                continue;
            }
        }
        output.push(evaluate_correlated_binding_state(
            projection, &matched, state, context,
        )?);
    }
    Ok(BindingValue::List(output))
}

/// Resolve every existential pattern leaf to a Boolean for one outer row, then hand the rebuilt
/// expression to the ordinary scalar evaluator. This preserves all existing three-valued Boolean,
/// CASE, list-predicate, and function behavior without treating the graph pattern as a scalar
/// function or leaking any bindings introduced while looking for a witness.
fn resolve_pattern_predicates(
    expression: &Expression,
    row: &Row,
    state: &mut ExecutionState<'_>,
    context: &ExecutionContext<'_>,
) -> Result<Expression> {
    if let Some(pattern) = expression.pattern_predicate_pattern() {
        return Ok(Expression::Literal(ScalarValue::Boolean(
            pattern_predicate_exists(row, &pattern, state, context)?,
        )));
    }
    let resolve = |expression: &Expression, state: &mut ExecutionState<'_>| {
        resolve_pattern_predicates(expression, row, state, context)
    };
    Ok(match expression {
        Expression::Literal(value) => Expression::Literal(value.clone()),
        Expression::Parameter(name) => Expression::Parameter(name.clone()),
        Expression::Variable(name) => Expression::Variable(name.clone()),
        Expression::Property(source, property) => {
            Expression::Property(Box::new(resolve(source, state)?), property.clone())
        }
        Expression::List(values) => Expression::List(
            values
                .iter()
                .map(|value| resolve(value, state))
                .collect::<Result<_>>()?,
        ),
        Expression::Map(values) => Expression::Map(
            values
                .iter()
                .map(|(name, value)| Ok((name.clone(), resolve(value, state)?)))
                .collect::<Result<_>>()?,
        ),
        Expression::MapProjection { source, items } => Expression::MapProjection {
            source: Box::new(resolve(source, state)?),
            items: items
                .iter()
                .map(|item| {
                    Ok(match item {
                        MapProjectionItem::AllProperties => MapProjectionItem::AllProperties,
                        MapProjectionItem::Property(name) => {
                            MapProjectionItem::Property(name.clone())
                        }
                        MapProjectionItem::Variable(name) => {
                            MapProjectionItem::Variable(name.clone())
                        }
                        MapProjectionItem::Entry(name, value) => {
                            MapProjectionItem::Entry(name.clone(), resolve(value, state)?)
                        }
                    })
                })
                .collect::<Result<_>>()?,
        },
        Expression::Case {
            operand,
            alternatives,
            default,
        } => Expression::Case {
            operand: operand
                .as_deref()
                .map(|operand| resolve(operand, state).map(Box::new))
                .transpose()?,
            alternatives: alternatives
                .iter()
                .map(|alternative| {
                    Ok(CaseAlternative {
                        when: resolve(&alternative.when, state)?,
                        then: resolve(&alternative.then, state)?,
                    })
                })
                .collect::<Result<_>>()?,
            default: default
                .as_deref()
                .map(|default| resolve(default, state).map(Box::new))
                .transpose()?,
        },
        Expression::ListComprehension {
            variable,
            list,
            predicate,
            projection,
        } => Expression::ListComprehension {
            variable: variable.clone(),
            list: Box::new(resolve(list, state)?),
            predicate: predicate
                .as_deref()
                .map(|predicate| resolve(predicate, state).map(Box::new))
                .transpose()?,
            projection: projection
                .as_deref()
                .map(|projection| resolve(projection, state).map(Box::new))
                .transpose()?,
        },
        Expression::Reduce {
            accumulator,
            initial,
            variable,
            list,
            expression,
        } => Expression::Reduce {
            accumulator: accumulator.clone(),
            initial: Box::new(resolve(initial, state)?),
            variable: variable.clone(),
            list: Box::new(resolve(list, state)?),
            expression: Box::new(resolve(expression, state)?),
        },
        Expression::ListPredicate {
            kind,
            variable,
            list,
            predicate,
        } => Expression::ListPredicate {
            kind: *kind,
            variable: variable.clone(),
            list: Box::new(resolve(list, state)?),
            predicate: Box::new(resolve(predicate, state)?),
        },
        Expression::Function {
            name,
            distinct,
            arguments,
        } => Expression::Function {
            name: name.clone(),
            distinct: *distinct,
            arguments: arguments
                .iter()
                .map(|argument| resolve(argument, state))
                .collect::<Result<_>>()?,
        },
        Expression::Unary { operation, operand } => Expression::Unary {
            operation: *operation,
            operand: Box::new(resolve(operand, state)?),
        },
        Expression::Binary {
            left,
            operation,
            right,
        } => Expression::Binary {
            left: Box::new(resolve(left, state)?),
            operation: *operation,
            right: Box::new(resolve(right, state)?),
        },
        Expression::IsNull {
            expression,
            negated,
        } => Expression::IsNull {
            expression: Box::new(resolve(expression, state)?),
            negated: *negated,
        },
        Expression::Index { expression, index } => Expression::Index {
            expression: Box::new(resolve(expression, state)?),
            index: Box::new(resolve(index, state)?),
        },
        Expression::Slice {
            expression,
            start,
            end,
        } => Expression::Slice {
            expression: Box::new(resolve(expression, state)?),
            start: start
                .as_deref()
                .map(|start| resolve(start, state).map(Box::new))
                .transpose()?,
            end: end
                .as_deref()
                .map(|end| resolve(end, state).map(Box::new))
                .transpose()?,
        },
        Expression::ExistentialSubquery(_) => expression.clone(),
        Expression::Star => Expression::Star,
    })
}

fn optional_match_where(
    input: Vec<Row>,
    patterns: &[(&Pattern, &super::ScanAccessPath)],
    predicates: &[&Expression],
    state: &mut ExecutionState<'_>,
    context: &ExecutionContext<'_>,
) -> Result<Vec<Row>> {
    let mut output = Vec::new();
    for input_row in input {
        check_execution(context)?;
        let mut matches = vec![input_row.clone()];
        for (pattern, access) in patterns {
            matches = match_pattern(matches, pattern, access, false, true, state, context)?;
            if matches.is_empty() {
                break;
            }
        }
        for predicate in predicates {
            if matches.is_empty() {
                break;
            }
            matches = filter_rows(matches, predicate, state, context)?;
        }
        if matches.is_empty() {
            let mut preserved = input_row;
            for (pattern, _) in patterns {
                bind_pattern_nulls(pattern, &mut preserved);
            }
            output.push(preserved);
        } else {
            output.extend(matches);
        }
    }
    Ok(output)
}

/// Executes a common pushed-down integer predicate against the resident property column. The
/// fallback remains authoritative for expressions, bindings, and property types that cannot be
/// represented by the exact device comparison contract.
fn device_filter_rows(
    rows: &[Row],
    expression: &Expression,
    state: &ExecutionState<'_>,
    context: &ExecutionContext<'_>,
) -> Result<Option<Vec<Row>>> {
    let Some(backend) = current_backend(state, context) else {
        return Ok(None);
    };
    let Expression::Binary {
        left,
        operation,
        right,
    } = expression
    else {
        return Ok(None);
    };
    let direct = property_operand(left, right, *operation, context);
    let reverse = property_operand(right, left, reverse_comparison(*operation), context);
    let Some((variable, property_name, comparison, operand)) = direct.or(reverse) else {
        return Ok(None);
    };
    let Some(property) = state.graph.property(property_name) else {
        return Ok(None);
    };
    if !context.graph.node_property_is_integer(property) {
        return Ok(None);
    }
    if rows.iter().any(|row| {
        !matches!(
            row.get(variable),
            Some(BindingValue::Node(_) | BindingValue::Null) | None
        )
    }) {
        return Ok(None);
    }
    check_execution(context)?;
    let selected = backend
        .filter_node_i64(
            context.project_id,
            property,
            comparison,
            operand,
            &context.cancellation,
        )?
        .into_iter()
        .collect::<BTreeSet<_>>();
    let output = rows
        .iter()
        .filter(|row| {
            matches!(row.get(variable), Some(BindingValue::Node(dense)) if selected.contains(dense))
        })
        .cloned()
        .collect();
    Ok(Some(output))
}

fn property_operand<'a>(
    property: &'a Expression,
    operand: &Expression,
    operation: BinaryOperator,
    context: &ExecutionContext<'_>,
) -> Option<(&'a str, &'a str, CompareOp, i64)> {
    let Expression::Property(source, property_name) = property else {
        return None;
    };
    let Expression::Variable(variable) = source.as_ref() else {
        return None;
    };
    let operand = match operand {
        Expression::Literal(ScalarValue::Integer(value)) => *value,
        Expression::Parameter(name) => match context.parameters.get(name) {
            Some(ResultValue::Scalar(ScalarValue::Integer(value))) => *value,
            _ => return None,
        },
        _ => return None,
    };
    let comparison = match operation {
        BinaryOperator::Equal => CompareOp::Eq,
        BinaryOperator::NotEqual => CompareOp::NotEq,
        BinaryOperator::Less => CompareOp::Less,
        BinaryOperator::LessOrEqual => CompareOp::LessOrEqual,
        BinaryOperator::Greater => CompareOp::Greater,
        BinaryOperator::GreaterOrEqual => CompareOp::GreaterOrEqual,
        _ => return None,
    };
    Some((variable, property_name, comparison, operand))
}

const fn reverse_comparison(operation: BinaryOperator) -> BinaryOperator {
    match operation {
        BinaryOperator::Less => BinaryOperator::Greater,
        BinaryOperator::LessOrEqual => BinaryOperator::GreaterOrEqual,
        BinaryOperator::Greater => BinaryOperator::Less,
        BinaryOperator::GreaterOrEqual => BinaryOperator::LessOrEqual,
        operation => operation,
    }
}

/// Publishes the current statement-local graph overlay into the pinned GPU generation before a
/// later MATCH reads it. The overlay remains private to this execution and is discarded with the
/// pinned backend; canonical publication still happens only after the complete statement commits.
fn refresh_resident_overlay(
    state: &mut ExecutionState<'_>,
    context: &ExecutionContext<'_>,
) -> Result<()> {
    let overlay_mutations = context
        .prior_graph_mutations
        .len()
        .checked_add(state.mutations.len())
        .ok_or_else(|| {
            Error::new(
                ErrorCode::ResultBudgetExceeded,
                "statement-local resident overlay mutation count overflow",
            )
        })?;
    if overlay_mutations == state.resident_overlay_mutations {
        return Ok(());
    }
    let mutations = context
        .prior_graph_mutations
        .iter()
        .chain(state.mutations.iter())
        .cloned()
        .collect::<Vec<_>>();
    let last_device_mutation = mutations
        .iter()
        .enumerate()
        .skip(state.resident_overlay_mutations)
        .filter_map(|(index, mutation)| {
            (!matches!(
                mutation,
                GraphMutation::DeclareLabel { .. }
                    | GraphMutation::DeclareProperty { .. }
                    | GraphMutation::DeclareRelationshipType { .. }
            ))
            .then_some(index)
        })
        .next_back();
    let Some(backend) = state.resident_backend.as_mut() else {
        return Ok(());
    };
    let mut staged = context.graph.clone();
    for (index, mutation) in mutations.into_iter().enumerate() {
        let changes_device_rows = !matches!(
            mutation,
            GraphMutation::DeclareLabel { .. }
                | GraphMutation::DeclareProperty { .. }
                | GraphMutation::DeclareRelationshipType { .. }
        );
        staged.apply(mutation)?;
        if index < state.resident_overlay_mutations || !changes_device_rows {
            continue;
        }
        // A transaction may contain mutations from several prior statement revisions. The graph
        // change journal intentionally retains only one revision, so publishing just the final
        // `device_delta` would omit every earlier inserted or updated row. Replay each new graph
        // mutation into the pinned generation in transaction order. Repeated mutations at one
        // revision are safe: their cumulative delta replaces the same stable dense rows.
        let temporal = if Some(index) == last_device_mutation {
            state
                .temporal_mutations
                .iter()
                .map(|mutation| ResidentTemporalDelta {
                    entity_kind: mutation.entity_kind,
                    target: mutation.target,
                    sample: mutation.sample.clone(),
                })
                .collect()
        } else {
            Vec::new()
        };
        backend.apply_project_overlay(ResidentProjectDelta {
            project: context.project_id,
            bookmark: context.bookmark,
            graph: staged.device_delta(staged.revision())?,
            temporal,
            vectors: Vec::new(),
            invalidate_derived: true,
        })?;
    }
    state.resident_overlay_mutations = overlay_mutations;
    Ok(())
}

fn match_pattern(
    input: Vec<Row>,
    pattern: &Pattern,
    access: &super::ScanAccessPath,
    optional: bool,
    share_match_relationships: bool,
    state: &mut ExecutionState<'_>,
    context: &ExecutionContext<'_>,
) -> Result<Vec<Row>> {
    refresh_resident_overlay(state, context)?;
    let mut output = Vec::new();
    for row in input {
        check_execution(context)?;
        let inherited_relationships = if share_match_relationships {
            row.match_relationships.clone()
        } else {
            BTreeSet::new()
        };
        let starts = start_candidates(&row, &pattern.start, access, true, state, context)?;
        let mut matches = Vec::new();
        for (start, mut candidate) in starts {
            check_execution(context)?;
            let mut path_nodes = vec![start];
            let mut path_relationships = Vec::new();
            let mut used_nodes = BTreeSet::from([start]);
            let mut used_relationships = inherited_relationships.clone();
            match_steps(
                start,
                0,
                &pattern.steps,
                &mut candidate,
                &mut matches,
                &mut path_nodes,
                &mut path_relationships,
                &mut used_nodes,
                &mut used_relationships,
                pattern.mode,
                false,
                state,
                context,
            )?;
        }
        select_paths(&mut matches, pattern.selector, &state.graph)?;
        if matches.is_empty() && optional {
            let mut preserved = row;
            bind_pattern_nulls(pattern, &mut preserved);
            output.push(preserved);
        } else {
            for matched in matches {
                let MatchedPath {
                    mut row,
                    nodes,
                    relationships,
                } = matched;
                if share_match_relationships {
                    row.match_relationships
                        .extend(relationships.iter().copied());
                }
                if let Some(variable) = &pattern.variable {
                    row.insert(
                        variable.clone(),
                        BindingValue::Path {
                            nodes,
                            relationships,
                        },
                    );
                }
                output.push(row);
            }
        }
    }
    Ok(output)
}

/// Evaluates one existential graph pattern against an already-bound outer row. Matching stops at
/// the first witness: an existential predicate never multiplies its input row and must not consume
/// the ordinary result-row budget merely because many paths prove the same Boolean value.
fn pattern_predicate_exists(
    row: &Row,
    pattern: &Pattern,
    state: &mut ExecutionState<'_>,
    context: &ExecutionContext<'_>,
) -> Result<bool> {
    refresh_resident_overlay(state, context)?;
    let starts = start_candidates(
        row,
        &pattern.start,
        &super::ScanAccessPath::Unspecified,
        true,
        state,
        context,
    )?;
    for (start, mut candidate) in starts {
        check_execution(context)?;
        let mut matches = Vec::with_capacity(1);
        let mut path_nodes = vec![start];
        let mut path_relationships = Vec::new();
        let mut used_nodes = BTreeSet::from([start]);
        let mut used_relationships = BTreeSet::new();
        match_steps(
            start,
            0,
            &pattern.steps,
            &mut candidate,
            &mut matches,
            &mut path_nodes,
            &mut path_relationships,
            &mut used_nodes,
            &mut used_relationships,
            pattern.mode,
            true,
            state,
            context,
        )?;
        if !matches.is_empty() {
            return Ok(true);
        }
    }
    Ok(false)
}

fn cyclic_multiway_join(
    input: Vec<Row>,
    patterns: &[(Pattern, super::ScanAccessPath)],
    state: &mut ExecutionState<'_>,
    context: &ExecutionContext<'_>,
) -> Result<Vec<Row>> {
    let mut output = Vec::new();
    for row in input {
        bind_multiway_nodes(patterns, row, state, context, &mut output)?;
        if output.len() > context.max_result_rows {
            return Err(Error::new(
                ErrorCode::ResultBudgetExceeded,
                "cyclic multiway join exceeded the result row budget",
            ));
        }
    }
    Ok(output)
}

fn bind_multiway_nodes(
    patterns: &[(Pattern, super::ScanAccessPath)],
    row: Row,
    state: &mut ExecutionState<'_>,
    context: &ExecutionContext<'_>,
    output: &mut Vec<Row>,
) -> Result<()> {
    check_execution(context)?;
    let mut unbound = BTreeSet::new();
    for (pattern, _) in patterns {
        for variable in pattern
            .start
            .variable
            .iter()
            .chain(pattern.steps[0].node.variable.iter())
        {
            if row.get(variable).is_none() {
                unbound.insert(variable.clone());
            }
        }
    }
    if unbound.is_empty() {
        let mut rows = vec![row];
        for (pattern, access) in patterns {
            rows = match_pattern(rows, pattern, access, false, true, state, context)?;
            if rows.is_empty() {
                break;
            }
        }
        output.extend(rows);
        return Ok(());
    }

    let mut best = None::<(usize, String, Vec<u32>)>;
    for variable in unbound {
        let candidates = multiway_node_candidates(&variable, patterns, &row, state, context)?;
        let candidate = (candidates.len(), variable, candidates);
        if best
            .as_ref()
            .is_none_or(|current| (&candidate.0, &candidate.1) < (&current.0, &current.1))
        {
            best = Some(candidate);
        }
    }
    let Some((_, variable, candidates)) = best else {
        return Ok(());
    };
    for dense in candidates {
        check_execution(context)?;
        let mut next = row.clone();
        next.insert(variable.clone(), BindingValue::Node(dense));
        bind_multiway_nodes(patterns, next, state, context, output)?;
        if output.len() > context.max_result_rows {
            break;
        }
    }
    Ok(())
}

fn multiway_node_candidates(
    variable: &str,
    patterns: &[(Pattern, super::ScanAccessPath)],
    row: &Row,
    state: &mut ExecutionState<'_>,
    context: &ExecutionContext<'_>,
) -> Result<Vec<u32>> {
    let mut sets = Vec::new();
    for (pattern, access) in patterns {
        let step = &pattern.steps[0];
        if pattern.start.variable.as_deref() == Some(variable) {
            sets.push(
                start_candidates(row, &pattern.start, access, false, state, context)?
                    .into_iter()
                    .map(|(dense, _)| dense)
                    .collect(),
            );
            if let Some(neighbor) = bound_node(row, step.node.variable.as_deref())? {
                sets.push(adjacency_candidates(
                    neighbor, step, true, row, state, context,
                )?);
            }
        }
        if step.node.variable.as_deref() == Some(variable) {
            sets.push(
                start_candidates(
                    row,
                    &step.node,
                    &super::ScanAccessPath::Unspecified,
                    false,
                    state,
                    context,
                )?
                .into_iter()
                .map(|(dense, _)| dense)
                .collect(),
            );
            if let Some(neighbor) = bound_node(row, pattern.start.variable.as_deref())? {
                sets.push(adjacency_candidates(
                    neighbor, step, false, row, state, context,
                )?);
            }
        }
    }
    if sets.is_empty() {
        return Ok(Vec::new());
    }
    for set in &mut sets {
        set.sort_unstable();
        set.dedup();
    }
    if sets.len() == 1 {
        return Ok(sets.pop().unwrap_or_default());
    }
    if let Some(backend) = current_backend(state, context) {
        return backend.intersect_sorted_node_sets(
            &ResidentMultiwayIntersectionRequest {
                project: context.project_id,
                sorted_sets: sets,
                max_output_rows: context.max_result_rows,
            },
            &context.cancellation,
        );
    }
    Ok(intersect_sorted_node_sets(sets))
}

fn bound_node(row: &Row, variable: Option<&str>) -> Result<Option<u32>> {
    let Some(variable) = variable else {
        return Ok(None);
    };
    match row.get(variable) {
        Some(BindingValue::Node(dense)) => Ok(Some(*dense)),
        Some(binding) if binding_is_null(binding) => Ok(None),
        None => Ok(None),
        Some(_) => Err(Error::new(
            ErrorCode::QueryType,
            "cyclic join node variable has a non-node value",
        )),
    }
}

fn adjacency_candidates(
    bound: u32,
    step: &PatternStep,
    reverse: bool,
    row: &Row,
    state: &ExecutionState<'_>,
    context: &ExecutionContext<'_>,
) -> Result<Vec<u32>> {
    let mut step = step.clone();
    if reverse {
        step.relationship.direction = match step.relationship.direction {
            Direction::Outgoing => Direction::Incoming,
            Direction::Incoming => Direction::Outgoing,
            Direction::Undirected => Direction::Undirected,
        };
    }
    let types = step
        .relationship
        .types
        .iter()
        .filter_map(|name| state.graph.relationship_type(name))
        .collect::<Vec<_>>();
    if !step.relationship.types.is_empty() && types.is_empty() {
        return Ok(Vec::new());
    }
    let mut candidates = Vec::new();
    for (edge, node) in expand_relationship(bound, &step, state, context)? {
        let Some(edge_view) = state.graph.edge_dense(edge) else {
            continue;
        };
        if (!types.is_empty() && !types.contains(&edge_view.relationship_type()))
            || !relationship_properties_match(edge, &step, row, state, context)?
        {
            continue;
        }
        candidates.push(node);
    }
    Ok(candidates)
}

fn intersect_sorted_node_sets(mut sets: Vec<Vec<u32>>) -> Vec<u32> {
    sets.sort_by_key(Vec::len);
    let mut sets = sets.into_iter();
    let mut intersection = sets.next().unwrap_or_default();
    for candidate in sets {
        let mut next = Vec::with_capacity(intersection.len().min(candidate.len()));
        let (mut left, mut right) = (0, 0);
        while left < intersection.len() && right < candidate.len() {
            match intersection[left].cmp(&candidate[right]) {
                Ordering::Less => left += 1,
                Ordering::Greater => right += 1,
                Ordering::Equal => {
                    next.push(intersection[left]);
                    left += 1;
                    right += 1;
                }
            }
        }
        intersection = next;
        if intersection.is_empty() {
            break;
        }
    }
    intersection
}

#[derive(Clone)]
struct MatchedPath {
    row: Row,
    nodes: Vec<u32>,
    relationships: Vec<u32>,
}

fn start_candidates(
    row: &Row,
    pattern: &NodePattern,
    access: &super::ScanAccessPath,
    record_dependencies: bool,
    state: &mut ExecutionState<'_>,
    context: &ExecutionContext<'_>,
) -> Result<Vec<(u32, Row)>> {
    if let Some(variable) = &pattern.variable {
        if let Some(value) = row.get(variable) {
            return match value {
                BindingValue::Node(dense)
                    if node_matches(*dense, pattern, row, state, context)? =>
                {
                    Ok(vec![(*dense, row.clone())])
                }
                BindingValue::Node(_) => Ok(Vec::new()),
                binding if binding_is_null(binding) => Ok(Vec::new()),
                _ => Err(Error::new(
                    ErrorCode::QueryType,
                    "node pattern variable has a non-node value",
                )),
            };
        }
    }
    let labels: Option<Vec<LabelId>> = pattern
        .labels
        .iter()
        .map(|name| state.graph.label(name))
        .collect();
    let Some(labels) = labels else {
        return Ok(Vec::new());
    };
    let first_label = match access {
        super::ScanAccessPath::Label { label } => state.graph.label(label),
        _ => labels.first().copied(),
    };
    let backend = current_backend(state, context);
    let stable_id = match access {
        super::ScanAccessPath::StableId { value, .. } => {
            match evaluate_state(value, row, state, context)? {
                ResultValue::Scalar(ScalarValue::Integer(value)) if value >= 0 => state
                    .graph
                    .node(NodeId(value as u64))
                    .map(|node| vec![node.dense()]),
                ResultValue::Scalar(ScalarValue::Null) => Some(Vec::new()),
                _ => None,
            }
        }
        _ => None,
    };
    let indexed = if stable_id.is_some() {
        stable_id
    } else {
        host_index_candidates(row, pattern, &labels, access, state, context)?
    };
    let used_scalar_index = indexed.is_some();
    let mut candidates: Vec<_> = match indexed {
        Some(candidates) => candidates,
        None => {
            if let Some(cap) = state.initial_scan_cap {
                // Bare limited scan (no filter/sort/aggregate/distinct): stop after `s + k` nodes
                // even when a resident backend is present. `backend.scan_nodes` returns the whole
                // label from the resident image, so honoring the cap here is what turns an
                // O(label) scan into O(s + k) for `MATCH (n[:Label]) RETURN … LIMIT k`.
                state
                    .graph
                    .scan_node_denses_bounded(first_label, state.read_layers, cap)
            } else if let Some(backend) = backend {
                backend.scan_nodes(
                    context.project_id,
                    first_label,
                    state.read_layers,
                    &context.cancellation,
                )?
            } else {
                state.graph.scan_node_denses(first_label, state.read_layers)
            }
        }
    };
    if !used_scalar_index && let Some(backend) = backend {
        let resident_predicate = match access {
            super::ScanAccessPath::ResidentProperty {
                property,
                operation,
                value,
                ..
            } => state.graph.property(property).and_then(|property| {
                let ResultValue::Scalar(ScalarValue::Integer(operand)) =
                    evaluate_state(value, row, state, context).ok()?
                else {
                    return None;
                };
                Some((property, binary_compare_op(*operation)?, operand))
            }),
            _ => None,
        };
        let property_predicate = resident_predicate.or_else(|| {
            pattern.properties.iter().find_map(|(name, expression)| {
                let property = state.graph.property(name)?;
                let ResultValue::Scalar(ScalarValue::Integer(operand)) =
                    evaluate_state(expression, row, state, context).ok()?
                else {
                    return None;
                };
                Some((property, CompareOp::Eq, operand))
            })
        });
        if let Some((property, operation, operand)) = property_predicate {
            let selected = backend.filter_node_i64(
                context.project_id,
                property,
                operation,
                operand,
                &context.cancellation,
            )?;
            let selected = selected.into_iter().collect::<BTreeSet<_>>();
            candidates.retain(|row| selected.contains(row));
        }
    }
    let mut result = Vec::new();
    for dense in candidates {
        check_execution(context)?;
        if node_matches(dense, pattern, row, state, context)? {
            let node = state
                .graph
                .node_dense(dense)
                .ok_or_else(|| Error::internal("scan returned deleted node"))?;
            if record_dependencies && let Some(base) = context.graph.node(node.id()) {
                state
                    .dependencies
                    .entities
                    .insert(EntityDependency::Node(node.id()), base.revision());
            }
            let mut next = row.clone();
            if let Some(variable) = &pattern.variable {
                next.insert(variable.clone(), BindingValue::Node(dense));
            }
            result.push((dense, next));
        }
    }
    Ok(result)
}

fn host_index_candidates(
    row: &Row,
    pattern: &NodePattern,
    labels: &[LabelId],
    access: &super::ScanAccessPath,
    state: &ExecutionState<'_>,
    context: &ExecutionContext<'_>,
) -> Result<Option<Vec<u32>>> {
    // Prior-transaction mutations are not reflected in this view's node overlay, so a full scan is
    // still required when they are present. Same-statement node mutations ARE captured by the overlay
    // (`self.nodes`) and are unioned into the candidates below, so they no longer force a full scan.
    // The scan itself runs entirely on the host view (`state.graph`, `node_matches`, `node_dense`),
    // so a Metal backend no longer precludes the host index — under Apple unified memory the host
    // store is the same physical memory the device reads. This is the fix that lets a correlated
    // index join (e.g. `UNWIND ... MATCH (n:L {k: rowvalue}) ...`, the bulk edge-load pattern) use
    // the equality index per row instead of scanning every node for every row.
    if !context.prior_graph_mutations.is_empty() || !context.prior_temporal_mutations.is_empty() {
        return Ok(None);
    }
    let Some(indexes) = context.scalar_indexes else {
        return Ok(None);
    };
    let mut values = BTreeMap::new();
    for (name, expression) in &pattern.properties {
        let Some(property) = state.graph.property(name) else {
            return Ok(Some(Vec::new()));
        };
        let ResultValue::Scalar(value) = evaluate_state(expression, row, state, context)? else {
            return Ok(None);
        };
        values.insert(property, value);
    }
    if let super::ScanAccessPath::EqualityIndex {
        values: indexed_values,
        ..
    } = access
    {
        for (name, expression) in indexed_values {
            let Some(property) = state.graph.property(name) else {
                return Ok(Some(Vec::new()));
            };
            let ResultValue::Scalar(value) = evaluate_state(expression, row, state, context)?
            else {
                return Ok(None);
            };
            values.insert(property, value);
        }
    }
    if values.is_empty() {
        return Ok(None);
    }
    let base_candidates = if let super::ScanAccessPath::EqualityIndex { name, label, .. } = access
        && let Some(label) = state.graph.label(label)
        && let Some(candidate) = indexes.equality_candidates_named(name, label, &values)?
    {
        Some(candidate)
    } else {
        let mut best = None::<Vec<u32>>;
        for label in labels {
            if let Some(candidate) = indexes.equality_candidates(*label, &values)?
                && best
                    .as_ref()
                    .is_none_or(|current| candidate.len() < current.len())
            {
                best = Some(candidate);
            }
        }
        best
    };
    let Some(mut candidates) = base_candidates else {
        return Ok(None);
    };
    // The base index only covers committed rows. Union any node the overlay modified this statement
    // (inserts/updates/relabels) so they are not missed; the caller re-checks each candidate with
    // node_matches, so stale or non-matching entries — including overlay-deleted base rows — are
    // filtered. During a pure edge-load `self.nodes` is empty, so this union is O(0).
    if state.graph.has_overlay_node_modifications() {
        let existing: BTreeSet<u32> = candidates.iter().copied().collect();
        for dense in state.graph.overlay_modified_node_denses() {
            if !existing.contains(&dense) {
                candidates.push(dense);
            }
        }
    }
    Ok(Some(candidates))
}

const fn binary_compare_op(operation: BinaryOperator) -> Option<CompareOp> {
    match operation {
        BinaryOperator::Equal => Some(CompareOp::Eq),
        BinaryOperator::NotEqual => Some(CompareOp::NotEq),
        BinaryOperator::Less => Some(CompareOp::Less),
        BinaryOperator::LessOrEqual => Some(CompareOp::LessOrEqual),
        BinaryOperator::Greater => Some(CompareOp::Greater),
        BinaryOperator::GreaterOrEqual => Some(CompareOp::GreaterOrEqual),
        _ => None,
    }
}

fn node_matches(
    dense: u32,
    pattern: &NodePattern,
    row: &Row,
    state: &ExecutionState<'_>,
    context: &ExecutionContext<'_>,
) -> Result<bool> {
    let Some(node) = state.graph.node_dense(dense) else {
        return Ok(false);
    };
    if !state.read_layers.contains_layer(node.layer()) {
        return Ok(false);
    }
    for label in &pattern.labels {
        let Some(label) = state.graph.label(label) else {
            return Ok(false);
        };
        if !node.labels().contains(&label) {
            return Ok(false);
        }
    }
    for (name, expression) in &pattern.properties {
        let Some(property) = state.graph.property(name) else {
            return Ok(false);
        };
        let expected = evaluate_state(expression, row, state, context)?;
        let actual =
            ResultValue::from_property(node.property(property).unwrap_or(ScalarValue::Null))?;
        if equal(&actual, &expected)? != Truth::True {
            return Ok(false);
        }
    }
    Ok(true)
}

fn match_steps(
    current: u32,
    index: usize,
    steps: &[PatternStep],
    row: &mut Row,
    output: &mut Vec<MatchedPath>,
    path_nodes: &mut Vec<u32>,
    path_relationships: &mut Vec<u32>,
    used_nodes: &mut BTreeSet<u32>,
    used_relationships: &mut BTreeSet<u32>,
    mode: PathMode,
    stop_after_first: bool,
    state: &mut ExecutionState<'_>,
    context: &ExecutionContext<'_>,
) -> Result<()> {
    check_execution(context)?;
    if stop_after_first && !output.is_empty() {
        return Ok(());
    }
    let Some(step) = steps.get(index) else {
        if output.len() >= context.max_result_rows {
            return Err(Error::new(
                ErrorCode::ResultBudgetExceeded,
                "path match exceeded the result row budget",
            ));
        }
        output.push(MatchedPath {
            row: row.clone(),
            nodes: path_nodes.clone(),
            relationships: path_relationships.clone(),
        });
        return Ok(());
    };
    let (minimum, maximum) = if step.relationship.variable_length {
        let minimum = step.relationship.min_hops.unwrap_or(1) as usize;
        let maximum = match step.relationship.max_hops {
            Some(maximum) => maximum as usize,
            None => match mode {
                PathMode::DifferentRelationships => state.graph.edge_count(),
                PathMode::Acyclic => state.graph.node_count().saturating_sub(1),
                PathMode::RepeatableElements => {
                    return Err(Error::new(
                        ErrorCode::QueryType,
                        "unbounded paths require a non-repeatable match mode",
                    ));
                }
            },
        };
        (minimum, maximum)
    } else {
        (1, 1)
    };
    if maximum < minimum {
        // openCypher defines a reversed hop interval as an empty expansion, not an invalid query.
        return Ok(());
    }
    let types = step
        .relationship
        .types
        .iter()
        .filter_map(|name| state.graph.relationship_type(name))
        .collect::<Vec<_>>();
    if !step.relationship.types.is_empty() && types.is_empty() {
        return Ok(());
    }
    let mut step_relationships = Vec::with_capacity(maximum.min(64));
    walk_relationship(
        current,
        0,
        minimum,
        maximum,
        index,
        step,
        &types,
        steps,
        row,
        output,
        path_nodes,
        path_relationships,
        &mut step_relationships,
        used_nodes,
        used_relationships,
        mode,
        stop_after_first,
        state,
        context,
    )
}

#[allow(clippy::too_many_arguments)]
fn walk_relationship(
    current: u32,
    hops: usize,
    minimum: usize,
    maximum: usize,
    step_index: usize,
    step: &PatternStep,
    types: &[RelationshipTypeId],
    steps: &[PatternStep],
    row: &Row,
    output: &mut Vec<MatchedPath>,
    path_nodes: &mut Vec<u32>,
    path_relationships: &mut Vec<u32>,
    step_relationships: &mut Vec<u32>,
    used_nodes: &mut BTreeSet<u32>,
    used_relationships: &mut BTreeSet<u32>,
    mode: PathMode,
    stop_after_first: bool,
    state: &mut ExecutionState<'_>,
    context: &ExecutionContext<'_>,
) -> Result<()> {
    check_execution(context)?;
    if stop_after_first && !output.is_empty() {
        return Ok(());
    }
    if hops >= minimum {
        let mut candidate = row.clone();
        let mut candidate_compatible = true;
        if let Some(variable) = &step.relationship.variable {
            let binding = if step.relationship.variable_length {
                BindingValue::List(
                    step_relationships
                        .iter()
                        .copied()
                        .map(BindingValue::Relationship)
                        .collect(),
                )
            } else {
                let Some(dense) = step_relationships.first().copied() else {
                    return Err(Error::internal("fixed relationship path has no edge"));
                };
                BindingValue::Relationship(dense)
            };
            if !binding_compatible(candidate.get(variable), binding.clone()) {
                candidate_compatible = false;
            } else {
                candidate.insert(variable.clone(), binding);
            }
        }
        if let Some(variable) = &step.node.variable {
            let binding = BindingValue::Node(current);
            if !binding_compatible(candidate.get(variable), binding.clone()) {
                candidate_compatible = false;
            } else {
                candidate.insert(variable.clone(), binding);
            }
        }
        if candidate_compatible && node_matches(current, &step.node, &candidate, state, context)? {
            if let Some(node) = state.graph.node_dense(current)
                && let Some(base) = context.graph.node(node.id())
            {
                state
                    .dependencies
                    .entities
                    .insert(EntityDependency::Node(node.id()), base.revision());
            }
            match_steps(
                current,
                step_index.saturating_add(1),
                steps,
                &mut candidate,
                output,
                path_nodes,
                path_relationships,
                used_nodes,
                used_relationships,
                mode,
                stop_after_first,
                state,
                context,
            )?;
            if stop_after_first && !output.is_empty() {
                return Ok(());
            }
        }
    }
    if hops == maximum {
        return Ok(());
    }
    let expanded = expand_relationship(current, step, state, context)?;
    for (edge_dense, node_dense) in expanded {
        check_execution(context)?;
        let (edge_type, edge_id, node_id) = {
            let (Some(edge), Some(node)) = (
                state.graph.edge_dense(edge_dense),
                state.graph.node_dense(node_dense),
            ) else {
                continue;
            };
            (edge.relationship_type(), edge.id(), node.id())
        };
        if !types.is_empty() && !types.contains(&edge_type) {
            continue;
        }
        if mode == PathMode::DifferentRelationships && used_relationships.contains(&edge_dense) {
            continue;
        }
        if mode == PathMode::Acyclic && used_nodes.contains(&node_dense) {
            continue;
        }
        if !relationship_properties_match(edge_dense, step, row, state, context)? {
            continue;
        }
        let inserted_edge = used_relationships.insert(edge_dense);
        let inserted_node = used_nodes.insert(node_dense);
        path_relationships.push(edge_dense);
        path_nodes.push(node_dense);
        step_relationships.push(edge_dense);
        if let Some(base) = context.graph.node(node_id) {
            state
                .dependencies
                .entities
                .insert(EntityDependency::Node(node_id), base.revision());
        }
        if let Some(base) = context.graph.edge(edge_id) {
            state
                .dependencies
                .entities
                .insert(EntityDependency::Relationship(edge_id), base.revision());
        }
        walk_relationship(
            node_dense,
            hops.saturating_add(1),
            minimum,
            maximum,
            step_index,
            step,
            types,
            steps,
            row,
            output,
            path_nodes,
            path_relationships,
            step_relationships,
            used_nodes,
            used_relationships,
            mode,
            stop_after_first,
            state,
            context,
        )?;
        step_relationships.pop();
        path_nodes.pop();
        path_relationships.pop();
        if inserted_node {
            used_nodes.remove(&node_dense);
        }
        if inserted_edge {
            used_relationships.remove(&edge_dense);
        }
        if stop_after_first && !output.is_empty() {
            return Ok(());
        }
    }
    Ok(())
}

fn expand_relationship(
    current: u32,
    step: &PatternStep,
    state: &ExecutionState<'_>,
    context: &ExecutionContext<'_>,
) -> Result<Vec<(u32, u32)>> {
    let current_node = state
        .graph
        .node_dense(current)
        .ok_or_else(|| Error::internal("pattern node disappeared"))?;
    let mut expanded: Vec<(u32, u32)> = Vec::new();
    if matches!(
        step.relationship.direction,
        Direction::Outgoing | Direction::Undirected
    ) {
        if let Some(backend) = current_backend(state, context) {
            expanded.extend(
                backend
                    .expand_project_out(context.project_id, &[current], &context.cancellation)?
                    .into_iter()
                    .filter_map(|(_, target, edge)| {
                        let edge_view = state.graph.edge_dense(edge)?;
                        let node_view = state.graph.node_dense(target)?;
                        (state.read_layers.contains_layer(edge_view.layer())
                            && state.read_layers.contains_layer(node_view.layer()))
                        .then_some((edge, target))
                    }),
            );
        } else {
            expanded.extend(
                state
                    .graph
                    .expand_out(current_node.id(), None, state.read_layers)?
                    .into_iter()
                    .map(|(edge, node)| (edge.dense(), node.dense())),
            );
        }
    }
    if matches!(
        step.relationship.direction,
        Direction::Incoming | Direction::Undirected
    ) {
        if let Some(backend) = current_backend(state, context) {
            expanded.extend(
                backend
                    .expand_project_in(context.project_id, &[current], &context.cancellation)?
                    .into_iter()
                    .filter_map(|(source, _, edge)| {
                        let edge_view = state.graph.edge_dense(edge)?;
                        let node_view = state.graph.node_dense(source)?;
                        (state.read_layers.contains_layer(edge_view.layer())
                            && state.read_layers.contains_layer(node_view.layer()))
                        .then_some((edge, source))
                    }),
            );
        } else {
            expanded.extend(
                state
                    .graph
                    .expand_in(current_node.id(), None, state.read_layers)?
                    .into_iter()
                    .map(|(edge, node)| (edge.dense(), node.dense())),
            );
        }
    }
    expanded.sort_unstable();
    expanded.dedup();
    Ok(expanded)
}

fn relationship_properties_match(
    edge_dense: u32,
    step: &PatternStep,
    row: &Row,
    state: &ExecutionState<'_>,
    context: &ExecutionContext<'_>,
) -> Result<bool> {
    for (name, expression) in &step.relationship.properties {
        let Some(property) = state.graph.property(name) else {
            return Ok(false);
        };
        let expected = evaluate_state(expression, row, state, context)?;
        let actual = ResultValue::from_property(
            state
                .graph
                .edge_dense(edge_dense)
                .and_then(|edge| edge.property(property))
                .unwrap_or(ScalarValue::Null),
        )?;
        if equal(&actual, &expected)? != Truth::True {
            return Ok(false);
        }
    }
    Ok(true)
}

fn select_paths(
    paths: &mut Vec<MatchedPath>,
    selector: PathSelector,
    graph: &GraphReadView<'_>,
) -> Result<()> {
    paths.sort_by(|left, right| path_order(left, right, graph));
    if selector == PathSelector::All {
        return Ok(());
    }
    let mut by_endpoints: BTreeMap<(u64, u64), Vec<MatchedPath>> = BTreeMap::new();
    for path in paths.drain(..) {
        let start = path
            .nodes
            .first()
            .and_then(|dense| graph.node_dense(*dense))
            .ok_or_else(|| Error::internal("matched path start disappeared"))?
            .id()
            .0;
        let end = path
            .nodes
            .last()
            .and_then(|dense| graph.node_dense(*dense))
            .ok_or_else(|| Error::internal("matched path end disappeared"))?
            .id()
            .0;
        by_endpoints.entry((start, end)).or_default().push(path);
    }
    let mut selected = Vec::new();
    for mut group in by_endpoints.into_values() {
        group.sort_by(|left, right| path_order(left, right, graph));
        match selector {
            PathSelector::All => selected.extend(group),
            PathSelector::Any | PathSelector::AnyShortest => {
                if let Some(path) = group.into_iter().next() {
                    selected.push(path);
                }
            }
            PathSelector::AllShortest => {
                let minimum = group
                    .first()
                    .map(|path| path.relationships.len())
                    .unwrap_or(0);
                selected.extend(
                    group
                        .into_iter()
                        .take_while(|path| path.relationships.len() == minimum),
                );
            }
            PathSelector::Shortest { count, groups } => {
                let count = usize::try_from(count).unwrap_or(usize::MAX);
                if groups {
                    let mut lengths = BTreeSet::new();
                    for path in group {
                        let length = path.relationships.len();
                        if !lengths.contains(&length) && lengths.len() == count {
                            break;
                        }
                        lengths.insert(length);
                        selected.push(path);
                    }
                } else {
                    selected.extend(group.into_iter().take(count));
                }
            }
        }
    }
    selected.sort_by(|left, right| path_order(left, right, graph));
    *paths = selected;
    Ok(())
}

fn path_order(left: &MatchedPath, right: &MatchedPath, graph: &GraphReadView<'_>) -> Ordering {
    let node_ids = |path: &MatchedPath| {
        path.nodes
            .iter()
            .map(|dense| {
                graph
                    .node_dense(*dense)
                    .map(|node| node.id().0)
                    .unwrap_or(u64::MAX)
            })
            .collect::<Vec<_>>()
    };
    let edge_ids = |path: &MatchedPath| {
        path.relationships
            .iter()
            .map(|dense| {
                graph
                    .edge_dense(*dense)
                    .map(|edge| edge.id().0)
                    .unwrap_or(u64::MAX)
            })
            .collect::<Vec<_>>()
    };
    left.relationships
        .len()
        .cmp(&right.relationships.len())
        .then_with(|| node_ids(left).cmp(&node_ids(right)))
        .then_with(|| edge_ids(left).cmp(&edge_ids(right)))
}

fn binding_compatible(existing: Option<&BindingValue>, candidate: BindingValue) -> bool {
    existing.is_none_or(|existing| existing == &candidate)
}

fn bind_pattern_nulls(pattern: &Pattern, row: &mut Row) {
    if let Some(variable) = &pattern.variable {
        row.insert_if_absent(variable.clone(), BindingValue::Null);
    }
    if let Some(variable) = &pattern.start.variable {
        row.insert_if_absent(variable.clone(), BindingValue::Null);
    }
    for step in &pattern.steps {
        if let Some(variable) = &step.relationship.variable {
            row.insert_if_absent(variable.clone(), BindingValue::Null);
        }
        if let Some(variable) = &step.node.variable {
            row.insert_if_absent(variable.clone(), BindingValue::Null);
        }
    }
}

fn extend_pattern_scope(scope: &mut BTreeSet<String>, pattern: &Pattern) {
    scope.extend(pattern.variable.iter().cloned());
    scope.extend(pattern.start.variable.iter().cloned());
    for step in &pattern.steps {
        scope.extend(step.relationship.variable.iter().cloned());
        scope.extend(step.node.variable.iter().cloned());
    }
}

fn create_pattern(
    rows: Vec<Row>,
    pattern: &Pattern,
    state: &mut ExecutionState<'_>,
    context: &ExecutionContext<'_>,
) -> Result<Vec<Row>> {
    let mut output = Vec::new();
    for mut row in rows {
        let mut current = create_or_reuse_node(&pattern.start, &mut row, state, context)?;
        let mut path_nodes = vec![current];
        let mut path_relationships = Vec::with_capacity(pattern.steps.len());
        for step in &pattern.steps {
            let target = create_or_reuse_node(&step.node, &mut row, state, context)?;
            if step.relationship.variable_length {
                return Err(Error::new(
                    ErrorCode::QueryType,
                    "CREATE relationship length must be one",
                ));
            }
            let relationship_name = step.relationship.types.first().ok_or_else(|| {
                Error::new(
                    ErrorCode::QueryType,
                    "CREATE relationship requires exactly one type",
                )
            })?;
            if step.relationship.types.len() != 1 {
                return Err(Error::new(
                    ErrorCode::QueryType,
                    "CREATE relationship requires exactly one type",
                ));
            }
            let relationship_type = intern_relationship_type(relationship_name, state)?;
            let properties =
                evaluate_properties(&step.relationship.properties, &row, state, context)?;
            validate_edge_properties(context.graph, &properties)?;
            let (source, destination) = if step.relationship.direction == Direction::Incoming {
                (target, current)
            } else {
                (current, target)
            };
            let id = allocate_edge_id(state)?;
            apply_mutation(
                state,
                GraphMutation::InsertEdge(EdgeInput {
                    id,
                    source: state
                        .graph
                        .node_dense(source)
                        .ok_or_else(|| Error::internal("created source missing"))?
                        .id(),
                    target: state
                        .graph
                        .node_dense(destination)
                        .ok_or_else(|| Error::internal("created target missing"))?
                        .id(),
                    relationship_type,
                    layer: state.write_layer,
                    revision: state.revision,
                    properties,
                }),
            )?;
            let dense = state
                .graph
                .edge(id)
                .ok_or_else(|| Error::internal("created relationship missing"))?
                .dense();
            if let Some(variable) = &step.relationship.variable {
                row.insert(variable.clone(), BindingValue::Relationship(dense));
            }
            path_relationships.push(dense);
            path_nodes.push(target);
            state.stats.relationships_created = state.stats.relationships_created.saturating_add(1);
            current = target;
        }
        if let Some(variable) = &pattern.variable {
            row.insert(
                variable.clone(),
                BindingValue::Path {
                    nodes: path_nodes,
                    relationships: path_relationships,
                },
            );
        }
        output.push(row);
    }
    Ok(output)
}

/// Evaluates one MERGE row's pattern properties exactly once before either the match or create
/// branch can run. Cypher does not permit a null property value in a MERGE pattern: treating it as
/// a failed match would incorrectly create an entity with the property silently removed. Literal
/// replacement also prevents volatile expressions from producing one value while matching and a
/// different value while creating.
fn evaluate_merge_pattern_properties(
    pattern: &Pattern,
    row: &Row,
    state: &ExecutionState<'_>,
    context: &ExecutionContext<'_>,
) -> Result<Pattern> {
    let mut evaluated = pattern.clone();
    evaluate_merge_property_entries(&mut evaluated.start.properties, row, state, context)?;
    for step in &mut evaluated.steps {
        evaluate_merge_property_entries(&mut step.relationship.properties, row, state, context)?;
        evaluate_merge_property_entries(&mut step.node.properties, row, state, context)?;
    }
    Ok(evaluated)
}

fn evaluate_merge_property_entries(
    entries: &mut [(String, Expression)],
    row: &Row,
    state: &ExecutionState<'_>,
    context: &ExecutionContext<'_>,
) -> Result<()> {
    for (name, expression) in entries {
        let value = scalar(evaluate_state(expression, row, state, context)?)?;
        if matches!(value, ScalarValue::Null) {
            return Err(merge_null_property_error(name));
        }
        *expression = Expression::Literal(value);
    }
    Ok(())
}

fn merge_null_property_error(name: &str) -> Error {
    Error::new(
        ErrorCode::QueryType,
        format!("MergeReadOwnWrites: MERGE property `{name}` evaluated to null"),
    )
}

fn create_or_reuse_node(
    pattern: &NodePattern,
    row: &mut Row,
    state: &mut ExecutionState<'_>,
    context: &ExecutionContext<'_>,
) -> Result<u32> {
    if let Some(variable) = &pattern.variable {
        if let Some(binding) = row.get(variable) {
            return match binding {
                BindingValue::Node(dense) => Ok(*dense),
                _ => Err(Error::new(
                    ErrorCode::QueryType,
                    "CREATE variable is already bound to a non-node",
                )),
            };
        }
    }
    let labels = pattern
        .labels
        .iter()
        .map(|name| intern_label(name, state))
        .collect::<Result<Vec<_>>>()?;
    let properties = evaluate_properties(&pattern.properties, row, state, context)?;
    validate_node_properties(context.graph, &properties)?;
    let id = allocate_node_id(state)?;
    apply_mutation(
        state,
        GraphMutation::InsertNode(NodeInput {
            id,
            layer: state.write_layer,
            revision: state.revision,
            labels,
            properties,
        }),
    )?;
    let dense = state
        .graph
        .node(id)
        .ok_or_else(|| Error::internal("created node missing"))?
        .dense();
    if let Some(variable) = &pattern.variable {
        row.insert(variable.clone(), BindingValue::Node(dense));
    }
    state.stats.nodes_created = state.stats.nodes_created.saturating_add(1);
    state.stats.labels_added = state
        .stats
        .labels_added
        .saturating_add(pattern.labels.len() as u64);
    Ok(dense)
}

fn set_items(
    rows: Vec<Row>,
    items: &[SetItem],
    state: &mut ExecutionState<'_>,
    context: &ExecutionContext<'_>,
) -> Result<Vec<Row>> {
    for row in &rows {
        for item in items {
            match item {
                SetItem::Property {
                    target,
                    value,
                    event_time,
                } => {
                    let binding = row
                        .get(&target.variable)
                        .ok_or_else(|| Error::new(ErrorCode::QueryType, "SET target is missing"))?;
                    if binding_is_null(binding) {
                        continue;
                    }
                    let value = scalar(evaluate_state(value, row, state, context)?)?;
                    // `SET entity.property = null` cannot create a property. Do not even declare
                    // a globally unknown token for this target-local no-op.
                    if event_time.is_none()
                        && matches!(&value, ScalarValue::Null)
                        && state.graph.property(&target.property).is_none()
                    {
                        continue;
                    }
                    let property = intern_property(&target.property, state)?;
                    validate_property_for_binding(context.graph, binding, property, &value)?;
                    let (entity_kind, entity_id, temporal_target) =
                        temporal_target_for_binding(binding, property, state)?;
                    if event_time.is_some() || temporal_target.is_some() {
                        let temporal_target = temporal_target.ok_or_else(|| {
                            Error::new(
                                ErrorCode::QueryType,
                                "AT TIME is legal only for a declared temporal property",
                            )
                        })?;
                        let uses_commit_time = event_time.is_none();
                        let event_time = match event_time {
                            Some(event_time) => {
                                timestamp_nanos(&evaluate_state(event_time, row, state, context)?)?
                            }
                            None => context.resolved_time_nanos,
                        };
                        let prepared = PreparedTemporalMutation {
                            entity_kind,
                            target: temporal_target,
                            sample: TemporalSample {
                                entity_id,
                                property,
                                event_time_nanos: event_time,
                                sequence_index: state.revision,
                                value,
                            },
                            uses_commit_time,
                        };
                        state.temporal.append(
                            prepared.entity_kind,
                            prepared.target,
                            prepared.sample.clone(),
                            context.resolved_time_nanos,
                        )?;
                        state.temporal_mutations.push(prepared);
                    } else {
                        let target = PropertyMutationTarget::from_binding(binding, state, "SET")?
                            .ok_or_else(|| {
                            Error::internal("non-null SET target disappeared")
                        })?;
                        let current = target.property(state, property)?;
                        if current.as_ref() == Some(&value)
                            || (matches!(&value, ScalarValue::Null) && current.is_none())
                        {
                            continue;
                        }
                        apply_mutation(state, target.mutation(property, value, state.revision))?;
                    }
                    state.stats.properties_set = state.stats.properties_set.saturating_add(1);
                }
                SetItem::MergeMap { variable, value } => {
                    set_map_item(variable, value, false, row, state, context)?;
                }
                SetItem::ReplaceMap { variable, value } => {
                    set_map_item(variable, value, true, row, state, context)?;
                }
                SetItem::Labels { variable, labels } => {
                    let binding = row.get(variable).ok_or_else(|| {
                        Error::new(ErrorCode::QueryType, "SET label target is missing")
                    })?;
                    if binding_is_null(binding) {
                        continue;
                    }
                    let BindingValue::Node(dense) = binding else {
                        return Err(Error::new(
                            ErrorCode::QueryType,
                            "SET labels target must be a node",
                        ));
                    };
                    let node = state
                        .graph
                        .node_dense(*dense)
                        .ok_or_else(|| Error::new(ErrorCode::QueryType, "SET node is deleted"))?;
                    let node_id = node.id();
                    let existing = node.labels().iter().copied().collect::<BTreeSet<_>>();
                    let names = evaluate_label_names(labels, row, state, context)?;
                    let mut resolved = Vec::with_capacity(names.len());
                    for name in names {
                        if let Some(label) = state.graph.label(&name) {
                            if !existing.contains(&label) {
                                resolved.push(label);
                            }
                        } else {
                            resolved.push(intern_label(&name, state)?);
                        }
                    }
                    resolved.sort_unstable();
                    resolved.dedup();
                    if resolved.is_empty() {
                        continue;
                    }
                    let added = resolved.len();
                    apply_mutation(
                        state,
                        GraphMutation::AddNodeLabels {
                            node: node_id,
                            labels: resolved,
                            revision: state.revision,
                        },
                    )?;
                    state.stats.labels_added = state
                        .stats
                        .labels_added
                        .saturating_add(u64::try_from(added).unwrap_or(u64::MAX));
                }
            }
        }
    }
    Ok(rows)
}

#[derive(Clone, Copy)]
enum PropertyMutationTarget {
    Node(NodeId),
    Relationship(EdgeId),
}

impl PropertyMutationTarget {
    fn from_binding(
        binding: &BindingValue,
        state: &ExecutionState<'_>,
        operation: &'static str,
    ) -> Result<Option<Self>> {
        match binding {
            binding if binding_is_null(binding) => Ok(None),
            BindingValue::Node(dense) => state
                .graph
                .node_dense(*dense)
                .map(|node| Some(Self::Node(node.id())))
                .ok_or_else(|| Error::new(ErrorCode::QueryType, "SET node is deleted")),
            BindingValue::Relationship(dense) => state
                .graph
                .edge_dense(*dense)
                .map(|edge| Some(Self::Relationship(edge.id())))
                .ok_or_else(|| Error::new(ErrorCode::QueryType, "SET relationship is deleted")),
            _ => Err(Error::new(
                ErrorCode::QueryType,
                format!("{operation} target must be a node or relationship"),
            )),
        }
    }

    fn properties(self, state: &ExecutionState<'_>) -> Result<Vec<(PropertyId, ScalarValue)>> {
        match self {
            Self::Node(id) => state
                .graph
                .node(id)
                .map(|node| node.properties())
                .ok_or_else(|| Error::new(ErrorCode::QueryType, "SET node is deleted")),
            Self::Relationship(id) => state
                .graph
                .edge(id)
                .map(|edge| edge.properties())
                .ok_or_else(|| Error::new(ErrorCode::QueryType, "SET relationship is deleted")),
        }
    }

    fn property(
        self,
        state: &ExecutionState<'_>,
        property: PropertyId,
    ) -> Result<Option<ScalarValue>> {
        match self {
            Self::Node(id) => state
                .graph
                .node(id)
                .map(|node| node.property(property))
                .ok_or_else(|| Error::new(ErrorCode::QueryType, "SET node is deleted")),
            Self::Relationship(id) => state
                .graph
                .edge(id)
                .map(|edge| edge.property(property))
                .ok_or_else(|| Error::new(ErrorCode::QueryType, "SET relationship is deleted")),
        }
    }

    fn validate(self, graph: &GraphStore, property: PropertyId, value: &ScalarValue) -> Result<()> {
        match self {
            Self::Node(_) => graph.validate_node_property_value(property, value),
            Self::Relationship(_) => graph.validate_edge_property_value(property, value),
        }
    }

    fn mutation(self, property: PropertyId, value: ScalarValue, revision: u64) -> GraphMutation {
        match self {
            Self::Node(node) => GraphMutation::SetNodeProperty {
                node,
                property,
                value,
                revision,
            },
            Self::Relationship(edge) => GraphMutation::SetEdgeProperty {
                edge,
                property,
                value,
                revision,
            },
        }
    }
}

fn binding_is_null(binding: &BindingValue) -> bool {
    matches!(
        binding,
        BindingValue::Null | BindingValue::Value(ResultValue::Scalar(ScalarValue::Null))
    )
}

fn validate_property_for_binding(
    graph: &GraphStore,
    binding: &BindingValue,
    property: PropertyId,
    value: &ScalarValue,
) -> Result<()> {
    match binding {
        BindingValue::Node(_) => graph.validate_node_property_value(property, value),
        BindingValue::Relationship(_) => graph.validate_edge_property_value(property, value),
        _ => Err(Error::new(
            ErrorCode::QueryType,
            "SET target must be a node or relationship",
        )),
    }
}

fn set_map_item(
    variable: &str,
    value: &Expression,
    replace: bool,
    row: &Row,
    state: &mut ExecutionState<'_>,
    context: &ExecutionContext<'_>,
) -> Result<()> {
    let binding = row
        .get(variable)
        .ok_or_else(|| Error::new(ErrorCode::QueryType, "SET map target is missing"))?;
    let Some(target) = PropertyMutationTarget::from_binding(binding, state, "SET map")? else {
        return Ok(());
    };

    let values = evaluate_set_map_properties(value, row, state, context)?;
    let mut supplied = BTreeSet::new();
    let mut updates = Vec::with_capacity(values.len());
    for (property, value) in values {
        target.validate(context.graph, property, &value)?;
        supplied.insert(property);
        updates.push((property, value));
    }
    if replace {
        for (property, _) in target.properties(state)? {
            if !supplied.contains(&property) {
                updates.push((property, ScalarValue::Null));
            }
        }
    }
    for (property, value) in updates {
        apply_mutation(state, target.mutation(property, value, state.revision))?;
        state.stats.properties_set = state.stats.properties_set.saturating_add(1);
    }
    Ok(())
}

fn evaluate_set_map_properties(
    expression: &Expression,
    row: &Row,
    state: &mut ExecutionState<'_>,
    context: &ExecutionContext<'_>,
) -> Result<Vec<(PropertyId, ScalarValue)>> {
    match normalize_untrusted_container(evaluate_binding_state(expression, row, state, context)?) {
        BindingValue::Node(dense) => state
            .graph
            .node_dense(dense)
            .map(|node| node.properties())
            .ok_or_else(|| Error::new(ErrorCode::QueryType, "SET map source node is deleted")),
        BindingValue::Relationship(dense) => state
            .graph
            .edge_dense(dense)
            .map(|edge| edge.properties())
            .ok_or_else(|| {
                Error::new(
                    ErrorCode::QueryType,
                    "SET map source relationship is deleted",
                )
            }),
        BindingValue::Map(values) => {
            let mut properties = Vec::with_capacity(values.len());
            for (name, value) in values {
                let value = scalar(binding_to_result(&value, &state.graph)?)?;
                let property = intern_property(&name, state)?;
                properties.push((property, value));
            }
            Ok(properties)
        }
        _ => Err(Error::new(
            ErrorCode::QueryType,
            "SET map value must be a map, node, or relationship",
        )),
    }
}

fn temporal_target_for_binding(
    binding: &BindingValue,
    property: PropertyId,
    state: &ExecutionState<'_>,
) -> Result<(EntityKind, u64, Option<u64>)> {
    match binding {
        BindingValue::Node(dense) => {
            let node = state
                .graph
                .node_dense(*dense)
                .ok_or_else(|| Error::new(ErrorCode::QueryType, "temporal node is deleted"))?;
            let targets = node
                .labels()
                .iter()
                .map(|label| label.0)
                .collect::<Vec<_>>();
            let target = state
                .temporal
                .resolve_target(EntityKind::Node, &targets, property)?;
            Ok((EntityKind::Node, node.id().0, target))
        }
        BindingValue::Relationship(dense) => {
            let edge = state.graph.edge_dense(*dense).ok_or_else(|| {
                Error::new(ErrorCode::QueryType, "temporal relationship is deleted")
            })?;
            let targets = [edge.relationship_type().0];
            let target =
                state
                    .temporal
                    .resolve_target(EntityKind::Relationship, &targets, property)?;
            Ok((EntityKind::Relationship, edge.id().0, target))
        }
        _ => Err(Error::new(
            ErrorCode::QueryType,
            "temporal target must be a node or relationship",
        )),
    }
}

fn remove_items(
    rows: Vec<Row>,
    items: &[RemoveItem],
    state: &mut ExecutionState<'_>,
    context: &ExecutionContext<'_>,
) -> Result<Vec<Row>> {
    for row in &rows {
        for item in items {
            match item {
                RemoveItem::Property(item) => {
                    let Some(property) = state.graph.property(&item.property) else {
                        continue;
                    };
                    let binding = row.get(&item.variable).ok_or_else(|| {
                        Error::new(ErrorCode::QueryType, "REMOVE target is missing")
                    })?;
                    if binding_is_null(binding) {
                        continue;
                    }
                    let target = PropertyMutationTarget::from_binding(binding, state, "REMOVE")?
                        .ok_or_else(|| Error::internal("non-null REMOVE target disappeared"))?;
                    if target.property(state, property)?.is_none() {
                        continue;
                    }
                    apply_mutation(
                        state,
                        target.mutation(property, ScalarValue::Null, state.revision),
                    )?;
                    state.stats.properties_set = state.stats.properties_set.saturating_add(1);
                }
                RemoveItem::Labels { variable, labels } => {
                    let binding = row.get(variable).ok_or_else(|| {
                        Error::new(ErrorCode::QueryType, "REMOVE labels target is missing")
                    })?;
                    if binding_is_null(binding) {
                        continue;
                    }
                    let BindingValue::Node(dense) = binding else {
                        return Err(Error::new(
                            ErrorCode::QueryType,
                            "REMOVE labels target must be a node",
                        ));
                    };
                    let node = state.graph.node_dense(*dense).ok_or_else(|| {
                        Error::new(ErrorCode::QueryType, "REMOVE node is deleted")
                    })?;
                    let node_id = node.id();
                    let existing = node.labels().iter().copied().collect::<BTreeSet<_>>();
                    let names = evaluate_label_names(labels, row, state, context)?;
                    let mut resolved = names
                        .iter()
                        .filter_map(|name| state.graph.label(name))
                        .filter(|label| existing.contains(label))
                        .collect::<Vec<_>>();
                    resolved.sort_unstable();
                    resolved.dedup();
                    if resolved.is_empty() {
                        continue;
                    }
                    let removed = resolved.len();
                    apply_mutation(
                        state,
                        GraphMutation::RemoveNodeLabels {
                            node: node_id,
                            labels: resolved,
                            revision: state.revision,
                        },
                    )?;
                    state.stats.labels_removed = state
                        .stats
                        .labels_removed
                        .saturating_add(u64::try_from(removed).unwrap_or(u64::MAX));
                }
            }
        }
    }
    Ok(rows)
}

fn evaluate_label_names(
    labels: &[LabelName],
    row: &Row,
    state: &ExecutionState<'_>,
    context: &ExecutionContext<'_>,
) -> Result<Vec<String>> {
    let mut names = Vec::new();
    for label in labels {
        match label {
            LabelName::Static(name) => names.push(name.clone()),
            LabelName::Dynamic(expression) => {
                let value = evaluate_state(expression, row, state, context)?;
                let ResultValue::Scalar(ScalarValue::String(name)) = value else {
                    return Err(Error::new(
                        ErrorCode::QueryType,
                        "dynamic label expression must produce a string",
                    ));
                };
                names.push(name.to_string());
            }
            LabelName::DynamicAll(expression) => {
                let value = evaluate_state(expression, row, state, context)?;
                let ResultValue::List(values) = value else {
                    return Err(Error::new(
                        ErrorCode::QueryType,
                        "dynamic $all label expression must produce a list",
                    ));
                };
                for value in values {
                    let ResultValue::Scalar(ScalarValue::String(name)) = value else {
                        return Err(Error::new(
                            ErrorCode::QueryType,
                            "dynamic $all labels must all be strings",
                        ));
                    };
                    names.push(name.to_string());
                }
            }
        }
    }
    if names.iter().any(String::is_empty) {
        return Err(Error::new(
            ErrorCode::QueryType,
            "label names cannot be empty",
        ));
    }
    names.sort();
    names.dedup();
    Ok(names)
}

fn delete_items(
    rows: Vec<Row>,
    expressions: &[Expression],
    detach: bool,
    state: &mut ExecutionState<'_>,
    context: &ExecutionContext<'_>,
) -> Result<Vec<Row>> {
    let mut nodes = BTreeSet::new();
    let mut relationships = BTreeSet::new();
    for row in &rows {
        for expression in expressions {
            let binding = match expression {
                Expression::Variable(variable) => row.get(variable).cloned(),
                _ => Some(evaluate_binding_state(expression, row, state, context)?),
            };
            collect_delete_targets(binding.as_ref(), state, &mut nodes, &mut relationships)?;
        }
    }

    // Resolve every row binding before mutating the statement overlay, then apply each stable
    // entity ID once. Undirected and variable-length matches legitimately produce duplicate rows,
    // while a path requires its relationships to disappear before ordinary node deletion can be
    // validated.
    for edge in relationships {
        apply_mutation(
            state,
            GraphMutation::DeleteEdge {
                edge,
                revision: state.revision,
            },
        )?;
        state.stats.relationships_deleted = state.stats.relationships_deleted.saturating_add(1);
    }
    for node in nodes {
        let result = apply_mutation(
            state,
            GraphMutation::DeleteNode {
                node,
                detach,
                revision: state.revision,
            },
        );
        match result {
            Ok(()) => {
                state.stats.nodes_deleted = state.stats.nodes_deleted.saturating_add(1);
            }
            Err(error)
                if !detach
                    && error.code == ErrorCode::QueryType
                    && error.message == "node still has relationships" =>
            {
                return Err(Error::new(
                    ErrorCode::QueryType,
                    "DeleteConnectedNode: node still has relationships",
                ));
            }
            Err(error) => return Err(error),
        }
    }
    Ok(rows)
}

fn collect_delete_targets(
    binding: Option<&BindingValue>,
    state: &ExecutionState<'_>,
    nodes: &mut BTreeSet<NodeId>,
    relationships: &mut BTreeSet<EdgeId>,
) -> Result<()> {
    match binding {
        Some(BindingValue::Node(dense)) => {
            let node = state
                .graph
                .node_dense(*dense)
                .ok_or_else(|| Error::new(ErrorCode::QueryType, "DELETE node is missing"))?
                .id();
            nodes.insert(node);
        }
        Some(BindingValue::Relationship(dense)) => {
            let edge = state
                .graph
                .edge_dense(*dense)
                .ok_or_else(|| Error::new(ErrorCode::QueryType, "DELETE relationship is missing"))?
                .id();
            relationships.insert(edge);
        }
        Some(BindingValue::Path {
            nodes: path_nodes,
            relationships: path_relationships,
        }) => {
            for dense in path_nodes {
                let node = state
                    .graph
                    .node_dense(*dense)
                    .ok_or_else(|| Error::new(ErrorCode::QueryType, "DELETE node is missing"))?
                    .id();
                nodes.insert(node);
            }
            for dense in path_relationships {
                let edge = state
                    .graph
                    .edge_dense(*dense)
                    .ok_or_else(|| {
                        Error::new(ErrorCode::QueryType, "DELETE relationship is missing")
                    })?
                    .id();
                relationships.insert(edge);
            }
        }
        Some(binding) if binding_is_null(binding) => {}
        _ => {
            return Err(Error::new(
                ErrorCode::QueryType,
                "DELETE expression must resolve to a node, relationship, or path",
            ));
        }
    }
    Ok(())
}

fn project_rows(
    rows: Vec<Row>,
    projection: &Projection,
    input_scope: &BTreeSet<String>,
    state: &mut ExecutionState<'_>,
    context: &ExecutionContext<'_>,
    keep_scope: bool,
) -> Result<(Vec<Row>, Vec<String>)> {
    let star_columns: Vec<_> = input_scope
        .iter()
        .filter(|name| !name.starts_with('\0'))
        .cloned()
        .chain(
            rows.iter()
                .flat_map(|row| row.keys().filter(|name| !name.starts_with('\0')).cloned()),
        )
        .collect::<BTreeSet<_>>()
        .into_iter()
        .collect();
    let mut columns = Vec::new();
    for (index, item) in projection.items.iter().enumerate() {
        if matches!(item.expression, Expression::Star) {
            for name in &star_columns {
                if !columns.contains(name) {
                    columns.push(name.clone());
                }
            }
        } else {
            let name = item.column_name(index);
            if !columns.contains(&name) {
                columns.push(name);
            }
        }
    }
    let aggregate = projection
        .items
        .iter()
        .any(|item| is_aggregate(&item.expression));
    let groups = if aggregate {
        group_rows(rows, projection, state, context)?
    } else {
        vec![rows]
    };
    let mut output = Vec::new();
    for group in groups {
        if aggregate {
            let representative = group.first().cloned().unwrap_or_default();
            let mut projected = if keep_scope {
                representative.clone()
            } else {
                Row::new()
            };
            for (index, item) in projection.items.iter().enumerate() {
                if matches!(item.expression, Expression::Star) {
                    for name in &star_columns {
                        if let Some(value) = representative.get(name) {
                            projected.insert(name.clone(), value.clone());
                        }
                    }
                    continue;
                }
                let column = item.column_name(index);
                let value = if !is_aggregate(&item.expression) {
                    projection_binding(&item.expression, &representative, state, context)?
                } else {
                    evaluate_group(&item.expression, &group, state, context)?
                };
                projected.insert(column, value);
            }
            output.push(projected);
        } else {
            for row in group {
                let mut projected = if keep_scope { row.clone() } else { Row::new() };
                for (index, item) in projection.items.iter().enumerate() {
                    if matches!(item.expression, Expression::Star) {
                        for (name, value) in &row {
                            projected.insert(name.clone(), value.clone());
                        }
                    } else {
                        let column = item.column_name(index);
                        projected.insert(
                            column,
                            projection_binding(&item.expression, &row, state, context)?,
                        );
                    }
                }
                output.push(projected);
            }
        }
    }
    if projection.distinct {
        deduplicate_rows(&mut output, &state.graph)?;
    }
    Ok((output, columns))
}

fn projection_binding(
    expression: &Expression,
    row: &Row,
    state: &mut ExecutionState<'_>,
    context: &ExecutionContext<'_>,
) -> Result<BindingValue> {
    if let Expression::Variable(variable) = expression {
        return Ok(row.get(variable).cloned().unwrap_or(BindingValue::Null));
    }
    evaluate_correlated_binding_state(expression, row, state, context)
}

fn group_rows(
    rows: Vec<Row>,
    projection: &Projection,
    state: &mut ExecutionState<'_>,
    context: &ExecutionContext<'_>,
) -> Result<Vec<Vec<Row>>> {
    let mut groups: BTreeMap<Vec<u8>, Vec<Row>> = BTreeMap::new();
    for row in rows {
        let mut key_values = Vec::new();
        for item in projection
            .items
            .iter()
            .filter(|item| !is_aggregate(&item.expression))
        {
            let value = if matches!(item.expression, Expression::Star) {
                ResultValue::List(
                    row.values()
                        .map(|value| binding_to_result(value, &state.graph))
                        .collect::<Result<Vec<_>>>()?,
                )
            } else {
                let value =
                    evaluate_correlated_binding_state(&item.expression, &row, state, context)?;
                binding_to_result(&value, &state.graph)?
            };
            key_values.push(value);
        }
        let mut key = Vec::new();
        for value in &key_values {
            append_equality_value(&mut key, value);
        }
        groups.entry(key).or_default().push(row);
    }
    if groups.is_empty()
        && projection
            .items
            .iter()
            .all(|item| is_aggregate(&item.expression))
    {
        groups.insert(Vec::new(), Vec::new());
    }
    Ok(groups.into_values().collect())
}

fn evaluate_group(
    expression: &Expression,
    rows: &[Row],
    state: &mut ExecutionState<'_>,
    context: &ExecutionContext<'_>,
) -> Result<BindingValue> {
    let mut bindings = rows.first().cloned().unwrap_or_default();
    let mut aggregate_index = 0_usize;
    let materialized = materialize_group_aggregates(
        expression,
        rows,
        state,
        context,
        &mut bindings,
        &mut aggregate_index,
    )?;
    evaluate_correlated_binding_state(&materialized, &bindings, state, context)
}

fn evaluate_aggregate_root(
    expression: &Expression,
    rows: &[Row],
    state: &mut ExecutionState<'_>,
    context: &ExecutionContext<'_>,
) -> Result<ResultValue> {
    let Expression::Function {
        name,
        arguments,
        distinct,
        ..
    } = expression
    else {
        return rows.first().map_or_else(
            || Ok(ResultValue::Scalar(ScalarValue::Null)),
            |row| {
                evaluate_correlated_binding_state(expression, row, state, context)
                    .and_then(|value| binding_to_result(&value, &state.graph))
            },
        );
    };
    let function = name.join(".").to_ascii_lowercase();
    if !matches!(
        function.as_str(),
        "count"
            | "sum"
            | "avg"
            | "min"
            | "max"
            | "collect"
            | "variance"
            | "variancep"
            | "stdev"
            | "stdevp"
            | "percentilecont"
            | "percentiledisc"
    ) {
        return rows.first().map_or_else(
            || Ok(ResultValue::Scalar(ScalarValue::Null)),
            |row| {
                evaluate_correlated_binding_state(expression, row, state, context)
                    .and_then(|value| binding_to_result(&value, &state.graph))
            },
        );
    }
    let argument = arguments.first();
    let mut values = Vec::new();
    for row in rows {
        let value = if matches!(argument, Some(Expression::Star)) {
            if row.contains_key(INTERNAL_WINDOW_EMPTY) {
                ResultValue::Scalar(ScalarValue::Null)
            } else {
                ResultValue::Scalar(ScalarValue::Integer(1))
            }
        } else if let Some(argument) = argument {
            let value = evaluate_correlated_binding_state(argument, row, state, context)?;
            binding_to_result(&value, &state.graph)?
        } else {
            ResultValue::Scalar(ScalarValue::Null)
        };
        if !matches!(value, ResultValue::Scalar(ScalarValue::Null)) {
            values.push(value);
        }
    }
    if *distinct {
        let mut encoded = BTreeSet::new();
        let mut unique = Vec::with_capacity(values.len());
        for value in values {
            let bytes = value_key(&value);
            if encoded.insert(bytes) {
                unique.push(value);
            }
        }
        values = unique;
    }
    match function.as_str() {
        "count" => Ok(ResultValue::Scalar(ScalarValue::Integer(
            i64::try_from(values.len()).map_err(|_| {
                Error::new(ErrorCode::ResultBudgetExceeded, "aggregate count overflow")
            })?,
        ))),
        "collect" => Ok(ResultValue::List(values)),
        "sum" => aggregate_sum(&values),
        "avg" => aggregate_average(&values),
        "variance" | "variancep" | "stdev" | "stdevp" => {
            aggregate_dispersion(&values, function.as_str())
        }
        "percentilecont" | "percentiledisc" => {
            let percentile_expression = arguments.get(1).ok_or_else(|| {
                Error::new(
                    ErrorCode::QueryType,
                    "percentile aggregate requires value and percentile arguments",
                )
            })?;
            let empty = Row::new();
            let percentile = evaluate_correlated_binding_state(
                percentile_expression,
                rows.first().unwrap_or(&empty),
                state,
                context,
            )?;
            let percentile = numeric(&binding_to_result(&percentile, &state.graph)?)?;
            validate_percentile_argument(percentile)?;
            for row in rows.iter().skip(1) {
                let candidate =
                    evaluate_correlated_binding_state(percentile_expression, row, state, context)?;
                let candidate = numeric(&binding_to_result(&candidate, &state.graph)?)?;
                validate_percentile_argument(candidate)?;
                if candidate != percentile {
                    return Err(Error::new(
                        ErrorCode::QueryType,
                        "percentile argument must be constant within each group",
                    ));
                }
            }
            aggregate_percentile(&values, percentile, function == "percentilecont")
        }
        "min" | "max" => {
            let value = values.into_iter().reduce(|left, right| {
                let order = total_compare(&left, &right);
                if (function == "min" && order != Ordering::Greater)
                    || (function == "max" && order != Ordering::Less)
                {
                    left
                } else {
                    right
                }
            });
            Ok(value.unwrap_or(ResultValue::Scalar(ScalarValue::Null)))
        }
        _ => Err(Error::internal("aggregate dispatch is inconsistent")),
    }
}

fn evaluate_aggregate_binding_root(
    expression: &Expression,
    rows: &[Row],
    state: &mut ExecutionState<'_>,
    context: &ExecutionContext<'_>,
) -> Result<BindingValue> {
    let Expression::Function {
        name,
        arguments,
        distinct,
        ..
    } = expression
    else {
        return evaluate_aggregate_root(expression, rows, state, context)
            .map(untrusted_result_binding);
    };
    if name.join(".").to_ascii_lowercase() != "collect" {
        return evaluate_aggregate_root(expression, rows, state, context)
            .map(untrusted_result_binding);
    }

    let argument = arguments.first();
    let mut values = Vec::new();
    for row in rows {
        let value = if matches!(argument, Some(Expression::Star)) {
            if row.contains_key(INTERNAL_WINDOW_EMPTY) {
                BindingValue::Null
            } else {
                BindingValue::Value(ResultValue::Scalar(ScalarValue::Integer(1)))
            }
        } else if let Some(argument) = argument {
            evaluate_correlated_binding_state(argument, row, state, context)?
        } else {
            BindingValue::Null
        };
        if !binding_is_null(&value) {
            values.push(value);
        }
    }
    if *distinct {
        let mut encoded = BTreeSet::new();
        let mut unique = Vec::with_capacity(values.len());
        for value in values {
            let bytes = value_key(&binding_to_result(&value, &state.graph)?);
            if encoded.insert(bytes) {
                unique.push(value);
            }
        }
        values = unique;
    }
    Ok(BindingValue::List(values))
}

fn materialize_group_aggregates(
    expression: &Expression,
    rows: &[Row],
    state: &mut ExecutionState<'_>,
    context: &ExecutionContext<'_>,
    bindings: &mut Row,
    aggregate_index: &mut usize,
) -> Result<Expression> {
    if let Expression::Function { name, .. } = expression
        && is_aggregate_function(name)
    {
        let value = evaluate_aggregate_binding_root(expression, rows, state, context)?;
        let variable = format!("\0aggregate_{}", *aggregate_index);
        *aggregate_index = aggregate_index.saturating_add(1);
        bindings.insert(variable.clone(), value);
        return Ok(Expression::Variable(variable));
    }
    let mut recurse = |value: &Expression,
                       bindings: &mut Row,
                       aggregate_index: &mut usize|
     -> Result<Expression> {
        materialize_group_aggregates(value, rows, state, context, bindings, aggregate_index)
    };
    match expression {
        Expression::Literal(_)
        | Expression::Parameter(_)
        | Expression::Variable(_)
        | Expression::ExistentialSubquery(_)
        | Expression::Star => Ok(expression.clone()),
        Expression::Property(value, property) => Ok(Expression::Property(
            Box::new(recurse(value, bindings, aggregate_index)?),
            property.clone(),
        )),
        Expression::List(values) => Ok(Expression::List(
            values
                .iter()
                .map(|value| recurse(value, bindings, aggregate_index))
                .collect::<Result<_>>()?,
        )),
        Expression::Map(values) => Ok(Expression::Map(
            values
                .iter()
                .map(|(name, value)| Ok((name.clone(), recurse(value, bindings, aggregate_index)?)))
                .collect::<Result<_>>()?,
        )),
        Expression::MapProjection { source, items } => Ok(Expression::MapProjection {
            source: Box::new(recurse(source, bindings, aggregate_index)?),
            items: items
                .iter()
                .map(|item| match item {
                    MapProjectionItem::Entry(name, value) => Ok(MapProjectionItem::Entry(
                        name.clone(),
                        recurse(value, bindings, aggregate_index)?,
                    )),
                    _ => Ok(item.clone()),
                })
                .collect::<Result<_>>()?,
        }),
        Expression::Case {
            operand,
            alternatives,
            default,
        } => Ok(Expression::Case {
            operand: operand
                .as_deref()
                .map(|value| recurse(value, bindings, aggregate_index).map(Box::new))
                .transpose()?,
            alternatives: alternatives
                .iter()
                .map(|alternative| {
                    Ok(CaseAlternative {
                        when: recurse(&alternative.when, bindings, aggregate_index)?,
                        then: recurse(&alternative.then, bindings, aggregate_index)?,
                    })
                })
                .collect::<Result<_>>()?,
            default: default
                .as_deref()
                .map(|value| recurse(value, bindings, aggregate_index).map(Box::new))
                .transpose()?,
        }),
        Expression::ListComprehension {
            variable,
            list,
            predicate,
            projection,
        } => Ok(Expression::ListComprehension {
            variable: variable.clone(),
            list: Box::new(recurse(list, bindings, aggregate_index)?),
            predicate: predicate
                .as_deref()
                .map(|value| recurse(value, bindings, aggregate_index).map(Box::new))
                .transpose()?,
            projection: projection
                .as_deref()
                .map(|value| recurse(value, bindings, aggregate_index).map(Box::new))
                .transpose()?,
        }),
        Expression::Reduce {
            accumulator,
            initial,
            variable,
            list,
            expression,
        } => Ok(Expression::Reduce {
            accumulator: accumulator.clone(),
            initial: Box::new(recurse(initial, bindings, aggregate_index)?),
            variable: variable.clone(),
            list: Box::new(recurse(list, bindings, aggregate_index)?),
            expression: Box::new(recurse(expression, bindings, aggregate_index)?),
        }),
        Expression::ListPredicate {
            kind,
            variable,
            list,
            predicate,
        } => Ok(Expression::ListPredicate {
            kind: *kind,
            variable: variable.clone(),
            list: Box::new(recurse(list, bindings, aggregate_index)?),
            predicate: Box::new(recurse(predicate, bindings, aggregate_index)?),
        }),
        Expression::Function {
            name,
            distinct,
            arguments,
        } => Ok(Expression::Function {
            name: name.clone(),
            distinct: *distinct,
            arguments: arguments
                .iter()
                .map(|value| recurse(value, bindings, aggregate_index))
                .collect::<Result<_>>()?,
        }),
        Expression::Unary { operation, operand } => Ok(Expression::Unary {
            operation: *operation,
            operand: Box::new(recurse(operand, bindings, aggregate_index)?),
        }),
        Expression::Binary {
            left,
            operation,
            right,
        } => Ok(Expression::Binary {
            left: Box::new(recurse(left, bindings, aggregate_index)?),
            operation: *operation,
            right: Box::new(recurse(right, bindings, aggregate_index)?),
        }),
        Expression::IsNull {
            expression,
            negated,
        } => Ok(Expression::IsNull {
            expression: Box::new(recurse(expression, bindings, aggregate_index)?),
            negated: *negated,
        }),
        Expression::Index { expression, index } => Ok(Expression::Index {
            expression: Box::new(recurse(expression, bindings, aggregate_index)?),
            index: Box::new(recurse(index, bindings, aggregate_index)?),
        }),
        Expression::Slice {
            expression,
            start,
            end,
        } => Ok(Expression::Slice {
            expression: Box::new(recurse(expression, bindings, aggregate_index)?),
            start: start
                .as_deref()
                .map(|value| recurse(value, bindings, aggregate_index).map(Box::new))
                .transpose()?,
            end: end
                .as_deref()
                .map(|value| recurse(value, bindings, aggregate_index).map(Box::new))
                .transpose()?,
        }),
    }
}

fn aggregate_sum(values: &[ResultValue]) -> Result<ResultValue> {
    let mut integer_sum = 0_i64;
    let mut all_integer = true;
    let mut sum = 0.0_f64;
    let mut compensation = 0.0_f64;
    for value in values {
        match value {
            ResultValue::Scalar(ScalarValue::Integer(value)) if all_integer => {
                integer_sum = integer_sum.checked_add(*value).ok_or_else(|| {
                    Error::new(ErrorCode::QueryType, "integer aggregate sum overflow")
                })?;
            }
            ResultValue::Scalar(ScalarValue::Integer(value)) => {
                compensated_add(&mut sum, &mut compensation, *value as f64);
            }
            ResultValue::Scalar(ScalarValue::Float(value)) => {
                if all_integer {
                    sum = integer_sum as f64;
                    all_integer = false;
                }
                compensated_add(&mut sum, &mut compensation, value.into_inner());
            }
            _ => {
                return Err(Error::new(
                    ErrorCode::QueryType,
                    "numeric aggregate received a non-numeric value",
                ));
            }
        }
    }
    if all_integer {
        Ok(ResultValue::Scalar(ScalarValue::Integer(integer_sum)))
    } else {
        Ok(number(sum + compensation))
    }
}

fn aggregate_average(values: &[ResultValue]) -> Result<ResultValue> {
    if values.is_empty() {
        return Ok(ResultValue::Scalar(ScalarValue::Null));
    }
    let mut sum = 0.0_f64;
    let mut compensation = 0.0_f64;
    for value in values {
        compensated_add(&mut sum, &mut compensation, numeric(value)?);
    }
    Ok(number(
        (sum + compensation)
            / u64::try_from(values.len())
                .map_err(|_| Error::new(ErrorCode::ResultBudgetExceeded, "row count overflow"))?
                as f64,
    ))
}

fn aggregate_dispersion(values: &[ResultValue], function: &str) -> Result<ResultValue> {
    let sample = matches!(function, "variance" | "stdev");
    if values.is_empty() || (sample && values.len() < 2) {
        return Ok(ResultValue::Scalar(ScalarValue::Null));
    }
    let mut count = 0_u64;
    let mut mean = 0.0_f64;
    let mut squared_deviation = 0.0_f64;
    for value in values {
        count = count.checked_add(1).ok_or_else(|| {
            Error::new(
                ErrorCode::ResultBudgetExceeded,
                "aggregate row count overflow",
            )
        })?;
        let value = numeric(value)?;
        let delta = value - mean;
        mean += delta / count as f64;
        squared_deviation += delta * (value - mean);
    }
    let denominator = if sample { count - 1 } else { count };
    let variance = (squared_deviation / denominator as f64).max(0.0);
    Ok(number(if matches!(function, "stdev" | "stdevp") {
        variance.sqrt()
    } else {
        variance
    }))
}

fn aggregate_percentile(
    values: &[ResultValue],
    percentile: f64,
    continuous: bool,
) -> Result<ResultValue> {
    validate_percentile_argument(percentile)?;
    if values.is_empty() {
        return Ok(ResultValue::Scalar(ScalarValue::Null));
    }
    let mut numbers = values
        .iter()
        .enumerate()
        .map(|(index, value)| Ok((numeric(value)?, index)))
        .collect::<Result<Vec<_>>>()?;
    numbers.sort_by(|left, right| {
        left.0
            .total_cmp(&right.0)
            .then_with(|| left.1.cmp(&right.1))
    });
    if continuous {
        let position = percentile * (numbers.len().saturating_sub(1) as f64);
        let lower = position.floor() as usize;
        let upper = position.ceil() as usize;
        let fraction = position - lower as f64;
        Ok(number(
            numbers[lower].0 + (numbers[upper].0 - numbers[lower].0) * fraction,
        ))
    } else {
        let position = if percentile == 0.0 {
            0
        } else {
            (percentile * numbers.len() as f64).ceil() as usize - 1
        };
        Ok(values[numbers[position.min(numbers.len() - 1)].1].clone())
    }
}

fn validate_percentile_argument(percentile: f64) -> Result<()> {
    if !percentile.is_finite() || !(0.0..=1.0).contains(&percentile) {
        return Err(Error::new(
            ErrorCode::QueryType,
            "NumberOutOfRange: percentile must be finite and in 0..=1",
        ));
    }
    Ok(())
}

fn compensated_add(sum: &mut f64, compensation: &mut f64, value: f64) {
    let next = *sum + value;
    *compensation += if sum.abs() >= value.abs() {
        (*sum - next) + value
    } else {
        (value - next) + *sum
    };
    *sum = next;
}

fn sort_rows(
    mut rows: Vec<Row>,
    items: &[SortItem],
    state: &ExecutionState<'_>,
    context: &ExecutionContext<'_>,
) -> Result<Vec<Row>> {
    check_execution(context)?;
    if materialized_value_rows_are_ordered(&rows, items, context)? {
        return Ok(rows);
    }
    if let Some(positions) = resident_sort_positions(&rows, items, None, state, context)? {
        return reorder_rows(rows, &positions);
    }
    let mut keyed = Vec::with_capacity(rows.len());
    for (index, row) in rows.drain(..).enumerate() {
        if index & 4095 == 0 {
            check_execution(context)?;
        }
        let keys = items
            .iter()
            .map(|item| evaluate_state(&item.expression, &row, state, context))
            .collect::<Result<Vec<_>>>()?;
        keyed.push((keys, row));
    }
    keyed.sort_by(|(left, _), (right, _)| compare_sort_keys(left, right, items));
    check_execution(context)?;
    Ok(keyed.into_iter().map(|(_, row)| row).collect())
}

/// Proves the common projected-alias case is already in the requested order without cloning,
/// encoding, sorting, or rebuilding rows. A false result is only a fast-path miss: every shape
/// not proven here continues through the ordinary resident or CPU sort below.
fn materialized_value_rows_are_ordered(
    rows: &[Row],
    items: &[SortItem],
    context: &ExecutionContext<'_>,
) -> Result<bool> {
    let [item] = items else {
        return Ok(false);
    };
    let Expression::Variable(variable) = &item.expression else {
        return Ok(false);
    };
    let mut previous = None;
    for (position, row) in rows.iter().enumerate() {
        if position.is_multiple_of(4096) {
            check_execution(context)?;
        }
        let Some(BindingValue::Value(value)) = row.get(variable) else {
            return Ok(false);
        };
        if let Some(prior) = previous
            && compare_sort_keys(
                std::slice::from_ref(prior),
                std::slice::from_ref(value),
                items,
            ) == Ordering::Greater
        {
            return Ok(false);
        }
        previous = Some(value);
    }
    Ok(true)
}

#[cfg(test)]
mod materialized_value_order_tests {
    use super::*;

    fn context(graph: &GraphStore) -> ExecutionContext<'_> {
        ExecutionContext {
            project_id: ProjectId(uuid::Uuid::nil()),
            graph,
            binding_catalog: graph.catalog(),
            prior_graph_mutations: &[],
            temporal: None,
            prior_temporal_mutations: &[],
            vector_indexes: BTreeMap::new(),
            scalar_indexes: None,
            text_embedding: None,
            parameters: BTreeMap::new(),
            bookmark: Bookmark { term: 0, index: 0 },
            mutation_revision: 1,
            resolved_time_nanos: 0,
            next_node_id: 1,
            next_edge_id: 1,
            predicate_versions: BTreeMap::new(),
            capabilities: BindCapabilities::default(),
            max_result_rows: 1_024,
            max_batch_rows: 1_024,
            optimizer_statistics: None,
            backend: None,
            cancellation: CancellationToken::new(),
            deadline: None,
            resolved_query_at_time_nanos: None,
        }
    }

    fn value_row(key: i64, payload: i64) -> Row {
        Row::from([
            (
                "key".to_owned(),
                BindingValue::Value(ResultValue::Scalar(ScalarValue::Integer(key))),
            ),
            (
                "payload".to_owned(),
                BindingValue::Value(ResultValue::Scalar(ScalarValue::Integer(payload))),
            ),
        ])
    }

    fn key_order(ascending: bool) -> SortItem {
        SortItem {
            expression: Expression::Variable("key".to_owned()),
            ascending,
        }
    }

    #[test]
    fn recognizes_ascending_and_descending_materialized_alias_order() -> Result<()> {
        let graph = GraphStore::default();
        let context = context(&graph);
        let ascending = [value_row(1, 10), value_row(2, 20), value_row(3, 30)];
        assert!(materialized_value_rows_are_ordered(
            &ascending,
            &[key_order(true)],
            &context,
        )?);

        let descending = [value_row(3, 30), value_row(2, 20), value_row(1, 10)];
        assert!(materialized_value_rows_are_ordered(
            &descending,
            &[key_order(false)],
            &context,
        )?);
        Ok(())
    }

    #[test]
    fn rejects_an_inversion_without_reordering_rows() -> Result<()> {
        let graph = GraphStore::default();
        let context = context(&graph);
        let rows = [value_row(1, 10), value_row(3, 30), value_row(2, 20)];
        assert!(!materialized_value_rows_are_ordered(
            &rows,
            &[key_order(true)],
            &context,
        )?);
        Ok(())
    }

    #[test]
    fn equal_keys_preserve_input_stability() -> Result<()> {
        let graph = GraphStore::default();
        let context = context(&graph);
        let rows = [value_row(7, 10), value_row(7, 20), value_row(7, 30)];
        let before = rows.clone();
        assert!(materialized_value_rows_are_ordered(
            &rows,
            &[key_order(true)],
            &context,
        )?);
        assert_eq!(rows, before);
        Ok(())
    }

    #[test]
    fn declines_multi_key_complex_expression_and_non_value_bindings() -> Result<()> {
        let graph = GraphStore::default();
        let context = context(&graph);
        let rows = [value_row(1, 10), value_row(2, 20)];
        assert!(!materialized_value_rows_are_ordered(
            &rows,
            &[key_order(true), key_order(true)],
            &context,
        )?);
        assert!(!materialized_value_rows_are_ordered(
            &rows,
            &[SortItem {
                expression: Expression::Literal(ScalarValue::Integer(1)),
                ascending: true,
            }],
            &context,
        )?);

        let non_value = [Row::from([("key".to_owned(), BindingValue::Node(0))])];
        assert!(!materialized_value_rows_are_ordered(
            &non_value,
            &[key_order(true)],
            &context,
        )?);
        Ok(())
    }

    #[test]
    fn propagates_cancellation_and_deadline() {
        let graph = GraphStore::default();
        let rows = [value_row(1, 10)];

        let cancelled = context(&graph);
        cancelled.cancellation.cancel();
        let error = materialized_value_rows_are_ordered(&rows, &[key_order(true)], &cancelled)
            .expect_err("cancelled orderedness proof must stop");
        assert_eq!(error.code, ErrorCode::Cancelled);

        let mut expired = context(&graph);
        expired.deadline = Some(Instant::now());
        let error = materialized_value_rows_are_ordered(&rows, &[key_order(true)], &expired)
            .expect_err("expired orderedness proof must stop");
        assert_eq!(error.code, ErrorCode::DeadlineExceeded);
    }
}

fn top_k_rows(
    rows: Vec<Row>,
    items: &[SortItem],
    limit: usize,
    state: &ExecutionState<'_>,
    context: &ExecutionContext<'_>,
) -> Result<Vec<Row>> {
    check_execution(context)?;
    if limit == 0 || rows.is_empty() {
        return Ok(Vec::new());
    }
    if let Some(positions) = resident_sort_positions(&rows, items, Some(limit), state, context)? {
        return reorder_rows(rows, &positions);
    }
    let mut keyed = Vec::with_capacity(rows.len());
    for (position, row) in rows.into_iter().enumerate() {
        if position & 4095 == 0 {
            check_execution(context)?;
        }
        let keys = items
            .iter()
            .map(|item| evaluate_state(&item.expression, &row, state, context))
            .collect::<Result<Vec<_>>>()?;
        keyed.push((keys, position, row));
    }
    let compare = |left: &(Vec<ResultValue>, usize, Row),
                   right: &(Vec<ResultValue>, usize, Row)| {
        compare_sort_keys(&left.0, &right.0, items).then_with(|| left.1.cmp(&right.1))
    };
    if limit < keyed.len() {
        keyed.select_nth_unstable_by(limit, compare);
        keyed.truncate(limit);
    }
    keyed.sort_unstable_by(compare);
    check_execution(context)?;
    Ok(keyed.into_iter().map(|(_, _, row)| row).collect())
}

fn resident_sort_positions(
    rows: &[Row],
    items: &[SortItem],
    limit: Option<usize>,
    state: &ExecutionState<'_>,
    context: &ExecutionContext<'_>,
) -> Result<Option<Vec<u32>>> {
    let Some(backend) = current_backend(state, context) else {
        return Ok(None);
    };
    if items.is_empty() {
        return Ok(None);
    }
    let requested_descriptor_bytes = items
        .len()
        .checked_mul(std::mem::size_of::<ResidentSortKey>())
        .ok_or_else(|| {
            Error::new(
                ErrorCode::ResultBudgetExceeded,
                "resident sort-key descriptor size overflow",
            )
        })?;
    let mut host_scratch = backend.reserve_query_scratch(requested_descriptor_bytes)?;
    let mut keys = Vec::new();
    keys.try_reserve_exact(items.len()).map_err(|_| {
        Error::new(
            ErrorCode::ResultBudgetExceeded,
            "resident sort-key descriptors exceed the query memory budget",
        )
    })?;
    let descriptor_bytes = keys
        .capacity()
        .checked_mul(std::mem::size_of::<ResidentSortKey>())
        .ok_or_else(|| {
            Error::new(
                ErrorCode::ResultBudgetExceeded,
                "resident sort-key descriptor capacity overflow",
            )
        })?;
    host_scratch.resize(descriptor_bytes)?;
    if let [item] = items
        && let Expression::Property(source, property_name) = &item.expression
        && let Expression::Variable(variable) = source.as_ref()
        && let Some(property) = state.graph.property(property_name)
        && context.graph.node_property_is_integer(property)
    {
        let requested_row_bytes = rows
            .len()
            .checked_mul(std::mem::size_of::<u32>())
            .and_then(|bytes| descriptor_bytes.checked_add(bytes))
            .ok_or_else(|| {
                Error::new(
                    ErrorCode::ResultBudgetExceeded,
                    "resident sort row-selection size overflow",
                )
            })?;
        host_scratch.resize(requested_row_bytes)?;
        let mut dense_rows = Vec::new();
        dense_rows.try_reserve_exact(rows.len()).map_err(|_| {
            Error::new(
                ErrorCode::ResultBudgetExceeded,
                "resident sort row selection exceeds the query memory budget",
            )
        })?;
        let retained_row_bytes = dense_rows
            .capacity()
            .checked_mul(std::mem::size_of::<u32>())
            .and_then(|bytes| descriptor_bytes.checked_add(bytes))
            .ok_or_else(|| {
                Error::new(
                    ErrorCode::ResultBudgetExceeded,
                    "resident sort row-selection capacity overflow",
                )
            })?;
        host_scratch.resize(retained_row_bytes)?;
        let mut resident = true;
        for row in rows {
            let Some(BindingValue::Node(dense)) = row.get(variable) else {
                resident = false;
                break;
            };
            dense_rows.push(*dense);
        }
        if resident {
            keys.push(ResidentSortKey {
                source: ResidentSortSource::NodeProperty {
                    rows: dense_rows,
                    property,
                },
                descending: !item.ascending,
                nulls_first: !item.ascending,
            });
        } else {
            host_scratch.resize(descriptor_bytes)?;
        }
    }
    if keys.is_empty() {
        for item in items {
            let column = materialized_order_column(
                rows,
                &item.expression,
                state,
                context,
                &mut host_scratch,
            )?;
            keys.push(ResidentSortKey {
                source: ResidentSortSource::Materialized(column),
                descending: !item.ascending,
                nulls_first: !item.ascending,
            });
        }
    }
    let result = backend.sort_rows(
        &ResidentSortRequest {
            project: context.project_id,
            row_count: rows.len(),
            keys,
            limit,
        },
        &context.cancellation,
    )?;
    Ok(Some(result.positions))
}

fn materialized_order_column(
    rows: &[Row],
    expression: &Expression,
    state: &ExecutionState<'_>,
    context: &ExecutionContext<'_>,
    host_scratch: &mut ScratchReservation,
) -> Result<ResidentOrderColumn> {
    let offset_count = rows.len().checked_add(1).ok_or_else(|| {
        Error::new(
            ErrorCode::ResultBudgetExceeded,
            "materialized sort-key offset count overflow",
        )
    })?;
    let requested_fixed_bytes = offset_count
        .checked_mul(std::mem::size_of::<u32>())
        .and_then(|bytes| bytes.checked_add(rows.len()))
        .ok_or_else(|| {
            Error::new(
                ErrorCode::ResultBudgetExceeded,
                "materialized sort-key fixed storage overflow",
            )
        })?;
    let prior_bytes = host_scratch.bytes();
    host_scratch.resize(
        prior_bytes
            .checked_add(requested_fixed_bytes)
            .ok_or_else(|| {
                Error::new(
                    ErrorCode::ResultBudgetExceeded,
                    "materialized sort-key reservation size overflow",
                )
            })?,
    )?;
    let allocation_error = || {
        Error::new(
            ErrorCode::ResultBudgetExceeded,
            "materialized sort-key storage cannot be admitted within the query memory budget",
        )
    };
    let mut offsets = Vec::new();
    offsets
        .try_reserve_exact(offset_count)
        .map_err(|_| allocation_error())?;
    let mut digits = Vec::new();
    let mut validity = Vec::new();
    validity
        .try_reserve_exact(rows.len())
        .map_err(|_| allocation_error())?;
    let fixed_bytes = offsets
        .capacity()
        .checked_mul(std::mem::size_of::<u32>())
        .and_then(|bytes| bytes.checked_add(validity.capacity()))
        .ok_or_else(|| {
            Error::new(
                ErrorCode::ResultBudgetExceeded,
                "materialized sort-key retained capacity overflow",
            )
        })?;
    host_scratch.resize(prior_bytes.checked_add(fixed_bytes).ok_or_else(|| {
        Error::new(
            ErrorCode::ResultBudgetExceeded,
            "materialized sort-key retained reservation overflow",
        )
    })?)?;
    offsets.push(0);
    for (position, row) in rows.iter().enumerate() {
        if position & 4095 == 0 {
            check_execution(context)?;
        }
        let value = evaluate_state(expression, row, state, context)?;
        let encoded_length = total_order_key_len(&value)?;
        let next_digit_bytes = digits.len().checked_add(encoded_length).ok_or_else(|| {
            Error::new(
                ErrorCode::ResultBudgetExceeded,
                "materialized sort-key payload size overflow",
            )
        })?;
        if next_digit_bytes > u32::MAX as usize {
            return Err(Error::new(
                ErrorCode::ResultBudgetExceeded,
                "materialized sort-key payload exceeds u32",
            ));
        }
        if next_digit_bytes > digits.capacity() {
            host_scratch.resize(
                prior_bytes
                    .checked_add(fixed_bytes)
                    .and_then(|bytes| bytes.checked_add(next_digit_bytes))
                    .ok_or_else(|| {
                        Error::new(
                            ErrorCode::ResultBudgetExceeded,
                            "materialized sort-key retained reservation overflow",
                        )
                    })?,
            )?;
            digits
                .try_reserve_exact(next_digit_bytes - digits.len())
                .map_err(|_| allocation_error())?;
            host_scratch.resize(
                prior_bytes
                    .checked_add(fixed_bytes)
                    .and_then(|bytes| bytes.checked_add(digits.capacity()))
                    .ok_or_else(|| {
                        Error::new(
                            ErrorCode::ResultBudgetExceeded,
                            "materialized sort-key retained capacity overflow",
                        )
                    })?,
            )?;
        }
        let appended = append_total_order_key(&mut digits, &value)?;
        debug_assert_eq!(appended, encoded_length);
        offsets.push(u32::try_from(digits.len()).map_err(|_| {
            Error::new(
                ErrorCode::ResultBudgetExceeded,
                "materialized sort-key payload exceeds u32",
            )
        })?);
        validity.push(u8::from(!matches!(
            &value,
            ResultValue::Scalar(ScalarValue::Null)
        )));
    }
    Ok(ResidentOrderColumn {
        offsets,
        digits,
        validity,
    })
}

fn reorder_rows(rows: Vec<Row>, positions: &[u32]) -> Result<Vec<Row>> {
    let mut source = rows.into_iter().map(Some).collect::<Vec<_>>();
    let mut output = Vec::with_capacity(positions.len());
    for position in positions {
        let position = *position as usize;
        let row = source
            .get_mut(position)
            .and_then(Option::take)
            .ok_or_else(|| {
                Error::new(
                    ErrorCode::CorruptStorage,
                    "resident sort returned a duplicate or out-of-range position",
                )
            })?;
        output.push(row);
    }
    Ok(output)
}

fn compare_sort_keys(left: &[ResultValue], right: &[ResultValue], items: &[SortItem]) -> Ordering {
    for ((left, right), item) in left.iter().zip(right).zip(items) {
        let order = total_compare(left, right);
        if order != Ordering::Equal {
            return if item.ascending {
                order
            } else {
                order.reverse()
            };
        }
    }
    Ordering::Equal
}

fn temporal_history(
    rows: Vec<Row>,
    history: &HistoryClause,
    state: &ExecutionState<'_>,
    context: &ExecutionContext<'_>,
) -> Result<Vec<Row>> {
    let temporal = &state.temporal;
    let property = state
        .graph
        .property(&history.target.property)
        .ok_or_else(|| Error::new(ErrorCode::QueryType, "temporal property is unknown"))?;
    let mut output = Vec::new();
    for row in rows {
        let from = timestamp_nanos(&evaluate_state(&history.from, &row, state, context)?)?;
        let to = timestamp_nanos(&evaluate_state(&history.to, &row, state, context)?)?;
        let binding = row
            .get(&history.target.variable)
            .ok_or_else(|| Error::new(ErrorCode::QueryType, "HISTORY target is missing"))?;
        let (kind, id, target) = temporal_target_for_binding(binding, property, state)?;
        let target = target.ok_or_else(|| {
            Error::new(
                ErrorCode::QueryType,
                "HISTORY property is not declared temporal for the entity target",
            )
        })?;
        for sample in temporal.history(kind, target, id, property, from, to, state.revision)? {
            let mut next = row.clone();
            next.insert(
                history.variable.clone(),
                BindingValue::Value(sample_result(&sample)),
            );
            output.push(next);
        }
    }
    Ok(output)
}

fn temporal_window(
    rows: Vec<Row>,
    window: &WindowClause,
    state: &ExecutionState<'_>,
    context: &ExecutionContext<'_>,
) -> Result<Vec<Row>> {
    let reference = rows.first().cloned().unwrap_or_default();
    let spec = resolved_window_spec(window, &reference, state, context)?;
    let timed_rows = rows
        .into_iter()
        .map(|row| {
            let time = timestamp_nanos(&evaluate_state(
                &window.event_expression,
                &row,
                state,
                context,
            )?)?;
            Ok((time, row))
        })
        .collect::<Result<Vec<_>>>()?;
    let Some(minimum) = timed_rows.iter().map(|(time, _)| *time).min() else {
        return Ok(Vec::new());
    };
    let maximum = timed_rows
        .iter()
        .map(|(time, _)| *time)
        .max()
        .unwrap_or(minimum)
        .checked_add(1)
        .ok_or_else(|| Error::new(ErrorCode::TemporalRange, "WINDOW time range overflow"))?;
    let boundaries = TemporalStore::window_boundaries(minimum, maximum, &spec)?;
    let mut output = Vec::new();
    for (start, end) in boundaries {
        let before = output.len();
        for (time, row) in &timed_rows {
            if *time >= start && *time < end {
                let mut row = row.clone();
                bind_bucket(&mut row, &window.variable, start, end);
                output.push(row);
            }
        }
        if spec.emit_empty && output.len() == before {
            let mut row = Row::new();
            bind_bucket(&mut row, &window.variable, start, end);
            row.insert(INTERNAL_WINDOW_EMPTY.to_owned(), BindingValue::Null);
            output.push(row);
        }
    }
    Ok(output)
}

fn temporal_history_window(
    rows: Vec<Row>,
    history: &HistoryClause,
    window: &WindowClause,
    state: &ExecutionState<'_>,
    context: &ExecutionContext<'_>,
) -> Result<Vec<Row>> {
    let property = state
        .graph
        .property(&history.target.property)
        .ok_or_else(|| Error::new(ErrorCode::QueryType, "temporal property is unknown"))?;
    let mut output = Vec::new();
    for row in rows {
        let from = timestamp_nanos(&evaluate_state(&history.from, &row, state, context)?)?;
        let to = timestamp_nanos(&evaluate_state(&history.to, &row, state, context)?)?;
        let binding = row
            .get(&history.target.variable)
            .ok_or_else(|| Error::new(ErrorCode::QueryType, "HISTORY target is missing"))?;
        let (kind, id, target) = temporal_target_for_binding(binding, property, state)?;
        let target = target.ok_or_else(|| {
            Error::new(
                ErrorCode::QueryType,
                "HISTORY property is not declared temporal for the entity target",
            )
        })?;
        let samples =
            state
                .temporal
                .history(kind, target, id, property, from, to, state.revision)?;
        let spec = resolved_window_spec(window, &row, state, context)?;
        for (start, end) in TemporalStore::window_boundaries(from, to, &spec)? {
            let before = output.len();
            for sample in &samples {
                if sample.event_time_nanos >= start && sample.event_time_nanos < end {
                    let mut next = row.clone();
                    next.insert(
                        history.variable.clone(),
                        BindingValue::Value(sample_result(sample)),
                    );
                    bind_bucket(&mut next, &window.variable, start, end);
                    output.push(next);
                }
            }
            if spec.emit_empty && output.len() == before {
                let mut next = row.clone();
                next.insert(history.variable.clone(), BindingValue::Null);
                bind_bucket(&mut next, &window.variable, start, end);
                next.insert(INTERNAL_WINDOW_EMPTY.to_owned(), BindingValue::Null);
                output.push(next);
            }
        }
    }
    Ok(output)
}

fn resolved_window_spec(
    window: &WindowClause,
    row: &Row,
    state: &ExecutionState<'_>,
    context: &ExecutionContext<'_>,
) -> Result<crate::graph::WindowSpec> {
    let width = duration_nanos(&evaluate_state(&window.width, row, state, context)?)?;
    let every = match &window.every {
        Some(value) => duration_nanos(&evaluate_state(value, row, state, context)?)?,
        None => width,
    };
    let mut spec = if window.kind == WindowSyntax::Tumbling {
        crate::graph::WindowSpec::tumbling(width)
    } else {
        crate::graph::WindowSpec::hopping(width, every)
    };
    spec.emit_empty = window.emit_empty;
    spec.timezone.clone_from(&window.timezone);
    if let Some(align) = &window.align {
        spec.align_nanos = timestamp_nanos(&evaluate_state(align, row, state, context)?)?;
    }
    Ok(spec)
}

fn sample_result(sample: &TemporalSample) -> ResultValue {
    ResultValue::Map(BTreeMap::from([
        (
            "time".to_owned(),
            ResultValue::Scalar(ScalarValue::Integer(sample.event_time_nanos)),
        ),
        (
            "value".to_owned(),
            ResultValue::Scalar(sample.value.clone()),
        ),
    ]))
}

fn bind_bucket(row: &mut Row, variable: &str, start: i64, end: i64) {
    row.insert(
        variable.to_owned(),
        BindingValue::Value(ResultValue::Map(BTreeMap::from([
            (
                "start".to_owned(),
                ResultValue::Scalar(ScalarValue::Integer(start)),
            ),
            (
                "end".to_owned(),
                ResultValue::Scalar(ScalarValue::Integer(end)),
            ),
        ]))),
    );
}

fn vector_search(
    rows: Vec<Row>,
    search: &SearchClause,
    access: VectorAccessPath,
    state: &mut ExecutionState<'_>,
    context: &ExecutionContext<'_>,
) -> Result<Vec<Row>> {
    vector_search_with_selection(rows, search, access, None, state, context)
}

fn vector_search_with_selection(
    rows: Vec<Row>,
    search: &SearchClause,
    access: VectorAccessPath,
    selection: Option<&crate::execution::ResidentNodePipelineRequest>,
    state: &mut ExecutionState<'_>,
    context: &ExecutionContext<'_>,
) -> Result<Vec<Row>> {
    let source = context
        .vector_indexes
        .get(&search.index)
        .ok_or_else(|| Error::new(ErrorCode::IndexUnavailable, "vector index is unavailable"))?;
    let limit = evaluate_non_negative_usize(&search.limit, rows.first(), state, context)?;
    let requested_access = match access {
        VectorAccessPath::IvfPq { .. } => ResidentVectorAccess::IvfPq,
        VectorAccessPath::Exact { .. } => ResidentVectorAccess::Exact,
        // The unoptimized/reference plan is always exact. IVF-PQ is legal only after the
        // optimizer records an explicit, recall- and memory-gated physical decision.
        VectorAccessPath::Unspecified => ResidentVectorAccess::Exact,
    };
    let mut output = Vec::new();
    for row in rows {
        check_execution(context)?;
        let input = match &search.input {
            SearchInput::Vector(value) => evaluate_state(value, &row, state, context)?,
            SearchInput::Text(value) => {
                let value = evaluate_state(value, &row, state, context)?;
                let ResultValue::Scalar(ScalarValue::String(text)) = value else {
                    return Err(Error::new(
                        ErrorCode::QueryType,
                        "SEARCH FOR TEXT requires a string",
                    ));
                };
                let embedding = context.text_embedding.ok_or_else(|| {
                    Error::new(
                        ErrorCode::EmbeddingUnavailable,
                        "local embedding artifact is not active",
                    )
                })?;
                ResultValue::Vector(embedding.embed_query(&text)?)
            }
        };
        let ResultValue::Vector(vector) = input else {
            return Err(Error::new(
                ErrorCode::QueryType,
                "SEARCH FOR VECTOR requires a vector",
            ));
        };
        let (hits, candidate_budget, build_generation, evidence_bookmark) =
            if let Some(backend) = current_backend(state, context) {
                let result = backend.search_vectors(
                    &ResidentVectorQuery {
                        project: context.project_id,
                        property: source.property,
                        layers: state.read_layers,
                        selection: selection.cloned(),
                        queries: vector,
                        query_count: 1,
                        limit,
                        access: requested_access,
                    },
                    &context.cancellation,
                )?;
                let expected_project = context.project_id;
                if result.project != expected_project
                    || result.bookmark != context.bookmark
                    || result.profile.profile_hash != source.profile_hash
                    || result.access != requested_access
                    || result.hits.len() != 1
                {
                    return Err(Error::new(
                        ErrorCode::CorruptStorage,
                        "resident vector evidence differs from its physical query contract",
                    ));
                }
                (
                    result.hits.into_iter().next().unwrap_or_default(),
                    result.candidate_budget,
                    result.build_generation,
                    result.bookmark,
                )
            } else if requested_access == ResidentVectorAccess::IvfPq {
                let approximate = source.approximate.ok_or_else(|| {
                    Error::new(
                        ErrorCode::IndexUnavailable,
                        "physical IVF-PQ access path is unavailable",
                    )
                })?;
                (
                    approximate.search(source.exact, &vector, limit)?,
                    u32::try_from(approximate.config().candidate_budget).unwrap_or(u32::MAX),
                    approximate.build_generation(),
                    context.bookmark,
                )
            } else {
                (
                    source.exact.exact_search(&vector, limit)?,
                    0,
                    [0_u8; 32],
                    context.bookmark,
                )
            };
        if hits.iter().any(|hit| !hit.score.is_finite()) {
            return Err(Error::new(
                ErrorCode::CorruptStorage,
                "vector search returned a non-finite exact score",
            ));
        }
        let mut visible_hits = Vec::with_capacity(hits.len());
        for hit in hits {
            check_execution(context)?;
            let Some(node) = state.graph.node(NodeId(hit.entity_id)) else {
                continue;
            };
            if !state.read_layers.contains_layer(node.layer()) {
                continue;
            }
            visible_hits.push(hit);
            state
                .dependencies
                .entities
                .insert(EntityDependency::Node(node.id()), node.revision());
            let mut next = row.clone();
            next.insert(search.variable.clone(), BindingValue::Node(node.dense()));
            next.insert(
                search.score_variable.clone(),
                BindingValue::Value(ResultValue::Scalar(ScalarValue::Float(OrderedFloat(
                    f64::from(hit.score),
                )))),
            );
            output.push(next);
        }
        if state.vector_searches.len() >= 128 || visible_hits.len() > 4_096 {
            return Err(Error::new(
                ErrorCode::ResultBudgetExceeded,
                "vector evidence trace exceeds its bounded execution budget",
            ));
        }
        state.vector_searches.push(VectorSearchTrace {
            index_name: search.index.clone(),
            profile_hash: source.profile_hash,
            access: requested_access,
            candidate_budget,
            build_generation,
            bookmark: evidence_bookmark,
            hits: visible_hits,
        });
    }
    Ok(output)
}

fn call_procedure(
    rows: Vec<Row>,
    call: &CallClause,
    state: &mut ExecutionState<'_>,
    context: &ExecutionContext<'_>,
    procedures: Option<&ProcedureCatalog>,
) -> Result<Vec<Row>> {
    check_execution(context)?;
    match validate_call(call, procedures, Some(&context.parameters))? {
        ResolvedProcedure::Builtin(signature) => {
            builtin_graph_procedure(rows, call, signature, state, context)
        }
        ResolvedProcedure::ExecutionScoped(procedure) => {
            execution_scoped_procedure(rows, call, procedure, state, context)
        }
    }
}

fn execution_scoped_procedure(
    rows: Vec<Row>,
    call: &CallClause,
    procedure: &ProcedureDefinition,
    state: &mut ExecutionState<'_>,
    context: &ExecutionContext<'_>,
) -> Result<Vec<Row>> {
    if current_backend(state, context)
        .is_some_and(|backend| backend.kind() != crate::execution::BackendKind::Cpu)
    {
        return Err(Error::new(
            ErrorCode::GpuAdmissionFailure,
            format!(
                "procedure {} has no native constant-relation implementation in the active GPU execution class",
                procedure.name()
            ),
        ));
    }

    let selected_columns = selected_execution_procedure_columns(call, procedure);
    state.final_columns = selected_columns
        .iter()
        .map(|(_, alias)| alias.clone())
        .collect();
    if rows.is_empty() {
        return Ok(Vec::new());
    }

    let mut result = Vec::new();
    for (input_index, input) in rows.into_iter().enumerate() {
        if input_index & 255 == 0 {
            check_execution(context)?;
        }
        let arguments = match call.argument_mode {
            CallArgumentMode::Explicit => call
                .arguments
                .iter()
                .map(|argument| evaluate_state(argument, &input, state, context))
                .collect::<Result<Vec<_>>>()?,
            CallArgumentMode::Implicit => procedure
                .inputs()
                .iter()
                .map(|field| {
                    context.parameters.get(&field.name).cloned().ok_or_else(|| {
                        Error::new(
                            ErrorCode::QueryType,
                            format!(
                                "MissingParameter: implicit procedure argument `${}` is missing",
                                field.name
                            ),
                        )
                    })
                })
                .collect::<Result<Vec<_>>>()?,
        };
        for output_values in procedure.execute(arguments)? {
            if result.len() >= context.max_result_rows {
                return Err(Error::new(
                    ErrorCode::ResultBudgetExceeded,
                    "procedure result exceeds the query row budget",
                ));
            }
            let mut output = input.clone();
            for (output_index, alias) in &selected_columns {
                let value = output_values.get(*output_index).cloned().ok_or_else(|| {
                    Error::internal("typed procedure result omitted a declared output")
                })?;
                output.insert(alias.clone(), BindingValue::Value(value));
            }
            result.push(output);
        }
    }
    check_execution(context)?;
    Ok(result)
}

fn selected_execution_procedure_columns(
    call: &CallClause,
    procedure: &ProcedureDefinition,
) -> Vec<(usize, String)> {
    if call.yield_mode == CallYieldMode::Explicit {
        return call
            .yields
            .iter()
            .filter_map(|item| {
                let Expression::Variable(name) = &item.expression else {
                    return None;
                };
                procedure
                    .outputs()
                    .iter()
                    .position(|field| field.name == *name)
                    .map(|index| (index, item.alias.clone().unwrap_or_else(|| name.clone())))
            })
            .collect();
    }
    if call.yield_mode == CallYieldMode::All || call.standalone {
        return procedure
            .outputs()
            .iter()
            .enumerate()
            .map(|(index, field)| (index, field.name.clone()))
            .collect();
    }
    Vec::new()
}

#[allow(clippy::too_many_lines)]
fn builtin_graph_procedure(
    rows: Vec<Row>,
    call: &CallClause,
    signature: &ProcedureSignature,
    state: &mut ExecutionState<'_>,
    context: &ExecutionContext<'_>,
) -> Result<Vec<Row>> {
    let name = call.name.join(".").to_ascii_lowercase();
    let selected_columns = selected_procedure_columns(call, signature);
    state.final_columns = selected_columns
        .iter()
        .map(|(_, alias)| alias.clone())
        .collect();
    if rows.is_empty() {
        return Ok(Vec::new());
    }
    let active_backend = state.resident_backend.as_deref().or(context.backend);
    let adaptive_cpu = !context.capabilities.require_native_execution
        && active_backend
            .is_some_and(|backend| backend.kind() == crate::execution::BackendKind::Metal)
        && adaptive_executor_for_graph_procedure(name.as_str(), state.graph.node_count())
            == AdaptiveExecutor::Cpu;
    let accelerator_active = !adaptive_cpu
        && active_backend
            .is_some_and(|backend| backend.kind() != crate::execution::BackendKind::Cpu);
    if accelerator_active {
        refresh_resident_overlay(state, context)?;
        let backend = current_backend(state, context).ok_or_else(|| {
            Error::new(
                ErrorCode::GpuAdmissionFailure,
                "active accelerator has no current resident graph for this graph procedure",
            )
        })?;
        if backend.kind() == crate::execution::BackendKind::Cpu {
            return Err(Error::new(
                ErrorCode::GpuAdmissionFailure,
                "active accelerator pinned a CPU resident graph for this graph procedure",
            ));
        }
        return builtin_resident_graph_procedure(
            rows,
            call,
            signature,
            name.as_str(),
            state,
            context,
            backend,
        );
    }
    let (outgoing, incoming, algorithm_nodes, ordinal_by_dense) =
        state.graph.algorithm_adjacency(state.read_layers)?;
    let selected_columns = selected_procedure_columns(call, signature);
    state.final_columns = selected_columns
        .iter()
        .map(|(_, alias)| alias.clone())
        .collect();
    if rows.is_empty() {
        return Ok(Vec::new());
    }
    let estimated_scratch = algorithm_scratch_bytes(
        algorithm_nodes.len(),
        outgoing.neighbors().len(),
        name.as_str(),
    );
    if !adaptive_cpu
        && let Some(backend) = current_backend(state, context)
        && estimated_scratch > backend.available_query_scratch_bytes()
    {
        return Err(Error::retryable(
            ErrorCode::GpuAdmissionFailure,
            "graph procedure scratch exceeds available execution memory",
            Some(10),
        ));
    }

    let mut result = Vec::new();
    for (input_index, input) in rows.into_iter().enumerate() {
        if input_index & 255 == 0 {
            check_execution(context)?;
        }
        let fields = execute_graph_procedure(
            name.as_str(),
            call,
            &input,
            state,
            context,
            &outgoing,
            &incoming,
            &algorithm_nodes,
            &ordinal_by_dense,
        )?;
        if fields.len() > context.max_result_rows.saturating_sub(result.len()) {
            return Err(Error::new(
                ErrorCode::ResultBudgetExceeded,
                "graph procedure result exceeds the query row budget",
            ));
        }
        for fields in fields {
            let mut output = input.clone();
            for (source, alias) in &selected_columns {
                let value = fields
                    .iter()
                    .find_map(|(name, value)| (*name == source.as_str()).then(|| value.clone()))
                    .ok_or_else(|| Error::internal("procedure output column is absent"))?;
                output.insert(alias.clone(), value);
            }
            result.push(output);
        }
    }
    check_execution(context)?;
    Ok(result)
}

#[allow(clippy::too_many_arguments)]
fn builtin_resident_graph_procedure(
    rows: Vec<Row>,
    call: &CallClause,
    signature: &ProcedureSignature,
    name: &str,
    state: &ExecutionState<'_>,
    context: &ExecutionContext<'_>,
    backend: &dyn ExecutionBackend,
) -> Result<Vec<Row>> {
    let selected_columns = selected_procedure_columns(call, signature);
    let mut output = Vec::new();
    for (input_index, input) in rows.into_iter().enumerate() {
        if input_index.is_multiple_of(256) {
            check_execution(context)?;
        }
        let procedure = match name {
            "graph.degree" => ResidentGraphProcedure::Degree,
            "graph.bfs" => ResidentGraphProcedure::BreadthFirst {
                source_dense: procedure_dense_argument(&call.arguments[0], &input, state, context)?,
            },
            "graph.dfs" => ResidentGraphProcedure::DepthFirst {
                source_dense: procedure_dense_argument(&call.arguments[0], &input, state, context)?,
            },
            "graph.shortestpath" => ResidentGraphProcedure::ShortestPath {
                source_dense: procedure_dense_argument(&call.arguments[0], &input, state, context)?,
                target_dense: procedure_dense_argument(&call.arguments[1], &input, state, context)?,
            },
            "graph.dijkstra" => {
                let source_dense =
                    procedure_dense_argument(&call.arguments[0], &input, state, context)?;
                dijkstra_weight_property(call, &input, state, context)?.map_or(
                    ResidentGraphProcedure::DijkstraUnit { source_dense },
                    |weight_property| ResidentGraphProcedure::DijkstraWeighted {
                        source_dense,
                        weight_property,
                    },
                )
            }
            "graph.wcc" => ResidentGraphProcedure::WeaklyConnectedComponents,
            "graph.scc" => ResidentGraphProcedure::StronglyConnectedComponents,
            "graph.louvain" => ResidentGraphProcedure::Louvain,
            "graph.pagerank" => {
                let config = page_rank_config(call, &input, state, context)?;
                ResidentGraphProcedure::PageRank {
                    damping: config.damping,
                    tolerance: config.tolerance,
                    max_iterations: config.max_iterations,
                }
            }
            "graph.trianglecount" => ResidentGraphProcedure::TriangleCount,
            "graph.clusteringcoefficient" => ResidentGraphProcedure::ClusteringCoefficient,
            "graph.kcore" => ResidentGraphProcedure::KCore,
            _ => {
                return Err(Error::internal(
                    "resident graph procedure dispatch is inconsistent",
                ));
            }
        };
        let result = backend.execute_graph_procedure(
            &ResidentGraphProcedureRequest {
                project: context.project_id,
                layers: state.read_layers,
                procedure,
                max_output_rows: context.max_result_rows.saturating_sub(output.len()),
                deadline: context.deadline,
            },
            &context.cancellation,
        )?;
        let fields = resident_procedure_fields(result)?;
        if fields.len() > context.max_result_rows.saturating_sub(output.len()) {
            return Err(Error::new(
                ErrorCode::ResultBudgetExceeded,
                "graph procedure result exceeds the query row budget",
            ));
        }
        for fields in fields {
            let mut row = input.clone();
            for (source, alias) in &selected_columns {
                let value = fields
                    .iter()
                    .find_map(|(name, value)| (*name == source.as_str()).then(|| value.clone()))
                    .ok_or_else(|| Error::internal("procedure output column is absent"))?;
                row.insert(alias.clone(), value);
            }
            output.push(row);
        }
    }
    check_execution(context)?;
    Ok(output)
}

#[allow(clippy::too_many_lines)]
fn resident_procedure_fields(result: ResidentGraphProcedureResult) -> Result<Vec<ProcedureFields>> {
    match result {
        ResidentGraphProcedureResult::Degree {
            node_rows,
            out_degree,
            in_degree,
        } => {
            if node_rows.len() != out_degree.len() || node_rows.len() != in_degree.len() {
                return Err(Error::new(
                    ErrorCode::CorruptStorage,
                    "resident degree columns have different lengths",
                ));
            }
            node_rows
                .into_iter()
                .zip(out_degree)
                .zip(in_degree)
                .map(|((node, outgoing), incoming)| {
                    Ok(vec![
                        ("node", BindingValue::Node(node)),
                        ("outDegree", integer_binding(outgoing as usize)?),
                        ("inDegree", integer_binding(incoming as usize)?),
                        (
                            "degree",
                            integer_binding_u64(u64::from(outgoing) + u64::from(incoming))?,
                        ),
                    ])
                })
                .collect()
        }
        ResidentGraphProcedureResult::BreadthFirst {
            node_rows,
            distance,
        } => {
            if node_rows.len() != distance.len() {
                return Err(Error::new(
                    ErrorCode::CorruptStorage,
                    "resident BFS columns have different lengths",
                ));
            }
            node_rows
                .into_iter()
                .zip(distance)
                .map(|(node, distance)| {
                    Ok(vec![
                        ("node", BindingValue::Node(node)),
                        ("distance", integer_binding(distance as usize)?),
                    ])
                })
                .collect()
        }
        ResidentGraphProcedureResult::DepthFirst { node_rows, order } => {
            if node_rows.len() != order.len() {
                return Err(Error::new(
                    ErrorCode::CorruptStorage,
                    "resident DFS columns have different lengths",
                ));
            }
            node_rows
                .into_iter()
                .zip(order)
                .map(|(node, order)| {
                    Ok(vec![
                        ("node", BindingValue::Node(node)),
                        ("order", integer_binding(order as usize)?),
                    ])
                })
                .collect()
        }
        ResidentGraphProcedureResult::ShortestPath {
            node_rows,
            edge_rows,
            cost,
        } => {
            if node_rows.is_empty() && edge_rows.is_empty() && cost == 0 {
                return Ok(Vec::new());
            }
            if node_rows.is_empty()
                || edge_rows.len().saturating_add(1) != node_rows.len()
                || usize::try_from(cost).ok() != Some(edge_rows.len())
            {
                return Err(Error::new(
                    ErrorCode::CorruptStorage,
                    "resident shortest path has an invalid shape",
                ));
            }
            Ok(vec![vec![
                (
                    "path",
                    BindingValue::Path {
                        nodes: node_rows,
                        relationships: edge_rows,
                    },
                ),
                ("cost", integer_binding(cost as usize)?),
            ]])
        }
        ResidentGraphProcedureResult::Dijkstra {
            node_rows,
            cost,
            predecessor,
        } => {
            if node_rows.len() != cost.len() || node_rows.len() != predecessor.len() {
                return Err(Error::new(
                    ErrorCode::CorruptStorage,
                    "resident Dijkstra columns have different lengths",
                ));
            }
            Ok(node_rows
                .into_iter()
                .zip(cost)
                .zip(predecessor)
                .map(|((node, cost), predecessor)| {
                    vec![
                        ("node", BindingValue::Node(node)),
                        ("cost", float_binding(cost)),
                        (
                            "predecessor",
                            predecessor.map_or(BindingValue::Null, BindingValue::Node),
                        ),
                    ]
                })
                .collect())
        }
        ResidentGraphProcedureResult::Components {
            node_rows,
            component,
        } => {
            if node_rows.len() != component.len() {
                return Err(Error::new(
                    ErrorCode::CorruptStorage,
                    "resident component columns have different lengths",
                ));
            }
            node_rows
                .into_iter()
                .zip(component)
                .map(|(node, component)| {
                    Ok(vec![
                        ("node", BindingValue::Node(node)),
                        ("component", integer_binding(component as usize)?),
                    ])
                })
                .collect()
        }
        ResidentGraphProcedureResult::Louvain {
            node_rows,
            community,
        } => {
            if node_rows.len() != community.len() {
                return Err(Error::new(
                    ErrorCode::CorruptStorage,
                    "resident Louvain columns have different lengths",
                ));
            }
            node_rows
                .into_iter()
                .zip(community)
                .map(|(node, community)| {
                    Ok(vec![
                        ("node", BindingValue::Node(node)),
                        ("community", integer_binding(community as usize)?),
                    ])
                })
                .collect()
        }
        ResidentGraphProcedureResult::PageRank { node_rows, score } => {
            if node_rows.len() != score.len() {
                return Err(Error::new(
                    ErrorCode::CorruptStorage,
                    "resident PageRank columns have different lengths",
                ));
            }
            Ok(node_rows
                .into_iter()
                .zip(score)
                .map(|(node, score)| {
                    vec![
                        ("node", BindingValue::Node(node)),
                        ("score", float_binding(score)),
                    ]
                })
                .collect())
        }
        ResidentGraphProcedureResult::TriangleCount { count } => {
            Ok(vec![vec![("triangleCount", integer_binding_u64(count)?)]])
        }
        ResidentGraphProcedureResult::ClusteringCoefficient {
            node_rows,
            coefficient,
        } => {
            if node_rows.len() != coefficient.len() {
                return Err(Error::new(
                    ErrorCode::CorruptStorage,
                    "resident clustering-coefficient columns have different lengths",
                ));
            }
            Ok(node_rows
                .into_iter()
                .zip(coefficient)
                .map(|(node, coefficient)| {
                    vec![
                        ("node", BindingValue::Node(node)),
                        ("coefficient", float_binding(coefficient)),
                    ]
                })
                .collect())
        }
        ResidentGraphProcedureResult::KCore { node_rows, core } => {
            if node_rows.len() != core.len() {
                return Err(Error::new(
                    ErrorCode::CorruptStorage,
                    "resident k-core columns have different lengths",
                ));
            }
            node_rows
                .into_iter()
                .zip(core)
                .map(|(node, core)| {
                    Ok(vec![
                        ("node", BindingValue::Node(node)),
                        ("core", integer_binding(core as usize)?),
                    ])
                })
                .collect()
        }
    }
}

#[cfg(test)]
mod resident_procedure_field_tests {
    use super::*;

    #[test]
    fn resident_degree_total_does_not_saturate_at_u32() -> Result<()> {
        let [fields] = resident_procedure_fields(ResidentGraphProcedureResult::Degree {
            node_rows: vec![7],
            out_degree: vec![u32::MAX],
            in_degree: vec![u32::MAX],
        })?
        .try_into()
        .map_err(|_| Error::internal("degree field test returned the wrong row count"))?;
        let Some(("degree", BindingValue::Value(ResultValue::Scalar(ScalarValue::Integer(total))))) =
            fields.get(3)
        else {
            return Err(Error::internal(
                "degree field test returned the wrong shape",
            ));
        };
        assert_eq!(*total, i64::from(u32::MAX) * 2);
        Ok(())
    }
}

fn procedure_dense_argument(
    expression: &Expression,
    input: &Row,
    state: &ExecutionState<'_>,
    context: &ExecutionContext<'_>,
) -> Result<u32> {
    let value = evaluate_state(expression, input, state, context)?;
    let id = match value {
        ResultValue::Node(node) => node.id,
        ResultValue::Scalar(ScalarValue::Integer(value)) if value >= 0 => {
            NodeId(value.cast_unsigned())
        }
        _ => {
            return Err(Error::new(
                ErrorCode::QueryType,
                "graph procedure node argument must be a node or non-negative stable node ID",
            ));
        }
    };
    state
        .graph
        .node(id)
        .filter(|node| state.read_layers.contains_layer(node.layer()))
        .map(super::view::NodeReadView::dense)
        .ok_or_else(|| Error::new(ErrorCode::QueryType, "graph procedure node is not visible"))
}

type ProcedureFields = Vec<(&'static str, BindingValue)>;

#[allow(clippy::too_many_arguments)]
fn execute_graph_procedure(
    name: &str,
    call: &CallClause,
    input: &Row,
    state: &ExecutionState<'_>,
    context: &ExecutionContext<'_>,
    outgoing: &crate::graph::Csr,
    incoming: &crate::graph::Csr,
    algorithm_nodes: &[u32],
    ordinal_by_dense: &[u32],
) -> Result<Vec<ProcedureFields>> {
    match name {
        "graph.degree" => algorithm_nodes
            .iter()
            .enumerate()
            .map(|(ordinal, dense)| {
                let ordinal = u32::try_from(ordinal).map_err(|_| {
                    Error::new(
                        ErrorCode::ResultBudgetExceeded,
                        "algorithm node ordinal space exhausted",
                    )
                })?;
                let out_degree = adjacency_degree(outgoing, ordinal)?;
                let in_degree = adjacency_degree(incoming, ordinal)?;
                Ok(vec![
                    ("node", BindingValue::Node(*dense)),
                    ("outDegree", integer_binding(out_degree)?),
                    ("inDegree", integer_binding(in_degree)?),
                    (
                        "degree",
                        integer_binding(out_degree.saturating_add(in_degree))?,
                    ),
                ])
            })
            .collect(),
        "graph.bfs" => {
            let source = procedure_node_argument(
                &call.arguments[0],
                input,
                state,
                context,
                ordinal_by_dense,
            )?;
            let distances = bfs_cancellable(outgoing, source, || check_execution(context))?;
            Ok(distances
                .into_iter()
                .enumerate()
                .filter_map(|(ordinal, distance)| {
                    Some(vec![
                        ("node", BindingValue::Node(*algorithm_nodes.get(ordinal)?)),
                        (
                            "distance",
                            integer_binding(usize::try_from(distance?).ok()?).ok()?,
                        ),
                    ])
                })
                .collect())
        }
        "graph.dfs" => {
            let source = procedure_node_argument(
                &call.arguments[0],
                input,
                state,
                context,
                ordinal_by_dense,
            )?;
            let order = dfs_cancellable(outgoing, source, || check_execution(context))?;
            order
                .into_iter()
                .enumerate()
                .map(|(position, ordinal)| {
                    let dense = *algorithm_nodes
                        .get(ordinal as usize)
                        .ok_or_else(|| Error::internal("DFS returned an invalid node ordinal"))?;
                    Ok(vec![
                        ("node", BindingValue::Node(dense)),
                        ("order", integer_binding(position)?),
                    ])
                })
                .collect()
        }
        "graph.shortestpath" => {
            let source = procedure_node_argument(
                &call.arguments[0],
                input,
                state,
                context,
                ordinal_by_dense,
            )?;
            let target = procedure_node_argument(
                &call.arguments[1],
                input,
                state,
                context,
                ordinal_by_dense,
            )?;
            let Some(path) =
                shortest_path_cancellable(outgoing, source, target, || check_execution(context))?
            else {
                return Ok(Vec::new());
            };
            let relationships = path
                .windows(2)
                .map(|pair| {
                    outgoing
                        .row(pair[0])
                        .and_then(|mut edges| {
                            edges.find_map(|(target, edge)| (target == pair[1]).then_some(edge))
                        })
                        .ok_or_else(|| Error::internal("shortest path edge is absent"))
                })
                .collect::<Result<Vec<_>>>()?;
            let nodes = path
                .iter()
                .map(|ordinal| {
                    algorithm_nodes
                        .get(*ordinal as usize)
                        .copied()
                        .ok_or_else(|| Error::internal("shortest path node is absent"))
                })
                .collect::<Result<Vec<_>>>()?;
            Ok(vec![vec![
                (
                    "path",
                    BindingValue::Path {
                        nodes,
                        relationships,
                    },
                ),
                ("cost", integer_binding(path.len().saturating_sub(1))?),
            ]])
        }
        "graph.dijkstra" => {
            let source = procedure_node_argument(
                &call.arguments[0],
                input,
                state,
                context,
                ordinal_by_dense,
            )?;
            let weight_property = dijkstra_weight_property(call, input, state, context)?;
            let result = dijkstra_cancellable(
                outgoing,
                source,
                |edge| edge_weight(state, edge, weight_property),
                || check_execution(context),
            )?;
            result
                .distance
                .into_iter()
                .zip(result.predecessor)
                .enumerate()
                .filter_map(|(ordinal, (cost, predecessor))| {
                    let cost = cost?;
                    Some((ordinal, cost, predecessor))
                })
                .map(|(ordinal, cost, predecessor)| {
                    let dense = *algorithm_nodes.get(ordinal).ok_or_else(|| {
                        Error::internal("Dijkstra returned an invalid node ordinal")
                    })?;
                    let predecessor = predecessor
                        .and_then(|ordinal| algorithm_nodes.get(ordinal as usize).copied())
                        .map_or(BindingValue::Null, BindingValue::Node);
                    Ok(vec![
                        ("node", BindingValue::Node(dense)),
                        ("cost", float_binding(cost)),
                        ("predecessor", predecessor),
                    ])
                })
                .collect()
        }
        "graph.wcc" | "graph.scc" | "graph.louvain" => {
            let components = match name {
                "graph.wcc" => weakly_connected_components_cancellable(outgoing, incoming, || {
                    check_execution(context)
                })?,
                "graph.scc" => {
                    strongly_connected_components_cancellable(outgoing, incoming, || {
                        check_execution(context)
                    })?
                }
                _ => louvain_communities_cancellable(outgoing, incoming, || {
                    check_execution(context)
                })?,
            };
            let output_name = if name == "graph.louvain" {
                "community"
            } else {
                "component"
            };
            components
                .component
                .into_iter()
                .enumerate()
                .map(|(ordinal, component)| {
                    let dense = *algorithm_nodes.get(ordinal).ok_or_else(|| {
                        Error::internal("component algorithm returned an invalid node ordinal")
                    })?;
                    Ok(vec![
                        ("node", BindingValue::Node(dense)),
                        (output_name, integer_binding(component as usize)?),
                    ])
                })
                .collect()
        }
        "graph.pagerank" => {
            let config = page_rank_config(call, input, state, context)?;
            let ranks = page_rank_cancellable(outgoing, config, || check_execution(context))?;
            ranks
                .into_iter()
                .enumerate()
                .map(|(ordinal, rank)| {
                    let dense = *algorithm_nodes.get(ordinal).ok_or_else(|| {
                        Error::internal("PageRank returned an invalid node ordinal")
                    })?;
                    Ok(vec![
                        ("node", BindingValue::Node(dense)),
                        ("score", float_binding(rank)),
                    ])
                })
                .collect()
        }
        "graph.trianglecount" => Ok(vec![vec![(
            "triangleCount",
            integer_binding_u64(triangle_count_cancellable(outgoing, incoming, || {
                check_execution(context)
            })?)?,
        )]]),
        "graph.clusteringcoefficient" => {
            clustering_coefficients_cancellable(outgoing, incoming, || check_execution(context))?
                .into_iter()
                .enumerate()
                .map(|(ordinal, coefficient)| {
                    let dense = *algorithm_nodes.get(ordinal).ok_or_else(|| {
                        Error::internal("clustering coefficient returned an invalid node ordinal")
                    })?;
                    Ok(vec![
                        ("node", BindingValue::Node(dense)),
                        ("coefficient", float_binding(coefficient)),
                    ])
                })
                .collect()
        }
        "graph.kcore" => k_core_cancellable(outgoing, incoming, || check_execution(context))?
            .into_iter()
            .enumerate()
            .map(|(ordinal, core)| {
                let dense = *algorithm_nodes
                    .get(ordinal)
                    .ok_or_else(|| Error::internal("k-core returned an invalid node ordinal"))?;
                Ok(vec![
                    ("node", BindingValue::Node(dense)),
                    ("core", integer_binding(core as usize)?),
                ])
            })
            .collect(),
        _ => Err(Error::internal(
            "validated graph procedure is not executable",
        )),
    }
}

fn selected_procedure_columns(
    call: &CallClause,
    signature: &ProcedureSignature,
) -> Vec<(String, String)> {
    if call.yield_mode == CallYieldMode::All
        || (call.standalone && call.yield_mode == CallYieldMode::Omitted)
    {
        return signature
            .outputs
            .iter()
            .map(|name| ((*name).to_owned(), (*name).to_owned()))
            .collect();
    }
    if call.yield_mode == CallYieldMode::Omitted {
        return Vec::new();
    }
    call.yields
        .iter()
        .filter_map(|item| {
            let Expression::Variable(name) = &item.expression else {
                return None;
            };
            Some((
                name.clone(),
                item.alias.clone().unwrap_or_else(|| name.clone()),
            ))
        })
        .collect()
}

fn procedure_node_argument(
    expression: &Expression,
    input: &Row,
    state: &ExecutionState<'_>,
    context: &ExecutionContext<'_>,
    ordinal_by_dense: &[u32],
) -> Result<u32> {
    let value = evaluate_state(expression, input, state, context)?;
    let id = match value {
        ResultValue::Node(node) => node.id,
        ResultValue::Scalar(ScalarValue::Integer(value)) if value >= 0 => NodeId(value as u64),
        _ => {
            return Err(Error::new(
                ErrorCode::QueryType,
                "graph procedure node argument must be a node or non-negative stable node ID",
            ));
        }
    };
    let dense = state
        .graph
        .node(id)
        .filter(|node| state.read_layers.contains_layer(node.layer()))
        .map(|node| node.dense())
        .ok_or_else(|| Error::new(ErrorCode::QueryType, "graph procedure node is not visible"))?;
    ordinal_by_dense
        .get(dense as usize)
        .copied()
        .filter(|ordinal| *ordinal != u32::MAX)
        .ok_or_else(|| Error::internal("visible graph procedure node has no algorithm ordinal"))
}

fn page_rank_config(
    call: &CallClause,
    input: &Row,
    state: &ExecutionState<'_>,
    context: &ExecutionContext<'_>,
) -> Result<PageRankConfig> {
    if call.arguments.is_empty() {
        return Ok(PageRankConfig::default());
    }
    let damping = numeric(&evaluate_state(&call.arguments[0], input, state, context)?)?;
    let tolerance = numeric(&evaluate_state(&call.arguments[1], input, state, context)?)?;
    let maximum = evaluate_state(&call.arguments[2], input, state, context)?;
    let ResultValue::Scalar(ScalarValue::Integer(maximum)) = maximum else {
        return Err(Error::new(
            ErrorCode::QueryType,
            "graph.pagerank maximum iterations must be an integer",
        ));
    };
    let max_iterations = usize::try_from(maximum).map_err(|_| {
        Error::new(
            ErrorCode::QueryType,
            "graph.pagerank maximum iterations must be positive",
        )
    })?;
    Ok(PageRankConfig {
        damping,
        tolerance,
        max_iterations,
    })
}

fn dijkstra_weight_property(
    call: &CallClause,
    input: &Row,
    state: &ExecutionState<'_>,
    context: &ExecutionContext<'_>,
) -> Result<Option<PropertyId>> {
    let Some(expression) = call.arguments.get(1) else {
        return Ok(None);
    };
    let value = evaluate_state(expression, input, state, context)?;
    let ResultValue::Scalar(ScalarValue::String(name)) = value else {
        return Err(Error::new(
            ErrorCode::QueryType,
            "graph.dijkstra weight property must be a string",
        ));
    };
    state.graph.property(&name).map(Some).ok_or_else(|| {
        Error::new(
            ErrorCode::QueryType,
            "graph.dijkstra weight property is unknown",
        )
    })
}

fn edge_weight(state: &ExecutionState<'_>, edge: u32, property: Option<PropertyId>) -> Result<f64> {
    let Some(property) = property else {
        return Ok(1.0);
    };
    let edge = state
        .graph
        .edge_dense(edge)
        .ok_or_else(|| Error::internal("Dijkstra edge is not visible"))?;
    match edge.property(property) {
        Some(ScalarValue::Integer(value)) => Ok(value as f64),
        Some(ScalarValue::Float(value)) => Ok(value.into_inner()),
        _ => Err(Error::new(
            ErrorCode::QueryType,
            "graph.dijkstra weight must be a present numeric relationship property",
        )),
    }
}

fn adjacency_degree(adjacency: &crate::graph::Csr, node: u32) -> Result<usize> {
    let start = *adjacency
        .offsets()
        .get(node as usize)
        .ok_or_else(|| Error::internal("algorithm adjacency row is absent"))?
        as usize;
    let end = *adjacency
        .offsets()
        .get(node as usize + 1)
        .ok_or_else(|| Error::internal("algorithm adjacency row end is absent"))?
        as usize;
    Ok(end.saturating_sub(start))
}

fn algorithm_scratch_bytes(nodes: usize, edges: usize, name: &str) -> usize {
    let per_node = match name {
        "graph.louvain" => 96,
        "graph.scc" | "graph.wcc" | "graph.kcore" => 24,
        "graph.pagerank" | "graph.dijkstra" => 32,
        _ => 16,
    };
    nodes
        .saturating_mul(per_node)
        .saturating_add(edges.saturating_mul(16))
}

fn integer_binding(value: usize) -> Result<BindingValue> {
    let value = i64::try_from(value)
        .map_err(|_| Error::new(ErrorCode::ResultBudgetExceeded, "integer result overflow"))?;
    Ok(BindingValue::Value(ResultValue::Scalar(
        ScalarValue::Integer(value),
    )))
}

fn integer_binding_u64(value: u64) -> Result<BindingValue> {
    let value = i64::try_from(value)
        .map_err(|_| Error::new(ErrorCode::ResultBudgetExceeded, "integer result overflow"))?;
    Ok(BindingValue::Value(ResultValue::Scalar(
        ScalarValue::Integer(value),
    )))
}

fn float_binding(value: f64) -> BindingValue {
    BindingValue::Value(ResultValue::Scalar(ScalarValue::Float(OrderedFloat(value))))
}

fn evaluate_state(
    expression: &Expression,
    row: &Row,
    state: &ExecutionState<'_>,
    context: &ExecutionContext<'_>,
) -> Result<ResultValue> {
    evaluate_with_temporal(
        expression,
        row,
        &state.graph,
        context,
        Some(&state.temporal),
        state.revision,
    )
}

fn evaluate_binding_state(
    expression: &Expression,
    row: &Row,
    state: &ExecutionState<'_>,
    context: &ExecutionContext<'_>,
) -> Result<BindingValue> {
    evaluate_binding_with_temporal(
        expression,
        row,
        &state.graph,
        context,
        Some(&state.temporal),
        state.revision,
    )
}

#[allow(clippy::too_many_arguments)]
fn evaluate_binding_with_temporal(
    expression: &Expression,
    row: &Row,
    graph: &GraphReadView<'_>,
    context: &ExecutionContext<'_>,
    temporal: Option<&TemporalReadView<'_>>,
    visible_index: u64,
) -> Result<BindingValue> {
    match expression {
        Expression::Literal(value) => Ok(BindingValue::Value(ResultValue::Scalar(value.clone()))),
        Expression::Parameter(name) => context
            .parameters
            .get(name)
            .cloned()
            .map(untrusted_result_binding)
            .ok_or_else(|| {
                Error::new(
                    ErrorCode::QueryType,
                    format!("parameter `${name}` is missing"),
                )
            }),
        Expression::Variable(name) => Ok(row
            .get(name)
            .cloned()
            .map(normalize_untrusted_container)
            .unwrap_or(BindingValue::Null)),
        Expression::Property(source, property) => {
            let source = evaluate_binding_with_temporal(
                source,
                row,
                graph,
                context,
                temporal,
                visible_index,
            )?;
            match source {
                BindingValue::Map(values) => {
                    Ok(values.get(property).cloned().unwrap_or(BindingValue::Null))
                }
                source if binding_is_null(&source) => Ok(BindingValue::Null),
                _ => {
                    evaluate_with_temporal(expression, row, graph, context, temporal, visible_index)
                        .map(untrusted_result_binding)
                }
            }
        }
        Expression::List(values) => Ok(BindingValue::List(
            values
                .iter()
                .map(|value| {
                    evaluate_binding_with_temporal(
                        value,
                        row,
                        graph,
                        context,
                        temporal,
                        visible_index,
                    )
                })
                .collect::<Result<_>>()?,
        )),
        Expression::Map(values) => Ok(BindingValue::Map(
            values
                .iter()
                .map(|(name, value)| {
                    Ok((
                        name.clone(),
                        evaluate_binding_with_temporal(
                            value,
                            row,
                            graph,
                            context,
                            temporal,
                            visible_index,
                        )?,
                    ))
                })
                .collect::<Result<_>>()?,
        )),
        Expression::MapProjection { source, items } => evaluate_binding_map_projection(
            source,
            items,
            row,
            graph,
            context,
            temporal,
            visible_index,
        ),
        Expression::Case {
            operand,
            alternatives,
            default,
        } => evaluate_binding_case(
            operand.as_deref(),
            alternatives,
            default.as_deref(),
            row,
            graph,
            context,
            temporal,
            visible_index,
        ),
        Expression::ListComprehension {
            variable,
            list,
            predicate,
            projection,
        } => evaluate_binding_list_comprehension(
            variable,
            list,
            predicate.as_deref(),
            projection.as_deref(),
            row,
            graph,
            context,
            temporal,
            visible_index,
        ),
        Expression::Reduce {
            accumulator,
            initial,
            variable,
            list,
            expression,
        } => evaluate_binding_reduce(
            accumulator,
            initial,
            variable,
            list,
            expression,
            row,
            graph,
            context,
            temporal,
            visible_index,
        ),
        Expression::Function {
            name, arguments, ..
        } if matches!(
            name.join(".").to_ascii_lowercase().as_str(),
            "coalesce"
                | "head"
                | "last"
                | "tail"
                | "reverse"
                | "tolist"
                | "nodes"
                | "relationships"
                | "startnode"
                | "endnode"
                | "labels"
                | "type"
        ) =>
        {
            evaluate_binding_function(
                &name.join(".").to_ascii_lowercase(),
                arguments,
                row,
                graph,
                context,
                temporal,
                visible_index,
            )
        }
        Expression::Unary { operation, operand } => {
            let operand = evaluate_binding_with_temporal(
                operand,
                row,
                graph,
                context,
                temporal,
                visible_index,
            )?;
            evaluate_unary(*operation, binding_to_result(&operand, graph)?)
                .map(untrusted_result_binding)
        }
        Expression::Binary {
            left,
            operation,
            right,
        } => {
            let left =
                evaluate_binding_with_temporal(left, row, graph, context, temporal, visible_index)?;
            let right = evaluate_binding_with_temporal(
                right,
                row,
                graph,
                context,
                temporal,
                visible_index,
            )?;
            evaluate_binding_binary(left, *operation, right, graph)
        }
        Expression::IsNull {
            expression,
            negated,
        } => {
            let null = binding_is_null(&evaluate_binding_with_temporal(
                expression,
                row,
                graph,
                context,
                temporal,
                visible_index,
            )?);
            Ok(BindingValue::Value(ResultValue::Scalar(
                ScalarValue::Boolean(if *negated { !null } else { null }),
            )))
        }
        Expression::Index { expression, index } => {
            let value = evaluate_binding_with_temporal(
                expression,
                row,
                graph,
                context,
                temporal,
                visible_index,
            )?;
            let index =
                evaluate_with_temporal(index, row, graph, context, temporal, visible_index)?;
            evaluate_binding_index(value, index, graph)
        }
        Expression::Slice {
            expression,
            start,
            end,
        } => evaluate_binding_slice(
            expression,
            start.as_deref(),
            end.as_deref(),
            row,
            graph,
            context,
            temporal,
            visible_index,
        ),
        _ => evaluate_with_temporal(expression, row, graph, context, temporal, visible_index)
            .map(untrusted_result_binding),
    }
}

#[allow(clippy::too_many_arguments)]
fn evaluate_binding_map_projection(
    source: &Expression,
    items: &[MapProjectionItem],
    row: &Row,
    graph: &GraphReadView<'_>,
    context: &ExecutionContext<'_>,
    temporal: Option<&TemporalReadView<'_>>,
    visible_index: u64,
) -> Result<BindingValue> {
    let source =
        evaluate_binding_with_temporal(source, row, graph, context, temporal, visible_index)?;
    if binding_is_null(&source) {
        return Ok(BindingValue::Null);
    }
    let source_properties = match source {
        BindingValue::Map(values) => values,
        source @ (BindingValue::Node(_)
        | BindingValue::Relationship(_)
        | BindingValue::Value(ResultValue::Node(_))
        | BindingValue::Value(ResultValue::Relationship(_))) => {
            let properties = match binding_to_result(&source, graph)? {
                ResultValue::Node(node) => node.properties,
                ResultValue::Relationship(edge) => edge.properties,
                _ => {
                    return Err(Error::internal(
                        "map projection entity binding materialized as the wrong value type",
                    ));
                }
            };
            properties
                .into_iter()
                .map(|(name, value)| {
                    ResultValue::from_property(value)
                        .map(untrusted_result_binding)
                        .map(|value| (name, value))
                })
                .collect::<Result<BTreeMap<_, _>>>()?
        }
        _ => {
            return Err(Error::new(
                ErrorCode::QueryType,
                "map projection source must be a map, node, or relationship",
            ));
        }
    };
    let mut projected = BTreeMap::new();
    for item in items {
        match item {
            MapProjectionItem::AllProperties => projected.extend(source_properties.clone()),
            MapProjectionItem::Property(name) => {
                projected.insert(
                    name.clone(),
                    source_properties
                        .get(name)
                        .cloned()
                        .unwrap_or(BindingValue::Null),
                );
            }
            MapProjectionItem::Variable(name) => {
                projected.insert(
                    name.clone(),
                    row.get(name)
                        .cloned()
                        .map(normalize_untrusted_container)
                        .unwrap_or(BindingValue::Null),
                );
            }
            MapProjectionItem::Entry(name, expression) => {
                projected.insert(
                    name.clone(),
                    evaluate_binding_with_temporal(
                        expression,
                        row,
                        graph,
                        context,
                        temporal,
                        visible_index,
                    )?,
                );
            }
        }
    }
    Ok(BindingValue::Map(projected))
}

#[allow(clippy::too_many_arguments)]
fn evaluate_binding_case(
    operand: Option<&Expression>,
    alternatives: &[CaseAlternative],
    default: Option<&Expression>,
    row: &Row,
    graph: &GraphReadView<'_>,
    context: &ExecutionContext<'_>,
    temporal: Option<&TemporalReadView<'_>>,
    visible_index: u64,
) -> Result<BindingValue> {
    let operand = operand
        .map(|operand| {
            evaluate_binding_with_temporal(operand, row, graph, context, temporal, visible_index)
                .and_then(|value| binding_to_result(&value, graph))
        })
        .transpose()?;
    for alternative in alternatives {
        let when = evaluate_with_temporal(
            &alternative.when,
            row,
            graph,
            context,
            temporal,
            visible_index,
        )?;
        let selected = match &operand {
            Some(operand) => equal(operand, &when)? == Truth::True,
            None => truth(&when)? == Truth::True,
        };
        if selected {
            return evaluate_binding_with_temporal(
                &alternative.then,
                row,
                graph,
                context,
                temporal,
                visible_index,
            );
        }
    }
    default.map_or(Ok(BindingValue::Null), |default| {
        evaluate_binding_with_temporal(default, row, graph, context, temporal, visible_index)
    })
}

#[allow(clippy::too_many_arguments)]
fn evaluate_binding_list_comprehension(
    variable: &str,
    list: &Expression,
    predicate: Option<&Expression>,
    projection: Option<&Expression>,
    row: &Row,
    graph: &GraphReadView<'_>,
    context: &ExecutionContext<'_>,
    temporal: Option<&TemporalReadView<'_>>,
    visible_index: u64,
) -> Result<BindingValue> {
    let list = evaluate_binding_with_temporal(list, row, graph, context, temporal, visible_index)?;
    let values = match normalize_untrusted_container(list) {
        BindingValue::List(values) => values,
        value if binding_is_null(&value) => return Ok(BindingValue::Null),
        _ => {
            return Err(Error::new(
                ErrorCode::QueryType,
                "list comprehension input must be a list",
            ));
        }
    };
    let mut output = Vec::with_capacity(values.len());
    for value in values {
        let mut nested = row.clone();
        nested.insert(variable.to_owned(), value.clone());
        if let Some(predicate) = predicate {
            let predicate = evaluate_with_temporal(
                predicate,
                &nested,
                graph,
                context,
                temporal,
                visible_index,
            )?;
            if truth(&predicate)? != Truth::True {
                continue;
            }
        }
        output.push(match projection {
            Some(projection) => evaluate_binding_with_temporal(
                projection,
                &nested,
                graph,
                context,
                temporal,
                visible_index,
            )?,
            None => value,
        });
    }
    Ok(BindingValue::List(output))
}

#[allow(clippy::too_many_arguments)]
fn evaluate_binding_reduce(
    accumulator: &str,
    initial: &Expression,
    variable: &str,
    list: &Expression,
    expression: &Expression,
    row: &Row,
    graph: &GraphReadView<'_>,
    context: &ExecutionContext<'_>,
    temporal: Option<&TemporalReadView<'_>>,
    visible_index: u64,
) -> Result<BindingValue> {
    let mut result =
        evaluate_binding_with_temporal(initial, row, graph, context, temporal, visible_index)?;
    let list = evaluate_binding_with_temporal(list, row, graph, context, temporal, visible_index)?;
    let values = match normalize_untrusted_container(list) {
        BindingValue::List(values) => values,
        value if binding_is_null(&value) => return Ok(BindingValue::Null),
        _ => {
            return Err(Error::new(
                ErrorCode::QueryType,
                "reduce input must be a list",
            ));
        }
    };
    for value in values {
        let mut nested = row.clone();
        nested.insert(accumulator.to_owned(), result);
        nested.insert(variable.to_owned(), value);
        result = evaluate_binding_with_temporal(
            expression,
            &nested,
            graph,
            context,
            temporal,
            visible_index,
        )?;
    }
    Ok(result)
}

fn evaluate_binding_binary(
    left: BindingValue,
    operation: BinaryOperator,
    right: BindingValue,
    graph: &GraphReadView<'_>,
) -> Result<BindingValue> {
    match (operation, left, right) {
        (
            BinaryOperator::Add | BinaryOperator::Concat,
            BindingValue::List(mut left),
            BindingValue::List(right),
        ) => {
            left.extend(right);
            Ok(BindingValue::List(left))
        }
        (BinaryOperator::Add, BindingValue::List(mut left), right) => {
            left.push(right);
            Ok(BindingValue::List(left))
        }
        (BinaryOperator::Add, left, BindingValue::List(mut right)) => {
            right.insert(0, left);
            Ok(BindingValue::List(right))
        }
        (operation, left, right) => evaluate_binary(
            binding_to_result(&left, graph)?,
            operation,
            binding_to_result(&right, graph)?,
        )
        .map(untrusted_result_binding),
    }
}

fn evaluate_binding_index(
    value: BindingValue,
    index: ResultValue,
    graph: &GraphReadView<'_>,
) -> Result<BindingValue> {
    if binding_is_null(&value) || is_null_value(&index) {
        return Ok(BindingValue::Null);
    }
    match normalize_untrusted_container(value) {
        BindingValue::List(values) => {
            let ResultValue::Scalar(ScalarValue::Integer(index)) = index else {
                return Err(Error::new(
                    ErrorCode::QueryType,
                    "InvalidArgumentType: list index requires an INTEGER",
                ));
            };
            if index < 0 {
                return Ok(BindingValue::Null);
            }
            let Some(index) = usize::try_from(index).ok() else {
                return Ok(BindingValue::Null);
            };
            Ok(values.get(index).cloned().unwrap_or(BindingValue::Null))
        }
        BindingValue::Map(values) => {
            let ResultValue::Scalar(ScalarValue::String(index)) = index else {
                return Err(Error::new(
                    ErrorCode::QueryType,
                    "MapElementAccessByNonString: map index requires a STRING",
                ));
            };
            Ok(values
                .get(index.as_ref())
                .cloned()
                .unwrap_or(BindingValue::Null))
        }
        value => evaluate_dynamic_index(binding_to_result(&value, graph)?, index)
            .map(untrusted_result_binding),
    }
}

#[allow(clippy::too_many_arguments)]
fn evaluate_binding_slice(
    expression: &Expression,
    start: Option<&Expression>,
    end: Option<&Expression>,
    row: &Row,
    graph: &GraphReadView<'_>,
    context: &ExecutionContext<'_>,
    temporal: Option<&TemporalReadView<'_>>,
    visible_index: u64,
) -> Result<BindingValue> {
    let list =
        evaluate_binding_with_temporal(expression, row, graph, context, temporal, visible_index)?;
    let BindingValue::List(values) = normalize_untrusted_container(list) else {
        return Err(Error::new(ErrorCode::QueryType, "slicing requires a list"));
    };
    let start = match start {
        None => 0,
        Some(expression) => {
            let value =
                evaluate_with_temporal(expression, row, graph, context, temporal, visible_index)?;
            if is_null_value(&value) {
                return Ok(BindingValue::Null);
            }
            normalize_list_slice_bound(integer(&value)?, values.len())
        }
    };
    let end = match end {
        None => values.len(),
        Some(expression) => {
            let value =
                evaluate_with_temporal(expression, row, graph, context, temporal, visible_index)?;
            if is_null_value(&value) {
                return Ok(BindingValue::Null);
            }
            normalize_list_slice_bound(integer(&value)?, values.len())
        }
    };
    if start >= end {
        return Ok(BindingValue::List(Vec::new()));
    }
    Ok(BindingValue::List(
        values.get(start..end).unwrap_or_default().to_vec(),
    ))
}

fn deleted_entity_access(entity: &str) -> Error {
    Error::new(
        ErrorCode::QueryType,
        format!("DeletedEntityAccess: {entity} was deleted in this query"),
    )
}

#[allow(clippy::too_many_arguments)]
fn evaluate_entity_metadata_function(
    name: &str,
    arguments: &[Expression],
    row: &Row,
    graph: &GraphReadView<'_>,
    context: &ExecutionContext<'_>,
    temporal: Option<&TemporalReadView<'_>>,
    visible_index: u64,
) -> Result<Option<ResultValue>> {
    if !matches!(name, "labels" | "type") {
        return Ok(None);
    }
    if arguments.len() != 1 {
        return Err(function_arity(name, "1", arguments.len()));
    }
    let value = evaluate_binding_with_temporal(
        &arguments[0],
        row,
        graph,
        context,
        temporal,
        visible_index,
    )?;
    if binding_is_null(&value) {
        return Ok(Some(ResultValue::Scalar(ScalarValue::Null)));
    }
    let value = match (name, value) {
        ("labels", BindingValue::Node(dense)) => {
            let node = graph.node_dense(dense).ok_or_else(|| {
                if graph.node_dense_was_deleted(dense) {
                    deleted_entity_access("node")
                } else {
                    Error::new(ErrorCode::QueryType, "node binding does not exist")
                }
            })?;
            ResultValue::List(
                node.labels()
                    .iter()
                    .filter_map(|label| graph.label_name(*label).map(ToOwned::to_owned))
                    .map(string_value)
                    .collect(),
            )
        }
        ("labels", BindingValue::Value(ResultValue::Node(node))) => {
            ResultValue::List(node.labels.into_iter().map(string_value).collect())
        }
        ("labels", _) => {
            return Err(Error::new(
                ErrorCode::QueryType,
                "InvalidArgumentValue: labels requires a node",
            ));
        }
        ("type", BindingValue::Relationship(dense)) => {
            let relationship_type = graph
                .edge_dense(dense)
                .map(|edge| edge.relationship_type())
                .or_else(|| graph.deleted_edge_relationship_type(dense))
                .ok_or_else(|| {
                    Error::new(ErrorCode::QueryType, "relationship binding does not exist")
                })?;
            string_value(
                graph
                    .relationship_type_name(relationship_type)
                    .unwrap_or("")
                    .to_owned(),
            )
        }
        ("type", BindingValue::Value(ResultValue::Relationship(relationship))) => {
            string_value(relationship.relationship_type)
        }
        ("type", _) => {
            return Err(Error::new(
                ErrorCode::QueryType,
                "InvalidArgumentValue: type requires a relationship",
            ));
        }
        _ => return Err(Error::internal("entity metadata dispatch is inconsistent")),
    };
    Ok(Some(value))
}

#[allow(clippy::too_many_arguments)]
fn evaluate_binding_function(
    name: &str,
    arguments: &[Expression],
    row: &Row,
    graph: &GraphReadView<'_>,
    context: &ExecutionContext<'_>,
    temporal: Option<&TemporalReadView<'_>>,
    visible_index: u64,
) -> Result<BindingValue> {
    if let Some(value) = evaluate_entity_metadata_function(
        name,
        arguments,
        row,
        graph,
        context,
        temporal,
        visible_index,
    )? {
        return Ok(untrusted_result_binding(value));
    }
    let values = arguments
        .iter()
        .map(|argument| {
            evaluate_binding_with_temporal(argument, row, graph, context, temporal, visible_index)
        })
        .collect::<Result<Vec<_>>>()?;
    if name == "coalesce" {
        return Ok(values
            .into_iter()
            .find(|value| !binding_is_null(value))
            .unwrap_or(BindingValue::Null));
    }
    if values.iter().any(binding_is_null) {
        return Ok(BindingValue::Null);
    }
    if values.len() != 1 {
        return Err(function_arity(name, "1", values.len()));
    }
    let value = values
        .into_iter()
        .next()
        .ok_or_else(|| function_arity(name, "1", 0))?;
    let value = normalize_untrusted_container(value);
    match name {
        "head" | "last" => {
            let BindingValue::List(values) = value else {
                return Err(Error::new(
                    ErrorCode::QueryType,
                    "head/last requires a LIST",
                ));
            };
            Ok(if name == "head" {
                values.first().cloned()
            } else {
                values.last().cloned()
            }
            .unwrap_or(BindingValue::Null))
        }
        "tail" => {
            let BindingValue::List(values) = value else {
                return Err(Error::new(ErrorCode::QueryType, "tail requires a LIST"));
            };
            Ok(BindingValue::List(
                values.get(1..).unwrap_or_default().to_vec(),
            ))
        }
        "reverse" => match value {
            BindingValue::List(mut values) => {
                values.reverse();
                Ok(BindingValue::List(values))
            }
            BindingValue::Value(ResultValue::Scalar(ScalarValue::String(value))) => Ok(
                BindingValue::Value(string_value(value.chars().rev().collect())),
            ),
            _ => Err(Error::new(
                ErrorCode::QueryType,
                "reverse requires a LIST or STRING",
            )),
        },
        "tolist" => Ok(match value {
            BindingValue::List(values) => BindingValue::List(values),
            BindingValue::Path { nodes, .. } => {
                BindingValue::List(nodes.into_iter().map(BindingValue::Node).collect())
            }
            BindingValue::Value(ResultValue::Path { nodes, .. }) => BindingValue::List(
                nodes
                    .into_iter()
                    .map(|node| BindingValue::Value(ResultValue::Node(node)))
                    .collect(),
            ),
            value => BindingValue::List(vec![value]),
        }),
        "nodes" | "relationships" => match value {
            BindingValue::Path {
                nodes,
                relationships,
            } => Ok(if name == "nodes" {
                BindingValue::List(nodes.into_iter().map(BindingValue::Node).collect())
            } else {
                BindingValue::List(
                    relationships
                        .into_iter()
                        .map(BindingValue::Relationship)
                        .collect(),
                )
            }),
            value => {
                let ResultValue::Path {
                    nodes,
                    relationships,
                } = binding_to_result(&value, graph)?
                else {
                    return Err(Error::new(
                        ErrorCode::QueryType,
                        "nodes/relationships requires a path",
                    ));
                };
                Ok(if name == "nodes" {
                    BindingValue::List(
                        nodes
                            .into_iter()
                            .map(|node| BindingValue::Value(ResultValue::Node(node)))
                            .collect(),
                    )
                } else {
                    BindingValue::List(
                        relationships
                            .into_iter()
                            .map(|edge| BindingValue::Value(ResultValue::Relationship(edge)))
                            .collect(),
                    )
                })
            }
        },
        "startnode" | "endnode" => match value {
            BindingValue::Relationship(dense) => {
                let edge = graph
                    .edge_dense(dense)
                    .ok_or_else(|| Error::new(ErrorCode::QueryType, "relationship is deleted"))?;
                let id = if name == "startnode" {
                    edge.source()
                } else {
                    edge.target()
                };
                let dense = graph
                    .node(id)
                    .ok_or_else(|| Error::new(ErrorCode::QueryType, "endpoint node is missing"))?
                    .dense();
                Ok(BindingValue::Node(dense))
            }
            value => {
                let ResultValue::Relationship(edge) = binding_to_result(&value, graph)? else {
                    return Err(Error::new(
                        ErrorCode::QueryType,
                        "startNode/endNode requires a relationship",
                    ));
                };
                let id = if name == "startnode" {
                    edge.source
                } else {
                    edge.target
                };
                let dense = graph
                    .node(id)
                    .ok_or_else(|| Error::new(ErrorCode::QueryType, "endpoint node is missing"))?
                    .dense();
                materialize_node(graph, dense)
                    .map(ResultValue::Node)
                    .map(BindingValue::Value)
            }
        },
        _ => Err(Error::internal(
            "binding-preserving function dispatch is inconsistent",
        )),
    }
}

#[allow(clippy::too_many_arguments)]
fn evaluate_entity_label_predicate(
    source: &Expression,
    names: &[Expression],
    row: &Row,
    graph: &GraphReadView<'_>,
    context: &ExecutionContext<'_>,
    temporal: Option<&TemporalReadView<'_>>,
    visible_index: u64,
) -> Result<ResultValue> {
    let names = names
        .iter()
        .map(|name| match name {
            Expression::Literal(ScalarValue::String(name)) => Ok(name.as_ref()),
            _ => Err(Error::internal(
                "entity label predicate contains a non-literal name",
            )),
        })
        .collect::<Result<Vec<_>>>()?;
    let source =
        evaluate_binding_with_temporal(source, row, graph, context, temporal, visible_index)?;
    if binding_is_null(&source) {
        return Ok(ResultValue::Scalar(ScalarValue::Null));
    }
    let matches = match source {
        BindingValue::Node(dense) => {
            let node = graph
                .node_dense(dense)
                .ok_or_else(|| Error::new(ErrorCode::QueryType, "node is deleted"))?;
            names.iter().all(|name| {
                graph
                    .label(name)
                    .is_some_and(|label| node.labels().contains(&label))
            })
        }
        BindingValue::Relationship(dense) => {
            let edge = graph
                .edge_dense(dense)
                .ok_or_else(|| Error::new(ErrorCode::QueryType, "relationship is deleted"))?;
            names.iter().all(|name| {
                graph
                    .relationship_type(name)
                    .is_some_and(|kind| kind == edge.relationship_type())
            })
        }
        BindingValue::Value(ResultValue::Node(node)) => names
            .iter()
            .all(|name| node.labels.iter().any(|label| label == name)),
        BindingValue::Value(ResultValue::Relationship(edge)) => names
            .iter()
            .all(|name| edge.relationship_type.as_str() == *name),
        BindingValue::Path { .. }
        | BindingValue::List(_)
        | BindingValue::Map(_)
        | BindingValue::Value(_)
        | BindingValue::Null => {
            return Err(Error::new(
                ErrorCode::QueryType,
                "InvalidArgumentType: entity label predicate requires a NODE or RELATIONSHIP",
            ));
        }
    };
    Ok(boolean(matches))
}

fn evaluate_with_temporal(
    expression: &Expression,
    row: &Row,
    graph: &GraphReadView<'_>,
    context: &ExecutionContext<'_>,
    temporal: Option<&TemporalReadView<'_>>,
    visible_index: u64,
) -> Result<ResultValue> {
    if let Some((source, names)) = expression.entity_label_predicate_parts() {
        return evaluate_entity_label_predicate(
            source,
            names,
            row,
            graph,
            context,
            temporal,
            visible_index,
        );
    }
    match expression {
        Expression::Literal(value) => Ok(ResultValue::Scalar(value.clone())),
        Expression::Parameter(name) => context.parameters.get(name).cloned().ok_or_else(|| {
            Error::new(
                ErrorCode::QueryType,
                format!("parameter `${name}` is missing"),
            )
        }),
        Expression::Variable(name) => {
            binding_to_result(row.get(name).unwrap_or(&BindingValue::Null), graph)
        }
        Expression::Property(value, property) => {
            if let Expression::Variable(variable) = value.as_ref() {
                match row.get(variable) {
                    Some(BindingValue::Node(dense)) => {
                        let node = graph.node_dense(*dense);
                        if node.is_none() && graph.node_dense_was_deleted(*dense) {
                            return Err(deleted_entity_access("node"));
                        }
                        let Some(id) = graph.property(property) else {
                            return Ok(ResultValue::Scalar(ScalarValue::Null));
                        };
                        let value = match (context.resolved_query_at_time_nanos, temporal, node) {
                            (_, Some(temporal), Some(node)) => {
                                let targets = node
                                    .labels()
                                    .iter()
                                    .map(|label| label.0)
                                    .collect::<Vec<_>>();
                                match temporal.resolve_target(EntityKind::Node, &targets, id)? {
                                    Some(target) => context
                                        .resolved_query_at_time_nanos
                                        .map_or_else(
                                            || {
                                                temporal.current(
                                                    EntityKind::Node,
                                                    target,
                                                    node.id().0,
                                                    id,
                                                )
                                            },
                                            |when| {
                                                temporal.at_time(
                                                    EntityKind::Node,
                                                    target,
                                                    node.id().0,
                                                    id,
                                                    when,
                                                    visible_index,
                                                )
                                            },
                                        )
                                        .map(|sample| sample.value.clone())
                                        .unwrap_or(ScalarValue::Null),
                                    None => node.property(id).unwrap_or(ScalarValue::Null),
                                }
                            }
                            (_, _, Some(node)) => node.property(id).unwrap_or(ScalarValue::Null),
                            _ => ScalarValue::Null,
                        };
                        return ResultValue::from_property(value);
                    }
                    Some(BindingValue::Relationship(dense)) => {
                        let edge = graph.edge_dense(*dense);
                        if edge.is_none() && graph.deleted_edge_relationship_type(*dense).is_some()
                        {
                            return Err(deleted_entity_access("relationship"));
                        }
                        let Some(id) = graph.property(property) else {
                            return Ok(ResultValue::Scalar(ScalarValue::Null));
                        };
                        let value = match (context.resolved_query_at_time_nanos, temporal, edge) {
                            (_, Some(temporal), Some(edge)) => {
                                let targets = [edge.relationship_type().0];
                                match temporal.resolve_target(
                                    EntityKind::Relationship,
                                    &targets,
                                    id,
                                )? {
                                    Some(target) => context
                                        .resolved_query_at_time_nanos
                                        .map_or_else(
                                            || {
                                                temporal.current(
                                                    EntityKind::Relationship,
                                                    target,
                                                    edge.id().0,
                                                    id,
                                                )
                                            },
                                            |when| {
                                                temporal.at_time(
                                                    EntityKind::Relationship,
                                                    target,
                                                    edge.id().0,
                                                    id,
                                                    when,
                                                    visible_index,
                                                )
                                            },
                                        )
                                        .map(|sample| sample.value.clone())
                                        .unwrap_or(ScalarValue::Null),
                                    None => edge.property(id).unwrap_or(ScalarValue::Null),
                                }
                            }
                            (_, _, Some(edge)) => edge.property(id).unwrap_or(ScalarValue::Null),
                            _ => ScalarValue::Null,
                        };
                        return ResultValue::from_property(value);
                    }
                    _ => {}
                }
            }
            match evaluate_with_temporal(value, row, graph, context, temporal, visible_index)? {
                ResultValue::Map(values) => Ok(values
                    .get(property)
                    .cloned()
                    .unwrap_or(ResultValue::Scalar(ScalarValue::Null))),
                ResultValue::Node(node) => Ok(node
                    .properties
                    .get(property)
                    .cloned()
                    .map(ResultValue::from_property)
                    .transpose()?
                    .unwrap_or(ResultValue::Scalar(ScalarValue::Null))),
                ResultValue::Relationship(edge) => Ok(edge
                    .properties
                    .get(property)
                    .cloned()
                    .map(ResultValue::from_property)
                    .transpose()?
                    .unwrap_or(ResultValue::Scalar(ScalarValue::Null))),
                ResultValue::Scalar(
                    value @ (ScalarValue::Date(_)
                    | ScalarValue::LocalTime(_)
                    | ScalarValue::ZonedTime { .. }
                    | ScalarValue::LocalDateTime { .. }
                    | ScalarValue::ZonedDateTime { .. }
                    | ScalarValue::Duration { .. }),
                ) => temporal_property(&value, property),
                ResultValue::Scalar(ScalarValue::Null) => {
                    Ok(ResultValue::Scalar(ScalarValue::Null))
                }
                _ => Err(Error::new(
                    ErrorCode::QueryType,
                    "property access requires node, relationship, or map",
                )),
            }
        }
        Expression::List(values) => Ok(ResultValue::List(
            values
                .iter()
                .map(|value| {
                    evaluate_with_temporal(value, row, graph, context, temporal, visible_index)
                })
                .collect::<Result<_>>()?,
        )),
        Expression::Map(values) => Ok(ResultValue::Map(
            values
                .iter()
                .map(|(name, value)| {
                    Ok((
                        name.clone(),
                        evaluate_with_temporal(
                            value,
                            row,
                            graph,
                            context,
                            temporal,
                            visible_index,
                        )?,
                    ))
                })
                .collect::<Result<_>>()?,
        )),
        Expression::MapProjection { source, items } => {
            evaluate_map_projection(source, items, row, graph, context, temporal, visible_index)
        }
        Expression::Case {
            operand,
            alternatives,
            default,
        } => evaluate_case(
            operand.as_deref(),
            alternatives,
            default.as_deref(),
            row,
            graph,
            context,
            temporal,
            visible_index,
        ),
        Expression::ListComprehension {
            variable,
            list,
            predicate,
            projection,
        } => evaluate_list_comprehension(
            variable,
            list,
            predicate.as_deref(),
            projection.as_deref(),
            row,
            graph,
            context,
            temporal,
            visible_index,
        ),
        Expression::Reduce {
            accumulator,
            initial,
            variable,
            list,
            expression,
        } => evaluate_reduce(
            accumulator,
            initial,
            variable,
            list,
            expression,
            row,
            graph,
            context,
            temporal,
            visible_index,
        ),
        Expression::ListPredicate {
            kind,
            variable,
            list,
            predicate,
        } => evaluate_list_predicate(
            *kind,
            variable,
            list,
            predicate,
            row,
            graph,
            context,
            temporal,
            visible_index,
        ),
        Expression::Function {
            name, arguments, ..
        } => evaluate_function(
            &name.join(".").to_ascii_lowercase(),
            arguments,
            row,
            graph,
            context,
            temporal,
            visible_index,
        ),
        Expression::Unary { operation, operand } => evaluate_unary(
            *operation,
            evaluate_with_temporal(operand, row, graph, context, temporal, visible_index)?,
        ),
        Expression::Binary {
            left,
            operation,
            right,
        } => evaluate_binary(
            evaluate_with_temporal(left, row, graph, context, temporal, visible_index)?,
            *operation,
            evaluate_with_temporal(right, row, graph, context, temporal, visible_index)?,
        ),
        Expression::IsNull {
            expression,
            negated,
        } => {
            let null = matches!(
                evaluate_with_temporal(expression, row, graph, context, temporal, visible_index,)?,
                ResultValue::Scalar(ScalarValue::Null)
            );
            Ok(ResultValue::Scalar(ScalarValue::Boolean(if *negated {
                !null
            } else {
                null
            })))
        }
        Expression::Index { expression, index } => {
            let value =
                evaluate_with_temporal(expression, row, graph, context, temporal, visible_index)?;
            let index =
                evaluate_with_temporal(index, row, graph, context, temporal, visible_index)?;
            evaluate_dynamic_index(value, index)
        }
        Expression::Slice {
            expression,
            start,
            end,
        } => {
            let ResultValue::List(values) =
                evaluate_with_temporal(expression, row, graph, context, temporal, visible_index)?
            else {
                return Err(Error::new(ErrorCode::QueryType, "slicing requires a list"));
            };
            let start = match start {
                None => 0,
                Some(expression) => {
                    let value = evaluate_with_temporal(
                        expression,
                        row,
                        graph,
                        context,
                        temporal,
                        visible_index,
                    )?;
                    if is_null_value(&value) {
                        return Ok(ResultValue::Scalar(ScalarValue::Null));
                    }
                    normalize_list_slice_bound(integer(&value)?, values.len())
                }
            };
            let end = match end {
                None => values.len(),
                Some(expression) => {
                    let value = evaluate_with_temporal(
                        expression,
                        row,
                        graph,
                        context,
                        temporal,
                        visible_index,
                    )?;
                    if is_null_value(&value) {
                        return Ok(ResultValue::Scalar(ScalarValue::Null));
                    }
                    normalize_list_slice_bound(integer(&value)?, values.len())
                }
            };
            let values = if start >= end {
                Vec::new()
            } else {
                match values.get(start..end) {
                    Some(values) => values.to_vec(),
                    None => Vec::new(),
                }
            };
            Ok(ResultValue::List(values))
        }
        Expression::ExistentialSubquery(_) => Err(Error::internal(
            "existential subquery bypassed correlated expression execution",
        )),
        Expression::Star => Err(Error::new(
            ErrorCode::QueryType,
            "star is legal only in a projection or aggregate",
        )),
    }
}

#[allow(clippy::too_many_arguments)]
fn evaluate_map_projection(
    source: &Expression,
    items: &[MapProjectionItem],
    row: &Row,
    graph: &GraphReadView<'_>,
    context: &ExecutionContext<'_>,
    temporal: Option<&TemporalReadView<'_>>,
    visible_index: u64,
) -> Result<ResultValue> {
    let source = evaluate_with_temporal(source, row, graph, context, temporal, visible_index)?;
    if is_null_value(&source) {
        return Ok(ResultValue::Scalar(ScalarValue::Null));
    }
    let source_properties = match source {
        ResultValue::Node(node) => node
            .properties
            .into_iter()
            .map(|(name, value)| Ok((name, ResultValue::from_property(value)?)))
            .collect::<Result<BTreeMap<_, _>>>()?,
        ResultValue::Relationship(edge) => edge
            .properties
            .into_iter()
            .map(|(name, value)| Ok((name, ResultValue::from_property(value)?)))
            .collect::<Result<BTreeMap<_, _>>>()?,
        ResultValue::Map(values) => values,
        _ => {
            return Err(Error::new(
                ErrorCode::QueryType,
                "map projection source must be a map, node, or relationship",
            ));
        }
    };
    let mut projected = BTreeMap::new();
    for item in items {
        match item {
            MapProjectionItem::AllProperties => projected.extend(source_properties.clone()),
            MapProjectionItem::Property(name) => {
                projected.insert(
                    name.clone(),
                    source_properties
                        .get(name)
                        .cloned()
                        .unwrap_or(ResultValue::Scalar(ScalarValue::Null)),
                );
            }
            MapProjectionItem::Variable(name) => {
                projected.insert(
                    name.clone(),
                    binding_to_result(row.get(name).unwrap_or(&BindingValue::Null), graph)?,
                );
            }
            MapProjectionItem::Entry(name, expression) => {
                projected.insert(
                    name.clone(),
                    evaluate_with_temporal(
                        expression,
                        row,
                        graph,
                        context,
                        temporal,
                        visible_index,
                    )?,
                );
            }
        }
    }
    Ok(ResultValue::Map(projected))
}

#[allow(clippy::too_many_arguments)]
fn evaluate_case(
    operand: Option<&Expression>,
    alternatives: &[CaseAlternative],
    default: Option<&Expression>,
    row: &Row,
    graph: &GraphReadView<'_>,
    context: &ExecutionContext<'_>,
    temporal: Option<&TemporalReadView<'_>>,
    visible_index: u64,
) -> Result<ResultValue> {
    let operand = operand
        .map(|operand| {
            evaluate_with_temporal(operand, row, graph, context, temporal, visible_index)
        })
        .transpose()?;
    for alternative in alternatives {
        let when = evaluate_with_temporal(
            &alternative.when,
            row,
            graph,
            context,
            temporal,
            visible_index,
        )?;
        let selected = match &operand {
            Some(operand) => equal(operand, &when)? == Truth::True,
            None => truth(&when)? == Truth::True,
        };
        if selected {
            return evaluate_with_temporal(
                &alternative.then,
                row,
                graph,
                context,
                temporal,
                visible_index,
            );
        }
    }
    default.map_or_else(
        || Ok(ResultValue::Scalar(ScalarValue::Null)),
        |default| evaluate_with_temporal(default, row, graph, context, temporal, visible_index),
    )
}

#[allow(clippy::too_many_arguments)]
fn evaluate_list_comprehension(
    variable: &str,
    list: &Expression,
    predicate: Option<&Expression>,
    projection: Option<&Expression>,
    row: &Row,
    graph: &GraphReadView<'_>,
    context: &ExecutionContext<'_>,
    temporal: Option<&TemporalReadView<'_>>,
    visible_index: u64,
) -> Result<ResultValue> {
    let list = evaluate_with_temporal(list, row, graph, context, temporal, visible_index)?;
    let ResultValue::List(values) = list else {
        if is_null_value(&list) {
            return Ok(ResultValue::Scalar(ScalarValue::Null));
        }
        return Err(Error::new(
            ErrorCode::QueryType,
            "list comprehension input must be a list",
        ));
    };
    let mut output = Vec::with_capacity(values.len());
    for value in values {
        let mut nested = row.clone();
        nested.insert(variable.to_owned(), BindingValue::Value(value.clone()));
        if let Some(predicate) = predicate {
            let predicate = evaluate_with_temporal(
                predicate,
                &nested,
                graph,
                context,
                temporal,
                visible_index,
            )?;
            if truth(&predicate)? != Truth::True {
                continue;
            }
        }
        output.push(match projection {
            Some(projection) => evaluate_with_temporal(
                projection,
                &nested,
                graph,
                context,
                temporal,
                visible_index,
            )?,
            None => value,
        });
    }
    Ok(ResultValue::List(output))
}

#[allow(clippy::too_many_arguments)]
fn evaluate_reduce(
    accumulator: &str,
    initial: &Expression,
    variable: &str,
    list: &Expression,
    expression: &Expression,
    row: &Row,
    graph: &GraphReadView<'_>,
    context: &ExecutionContext<'_>,
    temporal: Option<&TemporalReadView<'_>>,
    visible_index: u64,
) -> Result<ResultValue> {
    let mut result = evaluate_with_temporal(initial, row, graph, context, temporal, visible_index)?;
    let list = evaluate_with_temporal(list, row, graph, context, temporal, visible_index)?;
    let ResultValue::List(values) = list else {
        if is_null_value(&list) {
            return Ok(ResultValue::Scalar(ScalarValue::Null));
        }
        return Err(Error::new(
            ErrorCode::QueryType,
            "reduce input must be a list",
        ));
    };
    for value in values {
        let mut nested = row.clone();
        nested.insert(accumulator.to_owned(), BindingValue::Value(result));
        nested.insert(variable.to_owned(), BindingValue::Value(value));
        result =
            evaluate_with_temporal(expression, &nested, graph, context, temporal, visible_index)?;
    }
    Ok(result)
}

#[allow(clippy::too_many_arguments)]
fn evaluate_list_predicate(
    kind: ListPredicateKind,
    variable: &str,
    list: &Expression,
    predicate: &Expression,
    row: &Row,
    graph: &GraphReadView<'_>,
    context: &ExecutionContext<'_>,
    temporal: Option<&TemporalReadView<'_>>,
    visible_index: u64,
) -> Result<ResultValue> {
    let list = evaluate_with_temporal(list, row, graph, context, temporal, visible_index)?;
    let ResultValue::List(values) = list else {
        if is_null_value(&list) {
            return Ok(ResultValue::Scalar(ScalarValue::Null));
        }
        return Err(Error::new(
            ErrorCode::QueryType,
            "list predicate input must be a list",
        ));
    };
    let mut true_count = 0_usize;
    let mut false_count = 0_usize;
    let mut unknown_count = 0_usize;
    for value in values {
        let mut nested = row.clone();
        nested.insert(variable.to_owned(), BindingValue::Value(value));
        let value =
            evaluate_with_temporal(predicate, &nested, graph, context, temporal, visible_index)?;
        match truth(&value)? {
            Truth::True => true_count = true_count.saturating_add(1),
            Truth::False => false_count = false_count.saturating_add(1),
            Truth::Unknown => unknown_count = unknown_count.saturating_add(1),
        }
        match kind {
            ListPredicateKind::All if false_count > 0 => return Ok(boolean(false)),
            ListPredicateKind::Any if true_count > 0 => return Ok(boolean(true)),
            ListPredicateKind::None if true_count > 0 => return Ok(boolean(false)),
            ListPredicateKind::Single if true_count > 1 => return Ok(boolean(false)),
            _ => {}
        }
    }
    let result = match kind {
        ListPredicateKind::All => {
            if unknown_count > 0 {
                Truth::Unknown
            } else {
                Truth::True
            }
        }
        ListPredicateKind::Any => {
            if unknown_count > 0 {
                Truth::Unknown
            } else {
                Truth::False
            }
        }
        ListPredicateKind::None => {
            if unknown_count > 0 {
                Truth::Unknown
            } else {
                Truth::True
            }
        }
        ListPredicateKind::Single => match (true_count, unknown_count) {
            (1, 0) => Truth::True,
            (0 | 1, 1..) => Truth::Unknown,
            _ => Truth::False,
        },
    };
    Ok(result.into_value())
}

fn evaluate_function(
    name: &str,
    arguments: &[Expression],
    row: &Row,
    graph: &GraphReadView<'_>,
    context: &ExecutionContext<'_>,
    temporal: Option<&TemporalReadView<'_>>,
    visible_index: u64,
) -> Result<ResultValue> {
    if let Some(value) = evaluate_entity_metadata_function(
        name,
        arguments,
        row,
        graph,
        context,
        temporal,
        visible_index,
    )? {
        return Ok(value);
    }
    let values = arguments
        .iter()
        .map(|argument| {
            evaluate_with_temporal(argument, row, graph, context, temporal, visible_index)
        })
        .collect::<Result<Vec<_>>>()?;
    if name != "coalesce" && values.iter().any(is_null_value) {
        return Ok(ResultValue::Scalar(ScalarValue::Null));
    }
    match name {
        "abs" => {
            require_arity(name, &values, 1)?;
            match &values[0] {
                ResultValue::Scalar(ScalarValue::Integer(value)) => value
                    .checked_abs()
                    .map(ScalarValue::Integer)
                    .map(ResultValue::Scalar)
                    .ok_or_else(|| Error::new(ErrorCode::QueryType, "integer absolute overflow")),
                value => Ok(number(numeric(value)?.abs())),
            }
        }
        "ceil" | "floor" | "round" | "sqrt" | "exp" | "log" | "log10" | "acos" | "asin"
        | "atan" | "sin" | "cos" | "tan" | "cot" | "degrees" | "radians" => {
            require_arity(name, &values, 1)?;
            let value = numeric(&values[0])?;
            let result = match name {
                "ceil" => value.ceil(),
                "floor" => value.floor(),
                "round" => value.round(),
                "sqrt" => value.sqrt(),
                "exp" => value.exp(),
                "log" => value.ln(),
                "log10" => value.log10(),
                "acos" => value.acos(),
                "asin" => value.asin(),
                "atan" => value.atan(),
                "sin" => value.sin(),
                "cos" => value.cos(),
                "tan" => value.tan(),
                "cot" => value.tan().recip(),
                "degrees" => value.to_degrees(),
                "radians" => value.to_radians(),
                _ => value,
            };
            Ok(number(result))
        }
        "sign" => {
            require_arity(name, &values, 1)?;
            let value = numeric(&values[0])?;
            Ok(ResultValue::Scalar(ScalarValue::Integer(if value > 0.0 {
                1
            } else if value < 0.0 {
                -1
            } else {
                0
            })))
        }
        "atan2" | "power" => {
            require_arity(name, &values, 2)?;
            Ok(number(if name == "atan2" {
                numeric_arg(&values, 0)?.atan2(numeric_arg(&values, 1)?)
            } else {
                numeric_arg(&values, 0)?.powf(numeric_arg(&values, 1)?)
            }))
        }
        "pi" | "e" => {
            require_arity(name, &values, 0)?;
            Ok(number(if name == "pi" {
                std::f64::consts::PI
            } else {
                std::f64::consts::E
            }))
        }
        "rand" => {
            require_arity(name, &values, 0)?;
            Ok(number(rand::rng().random::<f64>()))
        }
        "lower" | "tolower" | "upper" | "trim" | "ltrim" | "rtrim" => {
            require_arity(name, &values, 1)?;
            let value = string_arg(&values, 0)?;
            let result = match name {
                "lower" | "tolower" => value.to_lowercase(),
                "upper" => value.to_uppercase(),
                "trim" => value.trim().to_owned(),
                "ltrim" => value.trim_start().to_owned(),
                "rtrim" => value.trim_end().to_owned(),
                _ => value,
            };
            Ok(ResultValue::Scalar(ScalarValue::String(Arc::from(result))))
        }
        "left" | "right" => {
            require_arity(name, &values, 2)?;
            let value = string_arg(&values, 0)?;
            let count = non_negative_usize_arg(&values, 1, name)?;
            let characters = value.chars().collect::<Vec<_>>();
            let start = if name == "right" {
                characters.len().saturating_sub(count)
            } else {
                0
            };
            let end = if name == "left" {
                count.min(characters.len())
            } else {
                characters.len()
            };
            Ok(string_value(characters[start..end].iter().collect()))
        }
        "substring" => {
            if !(2..=3).contains(&values.len()) {
                return Err(function_arity(name, "two or three", values.len()));
            }
            let value = string_arg(&values, 0)?;
            let start = non_negative_usize_arg(&values, 1, name)?;
            let characters = value.chars().collect::<Vec<_>>();
            let end = values.get(2).map_or(Ok(characters.len()), |value| {
                usize::try_from(integer(value)?).map_err(|_| {
                    Error::new(
                        ErrorCode::QueryType,
                        "substring length must be non-negative",
                    )
                })
            })?;
            let start = start.min(characters.len());
            let end = start.saturating_add(end).min(characters.len());
            Ok(string_value(characters[start..end].iter().collect()))
        }
        "replace" => {
            require_arity(name, &values, 3)?;
            Ok(string_value(string_arg(&values, 0)?.replace(
                &string_arg(&values, 1)?,
                &string_arg(&values, 2)?,
            )))
        }
        "split" => {
            require_arity(name, &values, 2)?;
            let value = string_arg(&values, 0)?;
            let separator = string_arg(&values, 1)?;
            Ok(ResultValue::List(
                value
                    .split(&separator)
                    .map(|part| string_value(part.to_owned()))
                    .collect(),
            ))
        }
        "head" | "last" => {
            require_arity(name, &values, 1)?;
            let ResultValue::List(items) = &values[0] else {
                return Err(Error::new(
                    ErrorCode::QueryType,
                    "head/last requires a LIST",
                ));
            };
            Ok(if name == "head" {
                items.first().cloned()
            } else {
                items.last().cloned()
            }
            .unwrap_or(ResultValue::Scalar(ScalarValue::Null)))
        }
        "tail" => {
            require_arity(name, &values, 1)?;
            let ResultValue::List(items) = &values[0] else {
                return Err(Error::new(ErrorCode::QueryType, "tail requires a LIST"));
            };
            Ok(ResultValue::List(
                items.get(1..).unwrap_or_default().to_vec(),
            ))
        }
        "reverse" => {
            require_arity(name, &values, 1)?;
            match &values[0] {
                ResultValue::List(items) => Ok(ResultValue::List(
                    items.iter().rev().cloned().collect::<Vec<_>>(),
                )),
                ResultValue::Scalar(ScalarValue::String(value)) => {
                    Ok(string_value(value.chars().rev().collect()))
                }
                _ => Err(Error::new(
                    ErrorCode::QueryType,
                    "reverse requires a LIST or STRING",
                )),
            }
        }
        "range" => cypher_range(&values, context.max_result_rows),
        "isempty" => {
            require_arity(name, &values, 1)?;
            Ok(boolean(match &values[0] {
                ResultValue::List(items) => items.is_empty(),
                ResultValue::Map(items) => items.is_empty(),
                ResultValue::Scalar(ScalarValue::String(value)) => value.is_empty(),
                _ => {
                    return Err(Error::new(
                        ErrorCode::QueryType,
                        "isEmpty requires a LIST, MAP, or STRING",
                    ));
                }
            }))
        }
        "size" | "length" => {
            require_arity(name, &values, 1)?;
            let size = match values.first() {
                Some(ResultValue::List(values)) => values.len(),
                Some(ResultValue::Map(values)) => values.len(),
                Some(ResultValue::Scalar(ScalarValue::String(value))) => value.chars().count(),
                Some(ResultValue::Path { relationships, .. }) if name == "length" => {
                    relationships.len()
                }
                _ => {
                    return Err(Error::new(
                        ErrorCode::QueryType,
                        "size/length received an incompatible value",
                    ));
                }
            };
            Ok(ResultValue::Scalar(ScalarValue::Integer(
                i64::try_from(size)
                    .map_err(|_| Error::new(ErrorCode::ResultBudgetExceeded, "size overflow"))?,
            )))
        }
        "keys" => {
            require_arity(name, &values, 1)?;
            let keys = match &values[0] {
                ResultValue::Map(values) => values.keys().cloned().collect::<Vec<_>>(),
                ResultValue::Node(node) => node.properties.keys().cloned().collect(),
                ResultValue::Relationship(relationship) => {
                    relationship.properties.keys().cloned().collect()
                }
                _ => {
                    return Err(Error::new(
                        ErrorCode::QueryType,
                        "keys requires a MAP, node, or relationship",
                    ));
                }
            };
            Ok(ResultValue::List(
                keys.into_iter().map(string_value).collect(),
            ))
        }
        "labels" => {
            require_arity(name, &values, 1)?;
            let ResultValue::Node(node) = &values[0] else {
                return Err(Error::new(ErrorCode::QueryType, "labels requires a node"));
            };
            Ok(ResultValue::List(
                node.labels.iter().cloned().map(string_value).collect(),
            ))
        }
        "properties" => {
            require_arity(name, &values, 1)?;
            match &values[0] {
                ResultValue::Map(values) => Ok(ResultValue::Map(values.clone())),
                ResultValue::Node(node) => property_map(&node.properties),
                ResultValue::Relationship(relationship) => property_map(&relationship.properties),
                _ => Err(Error::new(
                    ErrorCode::QueryType,
                    "properties requires a MAP, node, or relationship",
                )),
            }
        }
        "nodes" | "relationships" => {
            require_arity(name, &values, 1)?;
            let ResultValue::Path {
                nodes,
                relationships,
            } = &values[0]
            else {
                return Err(Error::new(
                    ErrorCode::QueryType,
                    "nodes/relationships requires a path",
                ));
            };
            Ok(if name == "nodes" {
                ResultValue::List(nodes.iter().cloned().map(ResultValue::Node).collect())
            } else {
                ResultValue::List(
                    relationships
                        .iter()
                        .cloned()
                        .map(ResultValue::Relationship)
                        .collect(),
                )
            })
        }
        "startnode" | "endnode" => {
            require_arity(name, &values, 1)?;
            let ResultValue::Relationship(relationship) = &values[0] else {
                return Err(Error::new(
                    ErrorCode::QueryType,
                    "startNode/endNode requires a relationship",
                ));
            };
            let id = if name == "startnode" {
                relationship.source
            } else {
                relationship.target
            };
            let dense = graph
                .node(id)
                .ok_or_else(|| Error::new(ErrorCode::QueryType, "endpoint node is missing"))?
                .dense();
            materialize_node(graph, dense).map(ResultValue::Node)
        }
        "type" => {
            require_arity(name, &values, 1)?;
            let ResultValue::Relationship(relationship) = &values[0] else {
                return Err(Error::new(
                    ErrorCode::QueryType,
                    "type requires a relationship",
                ));
            };
            Ok(string_value(relationship.relationship_type.clone()))
        }
        "tostring" => {
            require_arity(name, &values, 1)?;
            to_string_value(&values[0])
        }
        "toboolean" => {
            require_arity(name, &values, 1)?;
            to_boolean_value(&values[0])
        }
        "tointeger" => {
            require_arity(name, &values, 1)?;
            to_integer_value(&values[0])
        }
        "tofloat" => {
            require_arity(name, &values, 1)?;
            to_float_value(&values[0])
        }
        "tolist" => {
            require_arity(name, &values, 1)?;
            Ok(match &values[0] {
                ResultValue::List(values) => ResultValue::List(values.clone()),
                ResultValue::Path { nodes, .. } => {
                    ResultValue::List(nodes.iter().cloned().map(ResultValue::Node).collect())
                }
                value => ResultValue::List(vec![value.clone()]),
            })
        }
        "vector.dot" | "vector.cosine" | "vector.distance" => {
            require_arity(name, &values, 2)?;
            vector_binary(name, &values[0], &values[1])
        }
        "vector.normalize" => {
            require_arity(name, &values, 1)?;
            vector_normalize(&values[0])
        }
        "coalesce" => Ok(values
            .into_iter()
            .find(|value| !matches!(value, ResultValue::Scalar(ScalarValue::Null)))
            .unwrap_or(ResultValue::Scalar(ScalarValue::Null))),
        "id" => match arguments.first() {
            Some(Expression::Variable(variable)) => match row.get(variable) {
                Some(BindingValue::Node(dense)) => Ok(ResultValue::Scalar(ScalarValue::Integer(
                    state_id_node(graph, *dense)?,
                ))),
                Some(BindingValue::Relationship(dense)) => Ok(ResultValue::Scalar(
                    ScalarValue::Integer(state_id_edge(graph, *dense)?),
                )),
                _ => Ok(ResultValue::Scalar(ScalarValue::Null)),
            },
            _ => Err(Error::new(
                ErrorCode::QueryType,
                "id requires an entity variable",
            )),
        },
        "revision" => match arguments.first() {
            Some(Expression::Variable(variable)) => match row.get(variable) {
                Some(BindingValue::Node(dense)) => {
                    let revision = graph
                        .node_dense(*dense)
                        .ok_or_else(|| Error::new(ErrorCode::QueryType, "node missing"))?
                        .revision();
                    Ok(ResultValue::Scalar(ScalarValue::Integer(
                        i64::try_from(revision).map_err(|_| {
                            Error::new(ErrorCode::QueryType, "revision exceeds Cypher INTEGER")
                        })?,
                    )))
                }
                Some(BindingValue::Relationship(dense)) => {
                    let revision = graph
                        .edge_dense(*dense)
                        .ok_or_else(|| Error::new(ErrorCode::QueryType, "relationship missing"))?
                        .revision();
                    Ok(ResultValue::Scalar(ScalarValue::Integer(
                        i64::try_from(revision).map_err(|_| {
                            Error::new(ErrorCode::QueryType, "revision exceeds Cypher INTEGER")
                        })?,
                    )))
                }
                _ => Ok(ResultValue::Scalar(ScalarValue::Null)),
            },
            _ => Err(Error::new(
                ErrorCode::QueryType,
                "revision requires an entity variable",
            )),
        },
        "date" | "localtime" | "time" | "localdatetime" | "datetime" => {
            temporal_constructor(name, &values, context.resolved_time_nanos)
        }
        "date.truncate"
        | "localtime.truncate"
        | "time.truncate"
        | "localdatetime.truncate"
        | "datetime.truncate" => temporal_truncate(name, &values),
        "datetime.fromepoch" => {
            require_arity(name, &values, 2)?;
            let seconds = integer(&values[0])?;
            let nanos = integer(&values[1])?;
            let nanos = u32::try_from(nanos)
                .ok()
                .filter(|nanos| *nanos < 1_000_000_000)
                .ok_or_else(|| {
                    Error::new(
                        ErrorCode::QueryType,
                        "datetime.fromepoch nanoseconds must be between 0 and 999999999",
                    )
                })?;
            chrono::DateTime::<chrono::Utc>::from_timestamp(seconds, nanos).ok_or_else(|| {
                Error::new(
                    ErrorCode::TemporalRange,
                    "datetime.fromepoch result is outside the temporal range",
                )
            })?;
            Ok(ResultValue::Scalar(ScalarValue::ZonedDateTime {
                seconds,
                nanos,
                timezone: Arc::from("UTC"),
            }))
        }
        "datetime.fromepochmillis" => {
            require_arity(name, &values, 1)?;
            let millis = integer(&values[0])?;
            let seconds = millis.div_euclid(1_000);
            let nanos = u32::try_from(millis.rem_euclid(1_000) * 1_000_000).map_err(|_| {
                Error::new(
                    ErrorCode::TemporalRange,
                    "datetime.fromepochmillis nanoseconds are invalid",
                )
            })?;
            chrono::DateTime::<chrono::Utc>::from_timestamp(seconds, nanos).ok_or_else(|| {
                Error::new(
                    ErrorCode::TemporalRange,
                    "datetime.fromepochmillis result is outside the temporal range",
                )
            })?;
            Ok(ResultValue::Scalar(ScalarValue::ZonedDateTime {
                seconds,
                nanos,
                timezone: Arc::from("UTC"),
            }))
        }
        "duration" => {
            require_arity(name, &values, 1)?;
            duration_constructor(&values[0])
        }
        "duration.between" | "duration.inmonths" | "duration.indays" | "duration.inseconds" => {
            temporal_duration_function(name, &values)
        }
        _ => Err(Error::new(
            ErrorCode::QueryType,
            "built-in function has no scalar implementation in this operator",
        )),
    }
}

fn evaluate_unary(operation: UnaryOperator, value: ResultValue) -> Result<ResultValue> {
    if matches!(value, ResultValue::Scalar(ScalarValue::Null)) {
        return Ok(value);
    }
    match operation {
        UnaryOperator::Not => Ok(truth(&value)?.not().into_value()),
        UnaryOperator::Positive => match value {
            ResultValue::Scalar(ScalarValue::Integer(_) | ScalarValue::Float(_)) => Ok(value),
            _ => Err(Error::new(
                ErrorCode::QueryType,
                "unary + requires a number",
            )),
        },
        UnaryOperator::Negative => match value {
            ResultValue::Scalar(ScalarValue::Integer(value)) => value
                .checked_neg()
                .map(ScalarValue::Integer)
                .map(ResultValue::Scalar)
                .ok_or_else(|| Error::new(ErrorCode::QueryType, "integer negation overflow")),
            ResultValue::Scalar(ScalarValue::Float(value)) => Ok(ResultValue::Scalar(
                ScalarValue::Float(OrderedFloat(-value.into_inner())),
            )),
            _ => Err(Error::new(
                ErrorCode::QueryType,
                "unary - requires a number",
            )),
        },
    }
}

fn evaluate_binary(
    left: ResultValue,
    operation: BinaryOperator,
    right: ResultValue,
) -> Result<ResultValue> {
    match operation {
        BinaryOperator::Equal => Ok(equal(&left, &right)?.into_value()),
        BinaryOperator::NotEqual => Ok(equal(&left, &right)?.not().into_value()),
        BinaryOperator::Less
        | BinaryOperator::LessOrEqual
        | BinaryOperator::Greater
        | BinaryOperator::GreaterOrEqual => {
            Ok(compare_predicate(&left, &right, operation)?.into_value())
        }
        BinaryOperator::And => Ok(truth(&left)?.and(truth(&right)?).into_value()),
        BinaryOperator::Or => Ok(truth(&left)?.or(truth(&right)?).into_value()),
        BinaryOperator::Xor => Ok(truth(&left)?.xor(truth(&right)?).into_value()),
        BinaryOperator::In => match right {
            ResultValue::List(values) => Ok(list_contains(&values, &left)?.into_value()),
            ResultValue::Scalar(ScalarValue::Null) => Ok(ResultValue::Scalar(ScalarValue::Null)),
            _ => Err(Error::new(
                ErrorCode::QueryType,
                "IN right operand must be a list",
            )),
        },
        BinaryOperator::Add => {
            if let Some(value) = evaluate_duration_addition(&left, &right)? {
                return Ok(value);
            }
            match (left, right) {
                (
                    ResultValue::Scalar(ScalarValue::String(left)),
                    ResultValue::Scalar(ScalarValue::String(right)),
                ) => Ok(ResultValue::Scalar(ScalarValue::String(Arc::from(
                    format!("{left}{right}"),
                )))),
                (ResultValue::List(mut left), ResultValue::List(right)) => {
                    left.extend(right);
                    Ok(ResultValue::List(left))
                }
                (ResultValue::List(mut left), right) => {
                    left.push(right);
                    Ok(ResultValue::List(left))
                }
                (left, ResultValue::List(mut right)) => {
                    right.insert(0, left);
                    Ok(ResultValue::List(right))
                }
                (
                    ResultValue::Scalar(ScalarValue::Integer(left)),
                    ResultValue::Scalar(ScalarValue::Integer(right)),
                ) => left
                    .checked_add(right)
                    .map(ScalarValue::Integer)
                    .map(ResultValue::Scalar)
                    .ok_or_else(|| Error::new(ErrorCode::QueryType, "integer addition overflow")),
                (left, right) if is_null_value(&left) || is_null_value(&right) => {
                    Ok(ResultValue::Scalar(ScalarValue::Null))
                }
                (left, right) => Ok(number(numeric(&left)? + numeric(&right)?)),
            }
        }
        BinaryOperator::Subtract
        | BinaryOperator::Multiply
        | BinaryOperator::Divide
        | BinaryOperator::Modulo
        | BinaryOperator::Power
            if is_null_value(&left) || is_null_value(&right) =>
        {
            Ok(ResultValue::Scalar(ScalarValue::Null))
        }
        BinaryOperator::Subtract => {
            if let Some(value) = evaluate_duration_subtraction(&left, &right)? {
                return Ok(value);
            }
            numeric_binary(left, right, NumericOperation::Subtract)
        }
        BinaryOperator::Multiply => {
            if let Some(value) = evaluate_duration_multiplication(&left, &right)? {
                return Ok(value);
            }
            numeric_binary(left, right, NumericOperation::Multiply)
        }
        BinaryOperator::Divide => {
            if let Some(value) = evaluate_duration_division(&left, &right)? {
                return Ok(value);
            }
            evaluate_division(left, right)
        }
        BinaryOperator::Modulo => evaluate_modulo(left, right),
        BinaryOperator::Power => Ok(number(numeric(&left)?.powf(numeric(&right)?))),
        BinaryOperator::Concat => match (left, right) {
            (ResultValue::List(mut left), ResultValue::List(right)) => {
                left.extend(right);
                Ok(ResultValue::List(left))
            }
            (
                ResultValue::Scalar(ScalarValue::String(left)),
                ResultValue::Scalar(ScalarValue::String(right)),
            ) => Ok(ResultValue::Scalar(ScalarValue::String(Arc::from(
                format!("{left}{right}"),
            )))),
            (left, right) if is_null_value(&left) || is_null_value(&right) => {
                Ok(ResultValue::Scalar(ScalarValue::Null))
            }
            _ => Err(Error::new(
                ErrorCode::QueryType,
                "|| requires two lists or two strings",
            )),
        },
        BinaryOperator::RegexMatch => {
            if is_null_value(&left) || is_null_value(&right) {
                return Ok(ResultValue::Scalar(ScalarValue::Null));
            }
            let (
                ResultValue::Scalar(ScalarValue::String(value)),
                ResultValue::Scalar(ScalarValue::String(pattern)),
            ) = (left, right)
            else {
                return Err(Error::new(
                    ErrorCode::QueryType,
                    "=~ requires STRING operands",
                ));
            };
            let regex = regex::Regex::new(&pattern).map_err(|error| {
                Error::new(
                    ErrorCode::QueryType,
                    format!("invalid regular expression: {error}"),
                )
            })?;
            Ok(boolean(regex.is_match(&value)))
        }
        BinaryOperator::StartsWith | BinaryOperator::EndsWith | BinaryOperator::Contains => {
            if is_null_value(&left) || is_null_value(&right) {
                return Ok(ResultValue::Scalar(ScalarValue::Null));
            }
            let (
                ResultValue::Scalar(ScalarValue::String(left)),
                ResultValue::Scalar(ScalarValue::String(right)),
            ) = (left, right)
            else {
                return Ok(ResultValue::Scalar(ScalarValue::Null));
            };
            Ok(boolean(match operation {
                BinaryOperator::StartsWith => left.starts_with(right.as_ref()),
                BinaryOperator::EndsWith => left.ends_with(right.as_ref()),
                BinaryOperator::Contains => left.contains(right.as_ref()),
                _ => false,
            }))
        }
    }
}

const DURATION_NANOS_PER_SECOND: i128 = 1_000_000_000;
const DURATION_SECONDS_PER_DAY: i128 = 86_400;
const DURATION_NANOS_PER_DAY: i128 = DURATION_SECONDS_PER_DAY * DURATION_NANOS_PER_SECOND;
const DURATION_DECIMAL_SCALE: i128 = DURATION_NANOS_PER_SECOND;
const DURATION_AVERAGE_SECONDS_PER_MONTH_INTEGER: i128 = 2_629_746;
const DURATION_AVERAGE_SECONDS_PER_MONTH: f64 = 2_629_746.0;

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
struct DurationParts {
    months: i64,
    days: i64,
    seconds: i64,
    nanos: i32,
}

#[derive(Clone, Copy, Debug)]
enum DurationNumber {
    Integer(i64),
    Float(f64),
}

impl DurationNumber {
    fn as_f64(self) -> f64 {
        match self {
            Self::Integer(value) => value as f64,
            Self::Float(value) => value,
        }
    }

    const fn is_float(self) -> bool {
        matches!(self, Self::Float(_))
    }

    fn as_i128(self) -> Result<i128> {
        match self {
            Self::Integer(value) => Ok(i128::from(value)),
            Self::Float(_) => Err(Error::new(
                ErrorCode::QueryType,
                "InvalidArgumentType: floating duration field reached integer construction",
            )),
        }
    }
}

fn duration_parts(value: &ResultValue) -> Option<DurationParts> {
    let ResultValue::Scalar(ScalarValue::Duration {
        months,
        days,
        seconds,
        nanos,
    }) = value
    else {
        return None;
    };
    Some(DurationParts {
        months: *months,
        days: *days,
        seconds: *seconds,
        nanos: *nanos,
    })
}

fn normalized_duration_scalar(
    months: i128,
    days: i128,
    seconds: i128,
    nanos: i128,
) -> Result<ScalarValue> {
    let seconds = seconds
        .checked_add(nanos.div_euclid(DURATION_NANOS_PER_SECOND))
        .ok_or_else(|| Error::new(ErrorCode::TemporalRange, "duration seconds overflow"))?;
    let nanos = nanos.rem_euclid(DURATION_NANOS_PER_SECOND);
    Ok(ScalarValue::Duration {
        months: i64::try_from(months)
            .map_err(|_| Error::new(ErrorCode::TemporalRange, "duration months overflow"))?,
        days: i64::try_from(days)
            .map_err(|_| Error::new(ErrorCode::TemporalRange, "duration days overflow"))?,
        seconds: i64::try_from(seconds)
            .map_err(|_| Error::new(ErrorCode::TemporalRange, "duration seconds overflow"))?,
        nanos: i32::try_from(nanos)
            .map_err(|_| Error::new(ErrorCode::TemporalRange, "duration nanoseconds overflow"))?,
    })
}

fn normalized_duration_value(
    months: i128,
    days: i128,
    seconds: i128,
    nanos: i128,
) -> Result<ResultValue> {
    normalized_duration_scalar(months, days, seconds, nanos).map(ResultValue::Scalar)
}

fn duration_property(
    months: i64,
    days: i64,
    seconds: i64,
    nanos: i32,
    property: &str,
) -> Result<ResultValue> {
    let nanos = i64::from(nanos);
    let value = match property.to_ascii_lowercase().as_str() {
        "years" => months / 12,
        "months" => months,
        "monthsofyear" => months % 12,
        "monthsofquarter" => months % 3,
        "quarters" => months / 3,
        "quartersofyear" => (months / 3) % 4,
        "weeks" => days / 7,
        "daysofweek" => days % 7,
        "days" => days,
        "hours" => seconds / 3_600,
        "minutesofhour" => (seconds / 60) % 60,
        "minutes" => seconds / 60,
        "secondsofminute" => seconds % 60,
        "seconds" => seconds,
        "millisecondsofsecond" => nanos / 1_000_000,
        "milliseconds" => seconds
            .checked_mul(1_000)
            .and_then(|value| value.checked_add(nanos / 1_000_000))
            .ok_or_else(|| {
                Error::new(ErrorCode::TemporalRange, "duration milliseconds overflow")
            })?,
        "microsecondsofsecond" => nanos / 1_000,
        "microseconds" => seconds
            .checked_mul(1_000_000)
            .and_then(|value| value.checked_add(nanos / 1_000))
            .ok_or_else(|| {
                Error::new(ErrorCode::TemporalRange, "duration microseconds overflow")
            })?,
        "nanosecondsofsecond" => nanos,
        "nanoseconds" => seconds
            .checked_mul(1_000_000_000)
            .and_then(|value| value.checked_add(nanos))
            .ok_or_else(|| Error::new(ErrorCode::TemporalRange, "duration nanoseconds overflow"))?,
        _ => {
            return Err(Error::new(
                ErrorCode::QueryType,
                format!("UnsupportedTemporalUnit: no such DURATION field `{property}`"),
            ));
        }
    };
    Ok(ResultValue::Scalar(ScalarValue::Integer(value)))
}

fn temporal_property(value: &ScalarValue, property: &str) -> Result<ResultValue> {
    let Some(accessor) = ResidentTemporalAccessor::from_property_name(property) else {
        return Err(unsupported_temporal_property(value.type_name(), property));
    };
    evaluate_temporal_accessor(value, accessor).map(ResultValue::Scalar)
}

/// Canonical Rust semantic owner for temporal and duration field access. The ordinary evaluator
/// and the resident CPU reference both enter here; accelerator kernels remain an independent
/// implementation checked against this result.
pub fn evaluate_temporal_accessor(
    value: &ScalarValue,
    accessor: ResidentTemporalAccessor,
) -> Result<ScalarValue> {
    let property_name = accessor.property_name();
    let resolved = match value {
        ScalarValue::Date(epoch_day) => temporal_date_property(*epoch_day, property_name)?,
        ScalarValue::LocalTime(nanos_of_day) => {
            temporal_clock_property(*nanos_of_day, property_name)?
        }
        ScalarValue::ZonedTime {
            nanos,
            offset_seconds,
        } => match temporal_clock_property(*nanos, property_name)? {
            Some(value) => Some(value),
            None => temporal_zone_property(
                &temporal_offset_string(*offset_seconds)?,
                *offset_seconds,
                None,
                property_name,
            )?,
        },
        ScalarValue::LocalDateTime { seconds, nanos } => {
            let local = IntervalLocalDateTime::from_stored(*seconds, *nanos)?;
            match temporal_date_property(local.epoch_day, property_name)? {
                Some(value) => Some(value),
                None => temporal_clock_property(local.nanos_of_day, property_name)?,
            }
        }
        ScalarValue::ZonedDateTime {
            seconds,
            nanos,
            timezone,
        } => temporal_zoned_datetime_property(*seconds, *nanos, timezone, property_name)?,
        ScalarValue::Duration {
            months,
            days,
            seconds,
            nanos,
        } => duration_property(*months, *days, *seconds, *nanos, property_name).map(Some)?,
        _ => None,
    };
    let resolved =
        resolved.ok_or_else(|| unsupported_temporal_property(value.type_name(), property_name))?;
    let ResultValue::Scalar(resolved) = resolved else {
        return Err(Error::internal(
            "temporal field accessor returned a non-scalar value",
        ));
    };
    Ok(resolved)
}

fn temporal_date_property(epoch_day: i64, property: &str) -> Result<Option<ResultValue>> {
    if !matches!(
        property,
        "year"
            | "quarter"
            | "month"
            | "week"
            | "weekyear"
            | "day"
            | "ordinalday"
            | "weekday"
            | "dayofweek"
            | "dayofquarter"
    ) {
        return Ok(None);
    }
    let date = CivilDate::from_epoch_day(epoch_day)?;
    let value = match property {
        "year" => date.year,
        "quarter" => i64::from((date.month - 1) / 3 + 1),
        "month" => i64::from(date.month),
        "week" => civil_iso_week(epoch_day)?.1,
        "weekyear" => civil_iso_week(epoch_day)?.0,
        "day" => i64::from(date.day),
        "ordinalday" => civil_ordinal_day(date)?,
        "weekday" | "dayofweek" => civil_iso_weekday(epoch_day),
        "dayofquarter" => civil_day_of_quarter(date)?,
        _ => return Ok(None),
    };
    Ok(Some(ResultValue::Scalar(ScalarValue::Integer(value))))
}

fn temporal_clock_property(nanos_of_day: i64, property: &str) -> Result<Option<ResultValue>> {
    if !matches!(
        property,
        "hour" | "minute" | "second" | "millisecond" | "microsecond" | "nanosecond"
    ) {
        return Ok(None);
    }
    validate_interval_clock(nanos_of_day)?;
    let seconds_of_day = nanos_of_day / 1_000_000_000;
    let nanos_of_second = nanos_of_day % 1_000_000_000;
    let value = match property {
        "hour" => seconds_of_day / 3_600,
        "minute" => (seconds_of_day / 60) % 60,
        "second" => seconds_of_day % 60,
        "millisecond" => nanos_of_second / 1_000_000,
        "microsecond" => nanos_of_second / 1_000,
        "nanosecond" => nanos_of_second,
        _ => return Ok(None),
    };
    Ok(Some(ResultValue::Scalar(ScalarValue::Integer(value))))
}

fn temporal_zoned_datetime_property(
    seconds: i64,
    nanos: u32,
    timezone: &str,
    property: &str,
) -> Result<Option<ResultValue>> {
    if property == "timezone" {
        return Ok(Some(string_value(timezone.to_owned())));
    }
    if property == "epochseconds" {
        return Ok(Some(ResultValue::Scalar(ScalarValue::Integer(seconds))));
    }
    if property == "epochmillis" {
        let milliseconds = seconds
            .checked_mul(1_000)
            .and_then(|value| value.checked_add(i64::from(nanos / 1_000_000)))
            .ok_or_else(|| Error::new(ErrorCode::TemporalRange, "datetime epochMillis overflow"))?;
        return Ok(Some(ResultValue::Scalar(ScalarValue::Integer(
            milliseconds,
        ))));
    }

    let offset_seconds = timezone_offset_at(seconds, nanos, timezone)?;
    if let Some(value) =
        temporal_zone_property(timezone, offset_seconds, Some((seconds, nanos)), property)?
    {
        return Ok(Some(value));
    }
    let local_seconds = seconds
        .checked_add(i64::from(offset_seconds))
        .ok_or_else(|| Error::new(ErrorCode::TemporalRange, "datetime local clock overflow"))?;
    let local = IntervalLocalDateTime::from_stored(local_seconds, nanos)?;
    match temporal_date_property(local.epoch_day, property)? {
        Some(value) => Ok(Some(value)),
        None => temporal_clock_property(local.nanos_of_day, property),
    }
}

fn temporal_zone_property(
    timezone: &str,
    offset_seconds: i32,
    instant: Option<(i64, u32)>,
    property: &str,
) -> Result<Option<ResultValue>> {
    let value = match property {
        "timezone" => string_value(timezone.to_owned()),
        "offset" => string_value(temporal_offset_string(offset_seconds)?),
        "offsetminutes" => {
            ResultValue::Scalar(ScalarValue::Integer(i64::from(offset_seconds) / 60))
        }
        "offsetseconds" => ResultValue::Scalar(ScalarValue::Integer(i64::from(offset_seconds))),
        "epochseconds" => match instant {
            Some((seconds, _)) => ResultValue::Scalar(ScalarValue::Integer(seconds)),
            None => return Ok(None),
        },
        "epochmillis" => match instant {
            Some((seconds, nanos)) => {
                let milliseconds = seconds
                    .checked_mul(1_000)
                    .and_then(|value| value.checked_add(i64::from(nanos / 1_000_000)))
                    .ok_or_else(|| {
                        Error::new(ErrorCode::TemporalRange, "datetime epochMillis overflow")
                    })?;
                ResultValue::Scalar(ScalarValue::Integer(milliseconds))
            }
            None => return Ok(None),
        },
        _ => return Ok(None),
    };
    Ok(Some(value))
}

fn temporal_offset_string(offset_seconds: i32) -> Result<String> {
    chrono::FixedOffset::east_opt(offset_seconds)
        .map(|offset| offset.to_string())
        .ok_or_else(|| Error::new(ErrorCode::TemporalRange, "temporal UTC offset is invalid"))
}

fn civil_iso_weekday(epoch_day: i64) -> i64 {
    (epoch_day.rem_euclid(7) + 3).rem_euclid(7) + 1
}

fn civil_iso_week(epoch_day: i64) -> Result<(i64, i64)> {
    let weekday = civil_iso_weekday(epoch_day);
    let thursday = epoch_day
        .checked_add(4 - weekday)
        .ok_or_else(|| Error::new(ErrorCode::TemporalRange, "ISO week date overflow"))?;
    let week_year = CivilDate::from_epoch_day(thursday)?.year;
    let january_fourth = CivilDate::new(week_year, 1, 4)?.epoch_day()?;
    let week_one_monday = january_fourth
        .checked_sub(civil_iso_weekday(january_fourth) - 1)
        .ok_or_else(|| Error::new(ErrorCode::TemporalRange, "ISO week date overflow"))?;
    Ok((week_year, (epoch_day - week_one_monday).div_euclid(7) + 1))
}

fn civil_ordinal_day(date: CivilDate) -> Result<i64> {
    let mut ordinal = i64::from(date.day);
    for month in 1..date.month {
        ordinal = ordinal
            .checked_add(i64::from(
                civil_days_in_month(date.year, month).ok_or_else(|| {
                    Error::new(ErrorCode::TemporalRange, "calendar month is invalid")
                })?,
            ))
            .ok_or_else(|| Error::new(ErrorCode::TemporalRange, "ordinal day overflow"))?;
    }
    Ok(ordinal)
}

fn civil_day_of_quarter(date: CivilDate) -> Result<i64> {
    let quarter_start = ((date.month - 1) / 3) * 3 + 1;
    let mut day = i64::from(date.day);
    for month in quarter_start..date.month {
        day = day
            .checked_add(i64::from(
                civil_days_in_month(date.year, month).ok_or_else(|| {
                    Error::new(ErrorCode::TemporalRange, "calendar month is invalid")
                })?,
            ))
            .ok_or_else(|| Error::new(ErrorCode::TemporalRange, "quarter day overflow"))?;
    }
    Ok(day)
}

fn unsupported_temporal_property(value_type: &str, property: &str) -> Error {
    Error::new(
        ErrorCode::QueryType,
        format!("UnsupportedTemporalUnit: no such {value_type} field `{property}`"),
    )
}

const TEMPORAL_MAX_YEAR: i64 = 999_999_999;

#[derive(Clone, Copy, Debug, PartialEq, Eq, PartialOrd, Ord)]
struct CivilDate {
    year: i64,
    month: u32,
    day: u32,
}

impl CivilDate {
    fn new(year: i64, month: u32, day: u32) -> Result<Self> {
        if !(-TEMPORAL_MAX_YEAR..=TEMPORAL_MAX_YEAR).contains(&year) {
            return Err(Error::new(
                ErrorCode::TemporalRange,
                "calendar year is outside the supported range",
            ));
        }
        let maximum = civil_days_in_month(year, month).ok_or_else(|| {
            Error::new(
                ErrorCode::QueryType,
                "InvalidArgumentValue: calendar month must be between 1 and 12",
            )
        })?;
        if day == 0 || day > maximum {
            return Err(Error::new(
                ErrorCode::QueryType,
                "InvalidArgumentValue: calendar day is invalid for the month",
            ));
        }
        Ok(Self { year, month, day })
    }

    fn from_epoch_day(epoch_day: i64) -> Result<Self> {
        let shifted = i128::from(epoch_day)
            .checked_add(719_468)
            .ok_or_else(|| Error::new(ErrorCode::TemporalRange, "calendar day overflow"))?;
        let era = shifted.div_euclid(146_097);
        let day_of_era = shifted - era * 146_097;
        let year_of_era =
            (day_of_era - day_of_era / 1_460 + day_of_era / 36_524 - day_of_era / 146_096) / 365;
        let mut year = year_of_era + era * 400;
        let day_of_year = day_of_era - (365 * year_of_era + year_of_era / 4 - year_of_era / 100);
        let month_prime = (5 * day_of_year + 2) / 153;
        let day = day_of_year - (153 * month_prime + 2) / 5 + 1;
        let month = month_prime + if month_prime < 10 { 3 } else { -9 };
        if month <= 2 {
            year += 1;
        }
        Self::new(
            i64::try_from(year)
                .map_err(|_| Error::new(ErrorCode::TemporalRange, "calendar year overflow"))?,
            u32::try_from(month)
                .map_err(|_| Error::new(ErrorCode::TemporalRange, "calendar month overflow"))?,
            u32::try_from(day)
                .map_err(|_| Error::new(ErrorCode::TemporalRange, "calendar day overflow"))?,
        )
    }

    fn epoch_day(self) -> Result<i64> {
        let mut year = i128::from(self.year);
        if self.month <= 2 {
            year -= 1;
        }
        let era = year.div_euclid(400);
        let year_of_era = year - era * 400;
        let month_prime = i128::from(self.month) + if self.month > 2 { -3 } else { 9 };
        let day_of_year = (153 * month_prime + 2) / 5 + i128::from(self.day) - 1;
        let day_of_era = year_of_era * 365 + year_of_era / 4 - year_of_era / 100 + day_of_year;
        let epoch_day = era
            .checked_mul(146_097)
            .and_then(|value| value.checked_add(day_of_era))
            .and_then(|value| value.checked_sub(719_468))
            .ok_or_else(|| Error::new(ErrorCode::TemporalRange, "calendar day overflow"))?;
        i64::try_from(epoch_day)
            .map_err(|_| Error::new(ErrorCode::TemporalRange, "calendar day overflow"))
    }

    fn add_months(self, months: i64) -> Result<Self> {
        let total_month = i128::from(self.year)
            .checked_mul(12)
            .and_then(|value| value.checked_add(i128::from(self.month - 1)))
            .and_then(|value| value.checked_add(i128::from(months)))
            .ok_or_else(|| Error::new(ErrorCode::TemporalRange, "calendar month overflow"))?;
        let year = i64::try_from(total_month.div_euclid(12))
            .map_err(|_| Error::new(ErrorCode::TemporalRange, "calendar year overflow"))?;
        let month = u32::try_from(total_month.rem_euclid(12) + 1)
            .map_err(|_| Error::new(ErrorCode::TemporalRange, "calendar month overflow"))?;
        let maximum = civil_days_in_month(year, month).ok_or_else(|| {
            Error::new(
                ErrorCode::TemporalRange,
                "calendar month is outside its range",
            )
        })?;
        Self::new(year, month, self.day.min(maximum))
    }
}

const fn civil_is_leap_year(year: i64) -> bool {
    year.rem_euclid(4) == 0 && (year.rem_euclid(100) != 0 || year.rem_euclid(400) == 0)
}

const fn civil_days_in_month(year: i64, month: u32) -> Option<u32> {
    match month {
        1 | 3 | 5 | 7 | 8 | 10 | 12 => Some(31),
        4 | 6 | 9 | 11 => Some(30),
        2 if civil_is_leap_year(year) => Some(29),
        2 => Some(28),
        _ => None,
    }
}

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
struct IntervalLocalDateTime {
    epoch_day: i64,
    nanos_of_day: i64,
}

impl IntervalLocalDateTime {
    fn from_stored(seconds: i64, nanos: u32) -> Result<Self> {
        if nanos >= 1_000_000_000 {
            return Err(Error::new(
                ErrorCode::TemporalRange,
                "local datetime nanoseconds are invalid",
            ));
        }
        let epoch_day = seconds.div_euclid(86_400);
        let second_of_day = seconds.rem_euclid(86_400);
        let nanos_of_day = second_of_day
            .checked_mul(1_000_000_000)
            .and_then(|value| value.checked_add(i64::from(nanos)))
            .ok_or_else(|| Error::new(ErrorCode::TemporalRange, "local datetime overflow"))?;
        CivilDate::from_epoch_day(epoch_day)?;
        Ok(Self {
            epoch_day,
            nanos_of_day,
        })
    }

    fn stored(self) -> Result<(i64, u32)> {
        if !(0..DURATION_NANOS_PER_DAY as i64).contains(&self.nanos_of_day) {
            return Err(Error::new(
                ErrorCode::TemporalRange,
                "local datetime clock is outside one day",
            ));
        }
        let seconds = self
            .epoch_day
            .checked_mul(86_400)
            .and_then(|value| value.checked_add(self.nanos_of_day / 1_000_000_000))
            .ok_or_else(|| Error::new(ErrorCode::TemporalRange, "local datetime overflow"))?;
        let nanos = u32::try_from(self.nanos_of_day % 1_000_000_000).map_err(|_| {
            Error::new(
                ErrorCode::TemporalRange,
                "local datetime nanoseconds are invalid",
            )
        })?;
        Ok((seconds, nanos))
    }

    fn date(self) -> Result<CivilDate> {
        CivilDate::from_epoch_day(self.epoch_day)
    }

    fn add_months(self, months: i64) -> Result<Self> {
        let date = self.date()?.add_months(months)?;
        Ok(Self {
            epoch_day: date.epoch_day()?,
            nanos_of_day: self.nanos_of_day,
        })
    }

    fn add_days(self, days: i64) -> Result<Self> {
        Ok(Self {
            epoch_day: self
                .epoch_day
                .checked_add(days)
                .ok_or_else(|| Error::new(ErrorCode::TemporalRange, "calendar day overflow"))?,
            nanos_of_day: self.nanos_of_day,
        })
    }
}

#[derive(Clone, Debug, PartialEq, Eq)]
enum IntervalZone {
    Fixed(i32),
    Named(Arc<str>),
}

impl IntervalZone {
    fn parse(timezone: &str) -> Result<Self> {
        if timezone.eq_ignore_ascii_case("UTC") || timezone.eq_ignore_ascii_case("Z") {
            return Ok(Self::Fixed(0));
        }
        if let Ok(offset) = timezone.parse::<chrono::FixedOffset>() {
            return Ok(Self::Fixed(offset.local_minus_utc()));
        }
        let zone = timezone.parse::<chrono_tz::Tz>().map_err(|_| {
            Error::new(
                ErrorCode::QueryType,
                format!("InvalidArgumentValue: unknown timezone `{timezone}`"),
            )
        })?;
        Ok(Self::Named(Arc::from(zone.name())))
    }

    fn offset_at(&self, seconds: i64, nanos: u32) -> Result<i32> {
        match self {
            Self::Fixed(offset) => Ok(*offset),
            Self::Named(timezone) => timezone_offset_at(seconds, nanos, timezone),
        }
    }
}

#[derive(Clone, Debug, PartialEq, Eq)]
enum IntervalTemporal {
    Date {
        epoch_day: i64,
    },
    LocalTime {
        nanos_of_day: i64,
    },
    ZonedTime {
        nanos_of_day: i64,
        offset_seconds: i32,
    },
    LocalDateTime(IntervalLocalDateTime),
    ZonedDateTime {
        seconds: i64,
        nanos: u32,
        zone: IntervalZone,
    },
}

impl IntervalTemporal {
    fn from_value(value: &ResultValue) -> Result<Self> {
        match value {
            ResultValue::Scalar(ScalarValue::Date(days)) => {
                let epoch_day = i64::from(*days);
                CivilDate::from_epoch_day(epoch_day)?;
                Ok(Self::Date { epoch_day })
            }
            ResultValue::Scalar(ScalarValue::LocalTime(nanos_of_day)) => {
                validate_interval_clock(*nanos_of_day)?;
                Ok(Self::LocalTime {
                    nanos_of_day: *nanos_of_day,
                })
            }
            ResultValue::Scalar(ScalarValue::ZonedTime {
                nanos,
                offset_seconds,
            }) => {
                validate_interval_clock(*nanos)?;
                Ok(Self::ZonedTime {
                    nanos_of_day: *nanos,
                    offset_seconds: *offset_seconds,
                })
            }
            ResultValue::Scalar(ScalarValue::LocalDateTime { seconds, nanos }) => Ok(
                Self::LocalDateTime(IntervalLocalDateTime::from_stored(*seconds, *nanos)?),
            ),
            ResultValue::Scalar(ScalarValue::ZonedDateTime {
                seconds,
                nanos,
                timezone,
            }) => Ok(Self::ZonedDateTime {
                seconds: *seconds,
                nanos: *nanos,
                zone: IntervalZone::parse(timezone)?,
            }),
            _ => Err(Error::new(
                ErrorCode::QueryType,
                "InvalidArgumentType: duration between functions require temporal values",
            )),
        }
    }

    const fn has_date(&self) -> bool {
        matches!(
            self,
            Self::Date { .. } | Self::LocalDateTime(_) | Self::ZonedDateTime { .. }
        )
    }

    const fn has_time(&self) -> bool {
        !matches!(self, Self::Date { .. })
    }

    fn zone(&self) -> Option<IntervalZone> {
        match self {
            Self::ZonedTime { offset_seconds, .. } => Some(IntervalZone::Fixed(*offset_seconds)),
            Self::ZonedDateTime { zone, .. } => Some(zone.clone()),
            _ => None,
        }
    }

    fn date_epoch_day(&self) -> Result<i64> {
        match self {
            Self::Date { epoch_day } => Ok(*epoch_day),
            Self::LocalDateTime(local) => Ok(local.epoch_day),
            Self::ZonedDateTime {
                seconds,
                nanos,
                zone,
            } => Ok(zoned_interval_local(*seconds, *nanos, zone)?.epoch_day),
            _ => Err(Error::new(
                ErrorCode::QueryType,
                "temporal value has no date component",
            )),
        }
    }

    fn attach_time(self) -> Self {
        match self {
            Self::Date { epoch_day } => Self::LocalDateTime(IntervalLocalDateTime {
                epoch_day,
                nanos_of_day: 0,
            }),
            value => value,
        }
    }

    fn attach_date(self, epoch_day: i64) -> Result<Self> {
        match self {
            Self::LocalTime { nanos_of_day } => Ok(Self::LocalDateTime(IntervalLocalDateTime {
                epoch_day,
                nanos_of_day,
            })),
            Self::ZonedTime {
                nanos_of_day,
                offset_seconds,
            } => interval_zoned_from_local(
                IntervalLocalDateTime {
                    epoch_day,
                    nanos_of_day,
                },
                IntervalZone::Fixed(offset_seconds),
            ),
            value => Ok(value),
        }
    }

    fn attach_zone(self, zone: IntervalZone) -> Result<Self> {
        match self {
            Self::LocalTime { nanos_of_day } => match zone {
                IntervalZone::Fixed(offset_seconds) => Ok(Self::ZonedTime {
                    nanos_of_day,
                    offset_seconds,
                }),
                IntervalZone::Named(_) => Err(Error::new(
                    ErrorCode::QueryType,
                    "named timezones cannot be attached to a local time without a date",
                )),
            },
            Self::LocalDateTime(local) => interval_zoned_from_local(local, zone),
            value => Ok(value),
        }
    }

    fn add_months(self, months: i64) -> Result<Self> {
        match self {
            Self::Date { epoch_day } => {
                let date = CivilDate::from_epoch_day(epoch_day)?.add_months(months)?;
                Ok(Self::Date {
                    epoch_day: date.epoch_day()?,
                })
            }
            Self::LocalDateTime(local) => Ok(Self::LocalDateTime(local.add_months(months)?)),
            Self::ZonedDateTime {
                seconds,
                nanos,
                zone,
            } => {
                let local = zoned_interval_local(seconds, nanos, &zone)?.add_months(months)?;
                interval_zoned_from_local(local, zone)
            }
            _ => Err(Error::new(
                ErrorCode::QueryType,
                "months cannot be added to a temporal value without a date",
            )),
        }
    }

    fn add_days(self, days: i64) -> Result<Self> {
        match self {
            Self::Date { epoch_day } => Ok(Self::Date {
                epoch_day: epoch_day
                    .checked_add(days)
                    .ok_or_else(|| Error::new(ErrorCode::TemporalRange, "calendar day overflow"))?,
            }),
            Self::LocalDateTime(local) => Ok(Self::LocalDateTime(local.add_days(days)?)),
            Self::ZonedDateTime {
                seconds,
                nanos,
                zone,
            } => {
                let local = zoned_interval_local(seconds, nanos, &zone)?.add_days(days)?;
                interval_zoned_from_local(local, zone)
            }
            _ => Err(Error::new(
                ErrorCode::QueryType,
                "days cannot be added to a temporal value without a date",
            )),
        }
    }
}

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
enum IntervalUnit {
    Months,
    Days,
    Nanos,
}

fn validate_interval_clock(nanos_of_day: i64) -> Result<()> {
    if (0..DURATION_NANOS_PER_DAY as i64).contains(&nanos_of_day) {
        Ok(())
    } else {
        Err(Error::new(
            ErrorCode::TemporalRange,
            "temporal clock is outside one day",
        ))
    }
}

fn zoned_interval_local(
    seconds: i64,
    nanos: u32,
    zone: &IntervalZone,
) -> Result<IntervalLocalDateTime> {
    let offset = i64::from(zone.offset_at(seconds, nanos)?);
    let local_seconds = seconds
        .checked_add(offset)
        .ok_or_else(|| Error::new(ErrorCode::TemporalRange, "zoned datetime overflow"))?;
    IntervalLocalDateTime::from_stored(local_seconds, nanos)
}

fn interval_zoned_from_local(
    local: IntervalLocalDateTime,
    zone: IntervalZone,
) -> Result<IntervalTemporal> {
    let (local_seconds, nanos) = local.stored()?;
    let seconds = match &zone {
        IntervalZone::Fixed(offset_seconds) => local_seconds
            .checked_sub(i64::from(*offset_seconds))
            .ok_or_else(|| Error::new(ErrorCode::TemporalRange, "zoned datetime overflow"))?,
        IntervalZone::Named(timezone) => {
            let date = local.date()?;
            let year = i32::try_from(date.year).map_err(|_| {
                Error::new(
                    ErrorCode::TemporalRange,
                    "named-zone datetime is outside the supported calendar range",
                )
            })?;
            let date =
                chrono::NaiveDate::from_ymd_opt(year, date.month, date.day).ok_or_else(|| {
                    Error::new(
                        ErrorCode::TemporalRange,
                        "named-zone datetime is outside the supported calendar range",
                    )
                })?;
            let local = date.and_time(clock_from_nanos(local.nanos_of_day)?);
            let ResultValue::Scalar(ScalarValue::ZonedDateTime { seconds, .. }) =
                zoned_datetime_scalar(local, timezone)?
            else {
                return Err(Error::internal(
                    "zoned datetime construction returned the wrong value type",
                ));
            };
            seconds
        }
    };
    Ok(IntervalTemporal::ZonedDateTime {
        seconds,
        nanos,
        zone,
    })
}

fn normalize_interval_pair(
    mut from: IntervalTemporal,
    mut to: IntervalTemporal,
    unit: IntervalUnit,
) -> Result<(IntervalTemporal, IntervalTemporal)> {
    if unit == IntervalUnit::Nanos {
        from = from.attach_time();
        to = to.attach_time();
    } else if from.has_time() && !to.has_time() {
        to = to.attach_time();
    } else if to.has_time() && !from.has_time() {
        from = from.attach_time();
    }

    if from.has_date() && !to.has_date() {
        to = to.attach_date(from.date_epoch_day()?)?;
    } else if to.has_date() && !from.has_date() {
        from = from.attach_date(to.date_epoch_day()?)?;
    }

    if let Some(zone) = from.zone()
        && to.zone().is_none()
    {
        to = to.attach_zone(zone)?;
    } else if let Some(zone) = to.zone()
        && from.zone().is_none()
    {
        from = from.attach_zone(zone)?;
    }
    Ok((from, to))
}

fn adjusted_end_epoch_day(from: IntervalLocalDateTime, to: IntervalLocalDateTime) -> Result<i64> {
    if to.epoch_day > from.epoch_day && to.nanos_of_day < from.nanos_of_day {
        to.epoch_day
            .checked_sub(1)
            .ok_or_else(|| Error::new(ErrorCode::TemporalRange, "calendar day overflow"))
    } else if to.epoch_day < from.epoch_day && to.nanos_of_day > from.nanos_of_day {
        to.epoch_day
            .checked_add(1)
            .ok_or_else(|| Error::new(ErrorCode::TemporalRange, "calendar day overflow"))
    } else {
        Ok(to.epoch_day)
    }
}

fn complete_months_between_dates(from: CivilDate, to: CivilDate) -> Result<i64> {
    let packed = |date: CivilDate| {
        i128::from(date.year)
            .checked_mul(12)
            .and_then(|value| value.checked_add(i128::from(date.month - 1)))
            .and_then(|value| value.checked_mul(32))
            .and_then(|value| value.checked_add(i128::from(date.day)))
    };
    let from = packed(from)
        .ok_or_else(|| Error::new(ErrorCode::TemporalRange, "calendar month overflow"))?;
    let to = packed(to)
        .ok_or_else(|| Error::new(ErrorCode::TemporalRange, "calendar month overflow"))?;
    i64::try_from((to - from) / 32)
        .map_err(|_| Error::new(ErrorCode::TemporalRange, "duration months overflow"))
}

fn interval_until_months(from: IntervalTemporal, to: IntervalTemporal) -> Result<i64> {
    let (from, to) = normalize_interval_pair(from, to, IntervalUnit::Months)?;
    match (from, to) {
        (
            IntervalTemporal::Date {
                epoch_day: from_day,
            },
            IntervalTemporal::Date { epoch_day: to_day },
        ) => complete_months_between_dates(
            CivilDate::from_epoch_day(from_day)?,
            CivilDate::from_epoch_day(to_day)?,
        ),
        (IntervalTemporal::LocalDateTime(from), IntervalTemporal::LocalDateTime(to)) => {
            let to_day = adjusted_end_epoch_day(from, to)?;
            complete_months_between_dates(from.date()?, CivilDate::from_epoch_day(to_day)?)
        }
        (
            IntervalTemporal::ZonedDateTime {
                seconds: from_seconds,
                nanos: from_nanos,
                zone: from_zone,
            },
            IntervalTemporal::ZonedDateTime {
                seconds: to_seconds,
                nanos: to_nanos,
                ..
            },
        ) => {
            let from = zoned_interval_local(from_seconds, from_nanos, &from_zone)?;
            let to = zoned_interval_local(to_seconds, to_nanos, &from_zone)?;
            let to_day = adjusted_end_epoch_day(from, to)?;
            complete_months_between_dates(from.date()?, CivilDate::from_epoch_day(to_day)?)
        }
        _ => Err(Error::new(
            ErrorCode::QueryType,
            "UnsupportedTemporalUnit: months require temporal values with a date",
        )),
    }
}

fn interval_until_days(from: IntervalTemporal, to: IntervalTemporal) -> Result<i64> {
    let (from, to) = normalize_interval_pair(from, to, IntervalUnit::Days)?;
    match (from, to) {
        (
            IntervalTemporal::Date {
                epoch_day: from_day,
            },
            IntervalTemporal::Date { epoch_day: to_day },
        ) => to_day
            .checked_sub(from_day)
            .ok_or_else(|| Error::new(ErrorCode::TemporalRange, "duration days overflow")),
        (IntervalTemporal::LocalDateTime(from), IntervalTemporal::LocalDateTime(to)) => {
            adjusted_end_epoch_day(from, to)?
                .checked_sub(from.epoch_day)
                .ok_or_else(|| Error::new(ErrorCode::TemporalRange, "duration days overflow"))
        }
        (
            IntervalTemporal::ZonedDateTime {
                seconds: from_seconds,
                nanos: from_nanos,
                zone: from_zone,
            },
            IntervalTemporal::ZonedDateTime {
                seconds: to_seconds,
                nanos: to_nanos,
                ..
            },
        ) => {
            let from = zoned_interval_local(from_seconds, from_nanos, &from_zone)?;
            let to = zoned_interval_local(to_seconds, to_nanos, &from_zone)?;
            adjusted_end_epoch_day(from, to)?
                .checked_sub(from.epoch_day)
                .ok_or_else(|| Error::new(ErrorCode::TemporalRange, "duration days overflow"))
        }
        _ => Err(Error::new(
            ErrorCode::QueryType,
            "UnsupportedTemporalUnit: days require temporal values with a date",
        )),
    }
}

fn checked_interval_nanos(epoch_day: i64, nanos_of_day: i64) -> Result<i128> {
    i128::from(epoch_day)
        .checked_mul(DURATION_NANOS_PER_DAY)
        .and_then(|value| value.checked_add(i128::from(nanos_of_day)))
        .ok_or_else(|| Error::new(ErrorCode::TemporalRange, "temporal nanosecond overflow"))
}

fn checked_instant_nanos(seconds: i64, nanos: u32) -> Result<i128> {
    i128::from(seconds)
        .checked_mul(DURATION_NANOS_PER_SECOND)
        .and_then(|value| value.checked_add(i128::from(nanos)))
        .ok_or_else(|| Error::new(ErrorCode::TemporalRange, "temporal nanosecond overflow"))
}

fn interval_until_nanos(from: IntervalTemporal, to: IntervalTemporal) -> Result<i128> {
    let (from, to) = normalize_interval_pair(from, to, IntervalUnit::Nanos)?;
    let (from, to) = match (from, to) {
        (
            IntervalTemporal::LocalTime { nanos_of_day: from },
            IntervalTemporal::LocalTime { nanos_of_day: to },
        ) => (i128::from(from), i128::from(to)),
        (
            IntervalTemporal::ZonedTime {
                nanos_of_day: from,
                offset_seconds: from_offset,
            },
            IntervalTemporal::ZonedTime {
                nanos_of_day: to,
                offset_seconds: to_offset,
            },
        ) => (
            i128::from(from) - i128::from(from_offset) * DURATION_NANOS_PER_SECOND,
            i128::from(to) - i128::from(to_offset) * DURATION_NANOS_PER_SECOND,
        ),
        (IntervalTemporal::LocalDateTime(from), IntervalTemporal::LocalDateTime(to)) => (
            checked_interval_nanos(from.epoch_day, from.nanos_of_day)?,
            checked_interval_nanos(to.epoch_day, to.nanos_of_day)?,
        ),
        (
            IntervalTemporal::ZonedDateTime {
                seconds: from_seconds,
                nanos: from_nanos,
                ..
            },
            IntervalTemporal::ZonedDateTime {
                seconds: to_seconds,
                nanos: to_nanos,
                ..
            },
        ) => (
            checked_instant_nanos(from_seconds, from_nanos)?,
            checked_instant_nanos(to_seconds, to_nanos)?,
        ),
        _ => {
            return Err(Error::new(
                ErrorCode::QueryType,
                "temporal values cannot be normalized to a common clock",
            ));
        }
    };
    to.checked_sub(from)
        .ok_or_else(|| Error::new(ErrorCode::TemporalRange, "duration seconds overflow"))
}

fn temporal_duration_function(name: &str, values: &[ResultValue]) -> Result<ResultValue> {
    require_arity(name, values, 2)?;
    if values.iter().any(is_null_value) {
        return Ok(ResultValue::Scalar(ScalarValue::Null));
    }
    let from = IntervalTemporal::from_value(&values[0])?;
    let to = IntervalTemporal::from_value(&values[1])?;
    match name {
        "duration.inmonths" => {
            normalized_duration_value(i128::from(interval_until_months(from, to)?), 0, 0, 0)
        }
        "duration.indays" => {
            normalized_duration_value(0, i128::from(interval_until_days(from, to)?), 0, 0)
        }
        "duration.inseconds" => normalized_duration_value(0, 0, 0, interval_until_nanos(from, to)?),
        "duration.between" => {
            let mut cursor = from.clone();
            let (months, days) = if from.has_date() && to.has_date() {
                let months = interval_until_months(cursor.clone(), to.clone())?;
                cursor = cursor.add_months(months)?;
                let days = interval_until_days(cursor.clone(), to.clone())?;
                cursor = cursor.add_days(days)?;
                (months, days)
            } else {
                (0, 0)
            };
            normalized_duration_value(
                i128::from(months),
                i128::from(days),
                0,
                interval_until_nanos(cursor, to)?,
            )
        }
        _ => Err(Error::internal(
            "temporal duration function dispatch is inconsistent",
        )),
    }
}

fn duration_constructor(value: &ResultValue) -> Result<ResultValue> {
    match value {
        ResultValue::Scalar(ScalarValue::String(value)) => {
            parse_duration(value).map(ResultValue::Scalar)
        }
        ResultValue::Map(map) => duration_from_map(map),
        ResultValue::Scalar(ScalarValue::Null) => Ok(ResultValue::Scalar(ScalarValue::Null)),
        _ => Err(Error::new(
            ErrorCode::QueryType,
            "InvalidArgumentType: duration requires a STRING or MAP",
        )),
    }
}

fn duration_map_number(map: &BTreeMap<String, ResultValue>, key: &str) -> Result<DurationNumber> {
    match map.get(key) {
        None => Ok(DurationNumber::Integer(0)),
        Some(ResultValue::Scalar(ScalarValue::Integer(value))) => {
            Ok(DurationNumber::Integer(*value))
        }
        Some(ResultValue::Scalar(ScalarValue::Float(value))) => {
            let value = value.into_inner();
            if value.is_finite() {
                Ok(DurationNumber::Float(value))
            } else {
                Err(Error::new(
                    ErrorCode::QueryType,
                    format!("InvalidArgumentValue: duration field `{key}` must be finite"),
                ))
            }
        }
        Some(_) => Err(Error::new(
            ErrorCode::QueryType,
            format!("InvalidArgumentType: duration field `{key}` must be numeric"),
        )),
    }
}

fn duration_from_map(map: &BTreeMap<String, ResultValue>) -> Result<ResultValue> {
    for key in map.keys() {
        if !matches!(
            key.as_str(),
            "years"
                | "months"
                | "weeks"
                | "days"
                | "hours"
                | "minutes"
                | "seconds"
                | "milliseconds"
                | "microseconds"
                | "nanoseconds"
        ) {
            return Err(Error::new(
                ErrorCode::QueryType,
                format!("InvalidArgumentValue: `{key}` is not a duration field"),
            ));
        }
    }

    let years = duration_map_number(map, "years")?;
    let months = duration_map_number(map, "months")?;
    let weeks = duration_map_number(map, "weeks")?;
    let days = duration_map_number(map, "days")?;
    let hours = duration_map_number(map, "hours")?;
    let minutes = duration_map_number(map, "minutes")?;
    let seconds = duration_map_number(map, "seconds")?;
    let milliseconds = duration_map_number(map, "milliseconds")?;
    let microseconds = duration_map_number(map, "microseconds")?;
    let nanoseconds = duration_map_number(map, "nanoseconds")?;
    let has_float = [
        years,
        months,
        weeks,
        days,
        hours,
        minutes,
        seconds,
        milliseconds,
        microseconds,
        nanoseconds,
    ]
    .into_iter()
    .any(DurationNumber::is_float);

    if has_float {
        return approximate_duration_value(
            years.as_f64() * 12.0 + months.as_f64(),
            weeks.as_f64() * 7.0 + days.as_f64(),
            hours.as_f64() * 3_600.0 + minutes.as_f64() * 60.0 + seconds.as_f64(),
            milliseconds.as_f64() * 1_000_000.0
                + microseconds.as_f64() * 1_000.0
                + nanoseconds.as_f64(),
        );
    }

    let years = years.as_i128()?;
    let months = months.as_i128()?;
    let weeks = weeks.as_i128()?;
    let days = days.as_i128()?;
    let hours = hours.as_i128()?;
    let minutes = minutes.as_i128()?;
    let seconds = seconds.as_i128()?;
    let milliseconds = milliseconds.as_i128()?;
    let microseconds = microseconds.as_i128()?;
    let nanoseconds = nanoseconds.as_i128()?;

    let months = years
        .checked_mul(12)
        .and_then(|value| value.checked_add(months))
        .ok_or_else(|| Error::new(ErrorCode::TemporalRange, "duration months overflow"))?;
    let days = weeks
        .checked_mul(7)
        .and_then(|value| value.checked_add(days))
        .ok_or_else(|| Error::new(ErrorCode::TemporalRange, "duration days overflow"))?;
    let seconds = hours
        .checked_mul(3_600)
        .and_then(|value| {
            minutes
                .checked_mul(60)
                .and_then(|minutes| value.checked_add(minutes))
        })
        .and_then(|value| value.checked_add(seconds))
        .ok_or_else(|| Error::new(ErrorCode::TemporalRange, "duration seconds overflow"))?;
    let nanos = milliseconds
        .checked_mul(1_000_000)
        .and_then(|value| {
            microseconds
                .checked_mul(1_000)
                .and_then(|microseconds| value.checked_add(microseconds))
        })
        .and_then(|value| value.checked_add(nanoseconds))
        .ok_or_else(|| Error::new(ErrorCode::TemporalRange, "duration nanoseconds overflow"))?;
    normalized_duration_value(months, days, seconds, nanos)
}

fn approximate_duration_value(
    months: f64,
    mut days: f64,
    mut seconds: f64,
    mut nanos: f64,
) -> Result<ResultValue> {
    let months_whole = duration_f64_to_i64(months, "months")?;
    days += DURATION_AVERAGE_SECONDS_PER_MONTH * (months - months_whole as f64)
        / DURATION_SECONDS_PER_DAY as f64;
    let days_whole = duration_f64_to_i64(days, "days")?;
    seconds += DURATION_SECONDS_PER_DAY as f64 * (days - days_whole as f64);
    let seconds_whole = duration_f64_to_i64(seconds, "seconds")?;
    nanos += DURATION_NANOS_PER_SECOND as f64 * (seconds - seconds_whole as f64);
    let nanos_whole = duration_f64_to_i64(nanos, "nanoseconds")?;
    normalized_duration_value(
        i128::from(months_whole),
        i128::from(days_whole),
        i128::from(seconds_whole),
        i128::from(nanos_whole),
    )
}

fn duration_f64_to_i64(value: f64, component: &str) -> Result<i64> {
    const LOWER: f64 = i64::MIN as f64;
    const UPPER_EXCLUSIVE: f64 = 9_223_372_036_854_775_808.0;
    if value.is_finite() && value >= LOWER && value < UPPER_EXCLUSIVE {
        Ok(value.trunc() as i64)
    } else {
        Err(Error::new(
            ErrorCode::TemporalRange,
            format!("duration {component} component is outside the supported range"),
        ))
    }
}

fn evaluate_duration_addition(
    left: &ResultValue,
    right: &ResultValue,
) -> Result<Option<ResultValue>> {
    match (duration_parts(left), duration_parts(right)) {
        (Some(left), Some(right)) => duration_duration_arithmetic(left, right, 1).map(Some),
        (Some(duration), None) if is_temporal_value(right) => {
            apply_duration_to_temporal(right, duration, 1).map(Some)
        }
        (None, Some(duration)) if is_temporal_value(left) => {
            apply_duration_to_temporal(left, duration, 1).map(Some)
        }
        _ => Ok(None),
    }
}

fn evaluate_duration_subtraction(
    left: &ResultValue,
    right: &ResultValue,
) -> Result<Option<ResultValue>> {
    match (duration_parts(left), duration_parts(right)) {
        (Some(left), Some(right)) => duration_duration_arithmetic(left, right, -1).map(Some),
        (None, Some(duration)) if is_temporal_value(left) => {
            apply_duration_to_temporal(left, duration, -1).map(Some)
        }
        _ => Ok(None),
    }
}

fn evaluate_duration_multiplication(
    left: &ResultValue,
    right: &ResultValue,
) -> Result<Option<ResultValue>> {
    if let Some(duration) = duration_parts(left)
        && let Some(factor) = duration_numeric_value(right)
    {
        return scale_duration(duration, factor).map(Some);
    }
    if let Some(duration) = duration_parts(right)
        && let Some(factor) = duration_numeric_value(left)
    {
        return scale_duration(duration, factor).map(Some);
    }
    Ok(None)
}

fn evaluate_duration_division(
    left: &ResultValue,
    right: &ResultValue,
) -> Result<Option<ResultValue>> {
    let Some(duration) = duration_parts(left) else {
        return Ok(None);
    };
    let Some(divisor) = duration_numeric_value(right) else {
        return Ok(None);
    };
    let divisor = divisor.as_f64();
    if divisor == 0.0 {
        return Err(Error::new(
            ErrorCode::QueryType,
            "cannot divide a duration by zero",
        ));
    }
    approximate_duration_value(
        duration.months as f64 / divisor,
        duration.days as f64 / divisor,
        duration.seconds as f64 / divisor,
        f64::from(duration.nanos) / divisor,
    )
    .map(Some)
}

fn duration_numeric_value(value: &ResultValue) -> Option<DurationNumber> {
    match value {
        ResultValue::Scalar(ScalarValue::Integer(value)) => Some(DurationNumber::Integer(*value)),
        ResultValue::Scalar(ScalarValue::Float(value)) => {
            Some(DurationNumber::Float(value.into_inner()))
        }
        _ => None,
    }
}

fn duration_duration_arithmetic(
    left: DurationParts,
    right: DurationParts,
    right_sign: i128,
) -> Result<ResultValue> {
    let combine =
        |left: i64, right: i64| i128::from(left).checked_add(i128::from(right) * right_sign);
    normalized_duration_value(
        combine(left.months, right.months)
            .ok_or_else(|| Error::new(ErrorCode::TemporalRange, "duration months overflow"))?,
        combine(left.days, right.days)
            .ok_or_else(|| Error::new(ErrorCode::TemporalRange, "duration days overflow"))?,
        combine(left.seconds, right.seconds)
            .ok_or_else(|| Error::new(ErrorCode::TemporalRange, "duration seconds overflow"))?,
        i128::from(left.nanos)
            .checked_add(i128::from(right.nanos) * right_sign)
            .ok_or_else(|| Error::new(ErrorCode::TemporalRange, "duration nanoseconds overflow"))?,
    )
}

fn scale_duration(duration: DurationParts, factor: DurationNumber) -> Result<ResultValue> {
    match factor {
        DurationNumber::Integer(factor) => {
            let factor = i128::from(factor);
            normalized_duration_value(
                i128::from(duration.months)
                    .checked_mul(factor)
                    .ok_or_else(|| {
                        Error::new(ErrorCode::TemporalRange, "duration months overflow")
                    })?,
                i128::from(duration.days)
                    .checked_mul(factor)
                    .ok_or_else(|| {
                        Error::new(ErrorCode::TemporalRange, "duration days overflow")
                    })?,
                i128::from(duration.seconds)
                    .checked_mul(factor)
                    .ok_or_else(|| {
                        Error::new(ErrorCode::TemporalRange, "duration seconds overflow")
                    })?,
                i128::from(duration.nanos)
                    .checked_mul(factor)
                    .ok_or_else(|| {
                        Error::new(ErrorCode::TemporalRange, "duration nanoseconds overflow")
                    })?,
            )
        }
        DurationNumber::Float(factor) => approximate_duration_value(
            duration.months as f64 * factor,
            duration.days as f64 * factor,
            duration.seconds as f64 * factor,
            f64::from(duration.nanos) * factor,
        ),
    }
}

const fn is_temporal_value(value: &ResultValue) -> bool {
    matches!(
        value,
        ResultValue::Scalar(
            ScalarValue::Date(_)
                | ScalarValue::LocalTime(_)
                | ScalarValue::ZonedTime { .. }
                | ScalarValue::LocalDateTime { .. }
                | ScalarValue::ZonedDateTime { .. }
        )
    )
}

fn apply_duration_to_temporal(
    temporal: &ResultValue,
    duration: DurationParts,
    direction: i128,
) -> Result<ResultValue> {
    match temporal {
        ResultValue::Scalar(ScalarValue::Date(days)) => {
            let months = i128::from(duration.months)
                .checked_mul(direction)
                .and_then(|value| i64::try_from(value).ok())
                .ok_or_else(|| Error::new(ErrorCode::TemporalRange, "date duration overflow"))?;
            let date = CivilDate::from_epoch_day(*days)?.add_months(months)?;
            let elapsed_days = i128::from(duration.seconds) / DURATION_SECONDS_PER_DAY;
            let days = i128::from(duration.days)
                .checked_add(elapsed_days)
                .and_then(|days| days.checked_mul(direction))
                .ok_or_else(|| Error::new(ErrorCode::TemporalRange, "date duration overflow"))?;
            let days = i128::from(date.epoch_day()?)
                .checked_add(days)
                .and_then(|value| i64::try_from(value).ok())
                .ok_or_else(|| Error::new(ErrorCode::TemporalRange, "date duration overflow"))?;
            CivilDate::from_epoch_day(days)?;
            Ok(ResultValue::Scalar(ScalarValue::Date(days)))
        }
        ResultValue::Scalar(ScalarValue::LocalTime(nanos)) => {
            let nanos = checked_add_clock_duration(*nanos, duration, direction)?;
            Ok(ResultValue::Scalar(ScalarValue::LocalTime(nanos)))
        }
        ResultValue::Scalar(ScalarValue::ZonedTime {
            nanos,
            offset_seconds,
        }) => {
            let nanos = checked_add_clock_duration(*nanos, duration, direction)?;
            Ok(ResultValue::Scalar(ScalarValue::ZonedTime {
                nanos,
                offset_seconds: *offset_seconds,
            }))
        }
        ResultValue::Scalar(ScalarValue::LocalDateTime { seconds, nanos }) => {
            let local = local_datetime_from_stored(*seconds, *nanos)?;
            let local = checked_add_calendar_to_local_datetime(local, duration, direction)?;
            let (seconds, nanos) = checked_add_timestamp_duration(
                local.and_utc().timestamp(),
                local.and_utc().timestamp_subsec_nanos(),
                duration,
                direction,
            )?;
            local_datetime_scalar(local_datetime_from_stored(seconds, nanos)?)
        }
        ResultValue::Scalar(ScalarValue::ZonedDateTime {
            seconds,
            nanos,
            timezone,
        }) => {
            let (calendar_seconds, calendar_nanos) = if duration.months == 0 && duration.days == 0 {
                (*seconds, *nanos)
            } else {
                let local = zoned_datetime_local(*seconds, *nanos, timezone)?;
                let local = checked_add_calendar_to_local_datetime(local, duration, direction)?;
                let ResultValue::Scalar(ScalarValue::ZonedDateTime { seconds, nanos, .. }) =
                    zoned_datetime_scalar(local, timezone)?
                else {
                    return Err(Error::internal(
                        "zoned datetime construction returned the wrong value type",
                    ));
                };
                (seconds, nanos)
            };
            let (seconds, nanos) = checked_add_timestamp_duration(
                calendar_seconds,
                calendar_nanos,
                duration,
                direction,
            )?;
            zoned_datetime_at_instant(seconds, nanos, timezone)
        }
        _ => Err(Error::new(
            ErrorCode::QueryType,
            "duration arithmetic requires a temporal value",
        )),
    }
}

/// Canonical scalar entrypoint shared by native row backends and the generic evaluator.
/// Backends provide the already-normalized four duration components and receive the exact
/// canonical temporal shape; no backend is allowed to manufacture a host-side sort key.
pub fn apply_duration_to_temporal_scalar(
    temporal: &ScalarValue,
    months: i64,
    days: i64,
    seconds: i64,
    nanos: i32,
) -> Result<ScalarValue> {
    let result = apply_duration_to_temporal(
        &ResultValue::Scalar(temporal.clone()),
        DurationParts {
            months,
            days,
            seconds,
            nanos,
        },
        1,
    )?;
    let ResultValue::Scalar(result) = result else {
        return Err(Error::internal(
            "temporal duration arithmetic returned a non-scalar value",
        ));
    };
    Ok(result)
}

fn checked_add_calendar_to_local_datetime(
    local: chrono::NaiveDateTime,
    duration: DurationParts,
    direction: i128,
) -> Result<chrono::NaiveDateTime> {
    let date = checked_add_calendar_months(local.date(), i128::from(duration.months) * direction)?;
    let date = checked_add_calendar_days(date, i128::from(duration.days) * direction)?;
    Ok(date.and_time(local.time()))
}

fn checked_add_calendar_months(date: chrono::NaiveDate, months: i128) -> Result<chrono::NaiveDate> {
    let total_month = i128::from(date.year())
        .checked_mul(12)
        .and_then(|value| value.checked_add(i128::from(date.month0())))
        .and_then(|value| value.checked_add(months))
        .ok_or_else(|| Error::new(ErrorCode::TemporalRange, "calendar month overflow"))?;
    let year = i32::try_from(total_month.div_euclid(12))
        .map_err(|_| Error::new(ErrorCode::TemporalRange, "calendar year overflow"))?;
    let month = u32::try_from(total_month.rem_euclid(12) + 1)
        .map_err(|_| Error::new(ErrorCode::TemporalRange, "calendar month overflow"))?;
    let mut day = date.day();
    loop {
        if let Some(date) = chrono::NaiveDate::from_ymd_opt(year, month, day) {
            return Ok(date);
        }
        day = day.checked_sub(1).ok_or_else(|| {
            Error::new(
                ErrorCode::TemporalRange,
                "calendar date is outside the supported range",
            )
        })?;
    }
}

fn checked_add_calendar_days(date: chrono::NaiveDate, days: i128) -> Result<chrono::NaiveDate> {
    let days = i128::from(date.num_days_from_ce())
        .checked_add(days)
        .ok_or_else(|| Error::new(ErrorCode::TemporalRange, "calendar day overflow"))?;
    let days = i32::try_from(days)
        .map_err(|_| Error::new(ErrorCode::TemporalRange, "calendar day overflow"))?;
    chrono::NaiveDate::from_num_days_from_ce_opt(days).ok_or_else(|| {
        Error::new(
            ErrorCode::TemporalRange,
            "calendar date is outside the supported range",
        )
    })
}

fn checked_add_clock_duration(
    clock_nanos: i64,
    duration: DurationParts,
    direction: i128,
) -> Result<i64> {
    let elapsed = duration_elapsed_nanos(duration, direction)?;
    let clock = i128::from(clock_nanos)
        .checked_add(elapsed)
        .ok_or_else(|| Error::new(ErrorCode::TemporalRange, "time duration overflow"))?
        .rem_euclid(DURATION_NANOS_PER_DAY);
    i64::try_from(clock).map_err(|_| Error::new(ErrorCode::TemporalRange, "time duration overflow"))
}

fn duration_elapsed_nanos(duration: DurationParts, direction: i128) -> Result<i128> {
    i128::from(duration.seconds)
        .checked_mul(DURATION_NANOS_PER_SECOND)
        .and_then(|value| value.checked_add(i128::from(duration.nanos)))
        .and_then(|value| value.checked_mul(direction))
        .ok_or_else(|| {
            Error::new(
                ErrorCode::TemporalRange,
                "duration clock component overflow",
            )
        })
}

fn checked_add_timestamp_duration(
    seconds: i64,
    nanos: u32,
    duration: DurationParts,
    direction: i128,
) -> Result<(i64, u32)> {
    let elapsed = duration_elapsed_nanos(duration, direction)?;
    let timestamp = i128::from(seconds)
        .checked_mul(DURATION_NANOS_PER_SECOND)
        .and_then(|value| value.checked_add(i128::from(nanos)))
        .and_then(|value| value.checked_add(elapsed))
        .ok_or_else(|| Error::new(ErrorCode::TemporalRange, "datetime duration overflow"))?;
    let seconds = i64::try_from(timestamp.div_euclid(DURATION_NANOS_PER_SECOND))
        .map_err(|_| Error::new(ErrorCode::TemporalRange, "datetime duration overflow"))?;
    let nanos = u32::try_from(timestamp.rem_euclid(DURATION_NANOS_PER_SECOND))
        .map_err(|_| Error::new(ErrorCode::TemporalRange, "datetime duration overflow"))?;
    chrono::DateTime::<chrono::Utc>::from_timestamp(seconds, nanos).ok_or_else(|| {
        Error::new(
            ErrorCode::TemporalRange,
            "datetime is outside the supported range",
        )
    })?;
    Ok((seconds, nanos))
}

#[derive(Clone, Copy)]
enum NumericOperation {
    Subtract,
    Multiply,
}

fn evaluate_division(left: ResultValue, right: ResultValue) -> Result<ResultValue> {
    match (left, right) {
        (
            ResultValue::Scalar(ScalarValue::Integer(dividend)),
            ResultValue::Scalar(ScalarValue::Integer(divisor)),
        ) => {
            if divisor == 0 {
                return Err(Error::new(ErrorCode::QueryType, "division by zero"));
            }
            dividend
                .checked_div(divisor)
                .map(ScalarValue::Integer)
                .map(ResultValue::Scalar)
                .ok_or_else(|| Error::new(ErrorCode::QueryType, "integer arithmetic overflow"))
        }
        (left, right) => Ok(number(numeric(&left)? / numeric(&right)?)),
    }
}

fn evaluate_modulo(left: ResultValue, right: ResultValue) -> Result<ResultValue> {
    match (left, right) {
        (
            ResultValue::Scalar(ScalarValue::Integer(dividend)),
            ResultValue::Scalar(ScalarValue::Integer(divisor)),
        ) => {
            if divisor == 0 {
                return Err(Error::new(ErrorCode::QueryType, "modulo by zero"));
            }
            Ok(ResultValue::Scalar(ScalarValue::Integer(
                dividend.wrapping_rem(divisor),
            )))
        }
        (left, right) => Ok(number(numeric(&left)? % numeric(&right)?)),
    }
}

fn numeric_binary(
    left: ResultValue,
    right: ResultValue,
    operation: NumericOperation,
) -> Result<ResultValue> {
    match (left, right) {
        (
            ResultValue::Scalar(ScalarValue::Integer(left)),
            ResultValue::Scalar(ScalarValue::Integer(right)),
        ) => {
            let result = match operation {
                NumericOperation::Subtract => left.checked_sub(right),
                NumericOperation::Multiply => left.checked_mul(right),
            };
            result
                .map(ScalarValue::Integer)
                .map(ResultValue::Scalar)
                .ok_or_else(|| Error::new(ErrorCode::QueryType, "integer arithmetic overflow"))
        }
        (left, right) => {
            let left = numeric(&left)?;
            let right = numeric(&right)?;
            Ok(number(match operation {
                NumericOperation::Subtract => left - right,
                NumericOperation::Multiply => left * right,
            }))
        }
    }
}

const fn is_null_value(value: &ResultValue) -> bool {
    matches!(value, ResultValue::Scalar(ScalarValue::Null))
}

/// Converts protocol/result data into an execution binding without granting entity authority.
/// Container shape is retained so later list/map operations can preserve any statement-owned
/// bindings alongside these leaves, but public node, relationship, and path values stay ordinary
/// values even when their IDs happen to exist in the current graph.
fn untrusted_result_binding(value: ResultValue) -> BindingValue {
    match value {
        ResultValue::List(values) => {
            BindingValue::List(values.into_iter().map(untrusted_result_binding).collect())
        }
        ResultValue::Map(values) => BindingValue::Map(
            values
                .into_iter()
                .map(|(name, value)| (name, untrusted_result_binding(value)))
                .collect(),
        ),
        value => BindingValue::Value(value),
    }
}

fn normalize_untrusted_container(value: BindingValue) -> BindingValue {
    match value {
        BindingValue::Value(ResultValue::List(values)) => {
            untrusted_result_binding(ResultValue::List(values))
        }
        BindingValue::Value(ResultValue::Map(values)) => {
            untrusted_result_binding(ResultValue::Map(values))
        }
        value => value,
    }
}

fn binding_to_result(value: &BindingValue, graph: &GraphReadView<'_>) -> Result<ResultValue> {
    match value {
        BindingValue::Node(dense) => materialize_node(graph, *dense).map(ResultValue::Node),
        BindingValue::Relationship(dense) => {
            materialize_edge(graph, *dense).map(ResultValue::Relationship)
        }
        BindingValue::Path {
            nodes,
            relationships,
        } => Ok(ResultValue::Path {
            nodes: nodes
                .iter()
                .map(|dense| materialize_node(graph, *dense))
                .collect::<Result<_>>()?,
            relationships: relationships
                .iter()
                .map(|dense| materialize_edge(graph, *dense))
                .collect::<Result<_>>()?,
        }),
        BindingValue::List(values) => Ok(ResultValue::List(
            values
                .iter()
                .map(|value| binding_to_result(value, graph))
                .collect::<Result<_>>()?,
        )),
        BindingValue::Map(values) => Ok(ResultValue::Map(
            values
                .iter()
                .map(|(name, value)| Ok((name.clone(), binding_to_result(value, graph)?)))
                .collect::<Result<_>>()?,
        )),
        BindingValue::Value(value) => Ok(value.clone()),
        BindingValue::Null => Ok(ResultValue::Scalar(ScalarValue::Null)),
    }
}

fn materialize_node(graph: &GraphReadView<'_>, dense: u32) -> Result<ResultNode> {
    let node = graph.node_dense(dense).ok_or_else(|| {
        if graph.node_dense_was_deleted(dense) {
            deleted_entity_access("node")
        } else {
            Error::new(ErrorCode::QueryType, "node binding does not exist")
        }
    })?;
    let labels = node
        .labels()
        .iter()
        .filter_map(|label| graph.label_name(*label).map(ToOwned::to_owned))
        .collect();
    let properties = node
        .properties()
        .into_iter()
        .filter_map(|(property, value)| {
            graph
                .property_name(property)
                .map(|name| (name.to_owned(), value))
        })
        .collect();
    Ok(ResultNode {
        id: node.id(),
        layer: node.layer(),
        revision: node.revision(),
        labels,
        properties,
    })
}

fn materialize_edge(graph: &GraphReadView<'_>, dense: u32) -> Result<ResultEdge> {
    let edge = graph.edge_dense(dense).ok_or_else(|| {
        if graph.deleted_edge_relationship_type(dense).is_some() {
            deleted_entity_access("relationship")
        } else {
            Error::new(ErrorCode::QueryType, "relationship binding does not exist")
        }
    })?;
    let relationship_type = graph
        .relationship_type_name(edge.relationship_type())
        .unwrap_or("")
        .to_owned();
    let properties = edge
        .properties()
        .into_iter()
        .filter_map(|(property, value)| {
            graph
                .property_name(property)
                .map(|name| (name.to_owned(), value))
        })
        .collect();
    Ok(ResultEdge {
        id: edge.id(),
        source: edge.source(),
        target: edge.target(),
        relationship_type,
        layer: edge.layer(),
        revision: edge.revision(),
        properties,
    })
}

fn rows_to_result(
    rows: &[Row],
    columns: &[String],
    graph: &GraphReadView<'_>,
    bookmark: Bookmark,
    statistics: StatementStats,
    max_batch_rows: usize,
    mut stream: Option<&mut dyn FnMut(ExecutionStreamItem) -> Result<()>>,
) -> Result<QueryResult> {
    let columns = if columns.is_empty() {
        rows.first()
            .map(|row| row.keys().cloned().collect())
            .unwrap_or_default()
    } else {
        columns.to_vec()
    };
    // A top-level Cypher statement with no result columns (for example `CREATE (n)`) has a
    // unit row internally so that later clauses can consume its bindings, but it exposes no
    // records to the client.  Do not leak that execution-only row through the query protocol.
    if columns.is_empty() {
        if let Some(emit) = stream.as_deref_mut() {
            emit(ExecutionStreamItem::Schema(Vec::new()))?;
        }
        return Ok(QueryResult {
            schema: Vec::new(),
            batches: Vec::new(),
            bookmark,
            statistics,
            truncated: false,
        });
    }
    let mut types = vec![ColumnType::Null; columns.len()];
    for row in rows {
        for (index, name) in columns.iter().enumerate() {
            let value_type = row.get(name).map_or(ColumnType::Null, binding_column_type);
            if types[index] == ColumnType::Null {
                types[index] = value_type;
            } else if types[index] != value_type && value_type != ColumnType::Null {
                types[index] = ColumnType::Any;
            }
        }
    }
    let batch_size = max_batch_rows.max(1);
    let schema = columns
        .iter()
        .cloned()
        .zip(types.iter().cloned())
        .collect::<Vec<_>>();
    if let Some(emit) = stream.as_deref_mut() {
        emit(ExecutionStreamItem::Schema(schema.clone()))?;
    }
    let mut batches = Vec::new();
    for start in (0..rows.len()).step_by(batch_size) {
        let end = start.saturating_add(batch_size).min(rows.len());
        let batch_columns = columns
            .iter()
            .enumerate()
            .map(|(index, name)| {
                Ok(ResultColumn {
                    name: name.clone(),
                    value_type: types[index].clone(),
                    values: rows[start..end]
                        .iter()
                        .map(|row| {
                            binding_to_result(row.get(name).unwrap_or(&BindingValue::Null), graph)
                        })
                        .collect::<Result<Vec<_>>>()?,
                })
            })
            .collect::<Result<Vec<_>>>()?;
        let batch = ResultBatch {
            row_count: end - start,
            columns: batch_columns,
        };
        if let Some(emit) = stream.as_deref_mut() {
            emit(ExecutionStreamItem::Batch(batch))?;
        } else {
            batches.push(batch);
        }
    }
    Ok(QueryResult {
        schema,
        batches,
        bookmark,
        statistics,
        truncated: false,
    })
}

fn binding_column_type(value: &BindingValue) -> ColumnType {
    match value {
        BindingValue::Node(_) => ColumnType::Node,
        BindingValue::Relationship(_) => ColumnType::Relationship,
        BindingValue::Path { .. } => ColumnType::Path,
        BindingValue::List(_) => ColumnType::List,
        BindingValue::Map(_) => ColumnType::Map,
        BindingValue::Value(value) => value.column_type(),
        BindingValue::Null => ColumnType::Null,
    }
}

const CREATED_AT_PROPERTY: &str = "created_at";

fn resolved_created_at(resolved_time_nanos: i64) -> Option<ScalarValue> {
    if resolved_time_nanos == 0 {
        return None;
    }
    Some(ScalarValue::ZonedDateTime {
        seconds: resolved_time_nanos.div_euclid(1_000_000_000),
        nanos: u32::try_from(resolved_time_nanos.rem_euclid(1_000_000_000)).ok()?,
        timezone: Arc::from("UTC"),
    })
}

fn add_automatic_created_at(
    properties: &mut Vec<(PropertyId, ScalarValue)>,
    property: PropertyId,
    created_at: ScalarValue,
) {
    if !properties
        .iter()
        .any(|(candidate, _)| *candidate == property)
    {
        properties.push((property, created_at));
    }
}

fn apply_mutation(state: &mut ExecutionState<'_>, mut mutation: GraphMutation) -> Result<()> {
    if let Some(created_at) = state.created_at.clone() {
        match &mut mutation {
            GraphMutation::InsertNode(input) => {
                let property = intern_property(CREATED_AT_PROPERTY, state)?;
                add_automatic_created_at(&mut input.properties, property, created_at);
            }
            GraphMutation::InsertEdge(input) => {
                let property = intern_property(CREATED_AT_PROPERTY, state)?;
                add_automatic_created_at(&mut input.properties, property, created_at);
            }
            _ => {}
        }
    }
    let write_target = match &mutation {
        GraphMutation::SetNodeProperty { node, .. }
        | GraphMutation::AddNodeLabels { node, .. }
        | GraphMutation::RemoveNodeLabels { node, .. }
        | GraphMutation::DeleteNode { node, .. } => Some(EntityDependency::Node(*node)),
        GraphMutation::SetEdgeProperty { edge, .. } | GraphMutation::DeleteEdge { edge, .. } => {
            Some(EntityDependency::Relationship(*edge))
        }
        GraphMutation::DeclareLabel { .. }
        | GraphMutation::DeclareProperty { .. }
        | GraphMutation::DeclareRelationshipType { .. }
        | GraphMutation::InsertNode(_)
        | GraphMutation::InsertEdge(_) => None,
    };
    state.graph.apply(&mutation)?;
    if let Some(write_target) = write_target {
        state.dependencies.write_targets.insert(write_target);
    }
    state.mutations.push(mutation);
    Ok(())
}

fn intern_label(name: &str, state: &mut ExecutionState<'_>) -> Result<LabelId> {
    if let Some(id) = state.graph.label(name) {
        return Ok(id);
    }
    let id = state.graph.intern_label(name)?;
    state.mutations.push(GraphMutation::DeclareLabel {
        name: name.to_owned(),
        id,
    });
    Ok(id)
}

fn intern_property(name: &str, state: &mut ExecutionState<'_>) -> Result<PropertyId> {
    if let Some(id) = state.graph.property(name) {
        return Ok(id);
    }
    let id = state.graph.intern_property(name)?;
    state.mutations.push(GraphMutation::DeclareProperty {
        name: name.to_owned(),
        id,
    });
    Ok(id)
}

fn intern_relationship_type(
    name: &str,
    state: &mut ExecutionState<'_>,
) -> Result<RelationshipTypeId> {
    if let Some(id) = state.graph.relationship_type(name) {
        return Ok(id);
    }
    let id = state.graph.intern_relationship_type(name)?;
    state
        .mutations
        .push(GraphMutation::DeclareRelationshipType {
            name: name.to_owned(),
            id,
        });
    Ok(id)
}

fn allocate_node_id(state: &mut ExecutionState<'_>) -> Result<NodeId> {
    loop {
        let id = NodeId(state.next_node_id);
        state.next_node_id = state.next_node_id.checked_add(1).ok_or_else(|| {
            Error::new(ErrorCode::ResultBudgetExceeded, "node ID space exhausted")
        })?;
        if !state.graph.contains_node_id(id) {
            return Ok(id);
        }
    }
}

fn allocate_edge_id(state: &mut ExecutionState<'_>) -> Result<EdgeId> {
    loop {
        let id = EdgeId(state.next_edge_id);
        state.next_edge_id = state.next_edge_id.checked_add(1).ok_or_else(|| {
            Error::new(
                ErrorCode::ResultBudgetExceeded,
                "relationship ID space exhausted",
            )
        })?;
        if !state.graph.contains_edge_id(id) {
            return Ok(id);
        }
    }
}

fn evaluate_properties(
    entries: &[(String, Expression)],
    row: &Row,
    state: &mut ExecutionState<'_>,
    context: &ExecutionContext<'_>,
) -> Result<Vec<(PropertyId, ScalarValue)>> {
    let mut result = Vec::new();
    for (name, expression) in entries {
        let value = scalar(evaluate_state(expression, row, state, context)?)?;
        result.push((intern_property(name, state)?, value));
    }
    Ok(result)
}

fn validate_node_properties(
    graph: &GraphStore,
    properties: &[(PropertyId, ScalarValue)],
) -> Result<()> {
    for (property, value) in properties {
        graph.validate_node_property_value(*property, value)?;
    }
    Ok(())
}

fn validate_edge_properties(
    graph: &GraphStore,
    properties: &[(PropertyId, ScalarValue)],
) -> Result<()> {
    for (property, value) in properties {
        graph.validate_edge_property_value(*property, value)?;
    }
    Ok(())
}

fn scalar(value: ResultValue) -> Result<ScalarValue> {
    value.into_property()
}

fn numeric(value: &ResultValue) -> Result<f64> {
    match value {
        ResultValue::Scalar(ScalarValue::Integer(value)) => Ok(*value as f64),
        ResultValue::Scalar(ScalarValue::Float(value)) => Ok(value.into_inner()),
        _ => Err(Error::new(ErrorCode::QueryType, "numeric value required")),
    }
}

fn integer(value: &ResultValue) -> Result<i64> {
    match value {
        ResultValue::Scalar(ScalarValue::Integer(value)) => Ok(*value),
        _ => Err(Error::new(ErrorCode::QueryType, "INTEGER value required")),
    }
}

fn normalize_list_slice_bound(bound: i64, length: usize) -> usize {
    if bound < 0 {
        match usize::try_from(bound.unsigned_abs()) {
            Ok(offset) => length.saturating_sub(offset),
            Err(_) => 0,
        }
    } else {
        match usize::try_from(bound) {
            Ok(bound) => bound.min(length),
            Err(_) => length,
        }
    }
}

fn evaluate_dynamic_index(value: ResultValue, index: ResultValue) -> Result<ResultValue> {
    if matches!(&value, ResultValue::Scalar(ScalarValue::Null))
        || matches!(&index, ResultValue::Scalar(ScalarValue::Null))
    {
        return Ok(ResultValue::Scalar(ScalarValue::Null));
    }
    match value {
        ResultValue::List(values) => {
            let ResultValue::Scalar(ScalarValue::Integer(index)) = index else {
                return Err(Error::new(
                    ErrorCode::QueryType,
                    "InvalidArgumentType: list index requires an INTEGER",
                ));
            };
            if index < 0 {
                return Ok(ResultValue::Scalar(ScalarValue::Null));
            }
            let Some(index) = usize::try_from(index).ok() else {
                return Ok(ResultValue::Scalar(ScalarValue::Null));
            };
            Ok(match values.get(index) {
                Some(value) => value.clone(),
                None => ResultValue::Scalar(ScalarValue::Null),
            })
        }
        ResultValue::Map(values) => {
            let ResultValue::Scalar(ScalarValue::String(index)) = index else {
                return Err(Error::new(
                    ErrorCode::QueryType,
                    "MapElementAccessByNonString: map index requires a STRING",
                ));
            };
            Ok(match values.get(index.as_ref()) {
                Some(value) => value.clone(),
                None => ResultValue::Scalar(ScalarValue::Null),
            })
        }
        ResultValue::Node(node) => dynamic_entity_property(&node.properties, index),
        ResultValue::Relationship(relationship) => {
            dynamic_entity_property(&relationship.properties, index)
        }
        _ => Err(Error::new(
            ErrorCode::QueryType,
            "InvalidArgumentType: indexing requires a LIST, MAP, NODE, or RELATIONSHIP",
        )),
    }
}

fn dynamic_entity_property(
    properties: &BTreeMap<String, ScalarValue>,
    index: ResultValue,
) -> Result<ResultValue> {
    let ResultValue::Scalar(ScalarValue::String(index)) = index else {
        return Err(Error::new(
            ErrorCode::QueryType,
            "MapElementAccessByNonString: entity property index requires a STRING",
        ));
    };
    properties
        .get(index.as_ref())
        .cloned()
        .map(ResultValue::from_property)
        .transpose()
        .map(|value| value.unwrap_or(ResultValue::Scalar(ScalarValue::Null)))
}

fn range_integer(value: &ResultValue) -> Result<i64> {
    match value {
        ResultValue::Scalar(ScalarValue::Integer(value)) => Ok(*value),
        _ => Err(resident_range_type_error()),
    }
}

fn numeric_arg(values: &[ResultValue], index: usize) -> Result<f64> {
    numeric(
        values.get(index).ok_or_else(|| {
            Error::new(ErrorCode::QueryType, "numeric function argument is missing")
        })?,
    )
}

fn string_arg(values: &[ResultValue], index: usize) -> Result<String> {
    match values.get(index) {
        Some(ResultValue::Scalar(ScalarValue::String(value))) => Ok(value.to_string()),
        _ => Err(Error::new(ErrorCode::QueryType, "STRING argument required")),
    }
}

fn require_arity(name: &str, values: &[ResultValue], expected: usize) -> Result<()> {
    if values.len() == expected {
        Ok(())
    } else {
        Err(function_arity(name, &expected.to_string(), values.len()))
    }
}

fn function_arity(name: &str, expected: &str, actual: usize) -> Error {
    Error::new(
        ErrorCode::QueryType,
        format!("{name} requires {expected} arguments but received {actual}"),
    )
}

fn non_negative_usize_arg(values: &[ResultValue], index: usize, function: &str) -> Result<usize> {
    let value = values.get(index).ok_or_else(|| {
        Error::new(
            ErrorCode::QueryType,
            format!("{function} argument is missing"),
        )
    })?;
    usize::try_from(integer(value)?).map_err(|_| {
        Error::new(
            ErrorCode::QueryType,
            format!("{function} length must be non-negative"),
        )
    })
}

fn string_value(value: String) -> ResultValue {
    ResultValue::Scalar(ScalarValue::String(Arc::from(value)))
}

fn property_map(values: &BTreeMap<String, ScalarValue>) -> Result<ResultValue> {
    values
        .iter()
        .map(|(name, value)| Ok((name.clone(), ResultValue::from_property(value.clone())?)))
        .collect::<Result<BTreeMap<_, _>>>()
        .map(ResultValue::Map)
}

fn to_string_value(value: &ResultValue) -> Result<ResultValue> {
    let string = match value {
        ResultValue::Scalar(ScalarValue::Null) => {
            return Ok(ResultValue::Scalar(ScalarValue::Null));
        }
        ResultValue::Scalar(ScalarValue::Boolean(value)) => value.to_string(),
        ResultValue::Scalar(ScalarValue::Integer(value)) => value.to_string(),
        ResultValue::Scalar(ScalarValue::Float(value)) => value.to_string(),
        ResultValue::Scalar(ScalarValue::String(value)) => value.to_string(),
        ResultValue::Scalar(ScalarValue::Date(days)) => format_date(*days)?,
        ResultValue::Scalar(ScalarValue::LocalTime(nanos)) => format_local_time(*nanos)?,
        ResultValue::Scalar(ScalarValue::ZonedTime {
            nanos,
            offset_seconds,
        }) => format_zoned_time(*nanos, *offset_seconds)?,
        ResultValue::Scalar(ScalarValue::LocalDateTime { seconds, nanos }) => {
            format_local_datetime(*seconds, *nanos)?
        }
        ResultValue::Scalar(ScalarValue::ZonedDateTime {
            seconds,
            nanos,
            timezone,
        }) => format_zoned_datetime(*seconds, *nanos, timezone)?,
        ResultValue::Scalar(ScalarValue::Duration {
            months,
            days,
            seconds,
            nanos,
        }) => format_duration(*months, *days, *seconds, *nanos),
        _ => {
            return Err(Error::new(
                ErrorCode::QueryType,
                "InvalidArgumentValue: toString received an unsupported value type",
            ));
        }
    };
    Ok(string_value(string))
}

/// Canonical Cypher rendering for a typed temporal scalar. Native CPU execution calls this only
/// after it has produced the temporal value itself; sharing the formatter prevents the generic
/// evaluator and the selected CPU backend from drifting on fractions, offsets, expanded years,
/// named zones, or mixed-sign duration normalization.
pub fn format_temporal_scalar(value: &ScalarValue) -> Result<Option<String>> {
    Ok(match value {
        ScalarValue::Null => None,
        ScalarValue::Date(days) => Some(format_date(*days)?),
        ScalarValue::LocalTime(nanos) => Some(format_local_time(*nanos)?),
        ScalarValue::ZonedTime {
            nanos,
            offset_seconds,
        } => Some(format_zoned_time(*nanos, *offset_seconds)?),
        ScalarValue::LocalDateTime { seconds, nanos } => {
            Some(format_local_datetime(*seconds, *nanos)?)
        }
        ScalarValue::ZonedDateTime {
            seconds,
            nanos,
            timezone,
        } => Some(format_zoned_datetime(*seconds, *nanos, timezone)?),
        ScalarValue::Duration {
            months,
            days,
            seconds,
            nanos,
        } => Some(format_duration(*months, *days, *seconds, *nanos)),
        _ => {
            return Err(Error::new(
                ErrorCode::QueryType,
                "InvalidArgumentValue: temporal serialization requires a temporal value",
            ));
        }
    })
}

fn format_date(days: i64) -> Result<String> {
    let date = CivilDate::from_epoch_day(days)?;
    let year = if (0..=9_999).contains(&date.year) {
        format!("{:04}", date.year)
    } else if date.year < 0 {
        format!("-{:04}", date.year.unsigned_abs())
    } else {
        format!("+{}", date.year)
    };
    Ok(format!("{year}-{:02}-{:02}", date.month, date.day))
}

fn format_local_time(nanos: i64) -> Result<String> {
    const DAY_NANOS: i64 = 86_400 * 1_000_000_000;
    if !(0..DAY_NANOS).contains(&nanos) {
        return Err(Error::new(
            ErrorCode::TemporalRange,
            "local time is outside one day",
        ));
    }
    let seconds = u32::try_from(nanos / 1_000_000_000)
        .map_err(|_| Error::new(ErrorCode::TemporalRange, "local time seconds are invalid"))?;
    let subsecond = u32::try_from(nanos % 1_000_000_000)
        .map_err(|_| Error::new(ErrorCode::TemporalRange, "local time nanos are invalid"))?;
    let time = chrono::NaiveTime::from_num_seconds_from_midnight_opt(seconds, subsecond)
        .ok_or_else(|| Error::new(ErrorCode::TemporalRange, "local time is invalid"))?;
    Ok(time.format("%H:%M:%S%.f").to_string())
}

fn format_zoned_time(nanos: i64, offset_seconds: i32) -> Result<String> {
    let time = format_local_time(nanos)?;
    let offset = chrono::FixedOffset::east_opt(offset_seconds)
        .ok_or_else(|| Error::new(ErrorCode::TemporalRange, "time offset is invalid"))?;
    Ok(format!("{time}{offset}"))
}

fn format_local_datetime(seconds: i64, nanos: u32) -> Result<String> {
    chrono::DateTime::<chrono::Utc>::from_timestamp(seconds, nanos)
        .map(|value| value.naive_utc().format("%Y-%m-%dT%H:%M:%S%.f").to_string())
        .ok_or_else(|| {
            Error::new(
                ErrorCode::TemporalRange,
                "local datetime is outside the format range",
            )
        })
}

fn format_zoned_datetime(seconds: i64, nanos: u32, timezone: &str) -> Result<String> {
    let value =
        chrono::DateTime::<chrono::Utc>::from_timestamp(seconds, nanos).ok_or_else(|| {
            Error::new(
                ErrorCode::TemporalRange,
                "datetime is outside the format range",
            )
        })?;
    if timezone == "UTC" {
        return Ok(value.to_rfc3339());
    }
    if let Ok(zone) = timezone.parse::<chrono_tz::Tz>() {
        return Ok(format!(
            "{}[{timezone}]",
            value.with_timezone(&zone).to_rfc3339()
        ));
    }
    if let Ok(offset) = timezone.parse::<chrono::FixedOffset>() {
        return Ok(offset.from_utc_datetime(&value.naive_utc()).to_rfc3339());
    }
    Err(Error::new(
        ErrorCode::TemporalRange,
        "datetime timezone is unknown",
    ))
}

fn format_duration(months: i64, days: i64, seconds: i64, nanos: i32) -> String {
    let mut rendered = String::from("P");
    let years = months / 12;
    let remaining_months = months % 12;
    if years != 0 {
        rendered.push_str(&format!("{years}Y"));
    }
    if remaining_months != 0 {
        rendered.push_str(&format!("{remaining_months}M"));
    }
    if days != 0 {
        rendered.push_str(&format!("{days}D"));
    }

    let total_nanos = i128::from(seconds) * DURATION_NANOS_PER_SECOND + i128::from(nanos);
    if total_nanos != 0 {
        rendered.push('T');
        let whole_seconds = total_nanos / DURATION_NANOS_PER_SECOND;
        let fractional_nanos = total_nanos % DURATION_NANOS_PER_SECOND;
        let hours = whole_seconds / 3_600;
        let after_hours = whole_seconds % 3_600;
        let minutes = after_hours / 60;
        let second_nanos = (after_hours % 60) * DURATION_NANOS_PER_SECOND + fractional_nanos;
        if hours != 0 {
            rendered.push_str(&format!("{hours}H"));
        }
        if minutes != 0 {
            rendered.push_str(&format!("{minutes}M"));
        }
        if second_nanos != 0 {
            rendered.push_str(&format_duration_seconds_component(second_nanos));
        }
    } else if years == 0 && remaining_months == 0 && days == 0 {
        rendered.push_str("T0S");
    }
    rendered
}

fn format_duration_seconds_component(total_nanos: i128) -> String {
    let sign = if total_nanos < 0 { "-" } else { "" };
    let absolute = total_nanos.abs();
    let seconds = absolute / DURATION_NANOS_PER_SECOND;
    let nanos = absolute % DURATION_NANOS_PER_SECOND;
    if nanos == 0 {
        return format!("{sign}{seconds}S");
    }
    let fraction = format!("{nanos:09}");
    format!("{sign}{seconds}.{}S", fraction.trim_end_matches('0'))
}

fn to_boolean_value(value: &ResultValue) -> Result<ResultValue> {
    match value {
        ResultValue::Scalar(ScalarValue::Boolean(value)) => Ok(boolean(*value)),
        ResultValue::Scalar(ScalarValue::String(value)) if value.eq_ignore_ascii_case("true") => {
            Ok(boolean(true))
        }
        ResultValue::Scalar(ScalarValue::String(value)) if value.eq_ignore_ascii_case("false") => {
            Ok(boolean(false))
        }
        ResultValue::Scalar(ScalarValue::String(_)) => Ok(ResultValue::Scalar(ScalarValue::Null)),
        _ => Err(Error::new(
            ErrorCode::QueryType,
            "InvalidArgumentValue: toBoolean requires a BOOLEAN or STRING",
        )),
    }
}

fn to_integer_value(value: &ResultValue) -> Result<ResultValue> {
    let converted = match value {
        ResultValue::Scalar(ScalarValue::Integer(value)) => Some(*value),
        ResultValue::Scalar(ScalarValue::Boolean(value)) => Some(i64::from(*value)),
        ResultValue::Scalar(ScalarValue::Float(value)) => {
            let value = value.into_inner();
            const LOWER: f64 = i64::MIN as f64;
            const UPPER_EXCLUSIVE: f64 = 9_223_372_036_854_775_808.0;
            (value.is_finite() && value >= LOWER && value < UPPER_EXCLUSIVE)
                .then(|| value.trunc() as i64)
        }
        ResultValue::Scalar(ScalarValue::String(value)) => {
            value.trim().parse::<i64>().ok().or_else(|| {
                let value = value.trim().parse::<f64>().ok()?;
                const LOWER: f64 = i64::MIN as f64;
                const UPPER_EXCLUSIVE: f64 = 9_223_372_036_854_775_808.0;
                (value.is_finite() && value >= LOWER && value < UPPER_EXCLUSIVE)
                    .then(|| value.trunc() as i64)
            })
        }
        _ => {
            return Err(Error::new(
                ErrorCode::QueryType,
                "InvalidArgumentValue: toInteger requires a BOOLEAN, INTEGER, FLOAT, or STRING",
            ));
        }
    };
    Ok(
        converted.map_or(ResultValue::Scalar(ScalarValue::Null), |value| {
            ResultValue::Scalar(ScalarValue::Integer(value))
        }),
    )
}

fn to_float_value(value: &ResultValue) -> Result<ResultValue> {
    let converted = match value {
        ResultValue::Scalar(ScalarValue::Integer(value)) => Some(*value as f64),
        ResultValue::Scalar(ScalarValue::Float(value)) => Some(value.into_inner()),
        ResultValue::Scalar(ScalarValue::String(value)) => value
            .trim()
            .parse::<f64>()
            .ok()
            .filter(|value| value.is_finite()),
        _ => {
            return Err(Error::new(
                ErrorCode::QueryType,
                "InvalidArgumentValue: toFloat requires an INTEGER, FLOAT, or STRING",
            ));
        }
    };
    Ok(converted.map_or(ResultValue::Scalar(ScalarValue::Null), number))
}

fn vector_values(value: &ResultValue) -> Result<Vec<f64>> {
    let values = match value {
        ResultValue::Vector(values) => values.iter().map(|value| f64::from(*value)).collect(),
        ResultValue::List(values) => values.iter().map(numeric).collect::<Result<Vec<_>>>()?,
        _ => {
            return Err(Error::new(
                ErrorCode::QueryType,
                "vector function requires a VECTOR or numeric LIST",
            ));
        }
    };
    if values.is_empty() || values.iter().any(|value| !value.is_finite()) {
        return Err(Error::new(
            ErrorCode::QueryType,
            "vector function requires finite non-empty vectors",
        ));
    }
    Ok(values)
}

fn vector_binary(name: &str, left: &ResultValue, right: &ResultValue) -> Result<ResultValue> {
    let left = vector_values(left)?;
    let right = vector_values(right)?;
    if left.len() != right.len() {
        return Err(Error::new(ErrorCode::QueryType, "vector dimensions differ"));
    }
    let dot = left
        .iter()
        .zip(&right)
        .map(|(left, right)| left * right)
        .sum::<f64>();
    let value = match name {
        "vector.dot" => dot,
        "vector.distance" => left
            .iter()
            .zip(&right)
            .map(|(left, right)| {
                let difference = left - right;
                difference * difference
            })
            .sum::<f64>()
            .sqrt(),
        "vector.cosine" => {
            let left_norm = left.iter().map(|value| value * value).sum::<f64>().sqrt();
            let right_norm = right.iter().map(|value| value * value).sum::<f64>().sqrt();
            if left_norm <= f64::EPSILON || right_norm <= f64::EPSILON {
                return Err(Error::new(
                    ErrorCode::QueryType,
                    "cosine similarity is undefined for a zero vector",
                ));
            }
            dot / (left_norm * right_norm)
        }
        _ => return Err(Error::internal("vector function dispatch is inconsistent")),
    };
    Ok(number(value))
}

fn vector_normalize(value: &ResultValue) -> Result<ResultValue> {
    let values = vector_values(value)?;
    let norm = values.iter().map(|value| value * value).sum::<f64>().sqrt();
    if norm <= f64::EPSILON {
        return Err(Error::new(
            ErrorCode::QueryType,
            "cannot normalize a zero vector",
        ));
    }
    Ok(ResultValue::Vector(
        values
            .into_iter()
            .map(|value| (value / norm) as f32)
            .collect(),
    ))
}

fn cypher_range(values: &[ResultValue], maximum_rows: usize) -> Result<ResultValue> {
    cypher_range_with_demand(values, maximum_rows, None)
}

fn cypher_range_with_demand(
    values: &[ResultValue],
    maximum_rows: usize,
    demand: Option<usize>,
) -> Result<ResultValue> {
    if !(2..=3).contains(&values.len()) {
        return Err(function_arity("range", "two or three", values.len()));
    }
    let start = range_integer(&values[0])?;
    let end = range_integer(&values[1])?;
    let step = values.get(2).map_or(Ok(1), range_integer)?;
    if step == 0 {
        return Err(resident_range_step_error());
    }
    if (step > 0 && start > end) || (step < 0 && start < end) {
        return Ok(ResultValue::List(Vec::new()));
    }
    let mut output = Vec::new();
    let mut value = start;
    loop {
        if demand.is_some_and(|demand| output.len() >= demand) {
            break;
        }
        if output.len() >= maximum_rows {
            return Err(resident_range_budget_error());
        }
        output.push(ResultValue::Scalar(ScalarValue::Integer(value)));
        if value == end {
            break;
        }
        let Some(next) = value.checked_add(step) else {
            break;
        };
        if (step > 0 && next > end) || (step < 0 && next < end) {
            break;
        }
        value = next;
    }
    Ok(ResultValue::List(output))
}

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
enum TemporalTruncateUnit {
    Millennium,
    Century,
    Decade,
    Year,
    WeekYear,
    Quarter,
    Month,
    Week,
    Day,
    Hour,
    Minute,
    Second,
    Millisecond,
    Microsecond,
}

impl TemporalTruncateUnit {
    fn parse(value: &str) -> Result<Self> {
        match value.to_ascii_lowercase().as_str() {
            "millennium" => Ok(Self::Millennium),
            "century" => Ok(Self::Century),
            "decade" => Ok(Self::Decade),
            "year" => Ok(Self::Year),
            "weekyear" => Ok(Self::WeekYear),
            "quarter" => Ok(Self::Quarter),
            "month" => Ok(Self::Month),
            "week" => Ok(Self::Week),
            "day" => Ok(Self::Day),
            "hour" => Ok(Self::Hour),
            "minute" => Ok(Self::Minute),
            "second" => Ok(Self::Second),
            "millisecond" => Ok(Self::Millisecond),
            "microsecond" => Ok(Self::Microsecond),
            _ => Err(Error::new(
                ErrorCode::QueryType,
                format!("InvalidArgumentValue: unsupported temporal truncation unit `{value}`"),
            )),
        }
    }

    const fn rank(self) -> u8 {
        match self {
            Self::Millennium => 0,
            Self::Century => 1,
            Self::Decade => 2,
            Self::Year | Self::WeekYear => 3,
            Self::Quarter => 4,
            Self::Month | Self::Week => 5,
            Self::Day => 6,
            Self::Hour => 7,
            Self::Minute => 8,
            Self::Second => 9,
            Self::Millisecond => 10,
            Self::Microsecond => 11,
        }
    }

    const fn is_date_unit(self) -> bool {
        self.rank() <= Self::Day.rank()
    }
}

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
enum TemporalTruncateTarget {
    Date,
    LocalTime,
    Time,
    LocalDateTime,
    DateTime,
}

impl TemporalTruncateTarget {
    fn parse(function: &str) -> Result<Self> {
        match function {
            "date.truncate" => Ok(Self::Date),
            "localtime.truncate" => Ok(Self::LocalTime),
            "time.truncate" => Ok(Self::Time),
            "localdatetime.truncate" => Ok(Self::LocalDateTime),
            "datetime.truncate" => Ok(Self::DateTime),
            _ => Err(Error::internal(
                "temporal truncation function dispatch is inconsistent",
            )),
        }
    }

    const fn supports_unit(self, unit: TemporalTruncateUnit) -> bool {
        match self {
            Self::Date => unit.is_date_unit(),
            Self::LocalDateTime | Self::DateTime => true,
            Self::LocalTime | Self::Time => matches!(
                unit,
                TemporalTruncateUnit::Day
                    | TemporalTruncateUnit::Hour
                    | TemporalTruncateUnit::Minute
                    | TemporalTruncateUnit::Second
                    | TemporalTruncateUnit::Millisecond
                    | TemporalTruncateUnit::Microsecond
            ),
        }
    }
}

fn temporal_truncate(function: &str, values: &[ResultValue]) -> Result<ResultValue> {
    if !(2..=3).contains(&values.len()) {
        return Err(function_arity(function, "two or three", values.len()));
    }
    let target = TemporalTruncateTarget::parse(function)?;
    let unit = TemporalTruncateUnit::parse(&string_arg(values, 0)?)?;
    if !target.supports_unit(unit) {
        return Err(Error::new(
            ErrorCode::QueryType,
            format!(
                "InvalidArgumentValue: `{}` is not a valid unit for {function}",
                string_arg(values, 0)?
            ),
        ));
    }
    let map = match values.get(2) {
        None => None,
        Some(ResultValue::Map(values)) => Some(values),
        Some(_) => {
            return Err(Error::new(
                ErrorCode::QueryType,
                format!("InvalidArgumentType: {function} third argument must be a MAP"),
            ));
        }
    };
    validate_temporal_truncate_map(target, unit, map)?;

    match target {
        TemporalTruncateTarget::Date => {
            let source = temporal_source_date(&values[1])?;
            let date = apply_truncated_date_fields(truncate_date(source, unit)?, map)?;
            date_scalar(date)
        }
        TemporalTruncateTarget::LocalDateTime => {
            let local = temporal_source_datetime(&values[1], unit.is_date_unit())?;
            let truncated = truncate_local_datetime(local, unit, map)?;
            local_datetime_scalar(truncated)
        }
        TemporalTruncateTarget::DateTime => {
            let local = temporal_source_datetime(&values[1], unit.is_date_unit())?;
            let truncated = truncate_local_datetime(local, unit, map)?;
            let timezone = temporal_map_string(map, "timezone")?
                .map(str::to_owned)
                .unwrap_or(temporal_source_timezone(&values[1])?);
            zoned_datetime_scalar(truncated, &timezone)
        }
        TemporalTruncateTarget::LocalTime => {
            let (source, _) = temporal_source_clock(&values[1])?;
            let truncated = truncate_clock(source, unit)?;
            let nanos = apply_truncated_clock_fields(truncated, unit, map)?;
            Ok(ResultValue::Scalar(ScalarValue::LocalTime(nanos)))
        }
        TemporalTruncateTarget::Time => {
            let (source, source_offset) = temporal_source_clock(&values[1])?;
            let truncated = truncate_clock(source, unit)?;
            let nanos = apply_truncated_clock_fields(truncated, unit, map)?;
            let offset_seconds = temporal_map_string(map, "timezone")?
                .map_or(Ok(source_offset.unwrap_or(0)), parse_fixed_timezone_seconds)?;
            Ok(ResultValue::Scalar(ScalarValue::ZonedTime {
                nanos,
                offset_seconds,
            }))
        }
    }
}

fn validate_temporal_truncate_map(
    target: TemporalTruncateTarget,
    unit: TemporalTruncateUnit,
    map: Option<&BTreeMap<String, ResultValue>>,
) -> Result<()> {
    let Some(map) = map else {
        return Ok(());
    };
    for key in map.keys() {
        if key == "timezone" {
            if !matches!(
                target,
                TemporalTruncateTarget::Time | TemporalTruncateTarget::DateTime
            ) {
                return Err(Error::new(
                    ErrorCode::QueryType,
                    "InvalidArgumentValue: timezone is valid only for zoned truncation",
                ));
            }
            continue;
        }
        let rank = temporal_field_rank(key).ok_or_else(|| {
            Error::new(
                ErrorCode::QueryType,
                format!("InvalidArgumentValue: `{key}` is not a temporal truncation field"),
            )
        })?;
        let target_accepts = match target {
            TemporalTruncateTarget::Date => rank <= TemporalTruncateUnit::Day.rank(),
            TemporalTruncateTarget::LocalDateTime | TemporalTruncateTarget::DateTime => true,
            TemporalTruncateTarget::LocalTime | TemporalTruncateTarget::Time => {
                rank > TemporalTruncateUnit::Day.rank()
            }
        };
        if !target_accepts || rank <= unit.rank() {
            return Err(Error::new(
                ErrorCode::QueryType,
                format!(
                    "InvalidArgumentValue: `{key}` is not smaller than the requested truncation unit"
                ),
            ));
        }
    }
    Ok(())
}

fn temporal_field_rank(field: &str) -> Option<u8> {
    match field {
        "year" | "weekYear" => Some(TemporalTruncateUnit::Year.rank()),
        "quarter" => Some(TemporalTruncateUnit::Quarter.rank()),
        "month" | "week" => Some(TemporalTruncateUnit::Month.rank()),
        "day" | "dayOfWeek" | "ordinalDay" | "dayOfQuarter" => {
            Some(TemporalTruncateUnit::Day.rank())
        }
        "hour" => Some(TemporalTruncateUnit::Hour.rank()),
        "minute" => Some(TemporalTruncateUnit::Minute.rank()),
        "second" => Some(TemporalTruncateUnit::Second.rank()),
        "millisecond" => Some(TemporalTruncateUnit::Millisecond.rank()),
        "microsecond" => Some(TemporalTruncateUnit::Microsecond.rank()),
        "nanosecond" => Some(TemporalTruncateUnit::Microsecond.rank() + 1),
        _ => None,
    }
}

fn temporal_source_date(value: &ResultValue) -> Result<chrono::NaiveDate> {
    match value {
        ResultValue::Scalar(ScalarValue::Date(days)) => date_from_days(*days),
        ResultValue::Scalar(ScalarValue::LocalDateTime { seconds, nanos }) => {
            local_datetime_from_stored(*seconds, *nanos).map(|value| value.date())
        }
        ResultValue::Scalar(ScalarValue::ZonedDateTime {
            seconds,
            nanos,
            timezone,
        }) => zoned_datetime_local(*seconds, *nanos, timezone).map(|value| value.date()),
        _ => Err(Error::new(
            ErrorCode::QueryType,
            "InvalidArgumentType: truncating to a date requires DATE, LOCAL DATETIME, or DATETIME",
        )),
    }
}

fn temporal_source_datetime(
    value: &ResultValue,
    date_allowed: bool,
) -> Result<chrono::NaiveDateTime> {
    match value {
        ResultValue::Scalar(ScalarValue::Date(days)) if date_allowed => date_from_days(*days)?
            .and_hms_opt(0, 0, 0)
            .ok_or_else(|| Error::new(ErrorCode::TemporalRange, "date midnight is invalid")),
        ResultValue::Scalar(ScalarValue::LocalDateTime { seconds, nanos }) => {
            local_datetime_from_stored(*seconds, *nanos)
        }
        ResultValue::Scalar(ScalarValue::ZonedDateTime {
            seconds,
            nanos,
            timezone,
        }) => zoned_datetime_local(*seconds, *nanos, timezone),
        _ => Err(Error::new(
            ErrorCode::QueryType,
            "InvalidArgumentType: datetime truncation input does not contain the required fields",
        )),
    }
}

fn temporal_source_timezone(value: &ResultValue) -> Result<String> {
    match value {
        ResultValue::Scalar(ScalarValue::ZonedDateTime { timezone, .. }) => {
            Ok(timezone.to_string())
        }
        ResultValue::Scalar(ScalarValue::Date(_) | ScalarValue::LocalDateTime { .. }) => {
            Ok("UTC".to_owned())
        }
        _ => Err(Error::new(
            ErrorCode::QueryType,
            "InvalidArgumentType: datetime truncation input has no date-time fields",
        )),
    }
}

fn temporal_source_clock(value: &ResultValue) -> Result<(i64, Option<i32>)> {
    match value {
        ResultValue::Scalar(ScalarValue::LocalTime(nanos)) => Ok((*nanos, None)),
        ResultValue::Scalar(ScalarValue::ZonedTime {
            nanos,
            offset_seconds,
        }) => Ok((*nanos, Some(*offset_seconds))),
        ResultValue::Scalar(ScalarValue::LocalDateTime { seconds, nanos }) => {
            let local = local_datetime_from_stored(*seconds, *nanos)?;
            Ok((local_time_nanos(local.time())?, None))
        }
        ResultValue::Scalar(ScalarValue::ZonedDateTime {
            seconds,
            nanos,
            timezone,
        }) => {
            let local = zoned_datetime_local(*seconds, *nanos, timezone)?;
            Ok((
                local_time_nanos(local.time())?,
                Some(timezone_offset_at(*seconds, *nanos, timezone)?),
            ))
        }
        _ => Err(Error::new(
            ErrorCode::QueryType,
            "InvalidArgumentType: time truncation input has no time fields",
        )),
    }
}

fn truncate_date(
    value: chrono::NaiveDate,
    unit: TemporalTruncateUnit,
) -> Result<chrono::NaiveDate> {
    let date = match unit {
        TemporalTruncateUnit::Millennium => {
            chrono::NaiveDate::from_ymd_opt(value.year().div_euclid(1_000) * 1_000, 1, 1)
        }
        TemporalTruncateUnit::Century => {
            chrono::NaiveDate::from_ymd_opt(value.year().div_euclid(100) * 100, 1, 1)
        }
        TemporalTruncateUnit::Decade => {
            chrono::NaiveDate::from_ymd_opt(value.year().div_euclid(10) * 10, 1, 1)
        }
        TemporalTruncateUnit::Year => chrono::NaiveDate::from_ymd_opt(value.year(), 1, 1),
        TemporalTruncateUnit::WeekYear => {
            chrono::NaiveDate::from_isoywd_opt(value.iso_week().year(), 1, chrono::Weekday::Mon)
        }
        TemporalTruncateUnit::Quarter => {
            chrono::NaiveDate::from_ymd_opt(value.year(), (value.month0() / 3) * 3 + 1, 1)
        }
        TemporalTruncateUnit::Month => {
            chrono::NaiveDate::from_ymd_opt(value.year(), value.month(), 1)
        }
        TemporalTruncateUnit::Week => value.checked_sub_signed(chrono::Duration::days(i64::from(
            value.weekday().num_days_from_monday(),
        ))),
        TemporalTruncateUnit::Day => Some(value),
        _ => None,
    };
    date.ok_or_else(|| {
        Error::new(
            ErrorCode::TemporalRange,
            "temporal date truncation is outside the supported range",
        )
    })
}

fn apply_truncated_date_fields(
    base: chrono::NaiveDate,
    map: Option<&BTreeMap<String, ResultValue>>,
) -> Result<chrono::NaiveDate> {
    let Some(map) = map else {
        return Ok(base);
    };
    let week_mode = ["weekYear", "week", "dayOfWeek"]
        .iter()
        .any(|key| map.contains_key(*key));
    let ordinal_mode = map.contains_key("ordinalDay");
    let quarter_mode = map.contains_key("quarter") || map.contains_key("dayOfQuarter");
    let selected_modes =
        usize::from(week_mode) + usize::from(ordinal_mode) + usize::from(quarter_mode);
    if selected_modes > 1
        || (week_mode && (map.contains_key("month") || map.contains_key("day")))
        || (ordinal_mode && (map.contains_key("month") || map.contains_key("day")))
        || (quarter_mode && map.contains_key("month"))
    {
        return Err(Error::new(
            ErrorCode::QueryType,
            "InvalidArgumentValue: conflicting temporal date fields",
        ));
    }

    if week_mode {
        let iso = base.iso_week();
        let year = temporal_map_i32(map, "weekYear")?
            .or(temporal_map_i32(map, "year")?)
            .unwrap_or(iso.year());
        let week = temporal_map_u32(map, "week")?.unwrap_or(iso.week());
        let weekday = temporal_map_u32(map, "dayOfWeek")?
            .map(iso_weekday)
            .transpose()?
            .unwrap_or(base.weekday());
        return chrono::NaiveDate::from_isoywd_opt(year, week, weekday).ok_or_else(|| {
            Error::new(
                ErrorCode::QueryType,
                "InvalidArgumentValue: invalid ISO week date",
            )
        });
    }
    if ordinal_mode {
        let year = temporal_map_i32(map, "year")?.unwrap_or(base.year());
        let ordinal = temporal_map_u32(map, "ordinalDay")?.unwrap_or(base.ordinal());
        return chrono::NaiveDate::from_yo_opt(year, ordinal).ok_or_else(|| {
            Error::new(
                ErrorCode::QueryType,
                "InvalidArgumentValue: invalid ordinal date",
            )
        });
    }
    if quarter_mode {
        let year = temporal_map_i32(map, "year")?.unwrap_or(base.year());
        let quarter = temporal_map_u32(map, "quarter")?.unwrap_or(base.month0() / 3 + 1);
        if !(1..=4).contains(&quarter) {
            return Err(Error::new(
                ErrorCode::QueryType,
                "InvalidArgumentValue: quarter must be between 1 and 4",
            ));
        }
        let start =
            chrono::NaiveDate::from_ymd_opt(year, (quarter - 1) * 3 + 1, 1).ok_or_else(|| {
                Error::new(
                    ErrorCode::QueryType,
                    "InvalidArgumentValue: invalid quarter",
                )
            })?;
        let base_quarter_start =
            chrono::NaiveDate::from_ymd_opt(base.year(), (base.month0() / 3) * 3 + 1, 1)
                .ok_or_else(|| Error::new(ErrorCode::TemporalRange, "base quarter is invalid"))?;
        let inherited_day = u32::try_from(
            base.signed_duration_since(base_quarter_start)
                .num_days()
                .checked_add(1)
                .ok_or_else(|| Error::new(ErrorCode::TemporalRange, "quarter day overflows"))?,
        )
        .map_err(|_| Error::new(ErrorCode::TemporalRange, "quarter day is outside its range"))?;
        let day = temporal_map_u32(map, "dayOfQuarter")?.unwrap_or(inherited_day);
        let date = start
            .checked_add_signed(chrono::Duration::days(i64::from(
                day.checked_sub(1).ok_or_else(|| {
                    Error::new(
                        ErrorCode::QueryType,
                        "InvalidArgumentValue: dayOfQuarter starts at 1",
                    )
                })?,
            )))
            .ok_or_else(|| Error::new(ErrorCode::TemporalRange, "quarter date overflows"))?;
        if date.month0() / 3 + 1 != quarter {
            return Err(Error::new(
                ErrorCode::QueryType,
                "InvalidArgumentValue: dayOfQuarter exceeds the quarter",
            ));
        }
        return Ok(date);
    }

    let year = temporal_map_i32(map, "year")?.unwrap_or(base.year());
    let month = temporal_map_u32(map, "month")?.unwrap_or(base.month());
    let day = temporal_map_u32(map, "day")?.unwrap_or(base.day());
    chrono::NaiveDate::from_ymd_opt(year, month, day).ok_or_else(|| {
        Error::new(
            ErrorCode::QueryType,
            "InvalidArgumentValue: temporal map produces an invalid calendar date",
        )
    })
}

fn truncate_local_datetime(
    value: chrono::NaiveDateTime,
    unit: TemporalTruncateUnit,
    map: Option<&BTreeMap<String, ResultValue>>,
) -> Result<chrono::NaiveDateTime> {
    let date = if unit.is_date_unit() {
        truncate_date(value.date(), unit)?
    } else {
        value.date()
    };
    let clock = if unit.is_date_unit() {
        0
    } else {
        truncate_clock(local_time_nanos(value.time())?, unit)?
    };
    let date = apply_truncated_date_fields(date, map)?;
    let clock = apply_truncated_clock_fields(clock, unit, map)?;
    date.and_time(clock_from_nanos(clock)?)
        .checked_add_signed(chrono::Duration::zero())
        .ok_or_else(|| Error::new(ErrorCode::TemporalRange, "local datetime overflows"))
}

fn truncate_clock(value: i64, unit: TemporalTruncateUnit) -> Result<i64> {
    const SECOND: i64 = 1_000_000_000;
    const MINUTE: i64 = 60 * SECOND;
    const HOUR: i64 = 60 * MINUTE;
    const DAY: i64 = 24 * HOUR;
    if !(0..DAY).contains(&value) {
        return Err(Error::new(
            ErrorCode::TemporalRange,
            "time value is outside one day",
        ));
    }
    let divisor = match unit {
        TemporalTruncateUnit::Day => DAY,
        TemporalTruncateUnit::Hour => HOUR,
        TemporalTruncateUnit::Minute => MINUTE,
        TemporalTruncateUnit::Second => SECOND,
        TemporalTruncateUnit::Millisecond => 1_000_000,
        TemporalTruncateUnit::Microsecond => 1_000,
        _ => {
            return Err(Error::new(
                ErrorCode::QueryType,
                "InvalidArgumentValue: date unit cannot truncate a time",
            ));
        }
    };
    Ok((value / divisor) * divisor)
}

fn apply_truncated_clock_fields(
    base: i64,
    unit: TemporalTruncateUnit,
    map: Option<&BTreeMap<String, ResultValue>>,
) -> Result<i64> {
    const SECOND: i64 = 1_000_000_000;
    let Some(map) = map else {
        return Ok(base);
    };
    let base_seconds = base / SECOND;
    let hour = temporal_map_i64(map, "hour")?.unwrap_or(base_seconds / 3_600);
    let minute = temporal_map_i64(map, "minute")?.unwrap_or((base_seconds / 60) % 60);
    let second = temporal_map_i64(map, "second")?.unwrap_or(base_seconds % 60);
    if !(0..=23).contains(&hour) || !(0..=59).contains(&minute) || !(0..=59).contains(&second) {
        return Err(Error::new(
            ErrorCode::QueryType,
            "InvalidArgumentValue: invalid clock fields",
        ));
    }

    let base_fraction = base % SECOND;
    let millisecond = temporal_map_i64(map, "millisecond")?;
    let microsecond = temporal_map_i64(map, "microsecond")?;
    let nanosecond = temporal_map_i64(map, "nanosecond")?;
    let fraction = if let Some(millisecond) = millisecond {
        let microsecond = microsecond.unwrap_or(0);
        let nanosecond = nanosecond.unwrap_or(0);
        if !(0..=999).contains(&millisecond)
            || !(0..=999).contains(&microsecond)
            || !(0..=999).contains(&nanosecond)
        {
            return Err(Error::new(
                ErrorCode::QueryType,
                "InvalidArgumentValue: invalid subsecond fields",
            ));
        }
        millisecond * 1_000_000 + microsecond * 1_000 + nanosecond
    } else if let Some(microsecond) = microsecond {
        let nanosecond = nanosecond.unwrap_or(0);
        if unit == TemporalTruncateUnit::Millisecond {
            if !(0..=999).contains(&microsecond) || !(0..=999).contains(&nanosecond) {
                return Err(Error::new(
                    ErrorCode::QueryType,
                    "InvalidArgumentValue: invalid sub-millisecond fields",
                ));
            }
            (base_fraction / 1_000_000) * 1_000_000 + microsecond * 1_000 + nanosecond
        } else {
            if !(0..=999_999).contains(&microsecond) || !(0..=999).contains(&nanosecond) {
                return Err(Error::new(
                    ErrorCode::QueryType,
                    "InvalidArgumentValue: invalid microsecond fields",
                ));
            }
            microsecond * 1_000 + nanosecond
        }
    } else if let Some(nanosecond) = nanosecond {
        if matches!(
            unit,
            TemporalTruncateUnit::Millisecond | TemporalTruncateUnit::Microsecond
        ) {
            if !(0..=999).contains(&nanosecond) {
                return Err(Error::new(
                    ErrorCode::QueryType,
                    "InvalidArgumentValue: nanosecond remainder must be between 0 and 999",
                ));
            }
            (base_fraction / 1_000) * 1_000 + nanosecond
        } else {
            if !(0..1_000_000_000).contains(&nanosecond) {
                return Err(Error::new(
                    ErrorCode::QueryType,
                    "InvalidArgumentValue: nanosecond must be between 0 and 999999999",
                ));
            }
            nanosecond
        }
    } else {
        base_fraction
    };
    (hour * 3_600 + minute * 60 + second)
        .checked_mul(SECOND)
        .and_then(|value| value.checked_add(fraction))
        .ok_or_else(|| Error::new(ErrorCode::TemporalRange, "clock fields overflow"))
}

fn temporal_map_i64(map: &BTreeMap<String, ResultValue>, key: &str) -> Result<Option<i64>> {
    match map.get(key) {
        None => Ok(None),
        Some(ResultValue::Scalar(ScalarValue::Integer(value))) => Ok(Some(*value)),
        Some(_) => Err(Error::new(
            ErrorCode::QueryType,
            format!("InvalidArgumentType: temporal field `{key}` must be an INTEGER"),
        )),
    }
}

fn temporal_map_i32(map: &BTreeMap<String, ResultValue>, key: &str) -> Result<Option<i32>> {
    temporal_map_i64(map, key)?
        .map(|value| {
            i32::try_from(value).map_err(|_| {
                Error::new(
                    ErrorCode::TemporalRange,
                    format!("temporal field `{key}` is outside its range"),
                )
            })
        })
        .transpose()
}

fn temporal_map_u32(map: &BTreeMap<String, ResultValue>, key: &str) -> Result<Option<u32>> {
    temporal_map_i64(map, key)?
        .map(|value| {
            u32::try_from(value).map_err(|_| {
                Error::new(
                    ErrorCode::QueryType,
                    format!("InvalidArgumentValue: temporal field `{key}` must be non-negative"),
                )
            })
        })
        .transpose()
}

fn temporal_map_string<'a>(
    map: Option<&'a BTreeMap<String, ResultValue>>,
    key: &str,
) -> Result<Option<&'a str>> {
    match map.and_then(|values| values.get(key)) {
        None => Ok(None),
        Some(ResultValue::Scalar(ScalarValue::String(value))) => Ok(Some(value)),
        Some(_) => Err(Error::new(
            ErrorCode::QueryType,
            format!("InvalidArgumentType: temporal field `{key}` must be a STRING"),
        )),
    }
}

fn iso_weekday(value: u32) -> Result<chrono::Weekday> {
    match value {
        1 => Ok(chrono::Weekday::Mon),
        2 => Ok(chrono::Weekday::Tue),
        3 => Ok(chrono::Weekday::Wed),
        4 => Ok(chrono::Weekday::Thu),
        5 => Ok(chrono::Weekday::Fri),
        6 => Ok(chrono::Weekday::Sat),
        7 => Ok(chrono::Weekday::Sun),
        _ => Err(Error::new(
            ErrorCode::QueryType,
            "InvalidArgumentValue: dayOfWeek must be between 1 and 7",
        )),
    }
}

fn unix_epoch_date() -> Result<chrono::NaiveDate> {
    chrono::NaiveDate::from_ymd_opt(1970, 1, 1)
        .ok_or_else(|| Error::internal("Unix epoch date is unavailable"))
}

fn date_from_days(days: i64) -> Result<chrono::NaiveDate> {
    unix_epoch_date()?
        .checked_add_signed(chrono::Duration::days(days))
        .ok_or_else(|| {
            Error::new(
                ErrorCode::TemporalRange,
                "date is outside the supported range",
            )
        })
}

fn date_scalar(date: chrono::NaiveDate) -> Result<ResultValue> {
    let days = date.signed_duration_since(unix_epoch_date()?).num_days();
    Ok(ResultValue::Scalar(ScalarValue::Date(days)))
}

fn local_datetime_from_stored(seconds: i64, nanos: u32) -> Result<chrono::NaiveDateTime> {
    chrono::DateTime::<chrono::Utc>::from_timestamp(seconds, nanos)
        .map(|value| value.naive_utc())
        .ok_or_else(|| {
            Error::new(
                ErrorCode::TemporalRange,
                "local datetime is outside the supported range",
            )
        })
}

fn local_datetime_scalar(value: chrono::NaiveDateTime) -> Result<ResultValue> {
    let value = value.and_utc();
    Ok(ResultValue::Scalar(ScalarValue::LocalDateTime {
        seconds: value.timestamp(),
        nanos: value.timestamp_subsec_nanos(),
    }))
}

fn clock_from_nanos(nanos: i64) -> Result<chrono::NaiveTime> {
    const SECOND: i64 = 1_000_000_000;
    const DAY: i64 = 86_400 * SECOND;
    if !(0..DAY).contains(&nanos) {
        return Err(Error::new(
            ErrorCode::TemporalRange,
            "time is outside one day",
        ));
    }
    chrono::NaiveTime::from_num_seconds_from_midnight_opt(
        u32::try_from(nanos / SECOND)
            .map_err(|_| Error::new(ErrorCode::TemporalRange, "time seconds are invalid"))?,
        u32::try_from(nanos % SECOND)
            .map_err(|_| Error::new(ErrorCode::TemporalRange, "time nanoseconds are invalid"))?,
    )
    .ok_or_else(|| Error::new(ErrorCode::TemporalRange, "time is invalid"))
}

fn parse_fixed_timezone_seconds(timezone: &str) -> Result<i32> {
    if timezone.eq_ignore_ascii_case("UTC") || timezone.eq_ignore_ascii_case("Z") {
        return Ok(0);
    }
    timezone
        .parse::<chrono::FixedOffset>()
        .map(|offset| offset.local_minus_utc())
        .map_err(|_| {
            Error::new(
                ErrorCode::QueryType,
                "InvalidArgumentValue: time timezone must be a fixed UTC offset",
            )
        })
}

fn zoned_datetime_local(seconds: i64, nanos: u32, timezone: &str) -> Result<chrono::NaiveDateTime> {
    let instant =
        chrono::DateTime::<chrono::Utc>::from_timestamp(seconds, nanos).ok_or_else(|| {
            Error::new(
                ErrorCode::TemporalRange,
                "datetime is outside the supported range",
            )
        })?;
    if timezone.eq_ignore_ascii_case("UTC") || timezone.eq_ignore_ascii_case("Z") {
        return Ok(instant.naive_utc());
    }
    if let Ok(offset) = timezone.parse::<chrono::FixedOffset>() {
        return Ok(instant.with_timezone(&offset).naive_local());
    }
    let zone = timezone.parse::<chrono_tz::Tz>().map_err(|_| {
        Error::new(
            ErrorCode::QueryType,
            format!("InvalidArgumentValue: unknown timezone `{timezone}`"),
        )
    })?;
    Ok(instant.with_timezone(&zone).naive_local())
}

fn timezone_offset_at(seconds: i64, nanos: u32, timezone: &str) -> Result<i32> {
    if timezone.eq_ignore_ascii_case("UTC") || timezone.eq_ignore_ascii_case("Z") {
        return Ok(0);
    }
    if let Ok(offset) = timezone.parse::<chrono::FixedOffset>() {
        return Ok(offset.local_minus_utc());
    }
    let instant =
        chrono::DateTime::<chrono::Utc>::from_timestamp(seconds, nanos).ok_or_else(|| {
            Error::new(
                ErrorCode::TemporalRange,
                "datetime is outside the supported range",
            )
        })?;
    let zone = timezone.parse::<chrono_tz::Tz>().map_err(|_| {
        Error::new(
            ErrorCode::QueryType,
            format!("InvalidArgumentValue: unknown timezone `{timezone}`"),
        )
    })?;
    Ok(instant
        .with_timezone(&zone)
        .offset()
        .fix()
        .local_minus_utc())
}

fn zoned_datetime_scalar(local: chrono::NaiveDateTime, timezone: &str) -> Result<ResultValue> {
    let (seconds, nanos, timezone): (i64, u32, Arc<str>) =
        if timezone.eq_ignore_ascii_case("UTC") || timezone.eq_ignore_ascii_case("Z") {
            let value = local.and_utc();
            (
                value.timestamp(),
                value.timestamp_subsec_nanos(),
                Arc::from("UTC"),
            )
        } else if let Ok(offset) = timezone.parse::<chrono::FixedOffset>() {
            let value = offset.from_local_datetime(&local).single().ok_or_else(|| {
                Error::new(
                    ErrorCode::QueryType,
                    "InvalidArgumentValue: local datetime is invalid in the fixed timezone",
                )
            })?;
            (
                value.timestamp(),
                value.timestamp_subsec_nanos(),
                Arc::from(offset.to_string()),
            )
        } else {
            let zone = timezone.parse::<chrono_tz::Tz>().map_err(|_| {
                Error::new(
                    ErrorCode::QueryType,
                    format!("InvalidArgumentValue: unknown timezone `{timezone}`"),
                )
            })?;
            let value = match zone.from_local_datetime(&local) {
                chrono::LocalResult::Single(value) => value,
                chrono::LocalResult::Ambiguous(_, _) => {
                    return Err(Error::new(
                        ErrorCode::QueryType,
                        "InvalidArgumentValue: local datetime is ambiguous in the timezone",
                    ));
                }
                chrono::LocalResult::None => {
                    return Err(Error::new(
                        ErrorCode::QueryType,
                        "InvalidArgumentValue: local datetime does not exist in the timezone",
                    ));
                }
            };
            (
                value.timestamp(),
                value.timestamp_subsec_nanos(),
                Arc::from(zone.name()),
            )
        };
    Ok(ResultValue::Scalar(ScalarValue::ZonedDateTime {
        seconds,
        nanos,
        timezone,
    }))
}

fn zoned_datetime_at_instant(seconds: i64, nanos: u32, timezone: &str) -> Result<ResultValue> {
    chrono::DateTime::<chrono::Utc>::from_timestamp(seconds, nanos).ok_or_else(|| {
        Error::new(
            ErrorCode::TemporalRange,
            "datetime is outside the supported range",
        )
    })?;
    let timezone: Arc<str> =
        if timezone.eq_ignore_ascii_case("UTC") || timezone.eq_ignore_ascii_case("Z") {
            Arc::from("UTC")
        } else if let Ok(offset) = timezone.parse::<chrono::FixedOffset>() {
            Arc::from(offset.to_string())
        } else {
            let zone = timezone.parse::<chrono_tz::Tz>().map_err(|_| {
                Error::new(
                    ErrorCode::QueryType,
                    format!("InvalidArgumentValue: unknown timezone `{timezone}`"),
                )
            })?;
            Arc::from(zone.name())
        };
    Ok(ResultValue::Scalar(ScalarValue::ZonedDateTime {
        seconds,
        nanos,
        timezone,
    }))
}

#[derive(Clone, Debug)]
struct TemporalProjectionParts {
    date: Option<chrono::NaiveDate>,
    clock_nanos: Option<i64>,
    timezone: Option<String>,
    instant: Option<(i64, u32)>,
}

fn temporal_projection_parts(value: &ResultValue) -> Result<TemporalProjectionParts> {
    let parts = match value {
        ResultValue::Scalar(ScalarValue::Date(days)) => TemporalProjectionParts {
            date: Some(date_from_days(*days)?),
            clock_nanos: None,
            timezone: None,
            instant: None,
        },
        ResultValue::Scalar(ScalarValue::LocalTime(nanos)) => TemporalProjectionParts {
            date: None,
            clock_nanos: Some(*nanos),
            timezone: None,
            instant: None,
        },
        ResultValue::Scalar(ScalarValue::ZonedTime {
            nanos,
            offset_seconds,
        }) => {
            let offset = chrono::FixedOffset::east_opt(*offset_seconds).ok_or_else(|| {
                Error::new(
                    ErrorCode::TemporalRange,
                    "zoned time contains an invalid UTC offset",
                )
            })?;
            TemporalProjectionParts {
                date: None,
                clock_nanos: Some(*nanos),
                timezone: Some(offset.to_string()),
                instant: None,
            }
        }
        ResultValue::Scalar(ScalarValue::LocalDateTime { seconds, nanos }) => {
            let local = local_datetime_from_stored(*seconds, *nanos)?;
            TemporalProjectionParts {
                date: Some(local.date()),
                clock_nanos: Some(local_time_nanos(local.time())?),
                timezone: None,
                instant: None,
            }
        }
        ResultValue::Scalar(ScalarValue::ZonedDateTime {
            seconds,
            nanos,
            timezone,
        }) => {
            let local = zoned_datetime_local(*seconds, *nanos, timezone)?;
            TemporalProjectionParts {
                date: Some(local.date()),
                clock_nanos: Some(local_time_nanos(local.time())?),
                timezone: Some(timezone.to_string()),
                instant: Some((*seconds, *nanos)),
            }
        }
        _ => {
            return Err(Error::new(
                ErrorCode::QueryType,
                "InvalidArgumentType: temporal projection requires a temporal value",
            ));
        }
    };
    Ok(parts)
}

fn temporal_constructor_from_temporal(name: &str, value: &ResultValue) -> Result<ResultValue> {
    let parts = temporal_projection_parts(value)?;
    match name {
        "date" => date_scalar(parts.date.ok_or_else(|| {
            Error::new(
                ErrorCode::QueryType,
                "InvalidArgumentType: date projection requires a value with a date",
            )
        })?),
        "localtime" => Ok(ResultValue::Scalar(ScalarValue::LocalTime(
            parts.clock_nanos.ok_or_else(|| {
                Error::new(
                    ErrorCode::QueryType,
                    "InvalidArgumentType: localtime projection requires a value with a time",
                )
            })?,
        ))),
        "time" => {
            let clock_nanos = parts.clock_nanos.ok_or_else(|| {
                Error::new(
                    ErrorCode::QueryType,
                    "InvalidArgumentType: time projection requires a value with a time",
                )
            })?;
            let offset_seconds = match (parts.timezone.as_deref(), parts.instant) {
                (Some(timezone), Some((seconds, nanos))) => {
                    timezone_offset_at(seconds, nanos, timezone)?
                }
                (Some(timezone), None) => parse_fixed_timezone_seconds(timezone)?,
                (None, _) => 0,
            };
            Ok(ResultValue::Scalar(ScalarValue::ZonedTime {
                nanos: clock_nanos,
                offset_seconds,
            }))
        }
        "localdatetime" => {
            let date = parts.date.ok_or_else(|| {
                Error::new(
                    ErrorCode::QueryType,
                    "InvalidArgumentType: localdatetime projection requires a date and time",
                )
            })?;
            let clock = parts.clock_nanos.ok_or_else(|| {
                Error::new(
                    ErrorCode::QueryType,
                    "InvalidArgumentType: localdatetime projection requires a date and time",
                )
            })?;
            local_datetime_scalar(date.and_time(clock_from_nanos(clock)?))
        }
        "datetime" => {
            let date = parts.date.ok_or_else(|| {
                Error::new(
                    ErrorCode::QueryType,
                    "InvalidArgumentType: datetime projection requires a date and time",
                )
            })?;
            let clock = parts.clock_nanos.ok_or_else(|| {
                Error::new(
                    ErrorCode::QueryType,
                    "InvalidArgumentType: datetime projection requires a date and time",
                )
            })?;
            match (parts.instant, parts.timezone.as_deref()) {
                (Some((seconds, nanos)), Some(timezone)) => {
                    zoned_datetime_at_instant(seconds, nanos, timezone)
                }
                _ => zoned_datetime_scalar(date.and_time(clock_from_nanos(clock)?), "UTC"),
            }
        }
        _ => Err(Error::internal(
            "temporal projection dispatch is inconsistent",
        )),
    }
}

fn temporal_constructor(
    name: &str,
    values: &[ResultValue],
    resolved_time_nanos: i64,
) -> Result<ResultValue> {
    if values.len() > 1 {
        return Err(function_arity(name, "zero or one", values.len()));
    }
    let seconds = resolved_time_nanos.div_euclid(1_000_000_000);
    let nanos = u32::try_from(resolved_time_nanos.rem_euclid(1_000_000_000)).map_err(|_| {
        Error::new(
            ErrorCode::TemporalRange,
            "timestamp nanoseconds are invalid",
        )
    })?;
    let now = chrono::DateTime::<chrono::Utc>::from_timestamp(seconds, nanos).ok_or_else(|| {
        Error::new(
            ErrorCode::TemporalRange,
            "resolved query time is outside the temporal range",
        )
    })?;
    if let Some(value) = values.first() {
        if let ResultValue::Map(map) = value {
            return temporal_constructor_from_map(name, map);
        }
        if !matches!(value, ResultValue::Scalar(ScalarValue::String(_))) {
            return temporal_constructor_from_temporal(name, value);
        }
    }
    let text = values.first().map(|_| string_arg(values, 0)).transpose()?;
    match name {
        "date" => {
            let days = text.map_or_else(
                || {
                    Ok::<i64, Error>(
                        now.date_naive()
                            .signed_duration_since(unix_epoch_date()?)
                            .num_days(),
                    )
                },
                |text| parse_iso_civil_date(&text)?.epoch_day(),
            )?;
            Ok(ResultValue::Scalar(ScalarValue::Date(days)))
        }
        "localtime" => {
            let time = text.map_or(Ok(now.time()), |text| parse_local_time(&text))?;
            Ok(ResultValue::Scalar(ScalarValue::LocalTime(
                local_time_nanos(time)?,
            )))
        }
        "time" => {
            let (time, offset_seconds) =
                text.map_or_else(|| Ok((now.time(), 0_i32)), |text| parse_offset_time(&text))?;
            Ok(ResultValue::Scalar(ScalarValue::ZonedTime {
                nanos: local_time_nanos(time)?,
                offset_seconds,
            }))
        }
        "localdatetime" => {
            let (seconds, nanos) = text.map_or_else(
                || Ok((now.timestamp(), now.timestamp_subsec_nanos())),
                |text| parse_iso_local_datetime(&text),
            )?;
            Ok(ResultValue::Scalar(ScalarValue::LocalDateTime {
                seconds,
                nanos,
            }))
        }
        "datetime" => {
            let (seconds, nanos, timezone) = text.map_or_else(
                || {
                    Ok::<(i64, u32, Arc<str>), Error>((
                        now.timestamp(),
                        now.timestamp_subsec_nanos(),
                        Arc::from("UTC"),
                    ))
                },
                |text| parse_iso_zoned_datetime(&text),
            )?;
            Ok(ResultValue::Scalar(ScalarValue::ZonedDateTime {
                seconds,
                nanos,
                timezone,
            }))
        }
        _ => Err(Error::internal(
            "temporal function dispatch is inconsistent",
        )),
    }
}

/// Evaluate an explicit deterministic temporal constructor for native-plan constant folding.
/// The zero-argument clock form is intentionally excluded: it must remain bound to the query's
/// resolved timestamp instead of being folded with a synthetic host time.
pub fn evaluate_explicit_temporal_constructor(
    name: &str,
    values: &[ResultValue],
) -> Result<ResultValue> {
    if values.is_empty() {
        return Err(Error::internal(
            "explicit temporal constant folding received a clock constructor",
        ));
    }
    if values
        .iter()
        .any(|value| matches!(value, ResultValue::Scalar(ScalarValue::Null)))
    {
        return Ok(ResultValue::Scalar(ScalarValue::Null));
    }
    temporal_constructor(name, values, 0)
}

/// Evaluate one deterministic duration constructor through the same normalization and range
/// checks used by ordinary Cypher execution.
pub fn evaluate_explicit_duration_constructor(values: &[ResultValue]) -> Result<ResultValue> {
    require_arity("duration", values, 1)?;
    if values
        .iter()
        .any(|value| matches!(value, ResultValue::Scalar(ScalarValue::Null)))
    {
        return Ok(ResultValue::Scalar(ScalarValue::Null));
    }
    duration_constructor(&values[0])
}

fn temporal_constructor_from_map(
    name: &str,
    map: &BTreeMap<String, ResultValue>,
) -> Result<ResultValue> {
    validate_temporal_constructor_map(name, map)?;
    if name == "datetime" && (map.contains_key("epochSeconds") || map.contains_key("epochMillis")) {
        return temporal_constructor_from_epoch_map(map);
    }

    let date_source = map.get("date").map(temporal_projection_parts).transpose()?;
    let time_source = map.get("time").map(temporal_projection_parts).transpose()?;
    let datetime_source = map
        .get("datetime")
        .map(temporal_projection_parts)
        .transpose()?;
    let date_base = date_source.as_ref().or(datetime_source.as_ref());
    let clock_base = time_source.as_ref().or(datetime_source.as_ref());

    match name {
        "date" => date_scalar(temporal_constructor_date(map, date_base)?),
        "localtime" => Ok(ResultValue::Scalar(ScalarValue::LocalTime(
            temporal_constructor_clock(map, clock_base)?,
        ))),
        "time" => temporal_constructor_time(map, clock_base),
        "localdatetime" => {
            let local = temporal_constructor_date(map, date_base)?.and_time(clock_from_nanos(
                temporal_constructor_clock(map, clock_base)?,
            )?);
            local_datetime_scalar(local)
        }
        "datetime" => temporal_constructor_datetime(
            map,
            date_base,
            clock_base,
            time_source.as_ref().or(datetime_source.as_ref()),
            datetime_source.as_ref(),
        ),
        _ => Err(Error::internal(
            "temporal map constructor dispatch is inconsistent",
        )),
    }
}

fn temporal_constructor_from_epoch_map(map: &BTreeMap<String, ResultValue>) -> Result<ResultValue> {
    let timezone = temporal_map_string(Some(map), "timezone")?.unwrap_or("UTC");
    if let Some(milliseconds) = temporal_map_i64(map, "epochMillis")? {
        let seconds = milliseconds.div_euclid(1_000);
        let nanos = u32::try_from(milliseconds.rem_euclid(1_000) * 1_000_000).map_err(|_| {
            Error::new(
                ErrorCode::TemporalRange,
                "epoch millisecond fraction is outside the temporal range",
            )
        })?;
        return zoned_datetime_at_instant(seconds, nanos, timezone);
    }
    let seconds = temporal_map_i64(map, "epochSeconds")?.ok_or_else(|| {
        Error::new(
            ErrorCode::QueryType,
            "InvalidArgumentValue: datetime epoch map requires epochSeconds or epochMillis",
        )
    })?;
    let nanos = temporal_map_i64(map, "nanosecond")?.unwrap_or(0);
    let nanos = u32::try_from(nanos)
        .ok()
        .filter(|value| *value < 1_000_000_000)
        .ok_or_else(|| {
            Error::new(
                ErrorCode::QueryType,
                "InvalidArgumentValue: epoch nanosecond must be between 0 and 999999999",
            )
        })?;
    zoned_datetime_at_instant(seconds, nanos, timezone)
}

fn temporal_constructor_time(
    map: &BTreeMap<String, ResultValue>,
    source: Option<&TemporalProjectionParts>,
) -> Result<ResultValue> {
    const SECOND: i64 = 1_000_000_000;
    const DAY: i64 = 86_400 * SECOND;
    let mut clock = temporal_constructor_clock(map, source)?;
    let requested_timezone = temporal_map_string(Some(map), "timezone")?;
    let target_offset = requested_timezone
        .map(parse_fixed_timezone_seconds)
        .transpose()?;
    let source_offset = source
        .and_then(|source| {
            source
                .timezone
                .as_deref()
                .map(|timezone| (source, timezone))
        })
        .map(|(source, timezone)| temporal_projection_offset(source, timezone, clock))
        .transpose()?;
    let offset_seconds = match (source_offset, target_offset) {
        (Some(source_offset), Some(target_offset)) => {
            clock = clock
                .checked_sub(i64::from(source_offset) * SECOND)
                .and_then(|value| value.checked_add(i64::from(target_offset) * SECOND))
                .ok_or_else(|| Error::new(ErrorCode::TemporalRange, "time conversion overflow"))?
                .rem_euclid(DAY);
            target_offset
        }
        (Some(source_offset), None) => source_offset,
        (None, Some(target_offset)) => target_offset,
        (None, None) => 0,
    };
    Ok(ResultValue::Scalar(ScalarValue::ZonedTime {
        nanos: clock,
        offset_seconds,
    }))
}

fn temporal_projection_offset(
    source: &TemporalProjectionParts,
    timezone: &str,
    adjusted_clock: i64,
) -> Result<i32> {
    if let Some(date) = source.date {
        let local = date.and_time(clock_from_nanos(adjusted_clock)?);
        let ResultValue::Scalar(ScalarValue::ZonedDateTime { seconds, nanos, .. }) =
            zoned_datetime_scalar(local, timezone)?
        else {
            return Err(Error::internal(
                "zoned datetime construction returned the wrong value type",
            ));
        };
        timezone_offset_at(seconds, nanos, timezone)
    } else {
        parse_fixed_timezone_seconds(timezone)
    }
}

fn temporal_constructor_datetime(
    map: &BTreeMap<String, ResultValue>,
    date_source: Option<&TemporalProjectionParts>,
    clock_source: Option<&TemporalProjectionParts>,
    zone_source: Option<&TemporalProjectionParts>,
    datetime_source: Option<&TemporalProjectionParts>,
) -> Result<ResultValue> {
    let date = temporal_constructor_date(map, date_source)?;
    let clock = temporal_constructor_clock(map, clock_source)?;
    let local = date.and_time(clock_from_nanos(clock)?);
    let source_timezone = zone_source.and_then(|source| source.timezone.as_deref());
    let requested_timezone = temporal_map_string(Some(map), "timezone")?;
    let has_field_overrides = map.keys().any(|key| {
        matches!(
            key.as_str(),
            "year"
                | "weekYear"
                | "quarter"
                | "month"
                | "week"
                | "day"
                | "dayOfWeek"
                | "ordinalDay"
                | "dayOfQuarter"
                | "hour"
                | "minute"
                | "second"
                | "millisecond"
                | "microsecond"
                | "nanosecond"
        )
    });

    if !has_field_overrides
        && map.contains_key("datetime")
        && let Some(source) = datetime_source
        && let Some((seconds, nanos)) = source.instant
    {
        return zoned_datetime_at_instant(
            seconds,
            nanos,
            requested_timezone
                .or(source.timezone.as_deref())
                .unwrap_or("UTC"),
        );
    }

    match (source_timezone, requested_timezone) {
        (Some(source_timezone), Some(target_timezone)) => {
            let ResultValue::Scalar(ScalarValue::ZonedDateTime { seconds, nanos, .. }) =
                zoned_datetime_scalar(local, source_timezone)?
            else {
                return Err(Error::internal(
                    "zoned datetime construction returned the wrong value type",
                ));
            };
            zoned_datetime_at_instant(seconds, nanos, target_timezone)
        }
        (Some(source_timezone), None) => zoned_datetime_scalar(local, source_timezone),
        (None, Some(target_timezone)) => zoned_datetime_scalar(local, target_timezone),
        (None, None) => zoned_datetime_scalar(local, "UTC"),
    }
}

fn validate_temporal_constructor_map(
    name: &str,
    map: &BTreeMap<String, ResultValue>,
) -> Result<()> {
    for key in map.keys() {
        let date_field = matches!(
            key.as_str(),
            "year"
                | "weekYear"
                | "quarter"
                | "month"
                | "week"
                | "day"
                | "dayOfWeek"
                | "ordinalDay"
                | "dayOfQuarter"
        );
        let time_field = matches!(
            key.as_str(),
            "hour" | "minute" | "second" | "millisecond" | "microsecond" | "nanosecond"
        );
        let accepted = match name {
            "date" => date_field || key == "date",
            "localtime" => time_field || key == "time",
            "time" => time_field || matches!(key.as_str(), "time" | "timezone"),
            "localdatetime" => {
                date_field || time_field || matches!(key.as_str(), "date" | "time" | "datetime")
            }
            "datetime" => {
                date_field
                    || time_field
                    || matches!(
                        key.as_str(),
                        "date" | "time" | "datetime" | "timezone" | "epochSeconds" | "epochMillis"
                    )
            }
            _ => false,
        };
        if !accepted {
            return Err(Error::new(
                ErrorCode::QueryType,
                format!("InvalidArgumentValue: `{key}` is not valid in {name} map construction"),
            ));
        }
    }
    if map.contains_key("datetime") && (map.contains_key("date") || map.contains_key("time")) {
        return Err(Error::new(
            ErrorCode::QueryType,
            "InvalidArgumentValue: datetime source cannot be combined with date or time sources",
        ));
    }
    if map.contains_key("epochSeconds") && map.contains_key("epochMillis") {
        return Err(Error::new(
            ErrorCode::QueryType,
            "InvalidArgumentValue: epochSeconds and epochMillis are mutually exclusive",
        ));
    }
    if map.contains_key("epochSeconds") || map.contains_key("epochMillis") {
        let invalid = map.keys().any(|key| {
            !matches!(
                key.as_str(),
                "epochSeconds" | "epochMillis" | "nanosecond" | "timezone"
            )
        }) || (map.contains_key("epochMillis") && map.contains_key("nanosecond"));
        if invalid {
            return Err(Error::new(
                ErrorCode::QueryType,
                "InvalidArgumentValue: epoch datetime construction cannot mix calendar fields",
            ));
        }
    }
    Ok(())
}

fn temporal_constructor_date(
    map: &BTreeMap<String, ResultValue>,
    source: Option<&TemporalProjectionParts>,
) -> Result<chrono::NaiveDate> {
    let base = if let Some(source) = source {
        source.date.ok_or_else(|| {
            Error::new(
                ErrorCode::QueryType,
                "InvalidArgumentType: temporal date source has no date component",
            )
        })?
    } else {
        let year = temporal_map_i32(map, "year")?
            .or(temporal_map_i32(map, "weekYear")?)
            .ok_or_else(|| {
                Error::new(
                    ErrorCode::QueryType,
                    "InvalidArgumentValue: temporal date map requires a year or date source",
                )
            })?;
        if map.contains_key("week") || map.contains_key("weekYear") || map.contains_key("dayOfWeek")
        {
            chrono::NaiveDate::from_isoywd_opt(year, 1, chrono::Weekday::Mon)
        } else {
            chrono::NaiveDate::from_ymd_opt(year, 1, 1)
        }
        .ok_or_else(|| {
            Error::new(
                ErrorCode::QueryType,
                "InvalidArgumentValue: temporal map year is outside the supported range",
            )
        })?
    };
    apply_truncated_date_fields(base, Some(map))
}

fn temporal_constructor_clock(
    map: &BTreeMap<String, ResultValue>,
    source: Option<&TemporalProjectionParts>,
) -> Result<i64> {
    let base = source
        .map(|source| {
            source.clock_nanos.ok_or_else(|| {
                Error::new(
                    ErrorCode::QueryType,
                    "InvalidArgumentType: temporal time source has no time component",
                )
            })
        })
        .transpose()?
        .unwrap_or(0);
    apply_truncated_clock_fields(base, TemporalTruncateUnit::Day, Some(map))
}

fn parse_iso_civil_date(text: &str) -> Result<CivilDate> {
    let (year_month, day) = text.rsplit_once('-').ok_or_else(|| {
        Error::new(
            ErrorCode::QueryType,
            "InvalidArgumentValue: date requires an ISO calendar date",
        )
    })?;
    let (year, month) = year_month.rsplit_once('-').ok_or_else(|| {
        Error::new(
            ErrorCode::QueryType,
            "InvalidArgumentValue: date requires an ISO calendar date",
        )
    })?;
    if year.is_empty() || month.len() != 2 || day.len() != 2 {
        return Err(Error::new(
            ErrorCode::QueryType,
            "InvalidArgumentValue: date requires an ISO calendar date",
        ));
    }
    let year = year.parse::<i64>().map_err(|_| {
        Error::new(
            ErrorCode::QueryType,
            "InvalidArgumentValue: date year is invalid",
        )
    })?;
    let month = month.parse::<u32>().map_err(|_| {
        Error::new(
            ErrorCode::QueryType,
            "InvalidArgumentValue: date month is invalid",
        )
    })?;
    let day = day.parse::<u32>().map_err(|_| {
        Error::new(
            ErrorCode::QueryType,
            "InvalidArgumentValue: date day is invalid",
        )
    })?;
    CivilDate::new(year, month, day)
}

fn parse_iso_local_datetime(text: &str) -> Result<(i64, u32)> {
    let (date, time) = text
        .split_once('T')
        .map_or((text, None), |(date, time)| (date, Some(time)));
    let date = parse_iso_civil_date(date)?;
    let nanos_of_day = time
        .map(parse_local_time)
        .transpose()?
        .map(local_time_nanos)
        .transpose()?
        .unwrap_or(0);
    IntervalLocalDateTime {
        epoch_day: date.epoch_day()?,
        nanos_of_day,
    }
    .stored()
}

fn parse_compact_or_colon_offset(text: &str) -> Result<i32> {
    let normalized;
    let text = if text.len() == 5 {
        let bytes = text.as_bytes();
        if matches!(bytes.first(), Some(b'+') | Some(b'-'))
            && bytes
                .get(1..)
                .is_some_and(|digits| digits.iter().all(u8::is_ascii_digit))
        {
            normalized = format!("{}:{}", &text[..3], &text[3..]);
            normalized.as_str()
        } else {
            text
        }
    } else {
        text
    };
    parse_fixed_timezone_seconds(text)
}

fn split_datetime_offset(text: &str) -> Result<(&str, i32, bool)> {
    let time_start = text.find('T').ok_or_else(|| {
        Error::new(
            ErrorCode::QueryType,
            "InvalidArgumentValue: datetime requires an ISO local date-time and offset",
        )
    })?;
    if let Some(local) = text.strip_suffix('Z').or_else(|| text.strip_suffix('z')) {
        return Ok((local, 0, true));
    }
    let time = text.get(time_start + 1..).ok_or_else(|| {
        Error::new(
            ErrorCode::QueryType,
            "InvalidArgumentValue: datetime time is invalid",
        )
    })?;
    let relative = time.rfind(['+', '-']).ok_or_else(|| {
        Error::new(
            ErrorCode::QueryType,
            "InvalidArgumentValue: datetime requires an ISO-8601 offset",
        )
    })?;
    let offset_start = time_start + 1 + relative;
    let local = text.get(..offset_start).ok_or_else(|| {
        Error::new(
            ErrorCode::QueryType,
            "InvalidArgumentValue: datetime local value is invalid",
        )
    })?;
    let offset = text.get(offset_start..).ok_or_else(|| {
        Error::new(
            ErrorCode::QueryType,
            "InvalidArgumentValue: datetime offset is invalid",
        )
    })?;
    Ok((local, parse_compact_or_colon_offset(offset)?, false))
}

fn parse_iso_zoned_datetime(text: &str) -> Result<(i64, u32, Arc<str>)> {
    let (datetime, named_zone) = if let Some(without_close) = text.strip_suffix(']') {
        let open = without_close.rfind('[').ok_or_else(|| {
            Error::new(
                ErrorCode::QueryType,
                "InvalidArgumentValue: datetime timezone suffix is invalid",
            )
        })?;
        let datetime = without_close.get(..open).ok_or_else(|| {
            Error::new(
                ErrorCode::QueryType,
                "InvalidArgumentValue: datetime value is invalid",
            )
        })?;
        let zone = without_close
            .get(open + 1..)
            .filter(|zone| !zone.is_empty())
            .ok_or_else(|| {
                Error::new(
                    ErrorCode::QueryType,
                    "InvalidArgumentValue: datetime timezone suffix is empty",
                )
            })?;
        (datetime, Some(zone))
    } else if text.contains(['[', ']']) {
        return Err(Error::new(
            ErrorCode::QueryType,
            "InvalidArgumentValue: datetime timezone suffix is invalid",
        ));
    } else {
        (text, None)
    };
    let (local, offset_seconds, was_utc_designator) = split_datetime_offset(datetime)?;
    let (local_seconds, nanos) = parse_iso_local_datetime(local)?;
    let seconds = local_seconds
        .checked_sub(i64::from(offset_seconds))
        .ok_or_else(|| Error::new(ErrorCode::TemporalRange, "datetime instant overflow"))?;
    let timezone = if let Some(timezone) = named_zone {
        let zone = timezone.parse::<chrono_tz::Tz>().map_err(|_| {
            Error::new(
                ErrorCode::QueryType,
                format!("InvalidArgumentValue: unknown timezone `{timezone}`"),
            )
        })?;
        let actual = timezone_offset_at(seconds, nanos, zone.name())?;
        if actual != offset_seconds {
            return Err(Error::new(
                ErrorCode::QueryType,
                "InvalidArgumentValue: datetime offset does not match the named timezone",
            ));
        }
        Arc::from(zone.name())
    } else if was_utc_designator {
        Arc::from("UTC")
    } else {
        let offset = chrono::FixedOffset::east_opt(offset_seconds).ok_or_else(|| {
            Error::new(
                ErrorCode::QueryType,
                "InvalidArgumentValue: datetime offset is outside its range",
            )
        })?;
        Arc::from(offset.to_string())
    };
    Ok((seconds, nanos, timezone))
}

fn parse_local_time(text: &str) -> Result<chrono::NaiveTime> {
    ["%H:%M:%S%.f", "%H:%M"]
        .into_iter()
        .find_map(|format| chrono::NaiveTime::parse_from_str(text, format).ok())
        .or_else(|| parse_compact_local_time(text))
        .ok_or_else(|| Error::new(ErrorCode::QueryType, "local time is invalid"))
}

fn parse_compact_local_time(text: &str) -> Option<chrono::NaiveTime> {
    let (whole, fraction) = text
        .split_once('.')
        .map_or((text, None), |(whole, fraction)| (whole, Some(fraction)));
    let digits = whole.as_bytes();
    if !digits.iter().all(u8::is_ascii_digit) {
        return None;
    }
    let decimal = |digits: &[u8]| {
        digits.iter().try_fold(0_u32, |value, digit| {
            value.checked_mul(10)?.checked_add(u32::from(*digit - b'0'))
        })
    };
    let (hour, minute, second) = match digits {
        [hour_a, hour_b] if fraction.is_none() => (decimal(&[*hour_a, *hour_b])?, 0, 0),
        [hour_a, hour_b, minute_a, minute_b] if fraction.is_none() => (
            decimal(&[*hour_a, *hour_b])?,
            decimal(&[*minute_a, *minute_b])?,
            0,
        ),
        [hour_a, hour_b, minute_a, minute_b, second_a, second_b] => (
            decimal(&[*hour_a, *hour_b])?,
            decimal(&[*minute_a, *minute_b])?,
            decimal(&[*second_a, *second_b])?,
        ),
        _ => return None,
    };
    let nanos = match fraction {
        None => 0,
        Some(fraction)
            if !fraction.is_empty()
                && fraction.len() <= 9
                && fraction.as_bytes().iter().all(u8::is_ascii_digit) =>
        {
            decimal(fraction.as_bytes())?.checked_mul(
                10_u32.pow(u32::try_from(9_usize.checked_sub(fraction.len())?).ok()?),
            )?
        }
        Some(_) => return None,
    };
    chrono::NaiveTime::from_hms_nano_opt(hour, minute, second, nanos)
}

fn parse_offset_time(text: &str) -> Result<(chrono::NaiveTime, i32)> {
    if let Ok(time) = parse_local_time(text) {
        return Ok((time, 0));
    }
    if let Some(local) = text.strip_suffix('Z').or_else(|| text.strip_suffix('z')) {
        return Ok((parse_local_time(local)?, 0));
    }
    let offset_start = text.rfind(['+', '-']).ok_or_else(|| {
        Error::new(
            ErrorCode::QueryType,
            "time requires an ISO time with an optional offset",
        )
    })?;
    let local = text
        .get(..offset_start)
        .ok_or_else(|| Error::new(ErrorCode::QueryType, "time local component is invalid"))?;
    let offset = text
        .get(offset_start..)
        .ok_or_else(|| Error::new(ErrorCode::QueryType, "time offset is invalid"))?;
    Ok((
        parse_local_time(local)?,
        parse_compact_or_colon_offset(offset)?,
    ))
}

fn local_time_nanos(time: chrono::NaiveTime) -> Result<i64> {
    i64::from(time.num_seconds_from_midnight())
        .checked_mul(1_000_000_000)
        .and_then(|seconds| seconds.checked_add(i64::from(time.nanosecond())))
        .ok_or_else(|| Error::new(ErrorCode::TemporalRange, "local time overflows"))
}

fn timestamp_nanos(value: &ResultValue) -> Result<i64> {
    match value {
        ResultValue::Scalar(ScalarValue::Integer(value)) => Ok(*value),
        ResultValue::Scalar(
            ScalarValue::ZonedDateTime { seconds, nanos, .. }
            | ScalarValue::LocalDateTime { seconds, nanos },
        ) => seconds
            .checked_mul(1_000_000_000)
            .and_then(|value| value.checked_add(i64::from(*nanos)))
            .ok_or_else(|| Error::new(ErrorCode::TemporalRange, "timestamp overflow")),
        _ => Err(Error::new(
            ErrorCode::QueryType,
            "temporal instant is required",
        )),
    }
}

fn duration_nanos(value: &ResultValue) -> Result<i64> {
    match value {
        ResultValue::Scalar(ScalarValue::Duration {
            months: 0,
            days,
            seconds,
            nanos,
        }) => days
            .checked_mul(86_400)
            .and_then(|value| value.checked_add(*seconds))
            .and_then(|value| value.checked_mul(1_000_000_000))
            .and_then(|value| value.checked_add(i64::from(*nanos)))
            .ok_or_else(|| Error::new(ErrorCode::TemporalRange, "duration overflow")),
        ResultValue::Scalar(ScalarValue::Integer(value)) => Ok(*value),
        _ => Err(Error::new(
            ErrorCode::TemporalRange,
            "fixed WINDOW requires an elapsed duration",
        )),
    }
}

pub fn parse_duration(input: &str) -> Result<ScalarValue> {
    let (sign, body) = input
        .strip_prefix("-P")
        .map(|value| (-1_i128, value))
        .or_else(|| input.strip_prefix("+P").map(|value| (1_i128, value)))
        .or_else(|| input.strip_prefix('P').map(|value| (1_i128, value)))
        .ok_or_else(|| {
            Error::new(
                ErrorCode::QueryType,
                "duration must use ISO-8601 P notation",
            )
        })?;
    if body.is_empty() {
        return Err(Error::new(
            ErrorCode::QueryType,
            "duration must contain at least one component",
        ));
    }
    let mut months = 0_i128;
    let mut days = 0_i128;
    let mut clock_nanos = 0_i128;
    let mut number = String::new();
    let mut time = false;
    let mut seen_time_separator = false;
    let mut seen_components = BTreeSet::new();
    for character in body.chars() {
        if character == 'T' {
            if !number.is_empty() || seen_time_separator {
                return Err(Error::new(ErrorCode::QueryType, "invalid duration"));
            }
            time = true;
            seen_time_separator = true;
            continue;
        }
        if character.is_ascii_digit()
            || character == '.'
            || ((character == '+' || character == '-') && number.is_empty())
        {
            number.push(character);
            continue;
        }
        if number.is_empty() {
            return Err(Error::new(
                ErrorCode::QueryType,
                "invalid duration component",
            ));
        }
        if !seen_components.insert((time, character)) {
            return Err(Error::new(
                ErrorCode::QueryType,
                "duration repeats a component",
            ));
        }
        let component = std::mem::take(&mut number);
        let component = parse_duration_decimal(&component)?;
        match (character, time) {
            ('Y', false) => {
                months = months
                    .checked_add(component.checked_mul(12).ok_or_else(|| {
                        Error::new(ErrorCode::TemporalRange, "duration years overflow")
                    })?)
                    .ok_or_else(|| {
                        Error::new(ErrorCode::TemporalRange, "duration months overflow")
                    })?;
            }
            ('M', false) => {
                months = months.checked_add(component).ok_or_else(|| {
                    Error::new(ErrorCode::TemporalRange, "duration months overflow")
                })?;
            }
            ('W', false) => {
                days = days
                    .checked_add(component.checked_mul(7).ok_or_else(|| {
                        Error::new(ErrorCode::TemporalRange, "duration weeks overflow")
                    })?)
                    .ok_or_else(|| {
                        Error::new(ErrorCode::TemporalRange, "duration days overflow")
                    })?;
            }
            ('D', false) => {
                days = days.checked_add(component).ok_or_else(|| {
                    Error::new(ErrorCode::TemporalRange, "duration days overflow")
                })?;
            }
            ('H', true) => {
                clock_nanos = checked_duration_clock_nanos(clock_nanos, component, 3_600)?;
            }
            ('M', true) => {
                clock_nanos = checked_duration_clock_nanos(clock_nanos, component, 60)?;
            }
            ('S', true) => {
                clock_nanos = clock_nanos.checked_add(component).ok_or_else(|| {
                    Error::new(ErrorCode::TemporalRange, "duration seconds overflow")
                })?;
            }
            _ => {
                return Err(Error::new(
                    ErrorCode::QueryType,
                    "unsupported duration component",
                ));
            }
        }
    }
    if !number.is_empty()
        || seen_components.is_empty()
        || (time && number.is_empty() && seen_components.iter().all(|(is_time, _)| !is_time))
    {
        return Err(Error::new(
            ErrorCode::QueryType,
            "duration component is missing a unit or time component",
        ));
    }
    let months = months
        .checked_mul(sign)
        .ok_or_else(|| Error::new(ErrorCode::TemporalRange, "duration months overflow"))?;
    let days = days
        .checked_mul(sign)
        .ok_or_else(|| Error::new(ErrorCode::TemporalRange, "duration days overflow"))?;
    let clock_nanos = clock_nanos
        .checked_mul(sign)
        .ok_or_else(|| Error::new(ErrorCode::TemporalRange, "duration seconds overflow"))?;
    let whole_months = months / DURATION_DECIMAL_SCALE;
    let fractional_months = months % DURATION_DECIMAL_SCALE;
    let calendar_nanos = fractional_months
        .checked_mul(DURATION_AVERAGE_SECONDS_PER_MONTH_INTEGER)
        .and_then(|value| {
            days.checked_mul(DURATION_SECONDS_PER_DAY)
                .and_then(|days| value.checked_add(days))
        })
        .ok_or_else(|| Error::new(ErrorCode::TemporalRange, "duration days overflow"))?;
    let whole_days = calendar_nanos / DURATION_NANOS_PER_DAY;
    let remaining_calendar_nanos = calendar_nanos % DURATION_NANOS_PER_DAY;
    let clock_nanos = remaining_calendar_nanos
        .checked_add(clock_nanos)
        .ok_or_else(|| Error::new(ErrorCode::TemporalRange, "duration seconds overflow"))?;
    normalized_duration_scalar(whole_months, whole_days, 0, clock_nanos)
}

fn parse_duration_decimal(value: &str) -> Result<i128> {
    let (negative, unsigned) = value
        .strip_prefix('-')
        .map(|value| (true, value))
        .or_else(|| value.strip_prefix('+').map(|value| (false, value)))
        .unwrap_or((false, value));
    let (whole, fraction) = unsigned
        .split_once('.')
        .map_or((unsigned, None), |(whole, fraction)| {
            (whole, Some(fraction))
        });
    if whole.is_empty()
        || !whole.bytes().all(|byte| byte.is_ascii_digit())
        || fraction.is_some_and(|fraction| {
            fraction.is_empty()
                || fraction.len() > 9
                || !fraction.bytes().all(|byte| byte.is_ascii_digit())
        })
    {
        return Err(Error::new(
            ErrorCode::QueryType,
            "invalid duration component",
        ));
    }
    let whole = whole.parse::<i128>().map_err(|_| {
        Error::new(
            ErrorCode::TemporalRange,
            "duration component is out of range",
        )
    })?;
    let fractional = fraction.map_or(Ok(0_i128), |fraction| {
        let padding = u32::try_from(9_usize.saturating_sub(fraction.len())).map_err(|_| {
            Error::new(
                ErrorCode::TemporalRange,
                "duration fractional component is invalid",
            )
        })?;
        let fraction = fraction.parse::<i128>().map_err(|_| {
            Error::new(
                ErrorCode::TemporalRange,
                "duration fractional component is invalid",
            )
        })?;
        fraction.checked_mul(10_i128.pow(padding)).ok_or_else(|| {
            Error::new(
                ErrorCode::TemporalRange,
                "duration fractional component is out of range",
            )
        })
    })?;
    let scaled = whole
        .checked_mul(DURATION_DECIMAL_SCALE)
        .and_then(|whole| whole.checked_add(fractional))
        .ok_or_else(|| {
            Error::new(
                ErrorCode::TemporalRange,
                "duration component is out of range",
            )
        })?;
    if negative {
        scaled.checked_neg().ok_or_else(|| {
            Error::new(
                ErrorCode::TemporalRange,
                "duration component is out of range",
            )
        })
    } else {
        Ok(scaled)
    }
}

fn checked_duration_clock_nanos(current: i128, component: i128, seconds: i128) -> Result<i128> {
    current
        .checked_add(
            component
                .checked_mul(seconds)
                .ok_or_else(|| Error::new(ErrorCode::TemporalRange, "duration seconds overflow"))?,
        )
        .ok_or_else(|| Error::new(ErrorCode::TemporalRange, "duration seconds overflow"))
}

fn evaluate_non_negative_usize(
    expression: &Expression,
    row: Option<&Row>,
    state: &ExecutionState<'_>,
    context: &ExecutionContext<'_>,
) -> Result<usize> {
    let empty = Row::new();
    let value = evaluate_state(expression, row.unwrap_or(&empty), state, context)?;
    evaluate_row_count_value(value)
}

fn evaluate_row_count_value(value: ResultValue) -> Result<usize> {
    match value {
        ResultValue::Scalar(ScalarValue::Integer(value)) if value < 0 => Err(Error::new(
            ErrorCode::QuerySyntax,
            "NegativeIntegerArgument: SKIP/LIMIT must be non-negative",
        )),
        ResultValue::Scalar(ScalarValue::Integer(value)) => usize::try_from(value).map_err(|_| {
            Error::new(
                ErrorCode::QueryType,
                "SKIP/LIMIT value exceeds the supported row-count range",
            )
        }),
        _ => Err(Error::new(
            ErrorCode::QuerySyntax,
            "InvalidArgumentType: SKIP/LIMIT requires an INTEGER",
        )),
    }
}

fn number(value: f64) -> ResultValue {
    ResultValue::Scalar(ScalarValue::Float(OrderedFloat(value)))
}
fn boolean(value: bool) -> ResultValue {
    ResultValue::Scalar(ScalarValue::Boolean(value))
}

fn is_aggregate(expression: &Expression) -> bool {
    contains_aggregate(expression)
}

fn deduplicate_rows(rows: &mut Vec<Row>, graph: &GraphReadView<'_>) -> Result<()> {
    let mut seen = BTreeSet::new();
    let mut unique = Vec::with_capacity(rows.len());
    for row in rows.drain(..) {
        let mut encoded = Vec::new();
        for (name, binding) in &row {
            encoded.extend_from_slice(&u64::try_from(name.len()).unwrap_or(u64::MAX).to_be_bytes());
            encoded.extend_from_slice(name.as_bytes());
            append_equality_value(&mut encoded, &binding_to_result(binding, graph)?);
        }
        if seen.insert(encoded) {
            unique.push(row);
        }
    }
    *rows = unique;
    Ok(())
}

fn state_id_node(graph: &GraphReadView<'_>, dense: u32) -> Result<i64> {
    let id = graph
        .node_dense(dense)
        .ok_or_else(|| Error::new(ErrorCode::QueryType, "node missing"))?
        .id()
        .0;
    i64::try_from(id)
        .map_err(|_| Error::new(ErrorCode::QueryType, "node ID exceeds Cypher INTEGER"))
}
fn state_id_edge(graph: &GraphReadView<'_>, dense: u32) -> Result<i64> {
    let id = graph
        .edge_dense(dense)
        .ok_or_else(|| Error::new(ErrorCode::QueryType, "relationship missing"))?
        .id()
        .0;
    i64::try_from(id).map_err(|_| {
        Error::new(
            ErrorCode::QueryType,
            "relationship ID exceeds Cypher INTEGER",
        )
    })
}

#[cfg(test)]
mod resident_nullable_output_tests {
    use super::*;
    use crate::execution::ResidentNullableRelationSlot;

    fn decode_with_graph(
        column: &ResidentNullableRelationOutputColumn,
        position: usize,
        graph: &GraphStore,
    ) -> Result<ResultValue> {
        resident_nullable_output_value(
            column,
            position,
            column.source_rows()[position],
            &GraphReadView::new(graph),
        )
    }

    fn decode(
        column: &ResidentNullableRelationOutputColumn,
        position: usize,
    ) -> Result<ResultValue> {
        let graph = GraphStore::default();
        decode_with_graph(column, position, &graph)
    }

    fn decoded_type(
        column: &ResidentNullableRelationOutputColumn,
        graph: &GraphStore,
    ) -> Result<ColumnType> {
        let graph = GraphReadView::new(graph);
        let values = column
            .source_rows()
            .iter()
            .copied()
            .enumerate()
            .map(|(position, dense)| {
                resident_nullable_output_value(column, position, dense, &graph)
            })
            .collect::<Result<Vec<_>>>()?;
        Ok(result_values_type(&values))
    }

    fn nullable_fixture_graph() -> Result<(GraphStore, u32, u32, RelationshipTypeId)> {
        let mut graph = GraphStore::default();
        let relationship_type = graph.catalog_mut().intern_relationship_type("LINK")?;
        let source = graph.insert_node(NodeInput {
            id: NodeId(1),
            layer: Layer::Observed,
            revision: 1,
            labels: Vec::new(),
            properties: Vec::new(),
        })?;
        graph.insert_node(NodeInput {
            id: NodeId(2),
            layer: Layer::Observed,
            revision: 2,
            labels: Vec::new(),
            properties: Vec::new(),
        })?;
        let relationship = graph.insert_edge(EdgeInput {
            id: EdgeId(3),
            source: NodeId(1),
            target: NodeId(2),
            relationship_type,
            layer: Layer::Observed,
            revision: 3,
            properties: Vec::new(),
        })?;
        Ok((graph, source, relationship, relationship_type))
    }

    #[test]
    fn nullable_scalar_outputs_decode_nulls_and_empty_strings() -> Result<()> {
        let slot = ResidentNullableRelationSlot(7);
        let integer = ResidentNullableRelationOutputColumn::IntegerProperty {
            slot,
            kind: ResidentNullableRelationBindingKind::Node,
            property: PropertyId(11),
            source_rows: vec![0, 1, 2],
            values: vec![17, 0, -3],
            validity: vec![1, 0, 1],
        };
        assert_eq!(
            decoded_type(&integer, &GraphStore::default())?,
            ColumnType::Integer
        );
        assert_eq!(
            decode(&integer, 0)?,
            ResultValue::Scalar(ScalarValue::Integer(17))
        );
        assert_eq!(decode(&integer, 1)?, ResultValue::Scalar(ScalarValue::Null));
        assert_eq!(
            decode(&integer, 2)?,
            ResultValue::Scalar(ScalarValue::Integer(-3))
        );

        let string = ResidentNullableRelationOutputColumn::StringProperty {
            slot,
            kind: ResidentNullableRelationBindingKind::Node,
            property: PropertyId(12),
            maximum_bytes: 2,
            source_rows: vec![0, 1, crate::execution::RESIDENT_NULLABLE_RELATION_NULL_ROW],
            offsets: vec![0, 0, 2, 2],
            bytes: b"ok".to_vec(),
            validity: vec![1, 1, 0],
        };
        assert_eq!(
            decoded_type(&string, &GraphStore::default())?,
            ColumnType::String
        );
        assert_eq!(
            decode(&string, 0)?,
            ResultValue::Scalar(ScalarValue::String(Arc::from("")))
        );
        assert_eq!(
            decode(&string, 1)?,
            ResultValue::Scalar(ScalarValue::String(Arc::from("ok")))
        );
        assert_eq!(decode(&string, 2)?, ResultValue::Scalar(ScalarValue::Null));

        let missing = ResidentNullableRelationOutputColumn::NullProperty {
            slot,
            kind: ResidentNullableRelationBindingKind::Node,
            source_rows: vec![0],
        };
        assert_eq!(
            decoded_type(&missing, &GraphStore::default())?,
            ColumnType::Null
        );
        assert_eq!(decode(&missing, 0)?, ResultValue::Scalar(ScalarValue::Null));
        Ok(())
    }

    #[test]
    fn nullable_scalar_decoder_rejects_corrupt_payloads() {
        let invalid_integer = ResidentNullableRelationOutputColumn::IntegerProperty {
            slot: ResidentNullableRelationSlot(0),
            kind: ResidentNullableRelationBindingKind::Relationship,
            property: PropertyId(1),
            source_rows: vec![0],
            values: vec![9],
            validity: vec![0],
        };
        let error = decode(&invalid_integer, 0).expect_err("noncanonical null must fail");
        assert_eq!(error.code, ErrorCode::CorruptStorage);

        let invalid_string = ResidentNullableRelationOutputColumn::StringProperty {
            slot: ResidentNullableRelationSlot(0),
            kind: ResidentNullableRelationBindingKind::Node,
            property: PropertyId(2),
            maximum_bytes: 1,
            source_rows: vec![0],
            offsets: vec![0, 1],
            bytes: vec![0xff],
            validity: vec![1],
        };
        let error = decode(&invalid_string, 0).expect_err("non-UTF-8 output must fail");
        assert_eq!(error.code, ErrorCode::CorruptStorage);
    }

    #[test]
    fn nullable_entity_schema_uses_decoded_values() -> Result<()> {
        let (graph, node, relationship, _) = nullable_fixture_graph()?;
        let null = crate::execution::RESIDENT_NULLABLE_RELATION_NULL_ROW;
        for (kind, dense, non_null_type) in [
            (
                ResidentNullableRelationBindingKind::Node,
                node,
                ColumnType::Node,
            ),
            (
                ResidentNullableRelationBindingKind::Relationship,
                relationship,
                ColumnType::Relationship,
            ),
        ] {
            let column = |rows| ResidentNullableRelationOutputColumn::Entity {
                slot: ResidentNullableRelationSlot(0),
                kind,
                rows,
            };
            assert_eq!(decoded_type(&column(Vec::new()), &graph)?, ColumnType::Null);
            assert_eq!(decoded_type(&column(vec![null]), &graph)?, ColumnType::Null);
            assert_eq!(
                decoded_type(&column(vec![null, dense]), &graph)?,
                non_null_type.clone()
            );
            assert_eq!(decoded_type(&column(vec![dense]), &graph)?, non_null_type);
        }
        Ok(())
    }

    #[test]
    fn nullable_scalar_schema_uses_decoded_values() -> Result<()> {
        let graph = GraphStore::default();
        let slot = ResidentNullableRelationSlot(2);
        let null = crate::execution::RESIDENT_NULLABLE_RELATION_NULL_ROW;
        let integer =
            |source_rows, values, validity| ResidentNullableRelationOutputColumn::IntegerProperty {
                slot,
                kind: ResidentNullableRelationBindingKind::Node,
                property: PropertyId(20),
                source_rows,
                values,
                validity,
            };
        assert_eq!(
            decoded_type(&integer(Vec::new(), Vec::new(), Vec::new()), &graph)?,
            ColumnType::Null
        );
        assert_eq!(
            decoded_type(&integer(vec![null], vec![0], vec![0]), &graph)?,
            ColumnType::Null
        );
        assert_eq!(
            decoded_type(&integer(vec![null, 0], vec![0, 7], vec![0, 1]), &graph)?,
            ColumnType::Integer
        );
        assert_eq!(
            decoded_type(&integer(vec![0], vec![7], vec![1]), &graph)?,
            ColumnType::Integer
        );

        let string = |source_rows, offsets, bytes, validity| {
            ResidentNullableRelationOutputColumn::StringProperty {
                slot,
                kind: ResidentNullableRelationBindingKind::Relationship,
                property: PropertyId(21),
                maximum_bytes: 2,
                source_rows,
                offsets,
                bytes,
                validity,
            }
        };
        assert_eq!(
            decoded_type(&string(Vec::new(), vec![0], Vec::new(), Vec::new()), &graph,)?,
            ColumnType::Null
        );
        assert_eq!(
            decoded_type(&string(vec![null], vec![0, 0], Vec::new(), vec![0]), &graph,)?,
            ColumnType::Null
        );
        assert_eq!(
            decoded_type(
                &string(vec![null, 0], vec![0, 0, 2], b"ok".to_vec(), vec![0, 1]),
                &graph,
            )?,
            ColumnType::String
        );
        assert_eq!(
            decoded_type(
                &string(vec![0], vec![0, 2], b"ok".to_vec(), vec![1]),
                &graph,
            )?,
            ColumnType::String
        );
        Ok(())
    }

    #[test]
    fn nullable_relationship_type_schema_uses_decoded_values() -> Result<()> {
        let (graph, _, relationship, relationship_type) = nullable_fixture_graph()?;
        let slot = ResidentNullableRelationSlot(3);
        let null = crate::execution::RESIDENT_NULLABLE_RELATION_NULL_ROW;
        let column = |source_rows, relationship_types| {
            ResidentNullableRelationOutputColumn::RelationshipType {
                slot,
                source_rows,
                relationship_types,
            }
        };
        assert_eq!(
            decoded_type(&column(Vec::new(), Vec::new()), &graph)?,
            ColumnType::Null
        );
        assert_eq!(
            decoded_type(&column(vec![null], vec![RelationshipTypeId(0)]), &graph,)?,
            ColumnType::Null
        );
        assert_eq!(
            decoded_type(
                &column(
                    vec![null, relationship],
                    vec![RelationshipTypeId(0), relationship_type],
                ),
                &graph,
            )?,
            ColumnType::String
        );
        assert_eq!(
            decoded_type(&column(vec![relationship], vec![relationship_type]), &graph,)?,
            ColumnType::String
        );
        Ok(())
    }
}

#[cfg(test)]
mod temporal_duration_cpu_tests {
    use super::*;

    fn date_value(text: &str) -> Result<ResultValue> {
        let days = parse_iso_civil_date(text)?.epoch_day()?;
        Ok(ResultValue::Scalar(ScalarValue::Date(days)))
    }

    fn local_datetime_value(text: &str) -> Result<ResultValue> {
        let (seconds, nanos) = parse_iso_local_datetime(text)?;
        Ok(ResultValue::Scalar(ScalarValue::LocalDateTime {
            seconds,
            nanos,
        }))
    }

    fn zoned_datetime_value(text: &str) -> Result<ResultValue> {
        let (seconds, nanos, timezone) = parse_iso_zoned_datetime(text)?;
        Ok(ResultValue::Scalar(ScalarValue::ZonedDateTime {
            seconds,
            nanos,
            timezone,
        }))
    }

    fn local_time_value(text: &str) -> Result<ResultValue> {
        Ok(ResultValue::Scalar(ScalarValue::LocalTime(
            local_time_nanos(parse_local_time(text)?)?,
        )))
    }

    fn expected_duration(months: i64, days: i64, seconds: i64, nanos: i32) -> ResultValue {
        ResultValue::Scalar(ScalarValue::Duration {
            months,
            days,
            seconds,
            nanos,
        })
    }

    #[test]
    fn temporal_duration_units_use_complete_calendar_and_elapsed_time() -> Result<()> {
        let start = date_value("1984-10-11")?;
        let end = date_value("2015-06-24")?;
        assert_eq!(
            temporal_duration_function("duration.between", &[start.clone(), end.clone()])?,
            expected_duration(368, 13, 0, 0)
        );
        assert_eq!(
            temporal_duration_function("duration.inmonths", &[start.clone(), end.clone()])?,
            expected_duration(368, 0, 0, 0)
        );
        assert_eq!(
            temporal_duration_function("duration.indays", &[start.clone(), end.clone()])?,
            expected_duration(0, 11_213, 0, 0)
        );
        assert_eq!(
            temporal_duration_function("duration.inseconds", &[start, end])?,
            expected_duration(0, 0, 968_803_200, 0)
        );
        Ok(())
    }

    #[test]
    fn temporal_duration_boundaries_and_subseconds_are_canonical() -> Result<()> {
        let forward = temporal_duration_function(
            "duration.between",
            &[
                local_datetime_value("2018-01-01T10:00:00.2")?,
                local_datetime_value("2018-01-02T10:00:00.1")?,
            ],
        )?;
        let reverse = temporal_duration_function(
            "duration.between",
            &[
                local_datetime_value("2018-01-02T10:00:00.1")?,
                local_datetime_value("2018-01-01T10:00:00.2")?,
            ],
        )?;
        let negative_fraction = temporal_duration_function(
            "duration.inseconds",
            &[
                local_time_value("12:34:54.7")?,
                local_time_value("12:34:54.3")?,
            ],
        )?;
        assert_eq!(forward, expected_duration(0, 0, 86_399, 900_000_000));
        assert_eq!(reverse, expected_duration(0, 0, -86_400, 100_000_000));
        assert_eq!(negative_fraction, expected_duration(0, 0, -1, 600_000_000));
        Ok(())
    }

    #[test]
    fn temporal_duration_named_zones_follow_elapsed_dst_time() -> Result<()> {
        let bracketed = temporal_duration_function(
            "duration.between",
            &[
                zoned_datetime_value("2017-10-28T23:00+02:00[Europe/Stockholm]")?,
                zoned_datetime_value("2017-10-29T04:00+01:00[Europe/Stockholm]")?,
            ],
        )?;
        let start = temporal_constructor_from_map(
            "datetime",
            &BTreeMap::from([
                (
                    "year".to_owned(),
                    ResultValue::Scalar(ScalarValue::Integer(2017)),
                ),
                (
                    "month".to_owned(),
                    ResultValue::Scalar(ScalarValue::Integer(10)),
                ),
                (
                    "day".to_owned(),
                    ResultValue::Scalar(ScalarValue::Integer(29)),
                ),
                (
                    "timezone".to_owned(),
                    ResultValue::Scalar(ScalarValue::String(Arc::from("Europe/Stockholm"))),
                ),
            ]),
        )?;
        let end = local_datetime_value("2017-10-29T04:00")?;
        let mixed = temporal_duration_function("duration.inseconds", &[start, end])?;
        assert_eq!(bracketed, expected_duration(0, 0, 21_600, 0));
        assert_eq!(mixed, expected_duration(0, 0, 18_000, 0));
        Ok(())
    }

    #[test]
    fn temporal_duration_wide_local_datetimes_and_nulls_are_supported() -> Result<()> {
        let wide = temporal_duration_function(
            "duration.inseconds",
            &[
                local_datetime_value("-999999999-01-01")?,
                local_datetime_value("+999999999-12-31T23:59:59")?,
            ],
        )?;
        assert_eq!(wide, expected_duration(0, 0, 63_113_903_968_377_599, 0));
        let null = ResultValue::Scalar(ScalarValue::Null);
        assert_eq!(
            temporal_duration_function(
                "duration.inmonths",
                &[null.clone(), date_value("2015-06-24")?],
            )?,
            null
        );
        Ok(())
    }
}
